P.entries["item:filled-soul-gem"] = {n="Filled Soul Gem",s="Nimboya ber dig ta Soul Gem till Grom'gol, där hans folk väntar på att Yenniku ska återvända.",h="Nimboya ber dig ta Soul Gem till Grom'gol, där hans folk väntar på att Yenniku ska återvända.",kw={"filled soul gem","grom'gol","kin'weelay","mind's eye","nimboya","soul gem","yenniku","zanzil"},sec={{t="En själ återställd",b="Vid Ruins of Aboraz på The Cape of Stranglethorn placeras Soul Gem på Yennikus huvud för att fånga hans själ. Ta den fyllda ädelstenen till Nimboya i Grom'gol, där hans folk väntar på att Yenniku ska återvända."}},faq={{q="Vad är Filled Soul Gem?",a="Filled Soul Gem innehåller Yennikus själ, fångad med Soul Gem vid Ruins of Aboraz.",al={"fylld ädelsten","soul gem med yenniku","vad finns i ädelstenen"}},{q="Vem är Yenniku?",a="Yenniku tillhör Nimboyas stam och hålls under Zanzil the Outcasts vilja.",al={"yennikus berättelse","vem är yenniku","yenniku"}},{q="Vart ska jag ta ädelstenen?",a="Ta Filled Soul Gem till Nimboya i Grom'gol.",al={"vart ska ädelstenen","ta ädelstenen vart","nimboya ädelsten"}},{q="Hur skapades Soul Gem?",a="Kin'weelay omformade Mind's Eye till en Soul Gem som fångar Yennikus själ.",al={"mind's eye ädelsten","hur fylla soul gem","soul gem recept"}}},fp="15,92,15.196.0,28.95.1,15.83.0,24.49.0,26.82.1"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Filled Tainted Ooze Jar",s="En Filled Tainted Ooze Jar innehåller trögflytande, förgiftat slem som skopats direkt från resterna av slemvarelser som strövar omkring i Felwoods fördärvade skogar. Proverna förvaras i särskilda behållare och förs till Ironforge för att stödja radikala teorier om livets ursprung på Azeroth.",h="En Filled Tainted Ooze Jar innehåller trögflytande, förgiftat slem som skopats direkt från resterna av...",kw={"explorers' league","felwood","ironforge","laris geardawdle","royal apothecary society","slem","förgiftat slem"},ang={["faction:Alliance"]="Alliansens spejare håller noga uppsikt över Forsaken's Royal Apothecary Society. Att förstå varför Undercity samlar in slem över hela kontinenterna är en viktig underrättelseprioritet.",["race:Gnome"]="För de gnomiska flyktingarna som bor i Ironforge är banbrytande vetenskapliga bidrag till Explorers' League avgörande för att bevisa sitt värde och återgälda dvärgarnas gästfrihet efter Gnomeregans tragedi."},sec={{t="Slem från den fördärvade skogen",b="De förgiftade slemvarelserna som strövar omkring i norra Kalimdor bär på Felwoods djupa, kvardröjande fördärv. Att samla in dem kräver försiktig förvaring i burkar från gnomiska forskare. De flesta resenärer undviker de giftiga varelserna helt, men proverna ger ovanligt material för naturfilosofi och biologiska studier långt från de härjade skogarna."},{t="Geardawddles storslagna teori",b="Proverna samlas in på uppdrag av Laris Geardawdle, en ambitiös gnomisk forskare som tjänstgör hos Explorers' League i Ironforge. Geardawdle fascineras av hur vanligt förekommande slemvarelser är och har lagt märke till att Forsaken's Royal Apothecary Society också intresserar sig aktivt för dem. Trots akademikernas vanliga skepsis teoretiserar han att slemvarelser kan vara uråldriga utsöndringar med koppling till själva skapelsen av Azeroth. Att säkra proverna är hans försök att vinna anseende bland dvärgiska forskare efter Gnomeregans tragiska fall."}},faq={{q="Vad finns i en Filled Tainted Ooze Jar?",a="Den innehåller ett färskt prov från resterna av en besegrad Tainted Ooze från Felwood, förseglat i en gnomisk insamlingsburk.",al={"vad finns i burken","innehåll i burk med förgiftat slem","vad är förgiftat slem"}},{q="Vem vill ha slemproverna?",a="Laris Geardawdle, en gnomisk forskare som arbetar med Explorers' League i Hall of Explorers i Ironforge, ber om dem för att utveckla sina studier av naturhistoria.",al={"vem tar slemmet","laris geardawdle-uppdrag","vem vill ha förgiftat slem"}},{q="Varför studerar Laris Geardawdle slemvarelser?",a="Geardawdle såg hur Royal Apothecary Society samlade in slemprover och blev fast besluten att först förstå deras natur. Han hyser en okonventionell teori om att slemvarelser är uråldriga utsöndringar med koppling till skapelsen av Azeroth, och hoppas kunna befästa sitt vetenskapliga anseende i Ironforge.",al={"varför studera slem","geardawddles slemteori","varför vill gnomen ha slem"}},{q="Var samlas proverna in?",a="De samlas in i Felwood genom att besegra Tainted Oozes och använda en tom behållarburk på deras kvarlevor.",al={"var hittar man förgiftat slem","plats för burk med förgiftat slem","var fyller jag burken"}}},fx={["297c9c04"]={q="Varifrån kommer en Filled Tainted Ooze Jar, och vem har tillverkat den?",a="Själva burken kommer från gnomforskaren Laris Geardawdle i Ironforge, som tillverkar särskilda tomma glasbehållare för att säkert samla flyktiga prover. Den fylls först när en äventyrare dödar en förorenad slemvarelse i Felwoods förvridna skogar och använder burken för att skrapa upp rester av varelsens geléaktiga kropp.",al={"tainted ooze jar ursprung","vem tillverkade tainted ooze jar","varifrån kommer tainted ooze jars"}}},fp="23,137,27.291.0,25.431.0,41.136.0,29.148.0,39.233.0,34.115.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Filled Tourmaline Phial",s="Den fyllda Filled Tourmaline Phial innehåller förtrollat vatten hämtat från månsjön intill Pools of Arlithrien i södra Teldrassil. Vattnet samlades in på begäran av Corithras Moonrage och ingår i arbetet med att övervaka världsträdets hälsa och balans medan det växer.",h="Den fyllda Filled Tourmaline Phial innehåller förtrollat vatten hämtat från månsjön intill Pools of...",kw={"corithras moonrage","crown of the earth","filled tourmaline phial","gnarlpine","månsjö","pools of arlithrien","teldrassil","tourmaline phial"},ang={["class:Druid"]="För druider berör det kontroversiella arvet efter ärkedruiden Fandral Staghelm direkt att bära phialen. Han drev på för att plantera Teldrassil under Shan'do Stormrages oförklarliga frånvaro.",["race:NightElf"]="Månsjöarnas vatten är en livsviktig andlig livlina för kaldorei, vilket gör korruptionen i de omgivande Gnarlpine-lundarna till ett djupt oroande omen för deras nya hem."},sec={{t="Arlithriens vatten",b="Tourmaline Phial har utformats särskilt för att hämta vatten från månsjön sydost om vägen till Darnassus, vid Pools of Arlithriens stränder. Det har blivit farligt att hämta vatten från denna helgedom på grund av de plötsligt aggressiva Gnarlpine furbolgs, fridfulla grannar som snabbt har förfallit till våldsamt vansinne. Corithras Moonrage ger resenärer i uppdrag att trotsa de fientliga lundarna för att säkra vattnet och försöka diagnostisera den tilltagande korruption som skakar landet."},{t="Teldrassils rötter",b="När phialen återförs till Dolanaar börjar Corithras Moonrage fundera över hur grenverket ovanför kom till. Efter Shan'do Malfurion Stormrages försvinnande samlade ärkedruiden Fandral Staghelm de äldstes cirkel på andra sidan havet i Darkshore för att plantera Teldrassil i hopp om att återfå deras förlorade odödlighet. Vattnet i den ädelstensprydda phialen speglar tillståndet hos detta heliga experiment – en ambition som nu har fläckats av en oförklarlig sjukdom som sprider sig bland både bestar och furbolgs."}},faq={{q="Vad används Filled Tourmaline Phial till?",a="Det är en förtrollad behållare med månsjövatten som Corithras Moonrage har begärt i Dolanaar. Han samlar vatten från månsjöar över hela Teldrassil för att studera hur korruptionen sprider sig och förklara världsträdets historia för nyanlända försvarare.",al={"användning av fylld tourmaline phial","tourmaline phials syfte","varför fylla phialen"}},{q="Var ligger månsjön för Tourmaline Phial?",a="Månsjön ligger sydost om Darnassus huvudport, längs stränderna vid Pools of Arlithrien i sydvästra Teldrassil. Området är hårt omstritt av rasande Gnarlpine furbolgs.",al={"var fyller jag tourmaline phial","månsjön vid pools of arlithrien","arlithriens källa plats"}},{q="Varför anfaller furbolgarna nära månsjön?",a="Gnarlpine furbolgs, som en gång var fredliga björnfolk och levde sida vid sida med nattalverna, har fallit offer för en krypande korruption som drabbar Teldrassil. Deras plötsliga förfall till vettlöst våld är ett av flera symptom som plågar det unga världsträdet.",al={"varför är gnarlpine galna","furbolgers fientlighet vid arlithrien","vansinniga gnarlpine"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en nattalvsk lärd och väktare stationerad i Dolanaar. Han vägleder unga äventyrare genom riten som kallas Crown of the Earth och lär dem om nattalvernas historia, planteringen av Teldrassil och Malfurion Stormrages försvinnande.",al={"corithras roll","corithras i dolanaar"}}},fx={["360c6167"]={q="Vad är Filled Tourmaline Phial?",a="Det är en tom turmalinflaska fylld med det heliga, självlysande vattnet från månkällan nära Pools of Arlithrien i Teldrassil. Nattalvdruider använder flaskor av olika mineraler för att hämta rent månkällvatten över hela ön. På så vis hålls varje prov åtskilt för deras heliga riter och för att rena landet.",al={"vad är filled tourmaline phial","föremålet filled tourmaline phial"}},b07aae52={q="Varifrån kommer Filled Tourmaline Phial?",a="Själva kärlet får du av Corithras Moonrage i Dolanaar. Du fyller flaskan genom att ta den sydöst om Darnassus till månkällan vid stranden av Pools of Arlithrien och hämta vatten direkt ur källan, mitt bland de strövande, uppretade Gnarlpine-furbolgerna.",al={"filled tourmaline phial ursprung","varifrån kommer filled tourmaline phial"}},c83d83e7={q="Varför vill Corithras Moonrage ha Filled Tourmaline Phial?",a="Corithras Moonrage samlar vatten från Teldrassils olika månkällor för att bedöma och bevara det unga Världsträdets andliga livskraft. När fördärvet kryper in bland grenarna och driver de inhemska Gnarlpine-furbolgerna till vansinne hjälper det druiderna att bevara den heliga balansen och förstå vad som hemsöker deras hem, om de samlar in och undersöker vatten från olika delar av trädet.",al={"varför vill corithras ha flaskan","syftet med filled tourmaline phial","varför samla månkällvatten"}}},fp="23,170,20.383.0,23.411.1,45.258.0,55.170.0,49.195.0,26.256.0"}
P.entries["item:filled-vessel"] = {n="Filled Vessel",s="Filled Vessel innehåller renat vatten från de olika heliga månbrunnarna på Teldrassil. Corithras Moonrage i Dolanaar anförtrodde den åt kurirer, som levererar den till Arch Druid Fandral Staghelm i Darnassus för att hjälpa honom studera världsträdets åkommor.",h="Filled Vessel innehåller renat vatten från de olika heliga månbrunnarna på Teldrassil.",kw={"cenarion enclave","corithras moonrage","crown of the earth","darnassus","fandral staghelm","filled vessel","månbrunnsvatten","teldrassil"},ang={["class:Druid"]="För Cenarion-adepter är leveransen av kärlet deras första officiella ärende åt Arch Druid Fandral Staghelm. Den visar på nära håll hur ekologiskt sårbart Teldrassil är.",["race:NightElf"]="Månbrunnsvattnet står för kaldoreiernas nya hems heliga livsnerver. Där blandas Elunes magi med det obundna världsträdets osäkra tillväxt."},sec={{t="En samling heliga vatten",b="Teldrassil planterades utan välsignelser från de stora aspekterna Alexstrasza och Nozdormu, vilket lämnade dess väldiga grenar sårbara för oväntad korruption, märkliga bestar och vansinniga furbolgstammar. För att övervaka och rena de växande grenarna skickas nattalvsakoliter ut för att samla vattenprover från månbrunnar runt om bland grenarna. Corithras Moonrage samlar de insamlade flaskorna i en enda Filled Vessel och skickar den vidare till huvudstaden. Blandningen är ett viktigt prov på Teldrassils livskraft för Arch Druid Fandral Staghelm, som arbetar outtröttligt i Cenarion Enclave för att finna ett botemedel mot det stora trädets utbredda brister."}},faq={{q="Vad finns i Filled Vessel?",a="Kärlet innehåller vatten från flera månbrunnar utspridda över Teldrassil, samlat i ett enda kärl av Corithras Moonrage i Dolanaar.",al={"kärlets innehåll","vilket vatten är det här","vad finns i kärlet"}},{q="Vem behöver Filled Vessel?",a="Filled Vessel förs till Arch Druid Fandral Staghelm, som håller till högst upp i Cenarion Enclave i Darnassus.",al={"vem ska jag lämna filled vessel till","vart ska kärlet","lämna in filled vessel"}},{q="Varför behöver Fandral Staghelm vattenproverna?",a="Teldrassil saknar de traditionella drakaspekternas välsignelser, vilket gör att märklig korruption, aggressiva vilddjur och galna furbolger plågar dess grenar. Staghelm studerar det blandade vattnet för att diagnostisera trädets brister och finna ett botemedel mot dess plågor.",al={"varför staghelm vill ha vatten","syftet med staghelms månbrunnsvatten","varför samla månbrunnsvatten"}},{q="Vem förberedde kärlet?",a="Corithras Moonrage, en nattalv stationerad i Dolanaar, häller flaskorna som unga äventyrare samlat in i kärlet innan han skickar det till Darnassus.",al={"vem gjorde filled vessel","vem lämnar filled vessel","corithras filled vessel"}}},fp="13,194,29.537.0,33.132.0,28.103.0,51.239.0,24.136.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="Längs Westfalls kust pekar Captain Sanders sista anvisningar ut mot havet. En lapp i en gammal kruka leder skattletare västerut mot hans begravda skatt.",h="Längs Westfalls kust pekar Captain Sanders sista anvisningar ut mot havet.",kw={"captain sanders","kista","ledtråd","pirat","skatt","westfall","whiskeykruka"},ang={["class:Rogue"]="Som rogue kan du följa Captain Sanders anvisningar ut till havs och leta efter skatter längs Westfalls stränder, bortom Defias fickor."},sec={{t="En sjömans sista ord",b="Captain Sanders lämnade sina sista anvisningar i en gammal whiskeykruka vid Westfalls kust. Piraten hade spritt kryptiska lappar längs strandlinjen, och den här fullbordar spåret. Från krukan leder anvisningarna rakt västerut över havet. Följ dem genom bränningarna till en enslig klippa ute till havs, där hans järnbeslagna sjökista ligger."}},faq={{q="Vad står det på den sista ledtråden?",a="Lappen visar västerut från whiskeykrukan och ut till havs, där en liten ö rymmer skattkistan.",al={"ledtrådstext","vad står det på ledtråden","sanders anvisningar"}},{q="Var hittades den här ledtråden?",a="Ledtråden låg i en gammal whiskeykruka vid Westfalls kust. Den var det tredje steget i Captain Sanders ledtrådsspår.",al={"var hittar jag sista ledtråden","gammal krukas plats","ledtrådens plats"}},{q="Vem var Captain Sanders?",a="Captain Sanders var en pirat vars tillhörigheter och skattkartor spolades upp längs Westfalls kust. Före sin död lämnade han gömda lappar och markörer över landsbygden som leder till hans skattgömma.",al={"vem är captain sanders","sanders piratberättelse","vem gömde skatten"}},{q="Vart leder den här ledtråden till slut?",a="Lappen leder dig västerut från Westfalls kust till en enslig ö, där Captain Sanders sjökista står.",al={"var finns kistan","sanders ö","öns plats"}}},fx={ed69490f={q="Vad är Final Clue to Sanders' Treasure?",a="Det är en väderbiten papperslapp som plockats upp ur kapten Sanders gamla whiskyflaska längs Westfalls kust. Anteckningen luktar svagt av sprit och bläcket har runnit av fukten. Den utgör kulmen på en skattjakt som den avlidne piratkaptenen ordnade och ger de sista anvisningarna för att hitta hans nedgrävda skatt.",al={"vad är final clue to sanders treasure","vad är den sista ledtråden","vad är det här för ledtråd"}},["0f7c35ef"]={q="Varifrån kommer Final Clue to Sanders' Treasure, och vem har skrivit den?",a="Ledtråden skrevs av kapten Sanders själv och förseglades i en gammal flaska intill den ensamma väderkvarnen på Westfalls havsklippor. Piratkaptenen gömde den som det sista steget i en invecklad led längs kusten, så att bara den som var tillräckligt ihärdig för att följa hans utspridda markörer skulle hitta hans gömda byte.",al={"vem skrev final clue","varifrån kommer final clue","final clue ursprung"}},["9095866c"]={q="Varför vill någon ha Final Clue to Sanders' Treasure?",a="Den som följer Captain Sanders spår söker hans sedan länge försvunna piratskatt. Tidigare ledtrådar förde från ett landmärke vid kusten till ett annat, men den här sista lappen visar uttryckligen att man ska bortom Westfalls stränder och ut på öppet hav, rakt mot den ensliga ön där kaptenens kista väntar.",al={"varför vill någon ha sista ledtråden","varför hitta sista ledtråden","sista ledtrådens syfte"}}},fp="31,150,24.332.0,29.113.0,26.121.0,24.197.0,37.107.0"}
P.entries["item:final-message-to-the-wildhammer"] = {n="Final Message to the Wildhammer",s="Final Message to the Wildhammer är ett spjut som Otho Moji'ko skickar från Revantusk Village till Aerie Peak. Den makabra uppvisningen ska visa Wildhammer-dvärgarna att trollen menar allvar.",h="Final Message to the Wildhammer är ett spjut som Otho Moji'ko skickar från Revantusk Village till Aerie Peak.",kw={"aerie peak","slutbudskap","gripfjädrar","otho moji'ko","revantusk village","spjut","brunn","wildhammer"},ang={["faction:Alliance"]="För Alliance är spjutet ett direkt hot, planterat i hjärtat av Aerie Peak bland Wildhammer-dvärgarna.",["race:Troll"]="Som troll bär du Otho Moji'kos hot in i Aerie Peak, där han hoppas att Wildhammer-dvärgarna ska få se Revantusks styrka."},sec={{t="Ett spjut till Aerie Peak",b="I Revantusk Village i Hinterlands ger Otho Moji'ko dig ett bloddränkt spjut insvept i gripfjädrar. Han vill att du planterar det vid brunnen mitt i Aerie Peak, där Wildhammer-dvärgarna får se det. Budskapet är tydligt, och Otho hoppas att du återvänder med livet i behåll."}},faq={{q="Vad är Final Message to the Wildhammer?",a="Det är ett bloddränkt spjut insvept i gripfjädrar, som Otho Moji'ko skickar till Aerie Peak.",al={"slutbudskap","wildhammer-spjut","othos budskap"}},{q="Vem ger dig spjutet?",a="Otho Moji'ko ger dig spjutet i Revantusk Village i Hinterlands.",al={"vem är otho","vem lämnar över det","troll som ger spjut"}},{q="Vart ska spjutet?",a="Otho vill att du planterar det vid brunnen mitt i Aerie Peak.",al={"var ska det planteras","aerie peaks brunn","var är budskapet"}},{q="Varför skicka ett blodigt spjut?",a="Otho vill att Wildhammer-dvärgarna ska se att trollen menar allvar.",al={"varför spjutet","vad betyder det","trollen menar allvar"}},{q="Vad händer när du placerar det?",a="Falstad Wildhammer ropar när du placerar spjutet, och du blir markerad för PvP.",al={"falstad ropar","placera budskapet","wildhammers reaktion"}}},fp="31,193,22.278.0,44.93.0,24.73.0,24.67.0,24.71.0,31.78.0"}
P.entries["item:fine-crab-chunks"] = {n="Fine Crab Chunks",s="Fine Crab Chunks är de finaste köttbitarna från kustlevande kräftdjur som strövar längs Darkshores stränder. De är mycket uppskattade för sin mångsidighet i matlagningen och eftertraktade av lokalbefolkningen längs kusten och hungriga fiskare som vill laga en mängd olika skaldjursrätter.",h="Fine Crab Chunks är de finaste köttbitarna från kustlevande kräftdjur som strövar längs Darkshores stränder.",kw={"auberdine","krabba","darkshore","encrusted tide crawler","fine crab chunks","havets frukter","gubber blump","reef crawler"},ang={["faction:Alliance"]="Att förse invånarna vid bryggorna i Auberdine med mat hjälper till att hålla Alliansens utsatta utpost vid liv bland Darkshores dystra faror.",["profession:Cooking"]="Alla blivande kockar vid kusten kommer att uppskatta Gubber Blumps encyklopediska passion för krabba, från soppor, sallader och pepparkryddningar till regionala delikatesser som Ironforge surprise crab."},sec={{t="Havets frukter",b="Darkshores dimmiga, karga stränder kryllar av småkrypande kräftdjur, särskilt Reef Crawlers och Encrusted Tide Crawlers. Många resenärer ser de bepansrade strandströvarna som skadedjur eller faror längs vattenlinjen, men driftiga finsmakare anser att köttet hör till kustens främsta läckerheter. De utvalda bitarna från dessa varelser är saftiga och möra och passar till nästan alla tänkbara tillagningssätt, från kokning och grillning till fritering och mustiga grytor."}},faq={{q="Vilka varelser ger Fine Crab Chunks?",a="De samlas in från Reef Crawlers och Encrusted Tide Crawlers som strövar längs Darkshores klippiga stränder och tidvattengrunda vatten.",al={"var får man fine crab chunks","vilka krabbor ger köttbitar","källa till krabbkött"}},{q="Vem vill ha Fine Crab Chunks i Darkshore?",a="Gubber Blump, en entusiastisk fiskare som håller till vid bryggorna i Auberdine, letar efter dessa utvalda köttbitar. Han älskar skaldjur och uppskattar dem för sitt stora utbud av hemlagade krabbrätter.",al={"vem behöver fine crab chunks","vem tar emot krabbkött","gubber blump krabba"}},{q="Kan du laga riktiga måltider av dem?",a="De här särskilda råa köttbitarna samlas främst in åt Gubber Blump och används inte som ingrediens i något särskilt recept. Den lokala matlagningstraditionen ser dock krabbkött som mycket mångsidigt: det passar att baka, grilla, koka, steka, fritera och blanda i sallader eller grytor.",al={"kan man tillaga fine crab chunks","vad kan man laga med fine crab chunks","krabbrecept"}}},fx={a1097ca6={q="Vad är Fine Crab Chunks?",a="Fine Crab Chunks är de bästa köttbitarna från de kraftiga krabborna längs Darkshores dimhöljda kust. De uppskattas för sin mörhet och mångsidighet, och lokala finsmakare ser dem som havets verkliga gåva, lämplig för nästan vilken tillagning som helst.",al={"vad är fina krabbköttbitar","fina krabbköttbitar i berättelsen","vad är fint krabbkött"}},["09afcf23"]={q="Var kommer Fine Crab Chunks ifrån?",a="De här läckerbitarna tas direkt från de vilda skaldjur som strövar längs Darkshores kust, särskilt Reef Crawlers och Encrusted Tide Crawlers. De tillverkas inte av dödliga händer, utan styckas färska från varelserna som trivs i det kalla bränningarna.",al={"var kommer fina krabbköttbitar ifrån","fina krabbköttbitars ursprung"}},["1943045a"]={q="Varför vill Gubber Blump ha Fine Crab Chunks?",a="Gubber Blump, en excentrisk fiskare vid kajen i Auberdine, är fullständigt besatt av krabbkött. Han är strandsatt med sitt fiskespö och förlitar sig på resenärer som samlar färska bitar, så att han kan laga en oändlig mängd krabbrätter, från bakade och grillade rätter till krabbsallader och grytor.",al={"varför vill gubber ha krabbköttbitar","vem vill ha fina krabbköttbitar","varför samla fina krabbköttbitar"}}},fp="16,131,16.217.0,38.116.0,40.91.0,40.174.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Fine Moonstalker Pelt",s="En Fine Moonstalker Pelt är det tjocka, orörda skinnet från de mest fullvuxna rovgiriga moonstalkers som strövar omkring i södra Darkshore. Terenthis i Auberdine använder dessa dyrbara pälsar för att väva en förtrollad mantel som låter sökare obemärkt ta sig förbi skogens fientliga bestar.",h="En Fine Moonstalker Pelt är det tjocka, orörda skinnet från de mest fullvuxna rovgiriga moonstalkers som...",kw={"auberdine","darkshore","fine moonstalker pelt","hona","moonstalker","hane","terenthis","volcor","wildbend river"},ang={["class:Hunter"]="Att spåra hanarna och honorna nära Wildbend River sätter en jägares spårningsförmåga på prov mot några av de grymmaste rovdjuren i Kalimdors kustområden.",["race:NightElf"]="Night elves vördar moonstalkers heliga vildhet och tar bara deras skinn när nöden är stor, för att hjälpa fallna fränder som Volcor."},sec={{t="Flådda flockledare",b="Vanliga moonstalkers strövar genom Darkshores dimhöljda skogar, men bara äldre moonstalker-hanar och moonstalker-honor har tillräckligt täta och friska pälsar för att ge ett fint skinn. Dessa mäktiga vildkatter hävdar revir längs Wildbend River och längre söderut mot Ashenvales gränser, där de jagar med dödligt tålamod."},{t="En mantel av förklädnad",b="Att samla in dessa skinn är ingen troféjakt. Terenthis ber om fem hela skinn för att skapa ett förtrollat plagg åt resande som söker efter den försvunne Night Elf Volcor. När skinnen vävs samman och binds med naturmagi bildar de en kamouflagekappa som omsluter bäraren i en illusion och dämpar dennes närvaro för Darkshores vilda djur, så länge bäraren avstår från aggressiva handlingar."}},faq={{q="Vilka varelser ger Fine Moonstalker Pelt?",a="Bara de fullvuxna ledarna för moonstalker-flockarna ger dessa skinn, närmare bestämt moonstalker-hanar och moonstalker-honor. Yngre eller vanliga moonstalkers har inte skinn av tillräcklig kvalitet.",al={"vad ger fine moonstalker pelt","var får man moonstalker-skinn","vilka katter har skinn"}},{q="Var finns de fullvuxna moonstalkers?",a="Dessa väldiga vildkatter håller till i södra Darkshore, särskilt nära Wildbend Rivers stränder och längre söderut längs skogsvägen mot Ashenvale.",al={"var finns hanarna och honorna","moonstalker-hane plats","moonstalker-hona plats"}},{q="Varför behöver Terenthis skinnen?",a="Terenthis använder fem av skinnen för att skapa en förtrollad mantel. Manteln är laddad med magi som ska dölja en räddare för rovdjur under sökandet efter den försvunne Night Elf Volcor.",al={"vad används skinnen till","varför samla moonstalker-skinn","terenthis skinnuppdrag"}},{q="Gör den färdiga manteln dig helt osynlig?",a="Manteln skapar en skör naturlig illusion som håller bestar på avstånd. Terenthis varnar för att allt utöver att tala med andra kommer att störa förtrollningen och skingra förklädnaden.",al={"hur fungerar manteln","mantelns illusionsbegränsningar","vad bryter mantelns smygande"}}},fx={["399f6830"]={q="Vad är en Fine Moonstalker Pelt?",a="En Fine Moonstalker Pelt är det bästa skinnet från de fullvuxna moonstalkerhanar och -honor som strövar omkring i Darkshores vildmarker. Dessa mäktiga nattsaberkatter har tjock, smidig päls som kan hålla kvar svaga naturförhäxningar, vilket gör deras skinn betydligt mer värdefulla och slitstarka än yngre djurs sträva päls.",al={"fine moonstalker pelt","vad är moonstalker-päls","fin päls"}},e53e751f={q="Var kommer en Fine Moonstalker Pelt ifrån?",a="Skinnen kommer från de största fullvuxna moonstalkers som jagar längs Darkshores kuster och i skogarna, särskilt nära Wildbend River och längre söderut mot gränsen till Ashenvale. Endast fullvuxna moonstalkerhanar och -honor ger skinn som är tjocka och friska nog att räknas som fina pälsar.",al={"var hittar man fin moonstalker-päls","moonstalker-pälsens ursprung","vem släpper fin moonstalker-päls"}}},fp="21,164,25.300.0,20.277.1,45.128.0,43.119.0,36.164.0,54.174.0"}
P.entries["item:fire-tar"] = {n="Fire Tar",s="I östra delen av The Barrens bär Razormane-spellcasters på Fire Tar. Hordens shamaner använder det för att brygga Fire Sapta, som låter dem kommunicera med eldsandar.",h="I östra delen av The Barrens bär Razormane-spellcasters på Fire Tar.",kw={"call of fire","fire sapta","fire tar","quilboar","razormane","schamanens totem","telf joolam","the barrens"},ang={["class:Shaman"]="Som shaman är det en viktig övergångsrit att samla Fire Tar. Du söker elementär resonans i den vida världen och använder den sedan för att brygga Fire Sapta och förtjäna din Fire Totem.",["faction:Horde"]="Som medlem av Horden korsar du Southfury River från Durotar in i The Barrens för att samla Fire Tar. Där ställs du mot de aggressiva Razormane-stammarna."},sec={{t="En brygd från Razormane",b="Razormane-geomancers, mystics och thornweavers bär på Fire Tar. Quilboar använder det flammbundna ämnet i sin hårda magi och sina ritualer. Shamaninstruktörer värdesätter det som en världslig reagent som hjälper dödligas sinnen att nå elementens råa vrede."},{t="Vägen till Fire Totem",b="Unga orc- och trollshamaner reser till Telf Joolam, högt uppe bland Durotars klippor, för att smida sina Fire Totems. Telf ber dem om en Reagent Pouch som tagits från Burning Blade-kultister och Fire Tar som samlats in från Razormane. Han brygger de två ingredienserna till en Fire Sapta. När en shaman dricker den kan hen uppfatta eldsandarna som väntar på de närliggande topparna."}},faq={{q="Vad används Fire Tar till?",a="Shamaner tar med sig Fire Tar till Telf Joolam i Durotar, där han brygger det med reagents från Burning Blade till en Fire Sapta. Brygden låter en shaman se och kommunicera med eldsandar för att förtjäna en Fire Totem.",al={"användning av fire tar","vad gör fire tar","varför behöver jag fire tar"}},{q="Vem bär på Fire Tar?",a="Razormane-quilboar som kan besvärjelser bär på Fire Tar i östra delen av The Barrens. Bland dem finns Razormane Geomancers, Mystics, Thornweavers och Water Seekers.",al={"vem släpper fire tar","fiender med fire tar","var hittar man fire tar"}},{q="Varför behöver schamaner ingredienser från fientliga magiker?",a="Saptas behöver fysiska beståndsdelar som mättats med motsvarande element. Razormane-besvärjare och Burning Blade-warlocks kanaliserar hetta och förödande lågor, så deras vardagliga material bär på den eldiga essens som behövs för att väcka en shamans elementseende.",al={"varför quilboars tjära","varför warlocks och quilboars"}},{q="Var brygger Telf Joolam Fire Sapta?",a="Telf Joolam brygger Fire Sapta på en hög klippa med utsikt över Durotars klippor, nära stigen mellan Razor Hill och The Barrens. Han lär invigda att balansera lågornas destruktiva och skapande natur.",al={"var finns telf joolam","lämna in fire tar"}}},fx={["1e4fc5f4"]={q="Vad är Fire Tar?",a="Fire Tar är ett flyktigt, elementärt ämne som bärs av besvärjare bland Razormane quilboar i Barrens. Denna stickande beck är genomsyrad av eldens grundläggande väsen och uppskattas av utövare av elementmagi för sin naturliga samhörighet med lågor.",al={"vad är fire tar","information om fire tar","beskriv fire tar"}},["006bd002"]={q="Var kommer Fire Tar ifrån, och vem tillverkar det?",a="Fire Tar samlas in från Razormane quilboar-besvärjarna som bor i östra Barrens, däribland deras geomancers, mystics och thornweavers. Telf Joolam ber noviser att ta med det som en ingrediens till hans Fire Sapta.",al={"vem tillverkar fire tar","fire tars ursprung","var kommer fire tar ifrån"}}},fp="8,178,29.274.0,26.361.0,26.196.0,21.147.0,61.243.0,43.215.0"}
P.entries["item:firebeard-s-head"] = {n="Firebeard's Head",s="Firebeard’s Head är beviset som krävs för arresteringsordern på Andre Firebeard vid Steamwheedle Port. Hamnens lag tillåter att hans huvud ersätter honom vid rättegången.",h="Firebeard’s Head är beviset som krävs för arresteringsordern på Andre Firebeard vid Steamwheedle Port.",kw={"andre firebeard","firebeard’s head","gadgetzan","pirat","security chief bilgewhizzle","steamwheedle port","tanaris","efterlyst"},sec={{t="En bindande arresteringsorder",b="Security Chief Bilgewhizzle godtar Andre Firebeards huvud som ombud vid förhandlingen. Arresteringsordern namnger piraten för brott mot Steamwheedle och Gadgetzan. När du tar huvudet till hamnen betraktar Bilgewhizzle kontraktet som fullgjort och erbjuder dig betalning för ditt arbete."}},faq={{q="Varför begär arresteringsordern hans huvud?",a="Arresteringsordern säger att Andre Firebeards huvud får företräda honom om han är död eller inte kan närvara vid förhandlingen. Security Chief Bilgewhizzle tar emot det vid Steamwheedle Port.",al={"andre huvud arresteringsorder","varför hans huvud","firebeard huvud"}},{q="Vem är Andre Firebeard?",a="Andre Firebeard är en pirat som är efterlyst för brott mot Steamwheedle och Gadgetzan.",al={"andre firebeard","piraten firebeard","vem är andre"}},{q="Vem tar emot Firebeard’s Head?",a="Security Chief Bilgewhizzle tar emot Andre Firebeards huvud vid Steamwheedle Port.",al={"vem vill ha huvudet","bilgewhizzle huvud","var lämna andre huvud"}},{q="Var ligger Steamwheedle Port?",a="Steamwheedle Port ligger vid Tanaris kust. Andre Firebeards arresteringsorder sitter uppsatt där.",al={"steamwheedle plats","tanaris hamn","var ligger hamnen"}}},fp="16,157,17.284.0,38.172.0,23.81.0,29.80.0,27.92.0"}
P.entries["item:fizzle-s-claw"] = {n="Fizzle's Claw",s="I Thunder Ridge förs Fizzle Darkstorms klo till Razor Hill som bevis på hans död. Den goblinske häxmästaren var en farlig konspiratör inom Burning Blade.",h="I Thunder Ridge förs Fizzle Darkstorms klo till Razor Hill som bevis på hans död.",kw={"burning blade","mörka stormar","durotar","fizzle darkstorm","fizzle's claw","orgnil soulscar","razor hill","thunder ridge"},ang={["class:Warlock"]="Som häxmästare vet du att Fizzle Darkstorm använde kaoskonster i Burning Blades tjänst och vände sina talanger mot Horden.",["faction:Horde"]="Som medlem av Horden hjälper du till att rena Durotar från skuggkulter som hotar den unga nationens säkerhet när du visar upp Fizzles klo i Razor Hill."},sec={{t="En grym trofé",b="Orgnil Soulscar skickade styrkor för att rensa bort skuggkulter som hotade orchernas hemland. Han pekade ut Fizzle Darkstorm som en anstiftare som spred fördärv i Thunder Ridge. Klofragmentet ger Hordens befälhavare bevis på att häxmästaren, som verkade under Burning Blades baner, har dödats."},{t="Hotet i Thunder Ridge",b="Thunder Ridge ligger strax nordväst om Razor Hill, tillräckligt nära för att hota de omkringliggande områdena. Hordens spejare förde Fizzles klo tillbaka till Razor Hill och bekräftade att hans ritualer och försök att etablera ett fäste för Burning Blade hade stoppats."}},faq={{q="Vem tillhör den här handen?",a="Klon tillhörde Fizzle Darkstorm, en goblinsk häxmästare med anknytning till Burning Blade.",al={"vem är fizzle","fizzle darkstorm","handens ägare"}},{q="Varför vill Orgnil Soulscar ha Fizzle's Claw?",a="Orgnil Soulscar vill ha bevis på att Fizzle är död. Burning Blade verkar i hemlighet, och klon bekräftar att detta hot mot Durotar har undanröjts.",al={"varför behövs handen","orgnil soulscar hand","bevis på död"}},{q="Var hittades handen?",a="Klon togs från Fizzle Darkstorm vid hans läger i Thunder Ridge, nordväst om Razor Hill i Durotar.",al={"fizzles plats","var är fizzle","hand från thunder ridge"}},{q="Vad gör Burning Blade i Durotar?",a="Burning Blade försöker undergräva orchernas nya hemland med demoniskt fördärv, mörk trolldom och inbördes oro. Häxmästare som Fizzle upprättar dolda läger för att sprida kaos i regionen.",al={"burning blade i durotar","varför finns kultister i thunder ridge"}}},fx={["0fb0af8e"]={q="Vad är Fizzle's Claw?",a="Fizzle's Claw är den avhuggna handen från Fizzle Darkstorm, en förrädisk goblinhäxmästare som är allierad med sekten Burning Blade. Den fungerar som ett makabert fysiskt bevis på hans död för Orgnil Soulscar i Razor Hill och bekräftar att sektens ledare, som ställde till problem i Thunder Ridge, har oskadliggjorts för gott.",al={"vad är fizzles klo","föremålet fizzles claw","vem är fizzle claw"}}},fp="13,177,13.277.0,27.251.0,29.90.0,44.151.0,25.101.0,43.199.0"}
P.entries["item:flagongut-s-fossil"] = {n="Flagongut's Fossil",s="Flagongut's Fossil är ett uråldrigt fynd från utgrävningsplatserna i Wetlands. Det anförtroddes åt dvärgarnas Explorers' League och rymmer dolda hemligheter som Archaeologist Flagongut försöker tyda med hjälp av en mystisk relik kallad Stone of Relu.",h="Flagongut's Fossil är ett uråldrigt fynd från utgrävningsplatserna i Wetlands.",kw={"utgrävning","explorers' league","flagongut","fossil","relu","stone of relu","wetlands","whelgar"},ang={["faction:Alliance"]="Om man säkrar föremål från Whelgar's förstörda utgrävningsplats hindrar man vilddjur från att förstöra värdefull historia och fientliga styrkor från att plundra den i träsket.",["race:Dwarf"]="För dvärgarnas utforskare är fossiler som Flagongut's inga rena kuriositeter. De är fysiska band till forntiden, som Explorers' League har vigt sig åt att gräva fram."},sec={{t="Utgrävning och studier",b="Den här uråldriga fossilen grävdes fram under dvärgarnas expeditioner i Khaz Modan och är mer än bara förstenad sten. Archaeologist Flagongut tror att den rymmer bortglömda krafter knutna till världens äldsta historia, jämförbara med fynd på andra sidan havet i Darkshore. Under regionala studier förvarades fossilen hos Prospector Whelgar på hans utgrävningsplats i Wetlands södra kullar."},{t="Att låsa upp reliken",b="När Flagongut upptäckte Stone of Relu insåg han att den var nyckeln som krävdes för att tyda fossilens hemligheter. Men stenen förlorades efter ett bakhåll av fläckiga rovfåglar på vägen. För att äntligen låsa upp fyndets hemligheter behöver Flagongut äventyrare som hämtar fossilen från Whelgars utgrävning och återfår stenen som svalts av djuren i Wetlands."}},faq={{q="Vad är Flagongut's Fossil?",a="Det är ett uråldrigt arkeologiskt fynd från Wetlands, som dvärgarnas Explorers' League förvarar för att analysera och avslöja hemligheter från världens forntid.",al={"vad är fossilen","flagonguts fossil och bakgrund"}},{q="Var finns fossilen?",a="Den finns i grottan högst upp vid Whelgar's Excavation Site, bland Wetlands södra berg, bevakad av de fläckiga rovfåglar som övertog utgrävningen.",al={"fossilens plats","var finns flagonguts fossil","whelgars fossilgrotta"}},{q="Varför vill Flagongut ha den tillbaka?",a="Flagongut tror att han kan tyda fossilens dolda magiska hemligheter om den kombineras med Stone of Relu, och jämföra dess egenskaper med liknande fynd i Kalimdor.",al={"varför vill flagongut ha den","vad ska flagongut göra med den"}},{q="Hur hänger den ihop med Darkshore?",a="Flagongut ser en koppling mellan fyndet i Wetlands och fossilen som Prospector Remtravel hittade på andra sidan havet i Darkshore. Han tror att Stone of Relu kan låsa upp kraften i båda relikerna.",al={"koppling till darkshore","remtravels fossil"}}},fp="18,180,20.293.0,19.257.1,27.144.0,28.155.0,36.158.0,33.180.0"}
P.entries["item:flatland-cougar-femur"] = {n="Flatland Cougar Femur",s="Ett Flatland Cougar Femur är ett tätt lårben från de rovdjurslika pumor som stryker omkring i Mulgore gyllene gräs. Det är en viktig ingrediens i en traditionell taurenkur mot dödliga, giftiga infektioner.",h="Ett Flatland Cougar Femur är ett tätt lårben från de rovdjurslika pumor som stryker omkring i Mulgore gyllene...",kw={"bloodhoof village","lårben","flatland cougar","maur raincaller","mazzranache","mulgore"},ang={["class:Hunter"]="Att spåra Flatland Cougar kräver skarp blick bland Mulgore vajande snår och prövar en ung jägares förmåga att fälla ett rovdjur utan att skada bytet.",["race:Tauren"]="För Mulgore tauren är jakten på Flatland Cougar både ett prov på vaksamhet och en källa till viktiga material för traditionella kurer från slätterna."},sec={{t="En kur mot ett giftigt bett",b="Flatland Cougar är ett av Mulgore farligaste inhemska rovdjur. Den smälter in bland de torra snåren tills den kastar sig över ett ovetande byte. Jägare tar ofta pumaskinn och klor till läderarbete och troféer, men de kraftiga, märgrika benen har också ett praktiskt värde inom den lokala läkekonsten. När Maur Raincaller, en tauren från Bloodhoof Village, fick ett giftigt sår av den monstruösa rosa stridern Mazzranache, bad han brådskande om ett lårben från en puma och delar från andra lokala bestar. Benet krossas eller kokas för att utvinna dess verksamma ämnen. De blir till ett motgift som kan dra feber och dödligt gift ur ett varigt bett."}},faq={{q="Vad används Flatland Cougar Femur till?",a="Maur Raincaller använder lårbenet för att brygga en nödkur i Bloodhoof Village. Den ökända plainstridern Mazzranache bet honom, och han behöver märgen och benet för att blanda ett motgift innan varelsens starka gift dödar honom.",al={"vad pumans lårben används till","vad är det här benet till","uppdrag med lårben"}},{q="Var får du tag på Flatland Cougar Femur?",a="Du får det från Flatland Cougar som strövar omkring på de centrala och södra slätterna i Mulgore. De håller ofta till nära sluttningarna och stryker genom de höga gräsen kring Bloodhoof Village.",al={"var hittar man lårben","var pumans lårben finns","vilka fiender släpper det"}},{q="Varför behöver Maur Raincaller just ett pumaben?",a="Taurenörtläkare och schamaner använder ofta täta ben och märg från rovdjur i traditionella salvor och tinkturer. Man tror att Mulgore främsta rovdjurs styrka och tålighet ger den återställande grund som behövs för att neutralisera starka gifter.",al={"varför pumaben","varför lårben"}},{q="Vem är Maur Raincaller?",a="Maur Raincaller är en tauren som bor i Bloodhoof Village. Efter att ha vandrat över slätterna råkade han ut för Mazzranache, en legendarisk strider som hans farfar en gång slogs mot. Han kom undan med knapp nöd, men hade ett infekterat, giftigt bett i axeln.",al={"maur raincaller","vem behöver benet"}}},fx={cc87b9fc={q="Vad är ett Flatland Cougar Femur?",a="Det är ett kraftigt ben från ett bakben, taget från de rovgiriga flatland cougars som strövar på Mulgore-slätterna. Sådana täta och tåliga ben efterfrågas ofta av stammarnas helare och schamaner för att bereda traditionella salvor, omslag och läkemedel.",al={"vad är flatland cougar femur","föremålet flatland cougar femur","vad är ett cougar-lårben"}},["47eeaceb"]={q="Var kommer ett Flatland Cougar Femur ifrån?",a="Det tas direkt från flatland cougars, de slanka rovdjur som hör hemma på Mulgore-gräsmarkerna. Till skillnad från tillverkade redskap eller brygder är det här en rå, naturlig trofé som jägare samlar in när de spårar vilddjuren över de vidsträckta slätterna.",al={"flatland cougar femurs ursprung","var hittar man flatland cougar femur","vem släpper cougar-lårben"}}},fp="21,172,28.545.0,43.216.0,44.178.0,58.226.0,23.224.0"}
P.entries["item:flatland-prowler-claw"] = {n="Flatland Prowler Claw",s="En Flatland Prowler Claw tas från de farliga kattdjursrovdjur som stryker omkring på Mulgore grässlätter. För blivande jägare är insamlingen av dessa klor en traditionell övergångsrit som visar list och kampvilja inför Thunder Bluffs äldste.",h="En Flatland Prowler Claw tas från de farliga kattdjursrovdjur som stryker omkring på Mulgore grässlätter.",kw={"flatland prowler","flatland prowler claw","hunter rise","melor stonehoof","mulgore","skorn whitecloud","jägarens väg","thunder bluff"},ang={["class:Hunter"]="Att fälla smygande prowlers prövar jägarens uppmärksamhet i fält. Därför blir klorna en symbol för den respekt som förtjänats bland skarpskyttarna på Thunder Bluffs Hunter Rise.",["race:Tauren"]="För tauren är jakten en hedervärd andlig tradition, och att visa upp klorna från ett listigt slättrovdjur markerar en invigd jägares första steg mot att tjäna stammen som spårare."},sec={{t="Ett bevis för jägaren",b="Flatland prowlers hör till de listigaste och mest revirhävdande rovdjuren som strövar över Mulgore vindpinade slätter. De är snabba på tassarna och skickliga på att överraska byten i det höga gräset. Därför utgör de ett verkligt hot mot resande och ett värdigt prov för unga jägare. Att samla deras vassa klor är inte bara en överlevnadsuppgift, utan en erkänd tradition. Skorn Whitecloud råder lovande vandrare att ta dessa troféer och visa upp dem för Melor Stonehoof på toppen av Thunder Bluffs Hunter Rise. Det bevisar att de har den beslutsamhet och fältvana som krävs för att följa jägarens väg."}},faq={{q="Vad används Flatland Prowler Claws till?",a="De är ett konkret bevis på skicklighet och mod. Unga jägare tar med sig fyra sådana klor till Melor Stonehoof vid Hunter Rise i Thunder Bluff för att visa att de är redo att följa jägarens väg.",al={"användning av prowler claw","varför samla prowler claws","klor för jägarens väg"}},{q="Vem ber dig samla in dem?",a="Den äldre jägaren Skorn Whitecloud uppmanar lovande spårare att samla klor från Mulgore prowlers som bevis innan de presenterar sig för Melor Stonehoof.",al={"vem vill ha prowler claws","uppdragsgivare för prowler claws"}},{q="Varför är flatland prowlers ett lämpligt byte?",a="Flatland prowlers är tåliga, smygande och listiga köttätare som hör hemma på Mulgore slätter. Att spåra upp och besegra sådana vaksamma rovdjur visar att en blivande jägare har det tålamod och de stridsinstinkter som tauren-traditionen kräver.",al={"varför flatland prowlers","är prowlers farliga"}}},fx={cc11ac90={q="Vad är en Flatland Prowler Claw?",a="Det är en klo från en flatland prowler, en av de rovgiriga vildkatter som strövar på Mulgore-gräsmarkerna. Bland taurenjägare är dessa klor ett påtagligt bevis på en ung jägares list, tålamod och växande förmåga att spåra byten.",al={"flatland prowler claw","vad är prowler claw"}},a7640831={q="Var kommer Flatland Prowler Claws ifrån?",a="Klorna kommer direkt från de rovgiriga flatland prowlers som jagar på Mulgore-gräsmarkerna där vinden sveper fram. De tillverkas inte, utan måste tas loss varsamt av en jägare efter att ha spårat upp och besegrat de smidiga bestarna i vildmarken.",al={"var hittar man prowler claws","hur får man tag på prowler claws"}},b4c8d82b={q="Varför vill någon ha Flatland Prowler Claws?",a="Skorn Whitecloud skickar blivande vandrare på jakt efter klorna för att bevisa sitt värde för Melor Stonehoof på Hunter's Rise i Thunder Bluff. Jakt är en av de högsta hedersbetygelserna i taurenkulturen, och klor från så tåliga och listiga rovdjur visar att du har den gryende skicklighet och anda som krävs för att följa jägarens väg.",al={"varför samla prowler claws","vem behöver prowler claws","varför vill melor stonehoof ha klor"}}},fp="21,138,16.457.0,41.189.0,29.129.0,52.196.0"}
P.entries["item:foreman-s-blackjack"] = {n="Foreman's Blackjack",s="Foreman's Blackjack håller peonerna i arbete i Durotars Valley of Trials. Förmän använder den läderklädda käppen för att väcka arbetare som somnar under Hordens tidiga byggnadsarbete.",h="Foreman's Blackjack håller peonerna i arbete i Durotars Valley of Trials.",kw={"klubba","durotar","foreman's blackjack","lata peoner","peon","thazzril","valley of trials"},ang={["faction:Horde"]="Blackjacken speglar den praktiska insats som krävs för att tämja Durotar, där det krävs att varje arbetare arbetar utan uppehåll för att bosätta sig i ett hårt land.",["race:Orc"]="För unga orcher som träder in i Valley of Trials ger blackjacken en tidig lektion i Hordens hierarki: de som saknar en krigares styrka eller mod förvisas till arbete och hålls i schack med våld."},sec={{t="Ett verktyg för orciskt arbete",b="Durotars karga öken kräver lager av timmer till Hordens nya hem. I Valley of Trials faller arbetet på peonerna, och Foreman Thazz'ril håller arbetslagen igång med Foreman's Blackjack. Den viktade klubban ger arbetare som slumrar under dalens skuggande träd en omskakande väckning, inte ett dödligt slag. Livet som peon i den nya Horden innebär utmattande, otacksamt arbete under järnhård kontroll."}},faq={{q="Vad används Foreman's Blackjack till?",a="Överordnade ger blackjacken till unga äventyrare för att tillrättavisa sovande peoner i Valley of Trials. Ett slag rycker en slumrande peon vaken och skickar genast tillbaka dem till att hugga och bära ved.",al={"användning av klubban","varför använda klubban","peonklubba"}},{q="Vem äger den här klubban?",a="Foreman Thazz'ril äger blackjacken. Arbetsförmannen är stationerad i Valley of Trials, där han övervakar insamlingen av råvirke till den unga orchiska bosättningen.",al={"vem ger klubban","vem äger foreman's blackjack"}},{q="Varför somnar peonerna hela tiden på jobbet?",a="Orchiska peoner arbetar outtröttliga, utmattande skift med att samla ved under Durotars hårda sol. När tröttheten tar över slumrar de ofta utan tillåtelse under dalens glesa träd.",al={"varför är peoner lata","lata peoner som sover"}},{q="Får jag behålla klubban när jag är klar med uppgiften?",a="Nej. Den överordnade kräver att verktyget lämnas tillbaka omedelbart efter att de arbetsovilliga har tillrättavisats. Det hålls till hands för arbetsförmän som upprätthåller arbetskvoterna.",al={"behålla klubban","får jag behålla foreman's blackjack"}}},fx={["4e7ef009"]={q="Vad är Foreman's Blackjack?",a="Foreman's Blackjack är en tung batong klädd i läder som Foreman Thazz'ril bär i Valley of Trials. Det är ett oansenligt redskap för disciplin, utformat för att inte åsamka svåra krigsskador, utan ge ett skarpt, svidande slag som får sovande arbetare på benen igen.",al={"vad är blackjacken","föremålet foreman's blackjack","vad är foreman's blackjack"}},["9e33a4a7"]={q="Varför vill Foreman Thazz'ril ha tillbaka sin blackjack?",a="Foreman Thazz'ril förlitar sig på sin blackjack för att hålla ordning på arbetslagen i Valley of Trials. Utan den har han få möjligheter att tvinga de utmattade, omotiverade peons att fortsätta hugga och släpa timmer åt Horden. När du har hjälpt till att få arbetarna tillbaka till sina sysslor förväntar han sig att få tillbaka sitt oumbärliga redskap.",al={"varför lämna tillbaka blackjacken","varför behöver thazz'ril blackjacken","varför vill han ha blackjacken"}}},fp="19,184,22.379.0,41.186.0,24.173.0,48.178.0,50.137.0"}
P.entries["item:forged-steel-bars"] = {n="Forged Steel Bars",s="I norra Barrens saknas Thun'grim Firegazes stålbarrer. Att återta dem visar att en krigare är besluten att återta stulen egendom.",h="I norra Barrens saknas Thun'grim Firegazes stålbarrer.",kw={"the barrens","smitt stål","forged steel bars","järnkista","razormane","stulen järnkista","thun'grim firegaze"},ang={["class:Warrior"]="Att återta Thun'grims stulna stål visar att en krigare kan spåra upp tjuvar och möta farliga quilboarflockar. I gengäld erbjuder Thun'grim skräddarsydda vapen.",["profession:Blacksmithing"]="De raffinerade barrerna visar skillnaden mellan grov, stampräglad skrotmetall och kvalitetsstålet som smids av tränade smeder i Horde."},sec={{t="Stulen metall",b="Thun'grim Firegaze, en synskadad orksmed, har ett läger i norra Barrens. Razormane quilboar tog hans järnkista under en nattlig räd och distraherade honom med grymtningar och frustningar medan tjuvarna smet iväg. Quilboar kunde inte bearbeta fint stål och lämnade den oöppnade kistan nära en förstörd vagn i sitt läger i nordväst. Barrerna är fortfarande oskadda för krigare som är villiga att återta dem."}},faq={{q="Vem äger de här smidda stålstängerna?",a="Barrerna tillhör Thun'grim Firegaze, en orkisk rustningssmed och vapensmed som bor i ett läger i norra Barrens.",al={"vem äger stängerna","thun'grims stål","vems stål är det här"}},{q="Varför stal quilboarerna dem?",a="Razormane quilboar stal dem för att plundra Thun'grims värdesaker. Eftersom de visste att hans syn var dålig hånade och distraherade de honom medan andra bar iväg hans järnkista.",al={"varför stjäla stål","quilboarernas motiv","razormanes stöld"}},{q="Använde quilboarerna stålet?",a="Nej. Razormanes saknade skickligheten att bearbeta så fint raffinerat stål. De lämnade kistan oöppnad bredvid en trasig vagn i sitt läger.",al={"smidde quilboarerna något","vad gjorde quilboarerna med stålet"}},{q="Vad erbjuder Thun'grim i utbyte mot dem?",a="Thun'grim erbjuder blivande krigare ett tillverkat vapen i utbyte mot att de vågar sig in i quilboar-lägren och återlämnar alla barrerna.",al={"belöning för smitt stål","vad får jag för stålet"}}},fx={["4e666297"]={q="Vad är Forged Steel Bars?",a="De här tackorna är ett lager av förädlad metall av hög kvalitet som tillhör smeden Thun'grim Firegaze. De förvaras säkert inlåsta i en järnkista vid hans läger och är fina material avsedda för smide av tåliga vapen. De är råa och har ännu inte blivit färdiga vapen, men hantverket överträffar vida det grova skrot som är typiskt för Barrens.",al={"vad är forged steel bars","information om forged steel bars","stulna ståltackor"}}},fp="17,144,12.419.0,33.114.0,32.173.0,31.136.0,45.110.0"}
P.entries["item:forked-mudrock-tongue"] = {n="Forked Mudrock Tongue"}
P.entries["item:fragments-of-rok-alim"] = {n="Fragments of Rok'Alim",s="Fragments of Rok'Alim är de krossade stenresterna efter en uråldrig jordelementar som strövar omkring i Thousand Needles kanjoner. När de lämnas till Dorn Plainstalker vid The Weathered Nook blir de ett obestridligt fysiskt bevis på att en krigare har besegrat en uråldrig fasa i envig.",h="Fragments of Rok'Alim är de krossade stenresterna efter en uråldrig jordelementar som strövar omkring i...",kw={"dorn plainstalker","elementar","fragment","krossaren","rok'alim","styrkeprovet","thousand needles","the weathered nook"},ang={["class:Shaman"]="Rok'Alim är en uråldrig jordande som varit bunden till världen långt före vår tids schamanistiska pakter. Hans obevekliga natur gör honom till ett fascinerande studieobjekt för elementarisk råstyrka.",["race:Tauren"]="Att övervinna kvarlevor från Azeroths uråldriga förflutna ligger nära tauren-traditionerna att pröva harmoni, uthållighet och personlig styrka mot landets mäktigaste faror."},sec={{t="Rester av en uråldrig kraft",b="Medan de flesta elementarer försvann från Azeroth efter att de gamla gudarna bannlysts, hade några få tillräcklig råstyrka för att överleva på ytan utan att kallas fram med dödligas magi. Rok'Alim the Pounder är en av dessa överlevare och strövar omkring på kanjonernas slätter söder om huvudvägen. De lokala kentaurerna känner igen honom på dånet när hans steniga nävar krossar allt som är dumdristigt nog att komma i hans väg. Om du fäller denna levande kvarleva från urvärlden får du taggiga bitar av tät, animerad sten – en trofé som bevisar oöverträffad fysisk styrka."},{t="Styrkeprovet",b="För tauren-eremiten Dorn Plainstalker är det avgörande momentet i Styrkeprovet att återfinna fragmenten. Som en del av en serie andliga och kampinriktade riter som hålls högt uppe i The Weathered Nook kräver provet att en aspirant möter en varelse med obeveklig råstyrka. Om du lämnar över Rok'Alims sönderslagna spillror bevisar du att du har modet och den fysiska styrkan som krävs för att överleva Kalimdors hårdaste faror."}},faq={{q="Vad är Fragments of Rok'Alim?",a="De är de krossade stenresterna efter Rok'Alim the Pounder, en uråldrig jordelementar som strövar omkring i Thousand Needles nordvästra kanjoner. De tjänar som bevis på att elementaren har besegrats.",al={"fragments of rokalim","vad är rokalimfragment","rokalims sten"}},{q="Vem vill ha dessa stenfragment?",a="Dorn Plainstalker, en tauren-uppdragsgivare som bor vid The Weathered Nook högt uppe längs Thousand Needles kanjonklippor, ber om fragmenten för att avsluta Styrkeprovet.",al={"vem tar emot rokalimfragment","lämna in fragments of rokalim","dorn plainstalker uppdrag"}},{q="Varför är Rok'Alim betydelsefull?",a="Till skillnad från de flesta nutida elementarer som måste frammana­s av dödliga magiker har Rok'Alim dröjt sig kvar i världen sedan de gamla gudarnas tid. Kentaurstammarna i kanjonerna gav honom namnet 'the Pounder' på grund av det dånande ljudet när hans nävar krossar sitt byte.",al={"varför är rokalim speciell","rokalim historia","vem är rokalim the pounder"}},{q="Var hittar man Rok'Alim?",a="Rok'Alim strövar omkring i Thousand Needles nordvästra sänka, söder om områdets huvudväg bland sandstensspirorna.",al={"rokalims plats","hitta rokalim the pounder","var dyker rokalim upp"}}},fx={ab6946f8={q="Var kommer Fragments of Rok'Alim ifrån?",a="Fragmenten är bitar som brutits loss från Rok'Alim the Pounder, en väldig stenelementar som vandrar runt på kanjonens nordvästra botten i Thousand Needles. Till skillnad från elementarer som dödliga besvärjare frammanar är Rok'Alim en uråldrig överlevare från de gamla gudarnas era, med tillräcklig inneboende kraft för att förbli bunden till världen även efter att hans herrar föll. De har inte tillverkats av dödliga händer, utan brutits direkt från hans levande stenform.",al={"fragments of rokalims ursprung","var kommer rokalimfragmenten ifrån","vem tillverkade rokalimfragmenten"}}},fp="21,180,28.394.0,18.321.0,35.174.0,32.159.0,28.236.0,24.112.0"}
P.entries["item:frostwolf-banner"] = {n="Frostwolf Banner",s="Frostwolf Banner är en stamfana som förvaras djupt inne i Wildpaw Cavern i Alterac Valley. Hordens nykomlingar skickas dit för att hämta den som en förfädersrit på vägen till vuxenlivet, väcka sin stridsanda och förtjäna sin första klansymbol.",h="Frostwolf Banner är en stamfana som förvaras djupt inne i Wildpaw Cavern i Alterac Valley.",kw={"alterac valley","frostwolf banner","gnoller","insignia","prövningsplats","warmaster laggrond","wildpaw cavern"},ang={["faction:Horde"]="Att hämta den här fanan markerar en krigares formella första strid och invigning i den legendariska Frostwolf Clan under Warmaster Laggrond.",["race:Orc"]="För orcer hedrar återlämnandet av en förlorad klanfana från vilda gnoller Frostwolf Clans arv och Thralls förfädersarv i Alterac Mountains."},sec={{t="En övergångsrit",b="För Hordens krigare som anländer till Alterac Valley börjar vägen till en verklig plats bland Frostwolf Clan med ett prov på uthållighet. Warmaster Laggrond skickar nyrekryter söderut, in i de fuktiga, fientliga gångarna i Wildpaw Cavern, ett näste fullt av revirhävdande gnoller. Att nå fanan som göms där inne och återvända med den oskadd visar mod, bevisar att krigarens stridsraseri har vaknat och ger dem Frostwolf-novisens insignia."}},faq={{q="Varför finns Frostwolf Banner i en gnollgrotta?",a="Warmaster Laggrond och klanen har medvetet placerat fanan i Wildpaw Cavern för att göra dess läge till ett invigningsprov. En färd in i gnollernas revir tvingar nya krigare att skaka av sig självbelåtenheten, möta faran och väcka sin stridsanda.",al={"varför finns fanan i wildpaw","gnoller har en fana","frostwolf banners plats"}},{q="Vem ska jag lämna tillbaka Frostwolf Banner till?",a="Fanan måste lämnas tillbaka till Warmaster Laggrond i Alterac Valley. När du överlämnar den välkomnar han formellt en nykomling till Frostwolf-ledet och belönar denne med en insignia som visar dennes ställning.",al={"vem vill ha frostwolf banner","lämna in fanans uppdrag","laggrond och fanan"}},{q="Varför ser fanan så ovanlig ut för ett Frostwolf-ärke?",a="Laggrond erkänner den som en klanfana för prövningar, men dess mönster liknar äldre staminsignier, däribland symboler som förknippas med tidiga orciska klaner från den gamla Horden.",al={"skymningshammarens symbol på fanan","fanan ser fel ut","frostwolf banners utformning"}}},fx={cf6c63b1={q="Vad är Frostwolf Banner?",a="Frostwolf Banner är en stamfana som representerar Frostwolf Clan i Alterac Valley. Dess emblem liknar märkligt nog uråldrig klansymbolik snarare än deras vanliga vapen, men den är fortfarande en hedrad symbol för klanens närvaro och makt i den frusna dalen.",al={"vad är frostwolf banner","frostwolf banner i berättelsen","om frostwolf banner"}},["518ec450"]={q="Varför vill Warmaster Laggrond att Frostwolf Banner återtas?",a="Warmaster Laggrond kräver att alla nykomlingar som vill strida tillsammans med Frostwolves i Alterac Valley genomgår ett stridsprov. Om du hämtar fanan från djupet av det gnollangripna Wildpaw Cavern bevisar du ditt mod, väcker din krigaranda och förtjänar en novis insignier bland klanen.",al={"varför återta frostwolf banner","varför vill laggrond ha fanan","frostwolf banners syfte"}}},fp="16,187,17.384.0,48.208.0,40.160.0,57.196.0"}
P.entries["item:frozen-ectoplasm"] = {n="Frozen Ectoplasm",s="Mux Manascrambler behöver Frozen Ectoplasm från Wintersprings rastlösa Highborne-andar. Det är ett av tre spektrala ämnen han söker för sitt arbete med de döda.",h="Mux Manascrambler behöver Frozen Ectoplasm från Wintersprings rastlösa Highborne-andar.",kw={"anguished highborne","ektoplasma","ectoplasmic distiller","frozen ectoplasm","hunting for ectoplasm","mux manascrambler","suffering highborne","winterspring"},ang={["profession:Engineering"]="Som ingenjör känner du kanske igen Mux’s Ectoplasmic Distiller som hans apparat för att samla in spektrala ämnen."},sec={{t="Vinterandar",b="Nära sjön i Winterspring lämnar Anguished och Suffering Highborne efter sig Frozen Ectoplasm. Mux Manascrambler ber dig samla in det med en Ectoplasmic Distiller, tillsammans med Scorched Ectoplasm från Silithus och Stable Ectoplasm från Eastern Plaguelands. Han hoppas att de tre ämnena ska låta honom nå själar som inte helt har lämnat den här världen."}},faq={{q="Var hittar jag Frozen Ectoplasm?",a="Anguished och Suffering Highborne nära sjön i Winterspring lämnar efter sig Frozen Ectoplasm.",al={"var finns frozen ectoplasm","var frozen ectoplasm","ektoplasma winterspring"}},{q="Vad används Frozen Ectoplasm till?",a="Mux Manascrambler behöver det till Hunting for Ectoplasm, där tre sorters ektoplasma ska samlas in med en Ectoplasmic Distiller.",al={"användning av frozen ectoplasm","vad används det till","ektoplasmans syfte"}},{q="Vem vill ha Frozen Ectoplasm?",a="Mux Manascrambler i Gadgetzan vill ha Frozen Ectoplasm, tillsammans med Scorched och Stable Ectoplasm.",al={"mux ektoplasma","vem behöver det","mux manascrambler"}},{q="Varför vill Mux ha ektoplasma?",a="Mux hoppas kunna använda ektoplasmans övernaturliga energier för att nå själar som inte helt har lämnat den här världen.",al={"varför ektoplasma","mux plan","nå själar"}},{q="Vilka andar lämnar efter sig Frozen Ectoplasm?",a="Anguished och Suffering Highborne-andarna i Winterspring lämnar efter sig Frozen Ectoplasm.",al={"ektoplasma från vad","highborne ektoplasma","frozen spirit byte"}}},fp="16,166,14.350.0,33.94.0,29.134.0,27.96.0,28.112.0,36.85.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Full Leaden Collection Phial",s="En tung, blyfodrad flaska fylld med radioaktivt nedfall från de trogger som hemsöker Gnomeregan. Uppfinnaren Ozzie Togglevolt har bett om det farliga provet i hopp om att framställa ett botemedel för bestrålade lepragnomer – eller kanske blanda till en farligt stark rom.",h="En tung, blyfodrad flaska fylld med radioaktivt nedfall från de trogger som hemsöker Gnomeregan.",kw={"full leaden collection phial","gnogaine","gnomeregan","bestrålad trogg","kharanos","uppsamlingsflaska av bly","lepragnom","ozzie togglevolt"},ang={["profession:Engineering"]="Blyhöljet visar på gängse gnomiska säkerhetsrutiner vid hantering av instabilt, giftigt nedfall för laboratorieprov.",["race:Gnome"]="För de förvisade gnomerna i Dun Morogh är det en dyster påminnelse om katastrofen som förgiftade deras förfäders hem att bära detta giftiga prov. Men det står också för ett desperat hopp om att återställa deras förvridna släktingar."},sec={{t="En giftig brygd",b="Blyfodret i uppsamlingsflaskan är nödvändigt för att skydda bäraren från det instabila gröna nedfall som genomsyrar Gnomeregan. Nedfallet uppstod när High Tinker Mekkatorques rådgivare fyllde de nedre korridorerna med giftig strålning för att stoppa de invaderande troggerna. Katastrofen förvred i stället både trogger och överlevande gnomer till vansinniga, bestrålade fasor. Genom att samla vätskerester direkt från Irradiated Invaders och Pillagers förser djärva äventyrare flyktingar bland uppfinnarna, som Ozzie Togglevolt och Razzle Sprysprocket i Kharanos, med råmaterial för deras försök att hitta botemedel."},{t="Botemedel eller brygd",b="Medan Gnoarn är helt inställd på att återta staden tar Ozzie Togglevolt sig an nedfallsproblemet med febriga gnomexperiment. Ozzie vill använda vätskan i flaskan för att behandla en instängd lepragnom – samtidigt som han hoppas att blandningen ska få tillbaka hans eget hår. Gränsen mellan ett mirakulöst motgift och en mycket instabil dryck är farligt tunn inom gnomisk laboratorievetenskap."}},faq={{q="Varför är flaskan gjord av bly?",a="Blyfodret hindrar det starkt radioaktiva nedfall som samlats från Gnomeregans förorenade trogger från att göra bäraren sjuk eller döda hen på vägen tillbaka till Kharanos.",al={"varför blyflaska","syftet med uppsamlingsflaskan av bly","syftet med den blyfärgade insamlingsflaskan"}},{q="Vem vill ha den här bestrålade vätskan?",a="Ozzie Togglevolt, en gnomisk forskare verksam i Kharanos, behöver det bestrålade nedfallet för att försöka hitta ett botemedel för gnomer som drabbats av lepra, med hjälp av Razzle Sprysprocket.",al={"vem behöver flaskan","ozzie togglevolts uppdrag","vem lämnar in gnogaine"}},{q="Varifrån kommer strålningen i flaskan?",a="De lysande gröna resterna samlas direkt från Irradiated Invaders och Irradiated Pillagers, trogger som strövar i de förgiftade korridorerna in mot Gnomeregan.",al={"hur fyller man flaskan","var finns bestrålade trogger","varifrån kommer det gröna skenet"}},{q="Botar Ozzie faktiskt lepragnomerna med det?",a="Ozzies experiment är kaotiska och osäkra. Hans brygd ska bota en tillfångatagen lepragnom och återställa hans eget hår, men gnomisk vetenskap kräver ofta upprepade försök och förfinade prover innan den ger säkra och tillförlitliga resultat.",al={"fungerar botemedlet","vad händer med gnogaine","blir lepragnomen botad"}}},fx={["32cc4509"]={q="Vad är Full Leaden Collection Phial?",a="Det är en tung, blyskärmad flaska fylld med glödande grönt radioaktivt avfall, utvunnet direkt från de förorenade troggs som hemsöker Gnomeregan. Det tjocka blyhöljet hindrar de farliga radioaktiva resterna från att förgifta den som bär flaskan.",al={"vad är blyflaskan","full blyflaska","vad är det här för flaska"}}},fp="28,161,12.485.0,18.331.1,30.195.0,32.163.0,48.145.0,50.226.0"}
P.entries["item:fungal-spores"] = {n="Fungal Spores",s="Runt Barrens oaser samlas Fungal Spores i svällda svampar. Vattnet får livet omkring dem att frodas, och Royal Apothecary Society söker sporerna för sin alkemi.",h="Runt Barrens oaser samlas Fungal Spores i svällda svampar.",kw={"apothecary helbrim","apotekarsällskapet","barrens","crossroads","the forgotten pools","fungal spores","späckad svamp","lushwater oasis","the stagnant oasis"},ang={["profession:Herbalism"]="Som örtletare kan du se hur det livgivande vattnet i Barrens oaser förändrar svamparna som växer i närheten.",["race:Undead"]="Som odöd vet du att Royal Apothecary Society värdesätter sällsynta regionala ingredienser till sin forskning. Kalimdors förändrade svampar erbjuder ett annat val än Lordaerons pestsmittade växter."},sec={{t="Oasernas livskraft",b="Barrens oaser ger de torra slätterna ett ovanligt rikt liv. Vid The Forgotten Pools, Lushwater Oasis och The Stagnant Oasis gör vattnet mer än att släcka törsten. Det får närliggande växter och djur att frodas och förändras. Svampar längs de fuktiga stränderna sväller av sporer som för med sig vattnets koncentrerade kraft och främjar tillväxt. Naturkunniga studerar förändringen, medan Royal Apothecary Society samlar svamparna för sin alkemi."},{t="De förkastades alkemi",b="Apotekare på andra håll samlar ovanliga lokala ingredienser till sina laboratorier och kollegor. Vid The Crossroads skickar Apothecary Helbrim sådana reagenser vidare, bland annat till Apothecary Zamah i Thunder Bluff. Sporerna är värdefulla för att brygga kraftfulla kemiska blandningar. Deras naturliga egenskaper har redan förändrats av de mystiska krafter som finns under Kalimdors jord, vilket gör dem användbara för Forsaken."}},faq={{q="Var hittar man sporerna?",a="Du hittar Fungal Spores i svällda svampar längs stränderna vid Barrens största oaser: The Forgotten Pools, Lushwater Oasis och The Stagnant Oasis.",al={"sporernas platser","var man hittar fungal spores","späckade svampars platser"}},{q="Varför är de förkastade intresserade av dem?",a="Oasernas vatten har förändrat sporerna med livfull livsenergi. Apothecary Helbrim använder dem i kraftfulla blandningar åt Royal Apothecary Society och sin kollega Apothecary Zamah i Thunder Bluff.",al={"varför helbrim vill ha sporer","apotekarens användning av sporer","vad sporer används till"}},{q="Varför växer svamparna kring oaserna sig så stora?",a="Vattnet vid Barrens oaser bär på ovanlig livsenergi som förändrar närliggande växter och djur. Svampar längs stränderna sväller av förändrade sporer.",al={"varför svamparna är muterade","oasvattnets effekt","oasernas mysterium"}},{q="Vem ber om sporerna?",a="Apothecary Helbrim, en alkemist av Forsaken vid The Crossroads i Barrens, ber äventyrare samla sporer åt hans forskning.",al={"vem som behöver fungal spores","uppdragsgivare för sporer","apothecary helbrim"}}},fx={["3c4c96db"]={q="Vad är det här för svampsporer?",a="Det här är potenta sporer som skördats från de frodiga svamparna som växer runt The Barrens oaser, till exempel The Forgotten Pools. Svamparna får näring av de märkliga, förändrade livsenergierna som flödar genom oasernas vatten och producerar sporer med ovanliga biologiska egenskaper som väcker alkemisternas intresse.",al={"vad är svampsporer","information om svampsporer","vad är sporerna"}},["02f1bc1b"]={q="Varför vill Apothecary Helbrim ha svampsporerna?",a="Apothecary Helbrim vid The Crossroads söker sporerna åt Royal Apothecary Society. Han har särskilt stor nytta av oassvamparnas förändrade egenskaper när han blandar en experimentell brygd, som han tänker leverera till sin kollega, Apothecary Zamah, i Thunder Bluff.",al={"varför vill helbrim ha sporer","varför vill någon ha svampsporer","vem behöver svampsporer"}}},fp="13,178,21.429.0,16.379.0,29.151.0,40.200.0,52.133.0,24.104.0"}
P.entries["item:furen-s-instructions"] = {n="Furen's Instructions",s="I Stormwind anger Furen's Instructions materialen som behövs för eldhärdad ringbrynja. Furen Longbeard ger pergamentet till allianskrigare som han har prövat.",h="I Stormwind anger Furen's Instructions materialen som behövs för eldhärdad ringbrynja.",kw={"charred horn","eldhärdad ringbrynja","furen longbeard","furen's instructions","galvanized horn","razorfen kraul","scorched spider fang","stonetalon","vial of phlogiston","wetlands"},ang={["class:Warrior"]="Som allianskrigare ställs du inför prövningar mot vildsinta bestar och quilboar för att förtjäna tung ringbrynjeutrustning.",["profession:Blacksmithing"]="Som smed kan du se hur Furens recept kombinerar reagenser från bestar med sällsynta alkemiska destillat för att härda rustningar utöver vad vanlig smideskonst klarar."},sec={{t="En mästersmeds krav",b="Furen Longbeard erbjuder sig att smida en tålig ringbrynja åt en krigare som har visat vad han går för genom enklare smidesarbete. Den dvärgiske rustningssmeden ber krigaren hämta de sällsynta beståndsdelarna själv. På pergamentet står vad som behövs, och krigaren får färdas mellan kontinenter för att samla ihop det."},{t="Exotiska beståndsdelar",b="Pergamentet kräver en farlig resa genom Eastern Kingdoms och Kalimdor. De härdade länkarna kräver dussintals förkolnade spindeltänder från fuktiga grottor i Wetlands, samt horn från eldspyende chimärer i Stonetalon Mountains klippiga berg. Listan kräver också ett galvaniserat horn från chimärernas matriark och en flaska flyktig flogiston som finns djupt inne i Razorfen Kraul, ett fäste för quilboar."}},faq={{q="Vad är Furen's Instructions?",a="Furen's Instructions är en skriven lista som Furen Longbeard ger till allianskrigare i Stormwind. Den anger vilka exotiska material som behövs för att tillverka eldhärdad ringbrynja.",al={"furens instruktioner","vad är furens instruktioner","furens lista"}},{q="Vem är Furen Longbeard?",a="Furen Longbeard är en dvärgisk mästarrustningssmed i Stormwinds Dwarven District. Han prövar erfarna krigare och tillverkar hållbar skyddsutrustning åt dem.",al={"vem är furen","furen longbeard","furen stormwind"}},{q="Varifrån kommer materialen på listan?",a="Listan kräver förkolnade spindeltänder från Wetlands, förbrända horn och ett galvaniserat horn från chimärer i Stonetalon Mountains samt en flaska flogiston från Roogug i Razorfen Kraul.",al={"var hittar jag föremålen","var finns furens material","material på furens lista"}},{q="Vad smider Furen av de här materialen?",a="Furen använder materialen och sina smideshemligheter för att smida ett särskilt stycke eldhärdad ringbrynja åt krigaren.",al={"vilken rustning smider furen","belöning i eldhärdad ringbrynja","furens smidesbelöning"}}},fx={["82702a01"]={q="Varifrån kommer Furen's Instructions, och vem skrev dem?",a="Furen Longbeard, en skicklig dvärgisk smed som arbetar i Stormwind, skrev dokumentet själv. Han känner till hemligheterna bakom att smida enastående ringbrynja och skrev den här detaljerade förteckningen över de sällsynta komponenter som behövs världen över, så att en ambitiös krigare vet precis vad han ska leta efter.",al={"vem skrev furens instruktioner","varifrån kommer furens instruktioner","furens instruktioners ursprung"}},["42eefba8"]={q="Varför är Furen's Instructions viktiga?",a="Instruktionerna vägleder dig genom en mödosam skattjakt i Kalimdor och Eastern Kingdoms. Furen kräver att du har dem med dig när du samlar in svedda huggtänder, chimärhorn och alkemiskt flogiston, så att du kommer tillbaka med exakt de reagenser han behöver för att smida eldhärdad rustning.",al={"varför behöver jag furens instruktioner","varför efterfrågas furens instruktioner","furens instruktioners syfte"}}},fp="20,106,24.279.0,17.410.0,29.161.0,23.147.0,45.191.0,43.117.0"}
P.entries["item:furen-s-notes"] = {n="Furen's Notes",s="Furen's Notes förmedlar hans upptäckter inom metallurgi och pansarsmide från Stormwind till alliansens hantverkare. Efter att ha smitt skyddsutrustning åt veteraner skickar Furen Longbeard kopior så att andra smeder kan förfina sitt arbete.",h="Furen's Notes förmedlar hans upptäckter inom metallurgi och pansarsmide från Stormwind till alliansens...",kw={"smedskonst","dwarven district","furen","furen longbeard","furen's notes","grimand elmore","klockmort spannerspan","mathiel"},ang={["class:Warrior"]="Som krigare leder dina rustningsprov i Stormwind direkt till dessa anteckningar. De dokumenterar praktiska idéer som formats av frontstridens behov.",["profession:Blacksmithing"]="Som smed får du se hur kunskap om specialiserat rustningshantverk utbyts mellan dvärgiska, alviska och gnomiska hantverkare över hela alliansen."},sec={{t="En mästares upptäckter",b="I Stormwinds Dwarven District smider Furen Longbeard specialanpassade vapen åt krigare och dokumenterar metoderna och upptäckterna han gör längs vägen. Dvärgarnas metallbearbetning förändras ständigt, så han gör flera kopior som andra smeder kan använda och bygga vidare på. Hans anteckningar beskriver praktiska sätt att härda, förstärka och forma rustningar så att de står emot dödliga slag."},{t="Spridda över alliansen",b="Furen skickar kopior till betrodda kontakter i alliansens nätverk av hantverkare. Grimand Elmore kanske hånskrattar åt en medsmid han påstår sig ha undervisat, men anteckningarna innehåller ändå användbara insikter. Kopior färdas över det Stora havet till nattalvernas hantverkare, däribland Mathiel på Darnassus Warrior's Terrace. Gemensamma behov i strid för deras olika traditioner samman."}},faq={{q="Vad innehåller Furen's Notes?",a="Furen's Notes innehåller beskrivningar av pansarsmidestekniker och metallurgiska upptäckter som Furen Longbeard utvecklade när han tillverkade specialrustningar åt erfarna krigare.",al={"vad är furen's notes","vad finns i furens anteckningar","innehållet i furen's notes"}},{q="Vem är Furen Longbeard?",a="Furen Longbeard är en mästersmed bland dvärgarna i Stormwinds Dwarven District. Han vägleder lovande krigare och tillverkar specialanpassad defensiv krigsutrustning.",al={"vem skrev detta","vem är furen","furen longbeard"}},{q="Varför blir Grimand Elmore arg över anteckningarna?",a="Grimand Elmore hävdar att han lärde Furen allt dvärgen kan och ogillar antydan om att hans före detta elev kan lära honom något nytt. Ändå medger Grimand att anteckningarna beskriver tekniker värda att pröva.",al={"varför är grimand arg","grimand elmores reaktion","grimand stolt"}},{q="Vem får kopior av Furen's Notes?",a="Furen skickar kopior till betrodda kollegor över hela alliansen, däribland vapensmeden Grimand Elmore i Stormwind, nattalvssmeden Mathiel i Darnassus och den gnomiska smeden Klockmort Spannerspan i Ironforge.",al={"vem får furens anteckningar","vart skickas anteckningarna","lämna över furens anteckningar"}},{q="Hur reagerar Mathiel på anteckningarna?",a="Mathiel, en nattalvssmed på Darnassus Warrior's Terrace, välkomnar Furens upptäckter med entusiasm. Han ser dem som en storslagen upptäckt och en ära att införliva i sitt eget arbete.",al={"mathiels reaktion","mathiel darnassus","vad tycker mathiel"}}},fx={["224f803f"]={q="Varför vill någon ha Furen's Notes?",a="Anteckningarna beskriver banbrytande smidestekniker som Furen Longbeard utvecklade när han smidde specialrustning åt krigare. Smeder i hela Alliansen, som Mathiel i Darnassus och Grimand Elmore i Stormwind, kan dra nytta av värdefulla metallurgiska insikter i dem. Även hantverkare som tvivlar på Furens skicklighet, som Elmore, ser nyskapande idéer där som de gärna vill pröva vid sina egna städ.",al={"varför vill smeder ha furens anteckningar","värdet av furens anteckningar","varför dela furens anteckningar"}}},fp="13,223,22.332.0,30.350.0,39.157.0,23.146.0,50.205.0,37.212.0,36.183.0"}
P.entries["item:furlbrow-s-deed"] = {n="Furlbrow's Deed",s="Familjen Furlbrow har strandat nära gränsen till Westfall, och deras lagfart är i Defias händer. På dokumentet står Theodore och Verna Furlbrows anspråk på familjens gård, medan paret väntar vid sin trasiga vagn.",h="Familjen Furlbrow har strandat nära gränsen till Westfall, och deras lagfart är i Defias händer.",kw={"lagfart","defias","gård","furlbrow","theodore","verna","vagn","westfall"},ang={["faction:Alliance"]="Som medlem av Alliance kan du ge lite tröst åt undersåtar som tvingats på flykt på grund av kungarikets brist på soldater.",["race:Human"]="Som människa kan du se hur Defias har skadat samhällsordningen i områdena intill Stormwind, till och med genom att stjäla enkla äganderättshandlingar."},sec={{t="Stulen mark och förfalskade anspråk",b="På lagfarten finns Theodore Furlbrows underskrift och även Vernas, som säkrar deras familjegård i Westfall. När Defias Brotherhood tog över regionen drev banditerna bort paret från deras hem och förde dokumentet till Elwynn Forest. Anteckningar på baksidan visar att de tänkte kopiera det när de förfalskade lagfarter för andra egendomar. Familjen Furlbrow förlorade sitt hem och sin försörjning och gav sig sedan ut på vägarna. Deras vagn gick sönder nära gränsen och lämnade dem strandsatta."}},faq={{q="Varför stal Defias lagfarten?",a="Anteckningar på pergamentet visar att Defias tänkte studera sigillet och underskrifterna och sedan förfalska lagfarter för att göra anspråk på beslagtagna gårdar runtom i Westfall.",al={"varför stjäla lagfarten","varför ville banditerna ha lagfarten","defias syfte med lagfarten"}},{q="Vem tillhör den här lagfarten?",a="Lagfarten tillhör Farmer Theodore Furlbrow och hans fru Verna, nybyggare i Westfall som laglösa drev bort från deras gård.",al={"vem äger familjen furlbrows lagfart","vem är furlbrow","vems lagfart är det här"}},{q="Var hittar man familjen Furlbrow?",a="Du hittar paret strax innanför Westfall, bredvid deras trasiga vagn på huvudvägen från Elwynn Forest.",al={"var finns familjen furlbrow","farmer furlbrows plats","var lämnar man tillbaka lagfarten"}},{q="Varför bryr sig familjen Furlbrow fortfarande om lagfarten om de har flytt?",a="Familjen Furlbrow vet att Westfall är alltför farligt för hederligt folk nu, men bevis på äganderätten ger dem hopp om att återta sin mark om freden återvänder.",al={"varför vill de ha tillbaka lagfarten","kommer familjen furlbrow att återvända"}}},fx={["4593623b"]={q="Varifrån kommer Furlbrow's Deed, och vem upprättade den?",a="Lagfarten ger officiell äganderätt till ett stort jordbruksområde i Westfall. Den är undertecknad av Theodore Furlbrow och bevittnad av hans hustru Verna. Den fastslog deras rättmätiga ägande av familjegården innan Defias-banditerna pressade dem på pengar och stal den rakt ur händerna på dem.",al={"furlbrows lagfarts ursprung","vem upprättade furlbrows lagfart","varifrån kom lagfarten"}}},fp="15,205,29.380.0,34.129.0,29.121.0,33.116.0,60.150.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Furlbrow's Pocket Watch",s="I Westfall har Farmer Furlbrow tappat ett minne från sin bröllopsdag. Fickuret var en gåva från Vernas far och lämnades kvar när Defias-banditer tog familjens pumpagård.",h="I Westfall har Farmer Furlbrow tappat ett minne från sin bröllopsdag.",kw={"benny blaanco","defias","farmer furlbrow","furlbrow's pocket watch","det bortglömda arvegodset","verna furlbrow","garderob","westfall"},ang={["faction:Alliance"]="När du hjälper familjen Furlbrow att återfå sitt arvegods ser du hur fullständigt Stormwinds krona har misslyckats med att skydda Westfalls hårt arbetande bönder från organiserad banditverksamhet."},sec={{t="Ett minne bland ruinerna",b="Farmer Furlbrow och Verna flydde hemmet i nattens mörker när Defias-banditer svärmade över Furlbrow Pumpkin Patch. I brådskan lämnade han kvar ett fickur från Vernas far. Uret ligger kvar i en garderob i det övertagna gårdshuset, där Benny Blaanco och hans banditer håller vakt. Det fördrivna paret slår nu läger längs vägen, och uret är en av få saker från deras tidigare liv som fredlösa inte har förstört."}},faq={{q="Varför är fickuret så viktigt för Farmer Furlbrow?",a="Vernas far gav Farmer Furlbrow uret på deras bröllopsdag. Efter att Defias Brotherhood tog deras mark, hem och försörjning är det parets sista ägodel med djupt känslomässigt värde.",al={"varför vill furlbrow ha sitt ur","varför furlbrows ur är viktigt","vem gav furlbrow uret"}},{q="Var förvaras fickuret?",a="Uret ligger i en garderob i Furlbrow-gårdshuset, bland pumpafälten väster om huvudvägen där familjen Furlbrow är strandsatt.",al={"var är fickuret","var furlbrows garderob finns","hur man hittar uret"}},{q="Vem vaktar uret?",a="Defias Brotherhood har tagit över gårdshuset. Benny Blaanco och hans kumpaner håller till nära garderoben.",al={"vem har furlbrows ur","vem vaktar uret i westfall","benny blaanco och uret"}},{q="Stal Defias uret direkt?",a="Nej. Familjen Furlbrow flydde i panik när banditerna gjorde en räd mot pumpagården, och Farmer Furlbrow glömde att packa ner uret. Det blev kvar i garderoben i deras sovrum när gården övertogs.",al={"plundrade defias uret","blev uret stulet"}}},fx={["42b91745"]={q="Vad är Furlbrow's Pocket Watch?",a="Det är ett kärt arvegods som tillhör Farmer Furlbrow. Hans hustru Vernas far gav honom klockan i bröllopsgåva. När Defias Brotherhood tog över deras pumpagård tvingades paret fly för sina liv mitt i natten och lämnade av misstag det dyrbara uret kvar i garderoben.",al={"vad är furlbrows fickur","furlbrows fickur","farmer furlbrows fickur"}},ba43cdcd={q="Varifrån kommer Furlbrow's Pocket Watch, och vem tillverkade den?",a="Klockan tillhörde ursprungligen Verna Furlbrows far, som gav den till Farmer Furlbrow på parets bröllopsdag. Det är okänt vem som tillverkade den eller i vilken stad, men för de fördrivna bönderna är den ett av få bestående minnen av familjen och deras tidigare liv, innan Defias drev bort dem från deras mark.",al={"vem tillverkade furlbrows fickur","var fick furlbrow klockan","furlbrows fickurs ursprung"}}},fp="23,161,23.356.0,56.202.0,31.136.0,26.107.0,40.219.0"}
P.entries["item:gadrin-s-parchment"] = {n="Gadrin's Parchment",s="Gadrin's Parchment läses vid Shadra'Alor i Hinterlands. Orden kallar på Shadra, vars gift Apothecary Lydon söker i Tarren Mill.",h="Gadrin's Parchment läses vid Shadra'Alor i Hinterlands.",kw={"apothecary lydon","gadrin","gadrins pergament","hinterlands","pergament","shadra","shadra'alor","gift","witherbark"},sec={{t="Vid Shadra'Alor",b="Djupt inne i Witherbarkriket läses Gadrin's Parchment vid altaret i Shadra'Alor. Orden kallar på Shadra, spindelguden. Apothecary Lydon söker hennes gift i Tarren Mill."}},faq={{q="Vad används Gadrin's Parchment till?",a="Gadrin's Parchment läses vid Shadra'Alor för att kalla på Shadra, spindelguden.",al={"vad pergamentet används till","gadrins pergament användning"}},{q="Var ska jag läsa pergamentet?",a="Läs Gadrin's Parchment vid altaret i Shadra'Alor, djupt inne i Witherbarkriket i Hinterlands.",al={"var använda pergamentet","shadras altare plats"}},{q="Vem är Shadra?",a="Shadra är spindelguden som kallas fram när Gadrin's Parchment läses vid Shadra'Alor.",al={"shadra spindel","spindelgud"}},{q="Vem vill ha Shadras gift?",a="Apothecary Lydon i Tarren Mill söker Shadras gift.",al={"gift till vem","lydons gift"}}},fp="18,137,14.182.0,32.75.0,30.101.0,14.79.0,25.53.0"}
P.entries["item:gaea-seed"] = {n="Gaea Seed",s="Gaea Seeds är tåliga frökärnor som hittas längs Mirkfallon Lakes strand i Stonetalon Mountains. Tauren-shamaner värdesätter dem, eftersom de är genomsyrade av elementära välsignelser som hjälper till att återställa områden som härjats av krig och industri.",h="Gaea Seeds är tåliga frökärnor som hittas längs Mirkfallon Lakes strand i Stonetalon Mountains.",kw={"the charred vale","återfödelsens kretslopp","jordmodern","gaea seed","mirkfallon lake","stonetalon","sun rock retreat","tammra windfield"},ang={["class:Shaman"]="Fröna visar hur man praktiskt kan återställa jorden och hur shamanistiska ritualer och Jordmoderns välsignelse kan påskynda naturlig tillväxt i skadade miljöer.",["race:Tauren"]="För tauren vid Sun Rock Retreat är odlingen av Gaea Seeds en helig plikt för att läka den balans i landet som rubbats av krig och skogsavverkning utifrån."},sec={{t="Kärl för förnyelse",b="Gaea Seeds hör hemma i Stonetalon Mountains och sköljs naturligt upp eller växer kring stränderna vid Mirkfallon Lake. De ser anspråkslösa ut och liknar små, trådiga kokosnötter, men har en medfödd tålighet. När industriell exploatering och konflikter sargar Stonetalon ser shamaner fröna som livsviktiga redskap för att läka den sårade jorden."},{t="Jordmoderns välsignelser",b="Vid Sun Rock Retreat samlar tauren-shamanen Tammra Windfield Gaea Seeds för att motverka förstörelsen som sprider sig över bergstopparna. Med traditionella sånger och elementära ritualer välsignar shamanerna de vilande skalen i Jordmoderns namn. Denna andliga kraft påskyndar deras naturliga tillväxt dramatiskt och förvandlar enkla frön till tåliga plantor som kan slå rot i förkolnad, karg mark som The Charred Vale."}},faq={{q="Var hittar man Gaea Seeds?",a="Gaea Seeds ligger utspridda längs Mirkfallon Lakes strand, i bergen norr om Sun Rock Retreat i Stonetalon.",al={"gaea seed plats","var hittar man gaea seeds","hur får man gaea seed"}},{q="Vad används Gaea Seeds till?",a="Tammra Windfield samlar dem vid Sun Rock Retreat för att utföra en elementär välsignelse. När fröna har genomsyrats av shamanistisk kraft används de för att återställa växtlivet i ödelagda områden som The Charred Vale.",al={"gaea seed användning","varför samla gaea seeds","vad gör tammra med gaea seeds"}},{q="Varför behöver shamaner välsigna fröna?",a="Marken i delar av Stonetalon har skadats svårt av eld, krig och skogsavverkning. Genom att kanalisera Jordmoderns kraft in i fröna påskyndar shamanerna groningen och gör dem tillräckligt starka för att växa i fientlig, förstörd jord.",al={"varför välsigna fröna","shamanmagi med gaea seed"}},{q="Hur ser Gaea Seeds ut?",a="De ligger nära vattenbrynet runt Mirkfallon Lake och ser ut som små, bruna, rundade skal eller kokosnötter som vilar på stranden.",al={"gaea seed utseende","hur känner man igen gaea seeds"}}},fx={["0f706426"]={q="Vad är ett Gaea Seed?",a="Ett Gaea Seed är en tålig, kokosliknande livskärna som hör hemma i Stonetalon Mountains. Fröna har en naturlig motståndskraft och stor växtkraft som tauren-schamaner utnyttjar med Earthmothers välsignelse för att återställa växtligheten i områden som skadats av industriell girighet och krig.",al={"vad är gaea seeds","information om gaea seed","vad är gaea seed"}},e9a7441d={q="Varifrån kommer ett Gaea Seed?",a="Gaea Seeds är naturliga botaniska underverk som bara finns vid Mirkfallon Lakes strand, högt uppe i Stonetalon Mountains norr om Sun Rock Retreat. De är inte skapade av dödliga händer, utan är naturliga gåvor från Earthmother som frodas längs sjöns stränder.",al={"vem skapade gaea seed","gaea seeds ursprung","varifrån kommer gaea seeds"}},["3509f4c5"]={q="Varför vill Tammra Windfield ha Gaea Seeds?",a="Tammra Windfield, en schaman i Sun Rock Retreat, söker Gaea Seeds för att läka den sargade vildmarken i Stonetalon. Oavbruten skogsavverkning och strider har ödelagt området, särskilt den svedda marken i The Charred Vale. När hon samlar in fröna kan hon kanalisera Earthmothers välsignelse och schamankraft till dem, så att de växer snabbare och återställer det förstörda landet.",al={"varför samla gaea seeds","vem vill ha gaea seeds","varför vill någon ha gaea seed"}}},fp="9,162,18.243.0,28.359.1,27.103.0,29.172.0,39.167.0,29.103.0"}
P.entries["item:gaffer-jack"] = {n="Gaffer Jack",s="En Gaffer Jack är en specialiserad ingenjörskomponent för finjustering av mekanismer, till exempel stintle pegs. Den excentriske gnomuppfinnaren Wizbang Cranktoggle tappade slarvigt en låda med dem i havet utanför Auberdine under sin sjöresa.",h="En Gaffer Jack är en specialiserad ingenjörskomponent för finjustering av mekanismer, till exempel stintle...",kw={"auberdine","darkshore","fiske","gaffer jack","ironforge","stintle pegs","wizbang cranktoggle"},ang={["profession:Engineering"]="Andra mekaniker känner igen frustrationen i att förlora specialdelar som gaffer jacks. Utan dem går det inte att kalibrera känsliga mekanismer som stintle pegs.",["race:Gnome"]="Att lämna Ironforges liv och rörelse för ett stillsamt liv i Auberdine kan verka ovanligt för en gnom. Men att efter för mycket dricka tappa en hel låda med viktiga delar överbord är helt i hans stil."},sec={{t="Förlorade till havs",b="Gnommekanikern Wizbang Cranktoggle ville ha lugn och ro, bort från smedjornas slamrande och värdshusens oväsen i Ironforge. Därför bokade han plats på ett skepp till Auberdine. Under sjöresan drack Wizbang lite för mycket och fumlade så att en hel behållare med gaffer jacks föll överbord. De små mekaniska fästanordningarna sjönk ner i Darkshores dimmiga kustvatten. Nu står han utan de viktiga delar som krävs för att finjustera sina stintle pegs."},{t="Bärgning från havet",b="Eftersom gaffer jacks spilldes ut i bränningarna längs stranden fastnar de ibland på krokarna hos tålmodiga fiskare som kastar ut i Darkshores kustvatten. När komponenterna bärgas kan Wizbang bygga ihop sina märkliga manicker. Att dra upp små metalldelar ur öppet hav kräver både enastående tålamod och ren tur."}},faq={{q="Vad används en Gaffer Jack till?",a="Enligt gnommekanikern Wizbang Cranktoggle är gaffer jacks viktiga ingenjörskomponenter som behövs för att finjustera stintle pegs i hans experimentella uppfinningar.",al={"gaffer jack syfte","vad gör en gaffer jack","gaffer jack användning"}},{q="Hur hamnade de här i havet vid Auberdine?",a="Wizbang Cranktoggle tog ett skepp från Eastern Kingdoms för att få lugn och ro, bort från Ironforge. Under resan drack han för mycket och råkade tappa sin låda med gaffer jacks överbord i Darkshores vatten.",al={"varför ligger gaffer jacks i vattnet","vem tappade gaffer jacks","gaffer jack förlorad"}},{q="Vem vill få tillbaka Gaffer Jacks?",a="Wizbang Cranktoggle, en excentrisk gnomuppfinnare som bor i hamnstaden Auberdine, behöver få tillbaka åtta stycken för att fortsätta bygga sina märkliga uppfinningar.",al={"vem behöver gaffer jacks","lämna in gaffer jacks","vem tar emot gaffer jacks"}},{q="Var kan man hitta Gaffer Jacks?",a="De ligger under vatten längs Darkshores kust på havsbotten, där sportfiskare ibland får upp dem när de fiskar i bränningarna.",al={"var hittar man gaffer jacks","hur hittar man gaffer jacks","gaffer jack plats"}}},fx={["1164a7e3"]={q="Vad är en Gaffer Jack?",a="En Gaffer Jack är en särskild ingenjörskomponent som används av uppfinnare som Wizbang Cranktoggle. Wizbang använder dem för att finjustera sina stintle-pinnar, vilket gör dem oumbärliga i hans verktygslåda för uppfinningar.",al={"vad är gaffer jack","gaffer jacks bakgrund","vad är gaffer jacks"}}},fp="11,130,11.333.0,14.253.0,31.95.0,51.206.0,33.152.0,32.112.0"}
P.entries["item:gahz-ridian-detector"] = {n="Gahz'ridian Detector",s="Gahz'ridian Detector är en anordning som Marvon Rivetseeker konstruerade för att hitta ornamenten som ligger utspridda över Tanaris. Den hjälper honom att samla material till sina studier av trollens ristningar.",h="Gahz'ridian Detector är en anordning som Marvon Rivetseeker konstruerade för att hitta ornamenten som ligger...",kw={"broken pillar","eastmoon ruins","gahz'ridian","gahz'ridian detector","gahz'ridian-ornament","gahz'rilla","marvon rivetseeker","southmoon ruins","tanaris"},sec={{t="En sökning i öknen",b="Marvon Rivetseeker tillverkade Gahz'ridian Detector för att hjälpa till att hitta ornament uthuggna i Gahz'ridian. Troll formade ornamenten för länge sedan som avbilder av Gahz'rilla, som de dyrkade som en gudom. Ristningarna ligger utspridda över Tanaris, och många finns nära Broken Pillar, Eastmoon Ruins och Southmoon Ruins."}},faq={{q="Vem tillverkade Gahz'ridian Detector?",a="Marvon Rivetseeker, en vetenskapsman och skattjägare i Tanaris, uppfann Gahz'ridian Detector.",al={"vem tillverkade detektorn","marvons anordning","detektorns uppfinnare"}},{q="Vad hittar detektorn?",a="Gahz'ridian Detector hjälper till att hitta ornament uthuggna i Gahz'ridian, ett material som fått sitt namn efter Gahz'rilla.",al={"vad detektorn hittar","hitta gahz'ridian","detektorns syfte"}},{q="Vem tillverkade Gahz'ridian-ornamenten?",a="Troll som en gång bodde i Tanaris högg ut Gahz'ridian-ornamenten för länge sedan.",al={"vem tillverkade ornamenten","trollristningar","ornamentens ursprung"}},{q="Varför är ornamenten formade som Gahz'rilla?",a="Ornamenten utformades efter Gahz'rilla, en hydra som trollen dyrkade som en gudom.",al={"varför gahz'rilla-ornament","hydraristningar","gahz'rilla-idol"}},{q="Var hittar jag Gahz'ridian-ornament?",a="Gahz'ridian-ornament ligger utspridda över Tanaris, särskilt kring Broken Pillar, Eastmoon Ruins och Southmoon Ruins.",al={"var ornamenten finns","gahz'ridian-platser","ornament i tanaris"}}},fp="20,184,15.304.0,34.98.0,28.105.0,35.75.0,45.86.0,39.114.0"}
P.entries["item:gahz-ridian-ornament"] = {n="Gahz'ridian Ornament",s="Gahz'ridian Ornaments är snidade reliker utspridda i Tanaris. Marvon Rivetseeker studerar dem för ledtrådar om trollen som en gång bodde här.",h="Gahz'ridian Ornaments är snidade reliker utspridda i Tanaris.",kw={"broken pillar","detektor","eastmoon ruins","gahz'ridian","gahz'rilla","marvon rivetseeker","ornament","southmoon ruins","tanaris","troll"},sec={{t="Snidade reliker",b="Marvon Rivetseeker söker efter Gahz'ridian Ornaments i Tanaris. Han säger att trollen som en gång bodde i öknen snidade dem som avbildningar av Gahz'rilla, hydran de dyrkade. Ornamenten är gjorda av ett ämne som Marvon kallar Gahz'ridian, efter denna vördnadsfullt dyrkade varelse. Han har redan samlat in några och vill ha fler för sina studier."}},faq={{q="Vad är Gahz'ridian Ornaments?",a="Gahz'ridian Ornaments är sniderier gjorda av trollen som en gång bodde i Tanaris. De föreställer Gahz'rilla, en hydra som trollen dyrkade.",al={"gahz'ridian","vad är gahz'ridian","betydelsen av ornament"}},{q="Vem vill ha ornamenten?",a="Marvon Rivetseeker, en vetenskapsman och skattjägare i Tanaris, vill ha Gahz'ridian Ornaments för sina studier.",al={"vem vill ha gahz'ridian","marvon ornament","var lämna ornament"}},{q="Var hittar jag Gahz'ridian Ornaments?",a="Ornamenten finns utspridda i Tanaris, många i närheten av Broken Pillar, Eastmoon Ruins och Southmoon Ruins.",al={"gahz'ridian platser","var finns ornament","gahz'ridian ruiner"}},{q="Vad är Gahz'rilla?",a="Gahz'rilla är en hydra som trollen i Tanaris dyrkade som en gudom. Ornamenten är snidade som avbildningar av den.",al={"gahz'rillas betydelse","hydragud","trollgudom"}},{q="Vad används detektorn till?",a="Marvon Rivetseeker uppfann Gahz'ridian Detector för att hjälpa till att hitta ornamenten som är utspridda i Tanaris.",al={"gahz'ridian detector","ornamentsökare","hur hitta gahz'ridian"}}},fp="20,142,13.341.0,31.135.0,24.108.0,39.112.0,19.108.0,25.106.0"}
P.entries["item:gallywix-s-head"] = {n="Gallywix's Head",s="I Orgrimmar visar Gallywix's Head att en förman från Venture Company avrättades. The Shattered Hand kräver trofén som bevis på dödandet.",h="I Orgrimmar visar Gallywix's Head att en förman från Venture Company avrättades.",kw={"the barrens","gallywix","orgrimmar","puzik","shattered hand","shenthul","the sludge fen","venture co"},ang={["class:Rogue"]="Som skurk bevisar du med hämtningen av Gallywix's Head din dödliga skicklighet i infiltration, smygande och riktat lönnmord åt The Shattered Hand.",["faction:Horde"]="Som medlem av The Horde hjälper du till att hejda Venture Company's exploaterande industriella intrång, som hotar gränserna till The Barrens och Durotar."},sec={{t="Ett bistert bevis på att målet undanröjts",b="Överförman Puzik Gallywix ledde Venture Company's arbete från dess torn norr om The Sludge Fen. När ryktet nådde dem att Venture Co. planerade något storskaligt skickade The Shattered Hand agenter för att montera ned anläggningen. Att ta Gallywix's Head till Shenthul i Orgrimmar bevisar att förmannen avrättades och befäster skurkens ställning i gillet."},{t="Infall vid The Sludge Fen",b="Ordern att ta Gallywix's Head kräver också att en stulen Cache of Zanzil's Altered Mixture hämtas och att tornets förgiftade personal slaktas. Agenter lönnmördar Gallywix högst upp på hans utkikspost och återför hans huvud till The Cleft of Shadow. Dådet bekräftar att Venture Company's storslagna plan i The Barrens har stoppats."}},faq={{q="Vems huvud är det här?",a="Huvudet tillhör Grand Foreman Puzik Gallywix, en goblinöverordnad som leder Venture Companys verksamhet vid The Sludge Fen i norra The Barrens.",al={"vem är gallywix","puzik gallywix","gallywix huvudets ursprung"}},{q="Vem vill ha Gallywix's Head?",a="Shenthul vill ha Gallywix's Head. Han är en skurk-tränare och agent för The Shattered Hand i The Cleft of Shadow i Orgrimmar.",al={"vem ska jag lämna huvudet till","lämna in gallywix huvud","shenthul huvud"}},{q="Varför vill Shattered Hand ha honom död?",a="Puzik Gallywix styrde Venture Company's torn norr om The Sludge Fen, där Venture Co. planerade något storskaligt. Han förvarade också den sista cachen med Zanzil's Altered Mixture i sitt kassaskrin. The Shattered Hand dömde honom till döden för att slå ut verksamheten och lägga beslag på blandningen.",al={"varför döda gallywix","orsak till mordet på gallywix"}},{q="Var finns Puzik Gallywix?",a="Puzik Gallywix finns högst upp i Venture Company's torn, strax norr om The Sludge Fen i norra The Barrens.",al={"var är gallywix","gallywix plats","tornboss vid sludge fen"}}},fx={["862bd188"]={q="Varifrån kommer Gallywix's Head?",a="Huvudet har skilts från Grand Foreman Puzik Gallywix, en goblinförman som övervakar verksamheten i Venture Companys torn norr om The Sludge Fen i The Barrens. En lönnmördare får i uppdrag av Shattered Hand att infiltrera fästet och döda dess invånare. Huvudet tas direkt från förmannens lik högst upp i tornet som bevis på att operationen har slagits ut grundligt.",al={"var får man gallywix huvud","gallywix huvuds ursprung","hur får man gallywix huvud"}}},fp="15,144,27.371.0,24.322.1,19.152.0,26.119.0,42.285.0,32.117.0"}
P.entries["item:galvanized-horn"] = {n="Galvanized Horn",s="I The Charred Vale bär chimaeramatriarker horn som rustningssmeder i Stormwind och Thunder Bluff söker efter. Dessa förhårdnade utväxter används i specialrustningar för krigare.",h="I The Charred Vale bär chimaeramatriarker horn som rustningssmeder i Stormwind och Thunder Bluff söker efter.",kw={"the charred vale","chimaeramatriark","eldhärdad ringbrynja","furen longbeard","galvanized horn","orm stonehoof","stonetalon mountains"},ang={["class:Warrior"]="Som krigare prövas din uthållighet och styrka när du fäller en matriark och tar hennes Galvanized Horn. Det bevisar ditt mod för mästersmeder i Stormwind eller Thunder Bluff.",["profession:Blacksmithing"]="Som smed visar hornet hur organiska material som härdats under extrema förhållanden kan mäta sig med eller överträffa bearbetade metaller i specialanpassad rustningsförstärkning."},sec={{t="Trofé från The Charred Vale",b="Chimaeramatriarker stryker omkring i The Charred Vale i Stonetalon Mountains. Deras horn blir ovanligt hårda av aska, eld och kampen för att överleva. Yngre chimaeror ger spröda, svärtade horn, men en matriarks horn är lika starkt som behandlad metall. Furen Longbeard i Stormwind och Orm Stonehoof i Thunder Bluff söker båda ett horn som prov på krigisk tapperhet och som en viktig ingrediens i utsökt ringbrynja."}},faq={{q="Varifrån kommer ett Galvanized Horn?",a="Ett Galvanized Horn kommer från en chimaeramatriark i The Charred Vale, i västra Stonetalon Mountains.",al={"var hittar man galvanized horn","hur får man galvanized horn","galvanized horn byte"}},{q="Varför vill smeder ha just det här hornet?",a="Mästersmeder värdesätter hornets täthet och värmetålighet. De använder det för att förstärka specialgjorda ringbrynjor och plåtrustningar.",al={"vad används galvanized horn till","användning av galvanized horn"}},{q="Vem tar emot Galvanized Horn?",a="Furen Longbeard i Stormwind söker hornet till eldhärdad rustning åt alliansens krigare. Orm Stonehoof i Thunder Bluff söker det som bevis på styrka och för att smida en krigarhjälm åt hordens krigare.",al={"vem behöver galvanized horn","lämna in galvanized horn"}},{q="Hur skiljer det sig från ett vanligt Charred Horn?",a="Vanliga Charred Horn kommer från yngre chimaeror. Ett Galvanized Horn kommer från en fullvuxen matriark och har en tätare, härdad struktur som passar för mästerligt smide.",al={"charred horn jämfört med galvanized horn","skiljer det sig från charred horn"}}},fx={["39b0e048"]={q="Vad är ett Galvanized Horn?",a="Ett Galvanized Horn är ett sällsynt, hårdnat horn från en chimärmatriark som lever i Stonetalon Mountains i Kalimdor. Till skillnad från vanliga chimärhorn har det härdats av den hårda, eldhärjade miljön i The Charred Vale, vilket gör det exceptionellt tåligt och eftertraktat av mästersmeder i både Alliansen och Horden.",al={"vad är galvanized horn","galvanized horns bakgrund"}}},fp="15,140,26.367.0,39.107.0,38.131.0,32.205.0,47.173.0"}
P.entries["item:gan-zulah-s-head"] = {n="Gan'zulah's Head",s="Gan'zulah's Head tas från Bloodscalp-hövdingen vid Zul'Kunda. Vid Grom'gol förs det till en bubblande kittel som en del av sökandet efter Yenniku.",h="Gan'zulah's Head tas från Bloodscalp-hövdingen vid Zul'Kunda.",kw={"bloodscalp","kittel","darkspear","gan'zulah","gan'zulah's head","grom'gol","nimboya","yenniku","zul'kunda"},ang={["faction:Horde"]="Som medlem av Horde hjälper du Darkspear vid Grom'gol att söka sanningen om Yenniku bland sina fiender, Bloodscalp.",["race:Troll"]="Som troll befinner du dig mitt i konflikten mellan Darkspear och Bloodscalp-klanen, vars hövdings huvud Nimboya söker."},sec={{t="En hövdings huvud",b="Vid Zul'Kunda i nordvästra Stranglethorn söks Gan'zulah's Head och Nezzliok the Dire's huvud. Nimboya ber dig ta båda till den bubblande kitteln vid Grom'gol Base Camp. Darkspear hoppas att de döda ledarna kan avslöja sanningen om Yenniku."}},faq={{q="Vem var Gan'zulah?",a="Gan'zulah var hövding för Bloodscalp-trollen vid Zul'Kunda och en fiende till Darkspear-stammen.",al={"gan zulah","bloodscalp-hövding","gan'zulahs bakgrund"}},{q="Varifrån kommer Gan'zulah's Head?",a="Gan'zulah's Head tas från Gan'zulah vid Ruins of Zul'Kunda i Stranglethorn Vale.",al={"varifrån kommer huvudet","var finns gan'zulah's head","hitta gan'zulah"}},{q="Varför vill Nimboya ha huvudet?",a="Nimboya vill att Gan'zulah's Head och Nezzliok's Head läggs i den bubblande kitteln vid Grom'gol Base Camp, i hopp om att få veta sanningen om Yenniku.",al={"varför huvudet","vad nimboya vill ha","huvud åt nimboya"}},{q="Vad är kitteln till för?",a="Darkspear lägger Gan'zulahs och Nezzlioks huvuden i kitteln i hopp om att få de döda ledarna att tala om Yenniku.",al={"bubblande kittel","kitteln vid grom'gol","vad kitteln gör"}},{q="Vem är Yenniku?",a="Yenniku är en Darkspear-troll vars öde fortfarande är okänt för Nimboya och hans folk.",al={"yenniku","var är yenniku","sökandet efter yenniku"}}},fp="16,150,14.262.0,18.95.0,38.89.0,31.146.0,25.125.1,15.82.0"}
P.entries["item:gargantuan-tumor"] = {n="Gargantuan Tumor",s="Gargantuan Tumor är en massiv, sjuklig utväxt som slitits loss från den fördärvade timberlingen Oakenscowl i Teldrassil. Den är ett tydligt bevis på den onaturliga sjukdom som sprider sig bland varelserna vid Lake Al'Ameth.",h="Gargantuan Tumor är en massiv, sjuklig utväxt som slitits loss från den fördärvade timberlingen Oakenscowl i...",kw={"fördärvning","gargantuan tumor","lake al'ameth","oakenscowl","teldrassil","timberling"},ang={["class:Druid"]="För druider som strävar efter att vårda Teldrassils späda grenar är den groteska tumören en oroväckande påminnelse om att naturen bland grenarna är farligt sårbar för fördärvning.",["race:NightElf"]="Att se en aktad timberlingäldste förvandlad till ett vansinnigt, plågat monster understryker de växande miljöproblemen som möter kaldoreiernas nya hemland."},sec={{t="Plåga över sjön",b="Nära Lake Al'Ameths södra strand finns en grotta där Oakenscowl håller till, en gång en ädel timberlingäldste som fallit offer för en vidrig åkomma. Varelsen var synbart förgiftad av en enorm utväxt som förvrängde dess beteende och spred smitta till djurlivet omkring den. Att skära loss denna groteska tumör är avgörande, både för att få slut på bestens plågade framfart och för att låta lokala forskare undersöka plågan och förstå hur en sådan fasansfull sjukdom fick fäste i grenarna på det nyväxta världsträdet."}},faq={{q="Varifrån kommer Gargantuan Tumor?",a="Tumören hämtas från Oakenscowl, en stor fördärvad timberling som bor i en grotta vid Lake Al'Ameths södra strand i Teldrassil.",al={"tumörens ursprung","hur får man gargantuan tumor","oakenscowl byte"}},{q="Vad får tumören att växa på Oakenscowl?",a="Den är ett yttre symtom på den märkliga fördärvning som förgiftar timberlingarna och djurlivet kring Lake Al'Ameth. Oakenscowl var en gång en mäktig ledare för sitt folk, men dukade helt under för denna smittsamma utväxt.",al={"varför har oakenscowl en tumör","timberlingarnas sjukdom","fördärvning vid lake al'ameth"}},{q="Vem vill studera den här tumören?",a="Forskare i området behöver tumören för att undersöka den märkliga förruttnelse som drabbar traktens timberlingar och hoppas kunna ta reda på hur plågan kan behandlas eller hejdas.",al={"vem tar emot tumören","lämna in gargantuan tumor","lämna in oakenscowl-uppdraget"}}},fx={b9b4574c={q="Vad är Gargantuan Tumor?",a="Det är en enorm, grotesk utväxt som skurits loss från Oakenscowl, en förvriden timberlingäldste som lurar i en grotta längs södra stranden av Lake Al'Ameth. Tumören förgiftar tydligt varelsen och driver den till vansinne, vilket sprider onaturlig förruttnelse och sjukdom i vattnen och bland djurlivet i närheten.",al={"vad är gargantuan tumor","gargantuan tumor","oakenscowl-tumören"}}},fp="16,140,20.455.0,42.131.0,48.171.0,30.121.0"}
P.entries["item:garrick-s-head"] = {n="Garrick's Head",s="Vid Northshire Vineyards bevisar Garrick Padfoots avhuggna huvud att stråtrövaren är död. Myndigheterna vid Northshire Abbey kräver det för att betala ut belöningen.",h="Vid Northshire Vineyards bevisar Garrick Padfoots avhuggna huvud att stråtrövaren är död.",kw={"belöning","deputy willem","elwynn forest","garrick padfoot","garrick's head","northshire abbey","northshire valley"},ang={["class:Rogue"]="Som skurk visar du lokala busar att stråtröveri möts av dödliga, yrkesskickliga klingor.",["race:Human"]="Som människa blir Padfoots huvud ett tidigt slag mot laglösheten som sprider sig genom Elwynn Forest."},sec={{t="En stråtrövares slut",b="Garrick Padfoot och hans gäng trakasserade bönder och handelsmän i Northshire Valley i flera veckor. Stormwinds försvar var hårt ansträngt, så Garrick slog sig ned i en koja nära vingårdarna och plundrade förbipasserande handelsmän. De lokala vakterna var upptagna med kobolder och Defias-banditer, så Deputy Willem utlyste en belöning för laglösens död. Han sökte någon som var villig att döda Garrick och återvända med bevis."}},faq={{q="Vem var Garrick Padfoot?",a="Garrick Padfoot var en stråtrövare som terroriserade bönderna och vingårdsarbetarna i Northshire Valley samt handelsmän på resande fot. Han upprättade en utpost med sitt gäng öster om Northshire Abbey, på andra sidan floden.",al={"vem är garrick","garrick padfoots historia","vem var padfoot"}},{q="Varför behövs ett avhugget huvud för att få belöningen?",a="Deputy Willem och myndigheterna i Northshire kräver bevis på att Garrick är död innan de betalar ut belöningen.",al={"varför hans huvud","bevis på dödsfall","varför ta garricks huvud"}},{q="Var gömde sig Garrick Padfoot?",a="Padfoot gömde sig i en liten träkoja öster om Northshire Abbey, på andra sidan flodbron nära Northshire Vineyards.",al={"var är garrick","garricks koja plats","var hittar man garrick padfoot"}},{q="Vem betalar belöningen för Garricks huvud?",a="Deputy Willem utlyste belöningen och betalar ut den när han får Garricks huvud. Han är stationerad strax utanför ingången till Northshire Abbey.",al={"vem vill ha garricks huvud","lämna in garricks huvud","vem lämnade in garricks huvud"}}},fx={cb1a40d1={q="Vad är Garrick's Head?",a="Det avhuggna huvudet är ett fasansfullt bevis på att Garrick Padfoot, en ökänd mördare som har terroriserat bönder och handelsmän i Northshire Valley, har gått under. Om du tar den här trofén tillbaka till klostret bekräftar det att hans rövarband har förlorat sin ledare.",al={"vad är garricks huvud","föremålet garricks huvud","vem tillhör det här huvudet"}},["79b2de99"]={q="Varifrån kommer Garrick's Head?",a="Det tas direkt från Garrick Padfoot själv. Skurken slog läger i en liten stuga nära Northshire Vineyards, på andra sidan floden österut, omgiven av lojala busar som vaktade hans byte.",al={"var får man garricks huvud","vem släpper garricks huvud","garricks huvuds källa"}}},fp="14,162,14.369.0,24.197.0,51.103.0,33.116.0,39.134.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Gazlowe's Ledger",s="I Ratchet jämför Gazlowe sina handelsböcker med hamnmanifestet när en leverans från Booty Bay försvinner.",h="I Ratchet jämför Gazlowe sina handelsböcker med hamnmanifestet när en leverans från Booty Bay försvinner.",kw={"booty bay","dizzywig","freebooters","gazlowe","liggare","ratchet","leverans","steamwheedle"},ang={["class:Rogue"]="Som rogue får du en inblick i flödet av smuggelgods, värdefull import och piratverksamhet längs The Barrens kust genom en goblinboss privata handelsliggare.",["faction:Horde"]="Som medlem av Horde kan du handla i Ratchet, en neutral hamn. När du hjälper Gazlowe att spåra stulna leveranser behåller du de lokala Steamwheedle-myndigheternas förtroende."},sec={{t="Ratchets handelsregister",b="Gazlowe bokför handelsvaror i Ratchet i en personlig liggare. Där noteras importerade lådor, utgående last och lagerförråd. När en leverans från Booty Bay saknas jämför Gazlowe sitt förväntade lager med kajregistren som Wharfmaster Dizzywig för."},{t="Avslöja stölden",b="Gazlowe och de andra goblinerna jämför liggaren med Dizzywigs hamnloggar och upptäcker att lasten aldrig nådde hamnlagret. Avvikelsen bekräftar Gazlowes misstanke om att lådorna stals innan de kom i land. Southsea Freebooters längs den närbelägna Merchant Coast bär skulden."}},faq={{q="Vad är Gazlowe's Ledger?",a="Gazlowe's Ledger förtecknar varor som väntas in och förvaras i Ratchet. Gazlowe skickar den till hamnen så att uppgifterna kan jämföras med kajregistren när en leverans saknas.",al={"gazlowes liggare","ratchets liggare","gazlowes lagerbok"}},{q="Vem behöver granska liggaren?",a="Wharfmaster Dizzywig granskar Gazlowe's Ledger mot sina fraktloggar. Han ansvarar för kajerna i Ratchet och kan avgöra om saknade varor hamnat fel eller aldrig lossats.",al={"vem ska jag lämna liggaren till","mottagare av liggaren","dizzywigs liggare"}},{q="Vilken last saknades enligt liggaren?",a="Gazlowe väntade på sin senaste leverans från Booty Bay. Dizzywig hittar inget avvikande i sina loggar, men säger att varor från Undermine väntar på att Gazlowe ska hämta dem.",al={"vad saknar gazlowe","saknat lastgods"}},{q="Vad händer efter att liggaren har kontrollerats?",a="Dizzywig kontrollerar om leveransen passerade genom hamnen. När han upptäcker att den inte gjorde det skickas liggaren tillbaka till Gazlowe, vilket bekräftar att Southsea Freebooters troligen lade beslag på lasten till sjöss.",al={"vad händer med liggaren","efter dizzywig har kontrollerat"}}},fx={d44950a4={q="Varifrån kommer Gazlowe's Ledger, och vem har den?",a="Förteckningen tillhör Gazlowe, goblinchefen som styr hamnstaden Ratchet. Den är hans personliga inventarielista och dokumenterar inkommande och utgående frakt som skeppas över Great Sea mellan Ratchet och andra gobliners handelsnav, som Booty Bay.",al={"vem skrev gazlowes förteckning","varifrån kommer gazlowes förteckning","gazlowes förtecknings ursprung"}},c4547cde={q="Varför behövs Gazlowe's Ledger just nu?",a="Gazlowe misstänker att en länge försenad leverans från Booty Bay har stulits av Southsea Freebooters. Innan han drar förhastade slutsatser behöver han att du tar hans förteckning till Wharfmaster Dizzywig vid hamnen, så att de kan jämföra inventarielistorna med hamnens loggböcker och utesluta ett skrivfel.",al={"varför vill någon ha gazlowes förteckning","varför behövs gazlowes förteckning","vad används gazlowes förteckning till"}}},fp="16,103,28.271.0,20.278.1,25.169.0,32.170.0,37.165.0,41.193.1"}
P.entries["item:gem-of-anacondra"] = {n="Gem of Anacondra",s="Gem of Anacondra är en av fyra drömgemmer som de korrumperade ormförrådarledarna håller i Wailing Caverns. Lady Anacondra bär den som ett påtagligt bevis på sitt nederlag och på att Mardrömmens spridning över The Barrens har hejdats.",h="Gem of Anacondra är en av fyra drömgemmer som de korrumperade ormförrådarledarna håller i Wailing Caverns.",kw={"drömgem","druids of the fang","gem of anacondra","lady anacondra","fangs ledare","nara wildmane","wailing caverns"},ang={["class:Druid"]="För Cenarion-druider är det en högtidlig plikt att hämta den här gemmen och fälla en syster som överlät sitt sinne och sina skepnader åt den korrumperande Emerald Nightmare.",["race:Tauren"]="Att återta gemmen hjälper Nara Wildmane i Thunder Bluff direkt och skingrar de mörka visioner som plågar Shu'halos slummer på Elder Rise."},sec={{t="Ett korrumperat fokus",b="När Naralex gick in i sin djupa slummer för att återföra vatten och liv till det torra The Barrens, trängde Emerald Nightmare in i hans tankar och förvrängde hans närmaste lärjungar. Lady Anacondra och hennes medkonspiratörer övergav sina traditionella seder och blev Druids of the Fang. De förvred sitt ädla, livgivande syfte till en giftig vanföreställning. Gem of Anacondra är en av de fyra drömgemmer som dessa ormlika ledare bär. Den fokuserar deras korrumperade band till The Emerald Dream och förankrar mardrömmen i grottsystemet."},{t="Att rena visionen",b="Nara Wildmane och Cenarion-druidernas krets i Thunder Bluff upptäckte att deras egen slummer plågades av visioner och onda ansikten från ledarna för Fang. De hävdar att Gem of Anacondra måste hämtas, tillsammans med stenarna från Cobrahn, Pythas och Serpentis, för att bekräfta att Lady Anacondra har fällts. Då kan den förtryckande mardrömmen lyftas från sinnena hos Kalimdors väktare av balansen."}},faq={{q="Vad är Gem of Anacondra?",a="Det är en drömgem som Lady Anacondra bär. Hon är en av de fyra ledarna för de förvridna Druids of the Fang som håller till i Wailing Caverns.",al={"vad är anacondras gem","anacondras gem","vad gör gem of anacondra"}},{q="Vem vill ha den här gemmen?",a="Nara Wildmane, en tauren-druid på Elder Rise i Thunder Bluff, söker efter gemmen och de tre andra drömgemmerna för att befria sitt sinne från mardrömmar och skydda The Barrens.",al={"vem tar emot gem of anacondra","var lämnar jag in anacondras gem","lämna in gem of anacondra"}},{q="Var finns Gem of Anacondra?",a="Lady Anacondra bär gemmen. Hon lurar i de slingrande underjordiska gångarna i Wailing Caverns, mitt i The Barrens.",al={"var droppar den","vem droppar gem of anacondra","lady anacondras plats"}},{q="Varför är drömgemmerna viktiga?",a="De fyra gemmerna hålls av de korrumperade ledarna för Druids of the Fang. När de samlas in bekräftas det att ledarna har undanröjts, och deras grepp om korruptionen i The Emerald Dream i området bryts.",al={"varför fyra gemmer","drömgemmernas syfte","fangs ledares gemmer"}}},fx={["2e0de493"]={q="Varifrån kommer Gem of Anacondra, och vem skapade den?",a="Lady Anacondra bär ädelstenen djupt inne i Wailing Caverns. Det är okänt vem som slipade eller förtrollade den, men den är en av drömädelstenarna som innehas av de fyra ledarna för Druids of the Fang. Dessa korrumperade nattalver tillhörde en gång en ädel krets som ägnade sig åt att hela The Barrens. Nu kanaliserar de sina förvridna visioner av The Emerald Dream genom dessa stenar.",al={"ursprung gem of anacondra","vem skapade gem of anacondra","var fick anacondra sin ädelsten"}}},fp="16,175,17.541.0,20.369.1,29.153.0,19.180.0,40.112.0,33.201.0"}
P.entries["item:gem-of-cobrahn"] = {n="Gem of Cobrahn",s="Gem of Cobrahn är en drömpärla som bärs av Lord Cobrahn, en av de korrumperade ledarna för Druids of the Fang i Wailing Caverns. Den fungerar både som fokus för hans förvridna drömmar och som fysiskt bevis som Nara Wildmane behöver för att bekräfta hans nederlag.",h="Gem of Cobrahn är en drömpärla som bärs av Lord Cobrahn, en av de korrumperade ledarna för Druids of the Fang...",kw={"drömpärla","druids of the fang","gem of cobrahn","fang-ledarna","lord cobrahn","nara wildmane","wailing caverns"},ang={["class:Druid"]="För Cenarion-druiderna innebär återtagandet av Gem of Cobrahn det tragiska men nödvändiga slutet för en fallen broder som övergav naturens harmoni för The Emerald Nightmare.",["race:Tauren"]="Druiderna i Thunder Bluff håller noga uppsikt över The Barrens. Att ta Cobrahns pärla skyddar slätterna och jaktmarkerna direkt från onaturlig förvanskning."},sec={{t="Ett fokus för korrumperade drömmar",b="När nattalven Naralex gick in i The Emerald Dream för att återställa Kalimdors karga slätter förvrängde hans mardröm både Wailing Caverns och hans lärjungar. En av dem var Cobrahn, som övergav Cenarion Circles fredliga seder och antog ormens skepnad. Lord Cobrahn bär en av de fyra drömpärlor som förankrar ledarnas grepp om de underjordiska vattenvägarna, och använder den för att kanalisera de förvridna drömmar som hotar att förvandla The Barrens till ett giftigt träsk."},{t="Återställa balansen",b="I Thunder Bluff plågas tauren-druiden Nara Wildmane av mardrömmar som skickas av de avfälliga Druids of the Fang. För att rena de underjordiska källorna och skydda Kalimdor från deras vision måste äventyrare utforska grottorna, döda Lord Cobrahn och hans tre medkonspiratörer och återta deras drömpärlor. När Cobrahns pärla återlämnas till Cenarion-druiderna upphör hans korrumperande inflytande över den sovande Naralex."}},faq={{q="Vad är Gem of Cobrahn?",a="Det är en drömpärla som innehas av Lord Cobrahn, en fallen druid som leder Druids of the Fang i Wailing Caverns. Den fungerar som en kanal för hans mardrömsförvridna krafter.",al={"gem of cobrahn","cobrahns pärla","vad är cobrahns pärla"}},{q="Vem vill ha Gem of Cobrahn?",a="Nara Wildmane, en tauren-druid på Elder Rise i Thunder Bluff, ber om pärlan tillsammans med tre andra för att sätta stopp för Druids of the Fang.",al={"vem behöver gem of cobrahn","lämna in cobrahns pärla","vem tar cobrahns pärla"}},{q="Hur många pärlor krävs för att slutföra uppdraget?",a="Fyra pärlor krävs: Gem of Cobrahn, Gem of Anacondra, Gem of Pythas och Gem of Serpentis. Var och en innehas av en av de fyra ormledarna i grottorna.",al={"hur många drömpärlor","fang-ledarnas pärlor","alla fang-pärlor"}},{q="Vem är Lord Cobrahn?",a="Lord Cobrahn var en gång lärjunge till Naralex. När Naralex vision förvandlades till en mardröm antog Cobrahn och flera andra druider ormens skepnad och bildade Druids of the Fang.",al={"vem är cobrahn","lord cobrahn bakgrund","cobrahn"}}},fp="14,123,27.439.0,17.357.1,27.116.0,29.138.0,47.172.0,20.172.0"}
P.entries["item:gem-of-pythas"] = {n="Gem of Pythas",s="Gem of Pythas är en av fyra fördärvade drömädelstenar som bärs av ledarna för Druids of the Fang i Wailing Caverns. Den hålls av Lord Pythas och ger näring åt mardrömmen som förvrider den underjordiska oasen och hotar The Barrens.",h="Gem of Pythas är en av fyra fördärvade drömädelstenar som bärs av ledarna för Druids of the Fang i Wailing...",kw={"the barrens","drömädelsten","druids of the fang","gem of pythas","lord pythas","nara wildmane","wailing caverns"},ang={["class:Druid"]="För Cenarion-druider är det en dyster plikt att återta ädelstenen, eftersom den står för hur Naralex innersta krets har förfallit fullständigt till ormlika fasor.",["race:Tauren"]="De förvridna ritualerna i grottorna hotar den bräckliga balansen i The Barrens, vilket gör det avgörande att återta ädelstenarna för att skydda schamanernas och druidernas hemland."},sec={{t="En behållare för mardrömmen",b="När Naralex trädde in i The Emerald Dream för att återställa det torra The Barrens förvrängdes hans ädla vision till en levande mardröm. Hans främsta följare föll med honom, kallade sig Druids of the Fang och sökte omvandla ytvärlden till en giftig djungel. Lord Pythas bär denna resonanta sten, en av fyra drömädelstenar som förankrar fördärvet i grottorna. Ädelstenen tjänar som en kanal för deras mörka plan och som bevis för druiderna i Thunder Bluff på att Pythas förvridna trans äntligen har brutits."}},faq={{q="Vad används Gem of Pythas till?",a="Ädelstenen förs till Nara Wildmane i Thunder Bluff tillsammans med ädelstenarna från Cobrahn, Anacondra och Serpentis. Tillsammans fullbordar de uppdraget att sätta stopp för de förrädiska ledarna för Druids of the Fang.",al={"gem of pythas användning","vad gör man med gem of pythas","pythas ädelstensuppdrag"}},{q="Vem bär den här ädelstenen?",a="Den hålls av Lord Pythas, en fallen Night Elf-druid som bor djupt inne i Wailing Caverns i The Barrens.",al={"vem släpper gem of pythas","pythas plats","var får man tag på gem of pythas"}},{q="Varför vill druiderna i Thunder Bluff ha ädelstenen?",a="Nara Wildmane och Cenarion-druiderna i Thunder Bluff hemsöks av fördärvet som strålar ut från Wailing Caverns. Genom att säkra ädelstenarna bevisar man att de fyra vanställda ledarna har dödats och hindrar mardrömmen från att sprida sig vidare in i The Barrens.",al={"varför vill nara ha ädelstenarna","nara wildmane pythas"}},{q="Finns det andra ädelstenar som den här?",a="Ja. Lord Pythas är en av fyra ledare. De andra, Lady Anacondra, Lord Cobrahn och Lord Serpentis, bär varsin drömädelsten djupt inne i grottan.",al={"andra drömädelstenar","fang-ädelstenar","ädelstenar i wailing caverns"}}},fx={["3d8d64d3"]={q="Vad är Gem of Pythas?",a="Gem of Pythas är en av fyra drömädelstenar som bärs av ledarna för Druids of the Fang i Wailing Caverns. Lord Pythas innehar reliken, som förkroppsligar det mörka, ormlika vansinne som korrumperade dessa en gång ädla nattalver. Den binder deras förvridna visioner av The Emerald Dream i fysisk form.",al={"gem of pythas","vad är gem of pythas","vad är den här ädelstenen"}}},fp="13,170,25.468.0,35.195.0,21.114.0,48.234.0,35.134.0"}
P.entries["item:gem-of-serpentis"] = {n="Gem of Serpentis",s="Gem of Serpentis är en drömädelsten som bärs av Lord Serpentis, en av de fyra ledarna för Druids of the Fang i Wailing Caverns. Den fungerar som en fokuserande kanal för den förvridna mardröm som omformar grottsystemet och hotar The Barrens.",h="Gem of Serpentis är en drömädelsten som bärs av Lord Serpentis, en av de fyra ledarna för Druids of the Fang...",kw={"druids of the fang","gem of serpentis","fangens ledare","lord serpentis","nara wildmane","the barrens","wailing caverns"},ang={["class:Druid"]="Drömädelstenarna som Serpentis och hans sekt bär på visar den fruktansvärda risken med att gå in i djup transgemenskap med drömmen utan vaksam andlig disciplin.",["race:Tauren"]="Att bryta Serpentis grepp om ädelstenen hjälper till att befria Thunder Bluffs schamaner och druider från de mörka syner som stör deras sömn i Mulgore."},sec={{t="Hjärtat i ormdrömmen",b="När Naralex sömn i Wailing Caverns föll offer för Emerald Nightmare förvandlades hans mest hängivna följare till de fanatiska Druids of the Fang. Lord Serpentis är en av sektens fyra ledare. Liksom de andra tre bär Serpentis en förtrollad drömädelsten som förankrar deras gemensamma vilja i den fördärvade visionen. Att återta ädelstenen bryter Serpentis grepp om grottans ekosystem och slår direkt mot ledarskapet bakom fördärvet som sprider sig över The Barrens."},{t="Bevis till Thunder Bluff",b="Taurendruiderna på Elder Rise i Thunder Bluff, särskilt Nara Wildmane, plågas av livfulla mardrömmar som orsakas av fördärvet under savannen. Att återta Gem of Serpentis tillsammans med ädelstenarna från Cobrahn, Anacondra och Pythas ger påtagliga bevis för att den avfälliga ordens ledare har fallit och lättar mardrömmens grepp om Cenarion Circle i Mulgore."}},faq={{q="Var kommer Gem of Serpentis ifrån?",a="Ädelstenen bärs av Lord Serpentis, en av de fyra ledarna för Druids of the Fang, som håller till djupt inne i Wailing Caverns vindlande vattenvägar.",al={"vem släpper gem of serpentis","var får man serpentis ädelsten","serpentis ädelstens plats"}},{q="Vad har ädelstenen för syfte?",a="Den är en av fyra fokusädelstenar som Druids of the Fang-ledarna använder för att kanalisera mardrömmen som förvrider den underjordiska oasen. Nara Wildmane i Thunder Bluff vill ha den som bevis för att Lord Serpentis har besegrats.",al={"varför behöver jag gem of serpentis","vad används gem of serpentis till"}},{q="Vem vill ha alla fyra drömädelstenarna?",a="Nara Wildmane, en druid på Elder Rise i Thunder Bluff, ber äventyrare att hämta ädelstenarna från Cobrahn, Anacondra, Pythas och Serpentis åt henne för att bryta mardrömmens grepp om regionen.",al={"vem tar emot ädelstenarna","lämna in serpentis ädelsten","lämna in till fang-ledarna"}},{q="Vem var Lord Serpentis innan han bar den här ädelstenen?",a="Han var ursprungligen en lärjunge till Naralex som gick in i grottorna för att återställa frodig växtlighet i The Barrens, men Emerald Nightmare förvrängde hans ädla ambitioner till en fanatisk önskan att omforma världen till en ormgestalt.",al={"lord serpentis berättelse","vem är serpentis"}}},fx={["58ca37b7"]={q="Vad är Gem of Serpentis?",a="Gem of Serpentis är en av fyra drömädelstenar som innehas av ledarna för Druids of the Fang i Wailing Caverns. Lord Serpentis bär den själv. Den är en symbol och ett redskap för de korrumperade druiderna, som vill förvrida The Barrens så att platsen motsvarar deras mörka visioner.",al={"gem of serpentis bakgrund","vad är serpentis ädelsten","lord serpentis ädelsten"}}},fp="16,191,29.465.0,23.330.1,42.139.0,31.209.0,30.208.0,48.207.0"}
P.entries["item:gem-of-the-serpent"] = {n="Gem of the Serpent"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Gerenzo's Mechanical Arm",s="Gerenzo's Mechanical Arm är den inopererade protesen som togs från den skurkaktige ingenjören Gerenzo Wrenchwhistle i Stonetalon Mountains. Den är ett obestridligt bevis på hans död för goblinagenter som vill röja undan konkurrensen.",h="Gerenzo's Mechanical Arm är den inopererade protesen som togs från den skurkaktige ingenjören Gerenzo...",kw={"arm","cragpool lake","gerenzo","mekanisk arm","sputtervalve","stonetalon","wrenchwhistle","ziz fizziks"},ang={["profession:Engineering"]="Armen visar hur olika de två ingenjörstraditionerna är: gnomer offrar gärna sin egen biologi för mekanisk precision, medan gobliner föredrar yttre tillägg och rå eldkraft.",["race:Gnome"]="Gerenzo är ett dystert exempel på gnomisk uppfinningsrikedom i sin ytterlighet, där mekaniska ersättningar går långt bortom vanliga medicinska proteser och blir sjuklig självförstärkning."},sec={{t="En bisarr uppfinning",b="Gerenzo Wrenchwhistle drev självmodifiering till en grotesk ytterlighet och fäste surrande kugghjul och metall direkt på sin sviktande kropp. Högt ovanför Cragpool Lake ersatte den avfälliga gnomens naturliga lemmar med avancerade maskiner. När goblintinkaren Ziz Fizziks vill röja Gerenzo ur vägen för att imponera på sina överordnade, är den här särskiljande mekaniska armen den enda trofé som är tillräckligt unik för att utgöra obestridliga bevis på ingenjörens död."},{t="Gnomisk filosofi, goblinsk kritik",b="För en goblin verkar det meningslöst att amputera en fullt fungerande arm bara för att sätta dit en mekanisk ersättare. Ziz Fizziks påpekade berömt att en riktig gobliningenjör helt enkelt skulle behålla båda sina biologiska armar och montera en mekanisk tredje arm i stället. Trots den filosofiska klyftan gör den avhuggna lemmen Sputtervalve nöjd och hjälper Ziz att ansöka om ett uppdrag i Gadgetzan eller Undermine."}},faq={{q="Var kommer Gerenzo's Mechanical Arm ifrån?",a="Den tas från Gerenzo Wrenchwhistle, som leder avverknings- och ingenjörsarbetet högt ovanför Cragpool Lake, nära vattenhjulet i Stonetalon Mountains.",al={"vem tappar gerenzo arm","gerenzo arm plats","var får man gerenzo mechanical arm"}},{q="Varför vill Ziz Fizziks ha armen?",a="Ziz behöver avgörande bevis till sin överordnade Sputtervalve för att visa att Gerenzo är död. Eftersom Gerenzo förändrade sin egen kropp så mycket går hans unika protesarm inte att förfalska eller förväxla med någon annans.",al={"varför vill ziz ha armen","lämna in armuppdrag","bevis på gerenzos död"}},{q="Varför ersatte Gerenzo sin egen arm?",a="Enligt Ziz Fizziks verkade Gerenzos kött ruttna bort. Av desperation eller genom gnomisk experimentlusta fäste Gerenzo maskiner vid kroppen och ersatte sina sviktande lemmar med mekaniska motsvarigheter.",al={"varför är gerenzo en cyborg","gerenzos ruttnande kött","varför mekanisk arm"}}},fx={["379afa91"]={q="Vad är Gerenzo's Mechanical Arm?",a="Det är en grov cybernetisk protes som ympats direkt på kroppen tillhörande Gerenzo Wrenchwhistle, en sjuklig gnomisk uppsyningsman som håller till nära vattenhjulet ovanför Cragpool Lake. I stället för att leva med naturligt kött och blod har Gerenzo förstärkt sin ruttnande kropp med urverkskugghjul och metallplattor. Denna avancerade mekaniska lem är hans mest igenkännliga kännetecken.",al={"vad är gerenzos arm","gerenzo arm föremål","gerenzos mekaniska arm"}}},fp="24,189,19.329.0,35.317.1,46.165.0,35.157.0,36.221.0"}
P.entries["item:ghost-hair-comb"] = {n="Ghost Hair Comb",s="Ghost Hair Comb är ett kusligt groomingredskap, sammanflätat med Blind Marys spöklika hårstrån. Madame Eva skickar kammen till spöket, och den blir ett redskap för en tragisk insikt innan det uppsamlade håret spinns till kuslig tråd.",h="Ghost Hair Comb är ett kusligt groomingredskap, sammanflätat med Blind Marys spöklika hårstrån.",kw={"blind mary","darkshire","duskwood","ghost hair comb","ghost hair thread","madame eva"},ang={["class:Priest"]="Marys förtvivlade reaktion på kammen speglar den kvardröjande dödliga fåfänga och djupa andliga plåga som är vanlig bland Duskwoods rastlösa döda.",["profession:Tailoring"]="De eteriska hårstråna som plockas från kammen blir ett kusligt tyg, skördat inte från får eller silkesmaskar, utan spunnet direkt ur spektral sorg."},sec={{t="Tragisk fåfänga",b="Madame Eva i Darkshire skickar kammen till spöket Blind Mary, som bor i ett ensligt, förfallet hus i utkanten av Duskwood. När kammen räcks fram ryggar spöket tillbaka i ren fasa och tvingas plötsligt inse den smärtsamma sanningen: hon är inte längre den vackra levande kvinna hon en gång var. I sin sorg och förtvivlan stöter Mary bort kammen, som blir kvar med hårstrån från hennes eget spöklika hår intrasslade i sig."},{t="Spunnen ur sorg",b="När kammen återlämnas till Madame Eva i Darkshire får håret som fastnat mellan kammens tänder ett långt mer esoteriskt syfte. Eva samlar de skira spektrala fibrerna och spinner dem till Ghost Hair Thread, ett magiskt hantverksmaterial som används för att sy ihop och binda ockulta skapelser i Duskwoods dunkla värld."}},faq={{q="Vad är Ghost Hair Comb?",a="Det är en kam som Madame Eva i Darkshire skickar till spöket Blind Mary. När Mary använder den eller kastar den åt sidan fastnar hårstrån från hennes spektrala hår i den, och Eva spinner sedan håret till Ghost Hair Thread.",al={"ghost hair comb","vad är det här för kam","evas kam"}},{q="Varför skriker Blind Mary och stöter bort kammen?",a="Kammen påminner Blind Mary om hennes förlorade dödliga skönhet. När hon får den tvingas hon möta sin sanna natur: ett skräckinjagande spektralt monster, inte den vackra kvinna hon minns från livet.",al={"varför skriker blind mary","blind marys reaktion på kammen","varför kastade mary bort kammen"}},{q="Vem vill ha tillbaka kammen?",a="Madame Eva, spåkvinnan och magikern som bor i staden Darkshire, ber att kammen ska lämnas tillbaka till henne så att hon kan ta till vara det fastnade spökhåret.",al={"vem vill ha kammen","var ska kammen lämnas","till vem ska kammen lämnas tillbaka"}},{q="Vad används spökhåret till?",a="Madame Eva spinner de spöklika hårstråna som samlats från kammen till Ghost Hair Thread, en ovanlig reagens som behövs för ockulta ritualer och hantverk i Duskwood.",al={"vad används spökhår till","vad är ghost hair thread","vad används ghost hair thread till"}}},fp="15,113,15.349.0,16.279.1,28.162.0,47.204.0,28.134.0,32.135.0"}
P.entries["item:ghost-hair-thread"] = {n="Ghost Hair Thread",s="Ghost Hair Thread är ett sällsynt, övernaturligt material som Madame Eva spinner i Darkshire. Det sägs vara laddat med starka ockulta krafter som kan binda andliga energier och till och med sy in liv i livlösa ting. Eremiten Abercrombie ber om det för att skydda sin förfallna hydda mot rastlösa spöken.",h="Ghost Hair Thread är ett sällsynt, övernaturligt material som Madame Eva spinner i Darkshire.",kw={"abercrombie","darkshire","duskwood","ghost hair thread","madame eva","raven hill","andar"},ang={["class:Warlock"]="Trådens förmåga att binda andliga väsen och ge liv åt livlös materia påminner om de mörka konsterna att manipulera själar och binda konstrukter.",["profession:Tailoring"]="Medan vanliga skräddare arbetar med ull, siden och magväv visar Madame Evas spöklika tråd att tyg kan spinnas direkt ur övernaturliga essenser och bära på förtrollningar."},sec={{t="Spunnet ur andevärlden",b="Ghost Hair Thread, som spinns av spåkvinnan Madame Eva i Darkshire, är mycket mer än vanligt material för sömnad. Enligt Eva har den spektrala tråden många ockulta egenskaper, från att binda illvilliga andar till att sy in liv i livlösa föremål. Dess eteriska natur gör den värdefull för ritualer och skyddsbesvärjelser i Duskwoods förbannade rike."},{t="Abercrombies skydd",b="Eremiten Abercrombie, som håller sig för sig själv i en fallfärdig hydda strax norr om Raven Hill Cemetery, ber resande att hämta tråden från Darkshire. Han säger att han desperat behöver spänna tråden över fönstren och dörrkarmen för att hindra de vandrande odöda från kyrkogården från att ta sig in i hans hem. Men med tanke på trådens märkliga förmåga att sy liv i livlösa ting förblir dess egentliga syfte ett oroande mysterium."}},faq={{q="Vad är Ghost Hair Thread?",a="Det är ett magiskt hantverksmaterial som Madame Eva spinner i Darkshire. Det har särskilda ockulta egenskaper och kan binda andar eller sy liv i livlösa ting.",al={"spökhår","vad är ghost hair thread","spöktråd"}},{q="Varför vill Abercrombie ha Ghost Hair Thread?",a="Abercrombie säger att han behöver tråden för att kanta sina fönster och dörröppning och skapa en skyddande barriär mot de rastlösa andar som strövar utanför nära Raven Hill Cemetery.",al={"abercrombies tråd","varför abercrombie vill ha tråden","abercrombies skydd"}},{q="Vem tillverkar tråden?",a="Madame Eva, Darkshires spåkvinna och sierska, tillverkar och tillhandahåller tråden på begäran.",al={"vem spinner ghost hair thread","madame evas tråd"}},{q="Kan spelare använda tråden för sömnad?",a="Nej. Trots sitt namn och sina magiska egenskaper är den ett särskilt föremål för ett uppdrag, avsett enbart att lämnas till Abercrombie. Den kan inte användas i vanliga hantverksrecept.",al={"ghost hair thread för sömnad","kan jag hantverka med ghost hair thread"}}},fp="17,214,24.220.0,18.290.1,26.120.0,44.129.0,21.86.0,41.96.0"}
P.entries["item:ghost-o-plasm"] = {n="Ghost-o-Plasm",s="Ghost-o-Plasm är spöklik energi som samlas in från Magrami Spectres i Desolace. Hornizz Brimbuzzle hoppas kunna sälja den till Magram-centaurerna.",h="Ghost-o-Plasm är spöklik energi som samlas in från Magrami Spectres i Desolace.",kw={"spökenergi","ghost-o-plasm","ghostoplasm","hornizz brimbuzzle","magnet","magram-centaurer","magrumi-spöken","valley of bones"},ang={["faction:Horde"]="Som medlem i Horde hjälper du Hornizz att förhandla med Magram-centaurerna genom en märklig handel med spökenergi.",["race:Gnome"]="Som gnom kanske du känner igen Hornizz spökmagneter som finurliga apparater, men hans plan hänger på vad Magram-centaurerna är villiga att betala."},sec={{t="Insamlad i dalen",b="Mellan de två väldiga skeletten som kallas Dead Goliaths lockar en låda med spökmagneter Magrami Spectres från Valley of Bones. Det är deras Ghost-o-Plasm som Hornizz Brimbuzzle vill åt. Han hoppas att Magram-centaurerna betalar bra för den, men han måste fortfarande övertyga dem om vad det märkliga ämnet är."}},faq={{q="Vad är Ghost-o-Plasm?",a="Ghost-o-Plasm är spöklik energi från Magrami Spectres i Desolace.",al={"ghost-o-plasm","spökgrejer","vad är det här för slem"}},{q="Var hittar jag Ghost-o-Plasm?",a="Magrami Spectres i Valley of Bones ger Ghost-o-Plasm när en låda med spökmagneter lockar dit dem.",al={"var finns spökplasma","skaffa ghost-o-plasm","spökgrejernas plats"}},{q="Vem vill ha Ghost-o-Plasm?",a="Hornizz Brimbuzzle vill ha Ghost-o-Plasm och hoppas kunna sälja den till Magram-centaurerna.",al={"vem behöver spökplasma","hornizz grejer","sälja spökenergi"}},{q="Varför vill Hornizz ha den?",a="Hornizz tror att Magram-centaurerna betalar bra för infångad spökenergi.",al={"varför hornizz vill ha den","varför samla spökgrejer","centaurernas spökenergi"}}},fp="13,135,22.304.0,22.72.0,30.99.0,24.81.0,25.77.0"}
P.entries["item:ghoul-fang"] = {n="Ghoul Fang",s="Ghoul Fangs är ohyggliga troféer som tas från de odöda som stryker omkring i Duskwoods fördärvade dungar och på dess kyrkogårdar. I Darkshire använder sierskan Madame Eva dem som viktiga ingredienser när hon tillverkar skyddande talismaner åt resenärer som möter det annalkande mörkret.",h="Ghoul Fangs är ohyggliga troféer som tas från de odöda som stryker omkring i Duskwoods fördärvade dungar och...",kw={"darkshire","duskwood","ghoul fang","ghouls","madame eva","totem of infliction","odöda"},ang={["faction:Alliance"]="För alliansens äventyrare som hjälper den hårt ansatta staden Darkshire blir dessa huggtänder ett sätt att förvandla Duskwoods fasor till redskap för överlevnad mot den annalkande plåga som liknar Scourge."},sec={{t="Troféer från The Restless Dead",b="Duskwoods skuggiga skog kryllar av glupska odöda, från köttätare som lurar nära gravarna till förruttnade lik som strövar omkring i skogen. Att ta en huggtand från dessa monstruösa varelser är både ett fasansfullt arbete och ett bevis på att man överlevt de glupska döda som hotar Darkshires gränser."},{t="Ockulta ingredienser",b="Madame Eva, Darkshires siare och mystiker, ser fruktansvärda omen virvla kring resenärer som vågar ta sig genom Duskwood. Hon binder den slumrande nekrotiska essensen i ghoulfangar samman med skelettfingrar och spindelgift för att förtrolla Totem of Infliction och förvandla skogens mörka krafter till en skyddande amulett mot våldsamma angrepp."}},faq={{q="Var hittar man Ghoul Fangs?",a="De samlas in från olika sorters ghouls i Duskwood, däribland Plague Spreaders, Brain Eaters, Bone Chewers, Fetid Corpses, Rotted Ones och Flesh Eaters, som hemsöker kyrkogårdar och ensliga stigar.",al={"var faller ghoul fangs","vem släpper ghoul fangs","ghoul fang plats"}},{q="Vem vill ha Ghoul Fangs?",a="Madame Eva, mystikern som bor i Darkshire, behöver dem som en del av en ritual för att skapa en skyddande amulett kallad Totem of Infliction.",al={"vem behöver ghoul fangs","lämna in ghoul fang","madame evas uppdrag"}},{q="Varför behöver Madame Eva dem?",a="Eva känner att faror hotar resenärerna och använder huggtänderna tillsammans med skelettfingrar och spindelgift för att förtrolla en skyddande totem som straffar dem som angriper bäraren.",al={"varför ghoul fangs","material till totem of infliction","vad gör madame eva med huggtänder"}}},fx={["7c703fef"]={q="Vad är en Ghoul Fang?",a="En Ghoul Fang är en vass tand som brutits loss från gapet på de odöda gastar som hemsöker Duskwood. Huggtänderna är besmittade av nekromantisk förruttnelse och hunger efter kött, och bär fortfarande spår av den mörka magi som ger de odöda liv. Därför är de kraftfulla ingredienser i skyddande amuletter och ockulta ritualer.",al={"vad är ghoul fang","ghoul fang bakgrund","om ghoul fang"}},["87f3f6fc"]={q="Varifrån kommer en Ghoul Fang?",a="Dessa huggtänder kommer från olika odöda gastar som strövar omkring i Duskwoods skuggor, till exempel Plague Spreaders, Brain Eaters, Bone Chewers och Flesh Eaters. De tillverkas inte för hand, utan samlas direkt från käftarna på de vandrande döda.",al={"ghoul fang ursprung","varifrån kommer ghoul fangs","vem släpper ghoul fangs"}}},fp="10,182,29.255.0,15.302.0,31.170.0,22.98.0,30.189.0"}
P.entries["item:ghoul-rib"] = {n="Ghoul Rib",s="Ghoul Rib samlas in från de odöda som stryker omkring i Duskwoods hemsökta dungar och gravplatser. Eremiten Abercrombie påstår att han behöver dem som material till en grotesk avbildning som ska hålla de människoätande fasorna nära hans skjul på avstånd.",h="Ghoul Rib samlas in från de odöda som stryker omkring i Duskwoods hemsökta dungar och gravplatser.",kw={"abercrombie","beggar's haunt","bone chewer","darkshire","duskwood","flesh eater","ghoul rib","gastavbildning","odöda"},ang={["class:Paladin"]="Att hantera de rastlösa dödas skändade ben är motbjudande arbete, men att hjälpa en isolerad eremit mot glupska vidunder går hand i hand med att skydda de levande från Duskwoods fasor.",["class:Priest"]="Den förvridna återuppväckelse som håller dessa ben samman speglar den djupa skugga som fallit över Duskwood och förvandlar stupade bybor till glupska asätare."},sec={{t="Ett makabert skydd",b="Duskwoods förbannade skog kryllar av våldsamma odöda, däribland glupska gastar som Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones och Plague Spreaders. Abercrombie, en excentrisk enstöring som bor isolerad i ett skjul norr om Raven Hill Cemetery, ber förbipasserande resenärer om dessa kraftiga, förruttnade ben. Han påstår att det gör honom sårbar att bo utanför Night Watchs beskydd i Darkshire, och att en skrämmande avbildning av gastrevben ska fungera som en fågelskrämma och skrämma bort kringströvande flockar av de döda."},{t="Misstankar kring skjulet",b="Att samla delar från dödade odöda är vanligt nog för att överleva i fientliga områden, men Abercrombies särskilda fascination för gastars anatomi väcker frågor. I stället för att söka skydd bakom Darkshires palissader eller förlita sig på vigda skyddsmärken envisas eremiten med att samla rått nekromantiskt inälvsmaterial för att förstärka sitt avskilda hem."}},faq={{q="Vilka varelser bär på Ghoul Rib?",a="De kan samlas in från olika sorters gastar i Duskwood, däribland Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones och Plague Spreaders. Dessa monster hemsöker gamla gravgårdar, vägkantsruiner och övergivna gårdar runt om i skogen.",al={"var får man ghoul rib","vilka gastar har revben","källor till ghoul rib"}},{q="Varför vill Abercrombie ha benen?",a="Abercrombie påstår att han bor för långt från Darkshire för att kunna förlita sig på Night Watchs beskydd. Han ber om revbenen för att bygga en enkel fågelskrämma eller avbildning som ska avskräcka kringströvande odöda från att banka på hans väggar.",al={"varför behöver abercrombie revben","syftet med gastavbildningen","vad gör abercrombie med revbenen"}},{q="Håller fågelskrämmor verkligen gastar borta?",a="Odöda saknar i allmänhet rädsla och drivs helt av tanklös hunger eller mörkt nekromantiskt tvång. Tanken att tanklösa gastar skulle fly från en fågelskrämma gjord av ben är ovanlig, men Abercrombie insisterar på att den ska hålla hans hem tryggt.",al={"fungerar avbildningen","kan avbildningar skrämma odöda","är gastar rädda för fågelskrämmor"}},{q="Var ligger Abercrombies skjul?",a="Abercrombie bor i ett förfallet skjul i västra Duskwood, strax norr om Raven Hill Cemetery.",al={"abercrombies plats","var finns eremiten","var lämnar man in ghoul rib"}}},fx={["3e8ffb18"]={q="Vad är en Ghoul Rib?",a="En Ghoul Rib är precis vad det låter som: ett ben från de ruttnade, återupplivade odöda som stryker omkring i Duskwood. Revbenen tas från odjur som Flesh Eaters, Brain Eaters och Bone Chewers. Dessa kvarlevor bär fortfarande spår av den vidriga magi som ger de vandrande döda liv i denna hemsökta skog.",al={"ghoul rib information","vad är ghoul ribs","ghoul ribs föremål"}},f2829c95={q="Varifrån kommer Ghoul Ribs?",a="Dessa revben kommer direkt från de olika gastar som hemsöker Duskwoods dystra vägar och gravhögar. De är naturliga skelettdelar, inte tillverkade reliker, och tas från odöda vidunder som Plague Spreaders och Rotted Ones. De strövar långt bortom den relativa tryggheten i Darkshire.",al={"ghoul rib källa","var får man ghoul ribs","vem skapade ghoul ribs"}}},fp="9,161,15.373.0,27.237.1,32.238.0,38.200.0,40.163.0,37.84.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Giant Crocolisk Skin",s="Giant Crocolisk Skin är tjocka hudar från de enorma kräldjur som hör hemma i Wetlands träskmarker. De är eftertraktade av Menethil Harbors hantverkare för läderarbete, men jakten är farlig och har lemlästat mer än en oförsiktig jägare.",h="Giant Crocolisk Skin är tjocka hudar från de enorma kräldjur som hör hemma i Wetlands träskmarker.",kw={"lärlingens uppgifter","crocolisk","giant crocolisk skin","james halloran","menethil harbor","wetlands"},ang={["class:Hunter"]="Att spåra giant crocolisks längs den dimmiga kusten prövar jägarens förmåga att följa vattenlevande bestar och undvika att dras ner under träskvattnet."},sec={{t="En farlig handel",b="Träsken och vattenvägarna i Wetlands är hem åt enorma crocolisks, vars hudar är så täta att de står emot träskens fukt och röta. I Menethil Harbor är hantverkare som James Halloran beroende av jämna leveranser av skinn för att tillverka slitstarka lädervaror. Men att ta huden från en fullvuxen giant crocolisk kräver att man trotsar djupt vatten och överlistar våldsamma träskrovdjur, så varje fällt byte är vunnet med möda."},{t="Lärlingens dårskap",b="Att skörda de tjocka hudarna var ursprungligen den unge lärlingens uppgift hos Halloran. Pojken saknade stridsförmågan att fälla fullvuxna träskbestar och överfölls längs den norra kusten. Han blev svårt sönderriven av giant crocolisks och vårdas nu av en lokal barnmorska, som säger att han kanske klarar sig. Attacken tvingade Halloran att anlita erfarna äventyrare för att jaga rovdjuren och säkra skinnen som behövs."}},faq={{q="Vad används Giant Crocolisk Skin till?",a="James Halloran, en köpman i Menethil Harbor, skaffar skinnen och uppskattar de tjocka hudarna när han tillverkar tåliga lädervaror som klarar träskmarkernas fuktiga klimat.",al={"användning av crocolisk skin","varför samla giant crocolisk skin","hallorans användning av skinnen"}},{q="Var finns crocolisks som ger de här skinnen?",a="Giant Wetlands Crocolisks stryker längs kusten och i träskvattnen norr om Menethil Harbor, i de grunda vattnen bortom de lokala murloc-bosättningarna.",al={"var giant crocolisks finns","var hitta giant crocolisks","crocolisk på wetlands kust"}},{q="Vad hände med Hallorans lärling?",a="Halloran skickade ut sin lärling ensam i träsket för att skörda skinn. Giant crocolisks anföll lärlingen och slet honom så illa att han nu vårdas av en barnmorska i Menethil, som säger att han kanske klarar sig.",al={"lärling skadad","hallorans lärling","vem förlorade ett ben"}},{q="Hur skiljer sig de här skinnen från skinn från unga crocolisks?",a="Unga crocolisks ger tunnare och smidigare skinn. Fullvuxna giant crocolisks ger betydligt tjockare och tåligare hudar, men att döda en kräver stor stridsvana.",al={"skinn från unga och jättelika crocolisks","skillnad på crocoliskläder"}}},fx={["406c8fec"]={q="Vad är Giant Crocolisk Skin?",a="Det är ett tjockt och slitstarkt skinn från de jättelika krokoliskerna som strövar omkring i Wetlands träsk. Garvare och hantverkare värdesätter skinnet för dess styrka och storlek. Det är inte lätt att flå ett sådant skinn, eftersom dessa rovdjur hör till de mest våldsamma bestar som jagar i vattendragen.",al={"vad är giant crocolisk skin","jättelikt krokolisk-skinn","information om crocolisk skin"}},bd43ba97={q="Varifrån kommer Giant Crocolisk Skin, och vem har tillverkat det?",a="Skinnet tas på naturlig väg från jättelika krokolisker i Wetlands träsk, norrut längs kusten bortom murlocernas hyddor. Det tillverkas inte av någon hantverkare, utan måste flås direkt från kadavren efter dessa väldiga träskbestar.",al={"vem gjorde giant crocolisk skin","varifrån kommer giant crocolisk skins","källa till giant crocolisk skin"}},c37602c5={q="Varför vill James Halloran ha Giant Crocolisk Skins?",a="James Halloran är en hantverkare i Menethil Harbor och behöver skinnen i sitt yrke. Först skickade han sin unge lärling för att samla in dem, men pojken blev svårt sargad av de glupska bestarna och lämnades i en barnmorskas vård. Då vände sig Halloran till erfarna äventyrare för att få tag på materialet och hämnas sin skyddsling.",al={"varför vill halloran ha skinn","vem vill ha giant crocolisk skins","varför behövs giant crocolisk skins"}}},fp="20,143,17.317.0,22.358.1,40.145.0,56.154.0,39.169.0,52.154.0"}
P.entries["item:gloom-weed"] = {n="Gloom Weed",s="Gloom Weed är en sjuklig växt som hör hemma i Tirisfal Glades förgiftade jord och ofta växer på fälten mellan Deathknell och Brill. Den är mest känd som fel växt som Gordo samlar in. Gordo är en tungfotad styggelse från de Forsaken som misstar den för alkemireagensen doom weed.",h="Gloom Weed är en sjuklig växt som hör hemma i Tirisfal Glades förgiftade jord och ofta växer på fälten mellan...",kw={"styggelse","brill","doom weed","gloom weed","gordo","master holland","tirisfal glades"},ang={["profession:Herbalism"]="Örtkunniga kan känna av växten med Find Herbs, vilket gör den mycket lättare att upptäcka bland Tirisfals skuggiga snår.",["race:Undead"]="För nya Forsaken som lämnar Deathknell blir hämtningen av Gloom Weed en snabb lektion i bristerna hos styggelsearbetskraft och Undercitys alkemisters fräna temperament."},sec={{t="En felaktig skörd",b="Gloom Weed spirar bland skuggorna och förruttnelsen i Tirisfal Glades och trivs i den obrukade jorden väster om Brill och öster om Solliden Farmstead. Trots sitt dystra namn är växten relativt harmlös och saknar den kraftiga alkemiska effekt som Royal Apothecary Society uppskattar. Dess främsta ryktbarhet kommer från styggelsen Gordo, som strövar längs vägen och försöker dra upp ogräs med sina stora, klumpiga händer. Gordo har missförstått sin herres order och samlar därför ständigt Gloom Weed. Han ber lättlurade resenärer bära knippen av den till Master Holland på Brills kyrkogård, till alkemistens stora förtret."}},faq={{q="Vad används Gloom Weed till?",a="I praktiken inte till något som Forsaken-alkemister har nytta av. Den samlas enbart in för att styggelsen Gordo misstar den för örten doom weed, som hans herre faktiskt bad om.",al={"gloom weed användning","vad gör gloom weed","vem behöver gloom weed"}},{q="Var växer Gloom Weed?",a="Den växer utspridd över Tirisfal Glades fält mellan Brill och Deathknell, särskilt längs vägen och på ängarna öster om Solliden Farmstead.",al={"var hittar man gloom weed","gloom weed plats","gloom weed växtplatser"}},{q="Vem är Gordo och varför plockar han den?",a="Gordo är en styggelse som Master Holland skickat ut för att samla reagenser. Hans hopsydda händer är klumpiga och hans sinne enkelt, så han vandrar längs vägarna och drar upp fel växter medan han ber förbipasserande om hjälp.",al={"vem är gordo","varför plockar gordo ogräs","gordo styggelse"}},{q="Vad var det Master Holland egentligen ville ha?",a="Master Holland behöver doom weed till sina experiment på Brills kyrkogård. När han får Gloom Weed fnyser han åt misstaget och ber resenärer samla in det han verkligen behöver.",al={"master holland ogräs","vad behöver holland","doom weed eller gloom weed"}}},fx={bc1ac336={q="Vad är Gloom Weed?",a="Gloom Weed är en vanlig, sjukligt utseende vild växt som spirar i den förbannade jorden i Tirisfal Glades. Den finns främst längs vägarna och på öppna fält mellan Brill och Deathknell. Den har ingen magisk kraft eller värdefulla alkemiska egenskaper. I själva verket är den inte mycket mer än ett vanligt vägkantsogräs, Tirisfal Glades motsvarighet till en prästkrage, som råkar frodas trots att landsbygden är förhärjad.",al={"vad är gloom weed","gloom weed bakgrund","gloom weed växt"}},defb981c={q="Varför vill någon ha Gloom Weed?",a="I stort sett ingen vill egentligen ha Gloom Weed. Den enda anledningen till att någon samlar in den är att Gordo, en trögfattad styggelse som vandrar omkring på fälten nära Brill, missförstod sina instruktioner fullständigt. Hans mästare, Junior Apothecary Holland, skickade ut honom för att skörda värdefull doom weed till De övergivnas experiment. Men Gordos tröga hjärna blandade ihop namnen, så ovetande resenärer fick i stället plocka värdelös gloom weed.",al={"vem vill ha gloom weed","varför samla gloom weed","varför plocka gloom weed"}}},fp="10,118,18.441.0,28.137.0,27.131.0,38.172.0,38.180.0"}
P.entries["item:glowing-ember"] = {n="Glowing Ember",s="Vid Shrine of Eternal Flame tänder en Glowing Ember offerkaret inför en schamans prövning. Den kommer från en Minor Manifestation of Fire på Durotars klippor.",h="Vid Shrine of Eternal Flame tänder en Glowing Ember offerkaret inför en schamans prövning.",kw={"call of fire","fire sapta","glowing ember","mindre manifestation av eld","shrine of eternal flame","telf joolam","torch of the dormant flame"},ang={["class:Shaman"]="Som schaman prövar du din beslutsamhet mot levande eld i denna övergångsrit innan du börjar befalla din totem."},sec={{t="Eldens kärna",b="En blivande schaman dricker Fire Sapta för att se de eldiga andarna på höjden nära Telf Joolam. Där möter den invigde en Minor Manifestation of Fire. När elementaren faller återstår bara en glödande kolbit av dess fysiska gestalt. Rå elementär hetta pulserar fortfarande i den och bär på den levande gnista som behövs för att väcka det heliga offerkaret vid Shrine of Eternal Flame."},{t="Tända facklan",b="När Glowing Ember läggs i det kalla karet på bergets offerkar flammar en vitglödande eld upp. Offerkarens låga låter den invigde tända Torch of the Dormant Flame. Facklan binder eldens vilda väsen i ett kärl som den invigde kan bära nerför berget som bevis på sin makt över elementen."}},faq={{q="Var kommer Glowing Ember ifrån?",a="Du hämtar glöden från en besegrad Minor Manifestation of Fire på toppen ovanför Shrine of Eternal Flame i Durotar.",al={"hur får man tag på glowing ember","glowing ember byte","var hittar man glowing ember"}},{q="Vad används glöden till?",a="Du lägger glöden i metallofferkarret vid Shrine of Eternal Flame. Dess intensiva, rytmiska låga tänder den ceremoniella Torch of the Dormant Flame.",al={"vad gör glowing ember","användning av glowing ember","glöd i eldfatet"}},{q="Varför behöver schamaner Fire Sapta för att få tag på den?",a="De elementära andarna på bergets topp är osynliga för vanliga dödliga. När du dricker Fire Sapta stäms dina sinnen in på elementarplanet och avslöjar Minor Manifestation of Fire, så att du kan utmana den.",al={"varför behövs sapta","kan inte se eldelementaren","fire sapta och glöden"}},{q="Vem ber schamaner söka efter den här glöden?",a="Telf Joolam, en eremit bland Durotars klippor, brygger Fire Sapta och vägleder schamanlärlingar genom prövningen att besegra eldanden.",al={"vem ger uppdraget","telf joolam och glöden","uppdragsgivare för call of fire"}}},fx={["8d7073a8"]={q="Vad är Glowing Ember?",a="Glowing Ember är den glödande resten som samlas in från en Minor Manifestation of Fire på toppen med utsikt över Durotar. När anden har besegrats lämnar den efter sig en koncentrerad bit levande eld. Den har tillräckligt med inneboende elementarkraft för att tända de slumrande lågorna på bergets heliga altare.",al={"vad är glowing ember","glowing ember bakgrund","glowing ember föremål"}}},fp="13,157,17.352.0,18.308.1,39.125.0,27.150.0,49.206.0,39.144.0"}
P.entries["item:glowing-fruit"] = {n="Glowing Fruit",s="Glowing Fruit är ett exotiskt, självlysande exemplar som växer bland märkliga blad på Teldrassils grenar. Dess onaturliga sken och märkliga samspel med Världsträdets jord gör det till föremål för brådskande botaniska studier bland naturkunniga.",h="Glowing Fruit är ett exotiskt, självlysande exemplar som växer bland märkliga blad på Teldrassils grenar.",kw={"botanik","denalan","glowing fruit","lake al'ameth","växt","teldrassil","timberlings"},ang={["class:Druid"]="För druider som är lyhörda för Teldrassils bräckliga balans utgör främmande växtlighet som reagerar oberäkneligt med jorden ett möjligt hot mot det växande Världsträdet.",["profession:Herbalism"]="Örtkunniga lägger genast märke till att fruktens märkliga självlysande sken tyder på ett exotiskt och kraftfullt samspel mellan främmande frösorter och förtrollad jord."},sec={{t="Ett märkligt exemplar",b="Den här stora, runda frukten upptäcktes hängande under ovanliga blad på Teldrassil och strålar av ett omisskännligt ljus. Botanikern Denalan vid Lake Al'Ameth känner igen den som främmande för Världsträdet och tror att dess frön kom från avlägsna länder på andra sidan havet. Oavsett ursprung reagerar frukten märkligt på Teldrassils rika, förtrollade jord och visar hur sårbar den unga världsträdskronan är för främmande och oförutsägbar växtlighet."}},faq={{q="Vad är Glowing Fruit?",a="Det är en exotisk, rund frukt som upptäcktes växa under ovanliga blad på Teldrassil. Den avger ett eteriskt sken och verkar ha reagerat ovanligt med den lokala jorden.",al={"glödande frukt teldrassil","vad är det här för frukt","uppdrag med märklig frukt"}},{q="Var kommer frukten ifrån?",a="Enligt naturkännaren Denalan hör frukten inte hemma på Teldrassil. Han misstänker att fröna drev eller fördes hit från långt bortom havet, kanske från Azeroths Eastern Kingdoms, innan de slog rot i jorden.",al={"fruktens ursprung","varifrån kom fröna","hör den hemma här"}},{q="Vem vill undersöka Glowing Fruit?",a="Denalan, en forskare av Night Elf-folket som är stationerad vid Lake Al'Ameth, studerar Teldrassils grenar och ekosystem. Han är särskilt intresserad av främmande växtliv som har reagerat med Världsträdets jord.",al={"vem behöver frukten","var lämnar jag glödande frukt","denalans frukt"}}},fp="13,151,18.318.0,26.136.0,31.143.0,39.201.0"}
P.entries["item:glowing-gem"] = {n="Glowing Gem",s="Glowing Gem är en förtrollad sten som hämtats från murloclägren längs Ashenvales vatten. Den söktes först av den fallne spejaren Teronis och är en viktig del som behövs för att återskapa den magiska stav som Dartol skapade.",h="Glowing Gem är en förtrollad sten som hämtats från murloclägren längs Ashenvales vatten.",kw={"astranaar","reningsstav","dartol","glowing gem","iris lake","murloc","raene wolfrunner","shael'dryn","teronis"},ang={["class:Druid"]="Druiderna är intresserade av Teronis forskning om den spridande korruptionen och reliken som han hoppades kunna återställa.",["race:NightElf"]="Att återfinna ädelstenen och fullfölja Teronis uppdrag hjälper vaktposterna att hedra sin fallne spejare och skydda Ashenvale från den spridande korruptionen."},sec={{t="En förlorad relik från Dartol",b="Glowing Gem hittades hos de aggressiva murlocerna som bor nära Lake Falathim och är laddad med vilande magisk energi. Den unge Night Elf Teronis gav sig av från Astranaar för att spåra upp den och försöka hitta ett verktyg som kunde driva tillbaka korruptionen som spred sig genom Ashenvales skogar. Teronis mötte en för tidig död vid sjön, men stenen förblev oskadd bland strandens asätare."},{t="Att återställa staven",b="När stenen har återfunnits tillsammans med Teronis dagbok skickar vaktposternas ledare Raene Wolfrunner dess bärare nordost till Shael'dryn, en dryad som vakar vid en närbelägen månkällare. Dryaden besitter den urgamla kunskap som krävs för att binda samman Glowing Gem med stavens andra saknade delar, som Dartol skapade, så att den fallne spejarens arbete inte var förgäves."}},faq={{q="Varifrån kommer Glowing Gem?",a="Ädelstenen bärs av murlocer som stryker längs stränderna och det grunda vattnet kring helgedomen vid Lake Falathim i västra Ashenvale, där Teronis föll.",al={"glowing gem plats","vem släpper glowing gem","var får man glowing gem"}},{q="Varför letade Teronis efter den här ädelstenen?",a="Teronis undersökte sätt att rena den växande orenheten i Ashenvale. Enligt hans forskning är just den här ädelstenen en av de viktigaste delarna som behövs för att bygga upp en magisk stav som Dartol en gång skapade.",al={"teronis uppdrag","varför teronis ville ha ädelstenen","ädelstenens syfte"}},{q="Vem ska jag ta Glowing Gem till?",a="Visa stenen och Teronis dagbok för Raene Wolfrunner i Astranaar. Ta sedan Glowing Gem nordost till dryaden Shael'dryn vid månkällan öster om Iris Lake.",al={"vem behöver glowing gem","lämna in glowing gem","vad gör man med ädelstenen"}},{q="Vad är Dartols stav?",a="Det är ett magiskt redskap som Dartol skapade. Dess delar spreds över skogen, och Glowing Gem behövs för att återskapa det.",al={"dartols stav","vad skapade dartol"}}},fx={["464fc9d6"]={q="Vad är Glowing Gem?",a="Glowing Gem är en förtrollad sten som behövs för att återskapa staven som Dartol tillverkade. Teronis sökte efter den när han undersökte korruptionen i Ashenvale, och Raene Wolfrunner leder sökandet efter stavens återstående delar.",al={"vad är glowing gem","berätta om glowing gem","glowing gem bakgrund"}}},fp="11,131,22.265.0,17.285.1,37.142.0,37.167.0,37.166.0,26.137.0"}
P.entries["item:glowing-soul-gem"] = {n="Glowing Soul Gem",s="En Glowing Soul Gem är en mörk ritualartefakt som bärs av agenter från Cult of the Dark Strand i norra Ashenvale. Stenen är fylld med skuggmagi och fångar en ovetande persons ande för att ge näring åt kultens illvilliga verksamhet.",h="En Glowing Soul Gem är en mörk ritualartefakt som bärs av agenter från Cult of the Dark Strand i norra...",kw={"althalaxx","cult of the dark strand","dark strand","delgren the purifier","glowing soul gem","maestra's post","ordil'aran","soul gem"},ang={["class:Priest"]="Präster som betraktar själstenen kan känna den instängda andens plågor och förstår att artefakten måste renas snarast, så att själen kan finna ro.",["class:Warlock"]="Ingen förstår konsten att fånga andar i själstenar bättre än häxmästare. De ser Dark Strands ädelsten som en grövre, nekromantisk variant av andemanipulation."},sec={{t="Ett kärl för mörk magi",b="Nordost om Maestra's Post, i de skuggiga ruinerna av Ordil'Aran, utövar medlemmar av Cult of the Dark Strand mörk magi under sina skuggmästares vakande blick. Bland dem bär agenter Glowing Soul Gems, kärl som förtrollats för att fånga och plåga de dödas själar. Stenarna är mer än bara prydnadssaker; de fungerar som kanaler för magisk energi och binder andar till kultens mörka syften."},{t="Ordil'Arans hemligheter",b="Delgren the Purifier vid Maestra's Post försöker slå ut Dark Strands inflytande i norra Kalimdor och undersöker därför dessa artefakter. Den som tyder förtrollningarna i en Glowing Soul Gem upptäcker inte bara mörka magiska formler, utan också en själ som ropar inifrån ädelstenen. Det avslöjar de ondskefulla experimenten som knyter kultisterna i Ashenvale till deras fränder vid Tower of Althalaxx."}},faq={{q="Vad är en Glowing Soul Gem?",a="Det är en förtrollad själsten som används av Cult of the Dark Strand. Fylld med skuggmagi fångar den andar och utvinner deras essens för att ge näring åt kultens avskyvärda magi.",al={"vad är soul gem","soul gem darkshore","glowing soul gem bakgrund"}},{q="Var kommer den här själstenen ifrån?",a="Den bärs av medlemmar i Cult of the Dark Strand, däribland kultister, lönnmördare, hantlangare och adepter som verkar från ruinerna av Ordil'Aran i norra Ashenvale.",al={"vem släpper soul gem","glowing soul gem plats","ordil'aran-ädelsten"}},{q="Vem vill ha den här själstenen, och varför?",a="Delgren the Purifier, som är stationerad vid Maestra's Post, vill ha ädelstenen. Han tror att om han tyder dess förtrollningar kan han avslöja kultens hemliga kraftkälla och ta reda på vad de planerar.",al={"delgren soul gem","varför vill delgren ha soul gem","maestra's post soul gem"}},{q="Vad händer när själstenen tyds?",a="När förtrollningarna på ädelstenen löses upp frigörs spöket som fångats därinne. Den plågade själen blir fri, och Dark Strands förvridna metoder avslöjas.",al={"vad finns i soul gem","spöke i soul gem"}}},fp="16,179,24.294.0,25.318.1,29.167.0,35.167.0,32.161.0,45.143.1"}
P.entries["item:glutton-shackle"] = {n="Glutton Shackle",s="Glutton Shackles är förtrollade bojor som bärs av Moonrage Glutton-worgen i Silverpine Forest. De smiddes av den galne ärkemagikern Arugal, och banden kanaliserar magi som stärker hans annars bristfälliga trolldom och håller hans förbannade vargskapelser vid liv.",h="Glutton Shackles är förtrollade bojor som bärs av Moonrage Glutton-worgen i Silverpine Forest.",kw={"arugal","dalar dawnweaver","glutton shackle","moonrage glutton","the sepulcher","silverpine","worgen"},ang={["class:Mage"]="Magiker lär uppskatta Dalar Dawnweavers bitska kritik av Arugals usla teknik, eftersom det ses som ett tecken på medioker trollkonst att använda fysiska, förtrollade kryckor för att stabilisera enkla transmutations- och besvärjelser för att kalla fram varelser.",["race:Undead"]="Agenter från Forsaken ser insamlingen av bojorna som ett viktigt steg mot att neutralisera worgenhotet som tränger ända fram till The Sepulchers gränser."},sec={{t="En krycka för svag trolldom",b="För de tränade magikerna bland Forsaken är de vilda worgen som hemsöker Silverpine inte bara bestialiska vidunder – de vittnar om grov magisk inkompetens. Dalar Dawnweaver, en skicklig arkanist stationerad vid The Sepulcher, känner inget annat än förakt för ärkemagikern Arugal och anser honom vara en oduglig klåpare, ovärdig Kirin Tor. Dawnweaver upptäckte att Arugal förlitade sig på förtrollade reliker för att kompensera för sina bräckliga besvärjelser. Glutton Shackles, som bärs av de kraftiga Moonrage Gluttons som strövar omkring i norra Silverpine, fungerar som magiska ankare som förstärker förbannelsen som binder vidundren."},{t="Bränsle till motåtgärder för Forsaken",b="Eftersom Arugal band råa förtrollningar direkt i dessa tunga järnbojor behåller de en rest av magisk energi även efter att bärarna dödats. Dawnweaver kräver att agenter från Forsaken hämtar bojorna så att han kan studera deras konstruktion och suga åt sig deras magiska reserver. Genom att analysera de grova förtrollningarna i metallen hoppas Forsaken kunna avslöja worgenförbannelsens hemligheter och iscensätta fallet för bestmästaren som håller till i Shadowfang Keep."}},faq={{q="Vad är en Glutton Shackle?",a="En Glutton Shackle är en förtrollad järnboja som bärs av Moonrage Glutton-worgen i Silverpine Forest. Ärkemagikern Arugal skapade banden, som fyller bärarna med magisk förstärkning för att kompensera för hans bristfälliga besvärjelser.",al={"vad är glutton shackles","glutton shackle-lore","worgenbojor"}},{q="Varför vill Dalar Dawnweaver ha Glutton Shackles?",a="Dalar Dawnweaver behöver bojorna för att analysera Arugals grova förtrollningar och suga åt sig deras kvarvarande magiska energi. Genom att förstå föremålen Arugal använde för att stabilisera sina vidunder kan Forsaken bättre motverka hans magi.",al={"varför samla bojor","dalar dawnweavers uppdrag","bojor till the sepulcher"}},{q="Vem tillverkar bojorna?",a="De förtrollades av ärkemagikern Arugal, en tidigare trollkarl från Dalaran som kallade fram worgen för att bekämpa Scourge och så småningom förlorade förståndet. Han band sina skapelser till sin vilja med magiska prydnader.",al={"vem gjorde bojorna","arugals bojor","var kommer bojorna ifrån"}},{q="Var finns varelserna som bär bojorna?",a="Moonrage Gluttons strövar omkring i skogarna och på övergivna gårdar i mellersta och norra Silverpine Forest. De lurar ofta i flockar tillsammans med andra korrumperade Moonrage-worgen.",al={"var dyker gluttons upp","moonrage gluttons plats","silverpine worgenbojor"}}},fp="15,143,25.512.0,33.458.1,26.198.0,48.218.0,25.190.0,53.170.0"}
P.entries["item:glyph-of-azora"] = {n="Glyph of Azora",s="Från Tower of Azora använder Theocritus Glyphs of Azora för att hålla uppsikt över avlägsna hot. De ristade stenarna utökar räckvidden för Eye of Azora och låter honom läsa fienders tankar och planer.",h="Från Tower of Azora använder Theocritus Glyphs of Azora för att hålla uppsikt över avlägsna hot.",kw={"glyph of azora","morganth","redridge","kristallskådning","stonewatch keep","theocritus","tower of azora","tower of ilgalar"},ang={["class:Mage"]="Som magiker kan du använda magisk spådom för att utöka kristallskådning med riktad telepati och avlägsna sensoriska reläer.",["faction:Alliance"]="Som medlem av Alliansen kan du använda glyferna för att samla underrättelser om Morganth och Blackrock-orcherna vid Stonewatch Keep."},sec={{t="Ögon över gränsen",b="Theocritus håller uppsikt över fientliga makter från sitt torn i Elwynn Forest. Hans kristallrelik, Eye of Azora, låter honom se över stora avstånd, men inte nå in i sina motståndares tankar eller planer. Han placerar små fokus som kallas Glyphs of Azora på ytor långt borta för att föra sin magi längre. Varje glyf förankrar hans kraft och låter honom läsa fienders avsikter och projicera sin röst över flera mil för att tala med fältagenter."},{t="Spioneri i Redridge",b="I Redridge Mountains placerar Theocritus glyfer i fientligt territorium. Han fäster den första vid en uråldrig lejonstaty med utsikt över Tower of Ilgalar, där hans lömska rival, den mörke magikern Morganth, har sitt fäste. Genom glyfen tränger Theocritus in i Morganths sinne och upptäcker en tvist mellan den avfällige magikern och Blackrock-orcherna vid närbelägna Stonewatch Keep. För att ta reda på orsaken skickar han en andra glyf till höjderna i fästets intakta vakttorn, dold i en slängd spritburk."}},faq={{q="Vad är syftet med Glyph of Azora?",a="Theocritus använder en Glyph of Azora för att utöka räckvidden för Eye of Azora. Placerad på en avlägsen plats förankrar den hans magi, så att han kan läsa sina motståndares tankar och planer och tala med fältagenter över flera mil.",al={"vad gör glyph of azora","varför använda glyph of azora","glyph of azora syfte"}},{q="Vem skapade Glyph of Azora?",a="Theocritus skapade Glyph of Azora. Han bor i Tower of Azora vid den östra gränsen av Elwynn Forest.",al={"vem skapade glyfen","glyph of azora skapare","theocritus glyf"}},{q="Var placeras Glyphs of Azora?",a="En glyf är fäst vid en uråldrig lejonstaty med utsikt över Tower of Ilgalar. En andra är gömd i en slängd spritburk i det intakta vakttornet vid Stonewatch Keep.",al={"var ska jag placera glyfen","glyfens placeringar","var ska glyfen placeras"}},{q="Varför spionerar Theocritus på Tower of Ilgalar?",a="Tower of Ilgalar är Morganths fäste. Den lömske mörke magikern är Theocritus rival, och glyfen låter Theocritus läsa hans tankar och planer.",al={"varför spionera på morganth","theocritus ilgalar","morganths tvist"}},{q="Hur låter glyfen Theocritus tala med andra?",a="När glyfen har fästs vid en avlägsen yta förankrar den Theocritus magi och låter honom projicera sin röst över flera mil för att tala med fältagenter.",al={"talande glyf","theocritus röst i glyfen","kan glyfen prata"}}},fx={["16152ed3"]={q="Vad är Glyph of Azora?",a="Glyph of Azora är en förtrollad arkan markör som trollkarlen Theocritus skapade vid Tower of Azora. Tillsammans med hans skådande fokus, Eye of Azora, fungerar dessa ristade stenar som avlägsna avlyssningsposter. När en glyf fästs på en yta nära ett intressant område kan Theocritus tränga in i sina måls sinnen och tankar på långt håll. Han kan också projicera sin röst till alla som står bredvid den.",al={"vad är glyph of azora","glyph of azora föremål","berätta om glyph of azora"}},["7c5a9e02"]={q="Varför vill Theocritus att du placerar ut Glyph of Azora?",a="Theocritus använder dessa glyfer för att spionera på farliga motståndare i Redridge. Eye of Azora låter honom se platser på avstånd, men utan en ledare i närheten kan han inte tränga in i någons tankar. Om du placerar en glyf nära Tower of Ilgalar kan han utforska tankarna och framtidsplanerna hos sin rival, avfällingen Morganth. En annan glyf nära Stonewatch Keep hjälper honom att reda ut Morganths konflikt med Blackrock-orcerna.",al={"varför placera glyph of azora","varför vill theocritus placera ut glyfen","syftet med glyph of azora"}}},fp="14,161,22.362.0,21.468.1,42.206.0,31.107.0,37.168.0,49.150.0,55.136.0"}
P.entries["item:glyphic-letter"] = {n="Glyphic Letter",s="I Northshire Abbey kallar Glyphic Letter lovande noviser till studier i magi. Efter en första tjänstgöring i garnisonen kallas de upp till Khelden Bremen, klostrets magitränare.",h="I Northshire Abbey kallar Glyphic Letter lovande noviser till studier i magi.",kw={"magi","elwynn forest","glyphic letter","khelden bremen","magitränare","marshal mcbride","northshire abbey"},ang={["class:Mage"]="Som magiker kallar detta märkta brev dig uppför trapporna för att inleda formella studier i Alliansens magiska traditioner under Khelden Bremen.",["race:Human"]="Som människa inleder du din tjänst inom Stormwinds magiska discipliner med denna kallelse. Northshire Abbey har genom rikets historia gett magistudenter skydd."},sec={{t="En kallelse till magin",b="Khelden Bremen förseglar Glyphic Letter med sitt personliga sigill. Lärlingar i magi får det efter att ha visat sin disciplin i Northshire Valley. Kallelsen leder dem bort från grundläggande fälttjänst och till särskild magisk undervisning i klostret. Bremen prövar varje elevs beslutsamhet innan de tar sig an magin, med dess farliga krafter, obevekliga granskning och bördor."}},faq={{q="Vad är Glyphic Letter?",a="Khelden Bremen skriver och förseglar Glyphic Letter som en kallelse till undervisning. Det hänvisar blivande mänskliga magiker till honom i Northshire Abbeys övre rum för formella studier i magi.",al={"vad är det här brevet","föremålet glyphic letter","kheldens brev"}},{q="Vem skickar Glyphic Letter?",a="Khelden Bremen, magitränaren i Northshire Abbey, förseglar brevet med sitt sigill. Garnisonsledningen lämnar över det när en lärling har visat sitt värde mot närliggande skadedjur.",al={"vem skrev det","vem gav mig glyphic letter","brevets avsändare"}},{q="Vart ska jag ta Glyphic Letter?",a="Ta brevet in i Northshire Abbey. Gå in bakom Marshal McBride, följ den vänstra korridoren, gå uppför trapporna och leta efter det bakre rummet där Khelden Bremen undervisar i magi.",al={"vart ska jag gå","var är khelden bremen","kheldens plats"}},{q="Varför kallar Khelden på unga magiker?",a="Khelden vill pröva din beslutsamhet. Han varnar för att magi väcker både fruktan och respekt och innebär att utmana mäktiga krafter. Han måste veta att du har viljan att uthärda det ödet.",al={"varför vill khelden träffa mig","varför magitränaren","vad vill khelden"}}},fx={["4321b6bd"]={q="Varför vill Khelden Bremen att Glyphic Letter ska levereras till dig?",a="Brevet är en officiell kallelse och ett prov på beslutsamheten hos blivande magiker. Khelden Bremens meddelande är förseglat med hans personliga sigill och beskriver den farofyllda och krävande väg som magin innebär. Det varnar dig för rädslan och prövningarna som följer med sökandet efter förbjuden kunskap. Genom att lämna över brevet till dig försäkrar han sig om att du är villig att möta det ödet innan han inleder din formella utbildning.",al={"varför glyphic letter","varför fick jag glyphic letter","syftet med glyphic letter"}}},fp="14,180,23.390.0,27.190.0,29.183.0,35.185.0,38.193.0"}
P.entries["item:glyphic-memorandum"] = {n="Glyphic Memorandum",s="Glyphic Memorandum är ett skriftligt meddelande till nya magiker som anländer till Coldridge Valley. Det är skrivet på uppdrag av magitränaren Marryk Nurribit och uppmanar nyblivna trollkarlar att gå inomhus och börja sin formella undervisning i magi.",h="Glyphic Memorandum är ett skriftligt meddelande till nya magiker som anländer till Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","magiker","marryk nurribit"},ang={["class:Mage"]="För blivande magiker på färd genom Dun Morogh markerar det här meddelandet början på deras formella utbildning i magi under Marryk Nurribit.",["race:Gnome"]="Gnomiska magiker som inleder sina resor i exil får en påminnelse från sin tränare om att fokusera på sina studier och hålla sig borta från sitt förlorade hemland Gnomeregan."},sec={{t="En kallelse till Anvilmar",b="Nya trollkarlar som ger sig ut i den bitande kylan i Coldridge Valley får detta korta meddelande efter att ha slutfört sina första uppgifter. Den lokala magitränaren Marryk Nurribit har skrivit memorandumet och kallar unga utövare till värmen i Anvilmar. I stället för sträng akademisk dogm är Marryks råd informellt och rakt på sak: lär dig dina besvärjelser, lägg undan mynt till träning och öl på värdshuset, och håll dig långt borta från de strålningsskadade ruinerna i Gnomeregan."}},faq={{q="Vad är Glyphic Memorandum?",a="Det är en kort skriftlig kallelse till nyanlända magiker i Coldridge Valley, där de uppmanas att söka upp den lokala magitränaren inne i Anvilmar.",al={"glyfiskt meddelande","magikernas meddelande","vad är glyphic memorandum"}},{q="Vem skrev memorandumet?",a="Meddelandet kommer från Marryk Nurribit, en magitränare av gnomernas folk som är stationerad i Anvilmars salar i Dun Morogh.",al={"vem skrev det","vem skickade glyphic memorandum","meddelandets författare"}},{q="Vilka råd ger tränaren när han svarar på memorandumet?",a="När novisen visar upp meddelandet påminner Marryk honom om att visa måttfullhet, spara pengar till besvärjelser och öl på värdshuset samt undvika de radioaktiva salarna i Gnomeregan helt och hållet.",al={"marryks råd","vad säger marryk"}}},fx={c67a7a55={q="Varför vill Marryk Nurribit att du tar med Glyphic Memorandum till honom?",a="Memorandumet är en inbjudan och kallelse för blivande magiker som börjar sin bana i Coldridge Valley. När du levererar det till Marryk Nurribit i Anvilmar får du kontakt med din lokala magitränare. Han passar på att ge dig råd som nybörjare, påminna dig om att hålla dig borta från det fallna Gnomeregan och erbjuda formell undervisning i magins konst när du har råd.",al={"varför ta med glyphic memorandum","varför vill marryk ha memorandumet","varför vill man ha glyphic memorandum"}}},fp="18,158,21.305.0,31.126.0,26.81.0,64.131.0"}
P.entries["item:glyphic-scroll"] = {n="Glyphic Scroll",s="Glyphic Scroll är en kallelse till nyväckta Forsaken-magiker i Deathknell. Med Isabella, den lokala tränarens, sigill kallar den nybörjande magiker till den vanhelgade kyrkan för att finslipa sin konst i undeath.",h="Glyphic Scroll är en kallelse till nyväckta Forsaken-magiker i Deathknell.",kw={"arkan","deathknell","glyphic scroll","isabella","magiker","rulle","tirisfal"},ang={["class:Mage"]="Rullen är den första formella kallelsen en Forsaken-magiker får. Den betonar att undeath inte befriar en magiker från det arkana magins fördärvande beroende.",["race:Undead"]="För Forsaken är återvunnen arkansk kunskap mer än lärda studier. Den är ett oumbärligt vapen för att säkra deras självständighet mot både Scourge och levande fiender."},sec={{t="En kallelse från kyrkan",b="När en nyväckt Forsaken-magiker återvänder efter att ha rensat Deathknells kyrkogård från tanklösa Scourge väntar detta förseglade brev. Rullen är skriven under Isabellas sigill; hon är byns magitränare. Den kallar mottagaren till den förfallna kyrkans helgedom. För nyuppståndna magiker är den en första introduktion till den arkana disciplinen under Forsakens fana. Den påminner dem om att döden kanske befriade dem från dödlig svaghet, men att magisk kraft fortfarande lockar till fördärv lika starkt som någonsin."}},faq={{q="Vad är Glyphic Scroll?",a="Det är ett introduktionsbrev till nyväckta Forsaken-magiker i Deathknell. Med magitränaren Isabellas personliga sigill uppmanar det nyblivna magiker att söka upp henne i stadens kyrka och påbörja sin magiska utbildning.",al={"vad är det här för föremål","användning av glyphic scroll","vad gör rullen"}},{q="Vem skickar Glyphic Scroll?",a="Rullen levereras på uppdrag av Isabella, magitränaren i den förfallna kyrkan i Deathknell. Hon hör av sig till alla nyuppståndna odöda med fallenhet för det arkana.",al={"vem skrev den","vem gav mig den","rullens avsändare"}},{q="Varför vill Isabella träna nya Forsaken-magiker?",a="Isabella söker själsfränder som delar smärtan efter döden och viljan att återta sitt stulna hemland och sina öden. Hon tränar dem att utveckla tillräcklig arkansk kraft för att förgöra alla som motsätter sig Forsaken, samtidigt som hon varnar dem för att falla för magiskt beroende och fördärv.",al={"isabellas motiv","varför träna magiker"}}},fp="14,167,25.355.0,27.176.0,29.139.0,51.253.0"}
P.entries["item:glyphic-tablet"] = {n="Glyphic Tablet",s="I Valley of Trials ger Gornek Glyphic Tablet till unga Darkspear-trollmagiker. Dess kallelse skickar dem till Mai'ah för undervisning i arkan magi.",h="I Valley of Trials ger Gornek Glyphic Tablet till unga Darkspear-trollmagiker.",kw={"arkansk magi","durotar","glyphic tablet","gornek","mai'ah","trollmagiker","valley of trials"},ang={["class:Mage"]="Som magiker inleder du din arkana undervisning hos Darkspear med Mai'ahs varning om att magins fördärvande lockelse är din största fara.",["race:Troll"]="Som Darkspear-troll får du denna tavla för att inleda din väg vid sidan av de traditionella shamanska och krigiska levnadssätten."},sec={{t="En magikers första kallelse",b="Nya Darkspear-rekryter med fallenhet för arkan kraft får Glyphic Tablet i Valley of Trials. Gornek lämnar den till unga rekryter medan de utför sina första uppgifter bland de röda kanjonerna. På tavlan bjuder Mai'ah, en erfaren trollmagiker utanför The Den, in dem att träffa henne. Darkspear följer arkana traditioner som skiljer sig från människornas och högalvernas lärda akademier. Mai'ah erbjuder undervisning och en allvarlig varning: rå magi fördärvar och bedrar, och dess faror för en magikers sinne överträffar dem från varje fiendesoldat."}},faq={{q="Vad är syftet med Glyphic Tablet?",a="Glyphic Tablet kallar en ung trollmagiker till Mai'ah i Valley of Trials för att få ordentlig träning i besvärjelsekonst.",al={"vad gör glyphic tablet","glyphic tablet användning","varför har jag glyphic tablet"}},{q="Vem skickar Glyphic Tablet?",a="Mai'ah skriver tavlan, och Gornek lämnar den till unga trollrekryter i Valley of Trials.",al={"vem skrev glyphic tablet","vem gav mig glyphic tablet"}},{q="Varför behöver trollmagiker en varning om magi?",a="Mai'ah varnar för att arkan magi fördärvar, göder högmod och kan få besvärjare att känna sig osårbara. Dess osynliga faror är dödligare än fysiska rivaler.",al={"vad säger mai'ah","är magi farligt"}},{q="Kan andra folkslag i Horde få den här plattan?",a="Trollmagiker får Glyphic Tablet i Valley of Trials. Orkmagiker får en Glyphic Parchment som kallar dem till Mai'ah.",al={"kan orcer få glyphic tablet","är glyphic tablet bara för troll"}}},fx={be25ec39={q="Vad är Glyphic Tablet?",a="Glyphic Tablet är ett ristat meddelande som skickas till trollmagiker som börjar sina prövningar i Valley of Trials. Gornek levererar det och kallar dig till ett möte med Mai'ah, den lokala magitränaren, så att du kan inleda din formella utbildning i magins konst.",al={"vad är glyphic tablet","glyphic tablet föremål","om glyphic tablet"}},["28b4f0b5"]={q="Varför vill någon ha Glyphic Tablet?",a="Tableten söks inte för makt eller rikedom, utan fungerar som en formell kallelse och introduktion. Den ser till att unga trollmagiker inställer sig hos Mai'ah, som använder mötet för att utfärda viktiga varningar om de fördärvande faror som följer med att utöva arkana magi.",al={"varför vill man ha glyphic tablet","vem behöver glyphic tablet","varför behålla glyphic tablet"}}},fp="14,152,22.518.0,42.114.0,29.94.0,46.154.0,42.130.0"}
P.entries["item:glyphs-of-summoning"] = {n="Glyphs of Summoning",s="I Orgrimmar använder lärlingar bland trollkarlarna Glyphs of Summoning för att kalla fram en voidwalker. Inskrifterna är avskrivna från den uråldriga Tablet of Verga och drar en voidwalker från Nether till en besvärjelsecirkel, där den binds till trollkarlens tjänst.",h="I Orgrimmar använder lärlingar bland trollkarlarna Glyphs of Summoning för att kalla fram en voidwalker.",kw={"cleft of shadow","gan'rul bloodeye","glyphs of summoning","neeru fireblade","orgrimmar","tablet of verga","bindningen","voidwalker"},ang={["class:Warlock"]="Som trollkarl i Horde står du inför en viktig övergångsrit. Glyferna låter dig bevisa din makt över Void och göra anspråk på en voidwalker som tjänare."},sec={{t="En pakt smidd i skugga",b="I Cleft of Shadow studerar trollkarlarna de mörka konsterna långt från krigshövdingens vakters nyfikna blickar. För en blivande trollkarl som lär sig av Gan'rul Bloodeye är förmågan att befalla en voidwalker ett viktigt steg. Glyphs of Summoning bygger på kunskap som finns inskriven på Tablet of Verga och överbryggar Azeroth och Nether. I Neeru Fireblades tält lägger trollkarlen ut dem i en besvärjelsecirkel. De öppnar en passage och drar en varelse från Void till de dödligas värld. Innan Gan'rul lär ut de sista metoderna för att binda den måste trollkarlen besegra den framkallade varelsen i strid."}},faq={{q="Vad används Glyphs of Summoning till?",a="Glyferna är rituella inskrifter som används i besvärjelsecirkeln inne i Neeru Fireblades tält i Orgrimmar. De kallar fram en fientlig voidwalker från Nether, som trollkarlen måste kuva för att bemästra framkallningen.",al={"vad gör glyphs of summoning","glyphs of summoning syfte","hur använder man glyphs of summoning"}},{q="Var kommer Glyphs of Summoning ifrån?",a="Gan'rul Bloodeye, trollkarlstränaren i Cleft of Shadow, ger dig dem. De bygger på kunskap som bevarats på Tablet of Verga.",al={"var får man glyphs of summoning","vem ger glyphs of summoning"}},{q="Var utförs åkanderitualen?",a="Ritualen äger rum inne i Neeru Fireblades tält, på andra sidan grottgolvet i Orgrimmars Cleft of Shadow.",al={"var åkallar jag en voidwalker","plats för åkandecirkel i orgrimmar","neeru fireblades cirkel"}},{q="Varför måste utövare av svartkonst besegra den åkallade varelsen?",a="En trollkarl måste visa sin dominans för att säkert kunna kontrollera en demon eller varelse från Void. Genom att besegra den framkallade varelsen visar trollkarlen sin beslutsamhet, så att Gan'rul Bloodeye kan lära ut hur man binder dess sort till sin vilja.",al={"varför slåss mot voidwalkern","kuva voidwalker"}}},fx={["094a8ca5"]={q="Vad är Glyphs of Summoning?",a="Glyphs of Summoning är arkana och demoniska inskrifter som kopierats direkt från Tablet of Verga. De anförtros åt blivande häxmästare av Gan'rul Bloodeye under Orgrimmar och innehåller de exakta besvärjelser som krävs för att slita upp slöjan och kalla fram en fientlig voidwalker från Nether för att binda den.",al={"vad är glyphs of summoning","glyphs of summoning i historien"}},fd669514={q="Varför vill Gan'rul Bloodeye ha tillbaka Glyphs of Summoning?",a="Gan'rul Bloodeye kräver att du återlämnar glyferna tillsammans med bevis på din seger så att han kan slutföra din träning. När du visar att du har styrkan att kalla fram och kuva en rasande voidwalker använder Gan'rul glyferna och din bevisade skicklighet för att lära dig hur du permanent binder sådana väsen till din tjänst.",al={"varför återlämna glyphs of summoning","varför vill gan'rul ha glyphs of summoning","varför vill man ha glyphs of summoning"}}},fp="19,242,23.539.0,42.207.0,43.139.0,40.109.0,53.218.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Gnoam Sprecklesprocket",s="Gnoam Sprecklesprocket är en avancerad kraftkälla som bärgats från Sneed's Shredder djupt inne i The Deadmines. Gnomiska ingenjörer söker efter den här komponenten för att ge specialiserade borrmaskiner extra kraft i ett djärvt försök att återta sitt fallna hem Gnomeregan.",h="Gnoam Sprecklesprocket är en avancerad kraftkälla som bärgats från Sneed's Shredder djupt inne i The...",kw={"the deadmines","gnoam sprecklesprocket","gnomeregan","gyrodrillmatic","shoni the shilent","sneed","sneed's shredder","sprecklesprocket"},ang={["profession:Engineering"]="Kugghjulet är en intakt kraftkälla som kan driva maskinerna som behövs för att borra genom Gnomeregans bergiga underjordiska gränser.",["race:Gnome"]="Varje bärgad komponent för de landsförvisade gnomerna närmare att borra sig in i sitt förlorade hem och driva ut troggarna."},sec={{t="En livsviktig kraftkälla",b="Gnoam Sprecklesprocket hittades i en goblinstrimlare som användes i Defias fäste och är ett enastående exempel på kompakt mekanisk energi. Den här specialiserade kärnan satt djupt inne i den tungfotade maskinen som goblinernas arbetsledare Sneed körde och ger tillräckligt med uthållig energi för att driva tunga industriella stocknings- och skärblad. Dess stabilitet och kraftfulla uteffekt gör den till ett ovärderligt bärgningsfynd i Westfalls underjordiska tunnlar."},{t="In i Gnomeregan",b="I Stormwind City pekade den gnomiska uppfinnaren Shoni the Shilent ut strimlaren från The Deadmines som nyckeln till en större offensiv. Gnomiska styrkor vill återta Gnomeregan från troggarna som intog staden, men de förseglade underjordiska ingångarna utgör ett mäktigt hinder. Genom att utnyttja Sprecklesprocket tänker Shoni driva tunga gyrodrillmatic-utgrävare som kan borra rakt genom berggrunden runt den förlorade teknostaden och skapa en oväntad anfallsväg underifrån."}},faq={{q="Vad är Gnoam Sprecklesprocket?",a="Det är en intakt mekanisk kraftkälla med hög uteffekt, hämtad från en goblinstrimlare djupt inne i The Deadmines. Den har tillräcklig effekt för att driva tung underjordisk borrutrustning.",al={"sprecklesprocket","vad är det här kugghjulet","vad är föremålet"}},{q="Varifrån kommer Gnoam Sprecklesprocket?",a="Den bärgas från Sneed's Shredder, en industriell timmermaskin som goblinernas arbetsledare Sneed kör i timmerbruken i The Deadmines.",al={"vem släpper det","hur får man sprecklesprocket","byte från strimlare"}},{q="Varför behöver Shoni the Shilent den?",a="Shoni behöver dess uteffekt för att driva gyrodrillmatic-utgrävare. Maskinerna är byggda för att borra genom berggränserna under Gnomeregan, så att alliansvänliga gnomer kan anfalla troggarna.",al={"varför vill shoni ha den","shonis uppdragsföremål"}},{q="Är kugghjulet goblin- eller gnomteknik?",a="Det bärgas från en fungerande goblinstrimlare i The Deadmines, och Shoni tänker använda kraftkällan i gnomisk borrutrustning. Källan anger inte vem som ursprungligen konstruerade komponenten.",al={"är det goblinteknik","gnomisk eller goblinisk anordning"}}},fp="22,198,20.274.0,20.444.0,35.152.0,48.156.0,35.211.0,45.170.0"}
P.entries["item:gnoll-paw"] = {n="Gnoll Paw",s="Gnoll Paws når Sentinel Hill som bevis på en patrull mot Riverpaw-flockarna i Westfall. People's Militia erbjuder belöningar för att skydda lokala gårdar.",h="Gnoll Paws når Sentinel Hill som bevis på en patrull mot Riverpaw-flockarna i Westfall.",kw={"danuvin","gnoll paw","patrullera westfall","people's militia","riverpaw","sentinel hill","westfall"},ang={["class:Hunter"]="Som jägare kan du spåra Riverpaw-flockar över Westfalls öppna slätter och samtidigt hjälpa till att säkra utposter på landsbygden.",["faction:Alliance"]="För Alliansens hjältar hjälper belöningar från People's Militia till att skydda Stormwinds västra kornbod från kringströvande bestar och organiserade banditer."},sec={{t="Milisens belöning",b="People's Militia försvarar Westfall från Sentinel Hill. När kungens armé är frånvarande och kronan tycks blunda för landsbygdens problem får vanliga medborgare och frivilliga möta laglösa, kringströvande mekaniska varelser och Riverpaw-gnoller. Captain Danuvin erbjuder belöningar som bevis på att gnoller har dödats. När du tar med deras tassar visar det att patruller har sökt igenom buskmarkerna i stället för att vila under vakttornet."},{t="Ett samordnat hot",b="Riverpaw-gnoller i Westfall söker föda över slätterna, men milisens spanare har upptäckt tecken på nära samordning med Defias-tjuvar som håller till kring Deadmines. Flockarna terroriserar gårdar och ger sig på försörjningsvagnar, vilket hjälper till att skydda banditerna från lokalt motstånd. När du lämnar in gnolltassar hjälper du till att hålla landsvägarna mellan Sentinel Hill och Elwynn Forest öppna."}},faq={{q="Varför vill Captain Danuvin ha Gnoll Paws?",a="Captain Danuvin ber om Gnoll Paws som bevis på en lyckad patrull över Westfalls slätter. Med få resurser och utan hjälp från kronan betalar milisen belöningar när rekryter kommer med bevis på dödade gnoller.",al={"varför samla tassar","danuvin gnoll paws","vad används gnoll paws till"}},{q="Vilka gnoller släpper tassarna?",a="Tassarna kommer från Riverpaw-gnoller som strövar på Westfalls gräsmarker, kullar och övergivna gårdar.",al={"var hittar man gnoll paws","vilka gnoller har tassar","gnoll paw plats"}},{q="Agerar gnollerna ensamma i Westfall?",a="Nej. Captain Danuvin och milisen misstänker att Riverpaw-gnoller samarbetar med banditer och tjuvar kring Deadmines och hotar lokala gårdar.",al={"samarbetar gnoller med defias","gnoll deadmines samband","vem leder gnollerna"}},{q="Varför tar inte Stormwind hand om gnollhotet?",a="Stormwind har i stort sett lämnat Westfall åt sitt öde under inhemsk oro och politisk handlingsförlamning. Lokala bönder och People's Militia står för nästan hela arbetet med att försvara landsbygden.",al={"varför finns ingen stormwind-armé","var är armén","varför slåss milisen mot gnoller"}}},fx={aa4b645a={q="Vad är Gnoll Paw?",a="Gnoll Paw är en avhuggen hand från en Riverpaw-gnoll som strövar omkring på Westfalls slätter. För People's Militia, som är stationerad vid Sentinel Hill, är dessa makabra troféer obestridliga fysiska bevis på att en äventyrare aktivt har patrullerat området och decimerat de aggressiva gnollflockar som hotar traktens gårdar.",al={"vad är gnoll paw","föremålet gnoll paw","vad är gnoll paws"}},["96952327"]={q="Var kommer Gnoll Paws ifrån?",a="Dessa tassar kommer direkt från de vilda Riverpaw-gnollerna som är utspridda över Westfalls gräsmarker och övergivna gårdar. De förvildade gnollerna strövar omkring i området, jagar bönder och samarbetar med laglösa. Deras avhuggna tassar är därför en bister belöning som tagits direkt från stupade plundrare ute på fältet.",al={"var får man tag på gnoll paws","vem släpper gnoll paws","gnoll paws ursprung"}}},fp="9,161,21.403.0,20.379.1,41.199.0,29.98.0,40.159.1,50.195.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Gnomeregan Gumdrop",s="Under Hallow's End når Gnomeregan Gumdrop resenärer från de förvisade gnomerna. En sötsak hjälper sjuke Jesper att fira på barnhemmet i Stormwind.",h="Under Hallow's End når Gnomeregan Gumdrop resenärer från de förvisade gnomerna.",kw={"godis","gnomeregan gumdrop","hallow's end","ironforge","jesper","stormwind","talvash del kissel"},ang={["faction:Alliance"]="Du reser mellan mänskliga, dvärglika och gnomiska samhällen för att samla in sötsaken och dela Alliansens nära band under årstidens firande.",["race:Gnome"]="Även om gnomerna inte har återtagit någon egen stad, gör deras klassiska sötsak sällskap med godsakerna från Alliansens stora huvudstäder under Hallow's End."},sec={{t="Ett smakprov på gnomisk uppfinningsrikedom",b="I Mystic Ward i Ironforge delar Talvash del Kissel ut Gnomeregan Gumdrop till resenärer som spelar med i hans Hallow's End-trick. Värdshusvärdar i hela Alliansen erbjuder lokala godsaker, men de förvisade gnomerna har inget eget värdshus i någon huvudstad. Den radioaktiva katastrofen drev bort dem från deras underjordiska kungarike, men de delar fortfarande sina särpräglade sötsaker med Alliansen."},{t="En godsak till Jesper",b="Sjuke Jesper är hänvisad till barnhemmet i Stormwind på Cathedral Square och kan inte resa runt på kontinenterna för att gå bus eller godis. Resenärer samlar fyra regionala godsaker från Alliansens huvudstäder för att ta med till honom: Gnomeregan Gumdrop, Stormwind Nougat, Ironforge Mint och Darnassus Marzipan."}},faq={{q="Var kommer Gnomeregan Gumdrop ifrån?",a="Talvash del Kissel delar ut Gnomeregan Gumdrop i Mystic Ward i Ironforge när du spelar med i ett av hans Hallow's End-trick.",al={"vem delar ut gnomeregan gumdrop","hur får man gumdrop","gumdrop plats"}},{q="Varför delas det här godiset inte ut i Gnomeregan?",a="Troggs tog över och bestrålade Gnomeregan, vilket tvingade de överlevande gnomerna i exil. Många bor nu tillsammans med dvärgarna i Ironforge, däribland Talvash del Kissel.",al={"varför ironforge","varför är talvash i ironforge"}},{q="Vad används det här godiset till?",a="Du tar med sötsaken till Jesper, en sjuk föräldralös pojke på barnhemmet i Stormwind på Cathedral Square. Den är en av fyra festliga sötsaker som samlas in åt honom under Hallow's End.",al={"vad gör gumdrop","jespers godis"}},{q="Vilka andra godsaker samlas in tillsammans med den?",a="Jesper ber också om Stormwind Nougat, Ironforge Mint och Darnassus Marzipan. Du samlar in var och en i sin respektive huvudstad i Alliansen.",al={"andra godissorter","hallow's end-godsaker"}}},fx={["243db981"]={q="Vad är Gnomeregan Gumdrop?",a="Gnomeregan Gumdrop är ett festligt godis som representerar gnomfolket och delas ut under högtiden Hallow's End. Trots att det är uppkallat efter Gnomeregans förlorade tekniska underverk delas godiset ut av gnomer som sökt skydd i dvärgarnas huvudstad Ironforge, framför allt uppfinnaren Talvash del Kissel.",al={"vad är gnomeregan gumdrop","godiset gnomeregan gumdrop","gnomeregan gumdrop i historien"}}},fp="18,142,28.371.0,18.281.0,42.121.0,46.162.0,28.168.0,45.130.0"}
P.entries["item:gnomish-tools"] = {n="Gnomish Tools",s="Längs Durotars kust ligger Gnomish Tools bland vraken efter Proudmoores flotta. Horden söker efter de bärgade redskapen för att studera Alliansens ingenjörskonst och anpassa dess uppfinningar för sin överlevnad.",h="Längs Durotars kust ligger Gnomish Tools bland vraken efter Proudmoores flotta.",kw={"durotar","ingenjörskonst","gar'thok","gnomish tools","proudmoore","razor hill","scuttle coast","tiragarde keep"},ang={["faction:Horde"]="Som medlem av Horden kan du hjälpa till att bärga förlorad utrustning från Alliansen för studier. Kunskap om fiendens konstruktioner och främmande mekanismer kan hjälpa Horden att försvara sig mot framtida flottinvasioner.",["profession:Engineering"]="Som ingenjör kan du studera satserna och få inblick i Alliansens pillrares noggranna hantverk, urverksmekanismer och miniatyrisering."},sec={{t="Bärgning från djupet",b="Storamiral Daelin Proudmoores flotta förde med sig väldiga mängder modern utrustning till Durotar. Proudmoore ledde Kul Tiras och Alliansens styrkor till dess stränder, med avancerad utrustning från deras gnomiska allierade ombord. När flottan förstördes längs Scuttle Coast, öster om Tiragarde Keep, sjönk de ömtåliga mekaniska verktygssatserna under vågorna. Vattentäta verktygslådor ligger fortfarande bland ruttnande timmer och skeppsskrov täckta av havstulpaner på grunt vatten."},{t="Ögon i Orgrimmar",b="Gar'Thok, som håller uppsikt över Razor Hill, skickade ut hordespejare för att hämta verktyg ur Proudmoores flotta, som fått sin grav i vattnet. Orcherna vet att människor och gnomer är skickliga på ingenjörskonst, särskilt belägringsmaskiner, skeppsbygge och urverksmekanik. De skickar satserna med karavan till hantverkare och lärda i Orgrimmar. Där tänker Horden studera Alliansens konstruktioner, lära sig att stå emot fiendens krigsmaskiner och anpassa främmande uppfinningar för sin egen överlevnad."}},faq={{q="Varför ligger gnomiska verktyg utanför Durotars kust?",a="Storamiral Daelin Proudmoores flotta förde verktygen med sig när Kul Tiras anföll Durotar. När armadan krossades och sjönk längs Scuttle Coast, öster om Tiragarde Keep, hamnade flottans last på havsbotten.",al={"varför gnomiska verktyg här","gnomiska verktygens ursprung","hur hamnade verktygen i durotar"}},{q="Varför vill Horden ha de här verktygen?",a="Gar'Thok från Razor Hill vill att verktygen bärgas och skickas till Orgrimmar. Studier av Alliansens ingenjörers intrikata mekaniska kunnande kan hjälpa Horden att förstå fiendens maskiner och bygga bättre utrustning själv.",al={"varför vill gar'thok ha verktygen","hordens användning av gnomiska verktyg","vad används verktygen till"}},{q="Var finns verktygen?",a="Verktygen ligger i verktygslådor som är utspridda i och kring sjunkna vrak längs Durotars Scuttle Coast, strax öster om Tiragarde Keep. Många ligger under vatten eller på sönderslagna skrov som sticker upp till hälften ur vattnet.",al={"gnomiska verktygens plats","var hittar man gnomiska verktyg","gnomiska verktygslådors plats"}}},fx={bc7dc32b={q="Vad är det här för Gnomish Tools?",a="Det här är specialiserade mekaniska verktyg tillverkade av Alliansens gnomer. De är högt värderade för sin precision och sinnrika utformning och representerar några av Azeroths mest avancerade ingenjörskonst. De fanns ombord på storamiral Proudmoores krigsfartyg för att underhålla och reparera avancerad alliansutrustning, men spreds över havsbottnen utanför Durotars kust när hans flotta gick under.",al={"vad är gnomish tools","information om gnomish tools"}}},fp="13,208,14.447.0,17.457.0,53.225.0,36.204.0,26.188.0"}
P.entries["item:goggles-of-gem-hunting"] = {n="Goggles of Gem Hunting",s="Goggles of Gem Hunting är en gnomisk apparat som används för att hitta skatter under vattnet utanför Arathi Highlands. Förtrollningen avslöjar ädelstenar begravda i sten på havsbotten.",h="Goggles of Gem Hunting är en gnomisk apparat som används för att hitta skatter under vattnet utanför Arathi...",kw={"arathi highlands","doctor draxlegauge","alviska ädelstenar","faldir's cove","goggles","goggles of gem hunting","professor phizzlethorpe","sjunken skatt"},ang={["profession:Engineering"]="Som ingenjör kan du beundra hur Doctor Draxlegauge förenar gnomisk konstruktion med Professor Phizzlethorpes förtrollning i sina goggles.",["race:Gnome"]="Som gnom kan du se Doctor Draxlegauges uppfinningsrikedom i en apparat som byggts för att hitta ädelstenar under havet."},sec={{t="Under vågorna",b="Utanför Faldir's Cove lånar Doctor Draxlegauge ut Goggles of Gem Hunting till besättningen på Captain O'Breen. Professor Phizzlethorpe ger apparaten kraft med en förtrollad sten, så att den kan hitta ädelstenar där nere. Skatten har legat under vatten så länge att ädelstenarna har förkalkats till tjock sten. Draxlegauge ber att få tillbaka gogglesen när sökandet är klart."}},faq={{q="Vem tillverkade gogglesen?",a="Doctor Draxlegauge konstruerade Goggles of Gem Hunting, och Professor Phizzlethorpe gav dem kraft med en förtrollad sten.",al={"gogglesens tillverkare","vem byggde dem","draxlegauge goggles"}},{q="Vad gör gogglesen?",a="Gogglesen låter bäraren hitta ädelstenar under havet, även när de har förkalkats till tjock sten.",al={"hur fungerar gogglesen","hitta ädelstenar","goggles för att hitta ädelstenar"}},{q="Var används gogglesen?",a="Goggles of Gem Hunting används för att söka på havsbotten utanför Faldir's Cove i Arathi Highlands.",al={"var används gogglesen","gogglesens plats","faldir cove goggles"}},{q="Varför vill Captain O'Breen ha ädelstenarna?",a="Doctor Draxlegauge ber dig hitta de sjunkna ädelstenarna åt Captain O'Breen. Den tillgängliga redogörelsen ger ingen ytterligare anledning till Captain O'Breens intresse.",al={"kaptenen vill ha ädelstenar","varför samla alviska ädelstenar","o'breens skatt"}}},fp="22,175,17.367.0,21.126.0,23.109.0,27.98.0,39.145.0"}
P.entries["item:gold-dust"] = {n="Gold Dust",s="I Elwynn Forest samlar kobolder guldflisor och lägger dem på hög i gruvorna. Lokala köpare betalar för stoftet, medan gruvarbetare söker hela malmådror.",h="I Elwynn Forest samlar kobolder guldflisor och lägger dem på hög i gruvorna.",kw={"elwynn","fargodeep","gold dust","goldshire","goldtooth","jasperlode","kobold","remy two times"},ang={["class:Rogue"]="Som skurk kan du få veta hur underjorden förflyttar oraffinerat, ospårat damm genom skumma handlare som Remy \"Two Times\" och döljer obearbetade rikedomar för Stormwinds magistrater.",["profession:Mining"]="Gruvarbetare söker efter solida ådror av koppar och tenn med hacka och vaskpanna. Koboldernas damm antyder att Elwynns underjordiska gångar rymmer rikare malmådror än vanliga undersökningar visar."},sec={{t="En påse full av skrot",b="Kobolder gräver i Fargodeep Mine och Jasperlode Mine under Elwynn Forest. De sparar gulddammet de hittar i fickor och påsar i stället för att rena det. Lokala gårdfarihandlare och hälarna vill ha dessa småfynd och hoppas tjäna pengar utan att betala officiella smältningstullar."},{t="Goldshires svarta marknad",b="I Goldshire ber Remy \"Two Times\" resenärer att ta med återvunnet gulddamm till honom. Han säger att han erbjuder det bästa priset i staden och byter mynt och misstänkta polletter mot obearbetat damm på uppdrag av namnlösa medhjälpare. Resenärer hämtar guldet från kobolder, medan mäklarna säkrar rikedomar mitt framför näsan på Stormwinds vakter."}},faq={{q="Var kommer Gold Dust ifrån?",a="Kobolder i hela Elwynn Forest bär på Gold Dust. Gruvarbetare, tunnelgrävare, geomantiker och deras ledare Goldtooth samlar det och lägger det på hög medan de gräver sig genom kullarna.",al={"hur får man tag på gold dust","gold dust byte","var hittar man gold dust"}},{q="I vilka gruvor finns flest kobolder som bär på Gold Dust?",a="Kobolder med gulddamm svärmar i både Fargodeep Mine, söder om Goldshire, och Jasperlode Mine, i nordost.",al={"var finns gruvorna","bästa gruvan för gold dust","gruvornas platser"}},{q="Vem köper Gold Dust i Elwynn Forest?",a="Remy \"Two Times\", en skum handlare utanför Lion's Pride Inn i Goldshire, köper insamlade påsar med Gold Dust för pengar och polletter från sina medhjälpare.",al={"vem vill ha gold dust","remy two times gold dust","lämna in gold dust"}},{q="Varför bär kobolder på damm i stället för tackor?",a="Kobolder saknar disciplinen och infrastrukturen för att smälta malm ordentligt. När de gräver sig genom berget med grova hackor samlas löst gulddamm på deras tillhörigheter och i små påsar som de bär som glänsande prydnader.",al={"varför har kobolder damm","koboldguld"}}},fx={["38570104"]={q="Vad är Gold Dust?",a="Gold Dust består av fina, råa flingor av dyrbart guld som brutits av koboldhorderna under Elwynn Forest. Det är varken förädlad valuta eller gjutet guldtackeguld, utan råmaterial som kobolderna hackar loss direkt från rika ådror på platser som gruvorna Fargodeep och Jasperlode.",al={"vad är gold dust","föremålet gold dust","om gold dust"}},["4a74ebdb"]={q="Varför vill Remy Two Times ha Gold Dust?",a="Remy \"Two Times\" i Goldshire köper upp rått gulddamm för sin egen handel och sina skumraskbekanta. Kobolderna kan föga om att smälta tackor, så det finns gott om oredovisade mineraltillgångar på deras kroppar för den som är djärv nog att ta dem och sälja dem vidare.",al={"varför vill remy ha gold dust","varför vill man ha gold dust","varför vill remy two times ha gold dust"}}},fp="9,107,22.262.0,24.318.1,31.158.0,53.101.0,36.153.0,44.201.0"}
P.entries["item:golem-oil"] = {n="Golem Oil",s="Golem Oil samlas in från golems och elementaler i Searing Gorge. Velarok Windblade behöver oljan för att förbereda en fackla till de fyra vakttornen.",h="Golem Oil samlas in från golems och elementaler i Searing Gorge.",kw={"elementaler","flawless flame","golem oil","golems","hearts of flame","searing gorge","vakttorn","torch of flawless flame","velarok windblade"},sec={{t="Olja till facklan",b="Velarok Windblade ber om fyra klot med Golem Oil i Searing Gorge. Han behöver dem och fyra Hearts of Flame för att tillverka Torch of Flawless Flame, som ska sätta de fyra vakttornen i brand. Golems och elementaler i dessa trakter är de första varelserna att söka efter materialen hos."}},faq={{q="Vad används Golem Oil till?",a="Velarok Windblade använder fyra klot med Golem Oil och fyra Hearts of Flame för att tillverka Torch of Flawless Flame.",al={"användning av golem oil","varför samla golem oil"}},{q="Vem behöver Golem Oil?",a="Velarok Windblade ber om Golem Oil i Searing Gorge så att han kan tillverka Torch of Flawless Flame.",al={"vem vill ha oljan","velarok olja"}},{q="Var hittar jag Golem Oil?",a="Golems och elementaler i Searing Gorge är de första varelserna att söka efter Golem Oil hos.",al={"var finns golem oil","oljekälla"}},{q="Hur mycket Golem Oil behöver Velarok?",a="Velarok Windblade ber om fyra klot med Golem Oil.",al={"hur många klot","mängd olja"}},{q="Vad ska Torch of Flawless Flame göra?",a="Torch of Flawless Flame ska sätta de fyra vakttornen i brand.",al={"torch of flawless flame","facklans syfte"}}},fp="9,144,17.275.0,22.111.0,20.98.0,27.89.0,37.52.0,48.74.0"}
P.entries["item:golm-fragment"] = {n="Golm Fragment",s="Golm Fragment är en av fyra saknade bitar som huggits loss från Goaz Stone, en uråldrig relik som grävts fram vid utgrävningsplatsen i Wetlands. Äventyrare hämtar den medan de undviker våldsamma rovfåglar, och den hjälper dvärgarkeologer att sammanfoga mystiska titaninskrifter.",h="Golm Fragment är en av fyra saknade bitar som huggits loss från Goaz Stone, en uråldrig relik som grävts fram...",kw={"utgrävningsplats","goaz stone","golm fragment","uncovering the past","wetlands","whelgar"},ang={["faction:Alliance"]="När du hämtar fragmentet hjälper du Explorers' League att säkra ovärderlig uråldrig kunskap innan rovfåglarna tar över hela utgrävningsplatsen.",["race:Dwarf"]="För dvärgar är det viktigt att sammanfoga bitarna av Goaz Stone för att upptäcka deras titanursprung och den dolda historien som ligger begravd i Khaz Modan."},sec={{t="En bit av Goaz Stone",b="Golm Fragment upptäcktes vid utgrävningsplatsen i södra Wetlands och är en del av en monumental stenhäll som kallas Goaz Stone. Prospector Whelgar upptäckte stenen strax innan rovfåglar drev tillbaka Explorers' League, men fann att inskriften var avbruten på fyra viktiga ställen. Golm Fragment övergavs bland jord och omkullvälta lådor när utgrävningen blev överrumplad, och gömdes i en uråldrig relikask tills modiga utforskare kunde hämta den."},{t="Titanernas hemligheter",b="När Golm Fragment återförenas med fragmenten Ados, Modr och Neru blir den en kryptisk titantext som förutsäger en ”gudomlig plan” och en ”ödesdiger profetia”. När stenen sätts ihop kan Whelgar tyda rader som hänvisar till uråldriga väsen kedjade under jorden, vilket bekräftar att platsen rymmer kunskap som är långt äldre och farligare än ett enkelt dvärgarv."}},faq={{q="Vad används Golm Fragment till?",a="Det är en av fyra stenbitar som Prospector Whelgar behöver vid utgrävningsplatsen i Wetlands för att återställa Goaz Stone under uppdraget Uncovering the Past.",al={"golm fragment användning","varför behövs golm fragment","golm fragment uppdrag"}},{q="Var hittar man Golm Fragment?",a="Den finns bland uråldriga reliker och lös jord som ligger utspridda på utgrävningsplatsen i de södra kullarna i Wetlands, där det kryllar av rovfåglar.",al={"golm fragment plats","hitta golm fragment","var finns golm fragment"}},{q="Vad står det på Goaz Stone när den har satts ihop?",a="Whelgars första översättning talar om en gudomlig plan och en ödesdiger profetia. Han behöver alla fyra fragmenten för att fortsätta tyda den ofullständiga titantexten.",al={"goaz stone översättning","vad står det på stentavlan","whelgars översättning"}},{q="Vilka andra fragment behövs för att färdigställa stenen?",a="Förutom Golm måste du hämta fragmenten Ados, Modr och Neru för att sätta ihop hela stentavlan.",al={"andra fragment till stentavlan","goaz stone bitar","fyra fragment"}}},fx={["523a83d7"]={q="Vad är Golm Fragment?",a="Golm Fragment är en av fyra saknade bitar som brutits loss från Goaz Stone, en forntida relik som grävts fram vid utgrävningsplatsen i Wetlands. Den bär arkaiska inskrifter som passar in i den större tavlans gåtfulla berättelse.",al={"vad är golm fragment","golm fragment i historien","vad är golm-biten"}},["890266ad"]={q="Var kommer Golm Fragment ifrån, och vem skapade det?",a="Fragmentet var ursprungligen en del av Goaz Stone, som höggs ut i titanernas skrift för länge sedan. Det grävdes fram under dvärgarnas arkeologiska utgrävning i Wetlands, innan fientliga rovfåglar invaderade området och skingrade de sönderslagna bitarna.",al={"vem skapade golm fragment","golm fragments ursprung","varifrån kommer golm fragment"}},["6695e471"]={q="Varför vill Prospector Whelgar ha Golm Fragment?",a="Prospector Whelgar behöver Golm Fragment tillsammans med de andra bitarna för att sätta ihop hela Goaz Stone. Utan den bryts den översatta texten plötsligt av, och viktiga detaljer om en gudomlig plan och en ödesdiger profetia saknas.",al={"varför behöver whelgar golm fragment","vem vill ha golm fragment","varför leta efter golm fragment"}}},fp="13,178,25.394.0,21.324.1,35.148.0,37.127.0,44.151.1,52.83.0"}
P.entries["item:goodsteel-ledger"] = {n="Goodsteel Ledger",s="Goodsteel Ledger är en kopia av en lista som förvaras i Searing Gorge. Den namnger varor som Krinkle Goodsteel vill få levererade till sig i Gadgetzan.",h="Goodsteel Ledger är en kopia av en lista som förvaras i Searing Gorge.",kw={"balanced flameberge","gadgetzan","goodsteel ledger","krinkle goodsteel","liggare från tanaris","overdue package","searing gorge","solid crystal leg shaft"},sec={{t="Goodsteel Ledger",b="Nära ett utedass i Searing Gorge ligger Goodsteel Ledger, en kopia avsedd för Krinkle Goodsteel i Gadgetzan. På sidorna listas varor han söker från flera platser. När du tar liggaren till honom börjar jakten på det som står i den."}},faq={{q="Vad är Goodsteel Ledger?",a="Goodsteel Ledger är en kopia av Krinkle Goodsteels lista över efterfrågade varor, som hittades i Searing Gorge.",al={"goodsteel ledger","goodsteels lista","liggare från tanaris"}},{q="Var hittar jag liggaren?",a="Goodsteel Ledger ligger vid ett utedass i Searing Gorge.",al={"liggarens plats","var finns goodsteels liggare","liggare searing gorge"}},{q="Vem är Krinkle Goodsteel?",a="Krinkle Goodsteel är en gnom i Gadgetzan som letar efter varor från Searing Gorge och andra platser.",al={"krinkle","goodsteel-typen","vem vill ha liggaren"}},{q="Vad står i liggaren?",a="I liggaren står Solid Crystal Leg Shafts, an Overdue Package och Goodsteel's Balanced Flameberge.",al={"vad står på listan","föremål i liggaren","varor goodsteel vill ha"}},{q="Vart ska jag ta den?",a="Ta kopian av liggaren till Krinkle Goodsteel i Gadgetzan och samla sedan in varorna som står i den.",al={"vart ska liggaren tas","ta liggaren till krinkle","goodsteel gadgetzan"}}},fp="16,131,10.229.0,29.102.0,27.58.0,25.103.0,26.99.0,23.98.0"}
P.entries["item:goodsteel-s-balanced-flameberge"] = {n="Goodsteel's Balanced Flameberge",s="Goodsteel’s Balanced Flameberge är ett av föremålen som Krinkle Goodsteel söker för sitt arbete i Tanaris. Spåren leder från Searing Gorge till Swamp of Sorrows.",h="Goodsteel’s Balanced Flameberge är ett av föremålen som Krinkle Goodsteel söker för sitt arbete i Tanaris.",kw={"flameberge","gadgetzan","goodsteel’s balanced flameberge","jarquia","krinkle goodsteel","liggare från tanaris","swamp of sorrows"},sec={{t="En plats på listan",b="I Searing Gorge nämner Krinkle Goodsteels liggare en balanserad flameberge bland varorna han vill få till Gadgetzan. Jarquia, en murloc på Swamp of Sorrows östra kust, bär vapnet. När det väl har hittats kan det tas med de andra varorna på listan till Krinkle."}},faq={{q="Vem vill ha flamebergen?",a="Krinkle Goodsteel i Gadgetzan vill ha den balanserade flamebergen, som står i hans liggare.",al={"vem behöver den","krinkles svärd","vem vill ha vapnet"}},{q="Var hittar jag Goodsteel’s Balanced Flameberge?",a="Jarquia, en murloc på Swamp of Sorrows östra kust, bär Goodsteel’s Balanced Flameberge.",al={"var finns flamebergen","hitta goodsteels svärd","var finns jarquia"}},{q="Varför vill man ha flamebergen?",a="Krinkle Goodsteel begärde vapnet som en av flera varor i sin liggare.",al={"varför behöver krinkle den","vad ska den användas till","varför hämta svärdet"}},{q="Är ”flameberge” rätt stavning?",a="Namnet använder ”flameberge”, även om ordet vanligtvis stavas ”flamberge”.",al={"stavning av flamberge","stavfel i flameberge","är det en flamberge"}}},fp="31,162,19.280.0,25.92.0,51.106.0,29.84.0,39.83.0"}
P.entries["item:gordon-s-crate"] = {n="Gordon's Crate",s="Gordon's Crate är en tung vapensändning som packats i Undercity för Forsaken-styrkorna i Silverpine Forest. Den ska föras direkt till den avlägsna garnisonen vid The Sepulcher.",h="Gordon's Crate är en tung vapensändning som packats i Undercity för Forsaken-styrkorna i Silverpine Forest.",kw={"fladdermusförare","deathguard podrig","gordon's crate","gordons crate","karos razok","michael garrett","förnödenheter till silverpine","the sepulcher","undercity"},ang={["faction:Horde"]="Leveransen visar hur Forsakens flygrutter blir allt mer samordnade och snabbt för förnödenheter och kurirer över det omstridda Lordaeron.",["race:Undead"]="Varje sändning med klingor och utrustning från huvudstaden befäster Lady Sylvanas osäkra gränser i Silverpine Forest."},sec={{t="Förnödenheter till Silverpine",b="För att Forsaken ska behålla sitt grepp om Silverpine Forest krävs ett jämnt flöde av förnödenheter från Undercity. Gordon's Crate innehåller vapen som ska förstärka Deathguard Podrigs försvarare vid The Sepulcher, så att utpostens vakter inte överrumplas av worgen, vilddjur eller kvarvarande människor som lurar i skogen."},{t="Fladdermusförarens rutt",b="Eftersom landsvägarna ut från huvudstaden är farliga och långsamma förlitar sig värdefulla sändningar på Undercitys fladdermusförare. Lådan lämnas till Michael Garrett, fladdermästaren som håller till ovanför stadens Trade Quarter. Han ordnar färd med en tränad flygande fladdermus tillbaka till Karos Razoks näste vid The Sepulcher."}},faq={{q="Vad finns i Gordon's Crate?",a="Lådan innehåller vapen och viktiga stridsförnödenheter som rekvirerats från Undercity för att förstärka Deathguard-vakterna i Silverpine Forest.",al={"innehållet i gordons crate","vad innehåller lådan"}},{q="Vem ska ta emot Gordon's Crate?",a="Deathguard Podrig vid The Sepulcher tar emot lådan. För transporten måste du samordna med Undercitys fladdermusförare Michael Garrett för att ordna en direktflygning.",al={"vem får gordons crate","vart ska lådan"}},{q="Varför transporteras lådan med fladdermus i stället för av en kurir till fots?",a="Silverpine Forest är fortfarande omstritt och farligt. Tränade fladdermöss under uppsikt av förare som Michael Garrett och Karos Razok ger snabb transport genom luften och undviker hot längs markvägarna.",al={"varför flyga lådan","fladdermus och låda"}},{q="Varför kräver Michael Garrett att du besöker The Sepulcher först?",a="Forsaken-fladdermöss återvänder instinktivt till huvudstaden, men för att nå avlägsna baser som The Sepulcher på ett säkert sätt måste resenärer först knyta kontakt med den lokala föraren, Karos Razok, innan fladdermössen kan göra färden.",al={"varför behövs en flygrutt","krav för fladdermusflygning"}}},fx={df26763c={q="Vad är Gordon's Crate?",a="Gordon's Crate är en leverans med viktiga vapen och militära förnödenheter som packats i Undercity. Den har förberetts särskilt för att flygas med fladdermusförare till den avlägsna Försakade utposten vid The Sepulcher.",al={"gordon's crate","vad är det här för låda","gordons crate"}},e23fc119={q="Var kommer Gordon's Crate ifrån, och vem gjorde den?",a="Lådan kommer från Undercity, där Gordon packade garnisonens förnödenheter innan han ordnade leveransen till fladdermusförarna.",al={"varifrån kommer gordons crate","vem packade gordons crate","vem gjorde gordons crate"}},a5301c7a={q="Varför vill någon ha Gordon's Crate?",a="Deathguard Podrig och soldaterna som är stationerade vid The Sepulcher behöver verkligen leveransen. Lådan innehåller vapen som behövs för att se till att de lokala Deathguards som försvarar Silverpine Forest är välbeväpnade och inte blir överrumplade av sina fiender.",al={"varför behövs gordons crate","varför ta gordons crate till the sepulcher","vem behöver gordons crate"}}},fp="14,148,23.233.0,23.282.0,30.142.0,42.134.0,65.191.0,66.192.0"}
P.entries["item:gordunni-cobalt"] = {n="Gordunni Cobalt",s="Vid Gordunni Outpost fångar blå glimtar i jorden Orwin Gizzmicks blick. Han hoppas att den begravda kobolten ska inbringa ett bra pris.",h="Vid Gordunni Outpost fångar blå glimtar i jorden Orwin Gizzmicks blick.",kw={"camp mojache","kobolt","feralas","gordunni","gordunni cobalt","gordunni outpost","orwin gizzmick","orwins spade"},sec={{t="Blått i jorden",b="Orwin Gizzmick har nyligen kommit till Feralas och vill ha prover av mineralen som Gordunni-ogrerna begraver vid sitt utpostläger. Han lånar dig sin spade och pekar norrut från Camp Mojache. Leta efter det blå skenet bland jordhögarna. Orwin vill ha kobolten för att den kan vara värdefull för en köpare."}},faq={{q="Vem vill ha Gordunni Cobalt?",a="Orwin Gizzmick i Camp Mojache vill ha tolv prover av Gordunni Cobalt.",al={"vem vill ha kobolt","orwin kobolt","gizzmicks mineral"}},{q="Var hittar jag Gordunni Cobalt?",a="Kobolten ligger i jordhögar vid Gordunni Outpost, norr om Camp Mojache i Feralas.",al={"koboltens plats","var finns kobolt","blå jord"}},{q="Varför är kobolten begravd?",a="Gordunni-ogrerna begraver mineralen för att hindra andra från att lägga beslag på den.",al={"varför begravd","ogrer begraver kobolt","gordunni-jord"}},{q="Vad ska Orwin ha kobolten till?",a="Orwin hoppas hitta någon som betalar ett bra pris för kobolten.",al={"varför orwin vill ha den","koboltpris","sälja kobolt"}}},fp="15,127,16.277.0,30.71.0,33.85.0,25.82.0,36.69.0"}
P.entries["item:gordunni-orb"] = {n="Gordunni Orb",s="En Gordunni Orb är ett mäktigt magiskt föremål som tagits från Gordunni i Feralas. Dess magi kan hjälpa till att avslöja syftet med deras mörka ceremoni.",h="En Gordunni Orb är ett mäktigt magiskt föremål som tagits från Gordunni i Feralas.",kw={"camp mojache","mörk ceremoni","darkbriar lodge","feralas","gordunni","gordunni orb","magikerherre","rok orhan","uthel'nay"},ang={["class:Mage"]="Som magiker kanske du förstår varför Rok Orhan söker efter klotet: dess magi kan hjälpa till att avslöja mer om Gordunnis ceremoni.",["faction:Horde"]="Som medlem av Horde kan du hjälpa Rok Orhan från Camp Mojache att lära sig mer om Gordunni och planera deras fall."},sec={{t="En magikers klot",b="Rok Orhan i Camp Mojache söker efter en Gordunni Orb för att lära sig mer om Gordunni och deras magi. Klotet tas från en av Gordunnis magikerherrar. Dess kraft kan hjälpa till att avslöja syftet med deras mörka ceremoni."},{t="I Orgrimmar",b="Rok Orhan skickar Gordunni Orb till Uthel'nay vid Darkbriar Lodge i Orgrimmar. Uthel'nay känner igen dess stora kraft och varnar för att den är farlig."}},faq={{q="Vad är Gordunni Orb?",a="Gordunni Orb är ett mäktigt magiskt föremål som innehas av Gordunnis magikerherrar i Feralas.",al={"gordunni orb","vilket klot","magikerns klot"}},{q="Vem vill ha klotet?",a="Rok Orhan i Camp Mojache söker efter klotet för att lära sig mer om Gordunni och deras magi.",al={"vem vill ha klotet","rok orhan klot","camp mojache klot"}},{q="Vad används klotet till?",a="Rok Orhan hoppas att klotets kraft ska hjälpa till att avslöja mer om Gordunnis mörka ceremoni.",al={"klotets syfte","varför behövs klotet","vad gör det"}},{q="Vem kan undersöka klotet?",a="Uthel'nay vid Darkbriar Lodge i Orgrimmar kan berätta mer om klotet.",al={"vem undersöker klotet","uthel'nay","klot magiker"}},{q="Varför är klotet farligt?",a="Uthel'nay säger att Gordunni Orb är mycket kraftfull och farlig.",al={"klotets fara","farligt klot","är det kraftfullt"}}},fp="12,141,12.213.0,12.147.0,25.85.0,18.89.0,25.89.0,24.70.0,25.63.0"}
P.entries["item:gorishi-queen-brain"] = {n="Gorishi Queen Brain",s="Gorishi Queen Brain är ett prov från drottningen i Slithering Scar. Forskarna i Gadgetzan vill studera silithiderna och kraften som kanske styr dem.",h="Gorishi Queen Brain är ett prov från drottningen i Slithering Scar.",kw={"gadgetzan","gorishi","gorishi hive queen","gorishi queen brain","kupkristall","ondskefull intelligens","silithider","the slithering scar","un'goro crater"},sec={{t="En hjärna att studera",b="Forskarna i Gadgetzan söker Gorishi Queen Brain efter att Gorishi Hive Queen lockats fram ur sin kammare i södra Un'Goro Crater. De misstänker att silithiderna lyder en ondskefull intelligens och hoppas att drottningens hjärna ska hjälpa dem att förstå den. Deras upptäckter kan avslöja mer om kupan än om bara dess drottning."}},faq={{q="Vad är Gorishi Queen Brain?",a="Gorishi Queen Brain är ett prov från Gorishi Hive Queen, avsett för forskarna i Gadgetzan att studera.",al={"drottninghjärna","gorishi-hjärna","vad är den här hjärnan"}},{q="Var kommer Gorishi Queen Brain ifrån?",a="Den kommer från Gorishi Hive Queen i Slithering Scar, i södra Un'Goro Crater.",al={"varifrån kommer hjärnan","drottninghjärnans plats","gorishi-drottning"}},{q="Varför vill forskarna ha drottningens hjärna?",a="Forskarna i Gadgetzan hoppas att hjärnan ska hjälpa dem förstå silithiderna och den ondskefulla intelligens som de misstänker kanske styr dem.",al={"varför behövs hjärnan","vad ska hjärnan användas till","studera drottningen"}},{q="Hur lockas Gorishi Hive Queen fram?",a="En Gorishi Queen Lure som används på en kristall i kupans kläckerier är tänkt att locka fram drottningen.",al={"locka fram drottningen","gorishi-lure","hur får man ut drottningen"}},{q="Är drottningen den enda silithidförekomsten?",a="Forskarna tvivlar på att Gorishi Hive Queen visar hela omfattningen av silithidernas närvaro.",al={"fler silithider","finns silithiderna kvar","är det allt"}}},fp="19,174,15.327.0,32.110.0,45.88.0,42.137.0,39.95.0,40.97.0"}
P.entries["item:gorishi-queen-lure"] = {n="Gorishi Queen Lure",s="Gorishi Queen Lure är ett verktyg som används för att locka Gorishi Hive Queen ut ur hennes kammare i Un'Goro Crater. Forskare i Gadgetzan behöver drottningens hjärna för att studera silithiderna.",h="Gorishi Queen Lure är ett verktyg som används för att locka Gorishi Hive Queen ut ur hennes kammare i Un'Goro...",kw={"gadgetzan","gorishi","gorishi hive","gorishi queen lure","kupans kristall","drottning","drottningens hjärna","silithider","un'goro crater"},sec={{t="En kupa rörs",b="I Gorishi Hive i Un'Goro Crater tros en kristall stämma silithiderna överens genom hela deras nätverk av kupor. Locket används på kristallen för att locka fram drottningen. Forskare i Gadgetzan vill ha hennes hjärna för att studera den, eftersom de fruktar att en illvillig intelligens kan styra silithiderna."}},faq={{q="Vad gör Gorishi Queen Lure?",a="Gorishi Queen Lure används på en kristall i Gorishi Hive för att locka fram Gorishi Hive Queen.",al={"användning av drottninglocket","syftet med gorishi-locket","hur locket fungerar"}},{q="Var används locket?",a="Locket används på en kristall i kläckerierna i Gorishi Hive i Un'Goro Crater.",al={"var drottninglocket används","lockets plats","var gorishi-kupan finns"}},{q="Vem tillhandahöll locket?",a="Forskare i Gadgetzan tillhandahåller Gorishi Queen Lure så att drottningen kan lockas fram för studier.",al={"vem som gav locket","varifrån locket kom","gadgetzan-locket"}},{q="Varför vill forskarna ha drottningens hjärna?",a="Forskarna behöver Gorishi Hive Queens hjärna för att studera silithiderna och undersöka om en illvillig intelligens styr dem.",al={"varför drottningens hjärna","varför gorishis hjärna behövs","vad hjärnan är till för"}},{q="Vad är kristallen i kupan?",a="Man tror att kristallen stämmer silithiderna överens genom hela deras nätverk av kupor.",al={"kupans kristall","silithidernas kristall","vad kristallen gör"}}},fp="18,175,14.272.0,36.99.0,23.86.0,22.96.0,42.134.0,32.73.0"}
P.entries["item:grape-manifest"] = {n="Grape Manifest",s="På Northshire Abbey registrerar Grape Manifest druvor som bärgats från Milly Osworths vingård efter att banditer lagt beslag på skörden. Frukten är på väg till klostrets källare.",h="På Northshire Abbey registrerar Grape Manifest druvor som bärgats från Milly Osworths vingård efter att...",kw={"brother neals","elwynn","grape manifest","milly osworth","northshire abbey","vingård","vin"},ang={["profession:Cooking"]="För kockar visar förteckningen hur skördar från fälten förser klostrets förråd och hjälper till att mätta dess munkar.",["race:Human"]="Som människa kan du se de tidiga prövningarna i Stormwinds hjärtland: även klosterliv och enkla skördar behöver väpnat försvar mot kringströvande laglösa."},sec={{t="En förteckning över skörden",b="Milly Osworth sköter en vingård i Northshire Valley, där de lokala gårdarna hjälper till att försörja Northshire Abbey. Defias-banditer lade beslag på skörden, vilket hotade klostrets tillgång på färsk frukt och druvor för jäsning. Grape Manifest registrerar druvorna som återtagits från fälten och deras mängd, så att klostrets förrådsförvaltare kan hålla räkning på förråden och förbereda tunnor för jäsning."},{t="Klostrets källarmästare",b="Brother Neals ansvarar för mat och dryck på Northshire Abbey, och han tycker om att provsmaka dess vin i klocktornets stillhet. Förteckningen talar om för honom att druvorna är på väg och hjälper till att se till att munkar och rekryter på besök har något att dricka. För klostrets bröder är varje räddad skäppa en seger för förråden och en välsignelse från det Heliga Ljuset."}},faq={{q="Vad är Grape Manifest?",a="Grape Manifest är en förteckning skriven av Milly Osworth som registrerar skörden som bärgats från hennes överfallna vingård. Den håller reda på de färska druvorna som levereras till Northshire Abbey.",al={"vad är grape manifest","föremålet grape manifest"}},{q="Vem tar emot förteckningen?",a="Brother Neals tar emot förteckningen. Han ansvarar för klostrets mat- och vinförråd och provsmakar ofta årgångar i klocktornet på Northshire Abbey.",al={"vem får grape manifest","vem ska jag ge grape manifest till","vart ska grape manifest"}},{q="Varför var druvorna i fara?",a="Defias-banditer slog till i Northshire Valley och drev bort Milly Osworth från hennes vingård. Skörden hotades och klostret blev utan färsk frukt tills rekryterna ingrep.",al={"varför behövde druvorna räddas","banditer vid vingården","vad hände med millys skörd"}},{q="Vad gör Brother Neals med druvorna?",a="Brother Neals använder druvorna för att fylla på klostrets matförråd och jäsa färskt Northshire-vin åt brödraskapet som bor där och försvarare på besök.",al={"vad används druvor till","klostervin"}}},fx={a2f30a46={q="Var kommer Grape Manifest ifrån, och vem skrev det?",a="Milly Osworth, en bonde som arbetar i Northshire Valleys vingårdar, upprättar manifestet. När du har hjälpt henne att driva bort Defias-rövarna som intog hennes fält och återta den skördade druvan, sammanställer hon dokumentet för att redovisa den räddade skörden.",al={"vem skrev grape manifest","varifrån kommer grape manifest","grape manifests ursprung"}},cbb35726={q="Varför behövs Grape Manifest?",a="Brother Neals sköter mat- och dryckesförråden vid Northshire Abbey. Milly skickar manifestet för att meddela honom att hennes skörd har räddats från banditerna, så att klostrets vinmakare kan räkna med färska druvor till vintillverkningen.",al={"varför vill brother neals ha grape manifest","grape manifests syfte","varför behövs grape manifest"}}},fp="14,104,23.282.0,20.303.0,27.142.0,26.154.0,30.162.0,43.168.0"}
P.entries["item:gray-bear-tongue"] = {n="Gray Bear Tongue",s="En gråbjörnstunga är en rå ingrediens som skördas från vildbjörnarna i Hillsbrad Foothills. Royal Apothecary Society i Tarren Mill efterfrågar den som biologisk beståndsdel i sina experimentella gifter.",h="En gråbjörnstunga är en rå ingrediens som skördas från vildbjörnarna i Hillsbrad Foothills.",kw={"apothecary lydon","big samras","elixir of suffering","gray bear tongue","hillsbrad foothills","royal apothecary society","tarren mill"},ang={["race:Undead"]="Att skaffa organiska ingredienser från det lokala djurlivet hjälper Royal Apothecary Society direkt i dess uppdrag att skapa nya plågor mot de levande."},sec={{t="Apotekarstudier i Hillsbrad",b="Den otämjda vildmarken kring Tarren Mill är rik på inhemsk fauna, däribland flera sorters kraftiga gråbjörnar. Naturliga rovdjur utgör ett ständigt hot mot resande, men Forsaken ser dem som en skördekälla för råa alkemiska ingredienser. Apothecary Lydon studerar det lokala djurlivet för att isolera potenta organiska ämnen och använder den tjocka muskelvävnaden och vätskorna från gråbjörnstungor som basingredienser i dödliga brygder, såsom Elixir of Suffering."}},faq={{q="Vem vill ha gråbjörnstungor?",a="Apothecary Lydon, stationerad vid Forsaken-utposten Tarren Mill i Hillsbrad Foothills, söker tungorna för att brygga experimentella dödsmedel.",al={"vem behöver björntungor","apothecary lydon tungor","lämna in björntunga"}},{q="Vad ska apotekaren använda tungorna till?",a="Lydon utvecklar en dödlig brygd kallad Elixir of Suffering, avsedd att hjälpa till att hemsöka Hillsbrads levande människobefolkning med pest. Tungorna är ett av de viktigaste organiska ämnena, tillsammans med Creeper Ichor.",al={"varför vill lydon ha tungor","björntungans syfte","ingredienser i elixir of suffering"}},{q="Vilka varelser lämnar efter sig tungorna?",a="De kan skördas från alla lokala gråbjörnar i Hillsbrad Foothills, däribland vanliga gråbjörnar, äldre gråbjörnar, våldsamma gråbjörnar och det ökända odjuret Big Samras.",al={"var får man björntungor","vilka björnar har tungor","björnar i hillsbrad"}}},fx={["57051fe5"]={q="Vad är Gray Bear Tongue?",a="Det är precis vad det låter som: en färskt utskuren tunga från en av de vilda gråbjörnar som strövar omkring i Hillsbrad Foothills. De flesta resenärer tycker att det är motbjudande, men alkemister och forskare bland de Fördömda värdesätter djurvävnad för dess särskilda kemiska egenskaper när de blandar nya brygder.",al={"vad är gray bear tongue","föremålet gray bear tongue","vad är gray bear tongues"}},["4de594f1"]={q="Var kommer en Gray Bear Tongue ifrån?",a="Tungorna tas direkt från gråbjörnarna som strövar i skogarna och kullarna kring Tarren Mill i Hillsbrad Foothills. Jägare kan få dem från vanliga gråbjörnar, äldre exemplar, våldsamma varianter eller namnkunniga bestar som Big Samras.",al={"gray bear tongues ursprung","varifrån kommer gray bear tongues","vem släpper gray bear tongues"}}},fp="16,112,32.187.0,28.112.0,47.207.0,35.162.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-i"] = {n="Green Hills of Stranglethorn - Chapter I",s="Lösa sidor ur The Green Hills of Stranglethorn har samlats till kapitel I. Barnil sammanställer kapitlen till Master Nesingwarys manuskript.",h="Lösa sidor ur The Green Hills of Stranglethorn har samlats till kapitel I.",kw={"barnil","kapitel i","kapitel ett","green hills of stranglethorn","manuskript","master nesingwary","utspridda sidor","stranglethorn"},sec={{t="Lösa sidor",b="En vindby svepte genom Master Nesingwarys läger och spred sidorna ur hans manuskript över Stranglethorn. Barnil samlade in många, men det saknades fortfarande sidor till alla fyra kapitlen. Det här kapitlet hör till boken som Barnil sätter ihop, och han är redo att ordna sidorna när de har hittats."}},faq={{q="Vad är kapitel I?",a="Kapitel I är en av de fyra delarna av Master Nesingwarys utspridda manuskript, The Green Hills of Stranglethorn.",al={"green hills kapitel ett","kapitel i bok","vad är det här kapitlet"}},{q="Vem är Barnil?",a="Barnil hjälper till att sammanställa Master Nesingwarys manuskript och ber om kapitlen när de är färdiga.",al={"barnil vem","vem vill ha sidorna","barnils manuskript"}},{q="Varför ligger sidorna utspridda?",a="En kraftig vindby drog genom Master Nesingwarys läger och spred sidor ur manuskriptet över djungeln.",al={"sidor blåste bort","varför saknas sidor","manuskriptsidor"}},{q="Vem skrev The Green Hills of Stranglethorn?",a="Master Nesingwary är författaren till The Green Hills of Stranglethorn, en roman som Barnil hjälper till att sammanställa.",al={"nesingwarys bok","vem skrev green hills","master nesingwarys manuskript"}}},fp="40,160,15.305.0,18.115.0,14.109.0,28.117.0,43.104.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-ii"] = {n="Green Hills of Stranglethorn - Chapter II",s="Kapitel två är en av fyra delar av Master Nesingwarys utspridda manuskript, The Green Hills of Stranglethorn. Sidorna måste samlas in så att Barnil kan sätta ihop kapitlen och återlämna boken till Nesingwary.",h="Kapitel två är en av fyra delar av Master Nesingwarys utspridda manuskript, The Green Hills of Stranglethorn.",kw={"barnil","kapitel två","green hills of stranglethorn","manuskript","nesingwary","utspridda sidor","stranglethorn"},sec={{t="Utspridda sidor",b="Barnil hade samlat in det mesta av manuskriptet när en vindby drog genom Master Nesingwarys läger. Sidorna från kapitel två spreds över Stranglethorn tillsammans med resten. Du kan hjälpa Barnil att ordna de fyra kapitlen och sedan bära tillbaka dem till honom."}},faq={{q="Vad är kapitel två?",a="Kapitel två är en del av Master Nesingwarys manuskript, The Green Hills of Stranglethorn.",al={"kapitel två","green hills kapitel två"}},{q="Vem samlar in kapitlen?",a="Barnil samlar in och ordnar de utspridda kapitlen åt Master Nesingwary.",al={"vem vill ha sidorna","barnils sidor"}},{q="Varför är sidorna utspridda?",a="En kraftig vindby drog genom Master Nesingwarys läger och spred manuskriptets sidor genom djungeln.",al={"vad hände med sidorna","vinden blåste bort sidorna"}},{q="Vad ska jag göra med kapitlen?",a="Samla in alla fyra kapitlen och återlämna dem till Barnil så att han kan ordna dem åt Master Nesingwary.",al={"var återlämna kapitlen","vad behöver barnil"}},{q="Vem skrev The Green Hills of Stranglethorn?",a="Master Nesingwary är författaren till The Green Hills of Stranglethorn.",al={"nesingwarys bok","master nesingwarys roman"}}},fp="41,210,15.253.0,19.93.0,30.81.0,28.116.0,35.97.0,43.68.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iii"] = {n="Green Hills of Stranglethorn - Chapter III",s="Kapitel III är en av fyra utspridda delar av Master Nesingwarys manuskript Green Hills of Stranglethorn. Barnil samlar in sidorna vid lägret i Stranglethorn Vale.",h="Kapitel III är en av fyra utspridda delar av Master Nesingwarys manuskript Green Hills of Stranglethorn.",kw={"barnil","chapter iii","kapitel tre","green hills of stranglethorn","manuskript","nesingwary","utspridda sidor","stranglethorn vale"},sec={{t="Utspridda sidor",b="En vindstöt svepte genom Master Nesingwarys läger i Stranglethorn Vale och spred manuskriptets sidor genom djungeln. Barnil samlade de flesta, men de fyra kapitlen är fortfarande ofullständiga. Han samlar in sidorna så att manuskriptet kan sättas i ordning."}},faq={{q="Vad är Chapter III?",a="Chapter III är en av de fyra delarna av Master Nesingwarys utspridda manuskript Green Hills of Stranglethorn.",al={"kapitel tre","green hills kapitel 3"}},{q="Vem samlar in sidorna?",a="Barnil samlar in de utspridda sidorna och ordnar kapitlen åt Master Nesingwary.",al={"vem vill ha sidorna","barnils sidor"}},{q="Varför är sidorna utspridda?",a="En kraftig vindstöt drog genom Master Nesingwarys läger och spred manuskriptets sidor över djungeln.",al={"vad hände med sidorna","vinden blåste bort sidorna"}},{q="Vad heter manuskriptet?",a="Manuskriptet heter Green Hills of Stranglethorn.",al={"nesingwarys bok","green hills-boken"}}},fp="42,178,15.266.0,20.117.0,28.90.0,28.114.0,30.58.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iv"] = {n="Green Hills of Stranglethorn - Chapter IV",s="I Stranglethorn Vale behöver Barnil de spridda kapitlen ur Master Nesingwarys manuskript samlade och ordnade. Kapitel IV är en av de fyra delar som behövs för att färdigställa boken.",h="I Stranglethorn Vale behöver Barnil de spridda kapitlen ur Master Nesingwarys manuskript samlade och ordnade.",kw={"barnil","kapitel fyra","kapitel iv","green hills of stranglethorn","manuskript","master nesingwary","spridda sidor","stranglethorn vale"},sec={{t="Spridda sidor",b="En vindby drog genom Master Nesingwarys läger och spred sidor ur hans roman över djungeln. Barnil samlade ihop de flesta, men de saknade sidorna måste fortfarande samlas in och ordnas i fyra kapitel. Kapitel IV hör ihop med de tre andra innan manuskriptet kan återlämnas till Barnil."}},faq={{q="Vad är kapitel IV?",a="Kapitel IV är ett av de fyra kapitlen i Master Nesingwarys roman Green Hills of Stranglethorn.",al={"kapitel fyra","green hills kapitel iv","kapitel fyra bok"}},{q="Vem behöver det här kapitlet?",a="Barnil samlar ihop kapitlen ur Master Nesingwarys manuskript och ber om dem när alla fyra är färdiga.",al={"vem vill ha kapitel iv","vem ska ha kapitel fyra","barnils sidor"}},{q="Varför är sidorna utspridda?",a="En kraftig vindby drog genom Master Nesingwarys läger och spred sidor ur hans manuskript runt om i djungeln.",al={"varför sidor överallt","vad hände med boken","vinden blåste bort sidorna"}},{q="Vad handlar Green Hills of Stranglethorn om?",a="Det är en roman av Master Nesingwary. De insamlade kapitlen ska färdigställa manuskriptet.",al={"nesingwarys roman","green hills bok","vad är manuskriptet"}}},fp="41,192,15.301.0,19.104.0,23.114.0,28.119.0,47.95.0"}
P.entries["item:gregor-s-remains"] = {n="Gregor's Remains",s="Gregor's Remains är de fysiska benen som återfanns efter Gregor Agamand, som Scourge hade gjort till sin slav. Hans kvarlevor söks av en före detta mjölnare som vill göra upp en gammal räkning från andra sidan graven.",h="Gregor's Remains är de fysiska benen som återfanns efter Gregor Agamand, som Scourge hade gjort till sin slav.",kw={"agamand","brill","coleman","dödsfall i familjen","farthing","gregor","kvarnar","kvarlevor","scourge"},ang={["faction:Horde"]="När du rensar Agamand Mills tillfogar du Scourges kvarvarande härdar ett direkt slag och skyddar Tirisfal Glades säkerhet.",["race:Undead"]="Agamand-familjens tragedi speglar många Forsakens öde: vanligt folk som förråddes av adelns stolthet och lämnades åt pestens fasor."},sec={{t="Ett arv av förödelse",b="Före det tredje kriget hade familjen Agamand enorma rikedomar och stora landområden i norra Tirisfal Glades. När Scourge invaderade Lordaeron valde familjens överhuvuden stolthet framför flykt. De befäste familjens kvarnar och övertalade sina trogna arbetare att göra ett desperat motstånd mot de odöda. Försvaret misslyckades fullständigt. Godset blev översvämmat av fiender, och de som stannade kvar slaktades och återuppväcktes som odöda. Gregor Agamand blev ännu en viljelös träl i Lich Kings tjänst och hemsökte kvarnarna som familjen en gång styrde."},{t="Hämndens pris",b="För överlevare som slet sig loss från Lich Kings grepp och anslöt sig till Forsaken är minnet av det ödesdigra försvaret fortfarande ett bittert sår. Coleman Farthing, en före detta mjölnare stationerad i Brill, anklagar familjen Agamands högmod för att ha fångat hans själ i evig förruttnelse. Om Farthing får samla in Gregor's Remains får han en personlig hämnd och kan sätta punkt för historien om en herre som ledde sitt hushåll rakt in i fördärvet."}},faq={{q="Vem var Gregor Agamand?",a="Gregor Agamand var en framstående medlem av dynastin Agamand, den rikaste jordägande familjen i Tirisfal Glades före det tredje kriget. När de odödas pest kom valde han och hans familj att befästa sitt gods i stället för att fly. Alla där inne slaktades och återuppväcktes.",al={"gregors historia","vem är gregor","gregor agamand"}},{q="Varför vill Coleman Farthing ha Gregor's Remains?",a="Coleman Farthing arbetade som mjölnare åt familjen Agamand när han levde. Han hyser djupt agg mot familjen för att de övertalade arbetarna att stanna och kämpa mot Scourge, ett ödesdigert misstag som dömde dem alla till att bli odöda. Att få Gregors kvarlevor överlämnade till sig blir en hämnd som länge fått vänta.",al={"varför coleman vill ha kvarlevorna","coleman farthings agg","varför samla gregors ben"}},{q="Var hittar man Gregor's Remains?",a="Kvarlevorna återfinns hos den återuppväckte Gregor Agamand vid Agamand Mills, i Tirisfal Glades norra kullar.",al={"var hittar man gregor","gregors plats","gregor vid agamand mills"}},{q="Tillhör familjen Agamand Forsaken?",a="Nej. Till skillnad från Forsaken, som slet sig fria under drottning Sylvanas, är Gregor Agamand och hans släkt fortfarande viljelösa tjänare, bundna till Scourges vilja.",al={"är gregor forsaken","är agamand en del av scourge","vem styr gregor"}}},fx={["6dd1de2a"]={q="Vad är Gregor's Remains?",a="De är de fysiska kvarlevorna efter Gregor Agamand, en av arvingarna till den framstående Agamand-dynastin. Efter att ha fallit offer för de odödas pest återuppstod Gregor som en viljelös hantlangare åt Scourge och hemsökte ruinerna av familjens en gång så blomstrande kvarnar tills han slutligen besegrades.",al={"vad är gregors remains","föremålet gregors remains"}},["45ae8d93"]={q="Var kommer Gregor's Remains ifrån?",a="De här kvarlevorna är det som återstår av Gregor Agamand efter att han fällts vid Agamand Mills i västra Tirisfal Glades. När Scourge svepte genom Lordaeron befäste hans familj sitt gods och uppmanade arbetarna att stanna och kämpa, men alla slaktades och återuppväcktes som odöda.",al={"ursprunget till gregor's remains","vem skapade gregor's remains","var kom gregor's remains ifrån"}}},fp="16,123,16.482.0,22.346.0,23.279.0,48.232.0,33.109.0,38.134.0"}
P.entries["item:grelin-s-report"] = {n="Grelin's Report",s="Grelin's Report är en rapport skriven av Grelin Whitebeard om Frostmane-trollens situation i Coldridge Valley. Den anförtros åt en äventyrare i stället för en novislärling och utgör den officiella länken mellan spejarna som vaktar Anvilmar och Senir Whitebeard, som är stationerad i Kharanos.",h="Grelin's Report är en rapport skriven av Grelin Whitebeard om Frostmane-trollens situation i Coldridge Valley.",kw={"coldridge valley","grelin whitebeard","grelin's report","ironforge-senaten","kharanos","mountaineer thalos","senir whitebeard"},ang={["race:Dwarf"]="Att bära rapporten är en dvärgs färd från Coldridges trygga övningsmarker till det vidare försvaret av Dun Moroghs kärnland och tjänsten hos Ironforge.",["race:Gnome"]="När du levererar Grelins meddelande får gnomiska flyktingar visa sitt mod för dvärgarnas bergsvakter medan de färdas genom de gemensamma bergspassen i Dun Morogh."},sec={{t="En rapport förbi troggarna",b="Efter att ha bevakat Frostmane-trollen i Coldridge Valley drar Grelin's Report slutsatsen att de inte utgör något större hot och kan hanteras av Mountaineers som redan är stationerade där och av legosoldater som betalas med medel från senaten. I stället för att anförtro sin fumlande lärling denna viktiga underrättelse tar Grelin hjälp av en kapabel resenär som kan föra dokumentet genom det trogginfekterade Coldridge Pass. Papperet fungerar som ett officiellt pass genom Mountaineer Thalos' vägspärr och bevisar att bäraren är på brådskande uppdrag i den vidsträckta snöiga vildmarken i Dun Morogh."},{t="Upprörda känslor i Kharanos",b="När rapporten överlämnas till Senir Whitebeard på Thunderbrew Distillery i Kharanos innehåller den viktiga fältrapporter som är avsedda för Ironforge. Senir konstaterar med road uppgivenhet att hans bror åberopade King Magni Bronzebeard flitigt i texten. Grelin hävdar att kungen har godkänt insatsen, och Senir räknar med att vädjan till kunglig auktoritet kommer att uppröra några i Ironforge-senaten."}},faq={{q="Vad är syftet med Grelin's Report?",a="Rapporten förmedlar Grelin Whitebeards bedömning av Frostmane-trollen från Coldridge Valley till hans bror Senir i Kharanos. Den försäkrar ledarna utanför dalen om att trollen inte utgör något större hot och kan hanteras av lokala Mountaineers och legosoldater som betalas av senaten.",al={"vad är grelins rapport","varför skicka rapporten","grelin rapport syfte"}},{q="Varför kan Grelin inte överlämna den själv?",a="Grelin är kvar i Coldridge Valley och bevakar trollen. Han övervägde först att skicka sin lärling, men den farliga färden genom den trogginfekterade tunneln fick honom att i stället anförtro de viktiga dokumenten åt en stridsvan äventyrare.",al={"varför inte överlämna den","varför anförtro den åt en äventyrare"}},{q="Varför låter Mountaineer Thalos dig passera med rapporten?",a="Mountaineer Thalos vaktar tunneln ut ur Coldridge Valley för att skydda civila från våldsamma troggar. Att du har Grelin's Report visar att du färdas i ett brådskande ärende som rör dvärgarnas försvar, och övertygar Thalos om att släppa igenom dig.",al={"varför släpper thalos igenom mig","vägspärr i tunneln","troggar i coldridge pass"}},{q="Varför är Ironforge-senaten irriterad på rapporten?",a="Senir Whitebeard påpekar att Grelin åberopade King Magni flitigt i dokumentet. Att kringgå vanlig diplomatisk finkänslighet för att kräva kunglig uppmärksamhet gör ofta byråkraterna i Ironforge-senaten arga, även om bröderna håller med om att politikerna behöver en väckarklocka.",al={"varför är senaten arg","upprörda känslor","senirs reaktion"}}},fx={cdcce173={q="Vad är Grelin's Report?",a="Det är en skriftlig rapport som Grelin Whitebeard skrev i Coldridge Valley, adresserad till hans bror Senir Whitebeard i Kharanos. Den beskriver lokala iakttagelser och angelägna frågor i dalen, men Grelin åberopade King Magni Bronzebeards namn så frikostigt i texten att det väckte kontrovers bland senatorerna i Ironforge.",al={"vad är grelin's report","grelin's report"}},["9a092709"]={q="Var kommer Grelin's Report ifrån, och vem skrev den?",a="Dokumentet skrevs av Grelin Whitebeard när han var stationerad i Coldridge Valley. I stället för att anförtro det åt sin lärling bestämde sig Grelin för att lägga det i händerna på en kapabel resenär, så att det säkert skulle färdas österut genom den troggangripna tunneln som leder vidare in i Dun Morogh.",al={"vem skrev grelin's report","var kom grelin's report ifrån","vem skapade grelin's report"}},["6be6ebf1"]={q="Varför vill någon ha Grelin's Report?",a="Hans bror, Senir Whitebeard, väntar på rapporten i Kharanos för att samordna deras fynd innan de skickar sina gemensamma rapporter till Ironforge. Dokumentet är också viktigt för dig personligen: bevis på officiella Whitebeard-ärenden är det enda som får Mountaineer Thalos att låta dig passera genom den farliga, troggdrabbade tunneln ut ur Coldridge Valley.",al={"varför behövs grelin's report","varför vill senir ha grelin's report"}}},fp="15,155,26.493.0,29.370.0,39.233.0,36.218.0,57.195.0,50.236.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Grelin Whitebeard's Journal",s="Grelin Whitebeard's Journal är en personlig fältjournal som dvärgspanaren Grelin Whitebeard förde i Coldridge Valley. Den innehåller viktiga anteckningar om de lokala Frostmane-trollens aktiviteter. Frostmane-besten Grik'nir the Cold stal journalen och släpade den till trollgrottan i Coldridge Valley.",h="Grelin Whitebeard's Journal är en personlig fältjournal som dvärgspanaren Grelin Whitebeard förde i Coldridge...",kw={"coldridge valley","dun morogh","frostmane hold","grelin whitebeard","grik'nir the cold","senir whitebeard","stulen journal"},ang={["race:Dwarf"]="När journalen återtas säkras viktiga underrättelser åt dvärgarna om hotet från Frostmane-trollen, som närmar sig själva portarna till Ironforges övningsområden."},sec={{t="En spanares journal",b="När Grelin Whitebeard iakttog Frostmane-trollens aggressiva rörelser nära Coldridge Valley antecknade han noggrant sina iakttagelser i den här läderbundna journalen. Dokumentet innehåller hans råa fältobservationer om de inhemska vintertrollens styrka, organisation och hotnivå. Under en konfrontation eller ett bakhåll ryckte dock Grik'nir the Cold, en kraftigt märkt trollbest, åt sig journalen. Grelin tvingades därför be äventyrare på genomresa att söka igenom trollgrottan och ta tillbaka den innan han kunde färdigställa sin rapport."},{t="Meddelande till Senir",b="När Grelin återfår anteckningarna ur Grik'nirs grepp ger de honom tillräcklig trygghet för att bedöma hotet från trollen i Coldridge Valley som tillfälligt under kontroll. Med hjälp av de återfunna anteckningarna färdigställer Grelin sitt skriftliga meddelande om Frostmane-upproret. Det förseglas sedan och anförtros åt kurirer på väg till hans bror Senir Whitebeard, som är stationerad längre bort i Dun Morogh."}},faq={{q="Vem stal Grelin Whitebeards journal?",a="Journalen togs av Grik'nir the Cold, en framstående och kraftigt märkt Frostmane-trollbest som håller till djupt inne i trollgrottan i Coldridge Valley.",al={"vem tog journalen","vem har grelins journal","tjuven som stal grelins journal"}},{q="Vad står det i journalen?",a="Journalen innehåller Grelin Whitebeards egna spaningsanteckningar om de lokala Frostmane-trollen, deras hotnivå och säkerhetsläget i Coldridge Valley.",al={"journalens innehåll","vad finns i journalen","grelin whitebeards anteckningar"}},{q="Vad händer när journalen återfås?",a="När Grelin har hämtat sin journal använder han anteckningarna för att skriva en färdig underrättelserapport om trollens situation. Sedan ber han en äventyrare att leverera den till hans bror Senir Whitebeard.",al={"vad gör grelin med journalen","efter den stulna journalen"}},{q="Varför är journalen så viktig för Grelin?",a="Utan journalen kan Grelin inte sammanställa en korrekt spaningsrapport om Frostmane-upproret åt dvärgarnas myndigheter och sin bror Senir. Då är försvaret av Coldridge Valley osäkert.",al={"varför vill grelin ha tillbaka den","journalens betydelse"}}},fx={["15978139"]={q="Vad är Grelin Whitebeard's Journal?",a="Det är en personlig anteckningsbok som förs av Grelin Whitebeard, en observatör stationerad i Coldridge Valley. Där antecknar Grelin sina iakttagelser om Frostmane-trollens aktiviteter i området och sammanställer fältrapporter om dalens försvarsläge.",al={"vad är grelin whitebeard's journal","grelin's journal","grelins anteckningsbok"}},["9ed18e74"]={q="Var kommer Grelin Whitebeard's Journal ifrån, och vem skrev den?",a="Journalen sammanställdes av dvärgen Grelin Whitebeard under hans bevakning av Coldridge Valley. Men den rycktes ifrån honom och bars djupt in i den närliggande trollgrottan av Frostmane-bjässen Grik'nir the Cold.",al={"vem skapade grelin's journal","var kom grelin's journal ifrån","grelin's journals ursprung"}}},fp="27,163,16.436.0,17.302.1,38.142.0,31.134.0,44.133.1,43.198.0"}
P.entries["item:grell-earring"] = {n="Grell Earring",s="I Bashal'Aran bär Grell Earring spår av sigillet som binder Asterion.",h="I Bashal'Aran bär Grell Earring spår av sigillet som binder Asterion.",kw={"asterion","bashal'aran","darkshore","grell earring","sigill","vile sprite","wild grell"},ang={["class:Mage"]="Som magiker kan du se hur metall med tiden kan bevara den omgivande magin från uråldriga skyddssigill.",["race:NightElf"]="Som Night Elf ser du heliga ruiner översvämmade av feer som bär upphittad mässing, en påminnelse om förfallet på det forntida Kalimdors en gång storslagna egendomar."},sec={{t="Spår i mässingen",b="Wild Grells och Vile Sprites i Bashal'Aran samlar skrot bland ruinerna och gör örhängen av det. De flesta dödliga ser bara värdelöst krimskrams. Asterion, en uråldrig Night Elf som är bunden där som en plågad vålnad, studerar magin som dröjer sig kvar på örhängena. Han hoppas att spåren ska leda honom till det uråldriga sigill som håller honom fången."}},faq={{q="Var kommer Grell Earring ifrån?",a="Wild Grells och Vile Sprites i den förfallna Night Elf-bosättningen Bashal'Aran i Darkshore bär örhängena.",al={"grell earring byte","var får man tag på grell earrings","vem släpper grell earrings"}},{q="Varför vill Asterion ha de här örhängena?",a="Asterion är en uråldrig ande som hålls fången i Bashal'Aran av mäktig magi. Han använder örhängena för att söka efter spår av sigillet som har bundit hans själ i århundraden.",al={"asterions örhängen","varför samla grell earrings","vad används grell earring till"}},{q="Hur hjälper örhängena Asterion att söka efter sigillet?",a="Asterion hoppas kunna kasta en besvärjelse över örhängena och spåra sigillet som håller hans spöklika gestalt fången i Bashal'Aran.",al={"är örhängena magiska","kan grell använda magi"}},{q="Hittar Asterion det han behöver med hjälp av örhängena?",a="Sigillet finns inte i örhängena. Spåren på dem visar att varelserna nyligen har varit nära det, vilket leder Asterions sökande djupare in bland ruinerna.",al={"fungerade örhängena","asterions sigillplats"}}},fx={f6dd1a4f={q="Vad är ett Grell Earring?",a="Ett Grell Earring är ett enkelt smycke som bärs av de vilda grells och vidriga sprites som hemsöker ruinerna vid Bashal'Aran i Darkshore. De här upphittade örhängena är vanliga prydnader i sig, men har absorberat svaga magiska utsöndringar från ruinerna och från reliker som varelserna har hanterat.",al={"vad är grell earrings","grell earring-lore","vad är grell earring"}}},fp="13,75,19.322.0,34.120.0,38.141.0,54.116.0,51.146.0"}
P.entries["item:grenka-s-claw"] = {n="Grenka's Claw",s="Grenka's Claw är en fysisk trofé som tagits från den mäktiga harpyan Grenka Bloodscreech i djupet av Roguefeather Den. När den överlämnas till Dorn Plainstalker vid The Weathered Nook är den ett obestridligt bevis på att en blivande äventyrare har klarat ett utmattande fysiskt prov högt uppe i ravinen.",h="Grenka's Claw är en fysisk trofé som tagits från den mäktiga harpyan Grenka Bloodscreech i djupet av...",kw={"dorn plainstalker","grenka bloodscreech","grenka's claw","harpya","roguefeather den","screeching canyon","test of endurance","thousand needles","the weathered nook"},ang={["faction:Horde"]="Att rensa Roguefeather Dens djup och göra slut på Grenka Bloodscreech minskar hotet från harpyorna som ständigt trakasserar resenärer kring Freewind Post.",["race:Tauren"]="Äldste Dorn Plainstalker ser det som sin heliga plikt att härda unga hjordekämpar med taurenriternas visdom och uthållighet innan de möter den större, hårdare världen."},sec={{t="En uthållighetstrofé",b="I Roguefeather Dens slingrande grottor, väster om Freewind Post, gömmer harpyor undan mat och försvarar våldsamt sitt revir mot främlingar. För att pröva de unga kämparnas fysiska uthållighet ger Dorn Plainstalker dem i uppgift att tränga in i de djupa boplatserna och förstöra flockens matförråd. En sådan djärv provokation väcker oundvikligen Grenka Bloodscreechs vrede. Att hugga av hennes onda klo och återvända med den bevisar att en krigare kan stå emot våg efter våg av ursinniga harpyor och överleva deras matriarks våldsamma anfall."}},faq={{q="Vad används Grenka's Claw till?",a="Klon fungerar som ett segerbevis för Dorn Plainstalker, en taurenäldste som bor vid The Weathered Nook i Thousand Needles. När du lämnar den till honom slutför du Test of Endurance och visar att du har den fysiska uthållighet som krävs för att överleva utdragen strid.",al={"användning av grenka's claw","varför behöver jag grenka's claw","grenka's claw uppdrag"}},{q="Vem är Grenka Bloodscreech?",a="Grenka Bloodscreech är en mäktig harpy som håller till i Roguefeather Den, i Screeching Canyon längs Thousand Needles södra klippor. Hon visar sig bara när inkräktare hotar flocken genom att förstöra dess matförråd.",al={"vem är grenka","grenka bloodscreech i berättelsen","vad är grenka"}},{q="Vart ska jag ta klon när jag fått tag på den?",a="Ta klon tillbaka till Dorn Plainstalker vid The Weathered Nook, inbäddat bland klipporna i Thousand Needles. Han tar emot trofén som bevis på att du har klarat ditt prov i fysisk uthållighet.",al={"var lämnar man in grenka's claw","vem vill ha grenka's claw"}},{q="Varför kräver Dorn Plainstalker just den här trofén?",a="Dorn Plainstalker vägleder unga resenärer genom krävande prov för att säkerställa att de är mentalt, andligt och fysiskt rustade för större faror. Att döda Grenka och ta hennes klo bevisar att en krigare kan uthärda både en svärms bakhåll och en dödlig ledarinnas direkta anfall.",al={"varför vill dorn ha klon","klons syfte"}}},fx={cd538a11={q="Vad är Grenka's Claw?",a="Grenka's Claw är en fysisk trofé från Grenka Bloodscreech, en mäktig harpyja som håller till djupt inne i Roguefeather Den i Screeching Canyon. Klorna höggs av den våldsamma varelsen efter att någon provocerat hennes flock och överlevt dess vrede. De är ett obestridligt bevis på att en blivande äventyrare hade orken och stridsförmågan att klara ett brutalt stridsprov.",al={"grenka's claw","vad är grenka's claw","om grenka's claw"}}},fp="13,207,21.408.0,31.187.0,27.199.0,42.163.0,55.244.0"}
P.entries["item:grimtotem-horn"] = {n="Grimtotem Horn",s="Grimtotem Horns tas från Grimtotem-tauren väster om Camp Mojache i Feralas. Krueg Skullsplitter ber om dem när han får veta att stammen finns i närheten.",h="Grimtotem Horns tas från Grimtotem-tauren väster om Camp Mojache i Feralas.",kw={"belgrom","camp mojache","feralas","grimtotem","grimtotem horn","grimtotem horns","krueg skullsplitter","tauren"},ang={["faction:Horde"]="Som resande i Horde framställer Kruegs varning Grimtotem som ett hot mot Hordes landområden och byar."},sec={{t="Tagna i Feralas",b="Väster om Camp Mojache bär Grimtotem-tauren dessa horn. Krueg Skullsplitter ber dig ta med en samling till honom när han får veta att klanen finns i Feralas. Han säger att Belgrom har utfäst en belöning för Grimtotem och varnar för att de är farliga."}},faq={{q="Var kommer Grimtotem Horns ifrån?",a="Grimtotem-tauren väster om Camp Mojache i Feralas bär hornen.",al={"varifrån hornen kommer","källa till grimtotem horn"}},{q="Vem vill ha hornen?",a="Krueg Skullsplitter i Camp Mojache ber dig ta med Grimtotem Horns till honom.",al={"vem behöver horn","kruegs horn"}},{q="Varför vill Krueg ha dem?",a="Krueg ber om hornen när han får veta att Grimtotem-tauren finns i närheten. Han säger att Belgrom intresserar sig för stammen och har utfäst en belöning för dem.",al={"varför samla horn","vad hornen är till för"}},{q="Vilka är Grimtotem?",a="Grimtotem är en taurenklan som finns väster om Camp Mojache i Feralas.",al={"vilka grimtotem är","grimtotem-tauren"}}},fp="14,150,16.239.0,35.65.0,20.74.0,25.151.0,22.70.0"}
P.entries["item:grimtotem-satchel"] = {n="Grimtotem Satchel",s="Djupt under Orgrimmar håller Maur Grimtotem fortfarande Grimtotem Satchel i sitt grepp. Troggs dödade tauren i Ragefire Chasm, men han skyddade påsen när han dog. När den återlämnas till Thunder Bluff blir Magatha Grimtotems intresse tydligt.",h="Djupt under Orgrimmar håller Maur Grimtotem fortfarande Grimtotem Satchel i sitt grepp.",kw={"elder rise","grimtotem","magatha grimtotem","maur grimtotem","ragefire chasm","rahauro","väska","thunder bluff","trogg"},ang={["faction:Horde"]="En död Grimtotem-kurir låg djupt inne i tunnlarna under Thralls huvudstad. Ragefire Chasm rymmer faror bortom sina bestar.",["race:Tauren"]="En Grimtotem begav sig djupt under Orgrimmar, och sedan nådde bud om vad han hittat Magatha på Elder Rise. Klanens förehavanden inom de förenade taurenstammarna är lågmälda och oroliga."},sec={{t="Ett dödsgrepp",b="Maur Grimtotem föll för troggs djupt inne i Ragefire Chasm, under Orgrimmar. Tauren höll fortfarande den enkla läderväskan när hans kropp hittades. Han hade kämpat för att skydda den medan troggs omringade honom. Vad kunde den innehålla som fick honom att vakta den med sitt liv?"},{t="Elder Crones intresse",b="Rahauro på Elder Rise i Thunder Bluff tar emot väskan åt Magatha Grimtotem, Grimtotemklanens matriark. Maur tjänade Magatha, och hon hade fått höra att han hittat något märkligt i grottorna under Orgrimmar innan han dog. Hon ordnade en belöning för att väskan skulle återlämnas oskadd. Grimtotemklanens ledare hade ett tydligt intresse för vad Maur hittade."}},faq={{q="Var hittar man Grimtotem Satchel?",a="Grimtotem Satchel hittades under Maur Grimtotems kropp, djupt inne i Ragefire Chasm, den vulkaniska grottan under Orgrimmar. Hans armar höll fortfarande om den där troggs dödade honom.",al={"väskans plats","var finns väskan","hur hittar man väskan"}},{q="Vem tillhör väskan?",a="Väskan tillhörde Maur Grimtotem, en medlem av Grimtotemklanen som gick in i Ragefire Chasm. Han höll den nära när troggs anföll.",al={"vem äger väskan","maur väskans ägare"}},{q="Vem vill få tillbaka väskan?",a="Rahauro på Elder Rise i Thunder Bluff tar emot väskan åt Magatha Grimtotem. Magatha ordnade en belöning för att få tillbaka sin fallne klanfrändes tillhörigheter.",al={"vem får väskan","vem lämnar in väskan","vem vill ha grimtotem satchel"}},{q="Varför bar en Grimtotem detta under Orgrimmar?",a="Maur Grimtotem tjänade Magatha Grimtotem, som intresserade sig för Ragefire Chasm. Han gick dit för att tala med troggsen och hittade något märkligt, men dog innan han kunde visa det för henne.",al={"varför var maur i ragefire","vad gjorde grimtotem i orgrimmar"}},{q="Vad finns i väskan?",a="Påsens innehåll förblir förseglat när Rahauro tar emot den i Thunder Bluff. Magatha hoppas att den innehåller spår av det märkliga som Maur hittade i grottan.",al={"väskans innehåll","vad finns i väskan"}}},fp="17,225,12.266.0,26.343.1,37.178.0,31.135.0,31.165.0,50.190.0,27.153.0"}
P.entries["item:grizzled-bear-heart"] = {n="Grizzled Bear Heart",s="Ett Grizzled Bear Heart är ett biologiskt reagens som utvinns ur de kraftiga björnarna i Silverpine Forest. Det är en viktig beståndsdel i Royal Apothecary Societys mörka forskning om The New Plague.",h="Ett Grizzled Bear Heart är ett biologiskt reagens som utvinns ur de kraftiga björnarna i Silverpine Forest.",kw={"en dödsbrygd","apothecary renferrel","grizzled bear heart","master apothecary faranell","the new plague","old vicejaw","royal apothecary society","silverpine forest","skittering blood"},ang={["class:Hunter"]="Silverpine Forests väldiga björnar är farliga byten, och att spåra odjur som Old Vicejaw efter biologiska prover sätter jägarens tålamod och förmåga att ta till vara bytet på prov.",["race:Undead"]="För Forsaken hjälper insamlingen av dessa organ direkt Master Apothecary Faranell att skapa det ultimata vapnet mot både Arthas's Scourge och de levande dödliga som hotar Lordaeron."},sec={{t="Ett reagens till The New Plague",b="Royal Apothecary Society arbetar oavbrutet med att utveckla en framställd pest som kan utrota både Scourge och den levande mänskligheten. I Silverpine Forests skogar upptäckte Apothecary Renferrel att ett unikt gift från hjärtat hos en grizzled bear, blandat med spindelblod, ger en anmärkningsvärt dödlig brygd. Kurirer och lojala Forsaken jagar våldsamma grizzled bears, giant grizzled bears och det ökända odjuret Old Vicejaw för att skära ut organen och leverera dem direkt till Master Apothecary Faranell, djupt inne i Undercitys Apothecarium."}},faq={{q="Vad används ett Grizzled Bear Heart till?",a="Grizzled Bear Hearts samlas in som experimentella reagenser åt Royal Apothecary Society. Apothecary Renferrel upptäckte att gifter från dessa hjärtan kan destilleras till ett dödligt elixir som en del av Forsakens försök att brygga The New Plague.",al={"vad gör björnhjärtat","uppdrag med björnhjärta","reagens till dödsbrygd"}},{q="Vem vill ha björnhjärtana?",a="Apothecary Renferrel i Silverpine Forest ber resande att samla hjärtana tillsammans med Skittering Blood och leverera dem direkt till Master Apothecary Faranell i Undercitys Apothecarium.",al={"vem behöver björnhjärtat","faranell björnhjärta","vem ska jag ge björnhjärtat till"}},{q="Var kommer Grizzled Bear Hearts ifrån?",a="De skärs ut ur de olika grizzled bears som strövar omkring i Silverpine Forest, däribland ferocious grizzled bears, giant grizzled bears och det väldiga kringströvande odjuret Old Vicejaw.",al={"var hittar jag björnhjärtan","vilka björnar släpper hjärta","björnhjärtats plats"}},{q="Varför behöver Royal Apothecary Society naturliga djurgifter?",a="Sällskapet söker kraftfulla biologiska ämnen som kan smitta och förstöra både levande vävnad och odöd fysiologi. De unika kemiska egenskaperna i hjärtvävnaden hos Silverpine Forests kraftiga björnar ger en idealisk reaktiv bas när de blandas med virulent spindelblod.",al={"varför använder apotekare björngift","varför djurhjärtan till pest"}}},fx={["9ca08a87"]={q="Vad är ett Grizzled Bear Heart?",a="Det är ett färskt organ som tas från de våldsamma grizzled-björnarna som strövar omkring i Silverpine Forest. Hjärtat ser först ut som ett vanligt organ, men innehåller ett naturligt, motståndskraftigt biologiskt gift som gör det till en lockande ingrediens för alkemiska experiment.",al={"vad är grizzled bear heart","information om björnhjärtat","grizzled bear heart-lore"}}},fp="19,114,28.520.0,39.234.0,28.188.0,40.156.0,65.274.0"}
P.entries["item:grizzled-scalp"] = {n="Grizzled Scalp",s="En Grizzled Scalp är ett tjockt, pälsbeklätt skinn från grizzled thistle bears som strövar i Darkshores södra skogar. Trofén verkar märklig, men den excentriske gnommekanikern Wizbang Cranktoggle vill ha skinnen till sina dolda maskiner i vildmarken.",h="En Grizzled Scalp är ett tjockt, pälsbeklätt skinn från grizzled thistle bears som strövar i Darkshores södra...",kw={"auberdine","buzzbox 525","darkshore","grizzled scalp","grizzled thistle bear","thistle bear beer","wizbang cranktoggle"},ang={["profession:Engineering"]="Buzzbox-nätverket visar gnomernas talang för att kamouflera automatiska bryggpannor som kommunikationsutrustning för fältreparationer.",["race:NightElf"]="Night Elves skyddar Darkshores djurliv och ser med oblida ögon på både hänsynslös tjuvjakt och hemliga gnomiska destilleringsapparater som skräpar ner i vildmarken."},sec={{t="En märklig jäsning",b="Resenärer som jagar längs vägen söder om Auberdine stöter på de väderbitna grizzled thistle bears, kända för sina grova, tjocka skinn. Att flå farliga rovdjur är vardagsmat för vildmarksjägare, men när du lämnar fyra av deras skalper till Buzzbox 525 visar det sig att ändamålet är betydligt mindre ärofullt. Apparaten behöver inte björnpäls för tekniska reparationer eller vetenskapliga analyser. I stället använder gnommekanikern Wizbang Cranktoggle de dolda buzzboxarna som finns utspridda över Darkshore som hemliga destillerier. Eftersom de lokala Night Elves ogillar olovlig ölbryggning i sina bosättningar, förlitar sig Wizbang på godtrogna äventyrare som samlar björnskalper och andra märkliga ingredienser till hans älskade ”thistle bear beer”."}},faq={{q="Var hittar jag Grizzled Scalps?",a="Grizzled Scalps får du från grizzled thistle bears och deras matriark, Den Mother, i skogarna söder om Auberdine längs huvudleden i Darkshore.",al={"plats för grizzled scalp","vem släpper grizzled scalps","thistle bear-skalp"}},{q="Vad används Grizzled Scalps till?",a="De lämnas i Buzzbox 525, en automatisk mekanisk terminal gömd i buskarna längs vägen långt söder om Auberdine.",al={"användning av grizzled scalp","vad gör jag med grizzled scalps"}},{q="Varför behöver Buzzbox 525 björnskalper?",a="Wizbang Cranktoggle använder i hemlighet sitt buzzbox-nätverk för att destillera hembränt utom synhåll för vaksamma Night Elves. Grizzled Scalps är en ingrediens i hans hembryggda thistle bear beer.",al={"varför vill wizbang ha skalper","buzzbox 525:s syfte"}},{q="Varför gömmer Wizbang sin bryggning i Darkshores vildmark?",a="Night Elves som bor i Auberdine uppskattar inte en otillåten, högljudd alkoholförsäljning i sina heliga lundar. Wizbang gömde sina apparater i snåren längs vildmarksvägarna för att kunna driva sin hembräntsverksamhet oupptäckt.",al={"varför gömma buzzbox","wizbangs sprit i darkshore"}}},fx={["903811df"]={q="Vad är en Grizzled Scalp?",a="En Grizzled Scalp är den tjocka, pälsbeklädda hjässan från de tåliga björnar som strövar i Darkshores vildmarker. Dessa härdade bestar uthärdar det hårda nordliga klimatet och utvecklar stryktåliga, borstiga hudar som uppskattas av pälsjägare och nyfikna uppfinnare för sin unika täthet.",al={"vad är grizzled scalp","information om grizzled scalp","berätta om grizzled scalps"}},e940f924={q="Var kommer en Grizzled Scalp ifrån?",a="De här skalperna kommer från de fullvuxna tistelbjörnarna som hör hemma i Darkshore, främst Grizzled Thistle Bears och den våldsamma Den Mother. De är inga tillverkade varor, utan råa troféer som tas direkt från vilddjuren söder om Auberdine.",al={"var kommer grizzled scalps ifrån","grizzled scalps ursprung","vem släpper grizzled scalps"}}},fp="14,129,23.410.1,33.127.0,34.117.0,38.137.1,60.214.1"}
P.entries["item:groddoc-liver"] = {n="Groddoc Liver",s="Groddoc Liver kommer från aporna i Feralas. Rhapsody Shindigger behöver den till en drink som han hoppas ska få honom att berätta om en skrämmande flygtur över ett träsk.",h="Groddoc Liver kommer från aporna i Feralas.",kw={"feralas","groddoc ape","groddoc liver","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},sec={{t="En bitter ingrediens",b="Rhapsody Shindigger ber om Groddoc Liver i The Hinterlands, tillsammans med Roc Gizzards och Ironfur Livers. Han planerar att destillera de tre ingredienserna till en Kalimdor Kocktail. Drycken kan, säger han, hjälpa honom att berätta om fasorna under en flygtur över ett träsk."}},faq={{q="Var kommer Groddoc Livers från?",a="Groddoc Livers kommer från Groddoc Apes i Feralas.",al={"var hittar man groddoc liver","källa till groddoc liver"}},{q="Vem vill ha Groddoc Liver?",a="Rhapsody Shindigger i The Hinterlands ber om tre Groddoc Livers till sin Kalimdor Kocktail.",al={"vem behöver denna lever","rhapsody shindigger och lever"}},{q="Vad används Groddoc Liver till?",a="Rhapsody Shindigger använder Groddoc Liver tillsammans med Roc Gizzards och Ironfur Livers till en Kalimdor Kocktail.",al={"användning av groddoc liver","varför behövs levern"}},{q="Varför gör Rhapsody drinken?",a="Rhapsody säger att han behöver en starkare drink innan han kan berätta för dig om en skrämmande flygtur över ett träsk.",al={"varför cocktail","rhapsody vill ha en drink"}}},fp="13,159,19.254.0,34.49.0,24.99.0,31.100.0,33.103.0"}
P.entries["item:gryshka-s-letter"] = {n="Gryshka's Letter",s="Innkeeper Gryshka skickar ett tack till Zargh vid The Crossroads efter att ha fått färskt kött. Brevet presenterar också unga Horde-kurirer för vindryttarnas flygnätverk.",h="Innkeeper Gryshka skickar ett tack till Zargh vid The Crossroads efter att ha fått färskt kött.",kw={"the barrens","the crossroads","doras","gryshka","gryshka's letter","kött","orgrimmar","vindryttare","zargh"},ang={["faction:Horde"]="När du lämnar Gryshka's Letter lär sig unga Horde-äventyrare om wyvernernas flygmästarnätverk som förbinder Durotar och The Barrens."},sec={{t="En tacksam värdinna",b="Innkeeper Gryshka tackar Zargh för biffarna han skickar från The Barrens till Orgrimmars centrala värdshus. Hon minns när han förlorade ett finger medan han styckade kött och retas med honom för att han ser stilig ut även när han är blodig efter arbetet."},{t="Bud längs flyglederna",b="För att lämna tillbaka Gryshka's Letter vid The Crossroads beger du dig till Doras, vindryttarmästaren högst uppe på Orgrimmars platå. Visa honom att du redan har anmält dig hos Devrak vid The Crossroads, så presenterar Doras unga kurirer för wyvernernas flygleder som förbinder bosättningar i Durotar och The Barrens."}},faq={{q="Vem skrev Gryshka's Letter?",a="Innkeeper Gryshka, som driver ett värdshus i Orgrimmars Valley of Strength, skrev brevet efter att ha fått färskt kött.",al={"vem skrev detta","författaren till gryshkas brev","avsändare"}},{q="Vem är brevet avsett för?",a="Brevet är adresserat till Zargh, en slaktare vid The Crossroads i The Barrens som försåg Gryshka med kött.",al={"mottagare","vem får gryshkas brev","vart ska brevet"}},{q="Vad står det i brevet?",a="Gryshka tackar Zargh för köttbitarna, minns olyckan då han förlorade ett finger medan han styckade kött och retas med honom för att han ser stilig ut även när han är blodig.",al={"brevets text","vad säger gryshka","brevets innehåll"}},{q="Varför behöver Doras se brevet?",a="Doras är Orgrimmars vindryttarmästare. Gryshka skickar dig för att visa att du har anmält dig hos Devrak vid The Crossroads, så att Doras kan presentera dig för wyvernernas flygleder.",al={"varför visa doras","doras vindryttarmästaren","flygmästare i orgrimmar"}}},fx={["950e527c"]={q="Vad är Gryshka's Letter?",a="Det är ett handskrivet tackbrev från Innkeeper Gryshka i Orgrimmar. Hon skrev det som svar på en särskild köttleverans till hennes värdshus, både för att tacka och för att uttrycka sin tillgivenhet på ett flirtigt sätt. Brevet ska föras tillbaka till The Barrens.",al={"vad är gryshka's letter","föremålet gryshka's letter","om gryshka's letter"}},["0c09fbc7"]={q="Varför vill någon ha Gryshka's Letter?",a="Slaktaren Zargh vid The Crossroads väntar ivrigt på att få veta hur hans förstklassiga kött togs emot. Gryshka vill att brevet levereras för att visa sin innerliga tacksamhet och besvara hans känslor, medan vindryttarmästaren Doras bara behöver bekräfta din destination för att ordna en flygtur tillbaka över The Barrens.",al={"varför ska gryshka's letter levereras","vem vill ha gryshka's letter","varför vill zargh ha gryshka's letter"}}},fp="16,165,20.205.0,30.294.0,27.119.0,31.108.0,34.137.0,38.176.0"}
P.entries["item:gunther-s-spellbook"] = {n="Gunther's Spellbook",s="Gunther's Spellbook är en personlig arkan handbok knuten till en mystisk magiker som bor i Tirisfal Glades. Boken är genomsyrad av en förtrollning från Bethor Iceshard och visar att andra magiutövare har lyckats bryta sig fria från Lich King's kontroll, men den sanna historien mellan dess ägare och Forsaken återstår att nysta upp.",h="Gunther's Spellbook är en personlig arkan handbok knuten till en mystisk magiker som bor i Tirisfal Glades.",kw={"arcanus","bethor","dalaran","gunther","iceshard","kirin tor","handbok","tirisfal"},ang={["class:Mage"]="För arkaniska magiutövare står handboken för de gemensamma rötterna i Dalaran som knyter Forsakens nuvarande magiska ledarskap till självständiga magiutövare i vildmarken.",["race:Undead"]="Den förtrollade boken lyfter fram Forsakens pågående försök att rekrytera mäktiga, självständiga odöda som på egen hand bröt sig fria från Lich King."},sec={{t="En symbol för forna band",b="Före det tredje kriget studerade Gunther Arcanus de arkaniska konsterna i Dalaran tillsammans med Bethor Iceshard och Thule Ravenclaw som medlemmar i Kirin Tor. När de odödas pest svepte över Lordaeron föll Gunther och återuppväcktes som odöd, men lyckades till slut slita sig loss från Scourges grepp om hans sinne. Han trodde att han var ensam och ständigt jagad av Lich King's agenter och förblev därför djupt fientlig mot främlingar. När handboken hade återfunnits lade Bethor Iceshard en arkanisk förtrollning över dess sidor, en avsiktlig magisk signatur som låter Gunther känna igen Bethors närvaro och inse att han inte är den enda magikern med fri vilja."}},faq={{q="Vems handbok är det här?",a="Den tillhör Gunther Arcanus, en mäktig odöd magiker som bor på en isolerad ö i Brightwater Lake i Tirisfal Glades.",al={"vem äger boken","gunthers bokägare","handbokens ägare"}},{q="Varför förtrollade Bethor handboken?",a="Bethor lade en personlig besvärjelse på handboken som ett otvetydigt bevis på att han överlevt i Lordaeron och är fri från Lich King's kontroll. Han hoppas kunna övertyga Gunther om att ingå en allians med Forsaken.",al={"varför förtrolla boken","bethors besvärjelse på boken","bokens magi"}},{q="Varför är Gunther misstänksam när boken återlämnas?",a="Gunther tror att alla som närmar sig hans tillflyktsort är agenter från Scourge som skickats för att åter förslava honom. Till en början tror han bara att The Adventurer är tjuven som tog hans handbok.",al={"varför är gunther arg","gunther arg","gunther fientlig"}},{q="Hur kände Gunther och Bethor varandra?",a="För länge sedan studerade Gunther, Bethor Iceshard och Thule Ravenclaw magi tillsammans som vänner och lärlingar i Kirin Tor i staden Dalaran, innan pesten tog dem.",al={"bethors och gunthers förflutna","koppling till kirin tor","vänner i dalaran"}}},fp="19,150,22.608.1,24.107.1,37.179.0,52.162.0,43.144.1"}
P.entries["item:gyromechanic-gear"] = {n="Gyromechanic Gear",s="Ett Gyromechanic Gear är en bärgad precisionsmekanisk del från förödelsen utanför Gnomeregan. Uppfinnare i Kharanos söker just dessa kugghjul till en experimentell apparat som kan återställa spetälskegnomers mutationer.",h="Ett Gyromechanic Gear är en bärgad precisionsmekanisk del från förödelsen utanför Gnomeregan.",kw={"gnomeregan","gyromechanic gear","kharanos","spetälskegnom","operation recombobulation","razzle sprysprocket","recombobulator","restabilization cog"},ang={["profession:Engineering"]="Gnomisk precisionsmekanik är känd för sin extrema finurlighet och bygger på gyromekaniska komponenter med snäva toleranser för att reglera instabila prototypmaskiner.",["race:Gnome"]="Varje bärgat kugghjul för gnomernas uppfinnare ett steg närmare att kanske rädda sina radioaktiva fränder som vandrar omkring i snön utanför Gnomeregan."},sec={{t="Komponenter till återställningsapparaten",b="När strålning flödade genom Gnomeregan för att rensa ut trogginvasionen förvandlades en stor del av de överlevande gnomen till galna, bestrålade spetälskegnomer. Uppfinnarna Ozzie Togglevolt och Razzle Sprysprocket vägrade överge sina förvridna fränder och började utarbeta ritningar till Recombobulator, en djärv apparat som skulle upphäva strålningens fruktansvärda effekter. Prototypen kräver precisionsmekanismer som tål instabila inre tryck, särskilt Gyromechanic Gears och kompletterande Restabilization Cogs. Eftersom den lokala tillverkningen kollapsade när huvudstaden föll måste forskarna leta efter dessa ömtåliga delar direkt hos de fientliga spetälskegnomer som strövar omkring i Dun Morogh."}},faq={{q="Vad används ett Gyromechanic Gear till?",a="Det är en viktig mekanisk komponent som Razzle Sprysprocket behöver i Kharanos. Tillsammans med Restabilization Cogs byggs det in i Recombobulator, en prototypmaskin som ska bota bestrålade spetälskegnomer.",al={"vad används gyromechanic gear till","vad gör gyromechanic gear","gyromechanic gear-uppdrag"}},{q="Var kommer kugghjulen ifrån?",a="De bärgas från spetälskegnomer utanför Gnomeregan och från Gibblewilt i Dun Morogh.",al={"var hittar man gyromechanic gear","gyromechanic gear-byte","vem släpper gyromechanic gear"}},{q="Kan Recombobulator verkligen bota spetälskegnomer?",a="Razzle Sprysprocket är ständigt optimistisk kring Ozzies ritningar och tror att justeringar av förbränningskolvarna och electrogum-gel kommer att återställa deras fränder. Om maskinen verkligen kan häva katastrofal strålförgiftning i stor skala återstår att pröva; än så länge är det en gnomisk teori.",al={"fungerar recombobulator","går det att bota spetälskegnomer","lyckas återställningen"}},{q="Varför kan inte gnomer bara smida nya kugghjul?",a="Förlusten av Gnomeregan slog sönder gnomernas industriella kapacitet och låste in deras mest avancerade verktyg, verkstäder och automatiserade gjuterier. Att leta efter intakt precisionsutrustning från tiden före stadens fall i dess utkanter går ofta mycket snabbare än att bearbeta delar för hand.",al={"varför leta efter kugghjul","varför inte tillverka gyromechanic gears"}}},fx={["93a017f3"]={q="Vad är ett Gyromechanic Gear?",a="Ett Gyromechanic Gear är en intrikat konstruerad komponent för avancerade gnomiska maskiner. Delarna användes ursprungligen i Gnomeregans väldiga maskineri, men ligger nu utspridda bland ruinerna och plockas upp av de eländiga varelser som lurar utanför den fallna teknikstaden.",al={"vad är gyromechanic gear","information om gyromechanic gear","om gyromechanic gears"}}},fp="17,121,30.581.0,37.195.0,31.94.0,50.211.0,40.221.0"}
P.entries["item:hallowed-letter"] = {n="Hallowed Letter",s="Priestess Anetta kallar unga präster från Northshire Valley till Northshire Abbey. Hennes brev inleder deras studier av det heliga ljuset.",h="Priestess Anetta kallar unga präster från Northshire Valley till Northshire Abbey.",kw={"anetta","elwynn forest","hallowed letter","heliga ljuset","northshire abbey","präst","priestess anetta"},ang={["class:Priest"]="Som präst erkänner brevet dig som ett redskap för det heliga ljuset och knyter dig till tränarna i Northshire Abbey.",["race:Human"]="Som människa för du vidare Northshire Valleys tradition av helig plikt, som har utövats där sedan före det första kriget."},sec={{t="En kallelse till tron",b="Hallowed Letter bär Priestess Anettas personliga sigill och når blivande präster efter deras första prövningar mot koboldlägren i Northshire Valley. Hon ser det heliga ljusets gnista i varje novis och uppmanar dem att gå in i klostret och viga sig åt dess tjänst. Mörka krafter dröjer sig fortfarande kvar i Azeroth efter det tredje kriget. Prästerskapet samlar dem som kan hela, skydda och vägleda ett imperium som kämpar för att upprätthålla ordningen."}},faq={{q="Vad är Hallowed Letter?",a="Hallowed Letter är Priestess Anettas introduktionsbrev till nyanlända präster i Northshire Abbey, där hon kallar dem till deras första lektion.",al={"vad är hallowed letter","föremålet hallowed letter","prästbrev northshire"}},{q="Vem skrev brevet?",a="Priestess Anettas insignier finns på brevet. Hon utbildar och vägleder unga mänskliga präster som anländer till Northshire.",al={"vem skickade brevet","vem är författaren","brevets avsändare"}},{q="Varför kallar prästerskapet på nya noviser just nu?",a="Azeroth är fortfarande i kaos, och rester av Burning Legion hemsöker fortfarande världen. Kalimdor står inför nya prövningar, medan Stormwind behöver medkännande helare och ledare som kan återuppbygga och skydda folket.",al={"varför behöver präster hjälp","världens tillstånd","prästlore 25 efter tredje kriget"}},{q="Vad ska jag göra efter att ha läst brevet?",a="Ta med brevet till Northshire Abbey och tala med Priestess Anetta. Hon tar emot ditt löfte till ljuset och lär dig nya prästerliga färdigheter medan din resa fortsätter.",al={"var ska jag lämna brevet","lämna in uppdraget hallowed letter","vem ska jag prata med"}}},fx={["0a342f04"]={q="Varför vill Priestess Anetta att du ska få Hallowed Letter?",a="Priestess Anetta skickar brevet för att kalla lovande invigda av det Heliga Ljuset till Northshire Abbey. Hon har sett att du har visat prov på förmåga att försvara dalen och vill presentera sig, vägleda din andliga hängivenhet och ge dig djupare undervisning i prästerskapets heliga konster.",al={"varför hallowed letter","varför skickade anetta brevet","syftet med hallowed letter"}}},fp="15,128,15.424.0,28.147.0,21.113.0,58.196.0,42.179.0"}
P.entries["item:hallowed-rune"] = {n="Hallowed Rune",s="Hallowed Rune är en inskriven sten som ges till prästnoviser när de påbörjar sin träning i Coldridge Valley. Den skickas av Branstock Khalder, dvärgarnas prästtränare, och kallar blivande utövare av det heliga ljuset till Anvilmar för att inleda sin formella undervisning.",h="Hallowed Rune är en inskriven sten som ges till prästnoviser när de påbörjar sin träning i Coldridge Valley.",kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","hallowed rune","präst","trogger"},ang={["class:Priest"]="Hallowed Rune markerar den officiella början på en prästs formella mentorskap under det heliga ljuset i Coldridge Valley.",["race:Dwarf"]="Dvärgpräster förenar djup vördnad för ljuset med orubblig pliktkänsla gentemot Ironforge och ställer upp för att försvara sitt bergshem mot trogger."},sec={{t="En kallelse till ljuset",b="När en blivande präst visar sin beslutsamhet genom att hjälpa bergsfolket och försvararna i Coldridge Valley skickar Branstock Khalder ut Hallowed Rune. Stenen är inskriven med lärdomar om det heliga ljuset och fungerar både som en introduktion och en inbjudan. Dvärgiska noviser uppmanas att lämna de mindre skärmytslingarna i snön och bege sig till Anvilmar, där Branstock förbereder dem på att läka sår och använda helig kraft mot det troggangrepp som hotar Dun Morogh."}},faq={{q="Vad är Hallowed Rune?",a="Hallowed Rune är en liten helig sten med vägledande ord för prästnoviser. Den fungerar som en officiell kallelse från Branstock Khalder att inleda formell andlig och magisk undervisning i Anvilmar.",al={"vad är det här för föremål","föremålet hallowed rune","runans syfte"}},{q="Vem skickar Hallowed Rune till dig?",a="Den skickas av Branstock Khalder, dvärgarnas prästtränare som finns i Anvilmar. Han låter allierade i Coldridge Valley föra den vidare till unga präster som har börjat visa vad de går för ute på fältet.",al={"vem skickade runan","vem gav mig runan","branstocks runa"}},{q="Vad ska jag göra när jag fått Hallowed Rune?",a="Ta dig tid att läsa runan och bege dig sedan till Anvilmars stora sal för att anmäla dig hos Branstock Khalder. Där kommer han att erbjuda sig att lära dig nya böner och besvärjelser.",al={"vart ska jag ta runan","vad gör jag med hallowed rune"}},{q="Varför vill Branstock att prästnoviser utbildas så snabbt?",a="Coldridge Valley utsätts ständigt för troggangrepp, och bergsfolket behöver all gudomlig läkekraft och anfallskraft de kan uppbringa för att försvara Dun Morogh.",al={"varför behövs präster","troggproblemet präster"}}},fx={fac25589={q="Varför fick jag Hallowed Rune?",a="Runan fungerar som en formell kallelse och ett meddelande till novispräster som arbetar i Coldridge Valley. Branstock Khalder skickar den för att kalla blivande akolyter av det Heliga Ljuset till Anvilmar, där han kan undervisa dem i deras tro och lära dem heliga besvärjelser som är viktiga för att försvara dalen.",al={"varför har jag hallowed rune","syftet med hallowed rune","varför hallowed rune"}}},fp="13,114,22.281.0,26.185.0,35.121.0,51.138.0,58.152.0"}
P.entries["item:hallowed-scroll"] = {n="Hallowed Scroll",s="Hallowed Scroll är en formell kallelse till nyvaknade Forsaken-präster i Deathknell. Med Dark Cleric Duestens personliga sigill leder den nykomlingarna till det förstörda kapellet för att börja sin utbildning i tro, viljestyrka och skugga.",h="Hallowed Scroll är en formell kallelse till nyvaknade Forsaken-präster i Deathknell.",kw={"deathknell","duesten","forsaken","hallowed scroll","ljus","präst","tirisfal"},ang={["class:Priest"]="Det här pergamentet markerar det definitiva brottet med traditionell mänsklig tro och leder Forsaken-präster mot självständig övertygelse och skuggkonsterna som utövas av Cult of the Forgotten Shadow.",["race:Undead"]="Att få den här kallelsen speglar Deathknells brådskande, pragmatiska mobilisering. Den ser till att nyvaknade odöda snabbt utbildas och införlivas i Sylvanas styrkor."},sec={{t="En kallelse till de trolösa",b="Nyuppståndna Forsaken-präster märker att deras band till världen har förändrats våldsamt. Hallowed Scroll delas ut mitt i det pågående kaoset när Deathknell återtas och leder spirande besvärjare till vägledning i bosättningens förstörda kapell. Pergamentet är märkt med Dark Cleric Duestens sigill och fungerar både som en introduktion och en order om att inställa sig för formell undervisning. Därmed inleds prästens utbildning i den pragmatiska filosofi som präglar Forsaken-prästerskapet."},{t="Den självständiga vägen",b="När prästerna hörsammar pergamentets kallelse görs de genast fria från gamla dogmer. Duesten klargör att traditionella stöd, som vördnaden för Holy Light, förfäders andar eller demoniska pakter, inte längre tjänar de odöda. I stället markerar pergamentet början på en inåtvänd disciplin som helt bygger på den egna viljestyrkan. Undervisningen som inleds med detta pergament betonar överlevnad och maktutövning genom ren övertygelse. Den gör religiös hängivenhet till ett redskap för självbestämmande och mästerskap."}},faq={{q="Vad är Hallowed Scroll?",a="Hallowed Scroll är ett skrivet meddelande till nyuppståndna Forsaken-präster i Deathknell. Det instruerar läsaren att söka upp Dark Cleric Duesten i det lokala kapellet och börja sin formella prästutbildning.",al={"vad är det här pergamentet","hallowed scrolls syfte","föremålet hallowed scroll"}},{q="Vem skickade Hallowed Scroll?",a="Pergamentet bär det personliga sigillet från Dark Cleric Duesten, prästtränaren som håller till i den övergivna kyrkan i Deathknell.",al={"vem skrev hallowed scroll","vem skickade pergamentet","duestens pergament"}},{q="Vad lär Dark Cleric Duesten ut när du visar honom pergamentet?",a="Duesten lär ut att odöda präster måste överge sitt traditionella beroende av Holy Light, förfäders andar och andra världsliga krafter. Han förkunnar att Forsaken överlevde enbart tack vare sin egen viljestyrka och instruerar unga präster att utveckla tillit till sig själva för att vägleda och kuva andra.",al={"vad säger duesten","forsaken-prästers tro","prästlore om deathknell"}}},fx={["758c1904"]={q="Varför vill Dark Cleric Duesten att du ska få Hallowed Scroll?",a="Dark Cleric Duesten använder den förseglade skriftrullen för att kalla nyuppståndna Forsaken-präster till Deathknells kyrka. Han låter dig inte hålla fast vid det glömda Ljuset eller förfädernas andar, utan tänker undervisa dig i Forsaken-prästerskapets bistra filosofi: att enbart förlita dig på din obevekliga viljestyrka för att utöva makt och överleva i en fientlig värld.",al={"varför hallowed scroll","varför duesten hallowed scroll","syftet med hallowed scroll"}}},fp="15,183,26.374.0,25.351.0,28.161.0,29.118.0,66.279.0"}
P.entries["item:hallowed-sigil"] = {n="Hallowed Sigil",s="Hallowed Sigil är en ingraverad Night Elf-symbol som unga noviser bär i Shadowglen. Den skickas av prästläraren Shanda och är en formell kallelse som visar blivande tjänare åt Elune till Aldrassils uråldriga grenar.",h="Hallowed Sigil är en ingraverad Night Elf-symbol som unga noviser bär i Shadowglen.",kw={"aldrassil","hallowed sigil","novis","kaldorei","präst","shadowglen","shanda","teldrassil"},ang={["class:Priest"]="För Night Elf-präster är Hallowed Sigil deras allra första kallelse till formell utbildning under The Sisterhood of Elune.",["race:NightElf"]="Sigillet markerar början på en Kaldorei-trosbekännares tjänst, just när Alliansens resenärer har börjat anlända till Teldrassils grenar."},sec={{t="En kallelse till prästerskapet",b="Noviser bland Night Elf-präster som träder in under Shadowglens heliga lövverk får ofta Hallowed Sigil av en skogsbudbärare. Symbolen är graverad med heliga märken och fungerar som en personlig fullmakt från Shanda, prästläraren som finns vid Aldrassil. När en akolyt bär och läser sigillet leds hen upp till Aldrassils väldiga hålighet, där hen formellt introduceras för The Sisterhood of Elune och inleder sin andliga tjänst åt Kaldorei, medan nya resenärer anländer till Teldrassil."}},faq={{q="Vad är Hallowed Sigil?",a="Hallowed Sigil är en ingraverad helig symbol som ges till unga Night Elf-präster i Shadowglen. Den innehåller en kallelse som ber novisen söka upp sin mentor, Shanda.",al={"vad är hallowed sigil","prästsigill shadowglen"}},{q="Vem skickar Hallowed Sigil?",a="Den skickas med ett lokalt bud på uppdrag av Shanda, prästläraren som håller till inne i Aldrassils väldiga hålträd.",al={"vem skickade sigillet","shandas prästsymbol"}},{q="Vart ska jag ta sigillet?",a="Ta sigillet till Shanda inne i Aldrassil, mitt i Shadowglen på Teldrassil. När du har läst det fullbordar du din första introduktion till dina prästmentorer genom att lämna symbolen till henne.",al={"var lämnar jag hallowed sigil","lämna in hallowed sigil"}}},fx={["71c8963a"]={q="Varför vill Shanda att du lämnar tillbaka Hallowed Sigil?",a="Sigillet fungerar som en formell kallelse och en introduktionsgåva för nattalvernas novispräster. Priestess Shanda skickade det med en budbärare för att kalla dig till Aldrassil och se till att du söker hennes vägledning medan världen omkring vaknar och resenärer anländer till Teldrassils grenar. När du återvänder med det bekräftar du att du fått hennes meddelande och är redo att inleda din heliga utbildning.",al={"varför ta hallowed sigil till shanda","varför vill shanda ha sigillet","syftet med hallowed sigil"}}},fp="14,133,27.408.0,27.149.0,29.96.0,30.188.0"}
P.entries["item:hallowed-tablet"] = {n="Hallowed Tablet",s="I Valley of Trials kallar Hallowed Tablet unga Darkspear-präster till Ken'jai. Dess ord inleder deras lärdomar i att tala med andarna.",h="I Valley of Trials kallar Hallowed Tablet unga Darkspear-präster till Ken'jai.",kw={"darkspear","durotar","gornek","hallowed tablet","ken'jai","trollpräst","valley of trials"},ang={["class:Priest"]="Tavlan inleder din formella prästutbildning i Durotar och knyter dig till Ken'jai, din mentor.",["race:Troll"]="För Darkspear innebär prästämbetet nära gemenskap med andarna och loa. Tavlan bjuder in dig till dessa andliga traditioner från förfäderna."},sec={{t="En kallelse från andarna",b="Gornek ger Hallowed Tablet till en lovande trollpräst som tar sina första steg genom Valley of Trials. Orden bär på en personlig inbjudan från Ken'jai, prästtränaren utanför The Den. Ken'jai tyder tecken och hör andarnas viskningar och känner när unga Darkspear med andlig begåvning anländer till Durotar. Tavlan uppmanar den blivande prästen att läsa meddelandet och söka Ken'jais vägledning i att kanalisera andlig kraft."}},faq={{q="Vad är Hallowed Tablet?",a="Gornek ger noviser bland trollprästerna en inskriven stentavla i Valley of Trials. Dess budskap hänvisar dem till Ken'jai, deras prästtränare.",al={"vad är det här för föremål","hallowed tablet bakgrund","vad gör tavlan"}},{q="Vem skickade tavlan?",a="Ken'jai skickade tavlan genom Gornek. Andarna förutsåg en ny akolyts ankomst, vilket fick Ken'jai, prästtränaren utanför The Den, att skicka bud.",al={"vem skrev den","vem gav mig den här","tavlans upphovsperson"}},{q="Varför behöver trollpräster träffa Ken'jai?",a="Darkspear-präster talar med och befaller andarna. Ken'jai vägleder noviserna när deras andliga band fördjupas och hjälper till att se till att andarna vill lära dem starkare förmågor.",al={"vad gör kenjai","varför träffa kenjai"}}},fp="15,147,26.486.0,28.144.0,20.144.0,41.186.0"}
P.entries["item:hammertoe-s-amulet"] = {n="Hammertoe's Amulet",s="Hammertoe's Amulet är en dvärgs minnessak från hans sökande efter Uldamans förflutna. I Badlands för hans arbete vidare till dem som kände honom.",h="Hammertoe's Amulet är en dvärgs minnessak från hans sökande efter Uldamans förflutna.",kw={"amulett","badlands","dvärgar","hammertoe","historian karnik","prospector ryedol","skriftrullar","shadowforge-klanen","uldaman"},ang={["race:Dwarf"]="Som dvärg berör Hammertoes sökande efter sitt folks ursprung också ditt eget arv. Hans amulett för arbetet vidare till lärda som kände honom."},sec={{t="En dvärgs uppdrag",b="Efter att ha sårats i Badlands ber Hammertoe dig att ta hans amulett till Prospector Ryedol. Hammertoe hade sökt efter sitt folks ursprung och försökt hindra Shadowforge-klanen från att hitta skriftrullarna. Ryedol känner till det arbetet, och Hammertoe litar på att han avgör vad som måste göras."},{t="I Ironforge",b="När Ryedol har hört vad som hänt Hammertoe skickar han dig till Historian Karnik i Ironforge. Karnik och Hammertoe arbetade tillsammans för att hitta förlorade artefakter i Uldaman. Amuletten för deras arbete vidare till Karnik, och han inser att den betyder mer än sorgen efter hans följeslagare."}},faq={{q="Vem var Hammertoe?",a="Hammertoe var en dvärg som sökte efter sitt folks ursprung i Uldaman. Han arbetade också för att hindra Shadowforge-klanen från att hitta skriftrullarna.",al={"dvärgen hammertoe","vem är hammertoe","hammerto es historia"}},{q="Varför ger Hammertoe mig sin amulett?",a="Hammertoe ber dig ta amuletten till Prospector Ryedol i Badlands. Ryedol känner till Hammertoes sökande och kan avgöra vad som ska göras härnäst.",al={"varför amuletten","varför hammertoes amulett","vad gör jag med amuletten"}},{q="Vem är Prospector Ryedol?",a="Prospector Ryedol är dvärgen som Hammertoe anförtror sin amulett och sitt arbete i Uldaman åt.",al={"vem är ryedol","prospector killen"}},{q="Varför är amuletten viktig?",a="Amuletten tillhörde Hammertoe och står för hans arbete med att söka efter sitt folks ursprung i Uldaman. Ryedol och Historian Karnik känner till det arbetet.",al={"amulettens betydelse","vad är speciellt med den","spelar amuletten någon roll"}},{q="Vem är Historian Karnik?",a="Historian Karnik finns i Ironforge och arbetade med Hammertoe för att hitta förlorade artefakter i Uldaman. Ryedol hänvisar dig till honom med amuletten.",al={"vem är karnik","historikern"}},{q="Vad försökte Hammertoe hindra?",a="Hammertoe försökte hindra Shadowforge-klanen från att hitta skriftrullarna i Uldaman.",al={"shadowforge-klanens mål","varför stoppa shadowforge","skriftrullarna i uldaman"}}},fp="18,150,18.291.0,12.285.0,18.143.0,38.147.0,25.88.0,28.149.0,24.136.0,34.82.0"}
P.entries["item:hand-of-dagun"] = {n="Hand of Dagun",s="Hand of Dagun är en relik som Gerrig Bonegrip söker efter i Ironforge. Den är en av tre föremål han begär i utbyte mot Yagyin's Digest.",h="Hand of Dagun är en relik som Gerrig Bonegrip söker efter i Ironforge.",kw={"dagun","gerrig bonegrip","hand of dagun","legacy heart","gift","relik","star of xil'yeh","yagyin's digest"},ang={["faction:Alliance"]="För Alliance innebär Gerrig Bonegrips begäran en chans att hjälpa till att inleda ett nytt kapitel i hans orden."},sec={{t="En relik åt Bonegrip",b="Gerrig Bonegrip ber om Hand of Dagun och två andra reliker. Han behöver alla tre innan han ger dig en kopia av Yagyin's Digest, en text knuten till att inleda ett nytt kapitel i hans orden."}},faq={{q="Vad är Hand of Dagun?",a="Hand of Dagun är en relik som Gerrig Bonegrip ber om tillsammans med Star of Xil'yeh och Legacy Heart.",al={"hand of dagun","vad är handen"}},{q="Vem vill ha Hand of Dagun?",a="Gerrig Bonegrip i Ironforge ber dig ta med Hand of Dagun och två andra reliker till honom.",al={"vem vill ha hand of dagun","bonegrips hand","vem behöver den"}},{q="Varför behöver Gerrig Bonegrip den?",a="Gerrig behöver Hand of Dagun som en av tre reliker han begär innan han ger dig en kopia av Yagyin's Digest.",al={"varför vill bonegrip ha den","varför behövs handen","vad är den till för"}},{q="Vad gör Hand of Dagun?",a="Det sägs att Hand of Dagun bär på ett gift som förvandlar sitt offer till en medlem av en uråldrig ras.",al={"hand of daguns krafter","vad gör den","giftig hand"}}},fp="13,138,20.193.0,26.100.0,28.90.0,33.110.0,31.97.1"}
P.entries["item:hand-of-dextren-ward"] = {n="Hand of Dextren Ward",s="Hand of Dextren Ward är en avhuggen trofé från en dömd gravplundrare som satt fängslad i Stormwind Stockade. Den levererades till Darkshire som bevis på att gränsbygdens rättvisa äntligen skipats över en man som vanhelgade stadens döda.",h="Hand of Dextren Ward är en avhuggen trofé från en dömd gravplundrare som satt fängslad i Stormwind Stockade.",kw={"darkshire","dextren ward","duskwood","ebonlocke","hand of dextren ward","house of nobles","millstipe","morbent fel","stockade"},ang={["class:Mage"]="Ward var ingen magiker, men kropparna han grävde upp användes i nekromantikern Morbent Fels mörka konster. Hans död blev därför ett slag mot dem som handlar med de döda.",["faction:Alliance"]="Motsättningarna kring Wards fängslande blottar den djupa sprickan mellan Stormwinds avlägsna House of Nobles och Duskwoods övergivna nybyggare vid gränsen."},sec={{t="En besudlares pris",b="Dextren Ward dömdes till döden av Lord Ebonlocke efter att ha ertappats med att gräva upp kroppar på Duskwoods kyrkogårdar och sälja dem till nekromantikern Morbent Fel. Innan staden hann avrätta honom ingrep Stormwind och förde bort brottslingen till The Stockade. För de sörjande familjerna i Darkshire är Hand of Dextren Ward ett konkret bevis på att besudlaren har fått det straff han förtjänade, trots House of Nobles oönskade mildhet."},{t="Ett budskap till adeln",b="Utöver att tillfredsställa den lokala hämnden är kravet på Wards avhuggna hand en trotsig handling från Councilman Millstipe mot kronan. Duskwood känner sig övergivet av Stormwinds elit, som nekar dem militär hjälp men ändå hävdar sin egen auktoritet när det passar. Att avrätta en fånge i huvudstadens djupaste fängelsehåla och göra anspråk på hans hand är en bryskt tydlig påminnelse om att Darkshires råd kommer att upprätthålla sina egna lagar när House of Nobles sviker dem."}},faq={{q="Vem var Dextren Ward?",a="Dextren Ward var en brottsling som ertappades med att gräva upp lik från Darkshires gravplatser och sälja dem till den avskyvärde nekromantikern Morbent Fel. Han dömdes till halshuggning i Duskwood, men myndigheterna i Stormwind förde honom i stället till The Stockade utan att verkställa avrättningen.",al={"dextren ward bakgrund","vem är dextren ward","wards brott"}},{q="Varför vill Darkshire ha hans hand?",a="Councilman Millstipe kräver Wards avhuggna hand som obestridligt bevis på att han har mördats. Den ger avslut åt familjerna vars förfäders gravar plundrades och fungerar som ett trotsigt budskap till det korrupta House of Nobles: Darkshires rättvisa kan inte sättas ur spel.",al={"varför avhuggen hand","varför höggs wards hand av","millstipes bevis"}},{q="Var finns Hand of Dextren Ward?",a="Handen tas direkt från Dextren Ward själv. Han hålls inlåst i de djupare kamrarna på vänster sida av Stormwind Stockade, där han strider som krigare och har ett skrämmande stridsrop som får fiender att fly.",al={"var hittar man ward","wards plats i stockade","dextren wards plats"}},{q="Varför fängslade Stormwind Ward i stället för att avrätta honom?",a="House of Nobles hävdade jurisdiktion över Ward och valde att fängsla honom i The Stockade i stället för att låta Darkshire verkställa dödsdomen. Ledarna i Darkshire ser detta som korrupt byråkratiskt inblandande som nonchalerar gränsstadens nöd.",al={"varför skonades ward","stormwinds house of nobles och ward","ward fängslad"}}},fx={["48b9455f"]={q="Vad är Hand of Dextren Ward?",a="Det är den avhuggna handen från Dextren Ward, en ökänd gravplundrare och skändare av de döda som greps när han sålde lik från Darkshires kyrkogård till nekromantikern Morbent Fel. Den togs som ett fysiskt bevis på att han mördats i Stormwind Stockade, och bekräftar på ett dystert sätt att Lord Ebonlockes dödsdom till slut har verkställts.",al={"vad är hand of dextren ward","föremålet hand of dextren ward","dextren wards hand"}},b59a9a35={q="Var kommer Hand of Dextren Ward ifrån?",a="Den kommer direkt från Dextren Wards kropp och höggs av med ditt eget svärd i hans cell i Stormwind Stockade. Den är inte smidd eller tillverkad, utan tas som en obestridlig rättvisetrofé för att lämnas tillbaka till Councilman Millstipe i Duskwood.",al={"var kom dextren wards hand ifrån","vem skapade dextren wards hand","hand of dextren wards ursprung"}}},fp="20,181,16.374.0,23.378.1,21.246.0,33.225.0,40.189.0,57.245.0"}
P.entries["item:handful-of-oats-classic"] = {n="Handful of Oats",s="I Westfall behöver gamla Blanchy havre efter att familjen Furlbrows vagn gått sönder.",h="I Westfall behöver gamla Blanchy havre efter att familjen Furlbrows vagn gått sönder.",kw={"blanchy","furlbrow","spannmål","handful of oats","havre","havresäckar","westfall"},ang={["faction:Alliance"]="Som alliansresenär i Westfall kan du visa en liten barmhärtighet genom att samla havre åt strandsatta flyktingar som familjen Furlbrow, på Stormwinds försummade gränsmark."},sec={{t="Foder bland ruinerna",b="Westfall försörjde en gång Stormwind-kungariket, men dess gårdar ligger nu igenvuxna eller under Defias-banditers och förrymda skördegolemars kontroll. Säckar med spannmål och havre finns kvar nära lador, uthus och igenvuxna fält. Resenärer och flyktingar som blivit stående längs de dammiga vägarna när vagnar gått sönder kan samla ihop den överblivna havren och ge den till sina utmattade draghästar."}},faq={{q="Vad används nävar med havre till?",a="Havren är mat åt gamla Blanchy, ett utmattat sto som tillhör familjen Furlbrow. Deras vagn gick sönder på en väg i Westfall och lämnade henne utmattad och hungrig.",al={"vad används havre till","varför samla havre","användning av näve med havre"}},{q="Var kan man hitta den här havren?",a="Du kan samla havre ur säckar som ligger utspridda på övergivna gårdar i Westfall, särskilt i sydväst.",al={"var hitta havre","plats för havresäck","hur få tag på havre"}},{q="Varför lämnas havresäckarna obevakade?",a="Defias Brotherhood gjorde plötsligt uppror, och förrymda skördemaskiner härjade på fälten. Bönderna flydde i hast och lämnade skördad spannmål och andra förnödenheter på fälten och i ladorna.",al={"varför övergivna säckar","vem lämnade havren"}}},fx={["67495104"]={q="Vad är Handful of Oats?",a="Handful of Oats är enkelt djurfoder, skopat ur j säckar som lämnats utspridda på Westfalls gårdar. Under bördiga tider livnärde dessa korn kungarikets arbetshästar och dragdjur. I dag, när fälten överlåtits åt förrymda skördegolem och banditer, hör lösa havrekorn till de få rester av rent foder som finns kvar åt ett hungrigt lastdjur.",al={"vad är handful of oats","föremålet handful of oats"}},a4d08151={q="Varför vill någon ha Handful of Oats?",a="Verna Furlbrow behöver dem desperat för att ge näring åt Old Blanchy, familjens trogna arbetshäst. Efter att Furlbrow-familjen flytt från sitt hem gick deras vagn sönder på vägen, och Blanchy blev utmattad, utsvulten och nära att falla ihop. Några näringsrika nävar korn är allt som håller det trogna stoet vid liv medan familjen är strandsatt.",al={"vem vill ha handful of oats","varför samla havre","varför behövs handful of oats"}}},fp="15,75,22.347.0,35.137.0,30.94.0,37.187.0"}
P.entries["item:handful-of-stardust"] = {n="Handful of Stardust",s="Handfuls of Stardust är skimrande, frostiga beläggningar som samlas från glittrande buskar i Ashenvales södra vildmark. De kommer från The Ruins of Stardust och pulvret har naturligt svalkande egenskaper som Night Elf-läkare uppskattar när de behandlar svår feber.",h="Handfuls of Stardust är skimrande, frostiga beläggningar som samlas från glittrande buskar i Ashenvales södra...",kw={"ashenvale","astranaar","orendil","pelturas","omslag","relara","the ruins of stardust","stardust"},ang={["profession:Herbalism"]="Stardust plockas direkt för hand från glittrande buskar i stället för att samlas in som en formell botanisk ingrediens, och visar hur Night Elf förlitar sig på sällsynt lokal flora i läkande medicin.",["race:NightElf"]="För Kaldorei som försvarar Ashenvale speglar insamlingen av lokala läkemedel som stardust den bestående harmonin mellan deras forntida ruiner och örttraditioner."},sec={{t="Ett svalkande örtmedel",b="Stardust hittas på bladbuskar i de forntida The Ruins of Stardust, söder om Astranaar, och ser ut som en fin, lysande frost. Ruinerna hemsöks av kvardröjande elementandar, men växtligheten som frodas bland de krossade stenarna suger åt sig ett sällsynt omgivande sken. Traditionell Night Elf-medicin använder denna frostiga rest och bereder den till omslag som drar ut ihållande, farlig feber när vanliga salvor och månbrunnsvatten inte ger full lindring."},{t="En fars hopp",b="Pelturas Whitemoon, en orolig far i Astranaar, sökte pulvret på råd av örtkännaren Orendil Broadleaf. Pelturas unga dotter, Relara, led av en envis magisk åkomma och mardrömmar. En första välsignelse från en sten berörd av Elune lugnade hennes sinne, men en svår kroppslig feber dröjde sig kvar. Därför sökte han stardust för att blanda en svalkande pasta som kunde rädda flickans liv."}},faq={{q="Var hittar man Handful of Stardust?",a="Det samlas från glittrande buskar täckta av stardust som växer över hela The Ruins of Stardust, söder om Night Elf-bosättningen Astranaar i centrala Ashenvale.",al={"stardust-plats","var hittar man stardust","buskar täckta av stardust"}},{q="Vad används stardust till?",a="Pelturas Whitemoon i Astranaar använder pulvret för att bereda ett lindrande omslag som ska bryta den obevekliga feber som plågar hans sjuka dotter, Relara.",al={"användning av stardust","pelturas botemedel","stardust syfte"}},{q="Vilka faror finns kring stardustbuskarna?",a="The Ruins of Stardust är hem åt fientliga vattenelementar som lurar nära strandlinjen och bland de forntida, fallna pelarna där buskarna växer.",al={"fiender i ruins of stardust","varelser i ruins of stardust"}},{q="Har stardust någon koppling till gudinnan Elune?",a="Night Elf vördar himmelska krafter och ruinerna har ett stjärnklart namn, men stardust fungerar främst som en fysisk medicinalingrediens som örtkännare rekommenderar för dess frostiga, svalkande egenskaper.",al={"är stardust magiskt","stardusts koppling till elune"}}},fx={["8cce1335"]={q="Vad är Handful of Stardust?",a="Handful of Stardust är ett skimrande, frostigt pulver som samlas från den glittrande växtligheten i Ashenvales uråldriga Ruins of Stardust. Denna sällsynta botaniska rest har lugnande, magiska kylande egenskaper och är därför ovärderlig när man tillreder kraftfulla örtomslag mot envisa, livshotande febrar.",al={"vad är handful of stardust","vad är stardust","föremålslore om stardust"}}},fp="19,128,23.366.0,15.368.1,39.106.0,31.160.0,42.126.0,41.119.0"}
P.entries["item:hardened-tortoise-shell"] = {n="Hardened Tortoise Shell",s="Hardened Tortoise Shells är ovanligt tåliga skal som utvinns från sparkleshell-sköldpaddor som strövar omkring på The Shimmering Flats. De är eftertraktade av de gnomiska förarna vid Mirage Raceway. Dessa robusta organiska plattor står emot flyktiga och frätande experimentbränslen bättre än något annat.",h="Hardened Tortoise Shells är ovanligt tåliga skal som utvinns från sparkleshell-sköldpaddor som strövar...",kw={"hardened tortoise shell","mirage raceway","raketbil","the shimmering flats","sparkleshell","wizzle brassbolts"},ang={["profession:Engineering"]="Att använda organiska skal som bränsletankar för högt tryck är okonventionellt, men när gnomiskt bränsle smälter vanliga rör av legering kommer naturliga material med hög tålighet ofta till användning.",["race:Gnome"]="Bara gnomisk uppfinningsrikedom kan få någon att se en ökensköldpadda och genast tänka på en lätt och mycket tålig behållare för farligt raketbränsle."},sec={{t="Naturligt pansar mot faror i hög fart",b="Den solstekta vidsträckta öknen The Shimmering Flats är hem åt flera sorter sparkleshell-sköldpaddor, bland annat snappers och borers. Deras skal har utvecklats till ovanligt tåliga skydd mot det hårda ökensaltet och kringströvande rovdjur. På saltslätterna korroderar vanliga bränsletankar av metalllegering ofta eller spricker av påfrestningarna från gnomisk experimentkemi. Mekaniker som Wizzle Brassbolts värdesätter skalen inte som pansar eller sköldar, utan som organiskt råmaterial som är tåligt nog att byggas om till provisoriska, syrabeständiga bränsletankar för flyktiga raketdrivmedel."}},faq={{q="Var hittar du Hardened Tortoise Shells?",a="De samlas in från sparkleshell-sköldpaddor, närmare bestämt Sparkleshell Snappers, Borers och vanliga Sparkleshell Tortoises, som strövar över de öppna saltslätterna i The Shimmering Flats i Thousand Needles.",al={"var hittar man sköldpaddsskal","plats för hårdnat skal","plats för sparkleshell"}},{q="Varför vill Wizzle Brassbolts ha skalen?",a="Wizzles bror konstruerar ett extremt kraftfullt, frätande raketbränsle som hotar att smälta rakt igenom deras racerbils chassi. Wizzle tänker gröpa ur och förstärka sköldpaddornas ovanligt tåliga skal för att använda dem som kemiskt beständiga bränsletankar.",al={"varför behövs skalen","wizzles användning av skalen","vad används skalen till"}},{q="Går det lätt att forma dem med vanliga verktyg från verkstaden?",a="Nej. Skalen är så onaturligt hårda att gnomiska mekaniker räknar med att böja och förstöra verktyg av metall för ett helt verktygsskåp när de försöker karva, borra och forma dem till tankar.",al={"är skalen svåra att forma","böja verktyg mot skal"}}},fx={cc86b908={q="Vad är Hardened Tortoise Shell?",a="Det är det exceptionellt slitstarka, naturliga yttre skalet från de stora sparkleshell-sköldpaddorna som strövar omkring på saltslätterna. Skalen sägs vara mycket tåligare än vanliga djurhudar eller standardplåtar och stå emot friktion, salt och intensiv kemisk erosion.",al={"vad är hardened tortoise shell","föremålet hardened tortoise shell","hårdnat skal"}},["4ed6fee7"]={q="Var kommer Hardened Tortoise Shell ifrån?",a="Skalen är helt naturliga och inte tillverkade. De tas direkt från sparkleshell-sköldpaddorna, snappers och borers som trivs i den hårda, solstekta saltödemarken i The Shimmering Flats i Thousand Needles.",al={"hardened tortoise shells ursprung","vem skapade hardened tortoise shell","varifrån kommer hårdnade skal"}}},fp="23,236,36.355.0,43.181.0,45.238.0,46.156.0"}
P.entries["item:hardened-tumor"] = {n="Hardened Tumor",s="En Hardened Tumor är en sällsynt biologisk avvikelse som samlas in från Vile Fin-murlocer som lever runt Lake Lordamere. Den nämns först i forskningen av Apothecary Berard, som nu är en viljelös tjänare åt Arugal, och denna förkalkade utväxt används som ett ovanligt reagens i Royal Apothecary Societys försök att brygga The New Plague.",h="En Hardened Tumor är en sällsynt biologisk avvikelse som samlas in från Vile Fin-murlocer som lever runt Lake...",kw={"apothecary faranell","apothecary renferrel","berard","the dawning isles","hardened tumor","lake lordamere","murloc","new plague","vile fin"},ang={["race:Undead"]="Att skaffa tumören för forskningen framåt för Master Apothecary Faranell och bidrar till hans viktiga arbete med The New Plague, i Lady Sylvanas tjänst och i Forsakens kamp mot sina levande och odöda fiender."},sec={{t="En sällsynt biologisk avvikelse",b="När Apothecary Berard studerade den inhemska faunan längs Silverpine Forests östra gränser katalogiserade han en onormal, förkalkad utväxt som utvecklades inuti Vile Fin-murlocer vid Lake Lordamere. Sådana utväxter är ytterst sällsynta och förekommer bara hos fullvuxna exemplar längs strandlinjen och på The Dawning Isles. Det är fortfarande oklart vad som får Vile Fin-murlocer att bilda dessa hårdnade massor, men deras täta, sjukliga vävnad väckte genast Royal Apothecary Societys intresse."},{t="Bränsle till The New Plague",b="Efter att Arugals förbannelse gjort Berard till en viljelös tjänare återfanns hans dagbok i Pyrewood Village och fördes till Apothecary Renferrel vid The Sepulcher. Renferrel insåg potentialen i Berards arbete och gav Forsaken-agenter i uppdrag att hämta en Hardened Tumor tillsammans med inhemska vattenmossor. Master Apothecary Faranell leder Apothecarium i Undercity och söker reagenser som kan stå emot förruttnelse eller förändra biologisk materia. Han införlivade denna egendomliga utväxt direkt i sällskapets pågående framställning av The New Plague."}},faq={{q="Vad är en Hardened Tumor?",a="Det är en onormal, förkalkad massa som sällan bildas inuti Vile Fin-murlocer som lever runt Lake Lordamere. Den upptäcktes av Forsaken-forskaren Apothecary Berard, står emot vanlig fysisk nedbrytning och har unika biologiska egenskaper.",al={"vad är den här tumören","tumörens bakgrund","hardened tumor byte"}},{q="Varför vill Royal Apothecary Society ha den?",a="Master Apothecary Faranell och Royal Apothecary Society samlar in ovanliga giftiga och biologiska prover för att syntetisera The New Plague. Tumörens onormala motståndskraft och celluppbyggnad gör den till en utmärkt kandidat för deras pestexperiment.",al={"varför vill apotekaren ha tumören","tumörens användning i dödsrecept","faranells tumör"}},{q="Var hittar man dessa tumörer?",a="De hämtas från Vile Fin-murlocer i Silverpine Forest, särskilt de som lever på The Dawning Isles i östra Lake Lordamere och vid byns stränder nordost om Ambermill.",al={"var hittar man hardened tumor","vilka murlocer släpper tumören","tumörens plats"}},{q="Vem var Apothecary Berard?",a="Berard var apotekare i Royal Apothecary Society och stationerad i Silverpine Forest. Innan Arugals förbannelse gjorde honom till en viljelös tjänare i Pyrewood Village sammanställde han detaljerad forskning om den lokala floran, faunan och murlocernas mutationer. Han upptäckte hur mossorna och de hårdnade tumörerna på The Dawning Isles kunde användas.",al={"vem är berard","berards bakgrund","berards dagbok"}}},fx={["9aa7efc6"]={q="Var kommer Hardened Tumor ifrån?",a="Hårdnade tumörer är onormala biologiska utväxter som finns på Vile Fin-murlocer som lever runt Lake Lordamere i Silverpine Forest. De tillverkas inte av dödliga, utan tas i stället från köttet på dessa besudlade amfibievarelser. Apothecary Berard dokumenterade deras existens först i sin fältforskning och noterade att det är anmärkningsvärt sällsynt att hitta en murloc med en så ovanligt tät, förkalkad utväxt.",al={"hardened tumors ursprung","varifrån kommer hårdnade tumörer","vem skapade hardened tumor"}}},fp="14,179,25.353.0,23.477.1,25.212.0,46.223.0,29.175.0,26.287.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="Harpy Lieutenant Ring",s="I Dry Hills markerar Harpy Lieutenant Rings Witchwing Slayers, som leder flocken. Darsok Swiftdagger vid The Crossroads ber om dem som bevis på att de dödats.",h="I Dry Hills markerar Harpy Lieutenant Rings Witchwing Slayers, som leder flocken.",kw={"the crossroads","darsok swiftdagger","the dry hills","harpy lieutenant ring","the barrens","witchwing","witchwing slayer"},ang={["class:Rogue"]="Som rogue kanske du föredrar de precisa angrepp som Darsok Swiftdagger söker: att smyga in i harpyornas nästen och döda deras befälhavare.",["faction:Horde"]="Som medlem av horden möter du Witchwing-harpior som angriper försörjningslederna mellan Durotar, Mulgore och de norra utposterna. Att bryta deras ledarskap hjälper till att säkra hordens karavaners färd genom The Barrens."},sec={{t="Rangtecken",b="Witchwing Slayers leder angrepp på hordens resenärer i The Barrens. Deras ringar visar deras plats bland flockens ledare, över de vanliga plundrarna som slåss utan större samordning. Vid The Crossroads behöver Darsok Swiftdagger och försvararna ringarna från fallna slayers för att bekräfta att den här delen av harpiornas ledarskap har brutits."}},faq={{q="Vem bär de här ringarna?",a="Witchwing Slayers bär ringarna som löjtnanter i Witchwing-flocken i Dry Hills.",al={"vem släpper harpy lieutenant ring","witchwing slayer-ringar","vilka harpior har ringar"}},{q="Var finns Witchwing Slayers?",a="Witchwing Slayers håller till i Dry Hills, nordväst om The Crossroads i norra The Barrens.",al={"witchwing slayer-plats","var finns harpy-löjtnanter","harpior i the dry hills"}},{q="Varför vill Darsok Swiftdagger ha dem?",a="Darsok vill ha ringarna som bevis på att Witchwing Slayers har dödats. Deras död bryter en del av flockens ledarskap.",al={"varför samla harpy-ringar","darsok swiftdagger-ringar"}},{q="Bär vanliga harpioringar?",a="Nej. Ringarna markerar Witchwing Slayers, medan vanliga harpyplundrare är underlydande av lägre rang.",al={"kan plundrare släppa ringar","har witchwing-plundrare ringar"}}},fx={["105f77c8"]={q="Vad är Harpy Lieutenant Ring?",a="Dessa ringar är utmärkande smycken som bärs av Witchwing-slaktarna i Dry Hills. I sina nästen agerar slaktarna som löjtnanter och leder de lägre harpy-underhuggarna på sina matriarkers vägnar. För Horde-spejarna som bevakar Barrens fungerar smyckena som tydliga bevis på rang bland den skoningslösa flocken.",al={"vad är harpy lieutenant ring","harpy-ringens identitet","lore om harpy lieutenant ring"}}},fp="21,180,14.331.0,24.88.0,37.94.0,38.129.0,43.96.0"}
P.entries["item:hatecrest-naga-scale"] = {n="Hatecrest Naga Scale",s="Hatecrest Naga Scales tas från nagorna som hotar Sardor Isle i Feralas. Latronicus Moonspear vid Feathermoon Stronghold vill använda dem för att försvaga nagornas närvaro och undersöka vad de kan tillverka av dem.",h="Hatecrest Naga Scales tas från nagorna som hotar Sardor Isle i Feralas.",kw={"feathermoon stronghold","hatecrest naga scale","hatecrest-fjäll","latronicus moonspear","naga","pratt","sardor isle"},ang={["race:NightElf"]="Som Night Elf hjälper du Latronicus att skydda Feathermoon Strongholds intressen på Sardor Isle. Han säger att hans folk söker fred, men kommer att försvara det som tillhör dem."},sec={{t="Fjäll åt Feathermoon",b="Latronicus Moonspear ber dig ta med tio Hatecrest Naga Scales till Feathermoon Stronghold. Han fruktar att nagorna ska försöka säkra Sardor Isle och tänker därför försvaga deras närvaro innan hotet växer. Fjällen måste vara i gott skick. När han har fått dem planerar han att skicka dem till Pratt för undersökning och eventuell användning vid hantverk."}},faq={{q="Vad ska Hatecrest Naga Scales användas till?",a="Latronicus Moonspear vill ha tio Hatecrest Naga Scales i gott skick för att försvaga nagornas närvaro på Sardor Isle. Han planerar också att skicka dem till Pratt för att se om de kan användas vid hantverk.",al={"varför fjäll","användning av hatecrest-fjäll","fjällens syfte"}},{q="Vem vill ha fjällen?",a="Latronicus Moonspear vid Feathermoon Stronghold ber om tio Hatecrest Naga Scales.",al={"vem behöver fjäll","latronicus fjäll","fjäll åt vem"}},{q="Varför vill Feathermoon försvaga nagorna?",a="Latronicus fruktar att Hatecrest-nagorna ska försöka säkra Sardor Isle, så han vill försvaga deras närvaro innan de kan göra det.",al={"varför bekämpa hatecrest","naga-hot","varför sardor isle"}},{q="Vad kan Pratt göra med fjällen?",a="Latronicus planerar att skicka fjällen till Pratt, som kanske kan tillverka något användbart av dem.",al={"pratt fjäll","tillverka av fjäll","hantverk av fjäll"}}},fp="20,205,22.331.0,35.182.0,21.82.0,45.127.0,36.98.0"}
P.entries["item:hatefury-claw"] = {n="Hatefury Claw"}
P.entries["item:hatefury-horn"] = {n="Hatefury Horn",s="Ett Hatefury Horn tas från en av satyrerna i ruinerna av Sargeron, öster om Nijel’s Point. Kreldig Ungor samlar horn och klor till en lista över reagenser från Kharanos.",h="Ett Hatefury Horn tas från en av satyrerna i ruinerna av Sargeron, öster om Nijel’s Point.",kw={"hatefury claw","hatefury horn","hatefury-satyr","kreldig ungor","leftwitch","nijel's point","reagenser","sargeron"},ang={["race:Gnome"]="Som gnom känner du kanske till Leftwitch genom hennes rykte: magikern i Kharanos skickade en lista över reagenser till Reclaimers."},sec={{t="Ett reagens från Sargeron",b="Öster om Nijel’s Point hemsöker Hatefury-satyrerna ruinerna av Sargeron. Deras horn hör till de reagenser Kreldig Ungor behöver åt Leftwitch, en gnommagiker i Kharanos. Kreldig ber om tio horn och tio Hatefury Claws, men kan inte lova att de håller god kvalitet."}},faq={{q="Varifrån kommer Hatefury Horns?",a="Hatefury-satyrer i ruinerna av Sargeron, öster om Nijel’s Point, bär hornen.",al={"källa till hatefury horn","var hittar man horn","satyr horns"}},{q="Vem vill ha Hatefury Horns?",a="Kreldig Ungor samlar in tio Hatefury Horns till en lista över reagenser från Leftwitch, en gnommagiker i Kharanos.",al={"vem behöver hatefury horns","kreldigs horn","reagenser åt reclaimers"}},{q="Varför samlar Kreldig in dem?",a="Kreldig samlar hornen som reagenser åt Leftwitch i Kharanos.",al={"varför horn","leftwitchs reagenser","vad används hornen till"}},{q="Vad mer behöver Kreldig?",a="Kreldig ber också om tio Hatefury Claws.",al={"andra reagenser","hatefury claws","vad gör man med hornen"}}},fp="13,166,23.263.0,34.78.0,25.105.0,31.64.0,28.41.0"}
P.entries["item:head-of-arugal"] = {n="Head of Arugal",s="Head of Arugal är den makabra trofén som tagits från den galne ärkemagikern högst upp i Shadowfang Keep. Den har förts till de Fördömda vid The Sepulcher och är ett obestridligt bevis på att den lokala worgenflockens herre har fallit.",h="Head of Arugal är den makabra trofén som tagits från den galne ärkemagikern högst upp i Shadowfang Keep.",kw={"arugal","arugal måste dö","dalar dawnweaver","head of arugal","the sepulcher","shadowfang keep","silverpine"},ang={["class:Mage"]="Huvudet från en före detta ärkemagiker i Kirin Tor är en tydlig varning om det vansinne och den förödelse som okontrollerade, desperata frammaningar kan orsaka även begåvade magiker.",["race:Undead"]="För de Fördömda undanröjer leveransen av Arugals huvud en oberäknelig magiker vid deras södra tröskel och säkrar Silverpine Forest åt den Mörka Damen."},sec={{t="Den galne ärkemagikerns trofé",b="Ärkemagikern Arugal har länge kastat en mörk skugga över Silverpine Forest och styrt de varglika fasorna från Shadowfang Keeps murar. Att ta hans avhuggna huvud är det yttersta uppdraget från Dalar Dawnweaver vid The Sepulcher. För de Fördömda är huvudet mycket mer än en makaber trofé; det står för att en mäktig magiker har undanröjts, en vars vildsinta bestar hindrade Lady Sylvanas från att få full kontroll över Silverpine. När huvudet överlämnas till Dawnweaver bekräftar det att den förrymde ärkemagikerns vidriga trolldom äntligen har skurits bort från landet."}},faq={{q="Vem vill ha Head of Arugal?",a="Dalar Dawnweaver, ett sändebud stationerat vid The Sepulcher i Silverpine Forest, kräver huvudet som en del av uppdraget ”Arugal Must Die”.",al={"vem behöver arugals huvud","lämna in arugals huvud","vem tar emot head of arugal"}},{q="Var får du tag på Head of Arugal?",a="Det skärs av från ärkemagikern Arugal själv, som håller till på Shadowfang Keeps högsta tornspira med utsikt över Pyrewood Village och skogarna i Silverpine.",al={"hur får man tag på arugals huvud","arugals huvud byte","var finns arugals huvud"}},{q="Varför vill de Fördömda ha Arugal död?",a="Arugals närvaro och hans flock av vildsinta worgen hindrar de Fördömda från att säkra Silverpine Forest som ett tryggt strategiskt fäste åt Lady Sylvanas och Undercity.",al={"varför döda arugal","de fördömdas skäl att döda arugal","varför vill dalar att arugal ska dö"}},{q="Vad händer när huvudet lämnas in?",a="Dalar Dawnweaver lovar att utrota resterna av Arugals vidriga besvärjelser och förklarar att Silverpine äntligen är fritt från den galne magikerns grepp.",al={"efter arugals död","resultatet av arugal must die"}}},fx={c9f64370={q="Vad är Head of Arugal?",a="Head of Arugal är det avhuggna huvudet från Archmage Arugal, den galne före detta trollkarlen från Dalaran som släppte lös worgen i Silverpine Forest. Det togs från hans fäste i Shadowfang Keep och är ett obestridligt fysiskt bevis på att den vansinnige trollkarlen till sist har dödats och att hans mörka magi brutits.",al={"vad är head of arugal","föremålet head of arugal","arugals huvud"}},["10305f38"]={q="Var kommer Head of Arugal ifrån?",a="Huvudet tas direkt från Archmage Arugal i de höga delarna av Shadowfang Keep. Efter att ha invaderat det förbannade fästet och besegrat den galne ärkemagikern i strid fäller du honom och tar hans huvud för att bekräfta hans död.",al={"var får man head of arugal","vem släpper head of arugal","arugals huvuds ursprung"}}},fp="14,152,26.345.0,29.128.0,39.144.0,37.160.0,41.147.1"}
P.entries["item:head-of-bangalash"] = {n="Head of Bangalash",s="Hemet Nesingwary söker efter Head of Bangalash i Stranglethorn Vale. Den stora vita tigern är det senaste bytet i hans jakt.",h="Hemet Nesingwary söker efter Head of Bangalash i Stranglethorn Vale.",kw={"storviltsjägare","head of bangalash","hem et nesingwary","jakttrofé","king bangalash","stranglethorn","vit tiger"},ang={["class:Hunter"]="Som jägare visar Hemets jakt på King Bangalash hans skicklighet i att jaga och spåra."},sec={{t="Den stora vita tigern",b="Hemet Nesingwary har jagat King Bangalash länge. Efter jakterna på Sin'Dall, Bhag'thera och Tethis är den stora vita tigern priset han fortfarande söker. Tigerns huvud visar att jakten är över."}},faq={{q="Vem vill ha Head of Bangalash?",a="Hemet Nesingwary vill ha Head of Bangalash som pris för sin jakt på King Bangalash.",al={"vem vill ha tigerhuvudet","hemets trofé","vem är det till"}},{q="Vad är Bangalash?",a="King Bangalash är en stor vit tiger i Stranglethorn Vale.",al={"vem är bangalash","vit tiger","kungstiger"}},{q="Varför vill Hemet ha huvudet?",a="Hemet har förföljt King Bangalash länge och kallar tigern jaktens verkliga pris.",al={"varför hemet vill ha det","jakten på bangalash","varför döda bangalash"}},{q="Vilka jakter kom före Bangalash?",a="Hemet nämner Sin'Dall, Bhag'thera och Tethis bland jakterna före King Bangalash.",al={"tidigare storvilt","sin'dall bhag'thera tethis","vad jagade hemet"}}},fp="17,123,21.207.0,32.89.0,18.60.0,29.97.0,33.91.0"}
P.entries["item:head-of-baron-vardus"] = {n="Head of Baron Vardus",s="Baron Vardus avhuggna huvud är beviset på Southshores jakt på den före detta adelsmannen från Alterac. Magistrate Maleb söker rättvisa för den brutalitet som drabbat staden.",h="Baron Vardus avhuggna huvud är beviset på Southshores jakt på den före detta adelsmannen från Alterac.",kw={"alterac","baron vardus","baron vardus huvud","magistrate maleb","southshore","strahnbrad","syndicate"},ang={["faction:Alliance"]="Som Alliance-resenär kan du se hur Southshore söker rättvisa mot en Syndicate-adelsman som skickade hejdukar mot staden."},sec={{t="En baron på fall",b="Kontraktet med Baron Vardus namn leder från Southshore till Syndicates tillhåll i Alterac. Vardus är en adelsman från det forna kungariket, känd för sitt kalla hjärta och sina brutala metoder. Magistrate Maleb vill ställa honom inför rätta efter att hans hejdukar skickats mot Southshore. Baronens huvud är beviset Maleb kräver."}},faq={{q="Vem var Baron Vardus?",a="Baron Vardus var en adelsman från det forna kungariket Alterac, känd för sitt kalla hjärta och sina brutala metoder.",al={"vem är vardus","baron vardus","vardus bakgrund"}},{q="Varför vill Southshore ha hans huvud?",a="Magistrate Maleb säger att Vardus skickade sina hejdukar mot Southshore och vill ställa honom inför rätta.",al={"varför döda vardus","southshore vill ha vardus","vardus efterlyst"}},{q="Var kan Baron Vardus hittas?",a="Vardus finns bland Syndicates tillhåll i Alterac, kanske vid ruinerna av Strahnbrad eller i dalen norr om dem.",al={"var är vardus","vardus plats","hitta baronen"}},{q="Vem tar emot huvudet?",a="Magistrate Maleb i Southshore tar emot Baron Vardus huvud som bevis på att jakten är över.",al={"vem vill ha huvudet","huvud till maleb","vardus huvud"}}},fp="20,163,19.327.0,21.105.0,34.96.0,32.115.0,22.93.1"}
P.entries["item:head-of-bazil-thredd"] = {n="Head of Bazil Thredd",s="Det avhuggna huvudet av Bazil Thredd tjänar som ett definitivt bevis på att ledaren bakom upproret i The Stockade har undanröjts. Warden Thelwater kräver denna makabra trofé, som markerar slutet för Defias Brotherhoods organiserade kontroll över Stormwinds underjordiska fängelse.",h="Det avhuggna huvudet av Bazil Thredd tjänar som ett definitivt bevis på att ledaren bakom upproret i The...",kw={"bazil thredd","defias","head of bazil thredd","fängelset","upploppen i the stockade","warden thelwater"},ang={["faction:Alliance"]="När Thredds avhuggna huvud visas upp stillas den omedelbara paniken i huvudstaden och bevisar att kronans rättvisa fortfarande når djupt in i det upproriska The Stockade."},sec={{t="Bevis på förräderiets slut",b="När upplopp bröt ut i The Stockade under Stormwind City gjorde Bazil Thredd sig snabbt känd som upprorets hjärna. Förskansad i sin cellavdelning bland lojala fångar från Defias Brotherhood styrde Thredd kaoset djupt inne bakom fängelsehålets murar. Warden Thelwater, som misstror främlingar och kämpar för att upprätthålla ordningen, krävde Thredds huvud som otvetydigt bevis på hans död och som ett test på The Adventurers verkliga lojalitet mot Stormwind."}},faq={{q="Vem vill ha Head of Bazil Thredd?",a="Warden Thelwater, som är stationerad vid ingången till The Stockade, kräver huvudet. Han behöver det som ett obestridligt bevis på att upprorets ledare har dödats innan han är villig att dela någon information om Thredds medkonspiratörer.",al={"vem behöver thredds huvud","var lämnar man in thredds huvud","uppdragsgivare för thredds huvud"}},{q="Vem var Bazil Thredd?",a="Bazil Thredd var en högt uppsatt medlem av Defias Brotherhood, fängslad under Stormwind. När fångarna gjorde uppror tog han befälet över upploppet och samordnade upproret djupt inne i den östra cellavdelningen.",al={"vem är bazil thredd","thredds bakgrund","vad gjorde bazil"}},{q="Var hittar man Bazil Thredd?",a="Bazil Thredd finns i den östra flygeln av instansen The Stockade. Han hålls inspärrad längst bort i avdelningen, i en central cell, bevakad av fångar från Defias Brotherhood som är lojala mot honom.",al={"var finns thredd","thredds plats","hur hittar man bazil thredd"}}},fx={["4fd859a6"]={q="Vad är Head of Bazil Thredd?",a="Det är det avhuggna huvudet från Bazil Thredd, fången som organiserar upproret djupt inne i Stockade. För Warden Thelwater är denna dystra trofé ett obestridligt fysiskt bevis på att ledaren för fängelseupproret har undanröjts för gott.",al={"vad är head of bazil thredd","föremålet head of bazil thredd","bazil thredds huvud"}},fe91a8a0={q="Var kommer Head of Bazil Thredd ifrån?",a="Det tas direkt från Bazil Thredd efter att du konfronterat och dödat honom i hans cell i Stormwinds Stockade, där han leder upproret under beskydd av sina brutala vakter.",al={"var får man bazil thredds huvud","hur får man head of bazil thredd","bazil thredd-huvudets källa"}}},fp="20,202,22.327.0,35.171.0,21.197.0,28.143.0"}
P.entries["item:head-of-deepfury"] = {n="Head of Deepfury",s="Det avhuggna huvudet av Kam Deepfury är ett dystert bevis på att Dark Iron-sammansvärjaren bakom sabotaget mot Thandol Span har mött sitt slut. Han dödades under upploppen i Stormwind Stockade, och hans död uppfyller Dun Modrs dvärgföreträdares personliga vendetta.",h="Det avhuggna huvudet av Kam Deepfury är ett dystert bevis på att Dark Iron-sammansvärjaren bakom sabotaget...",kw={"deepfury","dun modr","head of deepfury","kam deepfury","longbraid","motley garmason","stockade","thandol span"},ang={["faction:Alliance"]="Belöningen visar på växande motsättningar inom Alliansen. Mänsklig juridisk försiktighet i Stormwind ställs mot den hårda gränsrättvisa som Ironforges bergskrigare kräver.",["race:Dwarf"]="För Ironforges dvärgar handlar det om ren klanrättvisa att ta Deepfurys huvud och reglera den blodsskuld som Dark Iron-förräderiet vid Thandol Span har orsakat."},sec={{t="En sammansvuren får sin rättvisa",b="Kam Deepfury greps och spärrades in i Stormwind Stockade av politiska skäl. Mänsklig diplomatisk byråkrati räddade honom från omedelbar avrättning. För Ironforges bergskrigare vid Dun Modr var detta oacceptabelt. Underrättelser som Roggo avslöjade visade att Deepfury låg bakom den förödande attacken mot Thandol Span. Angreppet kostade kung Magnis soldater livet, liksom släktingar till Longbraid the Grim. Motley Garmason var bunden av sin plikt att stanna på sin post. Därför anlitade han Alliansens hjältar för att infiltrera det upploppsdrabbade fängelset och hämta Deepfurys huvud, så att dvärgarnas rättvisa skipades där den mänskliga diplomatin svek."}},faq={{q="Vem var Kam Deepfury?",a="Kam Deepfury var en förrädisk Dark Iron-dvärg som hjälpte till att planera sabotaget mot Thandol Span, den viktiga landbron mellan Wetlands och Arathi Highlands. Hans sammansvärjning ledde till att dvärgföreträdare dödades, däribland Longbraid the Grims bror.",al={"kam deepfurys bakgrund","vem är deepfury","kam deepfurys historia"}},{q="Varför satt Kam Deepfury i Stockade i stället för att avrättas?",a="Stormwinds myndigheter höll Deepfury vid liv av politiska skäl. Medan den mänskliga byråkratin nöjde sig med att låta honom ruttna i en fängelsecell, såg Ironforges bergskrigare denna mildhet som en skymf och krävde blod.",al={"varför fängslades deepfury","varför stockade"}},{q="Vem vill ha Head of Deepfury?",a="Motley Garmason, en dvärg stationerad vid Dun Modr i norra Wetlands, begär huvudet. Han är hedersbunden att stanna på sin post vid Longbraid the Grim och skickar därför en äventyrare för att slutföra det han själv inte kan göra.",al={"vem tar deepfurys huvud","lämna in fury runs deep"}},{q="Vad uppnår man genom att ta tillbaka huvudet?",a="När Deepfurys avhuggna huvud visas upp får de sörjande dvärgfamiljerna vid Dun Modr avslut och rättvisa. Det hämnas Longbraid the Grims dödade bror och visar att brott mot Ironforge inte kan döljas bakom mänskligt politiskt maktspel.",al={"varför ta med deepfurys huvud","resultatet av fury runs deep"}}},fx={["42407f6f"]={q="Vad är Head of Deepfury?",a="Det är det avhuggna huvudet från Kam Deepfury, en fängslad Dark Iron-dvärg som hålls djupt inne i Stormwind Stockade. Du tar det som obestridligt fysiskt bevis på att konspiratören bakom det katastrofala anfallet på Thandol Span till sist har fått sitt straff.",al={"head of deepfury","vad är head of deepfury","kam deepfurys huvud"}},ff6e9a29={q="Var kommer Head of Deepfury ifrån?",a="Huvudet tas direkt från Kam Deepfury själv i cellerna i The Stockade under Stormwind City. Mänskliga myndigheter låste in honom i stället för att avrätta honom, så du måste fälla honom i hans cell för att ta det.",al={"var får man head of deepfury","vem släpper head of deepfury","deepfury-huvudets källa"}}},fp="16,185,23.478.0,21.230.0,57.148.0,31.183.0,44.228.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="Head of Gath'Ilzogg",s="Gath'Ilzoggs avhuggna huvud är ett obestridligt bevis på att Blackrock-krigsherren har dödats. Att ta det bryter ledarskapet bakom belägringen av Stonewatch Keep och ger den hårt ansatta staden Lakeshire välbehövlig lättnad.",h="Gath'Ilzoggs avhuggna huvud är ett obestridligt bevis på att Blackrock-krigsherren har dödats.",kw={"blackrock","gath'ilzogg","lakeshire","magistrate solomon","redridge","stonewatch","stonewatch keep"},ang={["faction:Alliance"]="När huvudstaden är upptagen av interna stridigheter måste Alliansens frivilliga axla ansvaret för att försvara Redridge och själva slå ner Blackrock-ledarna.",["race:Human"]="För Stormwinds invånare hämnas dödandet av Gath'Ilzogg massakern på oskyldiga nybyggare och det förödmjukande fallet av Stonewatch Keep."},sec={{t="En prisbelönt krigsherre",b="Gath'Ilzogg ledde den brutala Blackrock-attacken som intog Stonewatch Keep, drev bort dess försvarare och utsatte den omgivande dalen för oupphörliga räder. Med Lakeshire på ruinens brant och Stormwind som i stort sett inte skickade några militära förstärkningar, utfäste Magistrate Solomon en belöning för krigsherrens huvud. Att döda Gath'Ilzogg i Stonewatchs befästa övre våningar och ta hans huvud krossar det lokala Blackrock-ledarskapet och markerar det första verkliga steget mot att återta borgen åt kungariket."}},faq={{q="Vem var Gath'Ilzogg?",a="Gath'Ilzogg var en mäktig Blackrock-orcisk krigsherre som ledde erövringen av Stonewatch Keep och styrde räder mot bosättningarna i Redridge Mountains, vilket drev Lakeshire till kollapsens brant.",al={"vem är gath'ilzogg","gathilzoggs historia","stonewatch-boss"}},{q="Vart förs huvudet när det har samlats in?",a="Huvudet förs direkt till Magistrate Solomon i Lakeshires stadshus som bevis på att belöningen på stadens efterlysningsanslag har infriats.",al={"vem vill ha huvudet","lämna in gath'ilzoggs huvud","magistrate solomons belöning"}},{q="Vad innebär Gath'Ilzoggs död för Lakeshire?",a="Hans död berövar Blackrock-inkräktarna deras främsta taktiker i Redridge. Även om många Blackrock-orcer fortfarande håller stånd i Stonewatch ger det lokala försvaret en chans att hålla regionen när deras befälskedja brutits.",al={"blir lakeshire räddat","betydelsen av att döda gath'ilzogg"}},{q="Var hittades Gath'Ilzogg?",a="Han höll till högt uppe i Stonewatch Keep, förskansad djupt inne i den erövrade befästningen tillsammans med sina personliga livvakter och löjtnanter.",al={"var finns gathilzogg","stonewatch keeps plats"}}},fx={["0b5a65b1"]={q="Vad är Head of Gath'Ilzogg?",a="Det är det avhuggna huvudet från Gath'Ilzogg, Blackrock-krigsherren som ledde anfallet mot Stonewatch Keep och organiserade räder som hotade Lakeshire. Att hugga av det ger obestridliga fysiska bevis på att den brutala ledaren bakom Blackrock-fälttåget i Redridge till sist har undanröjts.",al={"vad är head of gath'ilzogg","gathilzoggs huvud","gath ilzoggs huvud"}},ca6d6fe9={q="Var kommer Head of Gath'Ilzogg ifrån?",a="Huvudet tas direkt från Gath'Ilzogg efter att han dödats i de höga delarna av Stonewatch Keep. Krigsherren höll till i fästet han erövrat och planerade ytterligare angrepp mot folket i Redridge, tills en äventyrare vågade sig in i hans fäste och tog det som trofé.",al={"varifrån kommer head of gath'ilzogg","vem tog gath'ilzoggs huvud","gath ilzoggs huvuds ursprung"}},a1bebb0c={q="Varför vill Magistrate Solomon ha Head of Gath'Ilzogg?",a="Magistrate Solomon utlyste en sträng belöning och krävde fysiska bevis på krigsherrens död. Gath'Ilzogg bar ansvaret för att ha slaktat oskyldiga människor och intagit Stonewatch Keep. När hans huvud levereras får Lakeshires ledning veta att det omedelbara hotet är undanröjt, vilket ger upprättelse och hopp om att återta fästet.",al={"varför vill solomon ha gath'ilzoggs huvud","varför lämna in gath ilzoggs huvud","belöning för gath'ilzoggs huvud"}}},fp="19,133,18.453.0,20.185.0,39.133.0,49.230.0,28.152.0"}
P.entries["item:head-of-grimson"] = {n="Head of Grimson",s="Head of Grimson är det avhuggna troféhufvud som togs från Grimson the Pale, den korrumperade förvaltaren av Deep Elem Mine i Silverpine Forest. Det fördes till Dalar Dawnweaver vid The Sepulcher och utgör ett fysiskt bevis på att gruvans ledning har undanröjts. När gruvan säkrats kan Forsaken ta över värdefulla mineraltillgångar som ska understödja Varimathras militära fälttåg.",h="Head of Grimson är det avhuggna troféhufvud som togs från Grimson the Pale, den korrumperade förvaltaren av...",kw={"arugal","dalar dawnweaver","deep elem mine","grimson the pale","head of grimson","the sepulcher","silverpine forest","varimathras"},ang={["profession:Mining"]="Deep Elem Mine är en av Silverpines främsta mineralfyndigheter. Nu har dess vansinniga förvaltare röjts ur vägen, så att råmalmen kan flöda in i Hordens försörjningslinjer.",["race:Undead"]="Genom att ta gruvan uppfyller man Undercitys överkommandos strategiska direktiv och visar Forsakens beslutsamhet att återta Lordaerons livsviktiga infrastruktur från vansinniga kvarlevor."},sec={{t="Säkra Deep Elem Mine",b="Medan Dalar Dawnweaver studerade Archmage Arugals dunkla förtrollningar i säkerhet vid The Sepulcher, upptäckte Forsaken-spejare som kallades Darkstalkers ett strategiskt hot som växte fram i de sydöstra kullarna. Arugals mörka magi hade sipprat in i Deep Elem Mine, korrumperat arbetarna och drivit dess förvaltare, Grimson the Pale, till vansinne. För att säkra de underjordiska rikedomarna åt Varimathras styrkor skickade Dawnweaver ut hjältar för att fälla Grimson och återvända med hans avhuggna huvud som obestridligt bevis på att gruvan befriats från förbjuden magi."},{t="En trofé åt skräckherren",b="För Forsaken har krigets dystra troféer ett praktiskt värde. Genom att ta Grimson huvudet kan man försäkra sig om att arbetsstyrkan under jord i Deep Elem Mine är helt kuvad och att all kvarvarande lojalitet mot Arugals förvridna styre upphör. När Grimson är undanröjd kan gruvans rika mineralådror utvinnas och smidas om till vapen och rustningar, vilket upprätthåller Forsakens fortsatta framryckning genom Silverpine Forest och Lordaerons angränsande områden."}},faq={{q="Vem var Grimson the Pale?",a="Grimson the Pale var förvaltare av Deep Elem Mine, som ligger i de sydöstra kullarna i Silverpine Forest. Grimson och hans gruvarbetare utsattes för Archmage Arugals spridande skuggmagi och föll under dess mörka inflytande. Gruvan förvandlades till ett korrumperat fäste tills Forsaken ingrep.",al={"vem är grimson","grimson the pale bakgrund","grimsons bakgrund"}},{q="Varför vill Dalar Dawnweaver ha Grimson huvud?",a="Dalar Dawnweaver behöver konkreta bevis på att den korrumperade förmannen har undanröjts för gott. Varimathras vill ha Deep Elem Mines mineraltillgångar till Forsakens krigsinsats, och genom att döda Grimson bryter man motståndet från de korrumperade gruvarbetarna som håller tunnlarna.",al={"varför dalar vill ha huvudet","head of grimsons syfte","varför ta huvudet"}},{q="Var ligger Deep Elem Mine?",a="Deep Elem Mine ligger i kullarna sydost om The Sepulcher i Silverpine Forest. Den är en viktig mineraldepå som Forsaken och de korrumperade rester som fallit under Arugals magi strider om.",al={"var ligger deep elem mine","grimsons plats","gruvans plats i silverpine"}},{q="Vilken roll har Varimathras i det här uppdraget?",a="Varimathras leder Forsakens militära expansion genom Lordaeron från Undercity. Att säkra Deep Elem Mines resurser tjänar direkt hans strategiska mål och ger råmaterial till hans växande krigsmaskin i Silverpine.",al={"varimathras roll","varför vill varimathras ha gruvan","varimathras i silverpine"}}},fx={f0354d96={q="Vad är Head of Grimson?",a="Head of Grimson är det avhuggna huvudet från Grimson the Pale, taget som bevis på hans död. Grimson var en gång en vanlig uppsyningsman, men förvrängdes av den mörka magiska besmittelse som Archmage Arugal släppte lös över Silverpine. Att ta hans huvud markerar slutet på hans styre över Deep Elem Mine och ger obestridliga bevis på att gruvans korrumperade ledning har fallit.",al={"head of grimson","grimson-huvud","vad är grimsons huvud"}},["923cacb6"]={q="Var kommer Head of Grimson ifrån?",a="Denna dystra trofé kommer direkt från Deep Elem Mine, som ligger bland kullarna sydöst om The Sepulcher. Den huggs av från axlarna på Grimson the Pale, gruvans besmittade förman. Grimson dukade under för den vilda magi som läckte ut från Pyrewood och Shadowfang Keep och höll gruvan tills han fälldes på order av Dalar Dawnweaver.",al={"var får man head of grimson","vem släpper head of grimson","head of grimsons ursprung"}}},fp="15,198,27.409.0,26.275.1,25.184.0,46.226.0,36.158.0,45.173.0"}
P.entries["item:head-of-kelris"] = {n="Head of Kelris",s="Det avhuggna huvudet av Twilight Lord Kelris är ett obestridligt bevis på att ledaren för Twilight's Hammer i Blackfathom Deeps har fallit. Det fördes ut ur de fördärvade tempelruinerna och eftersöks av representanter för Argent Dawn, som vill bekräfta att hans vanheliga offer rituella offer har upphört.",h="Det avhuggna huvudet av Twilight Lord Kelris är ett obestridligt bevis på att ledaren för Twilight's Hammer i...",kw={"aku'mai","argent dawn","bashana runetotem","blackfathom deeps","skurkstreck i blackfathom","head of kelris","selgorm","twilight lord kelris"},ang={["faction:Alliance"]="Genom att överlämna Kelris huvud till Dawnwatcher Selgorm i Darnassus hämnas man vanhelgandet av ett uråldrigt Night Elf-tempel helgat åt Elune.",["faction:Horde"]="Om du visar upp huvudet för Bashana Runetotem i Thunder Bluff vinner du Cenarion Circles förtroende och bevisar deras hängivenhet åt att rena Kalimdor från dess fördärv."},sec={{t="En trofé av förstörelse",b="I Elunes sjunkna tempels nedsänkta djup iscensatte Twilight Lord Kelris mörka offer till Aku'mai, en monstruös tjänare åt en Old God. Att ta hans huvud markerar slutet på hans tyranniska ledarskap över Twilight's Hammers kultister och deras naga-allierade i grottan. Den makabra trofén måste föras tillbaka till civilisationerna vid ytan för att försäkra ledarna om att Kelris blodiga ceremonier äntligen har upphört."},{t="Bevis för Argent Dawn",b="I flera månader trodde Argent Dawn att Kelris var död eller försvunnen, tills hans ondskefulla inflytande åter dök upp tillsammans med Kalimdors tilltagande skuggor. När huvudet visas upp för agenter i Darnassus eller Thunder Bluff regleras gamla belöningar, och det bekräftar att hans försök att kasta världen tillbaka i uråldrigt kaos har stoppats."}},faq={{q="Vem var Twilight Lord Kelris?",a="Kelris var ledare för Twilight's Hammer-sekten som hade slagit sig ner i Blackfathom Deeps. I förbund med naga iscensatte han rituella offer av oskyldiga för att föda Aku'mai, en hydra som tjänar en Old God, i sin jakt på mörk kraft och uråldrigt kaos.",al={"vem är kelris","kelris historia","twilight lord kelris"}},{q="Vem vill ha Head of Kelris?",a="Alliansens förkämpar överlämnar huvudet till Dawnwatcher Selgorm i Darnassus, medan hordens äventyrare tar det till Bashana Runetotem på Elder Rise i Thunder Bluff. Dawnwatcher Selgorm tjänar Argent Dawn, medan Bashana Runetotem tillhör Cenarion Circle.",al={"vem tar emot kelris huvud","lämna in head of kelris","vem ska jag ge kelris huvud till"}},{q="Varför bryr sig Argent Dawn om Kelris?",a="Argent Dawn håller uppsikt över ondskefulla hot som sätter Azeroth i fara. Kelris var en ökänd skurk som länge hade gäckat dem, och hans dyrkan av Old Gods och offer av oskyldiga utgjorde ett allvarligt hot mot Kalimdors balans.",al={"varför argent dawn kelris","argent dawn blackfathom"}},{q="Var får man tag på huvudet?",a="Det huggs av från liket efter Twilight Lord Kelris i hans helgedom i grottan Blackfathom Deeps, som ligger under The Zoram Strand längs Ashenvales kust.",al={"var får man kelris huvud","kelris huvud plats"}}},fx={c257c517={q="Vad är Head of Kelris?",a="Det är det avhuggna huvudet från Twilight Lord Kelris, ledaren för Twilight's Hammer-kultisterna som slog sig ner djupt inne i ruinerna av Blackfathom Deeps. Det är ett makabert, obestridligt bevis på att kultens ondskefulle mästare i det sjunkna templet har dödats och att hans ritualer har fått ett slut.",al={"head of kelris","vad är head of kelris","föremålet kelris huvud"}},["0e645b89"]={q="Var kommer Head of Kelris ifrån?",a="Huvudet tas direkt från Twilight Lord Kelris i djupet av Blackfathom Deeps längs The Zoram Strand. Du måste kämpa dig förbi hans fanatiska kultister och vanskapta tjänare för att döda skymningsherren i hans innersta helgedom innan du tar det.",al={"var får man head of kelris","kelris-huvudets ursprung","hur får man head of kelris"}}},fp="14,116,16.305.0,18.291.0,29.202.0,29.236.0,43.156.0,27.139.0"}
P.entries["item:head-of-lathoric-the-black"] = {n="Head of Lathoric the Black",s="The Head of Lathoric the Black är ett bevis som förs från Searing Gorge till Thorius i Ironforge. Det är knutet till faran kring Obsidion.",h="The Head of Lathoric the Black är ett bevis som förs från Searing Gorge till Thorius i Ironforge.",kw={"lathoric the blacks huvud","obsidions hjärta","ironforge","lathoric","obsidion","searing gorge","thorius"},ang={["race:Dwarf"]="Som dvärg bär du med dig bevis på faran i Searing Gorge tillbaka till Thorius i Ironforge."},sec={{t="Ett dystert tecken",b="Thorius i Ironforge ber dig hämta The Head of Lathoric the Black från Searing Gorge. Huvudet bevisar att Lathoric the Black är död och förs tillsammans med The Heart of Obsidion."}},faq={{q="Vem kommer huvudet från?",a="Huvudet kommer från Lathoric the Black, som finns i Searing Gorge.",al={"lathorics huvud"}},{q="Varför vill Thorius ha det?",a="Thorius ber dig ta med huvudet till Ironforge som bevis med koppling till faran kring Obsidion.",al={"varför huvudet till thorius","bevis till thorius"}},{q="Vart ska jag ta huvudet?",a="Ta med The Head of Lathoric the Black till Thorius i Ironforge.",al={"lämna in huvudet","vart ta lathorics huvud"}},{q="Vad följer med huvudet?",a="The Heart of Obsidion förs tillsammans med huvudet till Thorius.",al={"hjärtat med huvudet","obsidions föremål"}}},fp="26,138,12.183.0,21.67.0,25.97.0,25.61.0,24.58.0"}
P.entries["item:head-of-nagaz"] = {n="Head of Nagaz",s="Nagaz huvud visar att Magistrate Malebs sökande i Alterac Mountains nådde Argus Wake. Maleb fruktar att gruppen kan hota Syndicate.",h="Nagaz huvud visar att Magistrate Malebs sökande i Alterac Mountains nådde Argus Wake.",kw={"alterac mountains","argus shadow mages","argus wake","dark council","nagaz huvud","nagaz","southshore","strahnbrad","syndicate","the uplands"},ang={["faction:Alliance"]="Som Alliance-resenär bär du Magistrate Malebs oro från Southshore in i Uplands, där Syndicate är som starkast."},sec={{t="Bevis för Maleb",b="I Uplands norr om Strahnbrad leder Nagaz de Argus Shadow Mages som nämns i ett brev till Magistrate Maleb. Maleb misstänker att Argus Wake har gått samman med Syndicate. Nagaz huvud ger Southshore bevis för att sändebuden har hittats."}},faq={{q="Vem var Nagaz?",a="Nagaz var medlem i Argus Wake och ledde Argus Shadow Mages i Uplands.",al={"vem är nagaz","nagaz person"}},{q="Var hittar jag Nagaz?",a="Nagaz finns i Uplands i Alterac Mountains, norr om Strahnbrad.",al={"nagaz plats","var nagaz"}},{q="Varför vill Magistrate Maleb ha Nagaz huvud?",a="Magistrate Maleb vill ha bevis för att Nagaz och Argus Shadow Mages finns i Uplands, där han fruktar att Argus Wake kan hota Syndicate.",al={"varför nagaz huvud","maleb vill ha huvudet"}},{q="Vad är Argus Wake?",a="Argus Wake är en grupp vars medlem Nagaz skrev till Syndicate. Maleb fruktar att dess allians med Syndicate kan utgöra ett hot.",al={"vad betyder argus wake","vilka är argus wake"}},{q="Vad gör Argus Shadow Mages?",a="Argus Shadow Mages är sändebud från Argus Wake som hittades tillsammans med Nagaz i Uplands.",al={"argus-magiker","skuggmagiker"}}},fp="13,155,15.256.0,14.79.0,23.70.0,46.144.0,23.131.0,38.89.0"}
P.entries["item:head-of-overseer-maltorius"] = {n="Head of Overseer Maltorius",s="Head of Overseer Maltorius är bevis på en belöning i Searing Gorge. Lookout Captain Lolo Longstriker ber dig ta tillbaka det från The Cauldron.",h="Head of Overseer Maltorius är bevis på en belöning i Searing Gorge.",kw={"the cauldron","head of overseer maltorius","lolo longstriker","maltorius","overseer maltorius","searing gorge","the slag pit","thorium brotherhood"},ang={["race:Dwarf"]="Som dvärg möter du en Dark Iron-befälhavare i The Slag Pit, där hans manskap arbetar i The Cauldron."},sec={{t="En belöning i ravinen",b="Lookout Captain Lolo Longstriker utlyser en belöning på Maltorius, en Dark Iron-dvärg som befäl över manskapet i The Slag Pit i The Cauldron. Ordern kallar honom en avfällig agent från Thorium Brotherhood. Hans avhuggna huvud är beviset Longstriker ber dig hämta från djupet av The Slag Pit."}},faq={{q="Vem var Overseer Maltorius?",a="Overseer Maltorius var en Dark Iron-dvärg och befälhavare för manskapet i The Slag Pit i The Cauldron. Belöningen kallar honom en avfällig agent från Thorium Brotherhood.",al={"vem är maltorius"}},{q="Var hittar jag Maltorius?",a="Maltorius finns djupt inne i The Slag Pit i The Cauldron, i Searing Gorge.",al={"maltorius plats","var är maltorius"}},{q="Varför är Maltorius efterlyst?",a="Belöningsordern kallar Maltorius en avfällig agent från Thorium Brotherhood och beordrar att han ska dödas.",al={"varför är maltorius efterlyst","belöning på maltorius"}},{q="Vem vill ha Maltorius huvud?",a="Lookout Captain Lolo Longstriker utlyser belöningen och ber dig ta tillbaka Maltorius huvud som bevis.",al={"vem utlyste belöningen","lolo maltorius"}},{q="Vad är Head of Overseer Maltorius?",a="Det är Maltorius avhuggna huvud, taget som bevis för belöningen i Searing Gorge.",al={"maltorius huvud","huvudföremål"}}},fp="26,151,21.281.0,27.148.0,27.76.0,24.88.0,27.104.0,39.82.0"}
P.entries["item:head-of-targorr"] = {n="Head of Targorr",s="Head of Targorr är det bistera bevis Guard Berton kräver i Lakeshire för att bekräfta att Targorr the Dread är död. Den tillfångatagna orchen var tidigare Blackrock-krigshövdingen Gath'Ilzoggs främsta bödel i Redridge Mountains. Han dömdes till döden i Stormwind Stockade, men misstänkt politiskt ingripande stoppade avrättningen.",h="Head of Targorr är det bistera bevis Guard Berton kräver i Lakeshire för att bekräfta att Targorr the Dread...",kw={"blackrock","gath'ilzogg","guard berton","head of targorr","lakeshire","redridge","stockade","targorr","targorr the dread"},ang={["faction:Alliance"]="För alliansens kämpar som försvarar Redridge hämnas Targorrs fall de slaktade försvararna i Lakeshire och kringgår korrupt adelbyråkrati i Stormwind.",["race:Human"]="Mänskliga soldater och stadsvakter hyser personligt agg mot Targorr för hans sadistiska tortyr av tillfångatagna soldater från kungariket under Blackrock-offensiven."},sec={{t="En uppskjuten avrättning",b="Targorr the Dread blev ökänd i Redridge som den brutala bödeln under Blackrock-klanens krigshövding Gath'Ilzogg. Targorr torterade och slaktade försvarare av kungariket Stormwind. Till slut tillfångatogs han och dömdes till döden i Stormwind Stockade. Byråkratiska ingripanden från adelsmän i Stormwind stoppade dock mystiskt nog straffet. Det fick lokala vakter som Berton att misstänka fuffens och korruption i huvudstaden."},{t="Rättvisa vid gränsen",b="Guard Berton fruktade att Targorr skulle kunna användas som politisk bricka eller på något sätt planera en flykt. Därför anlitade han en utomstående kämpe för att ta sig in i det oroliga fängelset och slutföra det domstolarna hade skjutit upp. När Targorrs huvud höggs av sattes det förlamade rättssystemet åt sidan. Det gav ett avslut åt de sörjande familjerna och de belägrade försvararna i Lakeshire, som hade lidit under bödelns klinga."}},faq={{q="Vem var Targorr the Dread?",a="Targorr var en ökänd orkisk bödel i Blackrock-klanen i Redridge. Under krigshövdingen Gath'Ilzogg blev han beryktad för att tortera och avrätta tillfångatagna soldater och försvarare från Stormwind.",al={"targorr","targorrs historia","vem är targorr"}},{q="Varför hölls Targorr vid liv i Stockade?",a="Targorr hade formellt dömts till döden, men byråkratiska adelsmän i Stormwind stoppade mystiskt nog avrättningen. Vakterna i Lakeshire misstänker politiskt fuffens och korruption. De fruktar att orchen hålls kvar som förhandlingsbricka.",al={"varför avrättas inte targorr","targorrs uppskjutna avrättning","rättegång i stockade"}},{q="Vem vill ha Targorrs huvud?",a="Guard Berton, som är posterad utanför Lakeshire Inn, ber om det avhuggna huvudet. Han har sett förödelsen Targorr orsakade i Redridge Mountains och vill ha definitiva bevis på att bödeln aldrig kan bli fri.",al={"vem tar targorrs huvud","guard berton","lämna in targorrs huvud"}},{q="Var hittar man Targorr?",a="Targorr the Dread sitter fängslad i Stormwind Stockade, bakom järngaller i de centrala cellblocken tillsammans med upproriska fångar.",al={"targorrs plats","hitta targorr","var i stockade"}}},fx={["1b8c229f"]={q="Vad är Head of Targorr?",a="Det är det avhuggna huvudet från Targorr the Dread, den ökände överbödeln som tjänade under Blackrock-krigsherren Gath'Ilzogg. Targorr tillfångatogs och hölls inspärrad i Stormwind Stockade, dömd till döden för att ha torterat och avrättat kungarikets tappra försvarare.",al={"vad är head of targorr","information om head of targorr","beskrivning av targorrs huvud"}},["29061798"]={q="Varifrån kommer Head of Targorr?",a="Huvudet kommer från Targorr the Dread själv, som sitter inspärrad djupt inne i Stormwind Stockade. När en adelsman från Stormwind stoppade hans planerade avrättning ger Guard Berton en äventyrare i uppdrag att ta saken i egna händer och smyga in i fängelsecellerna för att hugga huvudet av den hänsynslösa orchen.",al={"varifrån kommer head of targorr","vem släpper head of targorr","targorrs huvuds ursprung"}}},fp="15,187,19.344.0,16.356.0,26.183.0,43.205.0,25.202.0,23.118.0"}
P.entries["item:head-of-vancleef"] = {n="Head of VanCleef",s="Edwin VanCleefs avhuggna huvud är ett dystert, obestridligt bevis på att ledaren för Defias Brotherhood har fallit. Det fördes från The Deadmines djup till Sentinel Hill och står som ett tecken på People's Militia hårt vunna hämnd.",h="Edwin VanCleefs avhuggna huvud är ett dystert, obestridligt bevis på att ledaren för Defias Brotherhood har...",kw={"the deadmines","edwin vancleef","gryan stoutmantle","head of vancleef","people's militia","sentinel hill","westfall"},ang={["class:Rogue"]="Edwin VanCleef var en av de dödligaste mästertjuvarna i människans historia. Att ta hans huvud markerar det definitiva slutet på en enastående karriär i skuggor och sabotage.",["faction:Alliance"]="När VanCleefs huvud visas upp får People's Militia en förlösande seger, men det blottar också den oroande frånvaron av Stormwinds adelsråd under Westfalls mörkaste stund."},sec={{t="Bevis på mästarens fall",b="I månader styrde Edwin VanCleef Defias Brotherhoods terror från The Deadmines innersta kammare, skyddad av tungt beväpnade laglösa, gobliningenjörer och en väldig krigsbest. Enbart ord kunde aldrig övertyga Westfalls hårt prövade bosättare om att deras mardröm var över. Gryan Stoutmantle, ledare för People's Militia, krävde obestridliga fysiska bevis innan han förklarade landsbygden säker. Att hugga av ledarens huvud och föra ut det i dagsljuset ger de utmattade försvararna en konkret försäkran om att den store arkitekten bakom deras undergång aldrig mer kommer att hota Westfall."},{t="En dyster seger",b="Även om Stoutmantle ville se VanCleef död för Westfalls bästa, är det med stor högtidlighet han visar upp trofén. VanCleef var en gång den vördnadsvärde byggmästaren som återuppbyggde Stormwind efter det första kriget, innan svek och obetalda skulder drev honom och Stonemasons Guild till laglös revolt. Hans avhuggna huvud markerar slutet på den lokala milisens kampanj i Westfall, men blottlägger också kungadömets oförmåga att hantera sina egna inre oroligheter och lämnar åt frivilliga bönder och utländska äventyrare att skipa rättvisa."}},faq={{q="Vem vill ha Head of VanCleef?",a="Gryan Stoutmantle, kapten för People's Militia vid Sentinel Hill i Westfall, behöver huvudet för att slutföra den långa kampanjen mot Defias Brotherhood.",al={"vem ska jag lämna in det till","vem tar vancleefs huvud","vart ska vancleefs huvud"}},{q="Varför kräver Gryan Stoutmantle just hans huvud?",a="Defias Brotherhood höll Westfall i ett så hårt grepp så länge att ingen skulle tro på rykten om VanCleefs död utan obestridliga fysiska bevis. Stoutmantle behöver ett otvetydigt bevis för att lugna de hårt prövade bönderna och visa att milisens kamp inte var förgäves.",al={"varför ta hans huvud","varför vancleefs huvud"}},{q="Var får man tag på huvudet?",a="Det tas från Edwin VanCleef ombord på hans hemliga pansarkrigskepp, som finns allra längst in i The Deadmines under Moonbrook i sydvästra Westfall.",al={"var får man vancleefs huvud","hur får man tag på head of vancleef"}},{q="Tar dödandet av VanCleef slut på Defias Brotherhood?",a="Stoutmantle ser hans död som början på slutet för brödraskapet, men utbrytargrupper, laglösa banditer och sympatisörer finns fortfarande kvar i Westfall, Elwynn Forest och områdena bortom.",al={"är defias besegrade","vad händer med defias"}}},fx={["4a1d52aa"]={q="Vad är Head of VanCleef?",a="Head of VanCleef är det avhuggna huvudet från Edwin VanCleef, hjärnan bakom Defias Brotherhood, som gömmer sig djupt inne i The Deadmines. Det är ett makabert, obestridligt bevis på att ledaren för de fredlösas uppror äntligen har besegrats.",al={"vad är head of vancleef","föremålet head of vancleef","edwin vancleefs huvud"}}},fp="16,176,26.514.0,14.475.1,31.167.0,56.249.0,27.149.0,55.192.0"}
P.entries["item:heart-of-flame-quest-item"] = {n="Heart of Flame",s="Ett Heart of Flame är ett av materialen Velarok Windblade behöver i Searing Gorge. Det hjälper honom att förbereda en fackla för ett angrepp mot de fyra vakttornen.",h="Ett Heart of Flame är ett av materialen Velarok Windblade behöver i Searing Gorge.",kw={"golem oil","heart of flame","hearts of flame","searing gorge","vakttorn","the flawless flame","torch of flawless flame","velarok windblade"},sec={{t="Till facklan",b="Velarok Windblade behöver fyra Hearts of Flame och fyra klot med Golem Oil i Searing Gorge. Med materialen kan han tillverka en fackla med flawless flame. Han tänker sätta de fyra vakttornen i brand och slå till innan försvararna hinner reagera."}},faq={{q="Vad används ett Heart of Flame till?",a="Velarok Windblade behöver fyra Hearts of Flame för att tillverka en fackla med flawless flame. Han tänker använda den för att sätta de fyra vakttornen i brand.",al={"användning av heart of flame","varför heart of flame","flame heart"}},{q="Vem vill ha ett Heart of Flame?",a="Velarok Windblade vill ha fyra Hearts of Flame och fyra klot med Golem Oil till facklan han tänker tillverka.",al={"vem behöver det","velarok heart of flame","vem vill ha flame heart"}},{q="Var hittar jag Hearts of Flame?",a="Golemer och elementaler i Searing Gorge är varelserna Velarok hänvisar dig till för att hitta Hearts of Flame.",al={"heart of flame plats","var hitta flame heart","hearts of flame i searing gorge"}},{q="Hur många Hearts of Flame behöver Velarok?",a="Velarok behöver fyra Hearts of Flame för att tillverka facklan med flawless flame.",al={"antal heart of flame","hur många flame hearts","behöver fyra hearts"}},{q="Vad ska facklan med flawless flame användas till?",a="Velarok tänker använda facklan för att sätta fyra vakttorn i brand och skapa en öppning för ett anfall.",al={"fackla med flawless flame","facklans syfte","varför fyra torn"}}},fp="14,156,13.244.0,29.137.0,29.115.0,32.103.0,43.71.0,40.102.0"}
P.entries["item:heart-of-isha-awak"] = {n="Heart of Isha Awak",s="Jägare söker efter Isha Awaks hjärta längs The Merchant Coast söder om Ratchet. Mahren Skyseer vill ha det som bevis på att den djupa undergången har övervunnits.",h="Jägare söker efter Isha Awaks hjärta längs The Merchant Coast söder om Ratchet.",kw={"den djupa fasan","heart of isha awak","isha awak","mahren skyseer","the merchant coast","ratchet","the barrens"},ang={["class:Hunter"]="Som jägare ställs du inför ett yttersta modprov när du spårar och besegrar den djupa undergången under vågorna vid The Merchant Coast.",["race:Tauren"]="Som taurenjägare följer du Isha Awak för att förenas andligt med naturens våldsammaste rovdjur, vägledd av den äldre Mahren Skyseer."},sec={{t="Den djupa fasans trofé",b="Isha Awak jagar i havet utanför The Merchant Coast, söder om Ratchet. Sjömän och kustbor vördar och fruktar den väldiga tröskaren, känd som den djupa undergången. Den har dödat många mänskliga inkräktare längs kusten. Mahren Skyseer, en taurenmystiker, ser en hedervärd jägare, inte ett tanklöst hot. Hon tror att dess våldsamma ande bor i dess hjärta. Mahren skickar modiga jägare ner i vågorna för att besegra Isha Awak på dess eget revir och ta hjärtat som både trofé och andligt offer."}},faq={{q="Vad är Heart of Isha Awak?",a="Heart of Isha Awak är hjärtat från den jättelika tröskaren som jagar i vattnen söder om Ratchet. Jägare hämtar det som bevis på att de övervunnit den djupa undergången åt Mahren Skyseer.",al={"heart of isha awak","isha awak hjärta","vad är det här för hjärta"}},{q="Vem vill ha Heart of Isha Awak?",a="Mahren Skyseer, en tauren siare som slagit läger längs The Merchant Coast söder om Ratchet, vill att jägare hämtar hjärtat. Hon vill hedra besten och ta dess ande till sig.",al={"vem tar hjärtat","vem ska jag ge hjärtat till","mahren skyseer"}},{q="Var finns Isha Awak?",a="Isha Awak håller till i havet utanför The Merchant Coast i östra Barrens, söder om Ratchet.",al={"isha awak plats","var finns isha awak","var hittar man isha awak"}},{q="Varför vill Mahren Skyseer ha hjärtat?",a="Mahren Skyseer ser Isha Awak som en hedervärd jägare och en värdig motståndare. Genom att döda besten och hålla dess hjärta tar en jägare havsvarelsens ande till sig.",al={"varför döda isha awak","varför vill mahren ha hjärtat"}}},fx={["1c3e01c4"]={q="Varifrån kommer Heart of Isha Awak?",a="Hjärtat är ingen tillverkad artefakt, utan ett organ som tagits direkt från Isha Awak, det mäktiga havsvidundret som kallas Deep Doom. Varelsen hemsöker vattnen utanför The Barrens kust söder om Ratchet och fruktas av lokalbefolkningen, vars anhöriga den har slukat. Det enda sättet att få tag på hjärtat är att fälla detta havets urtidsrovdjur och skära ut det.",al={"heart of isha awak ursprung","varifrån kom heart of isha awak","vem skapade heart of isha awak"}}},fp="18,147,23.489.0,31.174.0,33.189.0,25.94.0,39.171.0"}
P.entries["item:heart-of-mokk"] = {n="Heart of Mokk",s="Heart of Mokk tas från Mokk the Savage på Cape of Stranglethorn. Fin Fizracket söker efter det som botemedel mot Stranglethorn Fever.",h="Heart of Mokk tas från Mokk the Savage på Cape of Stranglethorn.",kw={"the cape of stranglethorn","fin fizracket","heart of mokk","mokk the savage","stranglethorn fever","witch doctor unbagwa"},sec={{t="Ett botemedel mot febern",b="Fin Fizracket har drabbats av en dödlig feber i Booty Bay och tror att bara hjärtat från Mokk the Savage kan bota honom. Witch Doctor Unbagwa, gömd i en grotta på den södra udden, kan frammana det svårfångade vita odjuret. Hjärtat är vad Fin behöver för att återfå sina krafter."}},faq={{q="Vad är Heart of Mokk?",a="Heart of Mokk är hjärtat från Mokk the Savage, ett svårfångat vitt odjur på Cape of Stranglethorn.",al={"mokks hjärta","hjärtobjekt","vad är mokks hjärta"}},{q="Vem behöver Heart of Mokk?",a="Fin Fizracket i Booty Bay söker Heart of Mokk som botemedel mot Stranglethorn Fever.",al={"vem vill ha det","fin fizracket hjärta","vem behöver mokk"}},{q="Varifrån kommer Heart of Mokk?",a="Heart of Mokk kommer från Mokk the Savage på Cape of Stranglethorn.",al={"var är hjärtat","mokks plats","hitta heart of mokk"}},{q="Hur kan Mokk frammana?",a="Witch Doctor Unbagwa, i en gömd grotta på den södra udden, kan frammana Mokk the Savage.",al={"frammana mokk","var är unbagwa","witch doctor mokk"}}},fp="13,131,14.263.0,26.99.0,28.85.0,39.70.0,25.88.0"}
P.entries["item:heart-of-obsidion"] = {n="Heart of Obsidion",s="Heart of Obsidion är beviset Thorius behöver från Searing Gorge. Det visar på faran som fortfarande hotar dessa trakter.",h="Heart of Obsidion är beviset Thorius behöver från Searing Gorge.",kw={"heart of obsidion","ironforge","lathoric the black","obsidion","old gods","ragnaros","searing gorge","thorius"},ang={["race:Dwarf"]="Som dvärg tar Thorius Ironforges förräderi hårt. Han fruktar att Old Gods inflytande hotar hans folk."},sec={{t="Ett återlämnat hjärta",b="Thorius i Ironforge ber om Heart of Obsidion efter en varning från Dorius. Hjärtat, som tagits från Obsidion i Searing Gorge, förs tillbaka tillsammans med Head of Lathoric the Black. Thorius måste se båda innan han kan tro på det som har hänt."},{t="Thorius sorg",b="När Thorius ser Heart of Obsidion och Lathoric the Blacks huvud blir han likblek. Han får veta att hans egen bror gillrade fällan och förrådde Ironforge. Thorius fruktar att Old Gods inflytande fortfarande är starkt i dessa trakter och att Ragnaros kan korrumpera även de ädla och hedervärda."}},faq={{q="Vad är Heart of Obsidion?",a="Heart of Obsidion är en trofé från Obsidion i Searing Gorge.",al={"heart of obsidion","obsidions hjärta"}},{q="Vem behöver Heart of Obsidion?",a="Thorius i Ironforge ber om Heart of Obsidion tillsammans med Head of Lathoric the Black.",al={"vem vill ha obsidions hjärta","thorius hjärta"}},{q="Varför vill Thorius ha hjärtat?",a="Thorius behöver Heart of Obsidion och Head of Lathoric the Black som bevis för förräderiet.",al={"varför hjärtat","vilka bevis behöver thorius"}},{q="Vad bevisar hjärtat?",a="Tillsammans med Lathoric the Blacks huvud visar hjärtat Thorius att varningen om en fälla var sann.",al={"bevis på hjärtat","vad hände med thorius"}}},fp="17,117,16.245.0,15.273.1,30.71.0,32.93.0,32.96.1,26.94.1"}
P.entries["item:heartswood"] = {n="Heartswood",s="Heartswood är virke från ett heligt träd som växer bland The Ruins of Ordil'Aran i nordvästra Ashenvale. Det spirade där två forntida älskande fann sin sista vila, och dess klang av evig hängivenhet gör det till ett oumbärligt lockbete för att kalla fram en succubus.",h="Heartswood är virke från ett heligt träd som växer bland The Ruins of Ordil'Aran i nordvästra Ashenvale.",kw={"anathera","ashenvale","gakin the darkbinder","heartswood","latherion","ordil'aran","succubus"},ang={["class:Warlock"]="För alliansens häxmästare är det en avgörande övergångsrit att säkra Heartswood, på uppdrag av Gakin the Darkbinder. Virket ger det känslomässiga lockbete som krävs för att tvinga och binda en succubus som tjänare.",["race:NightElf"]="Trädet är ett tragiskt, heligt minnesmärke från War of the Ancients. Att häxmästare och kultister skändar det är därför en bitter kränkning av minnet av fallna förfäder."},sec={{t="Ett monument över hängivenhet",b="Heartswood växer bland alvernas stenar i The Ruins of Ordil'Aran i nordvästra Ashenvale. Enligt legenden föll två älskande vid namn Anathera och Latherion sida vid sida under det förödande War of the Ancients för tusentals år sedan. På just den plats där de drog sitt sista andetag slog ett märkligt träd rot och blommade ut som ett evigt vittnesbörd om deras hängivenhet. Även årtusenden senare sjunger virket från trädet av minnet av en odödlig passion, vilket gör det till ett föremål för stor nyfikenhet bland dem som studerar känslomässiga och andliga band."},{t="Ett verktyg för underkuvande",b="Heartswood föddes ur rena känslor, men väcker mörkare intresse. Succubi, demoner som livnär sig på passion, längtan och känslomässig exploatering, dras starkt till föremål genomsyrade av äkta, odödlig kärlek. Mänskliga och gnomiska häxmästare som undervisas av Gakin the Darkbinder i Stormwind söker särskilt efter detta sällsynta virke för att skapa ett rituellt lockbete. Med hjälp av den medfödda resonansen från de älskandes offer kan en utövare locka en succubus genom Nether, dra in henne i en åkandecirkel och binda henne till sin vilja."}},faq={{q="Vad är Heartswood?",a="Heartswood är virke från ett träd som sköt upp i Ashenvales The Ruins of Ordil'Aran, där två forntida Night Elf-älskande dog tillsammans under War of the Ancients.",al={"heartswood-trädet","vad är heartswood","heartswoods historia"}},{q="Vilka var Anathera och Latherion?",a="Anathera och Latherion var älskande som stred sida vid sida under War of the Ancients. När de båda föll i strid gödde deras sista omfamning jorden, och Heartswood-trädet växte upp som en bestående symbol för deras hängivenhet.",al={"anathera och latherion","heartswoods älskande","vilka dog vid heartswood"}},{q="Varför behöver häxmästare Heartswood?",a="Succubi är demoniska varelser som förkroppsligar begär och känslomässig manipulation. Eftersom Heartswood genljuder starkt av obeveklig, evig kärlek använder häxmästare det som ett kraftfullt psykiskt lockbete för att fresta och kalla en succubus till den fysiska världen.",al={"varför vill häxmästare ha heartswood","heartswood och succubus","heartswoods syfte"}},{q="Var hittar man Heartswood?",a="Heartswood finns i The Ruins of Ordil'Aran, i de nordvästra delarna av Ashenvales skog nära gränsen till Darkshore.",al={"heartswoods plats","var finns heartswood","heartswood i the ruins of ordil'aran"}}},fx={["61f35e8f"]={q="Varifrån kommer Heartswood, och vem skapade det?",a="Heartswood skapades inte av dödliga händer, utan skördades från ett ensamt träd som slog rot i The Ruins of Ordil'Aran i nordvästra Ashenvale. Under det katastrofala War of the Ancients för årtusenden sedan föll två älskande, Anathera och Latherion, tillsammans i strid. Där de drog sitt sista andetag slog trädet rot och växte, ett levande monument över deras eviga hängivenhet.",al={"heartswoods ursprung","varifrån kommer heartswood","hur skapades heartswood"}}},fp="10,201,22.420.0,21.390.1,19.157.0,32.223.0,32.184.0,30.113.0"}
P.entries["item:heartswood-core"] = {n="Heartswood Core",s="Häxmästare i Stormwind City använder Heartswood Core för att kalla fram en succubus. Gakin the Darkbinder tillhandahåller den förtrollade ritualfokuseraren, tillverkad av trä från ett uråldrigt träd, för att genomborra Twisting Nether och dra demonen in i en magisk åkallandecirkel.",h="Häxmästare i Stormwind City använder Heartswood Core för att kalla fram en succubus.",kw={"gakin the darkbinder","heartswood core","slaughtered lamb","stormwind","succubus","åkallandecirkel","bindningen","häxmästare"},ang={["class:Warlock"]="Som häxmästare i Alliansen använder du Heartswood Core som en oumbärlig träningsrelik för att kalla fram och bemästra din första succubus."},sec={{t="En fokuserare för Nether",b="Under Slaughtered Lamb i Stormwinds Mage Quarter utför häxmästare riter utom stadsvaktens synhåll. Heartswood Core kanaliserar magin som behövs för att inleda en bindningsritual. Den är tillverkad av trä från ett uråldrigt träd och rymmer tillräckligt med kvarvarande magi för att genomborra slöjan mellan världarna. Vid en invigd åkallandecirkel riktar en novis mörka konster genom kärnan och öppnar en passage till Twisting Nether, så att en succubus dras över gränsen."},{t="Bindningens prövning",b="En häxmästare som åkallar en demon måste ändå bevisa sin överlägsenhet över dess listiga och förföriska natur för att kunna kontrollera den. Gakin ger Heartswood Core till lovande utövare så att de kan möta den åkallade demonen i strid. Succubi utnyttjar svaghet och kan övermanna veka sinnen, vilket gör mötet till en dödlig övergångsrit. Den blivande häxmästaren måste kuva besten och återlämna den förbrukade kärnan till Gakin för att bevisa att viljan är stark nog att binda tjänaren för gott."}},faq={{q="Vad används Heartswood Core till?",a="Häxmästare använder Heartswood Core vid åkallandecirkeln under Slaughtered Lamb för att öppna en portal till Twisting Nether och dra en succubus in i vår värld. Du måste strida mot och binda den åkallade demonen.",al={"vad gör heartswood core","användning av heartswood core","syftet med heartswood core"}},{q="Vem tillhandahåller Heartswood Core?",a="Gakin the Darkbinder, en mästerlig häxmästare, tillhandahåller Heartswood Core och tränar noviser i de dolda katakomberna under Slaughtered Lamb i Stormwinds Mage Quarter.",al={"var får jag heartswood core","vem ger heartswood core"}},{q="Var ska kärnan användas?",a="Använd kärnan vid åkallandecirkeln i kryptorna under Slaughtered Lamb, djupt under Stormwinds gator.",al={"heartswood core plats","var åkallar man en succubus"}},{q="Vad händer när ritualen är klar?",a="När du har kallat fram succubusen ska du besegra den i strid och skicka tillbaka den till tomrummet. Återvänd sedan med Heartswood Core till Gakin the Darkbinder för att lära dig hur du kan befalla demonen efter behag.",al={"vad gör jag efter åkallningen","lämna in heartswood core"}}},fx={["34d5c17e"]={q="Vad är Heartswood Core?",a="Heartswood Core är en förtrollad ockult relik som skapats särskilt för åkallelseritualer. Den bereds av utövare av mörk magi och fungerar som en magisk katalysator, kraftfull nog att genomborra slöjan mellan världar och dra en succubus från Twisting Nether in i en åkallandecirkel.",al={"heartswood cores historia","vad är heartswood core","heartswood-föremål"}},a2df89b9={q="Varifrån kommer Heartswood Core, och vem skapade den?",a="Kärnan bereds av rå Heartswood som hämtats från The Ruins of Ordil'Aran i Ashenvale, och formas och förstärks under ledning av Gakin the Darkbinder. Gakin anförtro den färdiga reliken åt lovande warlocks som studerar under Slaughtered Lamb i Stormwind.",al={"vem skapade heartswood core","heartswood cores ursprung","hur tillverkades heartswood core"}},cef9a99d={q="Varför vill Gakin att Heartswood Core ska användas?",a="En warlock som vill binda en succubus behöver ett oerhört kraftfullt ankare för att öppna en port till tomrummet. Utan Heartswood Core kan du inte fullborda besvärjelsen som krävs för att framkalla demonen och kuva dess förrädiska sinne.",al={"varför använda heartswood core","heartswood cores syfte och historia","varför vill någon ha heartswood core"}}},fp="15,202,22.443.0,20.458.1,37.194.0,33.176.0,28.125.0,42.179.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="Heavy Leaden Collection Phial",s="Heavy Leaden Collection Phial är ett skyddat provkärl som Ozzie Togglevolt tillhandahåller i Kharanos. Det är utformat för att säkert suga upp och hålla kvar högst instabilt, bestrålat utsläpp från mutanter djupt inne i Gnomeregan för pågående forskning om sanering.",h="Heavy Leaden Collection Phial är ett skyddat provkärl som Ozzie Togglevolt tillhandahåller i Kharanos.",kw={"gnomeregan","hall of gears","heavy leaden collection phial","ozzie togglevolt","ampull","radioaktivt nedfall","enda botemedlet är mer grönt sken"},ang={["profession:Engineering"]="Ampullen är specialutrustning för att samla upp flyktigt nedfall, en process som kan kräva flera försök även med ett lämpligt kärl.",["race:Gnome"]="Varje droppe flyktigt nedfall som säkras i ampullen är ett desperat steg mot att återta Gnomeregan och förstå den kemiska galenskap som stal deras hem."},sec={{t="Ett skyddat kärl",b="Heavy Leaden Collection Phial är ett provkärl som används för att samla upp flyktiga rester från levande, bestrålade varelser i Gnomeregan. Det är svårt att hålla kvar detta nedfall, och det kan krävas flera försök för att samla in ett lämpligt prov."},{t="Jakten på ett botemedel",b="Ozzie Togglevolt tillhandahåller ampullen som en del av sin forskning för att häva de fruktansvärda mutationer som drabbar spetälskegnomer. Tidigare prover från troggar på ytan saknade den styrka som krävdes för effektiv kemisk analys. Genom att använda blyampullen på virulenta bestar som bestrålade slem och lurkers i Hall of Gears hoppas forskarna kunna isolera de verksamma ämnena i stadens giftiga nedfall och ta fram ett effektivt motgift."}},faq={{q="Vad används Heavy Leaden Collection Phial till?",a="Den används för att suga upp koncentrerat radioaktivt utsläpp direkt från levande, bestrålade varelser i Gnomeregan och ge forskarna i Kharanos rena prover för saneringsförsök.",al={"vad gör ampullen","ampullens syfte","vad är en blyampull"}},{q="Vem tillhandahåller Heavy Leaden Collection Phial?",a="Gnomforskaren Ozzie Togglevolt tillhandahåller den i Kharanos i Dun Morogh som en del av sin forskning om att bota bestrålade och drabbade spetälskegnomer.",al={"vem ger ampullen","var får jag ampullen","uppdragsgivare för ampullen"}},{q="Varför är ampullen gjord av tungt bly?",a="Den beskrivs som en tung blyampull, men dess exakta konstruktion förklaras inte. Ozzie varnar för att det är svårt att hålla kvar det radioaktiva nedfallet och att provet snabbt kollapsar.",al={"varför blyampull","varför tungt bly"}},{q="Vilka varelser måste samplas med ampullen?",a="Den måste användas på levande, lysande fasor i Gnomeregans djup, som bestrålade slem, lurkers och fasor som stryker omkring på de lägre nivåerna i Hall of Gears.",al={"vad ska jag använda den på","målvarelser","vilka monster lyser"}}},fx={ca9f55e0={q="Varför vill Ozzie Togglevolt ha tillbaka Heavy Leaden Collection Phial?",a="Ozzie Togglevolt behöver både ampullen och ett prov av högpotent radioaktivt nedfall tillbaka till sin verkstad i Kharanos. Han har tidigare testat svagare troggexemplar och bedömt dem som otillräckliga. För att föra sina experiment med att bota de drabbade leper gnomes framåt behöver han orörd, oförorenad strålning direkt från varelserna i Gnomeregan.",al={"varför lämna tillbaka heavy leaden phial","varför vill ozzie ha ampullen","varför behövs collection phial"}}},fp="29,212,17.202.0,17.442.0,51.172.0,47.150.0,36.193.0,47.175.0"}
P.entries["item:hezrul-s-head"] = {n="Hezrul's Head",s="Vid Lushwater Oasis leder Hezrul Bloodmark Kolkar-centaurerna i The Barrens. Hans huvud förs till Regthar Deathgate väster om The Crossroads som bevis på att deras hövding har fallit.",h="Vid Lushwater Oasis leder Hezrul Bloodmark Kolkar-centaurerna i The Barrens.",kw={"bloodmark","kentaur","crossroads","deathgate","hezrul","kolkar","lushwater","regthar"},ang={["faction:Horde"]="Som medlem av Horden säkrar du livsviktiga vattenrättigheter vid Lushwater Oasis och skyddar Hordens resenärer genom The Barrens när du tar Kolkar-hövdingens huvud.",["race:Orc"]="Som orc kanske du ser Kolkar som odisciplinerade busar vars raseri ger vika för orcisk stridsdisciplin. Regthar ser trofén som ett bevis på krigarära."},sec={{t="Halshuggning av Kolkar",b="Hezrul Bloodmark leder sin Kolkar-centaurklan från Lushwater Oasis, söder om The Crossroads. Kolkar håller öknens oaser och hotar Hordens försörjningsleder och unga bosättningar. Regthar Deathgate, en orc-veteran med uppdrag att säkra landet väster om The Crossroads, ser deras vilda vrede men liten disciplin. Han kräver Hezruls avhuggna huvud för att bryta klanens befälsordning och kasta dess överlevande krigare i oordning, vilket försvagar deras angrepp mot Horden."}},faq={{q="Vem tillhör det här huvudet?",a="Huvudet tillhör Hezrul Bloodmark, ledaren för Kolkar-centaurklanen i centrala The Barrens.",al={"vem är hezrul","hezruls identitet","vems huvud är det här"}},{q="Var hittar man Hezrul Bloodmark?",a="Hezrul leder sitt följe kring Lushwater Oasis, söder om The Crossroads i The Barrens.",al={"hezruls plats","var finns hezrul","hitta hezrul"}},{q="Vem vill ha Hezrul's Head?",a="Regthar Deathgate, en orc vid en militär utpost på vägen väster om The Crossroads, vill ha huvudet som bevis på att Hezrul har besegrats.",al={"lämna in hezruls huvud","vem tar hezruls huvud","regthar deathgate"}},{q="Varför måste Horden ha hans huvud i stället för att bara driva bort honom?",a="Horden behöver vara säker på att Hezrul är död. Centaurerna är oberäkneliga och benägna att slåss inbördes, och när deras hövding röjs ur vägen bryts deras befälsordning och hotet mot The Crossroads försvagas.",al={"varför döda hezrul","varför ta hans huvud","kentaurhot"}}},fx={["67b3da29"]={q="Varifrån kommer Hezrul's Head?",a="Det här avhuggna huvudet tas från Hezrul Bloodmark, en listig och brutal centaurhövding som finns vid Lushwater Oasis söder om The Crossroads. Hezrul leder Kolkar-stammen i området och ligger bakom dess angrepp mot Hordens utposter och närliggande bosättningar, tills han fälls.",al={"hezruls huvuds ursprung","varifrån kom hezruls head","från vem kom hezruls head"}}},fp="13,177,23.465.0,29.70.0,32.85.0,24.143.0,69.186.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="High Potency Radioactive Fallout",s="High Potency Radioactive Fallout är ett koncentrerat, instabilt prov av det bestrålade slam som förgiftar Gnomeregans nedre djup. Gnomiska forskare har samlat det i tunga blybehållare i hopp om att baklängeskonstruera ett botemedel för de drabbade spetälskegnomerna.",h="High Potency Radioactive Fallout är ett koncentrerat, instabilt prov av det bestrålade slam som förgiftar...",kw={"gnomeregan","grönt sken","hall of gears","high potency radioactive fallout","bestrålat slem","spetälskegnom","ozzie togglevolt"},ang={["profession:Engineering"]="För att innehålla och transportera instabila, sönderfallande radioaktiva isotoper behövs specialbyggda blyflaskor som skyddar bäraren från katastrofal strålningsexponering.",["race:Gnome"]="Varje droppe giftigt nedfall som samlas in från stadens djup ger ett svagt hopp om att vända den fruktansvärda mutation som slet sönder dina fränder under Gnomeregans fall."},sec={{t="Direkt från källan",b="Mindre strålningsprover kan skrapas loss från förorenade asätare på ytan utanför, men Gnomeregans katastrof kräver något långt mer koncentrerat. Forskarna utanför den fallna huvudstaden behöver rått, oförfalskat radioaktivt nedfall från levande bestrålade fasor, lurare och slem som kryper omkring på de lägsta nivåerna i Hall of Gears. Eftersom detta trögflytande slam hela tiden sönderfaller måste det förvaras i en särskild blyflaska och lämnas tillbaka snabbt, innan provet blir helt instabilt."},{t="Jakten på ett botemedel",b="Den desperata jakten på sådana dödliga ämnen har ett brådskande syfte. Ozzie Togglevolt och hans kollegor tror att det enda gångbara sättet att utveckla ett botemedel för spetälskegnomerna är att avslöja det bestrålade slammets hemligheter. Dessa tragiska överlevare blev vansinniga och vanställda av de giftiga utsläpp som beordrades under trogginvasionen. De sitter fortfarande fast i en levande mardröm, så även de farligaste insamlingsexpeditionerna i ruinerna är värda risken."}},faq={{q="Var kommer det radioaktiva nedfallet ifrån?",a="Det hämtas direkt från levande bestrålade varelser, som bestrålade slem, fasor och lurare, djupt nere på de lägre nivåerna i Gnomeregans Hall of Gears.",al={"var man hittar nedfall","nedfallets plats","källa till radioaktivt nedfall"}},{q="Varför behövs provet?",a="Gnomiska forskare, däribland Ozzie Togglevolt, behöver ett outspätt, högkoncentrerat prov av strålningen i Gnomeregan för att studera sjukdomen och försöka skapa ett botemedel för sina fördärvade släktingar, spetälskegnomerna.",al={"vem vill ha nedfallet","nedfallets syfte","varför samla nedfall"}},{q="Varför måste det hanteras så varsamt?",a="Nedfallet är extremt instabilt och bryts snabbt ned. Det måste transporteras säkert i en tung blybehållare och lämnas till forskarna innan dess styrka avtar och bara lämnar oanvändbara rester.",al={"nedfallets sönderfall","varför blyflaska","instabilt nedfall"}},{q="Varför dög inte de tidigare troggresterna?",a="Rester som samlades från trogger på ytan utanför staden visade sig vara för svaga och orena för vetenskapliga tester. Forskarna behöver särskilt det råa, koncentrerade sken som bara finns hos varelser i stadens bestrålade djup.",al={"varför inte troggsken","troggstrålning jämfört med nedfall","tidigare prov misslyckades"}}},fx={["30a827ed"]={q="Vad är High Potency Radioactive Fallout?",a="Detta nedfall är en koncentrerad, flyktig restprodukt som skördats direkt från de djupt bestrålade slemvarelser, fasor och smygare som rör sig i Gnomeregans förstörda salar. Det är mycket instabilt och glöder av giftig energi, och utgör den råa förorening som dröjer kvar mitt i katastrofens centrum.",al={"vad är high potency radioactive fallout","radioaktivt nedfalls historia","vad är nedfallet"}}},fp="32,146,21.383.0,24.362.0,46.145.0,26.163.0,36.138.0,45.166.0"}
P.entries["item:highborne-relic-classic"] = {n="Highborne Relic",s="Highborne Relics är urgamla magiska redskap som återfunnits hos de rastlösa andar som hemsöker ruinerna av Ameth'Aran i Darkshore. De är genomsyrade av de magiska experiment som krossade det forntida Kalimdor och eftersöks av Night Elf-lärda som vill se dem förstörda innan deras slumrande krafter kan vålla mer skada.",h="Highborne Relics är urgamla magiska redskap som återfunnits hos de rastlösa andar som hemsöker ruinerna av...",kw={"ameth'aran","magi","darkshore","highborne","highborne relic","sentinels","thundris windweaver"},ang={["class:Mage"]="Magiker kan tycka att relikernas magiska hantverk är fascinerande, men de lokala Night Elf-myndigheterna tolererar inga tveksamheter när de ska förstöras.",["race:NightElf"]="För Night Elf-folket är dessa reliker en dyster påminnelse om den katastrofala magiska arrogans som slet deras forntida civilisation i stycken."},sec={{t="Rester av Sunderingen",b="För tiotusen år sedan utövade Highborne-kasten vårdslös magi och förde till slut det forntida Kalimdor mot undergången. I dag ligger deras forna gods i ruiner över hela Darkshore. Bland de sönderfallande pelarna i Ameth'Aran irrar jämrande och slingrande vålnader över skogsmarken och klamrar sig för evigt fast vid de fysiska redskapen från sin forna trolldom. Dessa reliker förblir ihållande fästpunkter för magisk besmittelse, gripna av spöken som vägrar släppa taget om redskapen för sin egen undergång."},{t="Att rena den magiska besmittelsen",b="För det moderna Night Elf-samhället, som till stor del avsvor sig magi efter den stora Sunderingen, utgör sådana artefakter en allvarlig fara. Lärda som Thundris Windweaver i Auberdine ger, efter rapporter från spanare ur Sentinels, resande i uppdrag att slita relikerna ur de förbannade andarnas spektrala händer. När relikerna har samlats in förstörs de systematiskt för att säkerställa att Highbornes forntida ondska och katastrofala misstag inte kan upprepas."}},faq={{q="Var kommer Highborne Relics ifrån?",a="De återfinns hos vålnaderna som hemsöker ruinerna av Ameth'Aran, öster om huvudvägen i södra Darkshore. Förbannade, slingrande och jämrande Highborne-andar bär dem bland de forntida stenarna.",al={"var hittar jag highborne relics","vem släpper highborne relics","relikernas plats"}},{q="Varför vill Thundris Windweaver ha relikerna?",a="Thundris Windweaver fruktar den kvarvarande magiska korruption som fortfarande häftar vid dessa forntida föremål. Han samlar in dem så att de kan monteras ned helt och förstöras, vilket hindrar någon från att återuppliva den farliga Highborne-trolldomen.",al={"varför samla reliker","vad händer med relikerna","windweavers mål"}},{q="Varför är Highborne-andarna fortfarande i Ameth'Aran?",a="Andarna är forntida Highborne-adelsmän som dog när världen krossades för tiotusen år sedan. Förbannade av sin hybris och sin kvardröjande bindning till magi är deras rastlösa själar fortfarande bundna till ruinerna av sin forna stad.",al={"varför är ametharan-spöken där","vilka är de förbannade highborne","varför spöken i darkshore"}},{q="Är Highborne Relics säkra att använda?",a="Nej. Night Elf-folket anser att de är besmittade av den vidriga, tygellösa magiutövning som utlöste den stora Sunderingen. Deras slumrande magi anses farlig, och därför kräver de lärda att relikerna förstörs i stället för att studeras.",al={"kan jag använda highborne relics","är reliker farliga"}}},fx={["9b193d00"]={q="Vad är en Highborne Relic?",a="En Highborne Relic är ett uråldrigt magiskt redskap som skapats av de högborne trollkarlarna i det forntida Kalimdor. Dessa förtrollade verktyg finns kvar i händerna på de rastlösa andar som hemsöker de sönderslagna ruinerna i Ameth'Aran, märkta av den kvardröjande fläcken från den arkana trolldom som utlöste den stora särningen.",al={"vad är highborne relic","highborne relics historia","vad är det här för reliker"}}},fp="15,141,25.381.0,24.381.0,36.173.0,47.157.0,50.228.0,33.202.0"}
P.entries["item:highperch-venom-sac"] = {n="Highperch Venom Sac",s="Highperch Venom Sacs skördas från de vilda wyverner som häckar på Highperchs skyhöga spiror i Thousand Needles. Orcer värdesätter wyverner som flygande riddjur, men vissa apotekare och handelsmän värderar deras kraftfulla gaddar ännu högre än de levande bestarna.",h="Highperch Venom Sacs skördas från de vilda wyverner som häckar på Highperchs skyhöga spiror i Thousand...",kw={"fiora longears","heartrazor","highperch","gift","theramore","thousand needles","giftsäck","wyvern"},ang={["class:Rogue"]="Det högkoncentrerade, förlamande giftet från otämjda wyverner i Thousand Needles är ett av de mest potenta naturliga gifterna i Kalimdor.",["faction:Alliance"]="Att slå till mot Highperchs bon tjänar Alliansen två syften: att samla värdefulla biologiska reagenser för handel och att minska antalet vilda wyverner som annars kunde fångas och tämjas som riddjur åt Horden."},sec={{t="En givande skörd",b="Thousand Needles höga spiror hyser livskraftiga flockar av vilda wyverner, särskilt kring Highperchs upphöjda klippor. Dessa bevingade rovdjur förlitar sig på kraftigt gift från sina hullförsedda svansar för att förlama och döda byten. Horden tämjer ofta dessa varelser till lojala vindryttare, men deras giftsäckar betingar ett anmärkningsvärt högt pris bland alkemister, jägare och opportunistiska handelsmän runtom i Kalimdor."},{t="En köpare långt borta",b="Giftet kommer från centrala Kalimdors djupa raviner, men väcker intresse långt utanför dem. I hamnstaden Theramore betalar högalven Fiora Longears generöst för färska säckar från Highperchs kullar. Hon vill ha prover fyllda med gift, vilket vanligtvis bara finns hos unga wyverner eller fertila honor. Det driver på handeln med farliga reagenser långt från bestarnas naturliga ökenmiljö."}},faq={{q="Vilka varelser bär på dessa giftsäckar?",a="De samlas direkt från de vilda wyvernerna som lever på Highperch i Thousand Needles, däribland Highperch Wyverns, Patriarchs, Consorts och matriarken Heartrazor.",al={"var får man giftsäckar","vem släpper highperch venom","wyverngift byte"}},{q="Varför vill Fiora Longears ha detta gift i Theramore?",a="Fiora Longears vet att wyverngift är mycket värdefullt i vissa handelskretsar, ibland till och med mer lönsamt än riddjuren själva. Hon ger resenärer som beger sig till Highperch i Thousand Needles i uppdrag att hämta hela säckar för handel.",al={"varför vill fiora ha gift","giftköpare i theramore","vem köper wyverngift"}},{q="Är alla wyverngiftsäckar likadana?",a="Giftets styrka och mängd varierar. De mest värdefulla säckarna är svullna och sprängfyllda med gift, vilket vanligtvis förekommer hos unga wyverner eller fertila avelshonor.",al={"wyverngiftets kvalitet","sprängfyllda giftsäckar"}},{q="Hur använder Horden dessa wyverner jämfört med Alliansen?",a="Horden fångar och föder främst upp wyverner som flygande riddjur och spejare, så kallade vindryttare. Oberoende handelsmän och kontakter i Alliansen saknar nätverk för att tämja dem och skördar i stället bestarna direkt för deras dödliga kemiska reagenser.",al={"hordens användning av wyverner","använder orcer giftet"}}},fx={["98761a97"]={q="Vad är en Highperch Venom Sac?",a="En Highperch Venom Sac är ett organ som skördats från de vilda wyvernerna som bygger bo på den höga platån Highperch i Thousand Needles. Wyverner är mest kända i Kalimdor som bevingade riddjur som används av Horden, men deras gift är uppskattat för sin oerhörda styrka. Säckarna från bestarna på Highperch är särskilt fulla av detta dödliga gift, vilket gör dem till ett värdefullt byte för alkemister och handelsmän som handlar med exotiska djurreagenser.",al={"vad är highperch venom sac","highperch venom sac","wyverngiftsäck"}}},fp="19,123,16.261.0,15.310.0,38.125.0,53.203.0,36.137.0,66.206.0"}
P.entries["item:highperch-wyvern-egg"] = {n="Highperch Wyvern Egg",s="Wyvernägg från Highperch är kullägg som samlas in från boplatserna på de höga platåbergen i Thousand Needles. Aspirerande vindryttare i Horde vill ha dem för att föda upp och träna nya flygande riddjur.",h="Wyvernägg från Highperch är kullägg som samlas in från boplatserna på de höga platåbergen i Thousand Needles.",kw={"elu","freewind post","highperch","highperch wyvern egg","thousand needles","vindryttare","wyvern"},ang={["class:Hunter"]="För att ta sig fram på Highperchs farliga höjder krävs kunskap om hur våldsamma rovdjur beter sig, eftersom vuxna wyverner försvarar sina boplatser med rakbladsvassa klor och giftiga gaddar.",["faction:Horde"]="Pålitliga flygresor är avgörande för att upprätthålla kommunikation och militär beredskap över Kalimdors vidsträckta områden. Därför är det strategiskt viktigt att skaffa nya wyverner."},sec={{t="Bon på platån",b="Den höga platån Highperch i Thousand Needles är en naturlig fristad där traktens wyverner kan slå sig ned och föda upp sina ungar. Boplatserna nås bara via branta, slingrande stigar längs ravinväggarna och vaktas hårt av vuxna bestar. Äggen som läggs bland bona är tåliga och varma, med ungar under utveckling som kan anpassa sig till Kalimdors hårda himmel."},{t="Uppfödning av nya vindryttare",b="I hela Kalimdor är efterfrågan på tränade wyverner ständigt större än tillgången, medan Horde bygger ut sina nätverk för kurirer och spejare. Vid Freewind Post letar aspiranter som tauren Elu efter hela ägg i vilda bon. Genom att föda upp ungarna från kläckningen hoppas skötarna skapa de starka band som krävs för att träna pålitliga bevingade riddjur åt Hordes vindryttare."}},faq={{q="Var hittar man äggen?",a="De ligger utspridda i bon över Highperch, ett upphöjt platåberg längs Thousand Needles västra klippväggar. Dit kommer man via en stig som leder upp från ravinbottnen.",al={"äggens platser","var hittar man wyvernägg","var finns äggen på highperch"}},{q="Varför samlar Horde in vilda wyvernägg?",a="Hordes led av vindryttare växer, och skötarna har svårt att träna tillräckligt många vuxna wyverner för att möta efterfrågan. Aspiranter som Elu samlar in ägg för att föda upp ungarna från födseln och förbereda både best och ryttare för flygtjänst.",al={"varför stjäla wyvernägg","vad används äggen till","syftet med elus ägguppdrag"}},{q="Är föräldrawyverner fientliga mot äggsamlare?",a="Ja. Vilda wyverner skyddar sina bon våldsamt och angriper alla inkräktare som tar sig upp på Highperch för att röra deras kullar.",al={"angriper wyverner","skyddar wyverner sina bon"}},{q="Vem tar emot äggen i Freewind Post?",a="Elu, en blivande vindryttare som är stationerad högst upp på Freewind Post, samlar in äggen i hopp om att påbörja sin egen formella träning med riddjur.",al={"vem tar emot wyvernägg","elu i freewind post"}}},fx={efbaa71b={q="Vad är ett Highperch Wyvern Egg?",a="Det här är livsdugliga ägg från vilda wyverner som bygger bo högt uppe på ravinplatåerna i Thousand Needles. I deras starka skal vilar Kalimdors obekläckta bevingade rovdjur, och äggen är mycket eftertraktade av dem som vill föda upp lojala flygande riddjur från födseln.",al={"vad är highperch wyvern egg","information om wyvernegg","vad är det här för ägg"}},bbfa5024={q="Varifrån kommer Highperch Wyvern Eggs?",a="De läggs av vilda wyverner i deras bon på klipptopparna vid Highperch, en högplatå ovanför ravinerna i Thousand Needles. De vuxna wyvernerna försvarar sina bon våldsamt mot både rovdjur och djärva asätare.",al={"varifrån kommer highperch wyvern eggs","vem lade äggen","wyverneggens ursprung"}}},fp="20,116,17.269.0,23.290.0,27.139.0,44.168.0,48.118.0,40.107.0"}
P.entries["item:hildelve-s-journal"] = {n="Hildelve's Journal",s="Hildelve's Journal är den sista anteckningen efter dvärgpiloten Hildelve, återfunnen bland hans kvarlevor i Dun Moroghs iskalla vildmark. De blodfläckade sidorna berättar om hans ödesdigra möte med en våldsam björn och förmedlar hans sista önskan om hämnd.",h="Hildelve's Journal är den sista anteckningen efter dvärgpiloten Hildelve, återfunnen bland hans kvarlevor i...",kw={"dun morogh","hildelve","ice claw bear","journal","mangeclaw","pilot hammerfoot","belägringsbrigaden"},ang={["faction:Alliance"]="När stupade militärer som Hildelve får sina personliga tillhörigheter återfunna stärks banden mellan Alliansen och Ironforge Siege Brigade.",["race:Dwarf"]="Journalen hedrar dvärgpiloternas okuvliga anda. De trotsar iskylan och vilddjuren för att säkra höjderna i Khaz Modan."},sec={{t="En pilots sista ord",b="När hans ångvagn gick sönder lämnade dvärgpiloten Hildelve sin partner Hammerfoot med vagnarna och gav sig ensam ut bland de snötäckta klipporna i Dun Morogh på jakt efter det omtalade chironmalmet. Enligt anteckningarna i hans journal förföljdes han i flera dagar och överfölls sedan av en väldig ice claw bear vid namn Mangeclaw. Hildelve kämpade tappert och lyckades driva bort besten, men blev svårt sargad och lämnades åt den bitande kylan. Journalen beskriver hans plågsamma sista timmar och avslutas med en tydlig vädjan, innan rovdjuret återvände för att döda honom: den som fann hans kropp skulle hämnas hans död genom att jaga rätt på Mangeclaw."},{t="Tillbaka till belägringsbrigaden",b="Den återfunna journalen ger ett dystert avslut för Hildelves kamrat Pilot Hammerfoot, som är stationerad nära North Gate Outpost i östra Dun Morogh. Som medlem av Ironforge Siege Brigade fruktade Hammerfoot det värsta när Hildelve aldrig återvände från sin jakt på malm. När journalen lämnas över tillsammans med besten avhuggna klo får Hammerfoot bevis på att Hildelves ande fått ro och att hans sista önskan uppfyllts."}},faq={{q="Vem var Hildelve?",a="Hildelve var en dvärg som körde ångvagn åt Ironforge Siege Brigade. När vagnen gick sönder gav han sig ensam ut i Dun Moroghs vildmark på jakt efter chironmalm. Han dödades av björnen Mangeclaw innan han hann återvända.",al={"hildelves historia","vem är hildelve","dvärgpiloten hildelve"}},{q="Vad är Mangeclaw?",a="Mangeclaw är en ovanligt stor och vild ice claw bear som stryker omkring på Dun Moroghs snötäckta höjder. Den överföll Hildelve när han var strandsatt, sargade honom svårt och återvände senare för att ta hans liv.",al={"vem är mangeclaw","vad dödade hildelve","björnen som dödade hildelve"}},{q="Vem får journalen när den hittas?",a="Journalen lämnas till Pilot Hammerfoot, en belägringsmaskinspilot stationerad nära North Gate Outpost i östra Dun Morogh. Hammerfoot var en nära vän till Hildelve och sökte nyheter om den försvunna piloten.",al={"vart lämnar jag journalen","vem får hildelves journal","lämna in hildelves journal"}},{q="Vad ber Hildelve om i journalen?",a="Hildelve visste att hans sår var dödliga. På de sista sidorna beskrev han besten som attackerat honom och bad att varje resenär som fann hans kvarlevor skulle jaga rätt på Mangeclaw och hämnas hans död.",al={"hildelves sista önskan","vad finns i journalen","pilotens sista önskan"}}},fx={b58cc0e1={q="Vad är Hildelve's Journal?",a="Den här slitna loggboken tillhörde Hildelve, en nedskjuten dvärgpilot i Ironforge Siege Brigade. Den hittades intill hans kvarlevor i de frusna delarna av Dun Morogh och skildrar hans fasansfulla sista stund: hur han överlevde en första brutal attack från jättebjörnen Mangeclaw och skrev ner sin sista önskan om hämnd innan besten återvände för att döda honom.",al={"vad är det här för journal","hildelve's journals historia","om hildelve's journal"}},["308c8265"]={q="Varifrån kommer Hildelve's Journal, och vem skrev den?",a="Journalen skrevs av piloten Hildelve själv under hans prövningar i Dun Morogh. När hans ångvagn gick sönder gav han sig till fots ut för att leta efter chironmalm och blev attackerad av björnen Mangeclaw. Han förde denna personliga redogörelse ända fram till sin död och lämnade efter sig ett skriftligt vittnesmål om sin kamp och sin sista begäran.",al={"vem skrev journalen","varifrån kom hildelve's journal","hildelve's journals ursprung"}},["856dae3f"]={q="Varför vill någon ha Hildelve's Journal?",a="Hans kollega, ångvagnspiloten Pilot Hammerfoot, letade desperat efter nyheter om sin försvunne kamrat. Journalen ger ett definitivt besked om Hildelves öde och hedrar hans sista önskan om hämnd på monstret som tog hans liv. Den ger hans vänner i Ironforge Siege Brigade ett avslut.",al={"varför behålla hildelve's journal","vem vill ha journalen","varför ta tillbaka hildelve's journal"}}},fp="18,145,21.567.0,27.344.1,17.205.0,18.207.0,42.179.0,42.197.0"}
P.entries["item:hillsbrad-human-skull"] = {n="Hillsbrad Human Skull",s="En makaber krigstrofé som tagits från stupade mänskliga försvarare och stadsbor runt om i Hillsbrad Foothills. Dessa skallar samlas in av Forsaken i Tarren Mill som dystra minnen av de skoningslösa angreppen mot traktens mänskliga bosättningar.",h="En makaber krigstrofé som tagits från stupade mänskliga försvarare och stadsbor runt om i Hillsbrad Foothills.",kw={"darthalia","hillsbrad","samsa","skalle","southshore","tarren mill","trofé"},ang={["faction:Alliance"]="Att se Hillsbrads bönder och soldater förvandlade till samlade prydnadssaker visar den dystra grymheten i Forsakens fälttåg i Lordaeron.",["race:Undead"]="För Forsaken är människoskallar från Hillsbrad både ljuv hämnd och en makaber påminnelse om de levande fränder som stöter bort dem."},sec={{t="Troféer från ett bittert krig",b="Kampen rasar mellan Forsaken i Tarren Mill och människorna i Southshore och kringliggande bosättningar, och avhuggna skallar är fysiska bevis på massakern. Medan Deathstalkers och soldater genomför den systematiska utrensning som Darthalia beordrat under slaget om Hillsbrad, längtar andra vakter som fastnat på vaktpass efter en del av blodbadet. Deathguard Samsa ber ivrigt frontkämparna om dessa troféer och finner ett förvridet nöje i att samla kvarlevorna efter just de människor som Forsaken en gång levde bland."}},faq={{q="Vem vill ha de här människoskallarna?",a="Deathguard Samsa, en Forsaken-vaktpost stationerad i Tarren Mill, samlar på dem. Han avundas soldaterna som skickas ut för att strida och plundra Hillsbrad medan han själv är fast på vakttjänst, och ber förbipasserande äventyrare att hämta trettio skallar till hans privata samling.",al={"vem vill ha skallar","vem tar människoskallar","deathguard samsas skallar"}},{q="Var samlas Hillsbrad Human Skulls in?",a="De tas från mänskliga stridande och arbetare runt om i Hillsbrad Foothills, särskilt vid de människokontrollerade gårdarna, gruvorna och stadsbefästningarna som angrips under fälttåget i slaget om Hillsbrad.",al={"var faller skallar","samla människoskallar","vem släpper människoskallar"}},{q="Varför samlar Forsaken på mänskliga kvarlevor?",a="Utöver rent hat och svart humor är det för vissa Forsaken en dyster sysselsättning att samla troféer från döda människor. Soldater som Samsa ser skallarna som värdefulla kuriositeter och tillfredsställande bevis på Hillsbrads annalkande fall.",al={"varför vill forsaken ha skallar","forsakens skallsamling"}}},fx={a9ea879b={q="Varför vill Deathguard Samsa ha Hillsbrad Human Skulls?",a="Deathguard Samsa, som står vakt vid Tarren Mill, är mycket avundsjuk på krigarna som skickas ut för att plundra och strida mot de levande. Han är strandsatt bakom frontlinjerna och samlar på skallarna som dyrbara personliga dödssouvenirer, så att han på avstånd kan ta del av slakten på Hillsbrads mänskliga försvarare.",al={"varför vill samsa ha skallar","vem vill ha hillsbrad human skulls och varför","varför samla på hillsbrad human skulls"}},["0091f8c0"]={q="Vad är en Hillsbrad Human Skull?",a="Det här är makabra troféer, avhuggna från stupade mänskliga försvarare och stadsbor som ligger utspridda över Hillsbrad Foothills. Medan konflikten rasar mellan Forsaken i Tarren Mill och de levande människorna i Hillsbrad, tjänar dessa fasansfulla föremål som konkreta bevis på alliansens förluster i det omstridda området.",al={"vad är hillsbrad human skulls","föremålet hillsbrad skull","information om hillsbrad human skull"}},["9eb161fa"]={q="Varifrån kommer en Hillsbrad Human Skull, och vem skapade den?",a="Dessa dödskallar tas direkt från de dödliga människor som bor i Hillsbrad Foothills och skördas av Hordens krigare i det pågående gränskriget. De tillverkas inte, utan är makabra lämningar från slagfältet som tagits från stupade soldater, bönder och invånare som försvarat de lokala mänskliga bosättningarna mot Forsaken.",al={"hillsbrad human skulls ursprung","varifrån kommer hillsbrad-skallar","vem tillverkar hillsbrad-skallar"}}},fp="21,143,24.447.0,29.227.0,42.203.0,42.160.0"}
P.entries["item:hillsbrad-town-registry"] = {n="Hillsbrad Town Registry",s="Hillsbrad Town Registry är en officiell kommunal liggare som förvaras i stadshuset i Hillsbrad Fields. Den redovisar bosättningens överlevande invånare, markägare och kommunala handlingar och är därför ett viktigt strategiskt mål i Forsakens offensiv mot människornas fäste.",h="Hillsbrad Town Registry är en officiell kommunal liggare som förvaras i stadshuset i Hillsbrad Fields.",kw={"slaget om hillsbrad","darthalia","hillsbrad fields","hillsbrads stadshus","hillsbrad town registry","magistrate burnside"},ang={["faction:Horde"]="Att inta stadsregistret är ett avgörande steg för att bryta människornas makt i bergssluttningarna och befästa Forsakens fäste i Tarren Mill.",["race:Human"]="Liggaren står för den formella existensen och de rättigheter som Hillsbrads kvarvarande stadsbor har. Om den går förlorad drabbas hela regionens samhälle hårt."},sec={{t="En redogörelse för trots",b="Hillsbrad Town Registry ligger i stadshuset nära Magistrate Burnsides podium och dokumenterar Hillsbrads befolkning, hushåll och administrativa rättigheter. När Forsaken från Tarren Mill försöker bryta människornas motstånd i bergssluttningarna beordrar Darthalia Hordens mästare att infiltrera stadshuset, eliminera rådet och lägga beslag på liggaren. När registret beslagtas förlorar Hillsbrad sin kommunala ordning, samtidigt som Undercity får värdefull information om den överlevande befolkningen och dess tillgångar."}},faq={{q="Var förvaras Hillsbrad Town Registry?",a="Registret förvaras i stadshuset i Hillsbrad Fields, i ett hörn nära trappan som leder upp till Magistrate Burnsides plattform.",al={"registrets plats","var finns stadsregistret","hitta hillsbrad-registret"}},{q="Varför vill Forsaken stjäla det?",a="High Executor Darthalia vill fullständigt slå sönder människornas styre i bergssluttningarna. När registret tas förlorar staden viktiga uppgifter om sina invånare och sin egendom, samtidigt som Forsaken får detaljerad information om det överlevande samhället.",al={"varför stjäla registret","darthalias registeruppdrag","registrets syfte"}},{q="Vem vaktar registret?",a="Det vaktas av Magistrate Burnside och Hillsbrad Councilmen, som använder försvarsmagi och samlas i och omkring stadshuset.",al={"vem skyddar registret","stadshusets försvarare"}}},fx={["188a667c"]={q="Vad är Hillsbrad Town Registry?",a="Hillsbrad Town Registry är en officiell registerbok som förvaras i stadshuset i bosättningen Hillsbrad Fields. Den sköts av den lokala mänskliga förvaltningen under magistrat Burnside och dokumenterar samhällsärenden, befolkning och styre i ett av Alliansens kvarvarande fästen vid foten av kullarna.",al={"vad är hillsbrad town registry","hillsbrad town registry","vad är registerboken"}}},fp="23,209,20.486.0,42.136.0,37.220.0,24.138.0"}
P.entries["item:hippogryph-muisek"] = {n="Hippogryph Muisek",s="Hippogryph Muisek bevarar andarna från Frayfeather-hippogrypherna i Feralas. En druid i High Wilderness ber dig fånga dem med ett Muisek Vessel.",h="Hippogryph Muisek bevarar andarna från Frayfeather-hippogrypherna i Feralas.",kw={"feralas","frayfeather","high wilderness","hippogryph","hippogryph muisek","muisek vessel","ande"},ang={["race:NightElf"]="Som Night Elf känner du hippogrypher som trogna följeslagare vars andar är ståndaktiga. Druiden vill se till att andarna bevaras säkert."},sec={{t="Bevarade andar",b="Du ska fånga tio av High Wilderness Frayfeather-hippogrypher med Muisek Vessel. Night Elf-folket har länge hållit hippogrypher som trogna följeslagare, och deras andar är ståndaktiga. Kärlet bevarar varje ande efter att dess varelse dödats."}},faq={{q="Vad är Hippogryph Muisek?",a="Hippogryph Muisek är den bevarade anden från en Frayfeather-hippogryph, fångad i ett Muisek Vessel.",al={"hippogryph muisek","muisek-föremål"}},{q="Var hittar jag Frayfeather-hippogrypher?",a="Frayfeather-hippogrypher lever i High Wilderness, söder om druiden som ber dig fånga dem.",al={"hippogryph-plats","var finns frayfeather"}},{q="Varför fånga hippogrypherna?",a="Druiden vill bevara deras muisek, eftersom en ande som lämnas fri när dess varelse dör kan anta formen av en större varelse och hota dem i närheten.",al={"varför muisek","fånga hippogrypher"}},{q="Hur många hippogrypher behövs?",a="Druiden ber dig fånga tio Frayfeather-hippogrypher.",al={"hur många hippogrypher","antal muisek"}}},fp="17,160,17.263.0,26.99.0,40.101.0,28.155.1,32.58.0"}
P.entries["item:hippogryph-muisek-vessel"] = {n="Hippogryph Muisek Vessel",s="Hippogryph Muisek Vessel bevarar hippogryfernas andar i Feralas. Den används för att fånga deras muisek i High Wilderness.",h="Hippogryph Muisek Vessel bevarar hippogryfernas andar i Feralas.",kw={"frayfeather","high wilderness","hippogryf","hippogryf-muisek","hippogryph muisek vessel","muisek","zor lonetree"},ang={["race:NightElf"]="Hippogryfer har länge varit trogna följeslagare till Night Elves, och det är viktigt för Zor Lonetree att deras andar bevaras."},sec={{t="En bevarad and",b="När du har visat att du kan använda kärlet ber Zor Lonetree dig att fånga hippogryfernas muisek. Frayfeather-hippogryferna lever i High Wilderness, söder om honom. Deras andar har länge varit trogna följeslagare till Night Elves. Zor befarar att en ande som lämnas fri när ett djur dör kan bli en mäktigare varelse och söka hämnd."}},faq={{q="Vad gör Hippogryph Muisek Vessel?",a="Kärlet fångar hippogryfernas muisek så att deras andar kan bevaras.",al={"vad kärlet används till","använda hippogryfkärlet"}},{q="Var använder jag kärlet?",a="Frayfeather-hippogryferna finns i High Wilderness, söder om Zor Lonetree.",al={"var använda muisekkärlet","kärlet i high wilderness"}},{q="Varför fånga hippogryfernas muisek?",a="Kärlet bevarar hippogryfernas muisek. Zor Lonetree befarar att en ande som lämnas fri efter döden kan bli en mäktigare varelse och söka hämnd.",al={"varför fånga dem","hippogryfernas andar"}},{q="Är hippogryfer viktiga för Night Elves?",a="Hippogryfer har varit trogna följeslagare till Night Elves i många år.",al={"night elf-hippogryfer","hippogryfer som följeslagare"}}},fp="24,137,18.341.0,42.72.0,26.78.0,30.145.0,41.73.0"}
P.entries["item:hollow-vulture-bone"] = {n="Hollow Vulture Bone",s="Hollow Vulture Bones är lätta, tåliga skelettdelar från asätarna i The Shimmering Flats.",h="Hollow Vulture Bones är lätta, tåliga skelettdelar från asätarna i The Shimmering Flats.",kw={"hollow vulture bone","viktminskning","mirage raceway","pozzik","asätare","the shimmering flats","thousand needles"},ang={["class:Hunter"]="Gamarna i The Shimmering Flats är tåliga asätare, vilket gör dem till naturliga mål att spåra över det bländande saltfältet.",["profession:Engineering"]="Medan vanliga ritningar bygger på tungt järn och brons visar användningen av ihåliga fågelben den påhittiga, viktbesparande pragmatism som präglar goblinernas tävlingsinnovationer."},sec={{t="Tävlingsmaterial på saltslätten",b="Ute på saltslätten är fart allt, och vikt är fartens fiende. Vanlig ingenjörskonst bygger mycket på järn och koppar, men goblinernas depåteam på Mirage Raceway använder allt öknen erbjuder för att få ett övertag. Gamar har naturligt ihåliga men förvånansvärt tåliga ben, med ett perfekt förhållande mellan styrka och vikt för inre fästen, styranordningar och mindre bärande delar. För chefsuppfinnare som Pozzik är ben från lokala asätare en praktisk och billig genväg till några sekunder snabbare varvtider."}},faq={{q="Varför vill gobliner ha gamben?",a="Gobliningenjörer som Pozzik använder ihåliga gamben för att minska vikten på sina raketbilar. Fåglars ben är naturligt lätta och förvånansvärt starka, vilket gör dem till idealiskt material för styranordningar och mindre bärande delar.",al={"varför ben","gobliners användning av ben","pozziks användning av ben"}},{q="Var kommer benen ifrån?",a="De tas från Salt Flats Scavengers och Salt Flats Vultures som kretsar över The Shimmering Flats i Thousand Needles, särskilt kring de jättelika skelettrester som ligger utspridda över saltöknen.",al={"var hittar man hollow vulture bone","plats för gamben","hur får man gamben"}},{q="Vem är Pozzik?",a="Pozzik är en gobliningenjör och chefsmekaniker på Mirage Raceway. Han finjusterar och modifierar ständigt raketbilar för att tävla mot gn émlaget som leds av Fizzle Brassbolts.",al={"vem är pozzik","pozzik på mirage raceway","vem tar benen"}}},fx={["2d4c7633"]={q="Vad är ett Hollow Vulture Bone?",a="Det är lätta, tåliga ben som samlats in från asätarfåglarna som kretsar över The Shimmering Flats. Fåglars skelett är naturligt ihåliga för att underlätta flykten, vilket gör benen särskilt lämpade för mekanisk ingenjörskonst där varje gram räknas. Vid Mirage Raceway använder goblinmekaniker dem för att tillverka tåliga konstruktionsdelar och styrkomponenter till sina raketbilar.",al={"vad är hollow vulture bone","hollow vulture bones"}}},fp="19,195,29.384.0,38.158.0,31.189.0,14.164.0"}
P.entries["item:honorary-picks"] = {n="Honorary Picks",s="Honorary Picks är en uppsättning ceremoniella verktyg som smids i Ironforge åt unga dvärgiska gruvlärlingar. De anförtros åt resenärer via gryfonnätverket och levereras till Brock Stoneseeker i Thelsamar som tecken på att hans elever är redo att arbeta i Loch Modans rika malmådror.",h="Honorary Picks är en uppsättning ceremoniella verktyg som smids i Ironforge åt unga dvärgiska gruvlärlingar.",kw={"brock stoneseeker","gryth thurden","honorary picks","ironforge","loch modan","gruvhackor","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="Varje gruvarbetare i Khaz Modan förstår värdet av en rejäl hacka, och att få ett hedersverktyg markerar en nybörjares verkliga inträde i yrket.",["race:Dwarf"]="För en dvärg är det en hyllad tradition av släktskap och hantverk att ge lärlingar i provinserna verktyg smidda i Ironforge."},sec={{t="Verktyg för nästa generation",b="I dvärgarnas samhälle är gruvdrift mycket mer än ett yrke; den är en kulturell hörnsten som håller de stora smedjorna brinnande och förser kungariket med järn och sten. Honorary Picks är ett formellt erkännande för nybörjare inom prospektering som lär sig under Brock Stoneseeker i Thelsamar. Dessa hackor kommer direkt från Ironforge och överlämnas till elever som har visat sin hängivenhet och är redo att ta sig an de öppna malmfyndigheterna i Loch Modan."},{t="Gryfonlinjerna sätts på prov",b="Transporten av hackorna fyller ett ytterligare syfte för Alliansens bergsfolk och köpmän: att introducera kurirer till kungarikets gryfonnätverk. Sändningen förs från Ironforges Great Forge direkt till Gryth Thurden och flygs över bergen till Thorgrum Borrelson i Thelsamar. Den visar hur tätt huvudstaden fortfarande är knuten till sina avlägsna utposter genom snabba flygförbindelser."}},faq={{q="Vad används Honorary Picks till?",a="Honorary Picks tillverkas åt gruveleverna hos Brock Stoneseeker i Loch Modan. De är ceremoniella men fullt användbara verktyg som ges till lärlingar som är redo att bryta malmådror i regionen.",al={"vad är honorary picks","användning av honorary picks","syftet med honorary picks"}},{q="Vem skickar hackorna, och vem tar emot dem?",a="Hackorna görs i Ironforge och förs till Gryth Thurden vid stadens gryfonnäste. Därifrån flygs de österut till Thelsamar och överlämnas till gruvinstruktören Brock Stoneseeker.",al={"vem får honorary picks","leverans av honorary picks","mottagare av honorary picks"}},{q="Varför måste hackorna levereras med gryfon?",a="De skulle kunna bäras till fots genom North Gate Pass, men när gryfonryttaren Gryth Thurden skickar dem går transporten snabbt. Resenärerna får också lära sig att använda Alliansens etablerade flygrutter mellan Ironforge och Loch Modan.",al={"varför flyga hackorna","varför ta gryfon","honorary picks flygning"}},{q="Är Honorary Picks riktiga vapen eller verktyg som du kan utrusta?",a="Nej. Kuriren bär dem bara som last. De är avsedda för Brock Stoneseekers gruvelever, som gärna vill börja använda dem vid Loch Modans malmfyndigheter.",al={"kan jag utrusta honorary picks","är honorary picks ett föremål","kan honorary picks användas"}}},fx={a7b14bb4={q="Vad är Honorary Picks?",a="Honorary Picks är ett knippe ceremoniella eller minnesvärda gruvverktyg som tillverkats i Ironforge. De är avsedda som en särskild gåva till nybörjare som lär sig hantverket under erfarna prospektörers ledning i kullarna i Loch Modan.",al={"vad är honorary picks","föremålet honorary picks","historien om honorary picks"}},["0ecadd79"]={q="Varifrån kommer Honorary Picks, och vem har tillverkat dem?",a="Hackorna hämtas i dvärgarnas huvudstad Ironforge. De har tillverkats av skickliga bergssmeder i stadens Great Forge och packats särskilt för transport till instruktörer som utbildar lärlingar utanför Dun Moroghs gränser.",al={"vem tillverkade honorary picks","honorary picks ursprung","varifrån kom hackorna"}},["1a632b74"]={q="Varför vill någon ha Honorary Picks?",a="Gruvinstruktören Brock Stoneseeker i Thelsamar har begärt hackorna för att ge dem till sina nybörjarelever. Eleverna är blivande prospektörer i Loch Modan och ser fram emot utmärkelserna och verktygen, så att de kan börja arbeta i områdets rika mineralådror.",al={"varför leverera honorary picks","vem vill ha honorary picks","varför vill brock ha hackorna"}}},fp="14,202,29.256.0,25.237.0,37.165.0,43.192.0,49.237.0,61.144.0"}
P.entries["item:horn-of-arra-chea"] = {n="Horn of Arra'chea",s="Horn of Arra'chea är en jakttrofé från den legendariska kodo Arra'chea, som strövar omkring på Mulgore-slätterna. På uppdrag av överhövding Cairne Bloodhoof fungerar hornet som ett slutgiltigt bevis på att en blivande jägare har disciplinen och spårningsförmågan som krävs för att försörja Shu'halo.",h="Horn of Arra'chea är en jakttrofé från den legendariska kodo Arra'chea, som strövar omkring på...",kw={"arra'chea","cairne bloodhoof","horn of arra'chea","kodo","mulgore","earthmothers riter","thunder bluff"},ang={["class:Hunter"]="Att följa Arra'cheas cirkulära väg genom Mulgore vida vidder prövar grundläggande färdigheter i smygjakt och överlevnad i vildmarken, färdigheter som varje sann jägare värdesätter.",["race:Tauren"]="När du överlämnar hornet till överhövding Cairne bekräftar du din beredskap att försörja och försvara ditt folk på Thunder Bluff. Det är en viktig övergångsrit."},sec={{t="En hövdings prövning",b="Att klara Earthmothers inledande riter ger en ungdom sin rättmätiga plats på Thunder Bluff, men överhövding Cairne Bloodhoof förväntar sig att hans folk ständigt bevisar sitt värde. För tauren är identiteten oupplösligt knuten till jakten och deras bestående harmoni med landet. Cairne prövar unga jägare genom att ge dem i uppgift att spåra Arra'chea, en enorm, ensam kodo-tjur som strövar omkring på gräsmarkerna nedanför. Att ta Arra'cheas horn bevisar att jägaren behärskar den grundläggande konsten att spåra byte över stora avstånd."},{t="Försörja stammen",b="Att föra hornet till Thunder Bluffs höjdplatå visar mer än stridsstyrka; det bidrar till hela samhällets överlevnad. I taurenkulturen får inget från ett fällt djur gå till spillo. När trofén visas upp får överhövdingen veta var djuret föll, så att insamlingsgrupper snabbt kan bege sig ner på slätterna och ta till vara Arra'cheas tjocka skinn och näringsrika kött till den unga huvudstaden."}},faq={{q="Vad är Horn of Arra'chea?",a="Det är ett horn från Arra'chea, en mäktig och svårfångad kodo som strövar omkring på Mulgore-slätterna. Jägare för det till Cairne Bloodhoof som en övergångsrit för att visa sin spårningsförmåga.",al={"horn of arrachea","arracheas horn","vad är det här hornet"}},{q="Vem är Arra'chea?",a="Arra'chea är en välkänd kodo-tjur som strövar runt på gräsmarkerna nordost om Thunder Bluff. Han är känd för sin styrka och långa vandringsrutt och är ett krävande byte för jägare som vill bevisa sitt värde för stammen.",al={"arrachea","vem är arrachea","arracheas historia"}},{q="Varför ber Cairne Bloodhoof om den här trofén?",a="Cairne anser att man måste bevisa sin tjänstvillighet och förmåga gång på gång för att behålla sin ställning på Thunder Bluff. Genom att spåra upp och fälla Arra'chea visar en jägare sin hängivenhet till Earthmothers traditioner och bidrar med värdefulla resurser till samhället.",al={"varför vill cairne ha hornet","cairne arrachea","earthmothers riter horn"}},{q="Vad händer med resten av djuret efter att det dödats?",a="Enligt taurenfolkets sedvänja går inget från det jagade djuret till spillo. När hornet har lämnats in som bekräftelse på att djuret fällts skickar Cairne en insamlingsgrupp ner till Mulgore för att hämta skinnet och köttet till Thunder Bluff.",al={"arracheas kött","taurenernas jakttradition","arracheas kadaver"}}},fx={["0ff92160"]={q="Varifrån kommer Horn of Arra'chea, och vem har tillverkat det?",a="Hornet är inget tillverkat föremål, utan en naturlig trofé från Arra'chea, en mäktig kodo som strövar omkring på Mulgore-slätterna nedanför Thunder Bluff. För att få tag på det måste en jägare spåra upp det väldiga odjuret på de öppna gräsmarkerna och fälla det i hedervärd strid.",al={"horn of arra'chea ursprung","varifrån kom horn of arra'chea","vem tillverkade horn of arra'chea"}}},fp="17,138,18.421.0,23.316.0,30.173.0,17.199.0,46.233.0,57.169.0"}
P.entries["item:horn-of-awakening"] = {n="Horn of Awakening",s="Horn of Awakening är ett blåsinstrument som förvaras i en kista hos Kerlonian Evershade i södra Darkshore. Det används för att väcka den sömnige druiden när han somnar under färden till Ashenvale.",h="Horn of Awakening är ett blåsinstrument som förvaras i en kista hos Kerlonian Evershade i södra Darkshore.",kw={"ashenvale","darkshore","druid of the claw","emerald dream","horn of awakening","kerlonian evershade","maestra's post"},ang={["class:Druid"]="Druids of the Claw tillbringade generationer i slummer i Barrow Dens medan de kommunicerade med Emerald Dream. När de återvänder till den vakna verkligheten är de ofta omtöcknade och desorienterade.",["race:NightElf"]="Kerlonian visar hur svårt det kan vara för nattalvernas druider att återvända till den vakna världen efter sin långa slummer i Emerald Dream."},sec={{t="Ett botemedel mot sömniga druider",b="Kerlonian Evershade, en Druid of the Claw som nyligen väckts efter århundraden i Emerald Dream, känner sig ständigt håglös i den vakna världen. På väg söderut mot Maestra's Post anförtros han hornet åt resenärer som vill eskortera honom. När utmattningen tar över på den farliga leden genom vildmarken väcker en klar stöt från instrumentet hans sinnen och får honom på fötter igen innan vilddjur eller kultister hinner utnyttja hans slummer."}},faq={{q="Var finns Horn of Awakening?",a="Hornet ligger i Kerlonian's Chest, intill Kerlonian Evershades lägerplats i södra Darkshore nära gränsen till Ashenvale.",al={"hornets plats","var finns horn of awakening","kerlonians kista"}},{q="Varför behöver Kerlonian hornet för att hålla sig vaken?",a="Efter långa tidsåldrar i slummer i Emerald Dream har Kerlonian svårt att vänja sig vid dödligas vakna tillstånd och faller ständigt i plötsliga, djupa tupplurar under färden.",al={"varför sover kerlonian","varför somnar han","slummer i emerald dream"}},{q="Vart försöker Kerlonian ta sig?",a="Han försöker nå Maestra's Post i norra Ashenvale för att möta Liladris Moonriver.",al={"kerlonians mål","vart går han","eskort till maestras post"}}},fx={["061d2ee3"]={q="Vad är Horn of Awakening?",a="Horn of Awakening är ett personligt instrument som tillhör nattalvdruiden Kerlonian Evershade. Kerlonian har nyligen återvänt från The Emerald Dream och drabbas under sina resor av djup, oläglig sömn. Han förvarar hornet säkert i sin kista, så att en följeslagare kan blåsa i det och väcka honom när han faller ihop längs vägen.",al={"horn of awakening","vad är det här hornet","kerlonians horn"}}},fp="17,119,26.391.0,37.127.0,47.148.0,32.93.0"}
P.entries["item:horn-of-echeyakee"] = {n="Horn of Echeyakee",s="Vid The Crossroads ger Sergra Darkthorn jägarna Horn of Echeyakee. När man blåser i det bland de uråldriga kodo kvarlevorna nordost om bosättningen kallar det på Barrens legendariska vita rovdjur.",h="Vid The Crossroads ger Sergra Darkthorn jägarna Horn of Echeyakee.",kw={"the barrens","the crossroads","echeyakee","horn","kodoben","sergra darkthorn","whitemist"},ang={["class:Hunter"]="Som jägare möter du Echeyakee i en legendarisk övergångsrit, där dina sinnen sätts på prov mot ett rovdjur som är känt i hela The Barrens för sin närapå felfria smygförmåga.",["race:Tauren"]="Som tauren vet du att Echeyakees jakt har en andlig tyngd. Ditt folk ser hans snabba, smärtfria dödande som både barmhärtighet och dödens hårda nödvändighet."},sec={{t="Att kalla fram Whitemist",b="Jägare som sätts på prov i jakten får hornet. Dess signal kallar fram Echeyakee, vars namn betyder ”Whitemist” på Taur-ahe. Taurenjägare vördar savannkatternas konung som både barmhärtighet och död. Han slår till så snabbt att bytet varken känner skräck eller lidande. Hornet hör hemma i rovdjurets lya, bland jättelika kodoben bakom kullarna nordost om The Crossroads."}},faq={{q="Vad gör Horn of Echeyakee?",a="Hornet lockar fram Echeyakee, den svårfångade vita savannkatten. Blås i det nära de jättelika kodobenen nordost om The Crossroads, så visar sig odjuret för jägaren att möta.",al={"använd horn of echeyakee","vad används horn of echeyakee till"}},{q="Var kommer hornet ifrån?",a="Sergra Darkthorn, en orcisk jägare vid The Crossroads i The Barrens, ger hornet till äventyrare som vill bevisa sin list och sin spårningsförmåga.",al={"vem ger hornet","horn of echeyakees ursprung"}},{q="Vad betyder namnet Echeyakee?",a="På Taur-ahe, taurenfolkets språk, betyder Echeyakee ”Whitemist”. Namnet hedrar odjurets ljusa päls och dess tysta sätt att smyga oupptäckt genom torrt gräs.",al={"echeyakees betydelse","whitemists betydelse"}},{q="Var ska du blåsa i hornet?",a="Blås i hornet bland de jättelika kotoribbenen och skelettresterna bakom kullarna nordost om The Crossroads, där det vita lejonet strövar.",al={"var använda hornet","echeyakees plats"}}},fx={eb6b337d={q="Vad är Horn of Echeyakee?",a="Horn of Echeyakee är ett ceremoniellt jaktinstrument som Sergra Darkthorn ger till lovande jägare vid The Crossroads. Om man blåser i det bland de jättelika kodobenen nordost om bosättningen lockar signalen fram Echeyakee själv, det vita lejon som taurerna vördar som savannkatternas kung.",al={"horn of echeyakee","vad är det här hornet","vad är horn of echeyakee"}},["5884ea69"]={q="Varför ger Sergra Darkthorn dig Horn of Echeyakee?",a="Sergra Darkthorn ger dig hornet som ett viktigt verktyg för att pröva din skicklighet. Echeyakee smyger osedd över slätterna som en vit dimma och är nästan omöjlig att spåra enbart med synen. Hornets signal utmanar det stora rovdjuret och lockar fram det till strid, så att du kan ta dess skinn och bevisa din jaktförmåga.",al={"varför behöver jag horn of echeyakee","varför hornet of echeyakee","syftet med horn of echeyakee"}}},fp="17,207,21.375.0,35.165.0,30.144.0,34.134.0,27.135.0"}
P.entries["item:huge-gnoll-claw"] = {n="Huge Gnoll Claw",s="I sydvästra Elwynn Forest söker man efter Hoggers väldiga klo som bevis på hans död. Stormwinds myndigheter i Goldshire kräver den för att betala ut belöningen.",h="I sydvästra Elwynn Forest söker man efter Hoggers väldiga klo som bevis på hans död.",kw={"belöning","elwynn forest","goldshire","hogger","huge gnoll claw","marshal dughan","riverpaw"},ang={["class:Hunter"]="Som jägare visar du din skicklighet i att spåra och jaga bestar genom att säkra klon från ett rovdjur som regelbundet har övermannat beväpnade grupper.",["faction:Alliance"]="För Alliansen innebär Hoggers klo att rikets hjärtland befrias från sitt mest ökända skogshot. Klon bevisar ditt mod för Marshal Dughan och den hårt prövade garnisonen i Goldshire."},sec={{t="Belägg för belöningen",b="Hogger har terroriserat skogarna i södra Forest's Edge i månader. Patruller har inte lyckats stoppa besten, och den lokala garnisonen kan varken ringa in eller kuva honom. Stormwindarmén, som är hårt ansatt i hela Elwynn Forest, utlyste en belöning för hans huvud. Marshal Dughan i Goldshire kräver tydliga bevis innan han betalar ut den. Hoggers överdimensionerade klo visar bortom allt tvivel att den ökände plundraren har fallit."}},faq={{q="Vad används Huge Gnoll Claw till?",a="Ta Hoggers klo till Marshal Dughan i Goldshire som bevis på hans död, så kan du hämta ut den utlysta belöningen.",al={"vad gör jag med hoggers klo","användning av huge gnoll claw","vem vill ha klon"}},{q="Var kommer klon ifrån?",a="Klon kommer från Hogger, en elitgnoll som strövar nära Riverpaw-lägren längs de sydvästra gränserna av Forest's Edge i Elwynn Forest.",al={"vem släpper klon","hur får man huge gnoll claw","var hittar man huge gnoll claw"}},{q="Varför vill Marshal Dughan ha en klo i stället för huvudet?",a="Hogger är onormalt stor för att vara gnoll, och hans enorma klor är tydliga och omedelbart igenkännbara. En klo bevisar för Stormwindarmén att den ökände plundraren har dödats.",al={"varför klo som bevis på död","varför inte hoggers huvud","dughans bevis för belöning"}},{q="Kan jag få en ny klo om jag tappar bort den?",a="Ja. Om du tappar bort klon innan du lämnar den till Marshal Dughan kan du jaga Hogger igen i sydvästra Elwynn Forest och hämta en ny.",al={"tappat huge gnoll claw","kan jag få klon igen","hoggers klo återuppstår"}}},fx={d9093290={q="Vad är Huge Gnoll Claw?",a="Huge Gnoll Claw är ett avhugget, fysiskt bevis på att Hogger har dött. Hogger är en ökänd, väldig gnoll som terroriserar sydvästra Elwynn Forest. Eftersom Hogger har övermannat alla försök från de lokala myndigheterna att fånga honom, är den här särpräglade klon ett obestridligt bevis för Marshal Dughan på att besten äntligen har dödats.",al={"vad är huge gnoll claw","information om huge gnoll claw","hoggers klo"}},["7983cdb8"]={q="Varför vill Marshal Dughan ha Huge Gnoll Claw?",a="Marshal Dughan och Stormwind-armén utfäste en belöning för Hogger efter att det väldiga odjuret undkommit och övermannat deras patruller. Dughan kräver gnollens enorma klo som bevis på att den är död innan han betalar ut belöningen i Goldshire. Då får hans män äntligen slut på besvären som Hogger orsakat dem.",al={"varför vill dughan ha klon","vem vill ha huge gnoll claw","varför vill någon ha huge gnoll claw"}}},fp="15,140,21.406.0,37.104.0,31.138.0,56.179.0,36.142.0"}
P.entries["item:humbert-s-sword"] = {n="Humbert's Sword",s="Humbert's Sword är Deathguard Humberts personliga sidovapen i Tarren Mill. Dvärgsoldater plundrade vapnet från hans läger medan han spanade på deras fäste i Dun Garok.",h="Humbert's Sword är Deathguard Humberts personliga sidovapen i Tarren Mill.",kw={"darthalia","deathguard humbert","dun garok","hillsbrad","humbert's sword","tarren mill"},ang={["faction:Horde"]="Återtagandet av svärdet sammanfaller med Horde-styrkornas större operationer mot dvärgarnas enklav i Dun Garok, däribland insamling av dvärgblod och militära insignier.",["race:Undead"]="High Executor Darthalia upprätthåller skoningslös disciplin bland Forsaken-styrkorna i Hillsbrad. Därför är försumliga vakter som Humbert desperata att dölja sina misstag."},sec={{t="En spejares obetänksamma ögonblick",b="High Executor Darthalia skickade Deathguard Humbert för att övervaka dvärgarnas närvaro i Dun Garok från en dold plats. En morgon lämnade han sin post obevakad för att samla ved och koka vatten. Dvärgpatruller snubblade då över hans läger och plundrade all hans utrustning, däribland hans personliga klinga. Med så många dvärgar att genomsöka förlitar sig Humbert på Horde-agenter för att infiltrera fästningen och återta sitt förlorade vapen."},{t="Dvärgarnas byte",b="Efter stölden fördes Humberts tillhörigheter bakom Dun Garoks befästa barrikader. Dvärgiska gevärsskyttar, bergsjägare och präster fördelar förråd i garnisonen. Därför måste man leta bland försvararna i fästningens skyttegravar och skansar för att hitta just tjuven."}},faq={{q="Vem äger det här svärdet?",a="Klingan tillhör Deathguard Humbert, en Forsaken-vaktpost i Tarren Mill som fått i uppdrag att spana på Dun Garok.",al={"vems svärd är det här","humberts ägare","vem är humbert"}},{q="Hur fick dvärgarna tag på Humberts svärd?",a="Deathguard Humbert lämnade sin spejarlägerplats strax utanför Dun Garok på morgonen för att samla ved. Medan han var borta plundrade en dvärgpatrull lägret och förde bort hans utrustning.",al={"hur fick dvärgarna tag på det","varför har dvärgarna ett svärd","hur stals svärdet"}},{q="Varför är Humbert så desperat att få tillbaka sitt svärd?",a="Humbert behöver sitt vapen för att fortsätta bevaka Dun Garok, ett uppdrag han fått av High Executor Darthalia. Med så många dvärgar i garnisonen kan han inte hoppas hitta tjuven på egen hand.",al={"varför vill humbert ha svärdet","vad händer om humbert förlorar svärdet","varför bryr sig humbert"}},{q="Var finns svärdet?",a="Svärdet finns hos dvärgstyrkorna i Dun Garok, i sydöstra Hillsbrad Foothills. Det kan återtas från bergsjägarna, gevärsskyttarna eller prästerna som är stationerade runt om i utposten.",al={"var faller svärdet","svärdets plats","hur hittar man humbert's sword"}}},fp="15,163,25.357.0,17.242.0,20.116.0,40.156.0,50.171.0,29.181.0"}
P.entries["item:huntsman-malkhor-s-bones"] = {n="Huntsman Malkhor's Bones"}
P.entries["item:huntsman-malkhor-s-skull"] = {n="Huntsman Malkhor's Skull",s="Huntsman Malkhor's Skull är en del av kvarlevorna Huntsman Markhor söker efter i Jintha'alor. Han hoppas kunna ge sin tvillingbror en värdig begravning.",h="Huntsman Malkhor's Skull är en del av kvarlevorna Huntsman Markhor söker efter i Jintha'alor.",kw={"huntsman malkhor","huntsman markhor","jintha'alor","malkhors skalle","revantusk village","separationsångest","vilebranch"},sec={{t="En brors kvarlevor",b="Bland skallarna i Jintha'alor finns en som tillhör Huntsman Malkhor, tvillingbror till Huntsman Markhor från Revantusk Village. Vilebranch dödade Malkhor och lämnade kvarlevorna åt slemvarelser och vargar nära templets övre delar. Markhor ber dig hämta skallen och benen så att hans brors själ kan få ro."}},faq={{q="Vem tillhör skallen?",a="Skallen tillhör Huntsman Malkhor, tvillingbror till Huntsman Markhor från Revantusk Village.",al={"malkhors skalle","vems skalle","huntsman malkhor"}},{q="Var finns Malkhors skalle?",a="Malkhors skalle ligger i en hög med skallar på Jintha'alors övre nivå.",al={"skallens plats","var finns skallen","jintha'alors skalle"}},{q="Vem vill ha Malkhors kvarlevor?",a="Huntsman Markhor vill att du hämtar hans tvillingbrors skalle och ben så att han kan få en värdig begravning.",al={"vem vill ha kvarlevorna","markhors bror","separationsångest"}},{q="Hur dog Malkhor?",a="Vilebranch dödade Malkhor under en räd och gav hans kvarlevor åt slemvarelser och vargar.",al={"vad hände malkhor","malkhors död","vilebranch dödade"}},{q="Varför söker Markhor efter kvarlevorna?",a="Markhor hoppas kunna ordna en värdig begravning åt Malkhor och ge hans själ ro.",al={"varför hämta skallen","malkhors begravning","broderns kvarlevor"}}},fp="24,137,19.321.0,29.97.0,25.75.0,28.93.0,20.80.1,41.95.0"}
P.entries["item:hyacinth-mushroom"] = {n="Hyacinth Mushroom",s="Hyacinth Mushroom är en särpräglad svamp som växer vid trädrötter runt om i Shadowglen på Teldrassil. Lokala Night Elf-örtalister uppskattar dess läkande egenskaper, men den är också favoritföda och samlarbyte för de rackartygslystna grell och grellkin.",h="Hyacinth Mushroom är en särpräglad svamp som växer vid trädrötter runt om i Shadowglen på Teldrassil.",kw={"motgift","dirania silvershine","grell","grellkin","hyacinth mushroom","iverron","shadowglen","teldrassil"},ang={["profession:Herbalism"]="Det krävs ingen formell utbildning för att plocka svampen i Shadowglen, men varje nybörjare inom örtmedicin har nytta av att lära sig hur den neutraliserar skogens starka gifter.",["race:NightElf"]="För unga Night Elf som tränar i Shadowglen är det en tidig läxa att skörda vilda växter som Hyacinth Mushroom och använda naturens gåvor för att försörja sitt folk."},sec={{t="Shadowglens växtliv",b="Hyacinth Mushroom växer rikligt i Shadowglen, i de fuktiga skuggorna vid trädens bas, mossiga stenar och Aldrassils vidsträckta rötter. Svampen är användbar i skogsmediciner, men har också väckt de korrumperade grells intresse. De samlar ofta på den. När unga Night Elf-väktare eller aspiranter drabbas av giftiga djur i trakten, som spindlarna i Shadowthread Cave, är svampen en viktig ingrediens i lindrande brygder och motgift som skogens läkare blandar till."}},faq={{q="Vad används Hyacinth Mushroom till?",a="Dirania Silvershine använder den som en viktig ingrediens i ett motgift åt Iverron, en ung Night Elf som blev biten och förgiftad av giftspindlar när han utforskade Shadowthread Cave.",al={"hyacinth mushroom användning","vad gör den","bota iveron"}},{q="Var växer Hyacinth Mushroom?",a="Den spirar direkt ur marken nära stora träds stammar och rötter, liksom intill klippblock i Shadowglens avskilda dal på Teldrassil.",al={"svampens plats","var hittar man hyacinth mushroom","svampar i shadowglen"}},{q="Varför bär grell på Hyacinth Mushroom?",a="De rackartygslystna grell och grellkin som hemsöker södra Shadowglen har fattat tycke för svampen. De samlar och gömmer den i sina läger.",al={"grell släpper svamp","varför har grell svampar","grellkin svampar"}},{q="Är Hyacinth Mushroom giftig i sig?",a="Nej. Trots sitt klara utseende och den skuggiga miljö där den trivs använder traktens läkare den tryggt som ingrediens i läkande omslag och stärkande motgifter.",al={"är hyacinth mushroom giftig","giftig svamp"}}},fx={["77b7a797"]={q="Vad är en Hyacinth Mushroom?",a="Hyacinth Mushroom är en inhemsk svamp som växer bland Teldrassils skuggiga trädkronor, särskilt vid trädens baser och bland mossiga stenar i Shadowglen. Skogssvamparna är kända för sina läkande egenskaper och kan motverka gift när de kokas på rätt sätt tillsammans med andra växter i området.",al={"vad är hyacinth mushroom","information om hyacinth mushroom","om hyacinth mushrooms"}}},fp="17,161,19.329.0,37.158.0,33.121.0,42.102.0,44.84.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="Hypercapacitor Gizmo",s="Hypercapacitor Gizmo är ett excentriskt ingenjörsbygge som bärgats från botten av ravinen i Thousand Needles. Den hängde en gång runt halsen på ett inspärrat vilddjur i en förstörd karavan, och dess verkliga syfte är fortfarande ett mysterium, även för uppfinnaren som säger sig äga den.",h="Hypercapacitor Gizmo är ett excentriskt ingenjörsbygge som bärgats från botten av ravinen i Thousand Needles.",kw={"centaur","ursinnig panter","apparat","hypercapacitor","thousand needles","whitereach post","wizlo bearingshiner"},ang={["faction:Horde"]="Resande som hjälper Whitereach Post röjer undan de aggressiva centaur och hämtar tillbaka förlorade märkliga föremål från förstörda karavaner över ravinbottnen.",["profession:Engineering"]="Apparaten är ett klassiskt exempel på gobliningenjörskonst: en invecklad apparat med ett farligt klingande namn, byggd med stor entusiasm innan någon ens bestämt vad den skulle göra."},sec={{t="En karavans märkliga relik",b="När centaur-rövare överföll en goblinkaravan på väg genom Thousand Needles plundrade de nästan allt de kunde se. Den enda överlevande, Wizlo Bearingshiner, lyckades kravla sig i säkerhet vid Whitereach Post och lämnade sitt bästa bygge bakom sig: Hypercapacitor Gizmo. Märkligt nog hade man fäst apparaten runt halsen på en ursinnig, rasande panter som satt inlåst i en transportbur. Rövarnas centaur var så rädda för odjuret att de lämnade buren helt orörd bland de brinnande spillrorna och bevarade därmed ovetande Wizlos märkliga maskin."},{t="Pillande i mörkret",b="Wizlo kallar stolt apparaten sitt bästa bygge, men erkänner när den återfinns att han inte har en aning om vad den faktiskt gör. Liksom många goblinkonstruktioner är Hypercapacitor Gizmo en trasslig blandning av ambitioner och instabila delar, avsedd att hålla ägaren sysselsatt med ändlöst pillande i stället för att fylla någon praktisk, begriplig funktion."}},faq={{q="Vad är Hypercapacitor Gizmo?",a="Det är en ingenjörsapparat som tillhör goblinen Wizlo Bearingshiner. Trots sitt pampiga namn vet inte ens Wizlo vad den faktiskt har för funktion. Han tänker ägna sin tid åt att studera den och ta reda på vad den är till för.",al={"vad är en pryl","hypercapacitor","vad gör apparaten"}},{q="Hur hamnade apparaten runt halsen på en panter?",a="Wizlos karavan överfölls och plundrades av centaur i norra Thousand Needles. Under kaoset hamnade apparaten fäst runt halsen på en ursinnig panter i en transportbur, vilket fick de vidskepliga centaur att låta den vara.",al={"varför har pantern apparaten","hur fick pantern den"}},{q="Vem vill ha tillbaka Hypercapacitor Gizmo?",a="Wizlo Bearingshiner, den enda överlevande från den plundrade karavanen, vill ha tillbaka den. Han har sökt skydd vid Whitereach Post, ett taurenläger i nordvästra Thousand Needles.",al={"vem behöver apparaten","wizlos apparat"}},{q="Varför stal inte centaur den?",a="Centaur plundrade hela karavanen men var livrädda för den vildsinta pantern i buren. De lät odjuret och dess metallkrage vara helt orörda bland ruinerna.",al={"varför tog inte centaur den","centaur och panter"}}},fx={["240fe489"]={q="Varifrån kommer Hypercapacitor Gizmo, och vem har tillverkat det?",a="Anordningen tillhörde goblinmekanikern Wizlo Bearingshiner, som färdades med en karavan genom Thousand Needles innan centaurerna överföll dem. Wizlo kallar den sin kära ägodel, men det är fortfarande ett mysterium vem som uppfann den. Till och med Wizlo medger att han inte riktigt förstår vad den märkliga maskinen gör.",al={"vem tillverkade hypercapacitor gizmo","hypercapacitor gizmos ursprung","var fick wizlo tag på hypercapacitor gizmo"}}},fp="20,178,25.378.0,21.227.0,33.172.0,50.235.0,40.175.0,32.147.0"}
P.entries["item:ignition-key"] = {n="Ignition Key",s="Vid Sludge Fen hålls Ignition Key av Supervisor Lugwizzle vid Venture Companys borrningsplats. Wizzlecrank behöver den för att låsa upp en avancerad strimlares rörelsekolumn och aktivera dess reglage.",h="Vid Sludge Fen hålls Ignition Key av Supervisor Lugwizzle vid Venture Companys borrningsplats.",kw={"ignition key","huggare","the sludge fen","sputtervalve","supervisor lugwizzle","venture company","wizzlecrank"},ang={["profession:Engineering"]="Ignition Key låser upp en strimlare med avancerade reglage, däribland hastighetsreglering och precisa armrörelser som överträffar vanliga goblinkonstruktioner."},sec={{t="En saknad del av spionaget",b="Sputtervalve från Ratchet skickade en agent för att stjäla en Venture Company-strimlare från Sludge Fen, men planen körde fast. Den förklädde piloten, Wizzlecrank, klättrade in i förarhytten och upptäckte att rörelsekolumnen var låst. Han låtsades att maskinen hade mekaniska problem, så att förmännen inte skulle bli misstänksamma medan han väntade på att någon skulle hämta Ignition Key. Supervisor Lugwizzle förvarar nyckeln högt uppe på det centrala oljetornet, där reglagen för strimlarens arm, hastighet och rotation finns."}},faq={{q="Var finns Ignition Key?",a="Supervisor Lugwizzle förvarar Ignition Key i kontrollrummet högst upp i oljetornet i Sludge Fen, där han övervakar borrningsarbetet.",al={"plats för ignition key","vem tappar ignition key","hur får man ignition key"}},{q="Varför behöver Wizzlecrank just den här nyckeln?",a="Den avancerade Venture Company-strimlaren har en låst rörelsekolumn. Utan tändningsnyckeln kan Wizzlecrank inte styra dess rotation, hastighet, stabilitet eller arm tillräckligt bra för att köra iväg med den.",al={"varför behövs nyckeln","vad gör nyckeln","huggarens nyckel"}},{q="Vem vill få huggarstölden genomförd?",a="Sputtervalve, en gobliningenjör i Ratchet, ordnade stölden för att komma över Venture Companys överlägsna ingenjörsritningar.",al={"vem skickade wizzlecrank","varför stjäla huggaren","huggare i ratchet"}},{q="Vad händer när nyckeln har lämnats in?",a="Med nyckeln låser Wizzlecrank upp rörelsekolumnen och startar strimlarens motor. Sedan måste han ta sig snabbt genom Sludge Fens fientliga arbetare för att fly mot Ratchet.",al={"efter att ha lämnat in nyckeln","flykten","vad händer sedan"}}},fx={["762c90b7"]={q="Vad är Ignition Key?",a="Ignition Key är en startnyckel som låser upp styrspaken på en avancerad flismaskin från Venture Company vid The Sludge Fen. Utan den förblir den tunga skogsmaskinens reglage låsta, och piloten kan varken styra eller köra den.",al={"vad är ignition key","vad används ignition key till","nyckel till flismaskinen"}},["8801ec8f"]={q="Varifrån kommer Ignition Key?",a="Nyckeln hör till Venture Companys borrnings- och skogsavverkningsverksamhet vid The Sludge Fen. Den innehas av Supervisor Lugwizzle, som övervakar området från kontrollrummet ovanpå det centrala oljetornet.",al={"vem tillverkade ignition key","ignition keys ursprung","varifrån kom nyckeln"}}},fp="12,80,28.444.0,36.136.0,44.180.0,30.124.0,39.169.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="Ilkrud Magthrull's Tome",s="Ilkrud Magthrull's Tome är en grimoar som återfanns hos en farlig orcisk häxmästare i Ashenvales fördärvade djup. När den överlämnades till Delgren the Purifier avslöjade dess vidriga innehåll de större mörka intrigerna kring kultisterna i Tower of Althalaxx.",h="Ilkrud Magthrull's Tome är en grimoar som återfanns hos en farlig orcisk häxmästare i Ashenvales fördärvade...",kw={"ashenvale","delgren the purifier","fire scar shrine","ilkrud magthrull","maestra's post","bok","tower of althalaxx","häxmästare"},ang={["class:Paladin"]="Att återta boken hjälper Brother Delgren, en medkämpe för det heliga ljuset som vaksamt står emot skuggor och fördärv i Ashenvales otämjda vildmark.",["class:Warlock"]="Magthrulls grimoar är en värdefull dokumentation av mörka bindningar, med detaljer om kuvandet av voidwalkers och succubi vid det besmittade Fire Scar Shrine."},sec={{t="En grimoar av fördärv",b="Ilkrud Magthrull är en mäktig orcisk häxmästare som håller till vid Fire Scar Shrine i sydvästra Ashenvale, en plats förgiftad av kvarvarande demoniskt inflytande. Omgiven av frammanade undersåtar skrev Magthrull ner sina vidriga ritualer och dunkla meddelanden i denna personliga bok. Argent Dawn-paladinen Delgren the Purifier hade länge känt till häxmästarens närvaro, men de upptäckta banden mellan Magthrull och de mörka kultister som samlats vid Tower of Althalaxx gjorde det brådskande att återta boken."},{t="Att nysta upp kultens nätverk",b="När boken tagits från Magthrulls livlösa grepp överlämnas den till Delgren vid Maestra's Post. Delgren försöker tyda häxmästarens skrifter för att förstå nätverket som samordnar demonisk aktivitet över gränserna mellan Darkshore och Ashenvale. Texten ger viktiga underrättelser om de dunkla konspiratörer som drar i trådarna bakom fördärvet som slår rot i norra Kalimdor."}},faq={{q="Vem äger den här boken?",a="Boken tillhör Ilkrud Magthrull, en mäktig orcisk häxmästare som slagit sig ner bland de demoniska ruinerna vid Fire Scar Shrine i sydvästra Ashenvale.",al={"vem är ilkrud magthrull","vem skrev boken","ilkrud magthrull"}},{q="Var hittar man boken?",a="Den återtas direkt från Ilkrud Magthrull vid Fire Scar Shrine, som ligger söder om The Shrine of Aessina i Ashenvale.",al={"bokens plats","hur får man tag på boken","var hittar man ilkrud"}},{q="Varför vill Delgren the Purifier ha boken?",a="Delgren vill studera Magthrulls skrifter för att avslöja de mörka banden mellan lokala demonanhängare och kultisterna i Tower of Althalaxx.",al={"varför vill delgren ha boken","vad finns i boken","delgrens syfte med boken"}},{q="Vad händer när boken har återtagits?",a="Delgren granskar texten vid Maestra's Post för att tyda Magthrulls demoniska meddelanden och avgöra nästa steg i arbetet med att upplösa kultens nätverk.",al={"lämna in boken","vad gör delgren med boken"}}},fx={["5352c240"]={q="Varifrån kommer Ilkrud Magthrull's Tome, och vem har tillverkat den?",a="Boken innehåller Ilkrud Magthrulls personliga anteckningar och mörka forskning. Han är en mäktig orchhäxmästare som bor bland den demoniska korruptionen vid Fire Scar Shrine i sydvästra Ashenvale. Häxmästaren skrev själv boken, som samlar hans mörka besvärjelser och anteckningar. Han höll den nära till hands fram till sitt fall.",al={"vem skrev ilkrud magthrulls tome","ilkrud magthrulls bok ursprung","varifrån kom boken"}}},fp="23,159,24.434.0,19.342.1,19.142.0,24.109.0,44.139.0,41.138.0"}
P.entries["item:incantations-from-the-nether"] = {n="Incantations from the Nether",s="Under Orgrimmar håller Searing Blade-kultister Incantations from the Nether, en grimoar med demonisk magi. Sylvanas Windrunner och Varimathras söker dess demoniska kunskap åt Forsaken.",h="Under Orgrimmar håller Searing Blade-kultister Incantations from the Nether, en grimoar med demonisk magi.",kw={"incantations from the nether","ragefire chasm","searing blade","shadow council","spells of shadow","sylvanas","kraften att förgöra","varimathras"},ang={["class:Warlock"]="Böcker som hämtats direkt från Nether rymmer mäktig demonisk magi, åtrådd av ambitiösa utövare av mörk konst.",["race:Undead"]="Att hämta boken hjälper Dark Ladys innersta krets i Undercity. Den mörka kunskapen behövs för att föra krig mot Scourge."},sec={{t="Legionens gåvor",b="Searing Blade är en underjordisk sekt med band till Shadow Council, verksam i de eldiga gångarna i Ragefire Chasm under Orgrimmars röda stengator. Dess kultister värdesätter Incantations from the Nether, en trollformelsbok med demoniska riter som Burning Legions agenter har gett dem. De använder dess hemligheter för att smida förräderi i orchernas huvudstad. Ryktet om boken har nått Undercitys kungliga kvarter."},{t="Forsakens ambition",b="Varimathras skickar lojala Horde-äventyrare djupt in i Ragefire Chasm för att hämta Incantations from the Nether och dess systervolym, Spells of Shadow. Sylvanas Windrunner och hennes skräckfurstelöjtnant anser att sådana demoniska reliker går till spillo hos kultister med sämre omdöme. Dark Lady tänker använda bokens kraft, smidd i Nether, mot Lich King och utkräva vedergällning av Scourge."}},faq={{q="Var hittar man boken Incantations from the Nether?",a="Searing Blade-kultister och häxmästare bär boken i Ragefire Chasm, det vulkaniska grottnätverket under Orgrimmar.",al={"var hittar man incantations from the nether","vem släpper incantations from the nether","incantations from the nether plats"}},{q="Vem vill ha boken och varför?",a="Lady Sylvanas Windrunner och skräckfursten Varimathras söker boken. De ser Searing Blade-kultisterna som obetydliga och med sämre omdöme, och vill använda dess demoniska magi för att bekämpa sin svurna fiende, Lich King.",al={"vem behöver incantations from the nether","varför vill sylvanas ha den här boken","varimathras bokuppdrag"}},{q="Vad är Searing Blade?",a="Searing Blade är en hemlighetsfull underjordisk sekt av häxmästare och kultister under Orgrimmar, allierad med Shadow Council. Dess medlemmar tjänar Burning Legion och arbetar i hemlighet för att underminera Thralls nya Horde.",al={"searing blade berättelse","vilka är searing blade"}},{q="Vilken annan bok hör ihop med den här?",a="Varimathras behöver två volymer: Incantations from the Nether och Spells of Shadow. Båda måste tas från kultisterna i Ragefire Chasm för att slutföra hans uppdrag.",al={"annan bok åt varimathras","kraft att förgöra böcker"}}},fx={e0d58fa2={q="Vad är Incantations from the Nether?",a="Incantations from the Nether är en mörk grimoar med felmagi som Burning Legion skänkt. Den hamnade hos Searing Blade, en hemlig kult inom Shadow Council som verkar djupt nere i de eldiga klyftorna under Orgrimmar. Tillsammans med sin systerbok, Spells of Shadow, innehåller den kraftfulla demoniska ritualer som kultens häxmästare studerar för att tygla virvlande nätets krafter.",al={"vad är incantations from the nether","boken incantations from the nether","vad är det för slags bok incantations from the nether"}}},fp="28,178,19.393.0,17.383.1,53.136.0,28.188.0,26.215.0,40.164.0"}
P.entries["item:incendia-agave"] = {n="Incendia Agave",s="Incendia Agave är en sällsynt, taggig vattenväxt som hör hemma i Boiling Pool under Darkcloud Pinnacle i Thousand Needles. När en skicklig schaman förtrollar den kan dess unika egenskaper tända livets heliga eld.",h="Incendia Agave är en sällsynt, taggig vattenväxt som hör hemma i Boiling Pool under Darkcloud Pinnacle i...",kw={"arikara","boiling pool","darkcloud pinnacle","incendia agave","magatha grimtotem","helig eld","thousand needles"},ang={["class:Shaman"]="Agaven kräver rå schamanistisk elementarkonst för att omvandlas från en vattenväxt till ett pulver som är kraftfullt nog att tända heliga rituella lågor.",["profession:Herbalism"]="Örtkunniga har stor nytta av sitt spårsinne när de letar efter taggiga tuvor av Incendia Agave som gömmer sig längs den grumliga bottnen i Boiling Pool."},sec={{t="En sällsynt ökenört",b="Incendia Agave växer under och runt vattnet i Boiling Pool i Thousand Needles, direkt i skuggan av Darkcloud Pinnacle. Vandrande ångelementaler skyddar den naturligt, så den är svår att skörda och sällsynt i hela Kalimdor. Trots att den växer under vatten innehåller den kraftfulla naturelement som passar direkt för eldr ritualer."},{t="Den heliga elden",b="Taurenritualister vet att livets slumrande heliga eld inte kan tändas med vanliga gnistor. Äldste Magatha Grimtotem på Elder Rise i Thunder Bluff har de schamankunskaper som krävs för att förtrolla skördade säckar med Incendia Agave till ett mystiskt pulver. När pulvret är färdigt tänder det den ceremoniella eldfatet som behövs för att kalla fram den hämndlystna vindormen Arikara."}},faq={{q="Var växer Incendia Agave?",a="Incendia Agave växer i och runt sjön vid Boiling Pool, under Darkcloud Pinnacle i norra Thousand Needles. Mycket av den ligger nedsänkt på sjöbottnen.",al={"var hitta agave","incendia agaves plats","var finns agave"}},{q="Vad används Incendia Agave till?",a="Tio säckar agave samlas in för att framställa ett ritualpulver. När Magatha Grimtotem har förtrollat pulvret i Thunder Bluff används det för att tända livets heliga eld och kalla fram ormen Arikara.",al={"incendia agaves syfte","varför samla agave","vad gör agave"}},{q="Vem kan förtrolla Incendia Agave?",a="Magatha Grimtotem, en inflytelserik schaman på Elder Rise i Thunder Bluff, har den rituella kunskap som krävs för att väva in schamanmagi i den råa växten.",al={"vem förtrollar agave","magatha agave","vem gör agave till pulver"}},{q="Vilka hot omger Incendia Agave?",a="Fientliga ångelementaler strövar omkring i vattnet och längs stränderna vid Boiling Pool. De är särskilt motståndskraftiga mot frost- och eldbesvärjelser.",al={"faror med agave","vad vaktar agave","faror i boiling pool"}}},fx={d4005c78={q="Vad är Incendia Agave?",a="Incendia Agave är en ytterst sällsynt, taggig ört som bara växer kring och i Boiling Pools ångande vatten i Thousand Needles. Trots att den växer vid sjöns djup bär den på starka, vilande eldegenskaper. När en skicklig schaman har förädlat den blir den en viktig ingrediens i ritualer som kräver elementarkraft.",al={"vad är incendia agave","växten incendia agave","vad är incendia agave för slags växt"}}},fp="14,136,18.272.0,15.238.1,31.165.0,32.172.0,35.131.0,41.131.0"}
P.entries["item:incendia-powder"] = {n="Incendia Powder",s="Incendia Powder är en förtrollad rituell katalysator som förfinats för att tända heliga lågor. Hordens sändebud bär pulvret till Thousand Needles, där det särskilt behandlas med shamanistiska besvärjelser för att åkalla den slumrande andebesten Arikara på toppen av Darkcloud Pinnacle.",h="Incendia Powder är en förtrollad rituell katalysator som förfinats för att tända heliga lågor.",kw={"arikara","darkcloud pinnacle","incendia powder","motega firemane","heliga livselden","thousand needles","whitereach post"},ang={["class:Shaman"]="Pulvret visar hur elementär eld och andligt beskydd kan förenas för att väcka slumrande förfädersväsen.",["race:Tauren"]="Att använda rituella pulver för att tända gravbål speglar den sköra balansen mellan att vörda heliga traditioner och att försvara stammarnas ledarskap."},sec={{t="En åkallelsens gnista",b="Incendia Powder är inget vanligt sprängämne eller vanligt blixtpulver, utan ett renat, rituellt ämne som varsamt har genomsyrats av shamanistisk magi. Magatha Grimtotem förtrollar blandningen och anförtror den åt resenärer på Elder Rise i Thunder Bluff. Den är utformad för att reagera enbart med den slumrande heliga livselden på de avlägsna spirorna vid Darkcloud Pinnacle. När pulvret strös över den invigda eldstaden där de döda läggs till vila, kallar dess alkemiska och andliga skydd fram den hämndlystna bevingade ormen Arikara."},{t="Oroande tecken",b="Riterna som styr tillverkningen och användningen av Incendia Powder bygger på den äldre schamanen Magatha Grimtotems tolkningar. Hon tror att förändrade traditioner och ändrade seder bland tauren har fått uråldriga andar att jaga högöverhövding Cairne Bloodhoof. Därför förtrollades pulvret för att tvinga fram uppenbarelsen så att den kunde förstöras. Pulvret lyckas kalla fram den fruktansvärda ormen, men den våldsamma striden väcker oroväckande frågor om varför besten egentligen stördes."}},faq={{q="Vad används Incendia Powder till?",a="Incendia Powder är ett förtrollat stoft som kastas i den heliga livselden på toppen av Darkcloud Pinnacle i Thousand Needles. När blandningen tänder lågan kallas den hämndlystna andeormen Arikara fram.",al={"incendia powder syfte","varför behöver jag incendia powder","vad gör incendia powder"}},{q="Vem förtrollade pulvret?",a="Magatha Grimtotem förtrollade den insamlade Incendia Agave och gjorde den till ett förädlat pulver på Elder Rise i Thunder Bluff, efter att Motega Firemane från Whitereach Post skickat bud om Arikara.",al={"vem tillverkade incendia powder","vem förtrollade incendia powder"}},{q="Var måste pulvret användas?",a="Det måste strös i den heliga eldgropen på en avskild gravspira inom Darkcloud Pinnacle, högt ovanför Thousand Needles saltravinlandskap.",al={"incendia powder plats","var ska jag kasta incendia powder","var ska incendia powder användas"}},{q="Varför var det nödvändigt att åkalla Arikara?",a="Magatha Grimtotem fruktar att förändringar i taurenernas traditioner har gjort Arikara vred och att ormen kanske förföljer Cairne Bloodhoof. Hon ber att Arikara ska åkallas och dödas innan Cairne kan skadas.",al={"varför åkalla arikara","varför slåss mot arikara"}}},fx={["53c7ed7b"]={q="Vad är Incendia Powder?",a="Incendia Powder är ett förädlat, renat reagens genomsyrat av rituell magi. När pulvret strös över livets heliga eld på Darkcloud Pinnacle i Thousand Needles fungerar dess invävda förtrollning som en fyr som lockar fram Arikara, den hämndlystna vindormsanden.",al={"vad är incendia powder","historien om incendia powder","vad är pulvret"}}},fp="15,164,20.287.0,15.324.1,33.156.0,43.164.0,38.153.0,36.192.0"}
P.entries["item:insane-scribbles"] = {n="Insane Scribbles",s="De här Insane Scribbles, som slitits loss ur den förbryllande Twilight Tome, är ett fragment av mörk litteratur som kultister i Darkshore bär med sig. Att bara se den dansande texten och de förvridna ornamenten orsakar svår yrsel och mental påfrestning. Skogens uråldriga väktare studerar sådana fragment för att tyda Twilight's Hammers illasinnade avsikter.",h="De här Insane Scribbles, som slitits loss ur den förbryllande Twilight Tome, är ett fragment av mörk...",kw={"darkshore","insane scribbles","vansinne","de gamla gudarna","onu","twilight tome","twilight's hammer"},ang={["class:Priest"]="Präster som är känsliga för mentala angrepp och tomrörda energier känner igen den slingrande skriften som en farlig manifestation av vansinne, i direkt motsats till Ljusets klarhet.",["race:NightElf"]="För nattalverna utgör reliker från Twilight's Hammer ett fördärvande hot mot Darkshores uråldriga frid och heliga marker."},sec={{t="Ett vansinnesframkallande manuskript",b="Att betrakta sidorna i Twilight Tome är ytterst farligt för dödligas förstånd. Skriften slingrar sig över pergamentet, medan de eleganta ornamenten förvrids till groteska, oroande bilder inför läsarens ögon. Att slita loss ens ett enda blad – dessa Insane Scribbles – är en prövning som gör bäraren omtöcknad och desorienterad. Trots skriftens kaotiska obegriplighet sjuder pergamentet av uråldrig, ursprunglig magi som är direkt knuten till mörka krafter, sedan länge begravda under Azeroth."},{t="Ledtrådar åt de uråldriga",b="När klottret förs till Onu, den vördnadsvärda Ancient som vakar över Grove of the Ancients, ger det en inblick i de intrång som förpestar Darkshore. Onu känner igen den kaotiska energin som hänger kvar i pergamentet som De gamla gudarnas omisskännliga verk. För Kalimdors försvarare är det ett avgörande steg mot att ta reda på exakt varför Twilight's Hammer har samlats längs de dimhöljda stränderna att lägga pusslet av klottret."}},faq={{q="Vad händer om man försöker läsa klottret?",a="Texten låter sig inte enkelt översättas. Att bara titta på pergamentet får bokstäverna att flyta ihop och de omgivande mönstren att förvandlas till fasansfulla former, vilket orsakar plötslig yrsel och mental utmattning hos alla som försöker tyda dem.",al={"läsa vansinnesklotter","vad står det i texten","går det att läsa klottret"}},{q="Varifrån slets klottret loss?",a="Det slets ur Twilight Tome, en motbjudande magisk bok som förvaras av Twilight's Hammer-kultister verksamma i Darkshore.",al={"varifrån kommer klottret","twilight tome ursprung"}},{q="Vem kan förstå eller studera klottret?",a="The Ancient of Lore, Onu, undersöker det återfunna pergamentet. Med hjälp av århundraden av kunskap känner Onu den uråldriga, ursprungliga magin som binder bläcket och försöker ta reda på kultens syfte i regionen.",al={"vem vill ha klottret","onus klotter"}},{q="Vilken sorts kraft utstrålar pergamentet?",a="Pergamentet pulserar av kaotisk, ursprunglig magi knuten till De gamla gudarna, en återspegling av de mörka gudar som Twilight's Hammer dyrkar.",al={"vilken magi finns i klottret","typ av magi"}}},fx={["12486380"]={q="Vad är Insane Scribbles?",a="De är en enda vansinnesframkallande sida som rivits ur den mörka text som kallas Twilight Tome. Skriften böljar, dansar och vrider sig till groteska former framför dina ögon. Den utstrålar en kaotisk och ursprunglig magisk aura som hotar att överväldiga dina sinnen om du stirrar för länge.",al={"vad är insane scribbles","insane scribbles i berättelsen","vad är det här pergamentet"}},b40c7e7e={q="Varför vill Onu ha Insane Scribbles?",a="Den uråldrige Onu känner de gamla gudarnas kaotiska beröring invävd i pergamentet. Han vill studera de återfunna skrifterna i hopp om att tyda vad den hemlighetsfulla kulten Twilight's Hammer planerar i Darkshores skogar och längs dess stränder.",al={"varför vill onu ha insane scribbles","vem vill ha scribbles","varför ta scribbles till onu"}}},fp="16,246,22.397.0,22.356.1,48.213.0,37.122.0,42.200.0,47.123.0"}
P.entries["item:inscribed-bark"] = {n="Inscribed Bark",s="Inscribed Bark är ett levande pergament som det uråldriga The Oracle Tree anförtrott att förmedla Teldrassils tillstånd till Arch Druid Fandral Staghelm. Det fungerar som en officiell rapport om grenarna på Världsträdet och de kvardröjande hoten som plågar dess skogar.",h="Inscribed Bark är ett levande pergament som det uråldriga The Oracle Tree anförtrott att förmedla Teldrassils...",kw={"cenarion circle","darnassus","fandral staghelm","inscribed bark","oracle tree","teldrassil"},ang={["class:Druid"]="Druider känner igen detta inristade trä som ett brådskande bud från en uråldrig allierad, som pekar på den unga Världsträdets sköra balans och pågående plågor.",["race:NightElf"]="För Kaldorei står budskap på bark från uråldriga träd för det heliga bandet mellan naturen och dess väktare, och förbinder vildmarkens lundar med Darnassus marmorterrasser."},sec={{t="Ett budskap från The Oracle Tree",b="Denna inristade bark, skuren ur The Oracle Trees heliga trä, fungerar som en direkt förbindelse mellan den uråldriga väktaren och ledningen för Cenarion Circle i Darnassus. När äventyrarna har drivit bort harpyorna som tränger in i gläntorna, anförtror The Oracle Tree dem denna bricka, ovillig att riskera vanliga budbärare på de fördärvade stigarna bland grenarna. Det inristade budskapet informerar Arch Druid Fandral Staghelm om både de senaste segrarna och den djupare, oroande farsot som fortfarande håller Teldrassil i sitt grepp."}},faq={{q="Vad är Inscribed Bark?",a="Det är en barkbit med en inskriven lägesrapport från The Oracle Tree om grenarnas tillstånd och faror, avsedd för Arch Druid Fandral Staghelm i Darnassus.",al={"vad är inscribed bark","oracle tree-bark","inscribed barks syfte"}},{q="Vem skickar budskapet och varför?",a="The Oracle Tree ger den till äventyrarna efter att de drivit bort harpyorna från deras bon. Den uråldriga har blivit försiktig med att skicka vanliga budbärare längs skogens hotade stigar och anförtror därför en beprövad resenär att leverera rapporten.",al={"vem skrev inscribed bark","vem ger inscribed bark","oracle trees budbärare"}},{q="Hur reagerar Arch Druid Fandral Staghelm på budskapet?",a="Fandral erkänner att harpyornas nederlag gett ett andrum, men konstaterar frustrerat att djupare problem kvarstår. Rapporten förstärker hans kvardröjande oro över huruvida hans arbete med Teldrassil någonsin verkligen kommer att återställa nattalvernas förlorade odödlighet.",al={"fandrals reaktion på barken","vad säger fandral om barken"}}},fp="14,166,25.352.0,23.152.0,31.202.0,58.213.1"}
P.entries["item:insect-analysis-report"] = {n="Insect Analysis Report",s="Insect Analysis Report innehåller brådskande uppgifter om ett hot som sprider sig i Tanaris. Senior Surveyor Fizzledowser låter kopiera rapporten så att varningen når fler.",h="Insect Analysis Report innehåller brådskande uppgifter om ett hot som sprider sig i Tanaris.",kw={"fizzledowser","gadgetzan","insect analysis report","analys av insektsdelar","pestlezugg","silithider","tanaris","zilzibin drumlore"},ang={["faction:Alliance"]="Rapportens varning gäller silithiderna, som Zilzibin Drumlore pekar ut som ett hot mot både Alliance och Horde.",["faction:Horde"]="Rapporten ska varna din fraktion för silithiderna, ett hot som enligt Zilzibin Drumlore riktar sig mot både Horde och Alliance."},sec={{t="En varning från Tanaris",b="I Gadgetzan ber Senior Surveyor Fizzledowser att rapporten sprids vida omkring. Alchemist Pestlezugg anser att alla som kan läsa bör få veta om faran. Fizzledowser går med på att göra en kopia som du kan ta med till din fraktion."},{t="Lärd i Drag",b="I Orgrimmar studerar Zilzibin Drumlore Azeroths livsformer och historia. Han känner igen varelserna som beskrivs i rapporten som silithider och varnar för att de snabbt kan sluka Tanaris öken. Han kallar dem redskap för ett hot mot både Horde och Alliance."}},faq={{q="Vad är Insect Analysis Report?",a="Insect Analysis Report beskriver silithiderna, ett allvarligt hot som sprider sig från Tanaris.",al={"insektsrapport","analysrapport","vad finns i rapporten"}},{q="Vem skrev rapporten?",a="Senior Surveyor Fizzledowser skickar rapporten för vidare studier och spridning.",al={"vem gjorde rapporten","fizzledowsers rapport","varifrån kom rapporten"}},{q="Varför gör Fizzledowser en kopia?",a="Alchemist Pestlezugg ber om en kopia så att varningen kan spridas bland din fraktion.",al={"varför kopiera rapporten","få en kopia","dela rapporten"}},{q="Vem är Zilzibin Drumlore?",a="Zilzibin Drumlore är en trollärd i Orgrimmar som studerar Azeroths livsformer och historia.",al={"vem är zil","zilzibins bakgrund","trollärd"}},{q="Vilka varelser beskrivs i rapporten?",a="Zilzibin identifierar varelserna i rapporten som silithider, som hotar Tanaris och både Horde och Alliance.",al={"vilka insekter","silithidrapport","vad är det för kryp"}}},fp="22,163,22.232.0,23.264.1,35.89.0,21.87.0,34.93.0,25.95.0,40.116.0"}
P.entries["item:intact-raptor-horn"] = {n="Intact Raptor Horn",s="På The Barrens savanner jagas rovfåglar för sina hela horn. Mebok Mizzyrix från Ratchet vill ha dem till en plan som bygger på rykten om rovfåglarnas intelligens.",h="På The Barrens savanner jagas rovfåglar för sina hela horn.",kw={"helt horn","ishamuhale","mebok mizzyrix","raptorhorn","ratchet","smartdrycker","sunscale scytheclaw","takk the leaper"},ang={["class:Hunter"]="Som jägare behöver du fälla några av savannens våldsammaste rovdjur rent för att kunna ta ett trofé horn helt.",["profession:Cooking"]="Som kock kanske du hör att Mebok tänker finmala hornen för att smaksätta vin. Praktiska överlevare föredrar att använda rovfågeldelar till verktyg framför att laga något aptitligt."},sec={{t="En tvivelaktig ingrediens",b="Jägare värdesätter rovfåglarnas hudar, klor och troféer, men hela horn är svårare att ta till vara ute i fält. Mebok Mizzyrix, en excentrisk goblinalkemist i Ratchet, tror att rovfåglarna i The Barrens är listigare än sina släktingar på andra håll. Han misstänker att deras intelligens sitter i hornen. Genom att mala hela horn och brygga dem till tonika hoppas Mebok kunna fånga det påstådda geniet i drycker som går att sälja."},{t="På jakt efter flockarna",b="Ett horn som duger till bryggning måste komma från ett särskilt våldsamt rovdjur, inte vilken ung rovfågel som helst. Sunscale Scytheclaws stryker omkring på de södra slätterna och vid de norra gränserna nära Ashenvale. Takk the Leaper och den svårfångade Ishamuhale är ökända fasor på savannen, och deras kraftiga horn kan klara jaktens sammandrabbningar hela."}},faq={{q="Vem vill ha hela raptorhorn?",a="Mebok Mizzyrix, en handelsman och blivande bryggare av goblinsläkt i Ratchet, söker hela horn. Han tror att de är nyckeln till hans nästa produkt som ska göra honom rik snabbt.",al={"vem behöver raptorhorn","hornköpare","vem köper raptorhorn"}},{q="Varför måste hornen vara hela?",a="Mebok tänker mala hela horn till ett fint pulver som kan förtäras. Jägare kastar bort naggade eller trasiga horn, eller anser dem förbrukade, eftersom de saknar den fulla verkan han hoppas kunna utnyttja i sina recept.",al={"varför hela","krossade horn"}},{q="Vilka raptorer bär på dem?",a="Fullvuxna Sunscale Scytheclaws bär dem i Barrens nordligaste och sydligaste trakter. Även ökända, unika rovfåglar, däribland Ishamuhale och Takk the Leaper, har sådana horn.",al={"var hittar man horn","vilka raptorer","vilka raptorer släpper hela horn"}},{q="Gör raptorhorn dig verkligen smartare?",a="Rovfåglarna i The Barrens uppvisar ovanlig flocklist och samordning, men ingen har bevisat att deras intelligens sitter i hornen eller kan överföras till någon genom en dryck.",al={"fungerar smartdrycker","är raptorer smarta","raptorers intelligens"}}},fx={["41f89fc5"]={q="Vad är en Intact Raptor Horn?",a="En Intact Raptor Horn är ett oskadat horn från en skalle, taget från de rovdjursraptorer som stryker omkring i The Barrens. Företagsamma ortsbor värdesätter hornen och tror att deras orörda skick bevarar bestarnas naturliga väsen och list.",al={"vad är intact raptor horn","vad är ett raptorhorn"}},b3ef4089={q="Var kommer intact raptor horns ifrån?",a="Hornen växer naturligt på huvudet av raptorer i The Barrens, särskilt sunscale scytheclaws och ökända bestar som Ishamuhale och Takk the Leaper. De är jakttroféer som tas direkt från döda raptorer ute på savannen.",al={"varifrån kommer raptorhorn","vem släpper intact raptor horn"}}},fp="18,157,25.376.0,19.322.0,36.152.0,35.210.0,25.168.0,42.162.0"}
P.entries["item:intrepid-strongbox-key"] = {n="Intrepid Strongbox Key",s="Intrepid Strongbox Key är en rostig järnnyckel som kapten Halyndor en gång vaktade svartsjukt. Han var befälhavare på Alliance-fartyget Intrepid, som gick under. Även i döden håller kaptenen fast vid den och håller den förbannade artefakten inlåst. Den fördärvade hans besättning utanför Wetlands kust.",h="Intrepid Strongbox Key är en rostig järnnyckel som kapten Halyndor en gång vaktade svartsjukt.",kw={"kapten halyndor","förbannad besättning","glorin steelbrow","intrepid","skeppsvrak","kassaskrin","tredje flottan","wetlands"},ang={["class:Priest"]="Nyckeln öppnar en artefakt fylld av motbjudande nekrotisk energi. Menethils präst Glorin Steelbrow måste utföra de heliga riterna för att rena den och ge besättningens själar ro.",["faction:Alliance"]="Nyckeln tillhörde en befälhavare i Alliance tredje flotta. Den tragiska förlusten utanför Menethil Harbors kust är fortfarande ett öppet sår för hamnens överlevande."},sec={{t="En kaptens hemlighet",b="När Tredje flottan gick under utanför Wetlands stormiga kust förliste krigsfartyget Intrepid, och besättningen förvandlades till rastlösa, förbannade andar. Kapten Halyndor höll tvångsmässigt vakt över ett mystiskt föremål som förvarades i fartygets tunga kassaskrin. Även efter sin död stryker hans vålnad omkring på det vattenfyllda däcket och vägrar släppa den rostiga nyckeln som öppnar lastrummets mörkaste vrå."},{t="Bryta förbannelsen",b="Att ta nyckeln från kapten Halyndor är det enda sättet att öppna Intrepids låsta kassaskrin och hämta den förbannade relik som binder besättningen vid deras plåga. Först när du hämtat föremålet med nyckeln kan du lämna det till dvärgprästen Glorin Steelbrow i Menethil Harbor för rening."}},faq={{q="Vem har Intrepid Strongbox Key?",a="Nyckeln finns hos kapten Halyndor, den vålnadslika befälhavaren som vandrar på övre däcket av det nordliga skeppsvraket utanför Wetlands nordvästra kust.",al={"vem har nyckeln","var får man intrepid key","halyndors nyckel"}},{q="Vad öppnar Intrepid Strongbox Key?",a="Den öppnar Intrepids låsta kassaskrin, som ligger nedsänkt i det splittrade skrovet på det sjunkna skeppet under kaptenens däck.",al={"vad öppnar den","intrepids kassaskrin plats","var finns kistan"}},{q="Varför hölls kassaskrinet låst?",a="Kapten Halyndor låste in ett mörkt, förbannat föremål i kistan för att hålla det dolt och säkert. När flottan sjönk band föremålets kvardröjande ondska besättningen till odödlighet.",al={"vad fanns i kistan","varför var den låst"}},{q="Vem kan rena det förbannade föremålet i kistan?",a="Glorin Steelbrow, en dvärgpräst bosatt i Menethil Harbor, har de heliga kunskaper som krävs för att rena den förbannade artefakten när kistan väl är upplåst.",al={"vem renar den","glorin steelbrow kista"}}},fx={b4277111={q="Vad är Intrepid Strongbox Key?",a="Det är en rostig skeppsnyckel som Captain Halyndor förvarar ombord på det förlista skeppet Intrepid. Även efter sin död vaktar den förbannade kaptenen nyckeln svartsjukt, för det är det enda sättet att låsa upp skeppets förstärkta kassaskrin, gömt i det sönderslagna skrovet.",al={"intrepid strongbox key","vad är nyckeln","intrepid-nyckeln"}},["90ec2e74"]={q="Varför behövs Intrepid Strongbox Key?",a="Nyckeln behövs för att öppna Intrepids kassaskrin och hämta den mörka relik som är inlåst där. First Mate Fitzsimmons tror att artefakten som förvarades där orsakade den fruktansvärda förbannelse som binder Halyndor och hans besättning till vraket. Att öppna skrinet är första steget mot att häva den.",al={"varför behöver jag nyckeln","varför skaffa nyckeln","intrepid-nyckelns syfte"}}},fp="22,188,18.260.0,17.194.1,39.122.0,42.110.0,34.154.0,49.114.0"}
P.entries["item:invisibility-liquor"] = {n="Invisibility Liquor",s="Invisibility Liquor låter Maybell Maclure undkomma familjens blickar och träffa Tommy Joe Stonefield. Deras familjer är fast i en fejd.",h="Invisibility Liquor låter Maybell Maclure undkomma familjens blickar och träffa Tommy Joe Stonefield.",kw={"crystal kelp","elwynn forest","invisibility liquor","maybell maclure","stonefield-fejden","flykten","tommy joe stonefield"},ang={["class:Mage"]="Som magiker vet du att Kirin Tors arkanister ägnar år åt att bemästra illusioner och osynlighetsbesvärjelser. Invånarna i Elwynn gör en grov imitation med jästa spritdrycker och vattendränkt kelp.",["race:Human"]="Som människa vet du att fejden mellan Stonefield- och Maclure-klanerna på landsbygden når bittra ytterligheter."},sec={{t="En dryck för olyckligt förälskade",b="Tommy Joe Stonefield vill träffa Maybell Maclure i lugn och ro, men familjernas fejd håller hushållen åtskilda. Släktingarna håller noga uppsikt, och vanlig hemlighetsmakeri räcker inte. Invisibility Liquor låter den som dricker passera osedd över den omstridda jordbruksmarken."},{t="Okonventionell alkemi i Elwynn",b="Crystal Kelp Fronds från vatten där murlocs håller till ingår i brygden. När Maybell Maclure dricker den försvinner hon ur sikte och smiter in i skogen för ett hemligt möte."}},faq={{q="Vad gör Invisibility Liquor?",a="Invisibility Liquor är en alkoholhaltig dryck med magi som gör den som dricker osynlig en kort stund.",al={"dryckens effekter","osynlighetsbrygd","vad gör den"}},{q="Vem använder Invisibility Liquor?",a="Maybell Maclure får Invisibility Liquor så att hon kan komma undan familjens blickar och träffa Tommy Joe Stonefield, trots fejden mellan deras hushåll.",al={"vem dricker den","maybell maclures dryck"}},{q="Hur tillverkas drycken?",a="Drycken bryggs med Crystal Kelp Fronds som samlas från flodbäddar och sjöstränder i Elwynn Forest, där murlocs hamstrar växterna.",al={"dryckens ingredienser","crystal kelp-dryck"}},{q="Kan spelare dricka Invisibility Liquor själva?",a="Nej. Invisibility Liquor ska levereras till Maybell Maclure så att hon kan smita undan sin familj.",al={"kan jag dricka den","dricka invisibility liquor"}}},fx={["19edabb3"]={q="Vad är Invisibility Liquor?",a="Invisibility Liquor är en kraftfull alkemisk brygd som tillverkas i Elwynn Forest. Den framstår som en alkoholhaltig dryck, men har magiska egenskaper från kristallalgsblad som tillfälligt gör den som dricker den helt osynlig för dödliga ögon.",al={"vad är invisibility liquor","invisibility liquor i berättelsen","vad är invisibility liquor för slags dryck"}},f0e7bc08={q="Varför vill någon ha Invisibility Liquor?",a="Drycken ska hjälpa till att lösa en förbjuden kärlekshistoria. Maybell Maclure och Tommy Joe Stonefield står på varsin sida i sina familjers bittra fejd i Elwynn. Brygden låter Maybell smita förbi sin vaksamma släkt utan att synas och besöka den hon älskar.",al={"varför behövs invisibility liquor","vem vill ha invisibility liquor","varför vill de ha drycken"}}},fp="19,148,32.249.0,25.180.1,33.110.0,33.143.0,23.120.0,53.91.0"}
P.entries["item:iron-pike"] = {n="Iron Pike",s="Iron Pikes är robusta byggmaterial som ursprungligen skickades från Stormwind för att hjälpa till att reparera bron över Everstill i Lakeshire. Redridge-gnoller överföll och plundrade sändningen, vilket gjorde att staden fick brist på viktiga byggvaror.",h="Iron Pikes är robusta byggmaterial som ursprungligen skickades från Stormwind för att hjälpa till att...",kw={"bron över everstill","foreman oslow","iron pike","iron rivet","lakeshire","redridge-gnoller","redridge mountains"},ang={["faction:Alliance"]="Att återta stulna byggvaror från vilda gnoller bidrar till att säkra Lakeshires viktiga övergångar och hålla Stormwinds östra gräns befäst mot Blackrock-aggression.",["profession:Blacksmithing"]="Dessa tunga konstruktionspålar visar hur hårt de lokala smederna pressats, då hela deras förråd av råjärn behövde användas till krigsvapen."},sec={{t="Stulen last från karavanen",b="När Lakeshire nyligen utsattes för attacker från Blackrock-orcherna smältes stadens metallförråd ner för att smida rustningar, klingor och ammunition till försvaret. På grund av bristen bad de lokala byggarna om en ny järnleverans från Stormwind City. Innan materialet hann fram till staden kapade ett gäng Redridge-gnoller transportkaravanen längs vägen. Gnollerna släpade lådor med Iron Pikes och nitar norrut in bland kullarna, vilket stoppade viktiga reparationer av bron över Everstill."},{t="Återuppbyggnad av spannet",b="Foreman Oslow, som ansvarar för återuppbyggnaden av bron över Everstill, förlitar sig på äventyrare som tar sig in i gnollernas område och återtar det stulna byggmaterialet. Utan dessa tunga Iron Pikes för att förstärka sten- och träkonstruktionen är Lakeshire fortfarande delvis avskuret från den norra landsvägen och sårbart för nya angrepp."}},faq={{q="Varför bär gnollerna på Iron Pikes?",a="Gnollerna överföll en försörjningskaravan på väg från Stormwind till Lakeshire. De skingrades i Redridge-kullarna med lådor fulla av stulet byggmaterial, bland annat Iron Pikes och nitar.",al={"varför har gnoller iron pikes","var fick gnollerna tag på iron pikes"}},{q="Vem behöver Iron Pikes i Lakeshire?",a="Foreman Oslow behöver dem för att återuppbygga bron över Everstill, som förbinder Lakeshire över Lake Everstill. Staden har ont om järn efter att ha smält ner sina lokala förråd för att smida vapen och rustningar under de senaste orchattackerna.",al={"vem vill ha iron pikes","foreman oslow iron pikes"}},{q="Var kan Iron Pikes återtas?",a="De finns hos Redridge-gnollerna som slagit läger bland kullarna och höjdryggarna norr om Lakeshire.",al={"var hittar man iron pikes","iron pike plats"}},{q="Varför kunde Lakeshire inte bara smida egna Iron Pikes?",a="Lakeshire tömde sina lokala järnförråd i striderna mot Blackrock-orcherna och smälte ner varenda metallbit till svärd, kulor och skyddsutrustning. De tvingades be Stormwind om nytt konstruktionsjärn.",al={"varför beställde lakeshire järn","järnbrist i lakeshire"}}},fx={c6b2b586={q="Vad är en Iron Pike?",a="En Iron Pike är en tung järnpåle som används för att förstärka murverk och stenbyggen. Foreman Oslow och hans arbetslag behöver de stadiga byggpålarna för att reparera och stabilisera Lakeshires förstörda Everstill Bridge.",al={"vad är iron pike","vad är iron pikes","iron pike i redridge"}}},fp="9,162,20.307.0,19.266.0,47.197.0,40.193.0,40.89.0,55.180.0"}
P.entries["item:iron-pommel"] = {n="Iron Pommel",s="Iron Pommel är den sista saknade delen av Dartol's Rod, en stav skapad av den sedan länge döde magikern Dartol. Nattalverna i Astranaar söker den för att hejda furbolgernas angrepp på deras folk. Den anförtroddes åt druiderna i The Dor'Danil Barrow Den för att förvaras säkert, men gick förlorad när deras fristad skövlades och översvämmades av slemvarelser.",h="Iron Pommel är den sista saknade delen av Dartol's Rod, en stav skapad av den sedan länge döde magikern...",kw={"ashenvale","dartol's rod","dor'danil","iron pommel","oso's chest","raene's cleansing","shael'dryn"},ang={["class:Druid"]="Pommeln är ett dystert minnesmärke över druiderna i Dor'Danil, vars heliga uppdrag slutade i en massaker vid skogens rand.",["faction:Alliance"]="När du hämtar pommeln fullbordar du ett avgörande steg i arbetet med att säkra Dartol's Rod, ett viktigt redskap för att försvara Ashenvale mot den krypande fördärvelsen."},sec={{t="En slaktad cirkels börda",b="Dartol's Rod delades upp och spreds över Ashenvale för att skydda dess mystiska kraft. Iron Pommel anförtroddes åt nattalvdruiderna som bodde nära vägen söderut mot The Barrens. En tragedi drabbade den avskilda enklaven i The Dor'Danil Barrow Den när cirkeln massakrerades och deras fridfulla tillflykt föll i förödande tystnad. Pommeln försvann i kaoset och svaldes av de groteska, bubblande slemvarelser som nu stapplar fram genom den vanhelgade gläntan."},{t="Återfunnen i träsket",b="När druiderna är döda måste du genomsöka den förgiftade hålan söder om Splintertree Post för att hitta pommeln. Reliken låg inlåst i en stadig kista. Äventyrare som tar sig igenom de fördärvade slemvarelserna hittar den hela kistan inuti en slemvarelses frätande massa och säkrar till sist den sista delen som krävs för att återskapa staven."}},faq={{q="Vad används Iron Pommel till?",a="Iron Pommel är den sista delen som behövs för att sätta ihop Dartol's Rod igen. Om du tar den till Shael'dryn vid månbrunnen kan hon laga den uråldriga artefakten, så att den kan användas för att hejda furbolgernas angrepp på nattalverna i Ashenvale.",al={"vad iron pommel används till","varför behöver jag iron pommel","vad gör iron pommel"}},{q="Vem hade pommeln från början?",a="Den anförtroddes åt nattalvdruiderna som bodde nära vägen mot The Barrens. Tyvärr slaktades cirkeln innan staven kunde sättas ihop igen, och deras tillflykt lämnades i ruiner.",al={"vem vaktade pommeln","vem hade iron pommel","dor'danils druider"}},{q="Var hittar man pommeln?",a="Pommeln ligger inlåst i en kista som finns inuti en av de fördärvade slemvarelserna som vandrar i den förgiftade hålan öster om huvudvägen, söder om Splintertree Post och norr om gränsen till The Barrens.",al={"iron pommels plats","var finns iron pommel","var får jag tag på iron pommel"}},{q="Vem ska jag ta pommeln till?",a="Pommeln måste tas till Shael'dryn, en dryad som sköter månbrunnen öster om Iris Lake. Hon har den rituella kunskap som krävs för att återskapa Dartol's Rod.",al={"lämna in iron pommel","vart ska jag ta iron pommel","vem vill ha pommeln"}}},fx={["9716c2ef"]={q="Vad är Iron Pommel?",a="Iron Pommel är den sista saknade delen som krävs för att återskapa Dartol's Rod, en stav skapad av den sedan länge döde magikern Dartol. Före sitt tragiska fall fick druiderna i The Dor'Danil Barrow Den i uppdrag att vakta den tunga metalldelen. Den försvann bland korruptionen och våldet som svepte genom deras fristad, och hamnade till slut inlåst i en gammal kista ute i vildmarken. Där väntar den på någon som kan återfinna den.",al={"vad är iron pommel","iron pommel i berättelsen","vad är knoppen till dartol's rod till för"}}},fp="11,302,23.366.0,23.246.1,33.213.0,30.169.0,26.199.0,29.136.0"}
P.entries["item:iron-rivet"] = {n="Iron Rivet",s="Iron Rivet är kraftiga byggfästen som tillverkas i Stormwind för att hjälpa till att återuppbygga den förstörda bron över Everstill i Lakeshire. Efter att en försörjningskaravan överfölls och plundrades av Redridge-gnoller hamnade dessa tunga metalldelar utspridda i gnollernas läger i de norra kullarna.",h="Iron Rivet är kraftiga byggfästen som tillverkas i Stormwind för att hjälpa till att återuppbygga den...",kw={"bron över everstill","foreman oslow","iron pike","iron rivet","lakeshire","redridge-gnoller","redridge mountains"},ang={["faction:Alliance"]="Att återta dessa stulna förnödenheter hjälper Lakeshires lokala infrastruktur och hejdar samtidigt det tilltagande gnollhotet mot staden.",["profession:Blacksmithing"]="Dessa kraftiga fästen visar prov på Stormwinds vanliga smideskonst och har smitts särskilt för att förankra stora byggnadsverk som sten- och träbroar."},sec={{t="Stulen karavanlast",b="När Lakeshire utsattes för upprepade angrepp från Blackrock-orcherna tvingades stadsrådet smälta ned stadens järnreserver för att smida vapen, rustningar och ammunition i all hast. När den akuta krisen var över bad Foreman Oslow Stormwind om nya byggmaterial för att laga den skadade bron över Everstill. Försörjningskaravanen som fraktade lasten överfölls dock av lokala Redridge-gnoller innan den nådde staden. Lastdjuren och vagnarna släpades upp i kullarna norr om Lake Everstill, och viktiga byggmaterial som järnnitar och pikar skingrades bland gnollflockarna."},{t="Laga bron",b="Utan dessa kraftiga järnnitar kan arbetet med att reparera bron över Everstill inte utföras säkert. Sten- och träkonstruktionen som sträcker sig över sjön behöver förstärkta metallfästen för att tåla tyngden från vagnar och resande. Det är avgörande att återta nitarna direkt från gnollernas läger för att återställa Lakeshires viktiga förbindelse med de västra dalarna och skydda stadens utkanter mot fler intrång."}},faq={{q="Vad används Iron Rivet till?",a="Det är kraftiga byggfästen som Foreman Oslow behöver för att reparera den skadade bron över Everstill i Lakeshire, vars ursprungliga järn förlorades under striderna mot Blackrock-orcherna.",al={"vad järnnitar används till","varför järnnitar behövs","vad järnnitar är till för"}},{q="Varför har gnollerna nitarna?",a="En försörjningskaravan som skickats från Stormwind kapades av Redridge-gnollerna längs vägen. Asätarna kom över bygglasten och tog med sig nitarna och järnpikarna till sina läger norr om Lakeshire.",al={"varför gnoller har nitar","hur gnoller fick järnnitar","vem som stal nitarna"}},{q="Varför hade Lakeshire brist på järn från början?",a="Under en nylig orchinvasion tvingades Lakeshires försvarare smälta ned alla sina lagrade järnförråd till svärd, kulor och rustningar för att överleva belägringen.",al={"järnbrist i lakeshire","varför det saknas järn i lakeshire"}},{q="Vem letar efter nitarna?",a="Foreman Oslow, byggmästaren som leder återställandet av bron över Everstill vid Lakeshires strand.",al={"vem som vill ha järnnitar","vem som hämtar järnnitar"}}},fx={["0d91405a"]={q="Vad är en Iron Rivet?",a="En Iron Rivet är ett kraftigt metallfäste smitt för tungt byggnadsarbete i kungariket. Stormwind skickade en last med sådana nitar till Lakeshire för att hjälpa till att återuppbygga stadens förstörda infrastruktur, särskilt den viktiga Everstill Bridge.",al={"vad är iron rivet","vad är iron rivets","beskrivning av iron rivet"}},a8a8e120={q="Varifrån kommer Iron Rivets, och vem tillverkade dem?",a="Nitarna skickades från Stormwind som en del av en hjälpkonvoj med råmaterial och byggvaror till Redridge. Innan konvojen nådde Lakeshire överfölls och plundrades den av gnoller från Redridge, som spred järnmaterialet runt sina läger på bergssluttningarna.",al={"varifrån kommer iron rivets","vem tillverkade iron rivets","iron rivets ursprung"}}},fp="10,141,20.378.0,18.284.0,30.169.0,36.153.0,46.111.0,32.90.0"}
P.entries["item:iron-shaft"] = {n="Iron Shaft",s="Iron Shaft är en metalldel av Dartol's Rod, en relik som Raene Wolfrunners vän Teronis sökte efter i hopp om att hejda furbolgernas angrepp på Ashenvale. Den återfanns i en låst kista nära gränsen till Felwood och är en viktig del när reliken återställs åt Ashenvales försvarare.",h="Iron Shaft är en metalldel av Dartol's Rod, en relik som Raene Wolfrunners vän Teronis sökte efter i hopp om...",kw={"ashenvale","crazed ancient","dartol's rod","felwood","iron shaft","raenes rening","shael'dryn","withered ancient","wooden key"},ang={["class:Druid"]="Att sätta ihop Dartol's Rod igen handlar nära om druiderna som vårdare av skogen, och om att använda bortglömda redskap för att hela sargade marker.",["race:NightElf"]="Att återta Iron Shaft är en sorgsen plikt, eftersom du måste fälla älskade skogstreants som fallit offer för den demoniska smitta som sipprar ut från Felwood."},sec={{t="En del av Dartol's Rod",b="Dartol's Rod skapades av Dartol, och dess delar spreds över Ashenvale. En del lämnades till och med hos druiderna i Dor'Danil för säker förvaring. Iron Shaft utgör instrumentets stadiga metallkärna, undangömd i en låst kista i en avskild glänta nära Ashenvales norra gräns, inte långt från det fördärvade Felwood."},{t="Skogens fördärv",b="För att få tag på Iron Shaft måste du hämta dess nyckel från de lokala treants som en gång vårdade skogen. Den demoniska korruptionen kryper söderut från Felwood, och uråldriga väktare som Crazed och Withered Ancients har blivit vansinniga. Dryaden Shael'dryn ber resande att hämta skaftet, så att staven kan smidas samman på nytt och den fallne Teronis uppdrag slutföras."}},faq={{q="Vad används Iron Shaft till?",a="Iron Shaft är en del av Dartol's Rod, en trasig relik. Den samlas in så att dryaden Shael'dryn kan hjälpa till att sätta ihop staven igen och slutföra Teronis uppdrag. Han sökte efter den för att hejda furbolgernas angrepp på Ashenvale.",al={"iron shaft användning","vad är det här skaftet","varför behöver jag iron shaft"}},{q="Var hittar man Iron Shaft?",a="Den ligger låst i en kista i en stillsam glänta väster om vägen mot Felwood, i norra Ashenvale.",al={"iron shaft plats","hitta iron shaft","var finns kistan"}},{q="Hur öppnar du kistan med skaftet?",a="Kistan kräver en Wooden Key. Nyckeln bärs av de fördärvade treantsen, Crazed och Withered Ancients, som strövar omkring i skogen nordost om Raynewood Retreat.",al={"hur öppnar man kistan","kistnyckel","iron shaft nyckel"}},{q="Vem letar efter Iron Shaft?",a="Shael'dryn, en dryad vid en månskensbrunn mitt i Ashenvale, skickar äventyrare att samla ihop Dartol's Rods delar som en del av arbetet med att rena skogen.",al={"vem vill ha iron shaft","uppdragsgivare för iron shaft"}}},fx={ad78a81b={q="Vad är Iron Shaft?",a="Iron Shaft är en viktig del av Dartol's Rod, en relik skapad av Dartol. Stavens delar spreds över Ashenvale. Den här delen hamnade inlåst i en gömd kista nära gränsen till Felwood, och dess nyckel bars av de korrumperade treantsen i närheten.",al={"vad är iron shaft","föremålet iron shaft","dartol rod iron shaft"}},["45340e91"]={q="Varifrån kommer Iron Shaft, och vem tillverkade den?",a="Den smiddes som en del av en magisk stav skapad av Dartol. Stavens delar spreds senare, och just detta skaft låstes in i en sliten kista gömd i en glänta nära Felwood. De korrumperade treants som har nyckeln vaktar den indirekt.",al={"vem tillverkade iron shaft","iron shaft ursprung","dartol iron shaft"}},["3705c59d"]={q="Varför vill man ha Iron Shaft?",a="Raene Wolfrunner och Shael'dryn vill sätta ihop Dartol's Rod igen. Teronis trodde att staven kunde hejda furbolgernas angrepp på Ashenvales nattalver. För att återskapa reliken måste de samla dess saknade delar. Det stadiga järnskaftet utgör stavens centrala handtag och kärna, som håller ihop den magiska ädelstenen och knoppen.",al={"varför vill de ha iron shaft","varför samla iron shaft","syftet med iron shaft-uppdraget"}}},fp="10,146,23.242.0,19.262.1,32.190.0,30.104.0,47.138.0,34.139.0"}
P.entries["item:ironband-s-progress-report"] = {n="Ironband's Progress Report",s="Ironband's Progress Report är en skriftlig rapport om problemen vid Prospector Ironband's utgrävningsplats i östra Loch Modan. Den berättar om långsamma utgrävningar som hindras av aggressiva troggs och innehåller en brådskande vädjan om mer sprängkrut.",h="Ironband's Progress Report är en skriftlig rapport om problemen vid Prospector Ironband's utgrävningsplats i...",kw={"sprängkrut","explorers league","ironband","jern hornhelm","loch modan","prospector stormpike","thelsamar","troggs"},ang={["profession:Mining"]="Gruvarbetare vet alltför väl hur nödvändigt sprängkrut är när man röjer envisa klippformationer – och hur farligt det är när förråden försvinner i troggterritorium.",["race:Dwarf"]="För dvärgiska upptäcktsresande och gruvarbetare visar rapporten hur farligt det är att gräva ut forntida titanplatser i hjärtat av Khaz Modan."},sec={{t="En vädjan om krut",b="Prospector Ironband's utgrävning i Loch Modan störs ständigt av lokala troggs. För att hålla projektet igång sammanställde Ironband den här lägesrapporten och upprepade sitt desperata behov av sprängkrut. Rapporten bars först till Jern Hornhelm i Thelsamar och skickades sedan vidare till Explorers' League i Ironforge. Den beskriver hur arbetet på plats står stilla och begär tung ammunition. Rapporten väcker snabbt frågor bland ledarna för ligan, eftersom en riklig mängd sprängkrut skickades till Ironband flera veckor tidigare. Hans överordnade undrar därför vart de tidigare leveranserna tog vägen."}},faq={{q="Vad är Ironband's Progress Report?",a="Det är en officiell fältrapport från Prospector Ironband om läget vid hans utgrävningsplats i Loch Modan. Den lyfter särskilt fram störningarna från troggs och kräver mer sprängkrut.",al={"lägesrapport","ironbands rapport","vad är rapporten"}},{q="Vem tar emot rapporten?",a="Rapporten lämnas först till Jern Hornhelm, utgrävningens lokala kontaktperson i Thelsamar. Hornhelm ber sedan budbäraren att lämna den direkt till Prospector Stormpike vid Explorers' Leagues högkvarter i Ironforge.",al={"vem får rapporten","vem ska jag ge rapporten till","lämna lägesrapport"}},{q="Varför behöver Ironband mer sprängkrut?",a="Ironband hävdar att han behöver krutet för att underlätta sina arkeologiska utgrävningar, men de ständiga räderna från närliggande troggs tyder på att han också kan behöva sprängämnen för att försvara sig. Märkligt nog anser både Hornhelm och Stormpike att de skickade honom gott om sprängkrut flera veckor tidigare.",al={"varför sprängkrut","vad hände med krutet","krutbrist"}},{q="Hur reagerar Prospector Stormpike på rapporten?",a="Stormpike är rasande över de långsamma framstegen och förbryllad över att Ironband inte nämner den stora leveransen av sprängkrut som skickades tidigare. Han undrar vart den saknade ammunitionen kan ha tagit vägen.",al={"stormpikes reaktion","är stormpike arg"}}},fx={["9e6c80e6"]={q="Varifrån kommer Ironband's Progress Report, och vem skrev den?",a="Prospector Ironband skriver dokumentet själv på sin utgrävningsplats i östra Loch Modan. Han leder det mödosamma grävarbetet trots ständiga trakasserier från troggar. Rapporten ger en formell lägesbild av hur långsamt arbetet går och dokumenterar hans löpande materialbeställningar.",al={"vem skrev ironbands progress report","vem skrev ironbands rapport","varifrån kommer ironbands rapport"}},["2cf6b481"]={q="Varför vill någon ha Ironband's Progress Report?",a="Rapporten är viktig dokumentation som administrativa kontakter i Thelsamar och Explorers' League-högkvarteret i Ironforge kräver. Utan den officiella redogörelsen för platsens svårigheter och troggarnas inblandning kommer överordnade som Prospector Stormpike inte att godkänna att nya leveranser av sprängpulver skickas ut.",al={"varför behövs ironbands progress report","varför ta ironbands rapport","syftet med ironband's progress report"}}},fp="26,178,20.281.0,35.116.0,25.137.0,40.185.0,50.191.0"}
P.entries["item:ironfur-liver"] = {n="Ironfur Liver",s="Ironfur Liver kommer från Ironfur-björnar i Feralas. Rhapsody Shindigger behöver den till en drink som han hoppas ska få honom att lätta på tungan om ett träskäventyr.",h="Ironfur Liver kommer från Ironfur-björnar i Feralas.",kw={"feralas","groddoc liver","ironfur-björn","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},sec={{t="En starkare drink",b="Rhapsody Shindigger i The Hinterlands ber dig hämta tre Ironfur Livers till hans Kalimdor Kocktail. Han blandar dem med Groddoc Livers från Feralas och Roc Gizzards från Tanaris. Drycken ska, säger han, hjälpa honom att berätta om sin flygtur över träsket."}},faq={{q="Var kommer Ironfur Livers från?",a="Ironfur Livers kommer från Ironfur-björnar i Feralas.",al={"källa till ironfur liver","var hittar man lever"}},{q="Vem vill ha Ironfur Liver?",a="Rhapsody Shindigger i The Hinterlands vill ha tre Ironfur Livers till sin Kalimdor Kocktail.",al={"vem behöver den","rhapsody lever"}},{q="Varför behöver Rhapsody dessa levrar?",a="Rhapsody behöver Ironfur Livers, Groddoc Livers och Roc Gizzards för att göra en stark Kalimdor Kocktail. Han hoppas att drycken ska hjälpa honom att berätta om sitt träskäventyr.",al={"varför lever","vad är drinken till för"}},{q="Vad mer ingår i Kalimdor Kocktail?",a="Kalimdor Kocktail kräver också Groddoc Livers från Feralas och Roc Gizzards från Tanaris.",al={"drinkens ingredienser","andra organ"}}},fp="13,148,16.252.0,34.50.0,24.92.0,36.164.0,42.95.0"}
P.entries["item:ishamuhale-s-fang"] = {n="Ishamuhale's Fang",s="I Camp Taurajo väntar Jorn Skyseer på Ishamuhale's Fang från den fruktade solfjällsraptorn Speartooth i The Barrens. Tanden visar att jägaren besegrat ett av Kalimdors farligaste rovdjur.",h="I Camp Taurajo väntar Jorn Skyseer på Ishamuhale's Fang från den fruktade solfjällsraptorn Speartooth i The...",kw={"barrens","huggtand","ishamuhale","jorn","raptor","sergra","speartooth","sunscale","taurajo"},ang={["class:Hunter"]="Som jägare genomgår du en övergångsrit genom att ta Speartooth's Fang i The Barrens. Den prövar din förmåga att locka fram, möta och besegra ett listigt rovdjur.",["race:Tauren"]="Som tauren innebär det att göra anspråk på tanden att ta in ett rovdjurs råa kraft och samtidigt bevara disciplin och balans."},sec={{t="Speartooths trofé",b="Över den centrala savannen fruktar jägarna Ishamuhale, den vildaste levande solfjällsraptorn. Vissa säger att toppjägaren dödar av rovdjurslust, inte hunger. Färskt zhevrakött lockar besten fram i det öppna vid ett vissnat träd nordväst om Ratchet, där den inte visar någon nåd. Att ta dess väldiga huggtand visar Hordens jaktinstruktörer att en resenär har övervunnit slätternas vildhet."},{t="En lektion i måttfullhet",b="I Camp Taurajo ser Jorn Skyseer mer än elfenben och blod i Ishamuhale's Fang. För tauren där innebär det att ta den att jägarens styrka växer av rovdjurets våldsamma kraft. Nästa prov gäller självbehärskning: jägaren måste bemästra ursinnet i stället för att låta det styra själen."}},faq={{q="Vad är Ishamuhale's Fang?",a="Ishamuhale's Fang är en trofé från Ishamuhale, den beryktade solfjällsraptorn Speartooth som stryker omkring i The Barrens.",al={"ishamuhales tand","speartooths huggtand","raptorhuggtand i barrens"}},{q="Vem vill ha Ishamuhale's Fang?",a="Jorn Skyseer i Camp Taurajo vill ha huggtanden som del av jaktproven, som börjar med Sergra Darkthorn vid The Crossroads.",al={"vem lämnar jag ishamuhales huggtand till","lämna in ishamuhales huggtand","vart ska ishamuhales huggtand"}},{q="Hur hittar man odjuret Ishamuhale?",a="Ishamuhale lockas fram ur sitt gömställe med ett färskt zhevralik nära ett dött träd nordväst om Ratchet.",al={"hur får man ishamuhale att dyka upp","kalla fram ishamuhale","var finns ishamuhale"}},{q="Vad innebär det för tauren att ta huggtanden?",a="För tauren innebär det att göra anspråk på Ishamuhale's Fang att jägarens inre nu rymmer raptorens legendariska styrka, som måste brukas med självbehärskning och heder.",al={"huggtandens betydelse","taurens jägarritual ishamuhale"}}},fx={aa73e2a3={q="Varifrån kommer Ishamuhale's Fang?",a="Huggtanden tas direkt ur käkarna på Ishamuhale, även kallad Speartooth. Han är den våldsammaste sunscale-raptorn som strövar omkring i The Barrens. Han är ett naturligt rovdjur som dödar enbart på grund av sina vilda instinkter. Den skapades inte av dödliga händer, utan växte naturligt som bestens dödliga vapen.",al={"ishamuhale fang ursprung","varifrån kom ishamuhale fang","vem skapade ishamuhale fang"}}},fp="17,199,20.409.0,22.293.1,26.117.0,28.129.0,34.105.0,52.166.0"}
P.entries["item:ivar-s-head"] = {n="Ivar's Head",s="Ivar's Head är det makabra beviset på att den glupska ghulen Ivar the Foul har dödats i Silverpine Forest. Deathstalkern Rane Yorick vill ha det för att hennes sårade bror Quinn ska kunna återhämta sig tryggt.",h="Ivar's Head är det makabra beviset på att den glupska ghulen Ivar the Foul har dödats i Silverpine Forest.",kw={"deathstalkers","the ivar patch","ivar the foul","ivar's head","quinn yorick","rane yorick","silverpine forest"},ang={["faction:Horde"]="Att utplåna kvarvarande Scourge som Ivar skyddar Horde-kurirer på väg genom norra Silverpine mot The Sepulcher.",["race:Undead"]="För Forsaken-spejare är vilda ghouls tanklösa belastningar som stör militär spaning och hotar Lordaerons spirande säkerhet."},sec={{t="Ett avhugget hot",b="När Forsaken Deathstalkers Rane och Quinn Yorick spanade i norra Silverpine Forest på order av High Executor Hadrec, överfölls de vid en övergiven gård av en vild ghoul vid namn Ivar the Foul. Syskonen lyckades hålla besten stången, men Quinn blev svårt söndersliten i striden. Rane var fast vid den förstörda gården medan hennes bror återhämtade sig, och kunde inte lämna honom ensam på ett säkert sätt för att slutföra uppdraget. Om hon hugger av Ivars huvud får hon ett slutgiltigt bevis på att besten aldrig mer kommer att terrorisera gården, och Quinn får den tid han behöver för att återhämta sig under Ranes vaksamma uppsikt."}},faq={{q="Vems huvud är det här?",a="Huvudet tillhörde Ivar the Foul, en vildsint ghoul som hemsökte den övergivna gården kallad The Ivar Patch i norra Silverpine Forest.",al={"vem är ivar","ivar heads identitet","vad är ivar"}},{q="Varför vill Rane Yorick ha Ivar's Head?",a="Rane behöver fysiska bevis på att Ivar är död. Hennes bror Quinn blev svårt söndersliten av varelsen och behöver tid att läka utan rädsla för ett nytt bakhåll, innan de kan rapportera tillbaka till High Executor Hadrec.",al={"varför rane vill ha huvudet","lämna in ivar's head","varför döda ivar"}},{q="Var hittades Ivar the Foul?",a="Ivar the Foul lurar i den förfallna ladan vid The Ivar Patch och väntar på att de sårade Deathstalkers ska slappna av på sin vakt.",al={"ivars plats","var är ivar"}}},fx={fce823f2={q="Varifrån kommer Ivar's Head?",a="Det avhuggna huvudet tas direkt från liket efter Ivar the Foul, en våldsam ghoul som lurar i den förfallna ladan vid The Ivar Patch i Silverpine Forest. Det är ingen artefakt eller tillverkad sak, utan en fysisk trofé som skurits loss från ett odött monster för att garantera att han verkligen har förintats.",al={"ivar's head ursprung","varifrån kom ivar's head","vem skapade ivar's head"}}},fp="11,174,16.448.0,19.136.0,38.183.0,30.129.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Iverron's Antidote",s="Iverron's Antidote är en känslig medicinalbrygd som Dirania Silvershine tillredde i Shadowglen. Blandningen bryggdes särskilt för att neutralisera det dödliga giftet från traktens Webwood-spindlar och är mycket instabil, så den förstörs snabbt efter tillredningen.",h="Iverron's Antidote är en känslig medicinalbrygd som Dirania Silvershine tillredde i Shadowglen.",kw={"aldrassil","dirania silvershine","iverron","iverron's antidote","shadowglen","spindelgift","teldrassil","webwood-gift"},ang={["profession:Herbalism"]="Brygden visar hur extremt instabila de inhemska reagenserna från Teldrassil är och hur vissa örtmediciner måste intas omedelbart efter bryggningen.",["race:NightElf"]="För unga nattalvsäventyrare som börjar i Shadowglen visar den brådskande leveransen av botemedlet till Iverron hur beroende samhället är av snabba insatser och örtmedicin mot korruptionen som sprider sig bland Teldrassils grenar."},sec={{t="Ett bräckligt botemedel",b="Det här motgiftet tillverkades av Dirania Silvershine i Aldrassil och är avsett att motverka det kraftiga gift som drabbat den unga nattalven Iverron. Eftersom ingredienserna och örtutdragen är flyktiga har brygden en ovanligt kort hållbarhet och är verksam i bara fem minuter efter bryggningen. Budbärare måste genast springa norrut mot Webwood-grottan och leverera brygden innan den förvandlas till oanvändbar sörja."}},faq={{q="Vad används Iverron's Antidote till?",a="Det botar Iverron från det giftiga bett han fick av de närliggande Webwood-spindlarna utanför deras grotta i norra Shadowglen.",al={"motgiftets användning","vad gör iverron's antidote"}},{q="Varför har motgiftet en tidsgräns?",a="Dirania Silvershine säger att brygden är känslig och bara behåller sin verkan i fem minuter efter tillredningen. Om den inte ges snabbt bryts dess läkande egenskaper helt ned.",al={"varför fem minuter","motgiftets tidsgräns","varför går det ut"}},{q="Vem brygger motgiftet?",a="Dirania Silvershine, en nattalvsläkare stationerad i Aldrassil i Shadowglen, brygger drycken med ingredienser som samlats in för att rädda Iverron.",al={"vem gjorde motgiftet","motgiftets tillverkare"}},{q="Vad händer om motgiftet går ut?",a="När tiden är ute förstörs brygden och fungerar inte längre. Budbäraren måste återvända till Dirania Silvershine i Aldrassil för att få en ny sats.",al={"motgiftet har gått ut","tiden tog slut"}}},fx={["59c1ca07"]={q="Vad är Iverron's Antidote?",a="Det är en nybryggd medicinsk dryck, särskilt framtagen för att neutralisera det dödliga giftet från Webwood-spindlarna som lurar bland Teldrassils grenar. Eftersom motgiftet har en känslig blandning av naturliga ingredienser är det mycket instabilt och förstörs snabbt om det inte dricks inom några minuter efter tillredningen.",al={"vad är iverrons antidote","iverron antidote","iverrons motgift"}}},fp="18,204,16.292.0,36.115.0,40.143.0,23.127.0,37.142.0"}
P.entries["item:jade-phial"] = {n="Jade Phial",s="Jade Phial är ett särskilt tillverkat kärl som nattalvdruiden Corithras Moonrage tillhandahåller i Dolanaar. Det är utformat för att säkert hämta och transportera heligt vatten från Teldrassils månbrunnar, så att druidernas centrala brunn i Darnassus kan fyllas på.",h="Jade Phial är ett särskilt tillverkat kärl som nattalvdruiden Corithras Moonrage tillhandahåller i Dolanaar.",kw={"corithras moonrage","crown of the earth","dolanaar","jade phial","månbrunn","starbreeze village","teldrassil"},ang={["class:Druid"]="För unga druider är det en tidig lektion i att ta ansvar att bära Jade Phial. Den visar att Teldrassils månbrunnar kräver ständig vördnad och omsorg för att behålla sin livskraft.",["race:NightElf"]="Månbrunnarna står för det bestående bandet mellan kaldorei och Elune. Att vårda dem med kärl som Jade Phial är en helig plikt för varje nattalv."},sec={{t="Ett kärl för heligt vatten",b="Teldrassil är prickat med månbrunnar som kanaliserar månens och naturens energier, vilka är livsviktiga för nattalvernas samhälle och druidernas dyrkan. För att bevara denna harmoni måste druidernas centrala månbrunn i Darnassus regelbundet fyllas på med vatten från de avlägsna brunnarna längs den väldiga grenen. Corithras Moonrage anförtror unga noviser Jade Phial, ett kärl som noggrant förberetts för att samla rent vatten från månbrunnen nära Starbreeze Village utan att störa dess känsliga andliga kraft."}},faq={{q="Vad används Jade Phial till?",a="Jade Phial används för att samla heligt vatten från månbrunnen strax utanför Starbreeze Village. När kärlet är fyllt ska det återlämnas till Corithras Moonrage i Dolanaar, så att druidernas månbrunn i Darnassus kan fyllas på.",al={"syftet med jade phial","varför behöver jag jade phial","vad gör jade phial"}},{q="Vem tillhandahåller Jade Phial?",a="Corithras Moonrage, en nattalvdruid stationerad i Dolanaar, ger äventyrare kärlet när de utför riten som kallas Crown of the Earth.",al={"vem ger jade phial","var får man tag på jade phial","corithras jade phial"}},{q="Vart tar vattnet från kärlet vägen?",a="Vattnet som samlas i kärlet transporteras för att bevara och fylla på den centrala månbrunn som Cenariondruiderna sköter i huvudstaden Darnassus.",al={"vart tar månbrunnsvattnet vägen","jade phials destination","vem använder vattnet"}}},fx={["8250d8c3"]={q="Vad är Jade Phial?",a="Jade Phial är ett särskilt tillverkat rituellt kärl som Corithras Moonrage har gett dig i Dolanaar. Det är utformat för att säkert rymma och transportera det heliga, välsignade vattnet från Teldrassils månbrunnar utan att störa eller försvaga dess inneboende magiska egenskaper.",al={"jade phial","vad är jade phial"}}},fp="10,185,26.442.0,32.207.0,28.143.0,44.125.0"}
P.entries["item:jennea-s-flask"] = {n="Jennea's Flask",s="I Stormwinds trollkarlshelgedom skickar Jennea Cannon lärlingar till Mirror Lake för att hämta vatten. De tar med provet tillbaka för magisk analys.",h="I Stormwinds trollkarlshelgedom skickar Jennea Cannon lärlingar till Mirror Lake för att hämta vatten.",kw={"elwynn forest","jennea cannon","jennea's flask","mirror lake","stormwind","vattenprov","trollkarlshelgedomen"},ang={["class:Mage"]="Som magiker är det här en av dina första fältuppgifter för trollkarlshelgedomen att bära den här flaskan. Den prövar din förmåga att hantera känslig magisk forskning och hålla utkik efter förändringar i ley-linjerna."},sec={{t="Ett kärl för magisk forskning",b="Efter magiska strider över Azeroth har magiska strömmar slitits loss från sina uråldriga fåror. Jennea Cannon vill ta reda på hur dessa förändringar har påverkat Elwynn Forest. Hon ger lovande lärlingar en glasflaska och skickar dem sydväst om Stormwinds portar, till foten av vattenfallet vid Mirror Lake. Flaskan skyddar vattenprovet på vägen tillbaka till trollkarlshelgedomen, där det kan undersökas för magiska störningar."},{t="Att skydda vattnet",b="Jennea's flaska låter Stormwinds magiker kontrollera om skiftande ley-linjer har förorenat Mirror Lake. Om vattnet bär på skadlig magi kan det omkringliggande livet och alla som dricker det drabbas av märkliga åkommor. Ett prov kan avslöja magiska rester innan förorenade strömmar sprider sig genom landsbygden."}},faq={{q="Vad används Jennea's Flask till?",a="Du använder Jennea's Flask för att samla vatten från vattenfallet vid Mirror Lake i Elwynn Forest.",al={"flaskans syfte","vad gör flaskan","flaskans användning"}},{q="Vem ger dig flaskan?",a="Jennea Cannon, en magitränare i Stormwind Citys trollkarlshelgedom, ger dig flaskan.",al={"vem ger flaskan","varifrån kommer jenneas flaska"}},{q="Varför vill Jennea ha vatten från Mirror Lake?",a="Nyliga mystiska konflikter har stört magins flöde över världen. Jennea befarar att kringirrande strömmar kan sippra in i Elwynns vatten och utsätta alla som dricker från sjön för fara.",al={"varför vatten från mirror lake","varför vattenprov"}},{q="Var fyller du flaskan?",a="Fyll flaskan vid foten av vattenfallet som rinner ut i Mirror Lake, sydväst om Stormwinds huvudportar i Elwynn Forest.",al={"var fyller man flaskan","flaskans plats","sjöns plats"}}},fx={b836f408={q="Vad är Jennea's Flask?",a="Det är en särskild behållare för prover som Jennea Cannon, en instruktör i Mage Quarter i Stormwind, har gett dig. Hon anförtror den åt lovande lärlingar, så att de kan samla vatten direkt från vattenfallet vid Mirror Lake och låta henne undersöka det för magisk förorening.",al={"vad är jennea's flask","jennea's flask"}}},fp="14,138,28.439.0,19.309.0,32.86.0,25.88.0,44.184.0,28.126.0"}
P.entries["item:jer-kai-s-signet-ring"] = {n="Jer'kai's Signet Ring",s="Jer'kai's Signet Ring bär hennes bud från Feralas vildmarker till Tyrande Whisperwind i Darnassus. Det berättar för översteprästinnan att Jer'kai och Kindal mår bra och ger dig erkännande för din hjälp.",h="Jer'kai's Signet Ring bär hennes bud från Feralas vildmarker till Tyrande Whisperwind i Darnassus.",kw={"darnassus","feralas","jer'kai moonweaver","jer'kai's signet ring","kindal","bud","signetring","temple of the moon","tyrande whisperwind"},ang={["race:NightElf"]="Som Night Elf bär du Jer'kais bud till Tyrande Whisperwind, Elunes översteprästinna, vid Temple of the Moon."},sec={{t="Ett bud till Darnassus",b="I Feralas anförtror Jer'kai Moonweaver dig sin signetring efter att du hjälpt henne och Kindal. Hon ber dig ta den till Tyrande Whisperwind vid Temple of the Moon i Darnassus. Ringen berättar att de båda mår bra och ger Tyrande sanningen om din hjälp."},{t="Vid templet",b="Tyrande lyssnar till din berättelse om hur du hjälpte drakfolket och en av hennes prästinnor. Hon lovar att skicka tillbaka Jer'kais ring med spejare på väg mot Feralas. För stunden har ringen nått översteprästinnan med sitt bud."}},faq={{q="Vad ska Jer'kai's Signet Ring användas till?",a="Jer'kai ber dig ta ringen till Tyrande Whisperwind vid Temple of the Moon i Darnassus. Den berättar för Tyrande att Jer'kai och Kindal mår bra och ger dig erkännande för din hjälp.",al={"jerkai ring","signetringens syfte","ring till tyrande"}},{q="Vem gav mig ringen?",a="Jer'kai Moonweaver ger dig sin signetring i Feralas efter att du hjälpt henne och Kindal.",al={"vem gav ringen","jerkai ringens givare","varifrån kommer ringen"}},{q="Vem ska få ringen?",a="Tyrande Whisperwind, översteprästinnan vid Temple of the Moon i Darnassus, ska få ringen.",al={"ringens mottagare","vem får jerkais ring","tyrande ring"}},{q="Vad gör Tyrande med ringen?",a="Tyrande lovar att skicka tillbaka ringen till Jer'kai med spejare på väg mot Feralas.",al={"tyrandes svar","ringen skickas tillbaka","vad händer med ringen"}}},fp="21,197,22.267.0,13.219.0,34.178.0,21.86.0,36.98.0,35.86.1"}
P.entries["item:jeweled-pendant"] = {n="Jeweled Pendant",s="Jeweled Pendant är ett fint arbetat smycke som hittats bland Alliance-soldater nära Theramore. Att vanliga soldater bär det har väckt Hordes uppmärksamhet.",h="Jeweled Pendant är ett fint arbetat smycke som hittats bland Alliance-soldater nära Theramore.",kw={"alliance","horde","jeweled pendant","marg","muckshell","nazeer","smycke","stormwind","theramore","zor lonetree"},ang={["faction:Alliance"]="En soldat från Stormwind sågs bära det här fint arbetade smycket nära Theramore, och dess okända ägare kan vara en adelsman.",["faction:Horde"]="Smycket kan ge Horde en ledtråd om Alliance-adeln. Zor Lonetree studerar dess hantverk och historia."},sec={{t="En soldats byte",b="Nära Theramore såg Marg en soldat från Alliance bära ett hängsmycke med fler ädelstenar än en vanlig soldat hade råd med. Marg stal det från lägret, men en muckshell dödade honom på vägen tillbaka. Smycket återfanns och fördes till Nazeer i Brackenwall Village, där det fina hantverket väckte frågan om vem som egentligen ägde det."},{t="Ett adligt hantverk",b="Zor Lonetree, som är väl insatt i Alliance-politik, studerar nu smycket i Orgrimmar. Han ser skickligheten i hantverket och tror att många människor skulle kunna åtrå en sådan juvel. Ägaren är fortfarande okänd, medan Horde väntar på att få veta vad smycket kan avslöja."}},faq={{q="Vem ägde Jeweled Pendant?",a="Smyckets ägare är okänd. Marg såg det på en soldat från Alliance nära Theramore, men det fina hantverket tyder på att det tillhörde en adelsman.",al={"smyckets ägare","vem bar det","vems juvel"}},{q="Varför stal Marg smycket?",a="Marg såg en soldat från Alliance bära ett smycke täckt av ädelstenar och stal det från lägret nära Theramore.",al={"varför stjäla det","marg smycke","vad tog marg"}},{q="Vad hände med Marg?",a="En muckshell dödade Marg när han återvände till basen med smycket han hade stulit från Alliance-lägret.",al={"margs öde","hur dog marg","margs berättelse"}},{q="Varför bryr sig Horde om smycket?",a="Smycket verkar vara ett adligt hantverk, men bars av en soldat från Alliance nära Theramore. Zor Lonetree studerar det för att hitta ledtrådar till vem som äger det.",al={"horde smycke","varför rapportera till zor","smyckesmysterium"}},{q="Var finns smycket nu?",a="Zor Lonetree studerar Jeweled Pendant i Orgrimmar.",al={"smyckets plats","vart föra juvelen","zor smycke"}}},fp="15,179,19.329.0,16.264.0,30.145.0,31.105.0,22.101.1,42.143.0,25.58.0"}
P.entries["item:jitters-completed-journal"] = {n="Jitters' Completed Journal",s="Jitters' Completed Journal är en handskriven skildring av Duskwoods dystra tragedier, särskilt massakern på Sven Yorgens gård. Av rädsla för hämnd lämnar den tillbakadragne Jitters över den färdiga texten för att rentvå sitt namn och avslöja de onda krafter som hemsöker trakten.",h="Jitters' Completed Journal är en handskriven skildring av Duskwoods dystra tragedier, särskilt massakern på...",kw={"bishop farthing","cathedral of light","mörka ryttare","duskwood","forlorn rowe","jitters","journal","morbent fel","sven yorgen"},ang={["class:Priest"]="När journalen lämnas till Bishop Farthing vid Cathedral of Light får prästerna direkt möjlighet att rena vanhelgande orenhet med heliga reliker.",["faction:Alliance"]="Journalen är en bister påminnelse om hur djupt Duskwood har sjunkit ner i fara medan Stormwinds ledare är upptagna med annat."},sec={{t="En feg mans bekännelse",b="När Svens gård angreps flydde Jitters i skräck och lämnade sin halvfärdiga dagbok bland ruinerna. Den färdiga journalen fyller i luckorna från den hemska dagen och berättar hur mystiska mörka ryttare slaktade Svens familj. I flera veckor var journalen Jitters enda tröst medan han gömde sig i Duskwood. Han lämnar villigt över den färdiga boken, desperat efter att förklara vad som verkligen hände och i hopp om att den nedskrivna sanningen ska skona honom från Svens rasande vrede."},{t="Mörkrets gåta",b="Journalen lindrar inte bara gammal sorg: den får Sven att berätta att han sett de svartklädda ryttarna tala med trollkarlen Morbent Fel vid Forlorn Rowe. Sven skickar det färdiga manuskriptet norrut med resande till Cathedral of Light i Stormwind. Där läser Bishop Farthing Jitters' ord för att förstå den avskyvärda smitta som sprider sig i Duskwood, och använder avslöjandena för att bidra till att skapa ett heligt vapen som kan tränga igenom Fels mörka skydd."}},faq={{q="Varför lämnade Jitters ifrån sig journalen?",a="Jitters flydde från Svens gård under angreppet och lämnade en ofullständig journal efter sig. Han gav äventyrarna den färdiga versionen så att de kunde ta den till Sven, i hopp om att hela sanningen skulle rentvå honom och skydda honom från Svens hetsiga humör.",al={"varför lämnar jitters över journalen","jitters dagbok","varför skrev jitters detta"}},{q="Vad avslöjar journalen om Svens gård?",a="Den innehåller Jitters fullständiga ögonvittnesskildring av tragedin på Sven Yorgens gård och fyller i luckorna från hans ofärdiga journal.",al={"vad hände på svens gård","angreppet på svens familj","mörka ryttare på svens gård"}},{q="Vem är Morbent Fel och hur hänger han ihop med journalen?",a="Morbent Fel är en nekromantiker som bor vid Forlorn Rowe. Journalen får Sven att dela med sig av information som riktar utredningen mot honom.",al={"morbent fels koppling","vem är morbent fel","trollkarl vid forlorn rowe"}},{q="Varför förs journalen till Stormwind?",a="Sven ber äventyrarna ta journalen till Bishop Farthing vid Cathedral of Light. Eftersom Stormwind i stort sett har försummat Darkshires försvar behövs Farthings visdom och heliga kunskap för att förbereda ett vapen som kan tränga igenom Morbent Fels magiska skydd.",al={"varför bishop farthing","ta journalen till cathedral","söker visdom i journalen"}}},fx={["3f8dfebe"]={q="Vad är Jitters' Completed Journal?",a="Det är den fullständiga personliga krönikan som Jitters, en skräckslagen luffare som gömmer sig i Duskwood, förde. Till skillnad från de fragmentariska anteckningarna han lämnade när han flydde från Sven Yorgens gård beskriver detta färdiga manuskript hela följden av tragedier som drabbade gården, skogens annalkande fasor och de illvilliga gestalterna som rör sig i skuggorna.",al={"jitters' completed journal","vad är den här dagboken","jitters dagbok"}},e7121643={q="Var kommer Jitters' Completed Journal ifrån, och vem skrev den?",a="Jitters skrev själv dagboken. Efter att ha flytt från massakern på Svens gård och lämnat kvar en tidigare dagbok tillbringade han veckor i gömställe, där han febrilt skrev ner sina tankar och skildrade de illvilliga krafter som jagade genom Duskwood. Han behöll den färdiga boken som sin enda följeslagare tills han överlämnade den för att slippa möta Sven Yorgens vrede.",al={"vem skrev jitters' completed journal","jitters dagboks ursprung","varifrån kommer dagboken"}},["5c3c5710"]={q="Varför vill man ha Jitters' Completed Journal?",a="Sven Yorgen vill ha dagboken för Jitters ögonvittnesskildring av tragedin på hans gård. Senare studerar Bishop Farthing i Cathedral of Light den för att hjälpa till att förbereda en äventyrare på att möta ondskan som hemsöker Duskwood.",al={"varför vill de ha dagboken","varför är jitters dagbok viktig","vem vill ha dagboken"}}},fp="26,161,21.343.1,23.373.1,36.219.0,47.140.1,58.142.1,38.206.1"}
P.entries["item:johaan-s-findings"] = {n="Johaan's Findings",s="Johaan's Findings är en samling forskningsdokument skrivna av Apothecary Johaan i Brill. Anteckningarna skickas med en kurir söderut till Apothecary Renferrel vid The Sepulcher och förmedlar de senaste alkemiska framstegen i Tirisfal Glades.",h="Johaan's Findings är en samling forskningsdokument skrivna av Apothecary Johaan i Brill.",kw={"apothecary johaan","apothecary renferrel","brill","johaan","johaan's findings","the new plague","royal apothecary society","the sepulcher"},ang={["faction:Horde"]="Att föra forskningen söderut markerar en resenärs övergång från Tirisfal Glades välbekanta trakter till Silverpine Forests mörkare konflikter.",["race:Undead"]="De här resultaten speglar Royal Apothecary Societys enda drivande ambition: att leverera The New Plague som utlovats till den mörka damen."},sec={{t="Korrespondens mellan apotekare",b="Royal Apothecary Society verkar under Lady Sylvanas Windrunners obevekliga press att utveckla The New Plague, som ska kunna förgöra både de levande och Scourge. Eftersom forskarna är utspridda bland Lordaerons omstridda ruiner är det livsviktigt att data flödar mellan utposterna. Apothecary Johaan sammanställer sina lokala testanteckningar i Brill och skickar dem söderut till Apothecary Renferrel, som leder sällskapets arbete från The Sepulcher i Silverpine Forest. De här dokumenten utgör en liten del av sällskapets gemensamma arbete med att förfina sina dödliga brygder."}},faq={{q="Vad är Johaan's Findings?",a="Det är ett paket med alkemiska anteckningar och forskning sammanställda av Apothecary Johaan i Brill. Dokumenten beskriver hans senaste tester och experiment i Tirisfal Glades.",al={"johaans resultat","vad är johaans resultat","johaans forskningsdokument"}},{q="Vem ska få det här föremålet?",a="Anteckningarna är adresserade till Apothecary Renferrel, en senior medlem av Royal Apothecary Society som är stationerad vid The Sepulcher i norra Silverpine Forest.",al={"vem får johaans resultat","vart ska jag ta johaans resultat","leverans till renferrel"}},{q="Varför delar apotekarna forskningen med varandra?",a="Royal Apothecary Society förlitar sig på att de utspridda forskarna delar kunskap för att påskynda arbetet. Sylvanas Windrunner kräver att The New Plague utvecklas snabbt, så forskarna i Silverpine måste hållas uppdaterade om framstegen i Tirisfal.",al={"varför dela resultat","syftet med johaans resultat","royal apothecary societys forskning"}},{q="Vem skrev de här dokumenten?",a="Apothecary Johaan, en alkemist i Royal Apothecary Society som håller till nära galgen i Brill. Han testar lokala exemplar i experiment för att främja de fördömdas alkemiska mål.",al={"vem är apothecary johaan","vem skrev det här","apothecary johaan"}}},fp="17,181,25.524.0,26.156.0,37.156.0,55.236.0,26.169.0"}
P.entries["item:johaan-s-special-drink"] = {n="Johaan's Special Drink",s="Johaan's Special Drink är en dödlig brygd som Apothecary Johaan tillreder i byn Brill. Förklädd till en vanlig förfriskning används blandningen för att fälttesta Royal Apothecary Societys nya farsot.",h="Johaan's Special Drink är en dödlig brygd som Apothecary Johaan tillreder i byn Brill.",kw={"apothecary johaan","brill","captured mountaineer","gallows' end tavern","johaan","johaan's special drink","ny farsot"},ang={["race:Dwarf"]="Brygden visar det dystra öde som väntar dvärgiska spejare som kommer för nära Tirisfal Glades, där fångar används som försöksobjekt i laboratoriet.",["race:Undead"]="För de Fördömda innebär leveransen av Johaans brygd en konkret tjänst åt Royal Apothecary Society och Lady Sylvanas storslagna planer mot de levande."},sec={{t="En giftig brygd",b="Johaan's Special Drink bryggs i Brills bryggkittlar och är långt ifrån en dryck som serveras på värdshus. Apothecary Johaan tillreder brygden genom att förädla olika giftiga beståndsdelar och lokala reagenser till en enda dryck, särskilt utformad för att testa smittsamheten på levande kroppar. Den ges under förevändningen att släcka en fånges törst och visar de Fördömdas apotekares ihärdiga ambition att skapa ett vapen kraftfullt nog att uppfylla Sylvanas Windrunners planer för Azeroth."},{t="Prövningen i källaren",b="Drycken når sin avsedda mottagare i den dystra källaren under Gallows' End Tavern, som Deathguard använder som tillfällig arrest för objudna gäster. När den erbjuds en tillfångatagen dvärgisk bergsman som sitter fjättrad dricker den törstige fången girigt och misstar den för enkelt öl. Brygden verkar omedelbart och dödar dvärgen på fläcken, vilket bevisar för Royal Apothecary Society att deras senaste stam snabbt kan släcka livet hos levande offer."}},faq={{q="Vad är Johaan's Special Drink?",a="Det är en dödlig brygd som Apothecary Johaan har skapat i Brill. Trots att den presenteras som en dryck är den spetsad med en stam av de Fördömdas nya farsot, utformad för att testa dess dödliga verkan på levande varelser.",al={"vad är johaans dryck","johaans dryck","vad är det här för föremål"}},{q="Vem får drycken?",a="Drycken förs ner till källaren i Gallows' End Tavern i Brill och ges till en Captured Mountaineer som tillfångatagits av den lokala Deathguard.",al={"vem dricker den","vem ska jag ge drycken till","dryckens mål"}},{q="Vad händer när någon dricker den?",a="Fången sveper i sig vätskan i tron att det är strävt värdshusöl som ska släcka törsten, men faller genast död ner av brygdens giftiga ämnen.",al={"dör dvärgen","dryckens effekt","vad gör den"}},{q="Varför tillreder Apothecary Johaan den här drycken?",a="Apothecary Johaan utför försök med Royal Apothecary Societys nya farsot. Han använder den tillfångatagna dvärgen som ovetande försöksobjekt för att se hur effektiv blandningen är på att släcka dödligt liv.",al={"varför gjorde johaan den","apothecary johaans motiv","varför testa farsoten"}}},fx={["7bd04f9d"]={q="Var kommer Johaan's Special Drink ifrån, och vem gjorde den?",a="Blandningen bryggs direkt av Apothecary Johaan i Brill i Tirisfal Glades. På uppdrag av Royal Apothecary Society och Lady Sylvanas Windrunner förädlar Johaan experimentella gifter som samlats in från lokala varelser till denna kraftfulla, dödliga blandning.",al={"vem gjorde johaan's special drink","varifrån kommer johaan's special drink","vem bryggde drycken"}}},fp="22,174,12.359.0,16.323.1,31.117.0,26.139.0,36.68.1,43.163.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="Jordan's Ore Shipment",s="Jordan's Ore Shipment är en malmlåda som Bailor Stonehand skulle förädla till sin legering åt smeden Jordan Stilwell. Karavanen kom från Wetlands, men Mo'grosh-ogrerna överföll och plundrade den i Loch Modans nordöstra kullar.",h="Jordan's Ore Shipment är en malmlåda som Bailor Stonehand skulle förädla till sin legering åt smeden Jordan...",kw={"legering","bailor stonehand","jordan stilwell","jordan's ore shipment","loch modan","mo'grosh","test of righteousness"},ang={["class:Paladin"]="Att återta den stulna legeringen från Mo'grosh-ogrerna är ett viktigt steg i Jordan Stilwells beställning och visar ditt engagemang under Test of Righteousness.",["profession:Blacksmithing"]="Bailor Stonehands speciallegering visar prov på fin dvärgisk metallurgi. Den är så eftertraktad att Jordan Stilwell vägrade använda vanliga ersättningar i sitt hantverk."},sec={{t="En överfallen leverans",b="Den här malmen skulle förädlas till Bailor Stonehands särskilda legering och hade utlovats till Jordan Stilwell för hans metallarbete. När karavanen färdades söderut genom bergen från Wetlands in i Loch Modan överföll Mo'grosh-ogrerna den brutalt. De släpade lasten till sitt fäste i vildmarken, där de överlevande vakterna dog av sina sår. Jordans smidesprojekt står stilla tills en äventyrare kan ta tillbaka lasten från bestarna."}},faq={{q="Vad finns i lasten?",a="Lasten innehåller malm som dvärgen Bailor Stonehand förädlar till sin särskilda legering. Den har utlovats till smeden Jordan Stilwell för hans metallarbete i Ironforge.",al={"vad finns i jordans malmlast","vilken malm är det här","innehåll i jordans malmlast"}},{q="Vem stal Jordan's Ore Shipment?",a="Mo'grosh-ogrerna överföll karavanen när den färdades söderut från Wetlands. De dödade följeslagarna och släpade lådorna tillbaka till sitt område nordost om The Loch.",al={"vem tog malmlasten","vem stal den","ogrerna och malmlasten"}},{q="Vem är Bailor Stonehand?",a="Bailor Stonehand är en dvärgisk hantverkare stationerad i Loch Modan och en gammal vän till Jordan Stilwell. Han ordnade leveransen av legeringen innan ogreöverfallet.",al={"bailor stonehand","vem är bailor"}},{q="Varför är den här lasten viktig för paladiner?",a="Paladiner som genomgår Test of Righteousness söker efter legeringen för att hjälpa Jordan Stilwell smida ett helgat vapen av Ljuset.",al={"paladinernas malmlast","malm till test of righteousness","varför behöver paladiner detta"}}},fx={bb183b6f={q="Vad är Jordan's Ore Shipment?",a="Jordan's Ore Shipment är en malmlåda som dvärgen Bailor Stonehand skulle förädla till sin speciallegering åt smeden Jordan Stilwell i Ironforge. Lasten transporterades av en karavan på väg in från Wetlands innan den överfölls och beslagtogs av Mo'grosh-ogrer i norra Loch Modan.",al={"vad är jordan's ore shipment","information om jordan's ore shipment","vad är bailors malm"}},["84b5d642"]={q="Var kommer Jordan's Ore Shipment ifrån, och vem gjorde den?",a="Sändningen består av malm som transporterades med karavan från Wetlands in i Loch Modan, där Bailor Stonehand skulle förädla den till sin legering åt sin gamle vän Jordan Stilwell. Ogrer stoppade transporten och dödade dess vakter innan den hann fram.",al={"vem gjorde jordan's ore shipment","varifrån kommer jordan's ore shipment","jordan's ore shipments ursprung"}}},fp="21,201,20.399.0,28.134.0,32.168.0,24.157.0,43.126.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="Jordan's Refined Ore Shipment",s="Jordan's Refined Ore Shipment är en låda med metall av hög kvalitet, särskilt framtagen för smeden Jordan Stilwell. Den skaffas som en del av en paladins heliga prövningar och innehåller det nödvändiga materialet för att smida ett heligt dygdens vapen.",h="Jordan's Refined Ore Shipment är en låda med metall av hög kvalitet, särskilt framtagen för smeden Jordan...",kw={"bailor","ironforge","jordan stilwell","paladinvapen","raffinerad malm","test of righteousness"},ang={["class:Paladin"]="Att skaffa den raffinerade leveransen prövar en paladins tålamod och hängivenhet och är en av de fysiska prövningar som krävs för att skapa deras symboliska vapen för Ljuset.",["profession:Blacksmithing"]="Varje hantverkare vet att mästerligt smide kräver felfria, noggrant förberedda tackor i stället för rå malm från fältet."},sec={{t="Material till en smed",b="När Jordan Stilwell gav sig av för att smida ett vapen värdigt en hängiven paladin räckte vanligt material inte till. Smeden behövde flera sällsynta och noggrant utvalda komponenter: en Purified Kor Gem, stadigt Whitestone Oak-virke, sin egen förlorade smedshammare och en särskild leverans av raffinerad malm. Denna leverans utgör metallgrunden för det heliga arbetet och förs till Ironforge för att slutföra Test of Righteousness."}},faq={{q="Vad används Jordan's Refined Ore Shipment till?",a="Den raffinerade malmen levereras till Jordan Stilwell utanför Ironforge som en av fyra viktiga komponenter som krävs för att smida ett mästerverk till vapen åt paladiner som genomgår Test of Righteousness.",al={"raffinerad malm användning","vad gör jordan med malmen","malmleverans användning"}},{q="Vem förbereder den raffinerade malmen?",a="Leveransen ordnas genom Bailor, som övervakar raffineringen och utskeppningen av den specialmetall Jordan Stilwell behöver.",al={"vem gjorde malmen","bailor malm","vem raffinerar jordans malm"}},{q="Varför behöver Jordan just den här leveransen?",a="Jordan Stilwell tänker skapa en symbol för paladinernas tro och Ljuset, vilket kräver material av högre kvalitet än vanliga rester från smedjan. Den specialbehandlade metallen säkerställer att klingan eller hammarhuvudet får den balans och renhet som anstår en helig riddare.",al={"varför särskild malm","varför kan jordan inte använda vanligt järn","orsak till raffinerad malm"}}},fx={ec64bb0f={q="Vad är Jordan's Refined Ore Shipment?",a="Jordan's Refined Ore Shipment är en låda med metall av hög kvalitet, särskilt bearbetad åt vapensmeden Jordan Stilwell. Den förädlade malmen är avsedd för fint smidesarbete snarare än vanligt smedjearbete och ger Jordan det rena metallunderlag han behöver för att skapa ett enastående vapen, värdigt en hängiven paladin av Ljuset.",al={"vad är jordan's refined ore shipment","lore om jordan's refined ore shipment","vad är jordans förädlade malm"}}},fp="29,158,19.241.0,47.167.0,29.114.0,44.240.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="Jordan's Smithing Hammer",s="Jordan's Smithing Hammer är ett älskat familjearv som gått i arv till den mänsklige smeden Jordan Stilwell från hans far. Att återfinna det i de hemsökta salarna i Shadowfang Keep är avgörande för att smida ett heligt vapen invigt åt Ljuset.",h="Jordan's Smithing Hammer är ett älskat familjearv som gått i arv till den mänsklige smeden Jordan Stilwell...",kw={"dun morogh","ironforge","jordan stilwell","paladinvapen","shadowfang keep","smideshammare","test of righteousness"},ang={["class:Paladin"]="Att återta arvehamaren är en del av de krävande rättfärdighetens prövningar och visar att en paladin är fast besluten att trotsa farliga trakter för att få tag på verktygen för heligt smide.",["profession:Blacksmithing"]="Varje smed förstår det känslomässiga och praktiska bandet mellan en mästersmed och hammaren som gått i arv från tidigare generationer."},sec={{t="En hantverkares arv",b="För en vanlig betraktare kan Jordan's Smithing Hammer verka vara vanligt smidesjärn, men för Jordan Stilwell står den för både arv och öde. Han ärvde verktyget av sin far, och det är en central del av Jordans identitet som smidesmästare utanför Ironforge. På något sätt har den hamnat innanför Shadowfang Keeps övergivna stenväggar i Silverpine Forest, och den måste återtas innan Jordan kan försöka sig på sitt mästerverk, ett heligt vapen värdigt en helig kämpe."}},faq={{q="Var finns Jordan's Smithing Hammer?",a="Hammaren vilar innanför Shadowfang Keeps förbannade murar, i Silverpines mörka skogar. Paladiner som genomgår Test of Righteousness måste ta sig in i den ockuperade fästningen för att återta den.",al={"hammarens plats","var finns jordans hammare","var hittar man jordans smideshammare"}},{q="Varför är hammaren så viktig för Jordan Stilwell?",a="Jordan fick hammaren i arv av sin far. Den har ett stort känslomässigt värde och är verktyget han behöver för att smida sin främsta skapelse, ett heligt vapen åt Ljuset.",al={"varför vill jordan ha hammaren","jordan stilwell och hammaren i berättelsen"}},{q="Vad används hammaren till när den återfunnits?",a="När den återförts till Jordan utanför Ironforges portar tillsammans med virke, malm och en ädelsten använder han den till att smida ett storslaget, heligt vapen som belöning åt paladinen som hjälpte honom.",al={"vad smider hammaren","hammarens användning i test of righteousness"}}},fx={["126e648c"]={q="Vad är Jordan's Smithing Hammer?",a="Jordan's Smithing Hammer är ett kärt smidesverktyg som tillhör mästersmeden Jordan Stilwell. Utöver sin praktiska användning vid städet har den ett stort känslomässigt värde som ett arvegods som Jordan fick direkt av sin far.",al={"vad är jordan's smithing hammer","jordans hammarföremål","om jordan's smithing hammer"}},["1df19239"]={q="Var kommer Jordan's Smithing Hammer ifrån, och vem gjorde den?",a="Jordans far lämnade över hammaren till honom. Vem som tillverkade den är inte dokumenterat, men innan du återfinner den hade arvegodset på något sätt hamnat långt från Ironforge, undanstoppat i Shadowfang Keeps mörka försvarsverk.",al={"varifrån kommer jordans hammare","vem gjorde jordan's smithing hammer","jordan's smithing hammers ursprung"}}},fp="24,93,20.244.0,42.172.0,51.148.0,43.150.0"}
P.entries["item:jungle-remedy"] = {n="Jungle Remedy",s="På Rebel Camp kan Jungle Remedy hjälpa de sårade att hålla sig stridsdugliga mot Kurzens styrkor. Sergeant Yohwa behöver läkemedel från Kurzen Compound för att behandla lägrets kämpar.",h="På Rebel Camp kan Jungle Remedy hjälpa de sårade att hålla sig stridsdugliga mot Kurzens styrkor.",kw={"headshrinkers","jungle remedy","kurzen","medicine men","rebel camp","sergeant yohwa","stranglethorn vale","witch doctors"},sec={{t="Ett lägers behov",b="Kurzens medicinmän använder Jungle Remedies för att läka sina kämpar i lägret. Sergeant Yohwa behöver dem på Rebel Camp, där de kan hjälpa hans egna att överleva och vara redo att slåss."}},faq={{q="Vad används Jungle Remedy till?",a="Sergeant Yohwa behöver Jungle Remedies för att behandla kämparna på Rebel Camp och hålla dem stridsdugliga mot Kurzen.",al={"användning av jungle remedy","vad gör jungle remedy"}},{q="Vem bär på Jungle Remedies?",a="Kurzen Medicine Men, Witch Doctors och Headshrinkers bär på Jungle Remedies. Jungle Fighters har dem ibland.",al={"var hittar man läkemedel","kurzenmedicin"}},{q="Varför behöver Sergeant Yohwa dem?",a="Kurzens styrkor använder läkemedlen för att läka sina egna kämpar, och Sergeant Yohwa behöver dem för att ta hand om de sårade på Rebel Camp.",al={"varför yohwa vill ha dem","medicin till rebel camp"}},{q="Var hittar jag Jungle Remedies?",a="Leta i Kurzen Compound i Stranglethorn Vale. Kurzens helare och andra kämpar bär på läkemedlen.",al={"läkemedlens plats","var finns läkemedel"}}},fp="13,185,15.194.0,26.121.0,28.116.0,34.135.0,33.107.0"}
P.entries["item:kadrak-s-flag"] = {n="Kadrak's Flag",s="Vid gränsen mellan The Barrens och Ashenvale ger Kadrak Horde ett märke att bära in i fiendeland. Flaggan planteras i The Talon Den efter att Keymaster Rynthariel dödats.",h="Vid gränsen mellan The Barrens och Ashenvale ger Kadrak Horde ett märke att bära in i fiendeland.",kw={"the barrens","hordes närvaro","kadrak","kadrak's flag","rynthariel","stonetalon","stonetalon peak","talon den"},ang={["faction:Horde"]="Att plantera baneret djupt inne i The Talon Den förkunnar Hordes styrka och visar att den slår till mot Night Elf-fristäder när den provoceras.",["race:NightElf"]="För en Night Elf är Hordes baner inne i The Talon Den en direkt förolämpning mot Stonetalon Peaks beskyddare."},sec={{t="Ett trotsigt märke",b="Kadrak skickar Hordes flagga till The Talon Den på Stonetalon Peak. Dryaden Rynthariel, Denens Keymaster, har skickat meddelanden över gränsen, och Kadrak beslutar att hennes död ensam inte räcker som svar. Han ger dig det karmosinröda baneret att plantera djupt inne i Denen. Hordes färger där bär en varning till Night Elves och dryader: intrång över The Barrens möts av vedergällning på Alliance-mark."}},faq={{q="Vad används Kadrak's Flag till?",a="Plantera Kadrak's Flag inne i The Talon Den på toppen av Stonetalon Peak efter att ha dödat Rynthariel the Keymaster. Hordes baner varnar Night Elves för att skicka fler spejare och budbärare in i The Barrens.",al={"flaggans syfte","varför plantera flaggan","vad gör flaggan"}},{q="Vem ger dig fanan?",a="Kadrak, en orc-spejare vid gränsposteringen mellan norra The Barrens och Ashenvale, ger dig baneret medan han arbetar för att säkra regionen.",al={"vem ger flaggan","var får man flaggan","var finns kadrak"}},{q="Var planteras fanan?",a="Plantera baneret inne i The Talon Den, en grottfristad på Stonetalon Peaks västra sluttningar i Stonetalon Mountains.",al={"var ska jag plantera flaggan","flaggans plats","plats för flaggan i talon den"}},{q="Vem är Rynthariel?",a="Rynthariel är en dryad och Keymaster i The Talon Den. Hon skickar budbärare in på Horde-territorium tills Kadrak avlyssnar hennes meddelanden och beordrar att hon ska dödas.",al={"rynthariel dryad","vem är rynthariel","nyckelmästare"}}},fx={["555b344d"]={q="Vad är Kadrak's Flag?",a="Kadrak's Flag är en symbol för Horde, som orcernas utpostbefälhavare Kadrak anförtrott åt dig vid gränsen mellan The Barrens och Ashenvale. Den bär Hordes färger och sigill och fungerar som en tydlig territoriell markering. Den gör anspråk på mark och sänder ett kompromisslöst trotsbudskap till Alliance-styrkor som tar sig söderut.",al={"vad är kadrak's flag","kadrak flagga","om kadrak's flag"}},["52bd9818"]={q="Varför vill Kadrak att hans flagga planteras i The Talon Den?",a="Kadrak vill att du ska driva ner fanan mitt i The Talon Den på Stonetalon Peak efter att dryadledaren Rynthariel har dödats. När Hordes standar står i deras fristad förstår eventuella överlevande spejare eller Alliance-sympatisörer att intrång på Hordes territorium möts av beslutsamma, dödliga motåtgärder.",al={"varför plantera kadrak's flag","varför vill kadrak att flaggan placeras","syftet med att plantera flaggan"}}},fp="13,140,18.386.0,31.202.0,23.145.0,26.127.0,18.161.0"}
P.entries["item:karnitol-s-satchel"] = {n="Karnitol's Satchel",s="Karnitols satchel innehåller tillhörigheter som eftersöks efter skeppsbrottet i Desolace. Kreldig Ungor leder sökandet mot Slitherblade-nagorna längs kusten.",h="Karnitols satchel innehåller tillhörigheter som eftersöks efter skeppsbrottet i Desolace.",kw={"desolace","karnitol","karnitols satchel","kreldig ungor","nagor","ranazjar isle","reclaimers","roetten stonehammer","satchel","slitherblade"},ang={["faction:Alliance"]="Reclaimers söker efter Karnitols tillhörigheter, och Kreldig Ungor kallar återfinnandet en stor tjänst åt dem."},sec={{t="Bland Slitherblade",b="Kreldig Ungor visar dig vägen till Ranazjar Isle, där Slitherblade-nagorna bor bland ruiner efter Night Elf under havet. Han misstänker att de mäktiga tidjägarna och havshäxorna kan ha samlat på sig Karnitols tillhörigheter. Satcheln återfinns hos dem längs kusten i Desolace."},{t="Tillbaka till Reclaimers",b="I Desolace lämnar du tillbaka den återfunna satcheln till Kreldig Ungor, som kallar det en stor tjänst åt Reclaimers. Han skickar den vidare till Roetten Stonehammer i Ironforge. Roetten säger att kistan förstördes, men att tillhörigheterna finns där, och låter Karnitol avgöra i vilket skick de är."}},faq={{q="Vem letar efter Karnitols satchel?",a="Kreldig Ungor leder sökandet efter Karnitols tillhörigheter på uppdrag av Reclaimers. Satcheln förs sedan till Roetten Stonehammer i Ironforge.",al={"vem vill ha satcheln","karnitols tillhörigheter","satchel till vem"}},{q="Var hittar jag satcheln?",a="Slitherblade-nagorna längs kusten i Desolace kan ha Karnitols tillhörigheter. Kreldig Ungor visar dig vägen till deras tidjägare och havshäxor nära Ranazjar Isle.",al={"var finns satcheln","satchelns plats","hitta karnitols väska"}},{q="Vad är Slitherblade?",a="Slitherblade är en naga-stam som bor bland ruiner efter Night Elf under havet nära Ranazjar Isle i Desolace.",al={"slitherblade-nagor","nagor i desolace","vem bor vid ranazjar"}},{q="Vem tar emot satcheln i Ironforge?",a="Roetten Stonehammer tar emot satcheln i Ironforge och säger att Karnitol kan avgöra om de återfunna tillhörigheterna duger.",al={"satchel i ironforge","vem får väskan","roettens satchel"}},{q="Återfanns Karnitols kista oskadd?",a="Nej. Roetten Stonehammer säger att kistan förstördes, men tillhörigheterna finns där för Karnitol att granska.",al={"vad hände med kistan","kistan förstörd","karnitols saker skadade"}}},fp="18,163,22.274.0,22.283.0,38.150.0,29.164.0,26.115.0,38.132.1,38.110.1"}
P.entries["item:keg-of-shindigger-stout"] = {n="Keg of Shindigger Stout",s="En Keg of Shindigger Stout är en tunna kraftigt dvärgäle, bryggd och bevakad av gevärsskyttarna och soldaterna som är stationerade i Dun Garok. Royal Apothecary Society i Tarren Mill vill ha den, inte som kvällsdrink utan som ett lömskt transportmedel för nysyntetiserade farsoter.",h="En Keg of Shindigger Stout är en tunna kraftigt dvärgäle, bryggd och bevakad av gevärsskyttarna och...",kw={"apothecary lydon","dun garok","dvärgäle","elixir of agony","keg of shindigger stout","shindigger stout","tarren mill"},ang={["faction:Horde"]="Ett angrepp mot Dun Garok stör en farlig militär utpost tillhörande Alliansen, belägen bland kullarna i sydöstra Hillsbrad Foothills.",["race:Undead"]="För Forsaken är stölden av en tunna eftertraktat dvärgöl en rent praktisk alkemisk åtgärd: alkoholen döljer lukten och smaken av de dödliga brygder som utvecklats åt Lady Sylvanas."},sec={{t="En dvärgfavorit",b="Dun Garok är en mäktig dvärgbastion i sydöstra Hillsbrad Foothills, som dvärgarna från Ironforge försvarar med hård hand. I de befästa kasernerna och matsalarna delar de härdade försvararna på tunnor med Shindigger Stout för att uthärda kylan och den utdragna belägringen från fiender i trakten. Ölet är kraftigt och finns i överflöd, så det är en stapelvara i garnisonens vardag."},{t="Apothecary Lydons giftbägare",b="Dvärgarna ser Shindigger Stout som en välförtjänt belöning efter strid, men Apothecary Lydon i Tarren Mill ser den som ett perfekt redskap för terror. Lydon har fått i uppdrag att utveckla Forsakens ondskefulla Elixir of Agony, men vägrar testa sin dödliga blandning på djur. I stället vill han ha en intakt öltunna att spetsas med brygden, så att han kan skapa en förgiftad gåva till tillfångatagna mänskliga bönder i Tarren Mill."}},faq={{q="Vad används Shindigger Stout till?",a="Apothecary Lydon i Tarren Mill vill ha tunnan med stout för att testa sitt nyförfinade Elixir of Agony. I stället för att slösa det frätande giftet på försöksdjur tänker han spetsat dvärgölet och utföra ett dödligt fälttest på människoliknande varelser.",al={"varför hämta shindigger stout","shindigger stouts syfte","vad gör lydon med tunnan"}},{q="Var hittar man en Keg of Shindigger Stout?",a="Tunnor med stout förvaras djupt inne i dvärgfästningen Dun Garok, som ligger i sydöstra Hillsbrad Foothills. De brukar stå i matsalarna och de nedre kasernrummen där dvärginfanteriet håller till.",al={"tunnans plats","var finns shindigger stout","hitta stouten"}},{q="Vem brygger Shindigger Stout?",a="Den bryggs och förvaras av dvärgarna i Dun Garok, som upprätthåller en kraftigt befäst garnison i Hillsbrad Foothills på Ironforges uppdrag.",al={"vem brygger shindigger stout","är det dvärgäle"}},{q="Varför brygger inte Apothecary Lydon egen alkohol till testet?",a="Lydon ber om en tunna som redan förvaras i Dun Garok så att han kan använda ölet i sitt experiment. Uppdraget beskriver inte att han brygger alkohol själv.",al={"varför stjäla dvärgöl","varför dun garok-öl"}}},fx={b55cb0ca={q="Vad är en Keg of Shindigger Stout?",a="En Keg of Shindigger Stout är en tunna med starkt dvärgälet som förvaras av dvärgarna från Ironforge, stationerade i fästningen Dun Garok. Den är avsedd att förse dvärgsoldaterna under deras insats i Hillsbrad Foothills, men den starka brygden gör den till ett utmärkt underlag för Apothecary Lydons experiment på uppdrag av Royal Apothecary Society.",al={"vad är keg of shindigger stout","information om shindigger stout-tunnan","vad är shindigger stout"}}},fp="23,169,18.253.0,32.234.1,34.150.0,45.163.0,27.125.0,63.144.0"}
P.entries["item:ken-zigla-s-draught"] = {n="Ken'zigla's Draught",s="Ken'zigla's Draught är en kraftfull, vidrigt smakande medicinalbrygd som Ken'zigla tillreder i Stonetalon Mountains. Den är framtagen för att återställa tillräckligt med styrka hos svårt sårade så att de kan röra sig utan att förblöda.",h="Ken'zigla's Draught är en kraftfull, vidrigt smakande medicinalbrygd som Ken'zigla tillreder i Stonetalon...",kw={"camp taurajo","dogran","grunt logmar","ken'zigla's draught","kenzigla","stonetalon mountains","succubusuppdrag","the barrens"},ang={["class:Warlock"]="Att skaffa och leverera brygden är ett viktigt steg i prövningarna för att kalla fram och binda en succubus. Det visar att en warlock är påhittig och kan spåra mål genom The Barrens.",["faction:Horde"]="Camp Taurajo har få vakter eftersom patruller är ute och samlar föda. För en agent som tillfångatagits bakom fiendens quilboarlinjer är brygden den enda livlinan."},sec={{t="En bitter kur",b="Den här kraftfulla brygden tillreder Ken'zigla i Stonetalon Mountains som akut hjälp åt dem som är nära döden. Den är mycket stark och måste doseras noga. Om patienten dricker mer än en halv dos på en gång riskerar blodcirkulationen att öka så kraftigt att patienten förblöder. En halv dos ger tillräcklig styrka för att röra sig och fly från överhängande fara. Resten måste vänta tills kroppen har stabiliserats efter en hel natts vila."},{t="Nåd i The Barrens",b="Brygden spelar en avgörande roll i sökandet efter Dogran, en agent som tillfångatogs och torterades av quilboar norr om Camp Taurajo. Horde warlocks bär med sig den medan de söker efter en soul devourers token, och smugglar den rakt in i razormanes fientliga läger. När Dogran dricker den får han precis tillräckligt med kraft för att linka bort från sina fångvaktare, trots att svåra skador har gjort att han för alltid förlorat användningen av sina lemmar."}},faq={{q="Vad används Ken'zigla's Draught till?",a="Det är en kraftfull medicinalbrygd som återställer styrka hos döende eller svårt skadade. Rätt dos ger en sårad person tillräckligt med ork för att resa sig och fly från fångenskap utan att drabbas av livshotande blödningar.",al={"vad gör kenziglas brygd","brygdens syfte","varför behöver jag kenziglas brygd"}},{q="Vem tillreder brygden?",a="Den tillreds av Ken'zigla, en apotekare eller ört- och läkekunnig som bor i Stonetalon Mountains. Ken'zigla förberedde den i väntan på att någon skulle komma för att hjälpa Dogran.",al={"vem tillreder brygden","vem är kenzigla","kenziglas plats"}},{q="Varför får man bara ta en halv dos åt gången?",a="Brygden är extremt påfrestande för kroppen. En halv dos ger precis tillräckligt med styrka för att röra sig utan att orsaka svåra blödningar. Den andra halvan måste vänta tills patienten har vilat en natt, så att kroppen inte utsätts för livshotande påfrestningar.",al={"hur tar man kenziglas brygd","halv dos brygd","anvisningar för brygden"}},{q="Vem får brygden?",a="Till slut förs den till Dogran, en agent som hålls fången och är svårt skadad i ett quilboarläger norr om Camp Taurajo i The Barrens.",al={"vem dricker brygden","vem är dogran","var ska brygden levereras"}},{q="Varför skickas warlocks för att hämta medicinen?",a="Horde warlocks som vill binda en succubus leds till Dogran, som har ett föremål med stark känslomässig betydelse. De måste hjälpa till att leverera brygden för att nå honom och få tag på det som behövs till ritualen.",al={"varför behöver warlocks den här","succubusuppdragets brygd","warlockuppdrag kenzigla"}}},fx={["6eadaa9a"]={q="Vad är Ken'zigla's Draught?",a="Det är en kraftfull, vidrigt smakande medicinalbrygd som trollapotekaren Ken'zigla tillverkat i Stonetalon Mountains. Blandningen är gjord för att hjälpa vid svåra skador och är tillräckligt kraftfull för att återställa en dödligt sårad soldats livskraft och låta soldaten röra sig, men den måste ges med stor försiktighet.",al={"vad är brygden","ken'zigla's draught","ken'ziglas brygd"}},["42d17912"]={q="Varför behövs Ken'zigla's Draught?",a="En orc vid namn Dogran tillfångatogs och torterades brutalt av quilboar i The Barrens. Han förblöder och är nära döden i fångenskap, och kan varken överleva eller fly utan brygdens läkande magi. Grunt Logmar i Camp Taurajo behöver desperat botemedlet så att Dogran kan härda ut sina skador länge nog för att fly från sina fångvaktare.",al={"varför behöver de brygden","vem behöver ken'zigla's draught","varför tillverka brygden"}}},fp="19,177,15.340.0,20.294.1,37.180.0,22.59.0,50.208.0,25.136.0,48.207.0"}
P.entries["item:khan-dez-hepah-s-head"] = {n="Khan Dez'hepah's Head"}
P.entries["item:khan-jehn-s-head"] = {n="Khan Jehn's Head",s="Khan Jehn's Head är bevis på att Magram-khanen har dödats. Uthek the Wise från Gelkis Village kräver den som ett tecken på vänskap med Gelkis-klanen.",h="Khan Jehn's Head är bevis på att Magram-khanen har dödats.",kw={"centaur","desolace","jordmagi","gelkis","jehn","khan jehn","khan jehn's head","magram","uthek the wise"},sec={{t="Ett tecken på vänskap",b="I Desolace ber Uthek the Wise dig ta med Khan Jehn's Head till Gelkis Village. Jehn leder de rivaliserande Magram-centaurerna, och Uthek säger att jorden berättar för honom att deras klan blir svagare. Gelkis vill att deras fiendes khan ska dö, och de vill att du ska bevisa att du står på deras sida."},{t="Khanens fall",b="När du återvänder med Khan Jehn's Head kallar Uthek Jehn stark men dåraktig. Han tror att jordmagi är starkare än Jehns kraft. När Magram-ledaren är borta väntar sig Uthek att klanen ska falla, och säger att Gelkis kommer att styra Desolace."}},faq={{q="Vem vill ha Khan Jehn's Head?",a="Uthek the Wise från Gelkis Village ber dig ta med Khan Jehn's Head som bevis på vänskap med Gelkis.",al={"vem vill ha huvudet","uthek huvud","gelkis begäran"}},{q="Vem var Khan Jehn?",a="Khan Jehn var ledare för Magram-centaurerna, Gelkis-klanens rivaler.",al={"vem är jehn","magram-khan","khan jehn"}},{q="Varför vill Gelkis att Jehn ska dö?",a="Uthek säger att Magram blir svagare och ber dig döda deras khan. Han tror att Gelkis kan styra när Jehn är borta.",al={"varför döda jehn","gelkis mot magram","varför jehn"}},{q="Vart ska jag ta Khan Jehn's Head?",a="Ta Khan Jehn's Head till Uthek the Wise i Gelkis Village i Desolace.",al={"vart ska huvudet","ta med jehn-huvudet","utheks plats"}},{q="Vad säger Uthek när Jehn har fallit?",a="Uthek kallar Jehn stark men dåraktig och säger att Magram kommer att falla utan sin ledare. Han väntar sig att Gelkis ska styra.",al={"utheks slutförande","vad händer efter jehn","gelkis styre"}}},fp="16,152,20.273.0,15.231.1,27.107.0,18.78.0,33.122.0,34.72.0,37.118.1"}
P.entries["item:khazgorm-s-journal"] = {n="Khazgorm's Journal",s="Vid Bael Modan leder Prospector Khazgorm Ironforges dvärgexpedition i södra Barrens. Hans fältjournal dokumenterar Explorers' Leagues arbete på mark som Stonespire-taurenerna gör anspråk på.",h="Vid Bael Modan leder Prospector Khazgorm Ironforges dvärgexpedition i södra Barrens.",kw={"bael modan","barrens","dvärg","explorers' league","gann stonespire","journal","khazgorm","prospektör"},ang={["faction:Horde"]="Som medlem av Horde kan du hjälpa Gann Stonespire att försvara Kalimdor mot Alliance-expeditioner som tränger in på Hordes territorium.",["race:Tauren"]="Som tauren kan du se journalen som bevis på att Ironforge-inkräktarna struntar i Stonespire-stammen när de spränger dess förfäders marker."},sec={{t="En redogörelse för förstörelse",b="Prospector Khazgorm styr de tunga maskinerna och sprängningarna som skär in i kullarna i södra Barrens. Hans anteckningar visar en utgrävning långt från Explorers' Leagues utlovade kunskapssökande: arbetet har trängt undan Stonespire-stammen. Taurenerna försökte lösa saken fredligt, men dvärgarna vägrade. Gann Stonespire vill ha journalen för att förstå Ironforges närvaro i sitt hemland och hitta ett sätt att bryta den."},{t="En förändrad taktik",b="Gann Stonespire hittar journalen bland Khazgorms kvarlevor, nära utgrävningsplatsens tält och pelare. Anteckningarna visar honom hur dvärgexpeditionen är organiserad, vilken utrustning den använder och var den är sårbar. Med den kunskapen övergår Gann från att driva bort arbetare till att slå mot utgrävningens maskiner. Journalen förändrar kampen om Bael Modan."}},faq={{q="Vem tillhör journalen?",a="Journalen tillhör Prospector Khazgorm, en ledare för Ironforges dvärgexpedition vid Bael Modan i södra Barrens.",al={"vem äger journalen","khazgorm","prospector khazgorm"}},{q="Varför vill Gann Stonespire ha den här boken?",a="Gann Stonespire vill studera planerna och hemligheterna hos dvärgarna som trängde undan hans stam. Khazgorms anteckningar hjälper honom att planera fler angrepp mot lägret vid Bael Modan.",al={"varför gann vill ha journalen","ganns journaluppdrag","ganns återtagandebok"}},{q="Var finns journalen?",a="Prospector Khazgorm bär journalen bland tälten och klippelarna vid den aktiva utgrävningen strax söder om Bael Modan.",al={"var finns khazgorms journal","hitta khazgorms journal","khazgorms plats"}},{q="Vad avslöjar journalen om dvärgarna?",a="Journalen visar att Explorers' Leagues jakt på begravda reliker och titanernas arv sker på direkt och våldsam bekostnad av stammar som Stonespire-taurenerna.",al={"explorers league i barrens","hemligheter vid dvärgarnas utgrävning","bael modans syfte"}}},fx={["6ed76dba"]={q="Var kommer Khazgorm's Journal ifrån, och vem skrev den?",a="Prospector Khazgorm, en ledare bland dvärggrävarna från Explorers' League som är stationerade vid Bael Modan i södra The Barrens, skrev dagboken. Khazgorm använde boken för att dokumentera expeditionens fynd och vardagsliv medan de grävde sig fram genom Stonespire-taurenernas förfäders land.",al={"khazgorms dagboks ursprung","vem skrev khazgorm's journal","varifrån kommer khazgorm's journal"}}},fp="18,180,23.415.0,18.357.1,31.122.0,40.187.0,31.123.0,47.163.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="Klaven Mortwake's Journal",s="I en kista från Duskwood beskriver Klaven Mortwake's Journal hur Defias Brotherhood söker ett sätt att väcka de döda. SI:7-agenter återfann den i Defias-tornet i nordöstra Westfall.",h="I en kista från Duskwood beskriver Klaven Mortwake's Journal hur Defias Brotherhood söker ett sätt att väcka...",kw={"defias-tornet","duskwood chest","journal","klaven mortwake","mathias shaw","gifter","si:7","zanzil"},ang={["class:Rogue"]="Som skurk visar du din skicklighet i låsdyrkning och smygande genom att ta dig in i tornet och hämta Mortwakes journal. Uppdraget låter dig också bekanta dig med att brygga dödliga gifter.",["faction:Alliance"]="Som medlem av Alliansen ger du Stormwinds spionmästare bevis för att Defiasupproret sträcker sig bortom missnöjda arbetare. Journalen avslöjar band till trollens häxdoktorer och alkemisk nekromanti."},sec={{t="En fasansfull formel",b="Defias-tornet reser sig längs åsarna i norra Westfall, dit märkliga leveranser anländer från Duskwoods skuggiga gränstrakter. Förvridna, icke-mänskliga vaktposter bevakar tornet. SI:7 hade hållit platsen under uppsikt länge, och en journal i den översta kistan avslöjade vad leveranserna innehöll. Klaven Mortwake antecknade forskning om alkemiska metoder för att väcka viljelösa odöda drönare. Alkemister med kopplingar till Zanzil-trollen i Stranglethorn hade funnit ett sätt att göra det med särskilda gifter och brygder. Defias Brotherhood försökte kopiera deras metod för sina egna led."},{t="Underrättelser åt SI:7",b="Master Mathias Shaw leder Stormwinds underrättelsetjänst SI:7 och sökte efter Mortwakes journal för att spåra Brotherhoods vidare allianser. Anteckningarna bekräftar experiment med återupplivning och olagligt stöd som knyter samman Duskwood, Venture Company och Defias. För skurkar i kronans tjänst innebär forskningen ett steg mot att bemästra gifter."}},faq={{q="Vad är Klaven Mortwake's Journal?",a="Klaven Mortwake's Journal är en forskningsanteckningsbok sammanställd av Klaven Mortwake, en agent i Defias-tornet i nordöstra Westfall. Den innehåller anteckningar om alkemisk nekromanti och olagliga försörjningsvägar.",al={"vad är klavens journal","mortwake journal","vad är det här för föremål"}},{q="Var hittar man journalen?",a="Journalen är låst inuti en Duskwood Chest på översta våningen i Defias-tornet i norra Westfall. Odöda vaktposter bevakar den, och en nyckel som tas från en av Klavens monstruösa vakter öppnar kistan.",al={"var hittar man klavens journal","klaven journals plats","duskwood chest plats"}},{q="Vilka hemligheter står i journalen?",a="Journalen berättar att Zanzil-trollen i Stranglethorn Vale har utvecklat giftiga brygder som kan väcka och kontrollera de döda. Defias Brotherhood försökte få tag på receptet och använda det.",al={"vad står det i journalen","journalens hemligheter","zanzil-gift"}},{q="Vem vill ha journalen?",a="Master Mathias Shaw, ledare för Stormwinds underrättelsetjänst SI:7, vill ha journalen för att övervaka Defias försörjningsvägar och lära kronans agenter om farorna med och användningen av taktiska gifter.",al={"vem lämnar man in klaven journal till","vem ska jag ge journalen till","mathias shaw journal"}}},fx={["887d3337"]={q="Var kommer Klaven Mortwake's Journal ifrån, och vem skrev den?",a="Dagboken tillhör Klaven Mortwake, som övervakade Defias Brotherhoods fäste i tornet i Westfall. Den skickades tillsammans med illavarslande odöda vakter och en kista som kom från Duskwood. I den beskrivs mörka alkemiska hemligheter med ursprung hos Zanzil the Outcasts troll i Stranglethorn Vale.",al={"vem skrev klavens dagbok","klaven mortwake's journals ursprung","var fick klaven tag på dagboken"}}},fp="25,137,18.586.1,21.348.0,34.203.0,27.201.0,44.188.0,23.183.0"}
P.entries["item:kodo-bone"] = {n="Kodo Bone"}
P.entries["item:kodo-horn"] = {n="Kodo Horn",s="I The Barrens samlas Kodo Horns in från de kringströvande kodoserna. Tonga Runetotem använder dem i örtmediciner för förgiftade vilda djur.",h="I The Barrens samlas Kodo Horns in från de kringströvande kodoserna.",kw={"barrens","cenarion","earthroot","gasell","kodo horn","gift","tonga runetotem"},ang={["class:Druid"]="Som en Horde-druid samlar du horn under Tonga Runetotems ledning medan du lär dig att bemästra naturens gifter.",["race:Tauren"]="Som tauren hyser du stor vördnad för kodos och tar från dem varsamt och med ett tydligt syfte: att skydda The Barrens känsliga ekosystem."},sec={{t="En ingrediens från slätterna",b="I hela The Barrens använder Tonga Runetotem hela kodo horn i sina örtmediciner. Han arbetar från The Crossroads, där hornen hjälper till att stärka hans salvor. Flisor och fragment saknar den styrka han behöver, så han samlar hela horn från fullvuxna kodoser som strövar över slätterna."}},faq={{q="Vad används Kodo Horn till?",a="Tonga Runetotem använder Kodo Horns tillsammans med Earthroot och rent vatten för att brygga en salva åt förgiftade gaseller i hela The Barrens. Att tillreda läkemedlet ingår i en druids utbildning i naturliga botemedel mot gift.",al={"vad kodo horn används till","varför samla kodo horn","användning av kodo horn"}},{q="Var samlas hornen in?",a="Du kan samla dem från Barrens Kodos och Lost Barrens Kodos i norra The Barrens, mellan The Crossroads och det omgivande busklandet.",al={"var hitta kodo horn","kodo horns plats","vilka kodo-djur fäller horn"}},{q="Varför kan druider inte använda hornfragment i stället?",a="Tonga Runetotem säger att flisor och fragment inte har nog med kraft för att få salvan i balans. Han behöver hela horn för att göra ett läkemedel som är starkt nog att motverka kraftiga gifter.",al={"varför inte trasiga horn","hornflisor"}},{q="Är det respektfullt av en druid att jaga kodo-djur?",a="Ja. Druider jagar kodos när det tjänar naturens balans och tar det de behöver för att läka större farsoter, som den mystiska förgiftning som drabbar de inhemska gasellhjordarna.",al={"druid jagar kodo-djur","balans och kodo-djur"}}},fx={f5876d60={q="Vad är ett Kodo Horn?",a="Det är ett helt horn som tagits från de väldiga kodoerna som strövar omkring på de norra savannerna i The Barrens. Hela och stadiga horn används ofta i stamfolkens hantverk och verktyg och är eftertraktade av schamaner och druider som kraftfulla alkemiska reagenser. De kan ge läkande blandningar stor naturlig motståndskraft.",al={"vad är kodo horn","kodo horn","om kodo horn"}},["062d3e91"]={q="Var kommer Kodo Horns ifrån?",a="Hornen kommer direkt från kodoerna i The Barrens, som betar över de torra slätterna. När jägare och druider fäller ett av dessa mäktiga djur kan de ta ett helt horn, förutsatt att det inte har krossats eller nötts ner till enbart flisor och fragment.",al={"varifrån kommer kodo horn","kodo horns ursprung","hur får man tag på kodo horn"}}},fp="9,116,23.263.0,29.184.0,32.146.0,44.156.0,51.166.0"}
P.entries["item:kodo-kombobulator"] = {n="Kodo Kombobulator",s="Kodo Kombobulator låter Smeed Scrabblescrew tämja åldrade kodos i Desolace. Han använder den för att förse ett karavanpartnerskap med riddjur för färden.",h="Kodo Kombobulator låter Smeed Scrabblescrew tämja åldrade kodos i Desolace.",kw={"åldrad kodo","karavan","desolace","kodo","kodo kombobulator","smeed scrabblescrew","tämjning"},ang={["profession:Engineering"]="Som ingenjör kanske du känner igen det goblinska hantverket bakom Smeed Scrabblescrews anordning för att kontrollera åldrade kodos."},sec={{t="En goblins anordning",b="I Scrabblescrew's Camp i Desolace lånar Smeed Scrabblescrew ut Kodo Kombobulator för att tämja uråldriga eller åldrade kodos. Den ger varje best en stöt så att den följer efter honom och förser den lokala karavanen med nya riddjur. Smeed hoppas att partnerskapet ska ge honom en rejäl vinst."}},faq={{q="Vad gör Kodo Kombobulator?",a="Kodo Kombobulator tämjer uråldriga eller åldrade kodos och får dem att följa efter Smeed Scrabblescrew.",al={"kodoanordning","vad används kombobulatorn till"}},{q="Vem skapade Kodo Kombobulator?",a="Smeed Scrabblescrew säger att han lärde sig återuppliva och kontrollera åldrade och döende kodos med sin Kodo Kombobulator.",al={"vem äger kodoanordningen","smeeds anordning"}},{q="Varför vill Smeed ha tämjda kodos?",a="Smeed, karavanägaren Cork och Rigger ingick ett partnerskap kring hans förmåga att tämja kodos. Karavanen förlitar sig på hans tillgång.",al={"varför tämja kodos","kodos till karavanen"}},{q="Var hittar jag Kodo Kombobulator?",a="Smeed Scrabblescrew vid Scrabblescrew's Camp i Desolace tillhandahåller Kodo Kombobulator för sitt arbete med åldrade kodos.",al={"kombobulatorns plats","var är smeed"}}},fp="17,144,17.268.0,35.92.0,31.110.0,32.130.0,39.116.0"}
P.entries["item:kodo-liver"] = {n="Kodo Liver",s="I Ratchet behöver Brewmaster Drohn Kodo Liver till ett märkligt öl. Han lärde sig brygga troggöl av den kringvandrande bryggmästaren Chen Stormstout.",h="I Ratchet behöver Brewmaster Drohn Kodo Liver till ett märkligt öl.",kw={"the barrens","bryggning","chen stormstout","drohn","kodo","kodo liver","ratchet","troggöl"},ang={["profession:Cooking"]="Kodokött föder människor i hela centrala Kalimdor, men Kodo Liver anses vara för vidrig och illaluktande för vanlig matlagning. Dess användning i Ratchets troggöl har gjort den ökänd.",["race:Tauren"]="Tauren hedrar varje del av de kodos de jagar. Även härdade slättlöpare ser snett på gobliner och främlingar som gör noveltyöl av kodoinälvor i Ratchet."},sec={{t="En märklig brygdingrediens",b="Kodos strövar omkring i The Barrens, där tauren och rovdjur jagar dem för deras hudar och kött. I Ratchet använder Brewmaster Drohn en färsk Kodo Liver tillsammans med salivkörtlar från thunderhawks och blixtkörtlar för att brygga troggöl. Chen Stormstout lärde Drohn receptet, och Drohn säger att blandningen ger en kraftig kick åt äventyrslystna resenärer. Ingredienserna kommer från vildmarken i centrala Kalimdor."}},faq={{q="Vad används en Kodo Liver till?",a="Brewmaster Drohn i Ratchet använder Kodo Liver i troggöl. Chen Stormstout lärde honom receptet.",al={"kodo-lever användning","varför behövs kodo-lever","vad används kodo-lever till"}},{q="Vilka varelser ger en Kodo Liver?",a="Kodo Liver kommer från kodos i The Barrens, däribland vanliga, ulliga, vilsegångna och större kodos, samt Lakota'mani och Brontus.",al={"var får man kodo-lever","vem släpper kodo-lever","källa till kodo-lever"}},{q="Varför skulle någon ha organ i öl?",a="Brewmaster Drohn följer de egendomliga recept som Chen Stormstout lärde honom. I troggöl ger råa organ som Kodo Liver och elementarkörtlar drycken dess kick och skarpa smak.",al={"varför lever i öl","kodo-lever i alkohol"}}},fx={a4c717e9={q="Vad är Kodo Liver?",a="Det är ett inre organ som tas från de väldiga, tjockhudade kodoerna som strövar omkring på The Barrens slätter. Det är ingen vanlig krogmat, men dess kraftfulla egenskaper gör det till en eftertraktad ingrediens för excentriska bryggmästare som skapar brygder med en verkligt legendarisk styrka.",al={"vad är kodo liver","kodo liver i berättelsen","kodo liver"}},c325e464={q="Varifrån kommer Kodo Liver?",a="Det tas direkt från vilda kodoer som strövar omkring på The Barrens savann, från vanliga kringvandrande bestar till uråldriga jättar som Lakota'mani och Brontus. Jägare och äventyrare skär ut det efter att ha fällt de väldiga varelserna.",al={"var får man tag på kodo liver","vem släpper kodo liver","kodo liver källa"}},["328036a8"]={q="Varför vill Brewmaster Drohn ha Kodo Liver?",a="Brewmaster Drohn i Ratchet söker efter en färsk lever till ett ovanligt recept på troggöl, som den kringvandrande pandarenbryggmästaren Chen Stormstout lärde honom. Tillsammans med blixtkörtlar och åskhöksaliv ger levern den starka drycken dess utmärkande sting.",al={"varför behöver drohn kodo liver","vem vill ha kodo liver","vad används kodo liver till i uppdrag"}}},fp="10,128,25.371.0,30.101.0,35.127.0,42.165.0"}
P.entries["item:kodobane-s-head"] = {n="Kodobane's Head",s="Nära The Forgotten Pools bevisar Barak Kodobanes avhuggna huvud att den listige hövdingen är död. Orkkrigsherren Regthar Deathgate tar emot det som bevis på att centaurhotet där har brutits.",h="Nära The Forgotten Pools bevisar Barak Kodobanes avhuggna huvud att den listige hövdingen är död.",kw={"barak","the barrens","centaur","the crossroads","deathgate","the forgotten pools","kodobane","kolkar","regthar"},ang={["faction:Horde"]="The Barrens vägkorsning förbinder Orgrimmar och Thunder Bluff landvägen. Att kuva centaurledare som Kodobane hjälper till att hålla karavanlederna säkra.",["race:Tauren"]="I generationer drev centaurerna de nomadiska taurerna över Kalimdor till utrotningens rand. Att döda Barak Kodobane hämnas århundraden av blodspillan och skyddar betesmarkerna i Mulgore och The Barrens."},sec={{t="Ett krigsbyte",b="Kolkarstammarna i The Barrens har länge varit splittrade, men maktlystna krigsherrar hotar nu att samla dem till en armé. Barak Kodobane slog läger vid The Forgotten Pools frodiga vatten, där oasen erbjuder livsviktiga resurser och närliggande leder ligger öppna för räder. Regthar Deathgate, som är stationerad i en bunker väster om The Crossroads, kräver Kodobanes avhuggna huvud som bevis på att denne befälhavare inte längre kan samla sina fränder mot Horden."}},faq={{q="Vem var Barak Kodobane?",a="Barak Kodobane var en framstående hövding bland kolkarcentaurerna. Han var listig och kunde leda, till skillnad från många av sina odisciplinerade fränder. Han organiserade krigsband och slog läger kring The Forgotten Pools för att hävda kolkarnas dominans över norra The Barrens.",al={"barak kodobane","vem är kodobane","baraks historia"}},{q="Varför vill Regthar Deathgate ha hans huvud?",a="Regthar Deathgate har i uppdrag att säkra Hordens territorium i The Barrens. Centaurerna är vanligtvis splittrade, så ledare med taktiskt sinne pekas ut. Regthar kräver Kodobanes huvud för att försäkra sig om att hövdingen är död och inte bara har drivits bort.",al={"varför ta huvudet","regthar deathgates huvud","kodobanes belöning"}},{q="Var finns Barak Kodobane?",a="Barak Kodobane slår läger nära The Forgotten Pools, oasen i norr strax nordväst om The Crossroads i The Barrens.",al={"baraks plats","var finns kodobane","baraks återkomstplats"}},{q="Stoppar det Kolkar-hotet att döda Barak?",a="Nej. Barak Kodobane är den förste av flera krigsherrar som samlar kolkarna. Hans död stör deras närvaro vid The Forgotten Pools, men Verog the Dervish och Hezrul Bloodmark fortsätter att styra centaurernas angrepp över The Barrens.",al={"är centaurerna besegrade","vad händer när barak dör"}}},fx={["891c4b09"]={q="Vad är Kodobane's Head?",a="Det är det avhuggna huvudet från Barak Kodobane, en av de framstående hövdingarna bland kentaurerna i Kolkar i The Barrens. Det bevaras som ett fysiskt bevis på hövdingens död och vittnar om ett avgörande slag mot det samordnade kentaurhot som plågar hordens bosättningar nära The Forgotten Pools.",al={"vad är kodobane's head","föremålet barak kodobane's head","historien om baraks huvud"}}},fp="15,171,15.418.0,23.242.0,41.246.0,30.114.0,42.231.0"}
P.entries["item:kravel-s-crate"] = {n="Kravel's Crate",s="Kravel's Crate är ett tungt paket som skickats av Kravel Koalbeard från Mirage Raceway i The Shimmering Flats. Det är avsett för Nesingwary-expeditionen i Stranglethorn Vale och innehåller särskild jaktammunition för att fälla djungelns farligaste villebråd.",h="Kravel's Crate är ett tungt paket som skickats av Kravel Koalbeard från Mirage Raceway i The Shimmering Flats.",kw={"ammunition","hemet nesingwary","kravel koalbeard","kravel's crate","mirage raceway","the shimmering flats","stranglethorn vale"},ang={["class:Hunter"]="Lådan innehåller särskild tung ammunition, utformad för avancerade dvärgiska jaktgevär och anpassad för storviltsexpeditioner.",["race:Dwarf"]="Leveransen är en affär helt och hållet mellan dvärgar. Den knyter samman Kravel Koalbeards affärer i saltöknarna med den berömda Nesingwary-jaktgruppen i Eastern Kingdoms."},sec={{t="En leverans till djungeln",b="Den slugt affärsdrivande Kravel Koalbeard delar ut Kravel's Crate vid Mirage Raceway. Paketet gäller en oavslutad affär mellan kontinenter. En förmögen dvärgkund beställde det flera veckor tidigare, men leveransen dröjde så länge att köparen hann lämna Kalimdor helt och hållet. För att inte gå miste om en förmögen kunds gunst, som redan betalat för vidarebefordran, anförtror Kravel förbipasserande äventyrare uppgiften att bära lådan hela vägen till norra Stranglethorn Vale."},{t="Ammunition i specialkaliber",b="Trots sitt anspråkslösa utseende och saltskorpan som samlas på den i The Shimmering Flats, innehåller lådan dödligt gods: tung ammunition i specialkaliber, särskilt anpassad för jaktgevär. När den tas emot i expeditionens läger norr om Grom'gol, konstaterar mottagaren att de kraftfulla skotten är högt värderade av storviltsjägare och livsviktiga för att överleva rovdjuren som stryker omkring bland djungelns trädkronor."}},faq={{q="Vad finns i Kravel's Crate?",a="Lådan är fylld med jaktammunition i specialkaliber. De tunga kulorna är särskilt avsedda för storviltsgevär som används för att fälla farliga bestar i vildmarken.",al={"innehållet i lådan","lådans innehåll","vad finns i kravels låda"}},{q="Vem skickade Kravel's Crate?",a="Den skickas av Kravel Koalbeard, en dvärghandlare verksam bland racen och hasardspelen vid Mirage Raceway i The Shimmering Flats i Thousand Needles.",al={"vem lämnar över lådan","vem äger kravels låda"}},{q="Vart ska lådan levereras?",a="Lådan måste bäras till Nesingwarys jaktläger i norra Stranglethorn Vale, vid floden norr om Grom'gol Base Camp.",al={"vart ska lådan levereras","lådans destination","vem får kravels låda"}},{q="Varför blev leveransen försenad?",a="Paketet tog flera veckor på sig att nå saltöknarna i Thousand Needles. Under tiden hade kunden redan packat ihop och gett sig av till Stranglethorn Vales djungler.",al={"varför dröjde kravel så länge","varför blev det försenat"}}},fx={["3beca7b7"]={q="Vad är Kravel's Crate?",a="Det är ett tungt leveranspaket som Kravel Koalbeard har vid Mirage Raceway i The Shimmering Flats. Lådan är säkert packad för långväga transport genom Kalimdor och över Great Sea och innehåller särskild jaktutrustning avsedd för en expedition i Stranglethorn Vale vildmarker.",al={"vad är kravel's crate","information om kravel's crate","föremålet kravel's crate"}},["6061fde3"]={q="Varför vill någon ha Kravel's Crate?",a="Lådan innehåller ammunition av särskild kaliber som beställts för storviltsjakt. Nesingwary jaktexpedition i Stranglethorn Vale är beroende av tung och pålitlig ammunition för att fälla djungelns våldsammaste bestar, så den försenade leveransen är en viktig proviantering till lägret.",al={"varför vill nesingwary ha lådan","varför är kravel's crate viktig","syftet med kravel's crate"}}},fp="14,186,24.367.0,24.340.0,30.134.0,24.154.0,33.152.0,29.147.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="Kreenig Snarlsnout's Tusk",s="Vid The Crossroads söker Thork bevis på att Kreenig Snarlsnout har stupat. Hans bete markerar slutet på Razormane-ledarens attacker mot Hordens karavaner i norra The Barrens.",h="Vid The Crossroads söker Thork bevis på att Kreenig Snarlsnout har stupat.",kw={"the barrens","the crossroads","kreenig","quilboar","razormane","snarlsnout","thork","bete"},ang={["faction:Horde"]="Karavanerna för med sig vapen, förnödenheter och nybyggare från Durotar, och håller Hordens expansion in i The Barrens vid liv. Att ta med det här betet till Thork hjälper till att skydda dessa livlinor.",["race:Orc"]="För en orch från The Crossroads är det praktisk krigföring att ta en trofé från en besegrad befälhavare: det visar styrka och sprider panik bland fienden."},sec={{t="En trofé av krossade ambitioner",b="Hordens karavaner som färdas västerut från Durotar utsätts ständigt för attacker i The Barrens. Räderna blev djärvare under Kreenig Snarlsnout, en vildsint Razormane-ledare. Thork, befälhavare för vakten vid The Crossroads, beordrade att Kreenig skulle dödas för att störa quilboarnas samordning. Hans bete bevisar att ledaren är död och förolämpar Razormane, vilket försvagar deras beslutsamhet och lämnar deras krigare utan central ledning."}},faq={{q="Vem var Kreenig Snarlsnout?",a="Kreenig Snarlsnout ledde Razormane-quilboarna som slagit läger nordost om The Crossroads. Han organiserade attacker mot Hordens karavaner längs huvudvägen från Durotar, vilket gjorde försörjningsrutten farlig fram till hans död.",al={"kreenig snarlsnout","vem är kreenig","snarlsnout bakgrund"}},{q="Varför vill Thork ha just beten?",a="Thork vill ha beten som bevis på att Kreenig är död och som en förolämpning mot Razormane. Att ta beten från en fallen hövding sårar deras stolthet och demoraliserar de överlevande rövarna.",al={"varför beten","varför lämna beten till thork","thorks bete"}},{q="Varifrån kommer den här beten?",a="Beten kommer från Kreenig Snarlsnouts läger nordost om The Crossroads, nära bergens utlöpare strax söder om huvudvägens passage från Durotar in i The Barrens.",al={"var finns kreenig","var får man beten","snarlsnouts plats"}},{q="Hur påverkas The Barrens av att Kreenig dödas?",a="Thork tror att Razormane-rövarna kommer att tappa fotfästet utan Kreenigs ledarskap. Hans död kastar deras led i oordning och hejdar ytterligare attacker mot livsviktiga försändelser.",al={"upphörde räderna","följder av kreenigs död"}}},fx={["4371b9f1"]={q="Vad är Kreenig Snarlsnout's Tusk?",a="Det är en avhuggen quilboartand som tagits som ett dystert trofé från Kreenig Snarlsnout, ledaren för Razormane-rövarna nordost om The Crossroads. Thork krävde den både som obestridligt bevis på hövdingens död och för att ytterligare förödmjuka quilboarna, och visa den återstående stammen att deras rövarledare har fallit.",al={"vad är kreenigs bete","föremålet kreenig snarlsnout's tusk"}}},fp="25,173,28.413.0,27.207.0,42.176.0,26.185.0,57.174.0"}
P.entries["item:kron-s-amulet"] = {n="Kron's Amulet",s="Längs Southfury River bär Krons minnessak minnet av en ung orchjägare som försvann.",h="Längs Southfury River bär Krons minnessak minnet av en ung orchjägare som försvann.",kw={"amulett","dreadmaw crocolisk","kron","misha tor'kren","razor hill","southfury river"},ang={["class:Hunter"]="För en jägare är Krons öde en tydlig lärdom om faran med att underskatta grymma bestar i okända flodområden.",["race:Orc"]="Krons öde visar hur stolthet och jakten på krigisk ära kan få en orch att ignorera de äldres visdom, med dödliga följder."},sec={{t="Tragedi vid Southfury",b="Kron var en viljestark ung orch från en gård nordväst om Razor Hill. Fast besluten att bevisa sig gav han sig ut för att jaga de grymma Dreadmaw Crocolisks längs Southfury River, vid gränsen till The Barrens. Hans mor, Misha Tor'kren, varnade honom för faran, men stoltheten drev honom vidare. Kron återvände aldrig från floden. Hans amulett hittades inuti ett av rovdjuren och bekräftade att han hade dödats och slukats."}},faq={{q="Vem var Kron?",a="Kron var en viljestark ung orchjägare som bodde med sin mor, Misha Tor'kren, på en gård nordväst om Razor Hill. Han gav sig ensam av för att pröva sin styrka mot flodens bestar, trots varningarna om deras grymhet.",al={"vem är kron","krons bakgrund","kron berättelse"}},{q="Var hittar man Kron's Amulet?",a="Dreadmaw Crocolisks och Corrupted Dreadmaw Crocolisks längs Southfury Rivers stränder i Durotar bär amuletten i sina bukar.",al={"var hittar jag amuletten","kron's amulet plats","vem släpper kron's amulet"}},{q="Vem vill ha Kron's Amulet tillbaka?",a="Misha Tor'kren vill få tillbaka Kron's Amulet. Hon väntar på besked om sin son på gården nordväst om Razor Hill, och amuletten ger henne smärtsam bekräftelse på hans öde.",al={"vem behöver amuletten","var lämnar jag in kron's amulet","misha tor'kren"}}},fx={["5d838632"]={q="Vad är Kron's Amulet?",a="Den här personliga prydnaden tillhörde Kron, en ung orch från en gård nordväst om Razor Hill. Driven av stolthet och ivrig att bevisa sin styrka gav han sig ensam av mot Southfury River för att jaga de våldsamma Dreadmaw-krokoliskerna längs gränsen till The Barrens. I stället för att återvända i triumf föll han offer för bestarna han ville döda. Den här talismanen svaldes tillsammans med hans kvarlevor och är den enda del av den unge jägaren som finns kvar och kan bevisa hans dystra öde.",al={"vad är amuletten","kron's amulet i berättelsen","vem äger amuletten"}}},fp="13,87,24.445.1,13.218.0,29.141.1,33.172.1"}
P.entries["item:kurzen-s-head"] = {n="Kurzen's Head",s="Kurzen’s Head är beviset som rebellerna söker i sitt läger i Stranglethorn Vale. Lieutenant Doren behöver det för att ta reda på om Colonel Kurzens befäl har brutits.",h="Kurzen’s Head är beviset som rebellerna söker i sitt läger i Stranglethorn Vale.",kw={"colonel kurzen","kurzen","kurzen elite","kurzen subchief","kurzen’s head","lieutenant doren","rebel camp","stockpile","stranglethorn vale"},sec={{t="Bevis åt Doren",b="Lieutenant Doren väntar på Rebel Camp på besked från Stockpile, där Colonel Kurzen för befäl över sina män. Rebellerna möter Kurzen’s Elite och Subchiefs samt översten själv. Doren ber om Kurzen’s Head som bevis på att fiendens ledare har besegrats. Hans grupps säkerhet hänger på svaret."}},faq={{q="Vem vill ha Kurzen’s Head?",a="Lieutenant Doren på Rebel Camp ber om Kurzen’s Head som bevis på att Colonel Kurzen och hans ledare är besegrade.",al={"vem vill ha huvudet","doren huvud","var lämna kurzen’s head"}},{q="Var finns Colonel Kurzen?",a="Colonel Kurzen för befäl över sina män långt inne i Stockpile i Stranglethorn Vale.",al={"kurzens plats","var kurzen","stockpile person"}},{q="Varför behöver rebellerna Kurzen’s Head?",a="Rebellerna behöver Kurzen’s Head som bevis på att Colonel Kurzen och hans ledare har besegrats.",al={"varför huvudet","syftet med kurzen’s head","bevis åt doren"}},{q="Vilket hot utgör Kurzen?",a="Lieutenant Doren kallar Kurzen en grym och mäktig befälhavare vars män hotar rebellgruppen.",al={"kurzens hot","varför slåss mot kurzen","kurzens bakgrund"}},{q="Vad händer när Kurzen besegras?",a="Lieutenant Doren säger att Kurzans nederlag räddar rebellgruppen och låter dem andas ut.",al={"kurzen besegrad","vad händer med rebellerna","kurzens slut"}}},fp="13,169,15.307.0,26.114.0,24.85.0,39.96.0,29.97.0,37.90.1"}
P.entries["item:kuz-s-skull"] = {n="Kuz's Skull",s="I södra Barrens markerar Kuz's Skull slutet för en fruktad Razormane-rövare. Kuz kom från Razorfen Kraul och hjälpte till att leda anfall mot Hordens utposter innan en tillfångatagen före detta frände sökte hämnd.",h="I södra Barrens markerar Kuz's Skull slutet för en fruktad Razormane-rövare.",kw={"the barrens","camp taurajo","kuz","kuz's skull","lok orcbane","mangletooth","nak","razormane"},ang={["faction:Horde"]="Som medlem av Horden hjälper du till att skydda bosättningar som The Crossroads och Camp Taurajo från organiserade quilboar-anfall genom att ta Kuzs huvud."},sec={{t="En bitter fejd",b="Kuz, Nak och deras hövding Lok Orcbane ledde Razormane-anfall genom södra Barrens. De tre rövarna skickades från Razorfen Kraul och angrep resande och bosättningar som The Crossroads. Deras svek mot Mangletooth, en annan quilboar, vände en av deras egna mot dem. De lämnade Mangletooth att ruttna i en bur vid Camp Taurajo. Från buren avslöjade han var Kuz fanns för Hordens hjältar, om de var villiga att döda rövaren och ta hennes huvud."},{t="Bevis på vedergällning",b="Kuz's Skull bevisar för Mangletooth att en av de tre ledarna för den södra krigshopen är död. För honom ger huvudet upprättelse mot stammen som övergav honom. Över The Barrens bryter Kuzs död befälet bakom Razormane-anfallen och ger försörjningsvägarna över slätterna en kort andhämtningspaus."}},faq={{q="Vem var Kuz?",a="Kuz var en av tre Razormane-quilboar som skickades från Razorfen Kraul till södra Barrens. Tillsammans med Nak och Lok Orcbane ledde hon bakhåll och räder mot Hordens läger och försörjningslinjer.",al={"vem är kuz","kuzs bakgrund","kuz razormane"}},{q="Varför vill Mangletooth ha Kuzs skalle?",a="Mangletooth vill ha Kuzs skalle eftersom Kuz och de andra Razormane lämnade honom att dö i en bur vid Camp Taurajo. Han söker hämnd innan han själv dör, visar Hordens hjältar vägen till sina rivaler och ber om deras skallar som bevis.",al={"varför mangletooth vill döda kuz","mangletooths hämnd"}},{q="Var hittar man Kuz i The Barrens?",a="Kuz finns i södra Barrens, bland Razormane-quilboar söder om Camp Taurajo nära de taggiga gränstrakterna.",al={"kuzs plats","var hittar man kuz"}},{q="Vad händer efter att Kuz dödats?",a="När Kuz's Skull och huvudena från Nak och Lok Orcbane når Mangletooth bryter de ledarskapet bakom Razormane-anfallen och hjälper till att säkra handelsvägarna i söder.",al={"kuzs uppdragsbelöning","följder av förräderi inifrån"}}},fx={["9baef7d0"]={q="Varifrån kommer Kuz's Skull?",a="Skallen tas direkt från kvarlevorna efter Kuz, en framstående Razormane-quilboar som höll till i södra The Barrens. Kuz kom från Razorfen Kraul tillsammans med sina rövarkamrater och hjälpte till att organisera våldsamma attacker mot horden innan hon jagades ned.",al={"varifrån kom kuz's skull","vem gjorde kuz's skull","kuz's skull ursprung"}}},fp="11,189,13.399.0,20.287.1,12.193.0,38.228.0,34.120.0,32.167.0"}
P.entries["item:laced-pumpkin"] = {n="Laced Pumpkin",s="En Laced Pumpkin är en vanlig pumpa som behandlats med en dödlig brygd, utvecklad av Apothecary Johaan i Brill. Den ges som föda till en svältande, fängslad Scarlet Crusader under förevändning att den ska stilla hungern. På så sätt blir den ett fälttest av de Forsaknas växande arsenal av alkemiska vapen.",h="En Laced Pumpkin är en vanlig pumpa som behandlats med en dödlig brygd, utvecklad av Apothecary Johaan i...",kw={"apothecary johaan","brill","captured scarlet zealot","gallows' end","laced pumpkin","royal apothecary society","tirisfal glades"},ang={["faction:Alliance"]="Den fångade zealotens öde är en tydlig och fasansfull påminnelse om vad som väntar levande människor som tillfångatas i Forsaknas områden.",["race:Undead"]="För Forsakna visar förvandlingen av vanlig mat till ett vapen hur pragmatiskt Royal Apothecary Society använder alla medel som krävs för att skydda Tirisfal mot fanatiska levande korsfarare."},sec={{t="En bitter skörd",b="För ett otränat öga ser den spetsade pumpan ut som vanliga grödor, räddade från den fördärvade jorden i Tirisfal Glades. Under Apothecary Johaans överinseende i Brill behandlas grönsaken dock med experimentella gifter, avsedda att förverkliga de odödas fulla potential. Royal Apothecary Society söker ständigt nya vapen för att slå tillbaka både Scourge i norr och levande människostyrkor som rycker fram från söder. Därför blir även enkla skördevaror bärare av smitta och kemisk död."},{t="Experimentet i källaren",b="Laced Pumpkins främsta syfte är praktiska tester på levande försökspersoner. I den fuktiga källaren under Gallows' End Tavern håller Forsakna fångvaktare en utsvulten Captured Scarlet Zealot fången. Fången är desperat efter mat och tar tacksamt emot det förgiftade erbjudandet. När han äter pumpan utlöser apotekarens brygd en våldsam förvandling. Den vrider den mänskliga zealoten till en tanklös ghoul, som stapplar omkring en kort stund i vånda innan den faller död till golvet av kall sten."}},faq={{q="Vad är Laced Pumpkin?",a="Det är en fältpumpa som injicerats med en experimentell formel, tillredd av Apothecary Johaan i Brill. Den ska testa hur Forsaknas alkemi påverkar levande försökspersoner.",al={"laced pumpkin","förgiftad pumpa","johaans pumpa"}},{q="Vem äter Laced Pumpkin?",a="En Captured Scarlet Zealot som hålls fången i källaren under Gallows' End Tavern i Brill äter den efter att fångvaktarna låtit honom svälta.",al={"vem äter den","pumpans mål","mata med pumpan"}},{q="Vad händer när någon äter pumpan?",a="Pumpan ges till den fångade zealoten för att testa Johaans senaste formel. Dess exakta effekter avslöjas när fången äter den.",al={"pumpans effekt","vad händer med zealoten","zealot ghoul"}},{q="Varför tillverkade Forsakna den?",a="Apothecary Johaan och Royal Apothecary Society testar nya biologiska brygder för att bekämpa både Scourge i norr och levande människor som tränger fram. De använder tillfångatagna fiender som försökspersoner.",al={"varför göra en förgiftad pumpa","forsaknas pesttester"}}},fx={["242570cd"]={q="Varifrån kommer Laced Pumpkin, och vem gjorde den?",a="Apothecary Johaan tillredde den här pumpan i Brill. Han sökte vapen för att försvara de Förfallna mot Scourge i norr och de levande människorna i söder, så han skördade vanliga grönsaker från Solliden Farmstead och behandlade dem med sin experimentella förruttnelsebrygd.",al={"vem gjorde laced pumpkin","varifrån kom laced pumpkin","skaparen av laced pumpkin"}},["071bacef"]={q="Varför vill någon ha Laced Pumpkin?",a="Apothecary Johaan behöver ge pumpan till en levande försöksperson för att utvärdera sin senaste kemiska formel. Den ges till en svältande fånge från Scarlet Crusade, som sitter inlåst i källaren under Gallows' End Tavern i Brill. Det blir ett dödligt test av Royal Apothecary Societys forskning.",al={"varför vill man ha laced pumpkin","varför använda laced pumpkin","vad behövs laced pumpkin till"}}},fp="13,177,16.375.0,21.383.1,26.160.0,27.168.0,43.170.1,31.201.0"}
P.entries["item:laden-dew-gland"] = {n="Laden Dew Gland",s="En Laden Dew Gland innehåller vatten som en daggsamlare har samlat in i Tanaris. Marin Noggenfogger i Gadgetzan vill ha en för att stilla sin törst.",h="En Laden Dew Gland innehåller vatten som en daggsamlare har samlat in i Tanaris.",kw={"daggsamlare","daggkörtel","laden dew gland","marin noggenfogger","tanaris","thistleshrub valley"},sec={{t="Vatten åt Marin",b="Sydväst om Gadgetzan ligger Thistleshrub Valley, där daggsamlare lagrar vatten i särskilda körtlar. Marin Noggenfogger ber dig hämta en Laden Dew Gland i hopp om att den ska stilla hans svåra törst."}},faq={{q="Vad är en Laden Dew Gland?",a="En Laden Dew Gland är ett vattenfyllt organ som daggsamlare bär i Thistleshrub Valley.",al={"daggkörtel","fylld körtel"}},{q="Vem vill ha körteln?",a="Marin Noggenfogger i Gadgetzan vill ha en Laden Dew Gland för att försöka stilla sin törst.",al={"vem behöver en daggkörtel","marins körtel"}},{q="Var hittar jag en Laden Dew Gland?",a="Thistleshrub Dew Collectors i Thistleshrub Valley, sydväst om Gadgetzan, bär på Laden Dew Glands.",al={"daggkörtelns plats","var finns körteln i tanaris"}},{q="Varför vill Marin ha den?",a="Marin hoppas att vattnet i körteln ska bli en dryck som stillar hans svåra törst.",al={"marin törstig","varför daggkörtel"}}},fp="15,131,15.208.0,26.91.0,20.84.0,34.99.0,23.94.0"}
P.entries["item:laird-s-response"] = {n="Laird's Response",s="Laird's Response är ett förseglat brev skrivet av fiskberedaren Laird i kusthamnen Auberdine. Brevet är avsett för Nessa Shadowsong i Rut'theran Village och beskriver märkliga ekologiska skillnader mellan fastlandets marina liv och de ovanligt stora fiskarna som trivs längs Teldrassils stränder.",h="Laird's Response är ett förseglat brev skrivet av fiskberedaren Laird i kusthamnen Auberdine.",kw={"auberdine","darkshore","fiske","laird","laird's response","nessa shadowsong","rut'theran village","teldrassil"},ang={["race:NightElf"]="För Night Elves som vakar över Teldrassils stränder ger Lairds anteckningar en fascinerande, om än en smula oroande, ledtråd om hur det unga World Tree redan utövar ett onaturligt inflytande över naturen omkring sig."},sec={{t="En fråga om fjäll och rötter",b="Efter att ha granskat fångstrapporter från hela Veiled Sea noterade Laird från Auberdine en slående skillnad: fisken som dras upp utanför Teldrassils kust är anmärkningsvärt större och rikligare än den som fångas längs Darkshores fastlandsstränder. I sitt skriftliga svar till Nessa Shadowsong delar Laird sin arbetsteori: det nyplanterade World Trees onaturliga närvaro och råa livskraft kan förvränga och stimulera det marina livet i omgivningen. Brevet, som bärs över vattnet av återvändande resenärer, väcker förundran och stilla nyfikenhet bland fiskarna i Rut'theran Village."}},faq={{q="Vad är Laird's Response?",a="Det är ett brev skrivet av Laird, en fiskhandlare och fiskberedare stationerad i Auberdine, som svar på en förfrågan från Nessa Shadowsong i Teldrassil.",al={"vad är det här föremålet","lairds response brev","vad är lairds response"}},{q="Vem skriver Laird till?",a="Svaret skickas till Nessa Shadowsong, en Night Elf som bor i Rut'theran Village vid Teldrassils södra fot.",al={"vem får lairds response","vem får det här brevet","nessas brev från laird"}},{q="Vad står det i brevet om fisken?",a="Laird noterar att fisk som fångas längs Teldrassils stränder är betydligt större och rikligare än den i Darkshore på fastlandet, vilket antyder att World Tree självt kan påverka det lokala marina livet.",al={"varför är fiskarna stora","skillnad på fiskar i darkshore och teldrassil","vad upptäckte laird"}},{q="Hur kommer meddelandet tillbaka till Rut'theran Village?",a="Bärarna kan antingen ta den reguljära färjan från Auberdines kajer eller ordna en hippogryfflykt med flygmästaren Caylais Moonfeather.",al={"hur tar man sig tillbaka till nessa","båt från darkshore till rut'theran","färja från auberdine till nessa"}}},fx={aee914ad={q="Varifrån kommer Laird's Response, och vem skrev den?",a="Det här skriftliga svaret är författat av Laird, en invånare i Auberdine vid Darkshores kust. Han skriver det som svar på frågor om det lokala marina livet, som skickats över havet från Rut'theran Village.",al={"vem skrev laird's response","varifrån kommer laird's response","laird's response ursprung"}},fb1c817f={q="Varför vill Nessa ha Laird's Response?",a="Nessa Shadowsong i Rut'theran Village väntar ivrigt på Lairds observationer om hur fångsterna på fastlandet skiljer sig från dem i Teldrassils vatten. De märkliga, överdimensionerade fiskarna kring Världsträdets väldiga grenar har förbryllat fiskare, och Lairds anteckningar bekräftar att det inte finns något liknande på Darkshores fastland. Det tyder på att Teldrassil själv förändrar det lokala djurlivet.",al={"varför vill nessa ha laird's response","varför efterfrågas laird's response","vem vill ha laird's response"}}},fp="16,154,28.461.0,25.127.0,24.108.0,40.176.0,55.135.0"}
P.entries["item:lake-creeper-moss"] = {n="Lake Creeper Moss",s="Lake Creeper Moss är en organisk förening som utvinns ur de vattenlevande kräldjur som lever bland The Dawning Isles i Lake Lordamere. Den är ett viktigt reagens som Royal Apothecary Society behöver för sina försök att framställa en dödlig ny farsot.",h="Lake Creeper Moss är en organisk förening som utvinns ur de vattenlevande kräldjur som lever bland The...",kw={"berard","the dawning isles","elder lake creeper","faranell","lake creeper","lake creeper moss","lake lordamere","new plague","royal apothecary society"},ang={["profession:Herbalism"]="Mossan växer naturligt på vattenbestar snarare än i vanlig jord, men hör till Lordaerons mörkare, experimentella flora som skördas för alkemistisk forskning.",["race:Undead"]="Varje prov av sjömossa som förs till Apothecarium för Forsaken närmare att fullända New Plague och utkräva hämnd på både Scourge och de levande."},sec={{t="Alkemisk skörd",b="Lake Creeper Moss växer på huden hos de grymma sötvattensbestar som strövar kring de södra Dawning Isles i Lake Lordamere. Dess unika egenskaper har formats av Lordaerons fördärvade vatten. Innan Arugals förbannelse tog hans förstånd dokumenterade Apothecary Berard mossens likhet med spårämnen på fossilen efter varelser som dödats av en uråldrig farsot i sjön. När Forsaken-agenter hittar prover skickas de direkt till Apothecarium i Undercity, där de används i Master Apothecary Faranells mörka forskning."},{t="Bränsle till den nya farsoten",b="Mossan är mer än en märklig vattenväxt. Den utgör ett kritiskt steg i utvecklingen av Forsakens signaturvapen. Tillsammans med den besläktade mossan från Lake Skulkers och sjuka tumörer från lokala Vile Fin-murlocer ger Lake Creeper Moss den organiska grund som behövs för att förädla en stam som kan utrota både levande vävnad och Scourge. Trots att alkemisten som upptäckte dess användning gått förlorad fortsätter Royal Apothecary Society att brygga hans recept i Dark Ladys tjänst."}},faq={{q="Vad används Lake Creeper Moss till?",a="Det är ett alkemiskt reagens som Master Apothecary Faranell och Royal Apothecary Society använder för att brygga och förädla sin New Plague i Undercity.",al={"vad används creeper moss till","varför samla lake creeper moss","lake creeper moss användning"}},{q="Varifrån kommer den här mossan?",a="Den samlas in från Lake Creepers och Elder Lake Creepers som lever i vattnen kring de södra Dawning Isles i östra Lake Lordamere.",al={"var hittar man creeper moss","creepermossens plats","lake creeper plats"}},{q="Vem upptäckte mossans alkemiska värde?",a="Apothecary Berard dokumenterade mossans unika egenskaper i sin fältjournal innan Arugals förbannelse gjorde honom till en tanklös tjänare i Pyrewood Village. Hans anteckningar återfanns senare av Apothecary Renferrel.",al={"vem hittade mossan","berards mossa","vem skrev om creeper moss"}},{q="Vem tar emot den insamlade mossan?",a="Master Apothecary Faranell tar emot mossan i Apothecarium i Undercity och kombinerar den med Lake Skulker Moss och en Hardened Tumor för att föra sin forskning framåt.",al={"vem vill ha creeper moss","lämna in creeper moss","faranells mossa"}}},fx={["70aadfdf"]={q="Vad är Lake Creeper Moss?",a="Lake Creeper Moss är en organisk tillväxt som skördas direkt från kropparna hos de vattenlevande creeper-varelserna i Lake Lordamere. Den ser ut som vanlig sumpväxtlighet, men Royal Apothecary Society värdesätter den som ett viktigt reagens i sina mörka experiment.",al={"vad är creepermossa","lake creeper moss i berättelsen","förklaring av creepermossa"}}},fp="17,190,18.486.0,22.414.1,35.160.0,31.139.0,43.207.0,32.158.0"}
P.entries["item:lake-skulker-moss"] = {n="Lake Skulker Moss",s="Lake Skulker Moss är ett biologiskt reagens som samlas in från träskbestarna i de norra delarna av Lake Lordamere. Apothecary Berard identifierade det, innan Arugals förbannelse tog hans förstånd, som en viktig organisk beståndsdel i Royal Apothecary Societys forskning om att brygga en New Plague.",h="Lake Skulker Moss är ett biologiskt reagens som samlas in från träskbestarna i de norra delarna av Lake...",kw={"berard","the dawning isles","faranell","lake lordamere","lake skulker","lake skulker moss","new plague","renferrel"},ang={["race:Undead"]="Varje skörd av mossa för Royal Apothecary Society ett steg närmare att fullända The New Plague, Forsakens främsta vapen mot både Scourge och de levande."},sec={{t="Ett pestreaktiv",b="Den här fuktiga vattenmossan skördas från de mossbevuxna kropparna hos Lake Skulkers och Elder Lake Skulkers på The Dawning Isles och har egenskaper som Forsaken-alkemister värdesätter. Innan Arugals förbannelse tog hans förstånd katalogiserade Apothecary Berard noggrant östra Silverpine Forests växter och djur. I sin journal drog han slutsatsen att både Lake Skulker Moss och Lake Creeper Moss kunde fungera som stabiliserande eller reaktiva ämnen. Efter att Berard blivit Arugals viljelösa tjänare återfanns hans journal i Pyrewood Village åt Apothecary Renferrel. Renferrel beordrade Forsaken-mästare att samla mossprover och en sällsynt tumör från lokala Vile Fin-murlocer och leverera dem direkt till Master Apothecary Faranell i Undercity."}},faq={{q="Vad används Lake Skulker Moss till?",a="Royal Apothecary Society i Undercity använder den som en organisk basingrediens för att tillverka The New Plague, i Lady Sylvanas Windrunners och Forsakens tjänst.",al={"användning av mossa","varför samla skulker-mossa","vad gör skulker-mossa"}},{q="Var kommer mossan ifrån?",a="Mossan skrapas från kropparna hos Lake Skulkers och Elder Lake Skulkers, vattenbestar som lever i vattnen kring The Dawning Isles i nordöstra Lake Lordamere, utanför Silverpine Forests kust.",al={"var hittar man skulker-mossa","skulker-mossans plats","vem släpper lake skulker moss"}},{q="Vem upptäckte mossans användbarhet?",a="Apothecary Berard identifierade först dess potential under sin fältforskning i Silverpine Forest. Arugals förbannelse gjorde Berard till en viljelös tjänare, men hans bevarade journal vägledde Apothecary Renferrel och Master Apothecary Faranell när de fortsatte hans experiment.",al={"vem hittade mossan","berards mossa","apothecary berards forskning"}},{q="Vem behöver det här reagenset?",a="Master Apothecary Faranell, ledaren för Royal Apothecary Society som bor i Apothecarium i Undercity, behöver mossan för att föra sina projekt inom biologisk krigföring framåt.",al={"vem vill ha skulker-mossa","faranell och skulker-mossa"}}},fx={["18c0a856"]={q="Vad är Lake Skulker Moss?",a="Lake Skulker Moss är en naturlig tillväxt som skördas från ryggarna på sjöskulkers, groddjursliknande bestar som lurar kring The Dawning Isles i Lake Lordamere. Den är obetydlig för fiskare och resande, men detta organiska material har särskilda egenskaper som väckt intresset hos Förfallna alkemister som studerar den lokala floran och faunan.",al={"vad är lake skulker moss","information om lake skulker moss","förklaring av skulkmossa"}}},fp="17,194,16.613.0,35.178.0,31.179.0,37.225.0,26.149.0"}
P.entries["item:large-candle"] = {n="Large Candle",s="I Elwynn Forests gruvor bär kobolder Large Candle på huvudet för att få ljus och vax. Lågorna visar dem vägen genom mörka tunnlar, och apotekare värdesätter vaxet.",h="I Elwynn Forests gruvor bär kobolder Large Candle på huvudet för att få ljus och vax.",kw={"fargodeep mine","goldshire","goldtooth","jasperlode mine","kobolders ljus","large candle","vax","william pestle"},ang={["faction:Alliance"]="Genom att ta ljus från kobolder i Elwynn försvagar alliansens äventyrare skadedjuren i gruvorna och förser Stormwinds apotekshandel med viktiga material.",["profession:Mining"]="Gruvarbetare som arbetar i ådrorna i Fargodeep och Jasperlode råkar regelbundet ut för koboldangrepp. Kobolderna vill åt både guldet och ljuset från Large Candle."},sec={{t="Ljus och vax under jord",b="Kobolder använder stearinljusens lågor för att hitta genom de mörka schakten under Elwynn Forest. De fäster ljusen på huvudet, och Kobold Miners, Tunnelers och Geomancers försvarar dem ursinnigt mot inkräktare. Large Candle som bärs i Fargodeep Mine och Jasperlode Mine är grovt tillverkade, men vaxet är värdefullt. Ytans handelsmän kan inte enkelt framställa det i stora mängder, så ljusen är både verktyg för kobolderna och en handelsvara för alkemister."},{t="Handel och apotekaren",b="William Pestle, en apotekare från Stormwind City, samlar in Large Candle på Lion's Pride Inn i Goldshire. Hans familj driver ett apotek, och han behöver smält vax till dess brygder, salvor och krämer. Pestle anlitar äventyrare på genomresa för att rensa de angripna gruvorna och ta ljus från kobolderna."}},faq={{q="Vad används Large Candle till?",a="William Pestle samlar in Large Candle i Goldshire åt apoteket som han driver tillsammans med sin bror i Stormwind City. De smälter ner ljusen till vax som används i krämer, salvor och alkemiska recept.",al={"användning av large candle","varför samla large candle","vem vill ha large candle"}},{q="Var hittar man Large Candle?",a="Kobolder bär Large Candle i Elwynn Forests gruvor, särskilt i Fargodeep Mine söder om Goldshire och Jasperlode Mine österut. Tunnelers, Miners och Geomancers bär dem.",al={"large candle plats","var får man tag på large candle","kobolders ljusbyte"}},{q="Varför bär kobolder ljus på huvudet?",a="Kobolder använder stearinljus för att gräva och hitta genom mörka underjordiska tunnlar. De fäster ljusen på huvudet så att händerna är fria för hackor, geomantisk besvärjelsekonst och vapen.",al={"varför har kobolder ljus","kobolder med ljus på huvudet lore"}},{q="Vem är William Pestle?",a="William Pestle är en apotekare från Stormwind City som sköter affärer på Goldshires Lion's Pride Inn. Han samlar in råvaror från vildmarken och gruvorna för att försörja apoteket som han driver tillsammans med sin bror.",al={"william pestle lore","vem är apotekaren i goldshire"}}},fx={["05873d56"]={q="Vad är Large Candle?",a="Large Candle är ett grovt, kraftigt vaxljus som bärs av kobolderna som bor i gruvorna i Elwynn Forest. Kobolderna är ökända för att vakta sina ljuskällor och använder de rejäla ljusen för att lysa upp mörkret i underjordiska tunnlar, som gruvorna Fargodeep och Jasperlode, medan de gräver efter guld och mineraler.",al={"vad är large candle","large candle i elwynn","historien om large candle"}}},fp="12,108,26.430.0,24.316.0,32.199.0,33.177.0,44.194.0,22.229.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="Large Soran'ruk Fragment",s="Large Soran'ruk Fragment vilar i Shadowfang Keep, långt från de andra skärvorna. Dess krossade klot rymde en gång en vanärad demon från Burning Legion.",h="Large Soran'ruk Fragment vilar i Shadowfang Keep, långt från de andra skärvorna.",kw={"burning legion","doan karhan","large soran'ruk fragment","orb of soran'ruk","shadowfang keep","soran'ruk"},ang={["class:Warlock"]="När du återtar Large Soran'ruk Fragment kan du bemästra den fångade demonanden inuti och hjälpa Doan Karhan att återskapa ett mäktigt vapen för demonisk magi."},sec={{t="Arvet efter Soran'ruk",b="Vanärade demoner från Burning Legion kan dömas till fångenskap i förtrollade klot. Magiker och häxmästare som står på Burning Legions sida får dessa kärl och hämtar kraft ur de kaoskrafter som fångats inuti. Även när ett klot krossas utstrålar dess bundna varelses kvarvarande essens fortfarande kraft. Varje fragment lockar till sig ambitiösa utövare av skuggmagi."},{t="Skärvan i Shadowfang",b="Soran'ruks klot sprack i två delar för länge sedan. Kultister på andra håll spred den ena halvan i mindre bitar. En trollkarl i det fördömda Shadowfang Keep lade beslag på den större halvan. Shadowfang Darksouls bär Large Soran'ruk Fragment, som håller den bundna anden fången tills någon försöker återskapa det uråldriga kärlet."}},faq={{q="Vad är Large Soran'ruk Fragment?",a="Large Soran'ruk Fragment är den större halvan av Orb of Soran'ruk, ett uråldrigt kärl som håller den bundna anden från en vanärad demon ur Burning Legion fången.",al={"large soran'ruk fragment","stor soran'ruk-skärva","vad är den här skärvan"}},{q="Var finns skärvan?",a="Shadowfang Darksouls håller fragmentet i Shadowfang Keep, en hemsökt fästning i Silverpine Forest.",al={"var hittar jag den stora skärvan","den stora skärvans plats","vem släpper large soran'ruk fragment"}},{q="Varför krossades klotet?",a="Det ursprungliga klotet delades i två huvuddelar. Den mindre halvan slogs sönder i skärvor och fördes till kustgrottorna i Blackfathom Deeps, medan mörka trollkarlar behöll den större halvan i Shadowfang Keep.",al={"hur gick klotet sönder","varför är klotet i skärvor","soran'ruks klots historia"}},{q="Vem vill sätta ihop det igen?",a="Doan Karhan, en tillbakadragen eremit i södra Barrens, har vigt sitt liv åt att studera och återskapa Burning Legions förlorade klot.",al={"vem behöver den stora skärvan","vem sätter ihop klotet igen"}}},fx={["0cdd1dfd"]={q="Varifrån kommer Large Soran'ruk Fragment, och vem gjorde det?",a="Fragmentet var en gång en del av Orb of Soran'ruk, en artefakt skapad av Burning Legion. När demoner från Legion förlorar sin gunst binds deras andar i klot som ges till dödliga magiker och häxmästare. Soran'ruk var en sådan demon, vars essens fängslades för att driva demonisk magi. Klotet delades senare i två delar, och den större skärvan hamnade hos en mörk besvärjare i Shadowfang Keep.",al={"soran'ruk-fragmentets ursprung","vem skapade orb of soran'ruk","varifrån kom soran'ruk"}}},fp="24,146,23.317.0,23.330.0,37.138.0,28.99.0,23.199.0,27.145.0"}
P.entries["item:large-stone-slab"] = {n="Large Stone Slab",s="Large Stone Slabs är stenstycken från jordelementärer i Badlands. Lotwil Veriatus behöver dem för att testa sina besvärjelser.",h="Large Stone Slabs är stenstycken från jordelementärer i Badlands.",kw={"badlands","elementär","large stone slab","lotwil veriatus","jordelementär","sten","stenplatta"},ang={["race:Tauren"]="Lotwil förundras över att en enda tauren kom med stenarna och säger att han hade väntat sig att det skulle krävas ett halvdussin."},sec={{t="Sten för studier",b="Väster om Lotwil Veriatus i Badlands bär jordelementärer på stenarna han söker. Deras större och starkare kroppar ger bitar som passar hans tester. Lotwil tror att hans besvärjelser kan hjälpa honom att kontrollera elementärer, och stenarna är en del av det arbetet."}},faq={{q="Var kommer Large Stone Slabs ifrån?",a="Jordelementärer i Badlands bär på Large Stone Slabs. Lotwil Veriatus pekar ut kullarna väster om honom och bergssidorna i närheten.",al={"varifrån kommer stenarna","stenarnas ursprung"}},{q="Vem vill ha stenarna?",a="Lotwil Veriatus behöver Large Stone Slabs för att testa besvärjelser som ska kontrollera elementärer.",al={"vem behöver stenarna","lotwils sten"}},{q="Varför vill Lotwil ha dem?",a="Lotwil testar sina besvärjelser på stenarna och hoppas kunna använda dem i experiment för att kontrollera elementärer.",al={"varför stenar","vad används stenarna till"}},{q="Vilka elementärer bär på dem?",a="Jordelementärer bär på stenarna Lotwil söker. Enligt hans vägbeskrivning finns de väster om honom och längs bergssidorna.",al={"vad är en jordelementär","vilka stenar"}}},fp="16,122,15.246.0,37.141.0,20.92.0,26.94.0,28.113.0"}
P.entries["item:laughing-sister-s-hair"] = {n="Laughing Sister's Hair",s="Laughing Sister's Hair består av mjuka, magiska hårlockar från dryader i Ashenvales förtrollade skogar. Skickliga vävare söker dem, eftersom lockarna har medfödda mystiska egenskaper som passar fint tillverkade klädnader.",h="Laughing Sister's Hair består av mjuka, magiska hårlockar från dryader i Ashenvales förtrollade skogar.",kw={"ashenvale","tyg","the crossroads","deino","dryad","hår","kil'hala","laughing sister","raynewood retreat"},ang={["faction:Horde"]="För att få tag på lockarna måste man tränga in på nattalvernas territorium i Ashenvale och döda skogsandar. Det visar att Horden är beredd att med våld skörda traktens magi.",["profession:Tailoring"]="Dryadernas eteriska lockar är en av de mest exotiska trådkällorna i Kalimdor och uppskattas för sin förmåga att binda medfödd naturmagi i tyg."},sec={{t="En sällsynt vävkomponent",b="Håret samlas från de dryader som kallas laughing sisters nära Raynewood Retreat i Ashenvale, och bär på anmärkningsvärd naturmagi. Dryaderna är heliga skogsväktare med band till Cenarius och nattalverna, men hantverkare i Horden värdesätter håret enbart som ett kraftfullt hantverksämne. Trollskräddaren Kil'hala vid The Crossroads spinner lockarna till förtrollade klädnader åt blivande utövare av arkan magi."}},faq={{q="Varifrån kommer Laughing Sister's Hair?",a="Håret samlas från laughing sisters, dryader som strövar i de förtrollade lundarna nära Raynewood Retreat i centrala Ashenvale.",al={"var hittar man laughing sisters hår","laughing sister hår plats","källa till dryadhår"}},{q="Varför letar Kil'hala efter dryadhår?",a="Kil'hala är en skräddare vid The Crossroads i The Barrens. Han använder de magiska hårstråna för att väva förtrollade tygklädnader åt Deinos lovande elever.",al={"varför kil'hala vill ha hår","användning av laughing sister's hair","trollskräddare dryadhår"}},{q="Ger laughing sisters ifrån sig sitt hår frivilligt?",a="Nej. laughing sisters är hårdföra naturväktare och svurna beskyddare av Ashenvale. Som Kil'hala torrt påpekar skulle dryader aldrig frivilligt ge sitt hår till Hordens agenter.",al={"kan man be dryader om hår","ger dryader bort hår"}}},fx={["3a458879"]={q="Vad är Laughing Sister's Hair?",a="Laughing Sister's Hair består av avklippta lockar från skrattande systrar, skogsdryaderna som bor nära Raynewood Retreat i Ashenvale. Stråna är genomsyrade av Cenarius döttrars naturliga elegans och magi och värdesätts av skickliga skräddare som ett sällsynt vävmaterial till kraftfulla trollkarlskläder.",al={"vad är laughing sister's hair","information om laughing sister's hair","material av dryadhår"}}},fp="22,138,24.333.0,44.136.0,39.136.0,55.149.0"}
P.entries["item:leftwitch-s-package"] = {n="Leftwitch's Package",s="Leftwitch’s Package för den sista delen av Reclaimers Inc:s verksamhet i Desolace tillbaka till Ironforge. Roetten Stonehammer tar emot det och betalar för arbetet.",h="Leftwitch’s Package för den sista delen av Reclaimers Inc:s verksamhet i Desolace tillbaka till Ironforge.",kw={"desolace","ironforge","leftwitch","leftwitch’s package","reclaimers inc","roetten stonehammer"},sec={{t="Tillbaka till Ironforge",b="Roetten Stonehammer väntar i Ironforge på Leftwitch’s Package från Desolace. Bär tillbaka det till honom, så betalar Reclaimers Inc. för den sista delen av arbetet. Roetten är glad att ha dig med, även för ett litet jobb."}},faq={{q="Vem är Leftwitch’s Package till för?",a="Roetten Stonehammer i Ironforge tar emot Leftwitch’s Package på Leftwitchs vägnar.",al={"vem vill ha paketet","leftwitch package till vem"}},{q="Vart ska paketet?",a="Ta Leftwitch’s Package från Desolace till Roetten Stonehammer i Ironforge.",al={"vart ska det tas","paketets destination"}},{q="Vad har paketet med att göra?",a="Leftwitch’s Package är den sista leveransen i Reagents för Reclaimers Inc:s verksamhet i Desolace.",al={"varför paketet","reclaimers paket"}},{q="Vad gör Roetten när han får det?",a="Roetten tackar dig för det punktliga arbetet och betalar dig på Reclaimers Inc:s vägnar.",al={"vad händer efter leveransen","roetten betalar"}}},fp="19,162,17.218.0,33.88.0,26.77.0,33.101.0,37.80.0"}
P.entries["item:legacy-of-the-aspects"] = {n="Legacy of the Aspects",s="Legacy of the Aspects är en uråldrig bokrulle som gömts djupt inne i The Dor'Danil Barrow Den i södra Ashenvale. Den hämtades under en intellektuell prövning för Horde och innehåller viktig kunskap om de stora aspekterna som formade det forntida Azeroth.",h="Legacy of the Aspects är en uråldrig bokrulle som gömts djupt inne i The Dor'Danil Barrow Den i södra...",kw={"ashenvale","gravkammare","braug dimspirit","dor'danil","legacy of the aspects","the talondeep path","test of lore"},ang={["class:Druid"]="Texten finns djupt inne i Dor'Danil Barrow Den, omgiven av de tragiska, plågade andarna efter fallna Night Elf-druider.",["faction:Horde"]="Boken är central i en traditionell övergångsrit som prövar om Horde-äventyrare har den visdom och kunskap som krävs för att mäta sig med sin fysiska styrka."},sec={{t="Ett prov för sinnet",b="Medan taurenäldsternas tidigare prövningar sätter fysisk uthållighet och beslutsamhet på prov, är jakten på Legacy of the Aspects utformad för att utmana sinnet. På uppdrag av Braug Dimspirit vid ingången till The Talondeep Path i Stonetalon Mountains måste en aspirant utforska de hemsökta gravkamrarna i Dor'Danil. Den uråldriga texten vilar på en piedestal av sten, bevakad av de rastlösa andarna efter fallna druider och de grymma varelser som dödade dem. Att ta boken är bara det första steget; den som söker måste lära sig innehållet utantill innan boken lämnas tillbaka, eftersom kunskaperna om dess historiska lärdomar sätts på prov."}},faq={{q="Var finns boken?",a="Boken vilar på en piedestal av sten i de nedre kamrarna i The Dor'Danil Barrow Den, i södra Ashenvale, söder om Splintertree Post.",al={"hitta legacy of the aspects","bokens plats","var finns boken"}},{q="Varför vill Braug Dimspirit ha boken?",a="Braug Dimspirit använder boken för att genomföra Test of Lore. Till skillnad från fysiska utmaningar ska den här prövningen avgöra om en äventyrare har den intelligens och uppmärksamhet som krävs för att studera och minnas viktig historisk kunskap.",al={"varför braug vill ha boken","syftet med test of lore"}},{q="Vad händer om du inte studerar texten innan du talar med Braug?",a="Braug förhör den som söker om innehållet så snart boken har hämtats. Fel svar leder till att personen snabbt förvisas med magi till Camp Taurajo i The Barrens, långt därifrån.",al={"följder av fel svar","misslyckas med prövningen"}}},fx={["32a02485"]={q="Vad är Legacy of the Aspects?",a="Legacy of the Aspects är en uråldrig och värdefull bok som vilar djupt inne i Dor'Danil Barrow Den i södra Ashenvale. Den vaktas av de rastlösa andarna efter stupade druider och de vidriga varelser som dödade dem. Boken innehåller historisk kunskap om drakAspekterna och är ett krävande prov på visdom och minne för den som vågar hämta den.",al={"vad är legacy of the aspects","boken legacy of the aspects","vad är den här boken"}}},fp="21,226,18.582.0,26.144.0,40.174.0,68.193.0"}
P.entries["item:letter-of-commendation"] = {n="Letter of Commendation"}
P.entries["item:letter-to-delgren"] = {n="Letter to Delgren",s="Brevet till Delgren är ett brådskande meddelande, skrivet av Balthule Shadowstrike nära Tower of Althalaxx i norra Darkshore. Det är adresserat till hans mentor, paladinen Delgren the Purifier, och beskriver de illvilliga planerna hos den demoniska kulten Dark Strand. Att leverera brevet för vital underrättelse söderut till Maestra's Post i Ashenvale.",h="Brevet till Delgren är ett brådskande meddelande, skrivet av Balthule Shadowstrike nära Tower of Althalaxx i...",kw={"ashenvale","balthule shadowstrike","dark strand","darkshore","delgren the purifier","letter to delgren","maestra's post","tower of althalaxx"},ang={["class:Paladin"]="Detta meddelande lyfter fram ett ovanligt kamratskap: en mänsklig paladin som undervisar en nattalvselev i det heliga ljuset och förenar Kaldoreis uråldriga marker med de Östra kungarikenas krigiska tro.",["faction:Alliance"]="Meddelandet vittnar om ett allt större samarbete inom Alliansen, där mänskliga kämpar och nattalvernas Sentinels går samman för att bekämpa demoniska kulter som infiltrerar norra Kalimdor."},sec={{t="En varning söderut",b="När kultister från Dark Strand samlas kring ruinerna av Tower of Althalaxx håller nattalven Balthule Shadowstrike vakt över deras växande illvilja. Eftersom han saknar den krigiska styrkan att ensam utrota kulten skriver Balthule detta meddelande för att be sin läromästare i det heliga ljuset, Delgren the Purifier, om hjälp. Kultens onda riter hotar mer än Darkshores kust, så meddelandet måste föras genom hela regionen till västra Ashenvale, där Delgren samarbetar med nattalvernas Sentinels för att jaga demoner och odöda hot."}},faq={{q="Vad är brevet till Delgren?",a="Det är ett förseglat meddelande skrivet av Balthule Shadowstrike, som rapporterar om den demoniska kulten Dark Strands växande verksamhet vid Tower of Althalaxx. Det är adresserat till paladinen Delgren the Purifier.",al={"vad är det här brevet","letter to delgren","balthules brev"}},{q="Vem är Delgren the Purifier?",a="Delgren är en mänsklig paladin stationerad vid Maestra's Post i västra Ashenvale. Han är hängiven det heliga ljuset och har erbjudit sina krigiska färdigheter för att hjälpa nattalvernas Sentinels att rena de gamla skogarna från demoner och odöda, samtidigt som han vägleder Balthule i helig krigföring.",al={"vem är delgren","delgrens bakgrund","var finns delgren"}},{q="Varför skickar Balthule brevet så långt bort?",a="Balthule är Delgrens lärjunge och vänder sig särskilt till sin mentors kunskap om hur man bekämpar demonisk korruption. Delgren har både stridsförmågan och stöd från de lokala Sentinel-styrkorna vid Maestra's Post för att organisera ett svar på Dark Strands mörka ritualer.",al={"varför skicka till ashenvale","varför inte berätta för auberdine"}},{q="Vart måste brevet levereras?",a="Brevet måste föras söderut genom hela Darkshore och över gränsen till Ashenvale, till Maestra's Post längs den västra vägen.",al={"vart ska jag ta brevet","var brevet ska levereras"}}},fx={["8fccd45f"]={q="Varifrån kommer Letter to Delgren, och vem skrev det?",a="Brevet skrevs av Balthule Shadowstrike, en nattalv stationerad i norra Darkshore nära Tower of Althalaxx. För att rena de gamla ruinerna från den demoniska korruption som fått fäste skrev Balthule detta brådskande brev för att be sin mentor, paladinen Delgren the Purifier, om hjälp och råd.",al={"vem skrev letter to delgren","varifrån kom letter to delgren","vem skickade letter to delgren"}},["99aa1720"]={q="Varför är Letter to Delgren så viktig?",a="Brevet innehåller avgörande underrättelser som avslöjar Dark Strand-kultens ondskefulla verksamhet vid Tower of Althalaxx. Delgren the Purifier har vigt sig åt att hjälpa nattalverna rena skogarna från demoner och odöda, och Balthule behöver genast varna sin mentor så att de kan möta det växande hotet.",al={"varför behöver delgren brevet","varför vill de ha brevet till delgren","brevets betydelse för delgren"}}},fp="17,204,20.414.0,30.134.0,28.229.0,47.214.0,44.122.0"}
P.entries["item:letter-to-ello"] = {n="Letter to Ello",s="Letter to Ello är ett förseglat brev skrivet av Abercrombie, en excentrisk eremit som bor i en koja strax norr om Raven Hill Cemetery i Duskwood. Brevet är adresserat till borgmästare Ello Ebonlocke i Darkshire och lämnas över med eremitens påstående att de är gamla vänner, trots att innehållet är skrivet med ålderdomliga tecken.",h="Letter to Ello är ett förseglat brev skrivet av Abercrombie, en excentrisk eremit som bor i en koja strax...",kw={"abercrombie","darkshire","duskwood","ello ebonlocke","letter to ello","lapp till borgmästaren","sirra von'indi"},ang={["faction:Alliance"]="Att bära meddelanden mellan excentriska enstöringar och lokala borgmästare hör till resenärernas vanliga plikter i Duskwood, även om stadens tjänstemän i Darkshire ständigt är på sin vakt mot märkliga brev."},sec={{t="En märklig hälsning",b="När äventyrare hjälper eremiten Abercrombie med uppgifter runt om i Duskwood, anförtror den gamle enstöringen dem den här lappen. Han påstår att borgmästare Ello Ebonlocke är en gammal vän som kommer att fira det de har åstadkommit. I själva verket minns borgmästaren i Darkshire inte någon som heter Abercrombie. När borgmästare Ebonlocke bryter sigillet upptäcker han att han inte kan tyda en enda fras i den ålderdomliga skriften. Därför skickar han lappen till Darkshires lärde, Sirra Von'Indi, för översättning."},{t="Mörka omen",b="Det till synes oskyldiga ärendet döljer eremitens sanna, makabra avsikter. De uråldriga runor som Abercrombie har skrivit ned bådar undergång för hela Darkshire, långt ifrån ett vänskapligt utbyte mellan gamla bekanta från staden."}},faq={{q="Vem skrev Letter to Ello?",a="Brevet skrevs av Abercrombie, en eremit som bor i en fallfärdig hydda nära Raven Hill Cemetery i västra Duskwood.",al={"vem skrev brevet","brev till ello författare","vem skickade brevet"}},{q="Kan borgmästare Ello Ebonlocke läsa brevet?",a="Nej. När brevet lämnas till borgmästare Ebonlocke i Darkshire upptäcker han att skriften är helt obegriplig och konstaterar att den verkar vara skriven på ett uråldrigt, okänt språk.",al={"kan ello läsa det","varför kan ello inte läsa lappen","språket i ellos brev"}},{q="Vem kan översätta lappen?",a="Borgmästare Ebonlocke ber budbärare ta brevet till Sirra Von'Indi, en lärd person i Darkshire som är väl bevandrad i uråldriga skrifter och esoteriska språk.",al={"vem översätter lappen","översätta abercrombies lapp","vem kan läsa brevet"}},{q="Känner borgmästare Ebonlocke verkligen Abercrombie?",a="Trots Abercrombies påstående att han och borgmästaren är gamla vänner, hävdar Ello Ebonlocke att han aldrig har hört talas om någon som heter Abercrombie.",al={"känner ello abercrombie","är ello och abercrombie vänner","abercrombie och ello gamla vänner"}}},fx={["74d18927"]={q="Vad är Letter to Ello?",a="Letter to Ello är ett mystiskt brev skrivet på ett uråldrigt, oläsligt språk av eremiten Abercrombie. Det är direkt adresserat till borgmästare Ello Ebonlocke i Darkshire. Eremiten hävdar att brevet ska berätta för hans ”gamle vän” om de dåd du utförde på kyrkogården.",al={"letter to ello","vad är letter to ello","abercrombies brev"}},ee8215fa={q="Varför vill borgmästare Ebonlocke ha Letter to Ello?",a="Borgmästare Ebonlocke vill bara ha brevet eftersom du kommer med besked om att en gammal vän vid namn Abercrombie har skickat det till honom. När han får det upptäcker borgmästaren dock att han inte kan läsa den ålderdomliga skriften och försöker genast få den översatt för att förstå vad eremiten egentligen menade.",al={"varför vill ello ha brevet","varför vill de ha letter to ello","varför leverera letter to ello"}}},fp="14,318,18.490.0,10.224.1,29.120.0,41.179.0,27.158.0,47.137.0"}
P.entries["item:letter-to-jin-zil"] = {n="Letter to Jin'Zil",s="Letter to Jin'Zil är ett brev skrivet av orchen Darsok Swiftdagger vid The Crossroads. Efter segern över Serena Bloodfeather får en äventyrare brevet i uppdrag att underrätta Darkspear-häxdoktorn Jin'Zil i Stonetalon Mountains om att hotet från Bloodfeather har rensats bort från norra The Barrens.",h="Letter to Jin'Zil är ett brev skrivet av orchen Darsok Swiftdagger vid The Crossroads.",kw={"darsok swiftdagger","harpyor","jin'zil","letter to jin'zil","malaka'jin","rokhan","serena bloodfeather","stonetalon"},ang={["faction:Horde"]="Brevet blir en länk för Horde-äventyrare som går från att hålla ordning i The Barrens till att ta itu med de djupare konflikter som pyr i Stonetalon Mountains.",["race:Troll"]="När brevet levereras leds Darkspear-resenärer direkt till Witch Doctor Jin'Zil, en äldre utövare som för vidare traditionell voodoo utanför Echo Isles."},sec={{t="Ett bud till Stonetalon",b="Efter att harpyornas tillhåll vid The Dry Hills utrotats och Serena Bloodfeather dödats skriver Darsok Swiftdagger detta meddelande till en gammal kamrat. Eftersom harpyorna i The Barrens ursprungligen höll till bland Stonetalon Mountains toppar använder Darsok brevet för att introducera en lovande krigare för den större vildmarken och meddela häxdoktorn Jin'Zil att harpyornas matriark har fallit."},{t="Gamla minnen i Malaka'jin",b="När Jin'Zil får brevet i grottan i Malaka'jin tar han emot nyheten med nostalgisk tillfredsställelse. Serena påminner den gamle häxdoktorn om grundandet av Durotar efter det tredje kriget, då hans vän Rokhan slog sig samman med halvojätten och besttämjaren Rexxar för att döda Serenas äldre syster, Bloodfeather. Nu när även Serena har dödats anser Jin'Zil att Bloodfeather-släktens hämndlystnad är helt utsläckt."}},faq={{q="Vem skrev Letter to Jin'Zil?",a="Brevet är skrivet av Darsok Swiftdagger, en orch som är stationerad vid The Crossroads i The Barrens och samordnar försvaret mot plundrande harpyklaner.",al={"vem skrev detta","brevets avsändare","darsoks brev"}},{q="Var finns Jin'Zil?",a="Witch Doctor Jin'Zil bor i en grotta i Malaka'jin, en utpost för Darkspear-troll i Stonetalon Mountains sydöstra klippor.",al={"var finns jinzil","jin'zils plats","hitta jinzil"}},{q="Vilka nyheter innehåller brevet?",a="Meddelandet underrättar Jin'Zil om att Serena Bloodfeather, ledaren för harpyorna som härjar i norra The Barrens, har dödats och att området norr om The Crossroads därmed är säkrat.",al={"vad står det i brevet","brevets budskap"}},{q="Varför bryr sig Jin'Zil om Bloodfeathers?",a="Jin'Zil minns grundandet av Durotar efter det tredje kriget, då hans följeslagare Rokhan och halvojättkrigaren Rexxar dödade Serenas äldre syster. Serena sökte hämnd på Horde ända sedan dess, så hennes fall är en välkommen lösning.",al={"varför jin'zil och harpyor","bloodfeathers historia","rokhan och bloodfeather"}}},fx={f9426e82={q="Varför vill Jin'Zil att Letter to Jin'Zil ska levereras till honom?",a="Brevet kommer med efterlängtade nyheter från hans gamle vän Darsok Swiftdagger i The Barrens. Jin'Zil har inte hört från Darsok på många år, och brevet bekräftar att Serena Bloodfeather har dött. Därmed är det slut på harpyornas matriarker, som plågade både The Barrens och Stonetalon.",al={"varför leverera letter to jin'zil","vem vill ha letter to jin'zil","varför bryr sig jin'zil om brevet"}}},fp="17,157,25.330.0,26.369.1,32.137.0,25.116.0,41.183.0,46.243.1"}
P.entries["item:letter-to-jorgen"] = {n="Letter to Jorgen",s="Ett förseglat brev ber Jorgen i Stormwind City om hjälp med en försvunnen diplomat.",h="Ett förseglat brev ber Jorgen i Stormwind City om hjälp med en försvunnen diplomat.",kw={"jaina proudmoore","jorgen","letter to jorgen","försvunnen diplomat","stormwind","theramore","valley of heroes"},ang={["class:Rogue"]="Som skurk vet du att diskreta meddelanden och motvilliga informatörer på gatan kan behövas när du försöker avslöja problem i huvudstaden.",["faction:Alliance"]="Brevet rör Alliansens bräckliga stabilitet och söker ett diskret svar på en händelse som hotar banden mellan Stormwind och Theramore."},sec={{t="En saklig kallelse",b="En diplomat på väg till Theramore kom aldrig fram till samtalen med Lady Jaina Proudmoore, och kungliga utredare agerade snabbt för att hålla saken tyst. Medan officiella agenter sökte igenom huvudstaden sattes andra kanaler i rörelse. Brevet går förbi militärbyråkratin och söker upp Jorgen, en barsk veteran som fiskar under de stora statyerna i Valley of Heroes. Det åberopar gamla förpliktelser och drar in honom i en hemlig undersökning bland rykten om en sammansvärjning inom Defias Brotherhood."}},faq={{q="Vad är syftet med brevet?",a="Brevet presenterar sin bärare och ber Jorgen att infria en gammal förpliktelse. Det skickar bäraren till Valley of Heroes så att Jorgen kan hjälpa till att utreda en försvunnen diplomat utan att väcka uppmärksamhet.",al={"vad gör letter to jorgen","varför letter to jorgen","brevets syfte"}},{q="Vem är Jorgen?",a="Jorgen är en tillbakadragen kontakt strax innanför Stormwinds portar som ägnar sin tid åt att fiska i Valley of Heroes. Han ogillar avbrott, men en gammal skuld binder honom att hjälpa till när han får se brevet.",al={"vem är jorgen","jorgen npc","jorgen stormwind"}},{q="Vilket försvinnande handlar brevet om?",a="En framstående diplomat lämnade Stormwind med båt för att möta Lady Jaina Proudmoore i Theramore, men försvann på vägen. Misstankarna riktas mot Defias Brotherhood, men hela planen hålls fortfarande hemlig.",al={"vilken diplomat är försvunnen","vem försvann","försvunnen diplomat"}},{q="Var lämnas brevet?",a="Brevet förs till Valley of Heroes, Stormwind Citys storslagna entré, kantad av monument över hjältarna från det andra kriget. Jorgen fiskar vid vattnet nära huvudportarna.",al={"var ska jag lämna brevet","jorgens plats","var finns jorgen"}}},fx={["0eeb183b"]={q="Vad är Letter to Jorgen?",a="Brevet är ett konfidentiellt meddelande om en Stormwind-diplomat som försvunnit spårlöst på väg till Theramore. Kungliga agenter söker redan öppet genom staden, så det förseglade brevet vänder sig till privata, diskreta kontakter utanför kronans vanliga kanaler för att utreda misstankarna om Defias Brotherhoods inblandning.",al={"vad är letter to jorgen","föremålet letter to jorgen","om letter to jorgen"}},["5d64bfbf"]={q="Varifrån kommer Letter to Jorgen, och vem skrev det?",a="Brevet skrevs av Bishop DeLavey i Stormwind, som ville ha en oberoende utredning av den försvunna diplomaten. Han litade mer på personliga allierade än på iögonfallande kungliga utredare och skrev meddelandet särskilt för att kalla på en gammal vän vid namn Jorgen, som för närvarande håller låg profil vid vattnet i Valley of Heroes.",al={"vem skrev letter to jorgen","vem skickade letter to jorgen","letter to jorgens ursprung"}},["9fd54092"]={q="Varför efterfrågas Letter to Jorgen?",a="Jorgen behöver brevet eftersom det beskriver ett hemligt åtagande han inte kan ignorera. Han vill helst fortsätta fiska i lugn och ro, men innehållet övertalar honom att hjälpa till att avslöja Defias-planen innan panik bryter ut i huvudstaden.",al={"varför leverera letter to jorgen","varför behöver jorgen brevet","syftet med att ge jorgen brevet"}}},fp="16,80,23.440.0,35.174.0,14.196.0,45.206.0,30.181.0"}
P.entries["item:lewis-note"] = {n="Lewis' Note",s="I Sentinel Hill skickar Quartermaster Lewis en brådskande begäran om förnödenheter till en privat rustningssmed i Stormwind. En kurir flyger dit med grip, med en begäran om skyddsutrustning till garnisonen i Westfall.",h="I Sentinel Hill skickar Quartermaster Lewis en brådskande begäran om förnödenheter till en privat...",kw={"grip","lewis' note","limited immunity","old town","osric strang","quartermaster lewis","sentinel hill","thor"},ang={["race:Human"]="Genom att leverera begäran lär sig unga mänskliga äventyrare att använda kungarikets gripnätverk och får se hur lite Stormwinds härskare gör för att utrusta Westfalls försvarare."},sec={{t="En vädjan om stål",b="Folkets milis i Sentinel Hill får lite stöd från Stormwinds adelsråd. Skärmytslingar med Defias Brotherhood tömmer ständigt dess redan knappa förråd av utrustning. För att hålla försvararna utrustade vänder sig Quartermaster Lewis till privata handlare i stället för kronans förråd. Hans begäran går helt förbi de officiella militära kanalerna. En kurir från Alliansen måste flyga med grip till Old Town och överlämna ordern till Osric Strang, ägare av Limited Immunity."}},faq={{q="Vad är Lewis' Note?",a="Lewis' Note är en skriftlig order från Quartermaster Lewis där han ber Osric Strang, en rustningssmed i Stormwind, att skicka skyddsutrustning till den hårt ansatta garnisonen i Westfall.",al={"vad är det här för föremål","syftet med lewis note","vad gör anteckningen"}},{q="Vem skrev den här anteckningen?",a="Quartermaster Lewis skrev anteckningen. Han ansvarar för förnödenheter, proviant och vapen åt folkets milis i Sentinel Hill.",al={"vem är lewis","quartermaster lewis"}},{q="Vem tar emot anteckningen?",a="Anteckningen går först till Thor, gripmästaren i Sentinel Hill. Därifrån levereras den direkt till Osric Strang i hans rustningsbutik, Limited Immunity, i Stormwinds Old Town.",al={"vart ska anteckningen","vem får lewis note","osric strang anteckning"}},{q="Varför får garnisonen inte bara rustning från kungariket?",a="Stormwinds regering har i stort sett försummat Westfall och lämnat dess försvarare utan direkt militär finansiering eller rustning från kronans förråd. Lewis förlitar sig på handelskontakter som Osric Strang för att hålla milisen utrustad.",al={"varför köpa från osric","varför hjälper stormwind inte","stormwinds hjälp till westfall"}}},fp="11,153,16.423.0,20.153.0,20.125.0,22.166.0,57.204.0"}
P.entries["item:lieutenant-s-insignia"] = {n="Lieutenant's Insignia",s="Nära Orgrimmar bär kultister Lieutenant's Insignia och Burning Blades märke. Äventyrare från Horde tar det från dem.",h="Nära Orgrimmar bär kultister Lieutenant's Insignia och Burning Blades märke.",kw={"burning blade","cleft of shadow","durotar","hidden enemies","lieutenant's insignia","neeru fireblade","shadow council","skull rock","thrall"},ang={["class:Warlock"]="För en häxmästare visar Lieutenant's Insignia hur Burning Blade använder felmagi i Burning Legions tjänst. Det sätter Thralls tolerans för laglydiga häxmästare inom Horde på prov.",["faction:Horde"]="För det unga Horde visar Lieutenant's Insignia faran med demonisk korruption som försöker undergräva Thralls nya nation inifrån."},sec={{t="Kultens märke",b="Kultister i Skull Rock på Durotars östra kust bär Lieutenant's Insignia. Märket anger att bäraren är officer inom Burning Blade. Krigshövdingen Thrall tolererar inga förrädare i sin nya nation. Men en utrensning kan skingra kulten innan dess herrar avslöjas. Därför anförtror han märket åt en förkämpe, för att pröva dem som misstänks ha infiltrerat området under Orgrimmar."},{t="Cleft of Shadow",b="Krigshövdingen Thrall skickar sin agent till Cleft of Shadow med Lieutenant's Insignia, för att visa det för Neeru Fireblade. Neeru tar agenten för en nybefordrad underordnad. Säker på sin ställning skryter häxmästaren om att Burning Blade tjänar Shadow Council och Burning Legion. De orden ger Thrall en möjlighet att avslöja korruptionen under staden."}},faq={{q="Varifrån kommer Lieutenant's Insignia?",a="Fanatiker och lärlingar inom Burning Blade i Skull Rock bär Lieutenant's Insignia. Grottan ligger vid Durotars kust öster om Orgrimmar.",al={"hur får man lieutenants insignia","vem släpper lieutenants insignia","lieutenant insignia ursprung"}},{q="Vad används märket till?",a="Krigshövdingen Thrall ger Lieutenant's Insignia till sin agent som förklädnad. En ung äventyrare som bär det kan utge sig för att vara officer inom Burning Blade och nå platser dit Thralls agenter inte når, för att ta reda på vem som leder kulten.",al={"varför behövs lieutenants insignia","lieutenants insignia användning i uppdrag","vad gör man med märket"}},{q="Vem är Neeru Fireblade?",a="Neeru Fireblade är en orchisk häxmästare i Cleft of Shadow i Orgrimmar. Han påstår sig tjäna Thrall genom att visa hur häxmästare kan hjälpa Horde, men leder i hemlighet den lokala Burning Blade-kulten.",al={"vem är neeru","neeru fireblade bakgrund"}},{q="Varför dödar inte Thrall bara Neeru Fireblade omedelbart?",a="Thrall vet att Neeru är en förrädare, men ett för tidigt angrepp kan varna kultens verkliga herrar och skingra dess nätverk. Han använder Neeru som en ovetande uppgiftslämnare för att avslöja Shadow Councils mer omfattande närvaro i Durotar.",al={"varför thrall inte dödar neeru","varför hålla neeru vid liv","varför infiltrera neeru"}}},fx={["2e1cfb76"]={q="Vad är Lieutenant's Insignia?",a="Det är ett emblem som bärs av officerare inom Burning Blade-kulten och visar att bäraren är erkänd som löjtnant. För demonkultister som verkar i hemlighet runt om i Durotar visar denna symbol lojalitet, status och auktoritet inom Shadow Councils nätverk.",al={"vad är lieutenant's insignia","vad är en löjtnantsinsignia","burning blades insignia"}}},fp="21,121,18.363.0,19.359.1,47.135.0,30.207.1,23.183.2,57.211.1"}
P.entries["item:lightning-gland"] = {n="Lightning Gland",s="I The Barrens tas blixtkörtlar från stormhudar som strövar över slätterna. Brewmaster Drohn i Ratchet behöver dem till troggöl, en eldig brygd som Chen Stormstout lärde honom att göra.",h="I The Barrens tas blixtkörtlar från stormhudar som strövar över slätterna.",kw={"the barrens","brewmaster drohn","chen stormstout","lightning gland","ratchet","stormhide","trogg ale"},ang={["profession:Cooking"]="Som kock kan du se hur Brewmaster Drohn och Chen Stormstout använder råa organ från bestar i spritdrycker, även om blixtkörtlar inte är vanlig mat."},sec={{t="En chockerande ingrediens",b="Stormhudar strövar på The Barrens savanner bland andra rovdjur som påverkats av elementen. Deras kött innehåller blixtkörtlar, organ laddade med vilande elektricitet. Körtlarna är dålig föda i sig, men bryggare uppskattar stinget de ger åt en brygd."},{t="Drohns troggöl",b="Brewmaster Drohn håller Chen Stormstouts bryggartraditioner vid liv i Ratchet. För att göra troggöl, en kraftfull brygd, behöver Drohn fem blixtkörtlar, en Thunderhawk Saliva Gland och en färsk Kodo Liver. Den färdiga drycken har ett skarpt sting som äventyrare finner uppfriskande och kraftfullt."}},faq={{q="Vilka varelser har lightning glands?",a="Stormhudar som strövar på The Barrens savanner bär på blixtkörtlar.",al={"var får man tag på lightning gland","vem släpper lightning gland","stormhide lightning gland"}},{q="Vem vill ha lightning glands och varför?",a="Brewmaster Drohn i Ratchet vill ha blixtkörtlar till troggöl, ett recept som vandrande bryggmästaren Chen Stormstout lärde honom.",al={"vem behöver lightning gland","lämna in lightning gland","vad används lightning gland till"}},{q="Vad mer behövs tillsammans med lightning gland?",a="Drohn behöver fem blixtkörtlar, en Thunderhawk Saliva Gland från större åskhökar och en färsk Kodo Liver från bestarna i The Barrens.",al={"ingredienser till drohns trogg ale","tre ingredienser till chens tunna"}}},fx={f0cc18d7={q="Vad är en lightning gland?",a="En lightning gland är ett organ som utvinns ur stormhidebestar som strövar omkring i The Barrens. Körteln är fylld av de naturliga elektriska energier som strömmar genom bestarna, och dess kraftfulla elementarladdning gör den till en eftertraktad, ovanlig ingrediens för brygder.",al={"vad är lightning gland","lightning glands bakgrund","vad är en lightning gland"}},ba679c5d={q="Var kommer en lightning gland ifrån?",a="Lightning glands tillverkas inte av dödliga. Det är biologiska organ som tas direkt från stormhides som stryker omkring på The Barrens savanner. Dessa vilddjur utvecklar körtlarna naturligt för att leda den sprakande elektriska energin.",al={"varifrån kommer lightning glands","lightning glands ursprung","hur bildas lightning glands"}}},fp="15,155,21.241.0,17.277.0,38.63.0,35.131.0,50.143.0"}
P.entries["item:logging-rope"] = {n="Logging Rope",s="Logging Rope är ett tungt rep som är oumbärligt för Warsong-klanens pågående avverkning i Ashenvale. Sändningar med detta slitstarka rep överfölls och stals av lokala furbolgstammar som våldsamt motsätter sig Hordens expansion in i den uråldriga skogen.",h="Logging Rope är ett tungt rep som är oumbärligt för Warsong-klanens pågående avverkning i Ashenvale.",kw={"ashenvale","foulweald","locke okarr","logging rope","splintertree post","thistlefur","warsong lumber camp","warsongs förnödenheter"},ang={["faction:Horde"]="Att återta avverkningsrepet är avgörande för att hålla Warsong-klanens krigsmaskin försedd med timmer trots ständiga överfall.",["race:Orc"]="Orchernas bosättning i Kalimdor är helt beroende av timmer från Ashenvale. Därför är varje kapad låda med avverkningsverktyg en förolämpning som kräver vedergällning."},sec={{t="Stulna rep",b="För att underhålla de goblinbyggda maskinerna och sågverken i Warsong Lumber Camp krävs enorma mängder slitstarkt avverkningsrep. I stället för att nå skogshuggarna i lägret stoppades viktiga sändningar av furbolgstammarna Foulweald och Thistlefur. Furbolgerna har drivits till vansinne av korrumperingen och försvarar sina förfäders skogar med ursinne. De samlar de stulna repen i sina läger i norra och centrala Ashenvale."},{t="Försörjning av krigsinsatsen",b="Locke Okarr vid Splintertree Post har fått i uppdrag att återta den försvunna försörjningskedjan innan Warsong Lumber Camp stannar helt. Genom att återta det grova repet direkt från furbolgernas lya-mödrar och krigare kan Horden säkra fällbart timmer, binda stockar och rigga sågmaskiner, trots de infödda skogsinvånarnas ständiga gerillamotstånd."}},faq={{q="Vad används Logging Rope till?",a="Det är ett tjockt rep av industriell kvalitet som Warsong Lumber Camp behöver för att surra fast avverkat timmer, transportera stockar över oländig terräng och säkra tunga maskiner i Ashenvale.",al={"användning av avverkningsrep","varför warsong behöver rep","warsongs avverkningsrep"}},{q="Vem stal avverkningsrepet?",a="Sändningarna plundrades av de infödda furbolgerna Foulweald och Thistlefur, som för bort repen till sina bylyor och läger runt om i Ashenvale.",al={"vem tog repet","reptjuv","vilka furbolger har rep"}},{q="Vem vill ha tillbaka repet?",a="Locke Okarr, som är stationerad vid Splintertree Post, begär repet tillsammans med andra försvunna förnödenheter för att verksamheten vid Warsong Lumber Camp inte ska stanna.",al={"vem behöver avverkningsrep","uppdragsgivare för avverkningsrep"}},{q="Varför stjäl furbolgerna avverkningsutrustning?",a="Furbolgerna motsätter sig Hordens kalhuggning av Ashenvale med våld. Genom att stoppa försörjningskaravaner stör de sågverken och hämnas intrånget på sina marker.",al={"furbolgernas motiv","varför furbolger anfaller sändningar"}}},fx={["26f07746"]={q="Vad är Logging Rope?",a="Logging Rope är ett kraftigt rep som är oumbärligt för Warsong-klanens omfattande timmerverksamhet i Ashenvale. Det används för att säkra, dra och binda samman massiva fällda träd och är en nödvändig del av timmerlägrets dagliga arbete.",al={"vad är logging rope","information om logging rope","warsongs timmerrep"}}},fp="12,184,12.342.0,24.231.0,30.118.0,27.130.0,25.136.0,43.120.0"}
P.entries["item:lok-s-skull"] = {n="Lok's Skull",s="I södra Barrens markerar Lok's Skull en fruktad Razormane-ledares fall. Lok Orcbane ledde vilda quilboar-räder mot Hordens försörjningsvägar, och skallen är hans avhuggna huvud.",h="I södra Barrens markerar Lok's Skull en fruktad Razormane-ledares fall.",kw={"förräderi inifrån","camp taurajo","crossroads","lok orcbane","lok's skull","mangletooth","razormane","thork"},ang={["faction:Horde"]="Som medlem av Horden bryter du med Lok Orcbanes skalle quilboar-ledarskapet i söder, som trakasserar försörjningskaravanerna mellan Camp Taurajo och The Crossroads.",["race:Orc"]="Som orch ger det djup tillfredsställelse och trygghet åt dem som försvarar Barrens att visa upp det avhuggna huvudet från en quilboar-hövding vid namn 'Orcbane'."},sec={{t="En hövdings fall",b="Lok Orcbane ledde aggressiva Razormane-anfall mot Hordens försörjningslinjer i södra Barrens. Han kom från Razorfen Kraul tillsammans med sina löjtnanter Nak och Kuz. Efter att ha förrått Mangletooth och lämnat honom fången i Camp Taurajo blev Lok känd bland orciska försvarare för hänsynslösa räder som de hade svårt att hejda. Mangletooth skickar Hordens mästare till Loks läger, där Loks skalle hämnas fångenskapen och slår mot ledarskapet bakom Razormanes offensiv."},{t="Bevis till Crossroads",b="Mangletooth kräver skallarna från alla tre sammansvurna för sin hämnd och skickar sedan Loks skalle norrut till Thork vid The Crossroads. Thork och Hordens befäl misstänkte att en annan quilboar ledde räderna. Loks skalle kom som en bister överraskning och visade att hotet mot Barrens centrala handelsvägar hade slagits ned."}},faq={{q="Vem var Lok Orcbane?",a="Lok Orcbane var en mäktig Razormane-krigare som kom från Razorfen Kraul för att leda quilboar-rövarband genom södra Barrens. Han hatade orcher och ledde aggressiva anfall mot Hordens karavaner och utposter tillsammans med sina betrodda allierade Nak och Kuz.",al={"vem är lok","lok orcbane bakgrund","vem var lok orcbane"}},{q="Varför vill Mangletooth ha Lok's Skull?",a="Lok Orcbane och hans följeslagare förrådde Mangletooth och lämnade honom att tillfångatas och sättas i bur av tauren i Camp Taurajo. Övertygad om att hans egen död är nära söker Mangletooth hämnd på dem som övergav honom och skickar Hordens äventyrare för att döda sina forna kamrater.",al={"varför vill mangletooth ha skallen","mangletooths hämnd","varför döda lok"}},{q="Varför förs skallen till Thork vid Crossroads?",a="Thork ansvarar för försvaret av The Crossroads och arbetar för att skydda Hordens försörjningsvägar från quilboar-attacker. Lok's Skull bevisar för orcbefälhavaren att ledaren för räderna i söder har dödats och gör resandet tryggare i området.",al={"varför föra skallen till thork","thork och loks skalle","vem får loks skalle"}},{q="Vilka var Nak och Kuz?",a="Nak och Kuz ledde räder tillsammans med Lok Orcbane i södra Barrens. Mangletooth säger att den ene var magiker och den andre spårare, vilket stärker bilden av Lok som en mäktig krigare i räderna mot Horden.",al={"nak och kuz","lok orcbanes löjtnanter","kuz och nak"}}},fx={a8e2f7c2={q="Vad är Lok's Skull?",a="Lok's Skull är det avhuggna huvudet från Lok Orcbane, en skoningslös krigare som ledde brutala räder med Razormane quilboars mot Hordens försörjningsleder i södra The Barrens. Skallen är ett dystert bevis på hans död. Den tjänar både som hämnd för en förrådd stammedlem och som obestridligt bevis för försvararna vid The Crossroads på att hotet är undanröjt.",al={"vad är lok's skull","föremålet lok's skull","vad är den här skallen"}},["4d726f58"]={q="Var kommer Lok's Skull ifrån?",a="Den tas direkt från den dödade Lok Orcbanes kropp i södra The Barrens. Lok och hans löjtnanter kom från Razorfen Kraul för att organisera räder mot Horden, tills Mangletooth, en utstött quilboar som hölls i Camp Taurajo, avslöjade deras fäste så att Lok kunde besegras.",al={"varifrån kom lok's skull","vem skapade lok's skull","lok's skulls ursprung"}}},fp="11,183,18.461.0,24.319.1,20.250.0,38.265.0,52.240.0,21.196.0"}
P.entries["item:lonebrow-s-journal"] = {n="Lonebrow's Journal",s="Lonebrow's Journal är en väderbiten dagbok som hittades hårt sluten i den dvärglike utforskaren Henrig Lonebrows skelett vid foten av The Great Lift. Sidorna beskriver Lonebrows sista dystra färd genom The Barrens och pekar mot faror som lurar i Razorfen Kraul.",h="Lonebrow's Journal är en väderbiten dagbok som hittades hårt sluten i den dvärglike utforskaren Henrig...",kw={"kraulens gamla häxa","falfindel waywarder","the great lift","henrig lonebrow","razorfen kraul","thalanaar","thousand needles"},ang={["faction:Alliance"]="Henrig Lonebrows sista anteckningar knyter samman Alliansens spejare med druiderna som vaktar gränsen till Feralas och samlar hjälp mot quilboarhotet.",["race:Dwarf"]="Att hitta en fallen frände i så avlägsna och fientliga trakter påminner om de faror som väntar dvärgutforskare långt bortom Khaz Modan."},sec={{t="En sista önskan vid The Great Lift",b="Henrig Lonebrow mötte sitt olyckliga slut nära foten av The Great Lift, som förbinder The Barrens med Thousand Needles. Hans övergivna kvarlevor ligger på en klipphylla, med den väderbitna dagboken fortfarande i sitt grepp. Dagboken vittnar om hans sista resor och uppmanar den som hittar den att underrätta nattalvdruiden Falfindel Waywarder i Thalanaar, gränsutposten mot Feralas. Lonebrows anteckningar kastar viktigt ljus över det växande hotet från quilboar i södra The Barrens."},{t="Band till Razorfen",b="När Lonebrows anteckningar överlämnas till Falfindel Waywarder bekräftar de Alliansens växande oro över quilboar i Razorfen Kraul. Dagbokens innehåll leder direkt till en uppmaning om att hjältar ska slå mot hjärtat av det taggiga nästet och besegra Charlga Razorflank, Kraulens gamla häxa som styr quilboarhotet."}},faq={{q="Vem var Henrig Lonebrow?",a="Henrig Lonebrow var en resande dvärg som dog vid foten av The Great Lift i Thousand Needles. Han dog med dagboken i handen, i hopp om att dess innehåll skulle nå nattalverna i Thalanaar.",al={"henrig lonebrow","vem är lonebrow","död dvärg vid hissen"}},{q="Var finns dagboken?",a="Dagboken ligger intill Henrig Lonebrows skelett, strax bortom rampen vid foten av The Great Lift, på en låg klipphylla i norra Thousand Needles.",al={"var finns lonebrows dagbok","hitta lonebrows dagbok","skelett vid the great lift"}},{q="Vem ska få Lonebrow's Journal?",a="Ta dagboken västerut genom Thousand Needles till Falfindel Waywarder, en nattalvdruid som är stationerad i Thalanaar vid gränsen till Feralas.",al={"vem ska jag lämna dagboken till","falfindel waywarder","var lämnar jag in dagboken"}},{q="Vad leder dagboken till?",a="När du läser dagboken och rapporterar till Falfindel Waywarder får du information om quilboar. Det leder till ett uppdrag i Razorfen Kraul där du ska besegra den gamla häxan Charlga Razorflank.",al={"uppdraget kraulens gamla häxa","fortsättning på lonebrows dagbok"}}},fx={a9190e03={q="Vad är Lonebrow's Journal?",a="Lonebrow's Journal är en väderbiten dagbok som hittades i dvärgen Henrig Lonebrows skelettartade händer. Den hittades vid foten av The Great Lift i Thousand Needles och dokumenterar hans resor och sista önskningar innan han dog i kanjonen.",al={"vad är lonebrow's journal","vad är den här boken","henrig lonebrows dagbok"}},["090ee1d4"]={q="Var kommer Lonebrow's Journal ifrån, och vem skrev den?",a="Dagboken skrevs av Henrig Lonebrow, en dvärgresenär som färdades genom Thousand Needles förrädiska kanjoner. Han bar den med sig fram till sin död nära foten av The Great Lift, där hans kvarlevor och dagboken till slut hittades.",al={"vem skrev lonebrow's journal","författaren till lonebrow's journal","varifrån kom dagboken"}},ea8f453f={q="Varför vill någon ha Lonebrow's Journal?",a="När dagboken levereras uppfylls den fallne dvärgens sista önskan. Falfindel Waywarder, en nattalvdruid stationerad i Thalanaar vid gränsen till Feralas, vill läsa innehållet för att förstå vad som hände Henrig och avslöja farorna som växer i Razorfen Kraul.",al={"varför leverera lonebrow's journal","vem behöver lonebrow's journal","varför vill de ha lonebrow's journal"}}},fp="18,144,30.432.0,20.245.1,24.192.0,27.150.0,38.134.0,30.133.1"}
P.entries["item:lookout-s-spyglass"] = {n="Lookout's Spyglass",s="Lookout's Spyglass är ett stulet redskap som Thorium Brotherhood värdesätter högt. Förlusten gör att Searing Gorges utkikare saknar ett utmärkt verktyg för att hålla uppsikt över området.",h="Lookout's Spyglass är ett stulet redskap som Thorium Brotherhood värdesätter högt.",kw={"dark iron utkikare","lookout's spyglass","searing gorge","the slag pit","kikare","stulet redskap","taskmaster scrange","thorium brotherhood"},sec={{t="Ett stulet redskap",b="Dark Iron-dvärgar tog Lookout's Spyglass från Thorium Brotherhood i Searing Gorge. Brödraskapet vill att den återlämnas till Taskmaster Scrange, som väntar på det stulna godset."}},faq={{q="Vad är Lookout's Spyglass?",a="Lookout's Spyglass är ett utmärkt övervakningsredskap som utkikare använder.",al={"kikare","utkikarkikare","vad är kikaren"}},{q="Vem stal kikaren?",a="Thorium Brotherhood säger att Dark Iron-dvärgar i Searing Gorge stal Lookout's Spyglass.",al={"vem tog den","dark iron stal kikaren","kikartjuvar"}},{q="Vem vill ha tillbaka kikaren?",a="Taskmaster Scrange från Thorium Brotherhood vill få tillbaka den stulna Lookout's Spyglass.",al={"vem vill ha den","återlämna kikaren","scranges kikare"}},{q="Var finns Dark Iron Lookouts?",a="Dark Iron Lookouts håller utkik från torn runt Slag Pit i Searing Gorge.",al={"utkikarnas plats","var finns utkikarna","dark iron utkikartorn"}},{q="Varför vill brödraskapet ha tillbaka den?",a="Lookout's Spyglass är ett ovärderligt övervakningsredskap för utkikarna.",al={"varför kikaren är viktig","kikarens användning","vad används den till"}}},fp="18,170,19.180.0,31.72.0,23.93.0,28.96.0,33.74.0,33.73.0"}
P.entries["item:lorgalis-manuscript"] = {n="Lorgalis Manuscript",s="Lorgalis Manuscript är en uråldrig text knuten till dyrkan av och läran om de gamla gudarna, bevarad bland nattalveruinerna under Ashenvale. Den döljs i det sjunkna tempelkomplexet Blackfathom Deeps och rymmer hemligheter som åtrås av mörka lärda, vilka söker väcka uråldriga krafter som slumrar.",h="Lorgalis Manuscript är en uråldrig text knuten till dyrkan av och läran om de gamla gudarna, bevarad bland...",kw={"blackfathom deeps","forlorn cavern","gerrig bonegrip","ironforge","lorgalis","manuskript","gammal gud","de som sover"},ang={["class:Warlock"]="Manuskriptet ger en sällsynt inblick i de gamla gudarnas och djupets varelsers förbjudna läror, insikter som åtrås av dem som ägnar sig åt mörka konster.",["race:NightElf"]="Texten ligger i de dränkta ruiner där nattalver en gång bodde, och dess vördnad för Aku'mai och de gamla gudarna visar hur den mörka dyrkan slagit rot i de fallna salarna."},sec={{t="En skrift om dem som sover",b="Lorgalis Manuscript ligger på botten av Blackfathom Deeps, de sjunkna ruiner där sedan länge döda alver en gång bodde, innan deras stad föll. Den skrevs av en viss Lorgalis och handlar om de gamla gudarna, som härjade över Azeroth när världen var ny och nu ligger fjättrade och sover. Den prisar också Aku'mai, en tjänare åt de gamla gudarna som bor i djupet. Läran sägs kunna öppna mystiska portar och väcka uråldriga väsen som sover djupt under världen. Manuskriptet förvaras i en gropig järnkista bland de översvämmade korridorerna och har väckt intresse hos både kultister och skugglärda."},{t="Ögon i skuggorna",b="I Forlorn Cavern i Ironforge anlitar en excentrisk samlare vid namn Gerrig Bonegrip djärva äventyrare för att ge sig över havet och hämta texten. Bonegrip talar vördnadsfullt om ”de sista dagarna” och gudomarnas uppvaknande. När texten väl återfunnits ska den skrivas av och delas med hans skuggfulla krets av bröder och systrar, så att förbjudna insikter sprids bland ytvarelser som aldrig var menade att förstå dem."}},faq={{q="Vad är Lorgalis Manuscript?",a="Det är en gammal text skriven av en viss Lorgalis, med mörk, esoterisk kunskap om de gamla gudarna. Dess innehåll sägs rymma hemligheterna som krävs för att öppna portar och väcka slumrande uråldriga väsen.",al={"vad är lorgalis manuscript","lorgalis boklärdom","vad gör manuskriptet"}},{q="Var finns manuskriptet?",a="Manuskriptet ligger i en gropig järnkista, nedsänkt djupt inne i Blackfathom Deeps, ett förstört nattalvstempel vid The Zoram Strand i Ashenvale.",al={"var hittar man lorgalis manuscript","manuskriptets plats","kistan i blackfathom"}},{q="Vem vill ha manuskriptet?",a="Gerrig Bonegrip, en gåtfull lärdomsväktare verksam i Forlorn Cavern i Ironforge, ger äventyrare i uppdrag att hämta det. Han tänker kopiera och sprida dess uråldriga läror bland sina hemlighetsfulla gelikar.",al={"vem vill ha lorgalis manuscript","gerrig bonegrips uppdrag","vem är bonegrip"}},{q="Varför talar Gerrig Bonegrip om de sista dagarna?",a="Bonegrip håller sig till dem som studerar och vördar de gamla gudarna. Hans intresse för uråldriga alvskrifter gäller lärdom som kan väcka ”dem som sover” och förebåda den annalkande tidens slut, som han ser det.",al={"gerrig om de sista dagarna","bonegrip kultist","bonegrip gamla gudar"}}},fx={["61ae2bf7"]={q="Var kommer Lorgalis Manuscript ifrån, och vem skrev det?",a="Manuskriptet skrevs av en person vid namn Lorgalis och ligger på botten av Blackfathom Deeps, de sjunkna ruinerna där sedan länge döda alver en gång bodde, innan deras stad föll. Det finns inga uppgifter om vem Lorgalis var. Texten redogör för förbjuden kunskap om Old Gods och Those Who Sleep och prisar Aku'mai, en tjänare åt Old Gods som bor i djupet. Manuskriptet ligger inlåst i en gropig järnkista i de översvämmade salarna.",al={"lorgalis manuscripts ursprung","vem skrev lorgalis manuscript","var skrevs lorgalis manuscript"}}},fp="19,187,25.525.0,19.394.1,32.172.0,32.139.0,25.164.0,49.155.0"}
P.entries["item:lotwil-s-shackles-of-elemental-binding"] = {n="Lotwil's Shackles of Elemental Binding",s="Lotwil Veriatus tillverkade dessa bojor för ett djärvt försök att frammana en elementarvarelse i Badlands. Att återfå dem är viktigt för hans arbete.",h="Lotwil Veriatus tillverkade dessa bojor för ett djärvt försök att frammana en elementarvarelse i Badlands.",kw={"alkemi","badlands","elementarvarelse","ingenjörskonst","fam'retor guardian","lotwil veriatus","lotwils bojor","bojor för att binda elementarvarelser"},sec={{t="En kallelse förbereds",b="I Badlands har Lotwil Veriatus färdigställt bojorna för ett remarkabelt experiment. Han kallar dit Lucien och Servo för att bevittna hans blandning av alkemi, ingenjörskonst och arkan magi. Med bindningen redo tänker Lotwil frammana en mäktig elementarvarelse."},{t="Utgången",b="Fam'retor Guardian lämnar Lotwils bojor efter sig. När du lämnar tillbaka dem tackar han dig för besväret och säger att hans magi skickade varelsen hem. Vad som än gick fel återlämnas bojorna till sin skapare."}},faq={{q="Vad är Lotwil's Shackles of Elemental Binding?",a="Det är bojor som Lotwil Veriatus tillverkade i ett försök att binda en mäktig elementarvarelse.",al={"lotwils bojor","bojor för att binda elementarvarelser","vad är bojorna"}},{q="Vem tillverkade bojorna?",a="Lotwil Veriatus tillverkade dem som en del av ett experiment som blandade alkemi, ingenjörskonst och arkan magi.",al={"vem tillverkade dem","lotwils bojtillverkare","vem är lotwil"}},{q="Var hittar jag bojorna?",a="Fam'retor Guardian i Badlands lämnar Lotwils bojor efter sig.",al={"var finns bojorna","bojornas plats","fam'retor guardian"}},{q="Varför vill Lotwil ha tillbaka bojorna?",a="Lotwil behöver få tillbaka dem efter att hans försök att frammana en mäktig elementarvarelse går snett.",al={"varför lämna tillbaka bojorna","vad behöver lotwil","bojor åt lotwil"}}},fp="38,130,20.249.0,11.217.1,48.83.0,22.99.0,30.71.1,39.86.1"}
P.entries["item:lunar-fungus"] = {n="Lunar Fungus",s="Lunar Fungus är en kraftfull medicinalväxt som skördas från svampblomster djupt inne i Darkshores grottsystem. Druidinitierade samlar dessa svampar tillsammans med vanliga örter för att brygga en läkande salva som kan behandla sjuka vilda djur.",h="Lunar Fungus är en kraftfull medicinalväxt som skördas från svampblomster djupt inne i Darkshores grottsystem.",kw={"alanndarian nightsong","auberdine","bota gift","darkshore","earthroot","lunar fungal bloom","lunar fungus"},ang={["class:Druid"]="Unga druider söker efter Lunar Fungus i Darkshores grottor som en del av sina grundläggande riter för att bemästra läkande magi och hela förgiftade vilda djur.",["race:NightElf"]="Att vårda de fördärvade skogsdjuren runt Auberdine med lokala botemedel som Lunar Fungus är en ständig plikt för Darkshores väktare."},sec={{t="Egenskaper och ekologi",b="Denna säregna svamp skördas från Lunar Fungal Blooms och trivs i mörka underjordiska grottor i hela Darkshore. Cenarion Circle värdesätter den för dess förstärkande verkan. När den blandas med en lenande vattenbas och vanlig Earthroot ger svampen den styrka som behövs för att skapa ett effektivt motmedel mot försvagande åkommor. Eftersom den främst växer i fuktiga underjordiska hålor där revirhävdande moonkin håller till, krävs varsam navigering genom den otämjda vildmarken för att få tag på den."},{t="En lektion i läkekonst",b="I Auberdine låter Alanndarian Nightsong unga druider skörda Lunar Fungus som en del av sina studier i naturens läkande krafter. Genom att se hur fysiska ingredienser som denna svamp motverkar starka gifter hos de lokala hjortarna lär sig de initierade de grundläggande principerna bakom örtmediciner, innan de går vidare till att kanalisera naturliga motgifter direkt genom skepnadsskifte och rå andlig kraft."}},faq={{q="Vad används Lunar Fungus till?",a="Lunar Fungus ger läkande kraft när en stärkande salva tillreds. Alanndarian Nightsong blandar den med Earthroot och rent vatten för att behandla sjuka hjortar i Darkshores vildmark.",al={"lunar fungus användning","vad gör lunar fungus","varför samla lunar fungus"}},{q="Var växer Lunar Fungus?",a="Den spirar ur Lunar Fungal Blooms i grottorna öster om Auberdine i Darkshore. Dessa mörka grottor delas med irriterade moonkin som försvarar sitt revir mot inkräktare.",al={"lunar fungus plats","var hittar man lunar fungus","lunar fungus blomster"}},{q="Vem behöver denna svamp i Auberdine?",a="Druiden Alanndarian Nightsong ber elever som studerar vildmarken att hämta Lunar Fungus som en del av sin träning. Dess naturliga läkande egenskaper används för att bereda botemedel åt sjuka skogsdjur.",al={"vem behöver lunar fungus","örtuppdrag i auberdine"}},{q="Varför måste druidinitierade samla fysiska örter för att bota gift?",a="Att förstå fysiska motgifter är ett grundläggande steg i druidernas utbildning. Genom att samla vilda ingredienser som Lunar Fungus och se hur specifika ämnen motverkar särskilda gifter förstår eleverna läkekonstens principer innan de lär sig att rena bort gifter direkt med andlig magi.",al={"varför druider samlar örter","druidernas träning i att bota gift"}}},fx={["2a41e7eb"]={q="Vad är Lunar Fungus?",a="Lunar Fungus är en kraftfull medicinalsvamp som växer naturligt i Darkshore. Den trivs i mörka grottor öster om Auberdine och skördas från större samlingar som kallas lunar fungal blooms. Druider värdesätter svampens naturliga styrka och använder den som en nödvändig ingrediens i alkemiska salvor mot förgiftade djur.",al={"vad är lunar fungus","information om lunar fungus","om lunar fungus"}}},fp="12,136,22.338.0,19.318.0,30.136.0,29.166.0,38.154.0,68.254.0"}
P.entries["item:lurker-venom"] = {n="Lurker Venom",s="Lurker Venom är ett kraftfullt naturligt gift som utvinns ur de rovspindlar som stryker omkring bland Loch Modans klippiga kullar och skogar. Dvärgarnas försvarare behöver detta frätande gift som en viktig ingrediens i en alkemisk neutraliserande blandning mot Dark Irons sabotage.",h="Lurker Venom är ett kraftfullt naturligt gift som utvinns ur de rovspindlar som stryker omkring bland Loch...",kw={"chief engineer hinderweir","cliff lurker","loch modan","lurker venom","shanda the spinner","spindelgift","stonewrought dam","wood lurker"},ang={["profession:Engineering"]="Att använda organiska gifter för att oskadliggöra fientlig ammunition visar hur dvärgarnas ingenjörer improviserar med reaktiva ämnen under stridsförhållanden.",["race:Dwarf"]="Bergsbestigare och försvarare i Loch Modan använder regelbundet faror i den lokala vildmarken för att skydda viktig infrastruktur i Khaz Modan mot Dark Iron-klanen."},sec={{t="Ett flyktigt reagens",b="Kullarna och klippbranterna kring Loch Modan kryllar av rovspindlar, från vanliga wood lurkers till den ökända matriarken Shanda the Spinner. Deras bett utgör en ständig fara för bergsbestigare och resenärer, men sprängämnesexperten Ashlan Stonesmirk utsåg deras giftiga sekret till en ingrediens i en desarmeringsblandning som Chief Engineer Hinderweir tillreder. Tillsammans med sällsynta mineraler och tårar som utvinns från sjöns krokolisker bildar Lurker Venom ett reaktivt lösningsmedel som kan desarmera komplicerade Dark Iron-sprängladdningar."}},faq={{q="Var kommer Lurker Venom ifrån?",a="Det utvinns ur de olika lurker-spindlar som hör hemma i Loch Modan, däribland Cliff Lurkers, Forest Lurkers, Wood Lurkers och deras kullmatriark Shanda the Spinner.",al={"hur får man tag på lurker venom","vem släpper lurker venom","var hittar man lurker venom"}},{q="Vad används Lurker Venom till?",a="Chief Engineer Hinderweir använder giftet som en del av en särskild kemisk blandning för att neutralisera och desarmera sprängladdningar som Dark Iron-infiltratörer placerat ut kring Stonewrought Dam.",al={"varför behöver jag lurker venom","vad används lurker venom till","vad gör hinderweir med giftet"}},{q="Varför använder man gift för att desarmera sprängladdningar?",a="Dvärgarnas ingenjörer förlitar sig ofta på reaktiva, sura eller frätande blandningar för att lösa upp känsliga mekaniska delar eller neutralisera instabilt sprängkrut utan att utlösa en explosion.",al={"varför använda spindelgift mot bomber","hur stoppar gift dark iron-bomber"}},{q="Är Shanda the Spinner den enda källan?",a="Nej. Shanda bär på giftet, men det går att utvinna från vilken som helst av de vanliga vilda lurker-spindlar som lever i skogarna och på Loch Modans klippbranter.",al={"måste jag döda shanda","shanda lurker venom"}}},fx={["0e11e6d3"]={q="Vad är Lurker Venom?",a="Lurker Venom är ett kraftfullt naturligt gift som utvinns ur rovspindlarna som lever i Loch Modans karga vildmark. Giftet är dödligt för byten, men dess särskilda kemiska egenskaper gör det värdefullt för specialiserade hantverkare och ingenjörer. Chefingenjör Hinderweir använder särskilt den flyktiga vätskan som ett viktigt reagens i ett alkemiskt neutraliseringsmedel, utformat för att oskadliggöra Dark Iron-dvärgarnas sprängämnen.",al={"vad är lurker venom","lurker venoms bakgrund","vad är det för slags föremål, lurker venom"}}},fp="12,147,18.533.0,34.147.0,30.160.0,37.163.0,38.133.0"}
P.entries["item:lydon-s-toxin"] = {n="Lydon's Toxin",s="Lydon's Toxin är en alkemisk blandning som Apothecary Lydon framställt i Tarren Mill för att stoppa Venture Company's skogsskövling i Stonetalon Mountains. Hordeäventyrare får i uppdrag att leverera den till Apothecary Zamah i Thunder Bluff, så att hon kan utforma ett effektivt sätt att sprida den.",h="Lydon's Toxin är en alkemisk blandning som Apothecary Lydon framställt i Tarren Mill för att stoppa Venture...",kw={"apothecary lydon","apothecary zamah","lydon's toxin","royal apothecary society","thunder bluff","toxic fogger","venture company"},ang={["race:Tauren"]="Tauren välkomnar hjälp mot Venture Company's förstörelse av naturen, men Royal Apothecary Societys kemiska metoder tänjer på gränserna för deras shamanska sinnelag.",["race:Undead"]="Transporten av Lydon's Toxin visar hur vittförgrenat Royal Apothecary Societys nätverk är. Det samordnar fältforskning mellan Lordaeron och Kalimdor för att visa sina allierade vad Forsaken kan bidra med."},sec={{t="En kunglig apotekarlösning",b="Apothecary Lydon utvecklade denna kraftfulla blandning i Hillsbrad Foothills för att bekämpa Venture Company's skadliga skogshuggare i Stonetalon Mountains. Enligt Lydon ger blandningen dödliga och potentiellt smittsamma resultat vid kontakt. Men innan ämnet kan släppas lös mot goblinernas verksamhet runt Windshear Crag måste det föras över kontinenterna till Apothecary Zamah, Royal Apothecary Societys representant i Thunder Bluff. Zamah behöver den obearbetade blandningen för att konstruera en apparat för bred spridning, Toxic Fogger, så att brygden utplånar de hänsynslösa skogsskövlarna utan att utsätta Horde-styrkor för onödig fara."}},faq={{q="Vad används Lydon's Toxin till?",a="Giftet framställdes av Apothecary Lydon för att bryta Venture Company's grepp om området kring Windshear Crag. Det är utformat för att vara förödande och potentiellt smittsamt mot de destruktiva goblinarbetarna.",al={"lydons toxins syfte","vad gör giftet","varför skapa lydons toxin"}},{q="Vem är Apothecary Lydon?",a="Apothecary Lydon är medlem i Royal Apothecary Society och är stationerad i Tarren Mill i Hillsbrad Foothills. Han är specialist på att skapa kraftfulla gifter och experimentella blandningar för att främja Forsakens mål.",al={"vem är lydon","apothecary lydon","lydons upphovsman"}},{q="Varför måste giftet till Thunder Bluff?",a="Lydon fulländade den kemiska blandningen, men den saknar en praktisk metod för storskalig spridning. Apothecary Zamah bor på Spirit Rise i Thunder Bluff, där hon studerar den lokala floran och samordnar Societyts arbete i Kalimdor. Hon tar hand om giftet för att anpassa det till ett portabelt dimspridningssystem.",al={"varför thunder bluff","varför ta giftet till zamah","apothecary zamahs syfte"}},{q="Vad händer när Zamah får giftet?",a="När Apothecary Zamah får flaskan omvandlar hon ämnet till en trycksatt aerosolapparat kallad Toxic Fogger, så att en agent kan sprida det genom hjärtat av Venture Company's läger.",al={"tillverkning av toxic fogger","vad gör zamah med giftet"}}},fx={["73882111"]={q="Vad är Lydon's Toxin?",a="Lydon's Toxin är en frätande alkemisk blandning som Apothecary Lydon från Royal Apothecary Society har tagit fram. Ämnet är särskilt utvecklat för att användas mot det goblinstyrda Venture Company och ska orsaka förödande och potentiellt smittsamma effekter när det används mot fiendens led.",al={"vad är lydon's toxin","lydon toxin","om lydon's toxin"}},["105322cc"]={q="Varför vill någon ha Lydon's Toxin?",a="De Forsaken-apotekarna och deras allierade i Horde vill ha toxinet för att utrota Venture Companys inträngande agenter. Apothecary Zamah behöver Lydon's brygd för att kunna konstruera en effektiv spridningsmekanism, så att Horde kan sprida dess dödliga, smittsamma effekter över fiendens arbetsplatser.",al={"varför vill de ha lydon's toxin","varför behövs toxinet","vad används lydon's toxin till"}}},fp="13,212,27.420.0,31.148.0,24.179.0,47.216.0,44.177.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="MacGrann's Dried Meats",s="MacGrann's Dried Meats är en månads ranson av saltade proviantvaror som jägaren Tundra MacGrann tillredde för att klara den hårda vintern i Dun Morogh. Hela förrådet stals av den våldsamma yetin Old Icebeard från en förstärkt köttkista av thorium.",h="MacGrann's Dried Meats är en månads ranson av saltade proviantvaror som jägaren Tundra MacGrann tillredde för...",kw={"chill breeze valley","dun morogh","macgrann's dried meats","köttkista","old icebeard","tundra macgrann"},ang={["profession:Cooking"]="Att salta och torka vilt är en viktig överlevnadsteknik i Dun Morogh. Den låter jägare som MacGrann bevara kött i flera månader utan att det förstörs i den isande kylan.",["race:Dwarf"]="Dvärgarnas bergsklättrare vet alltför väl att förberedelser är nyckeln till överlevnad på de höga topparna, och att ett förlorat vinterförråd kan vara skillnaden mellan liv och död."},sec={{t="Ett vinterförråd",b="Livet bland Dun Moroghs iskalla bergsklyftor kräver noggrann planering. För att förbereda sig på den kalla årstidens snöstormar jagade dvärgjägaren Tundra MacGrann vilt i flera veckor, saltade köttet och låste in det i en stadig kista. Eftersom han visste att björnar och kringströvande rovdjur ofta hemsökte hans gård tog MacGrann inga risker, utan låste in matförrådet i en köttkista av thorium. Trots försiktighetsåtgärderna hade han inte räknat med en inkräktare stark nog att bära bort hela kistan i stället för att försöka bryta upp den på plats."},{t="In i yetins håla",b="Medan MacGrann var borta för att spåra hjortar plundrade den ökända yetin Old Icebeard jägarens läger och släpade den tunga kistan till sitt näste i Chill Breeze Valley. Odjuret kunde inte forcera den massiva thoriumplåten, men MacGranns skadade ben hindrade honom från att snabbt rädda förrådet ur grottan. Utan hjälp att hämta förrådet innan vintern kom stod den strandsatta jägaren inför svält bland bergens snö."}},faq={{q="Vad är MacGrann's Dried Meats?",a="Det är en månads förråd av saltad proviant som Tundra MacGrann bevarade för att klara den bistra vintern i Dun Morogh.",al={"vad är macgrann's dried meats","tundras kött","macgranns köttförråd"}},{q="Varför låstes köttet in i en kista?",a="Dun Morogh kryllar av hungriga rovdjur som bergsbjörnar. MacGrann förvarade sitt torkade kött i en förstärkt köttkista av thorium, så att asätande bestar inte kunde komma åt hans vinterförråd.",al={"varför låsa in köttet","varför en thoriumkista","macgranns kista"}},{q="Vem stal köttkistan?",a="En hotfull yeti vid namn Old Icebeard stal hela kistan medan MacGrann var borta och jagade hjortar. Den släpade den tunga behållaren till sitt grottnäste i Chill Breeze Valley.",al={"vem tog köttet","vem stal det","tjuven som stal köttkistan"}},{q="Varför kan inte Tundra MacGrann hämta tillbaka köttet själv?",a="MacGrann har skadat benet och saknar därför den snabbhet och smidighet som krävs för att smyga in i Old Icebeards håla och ta sig därifrån innan den våldsamma yetin hinner fånga honom.",al={"varför hämtar inte macgrann det","varför behöver tundra hjälp","tundra skadad"}}},fx={["1f8f3b04"]={q="Varifrån kommer MacGrann's Dried Meats, och vem tillagade dem?",a="Det här torkade köttet bereddes och saltades av Tundra MacGrann, en bergsbestigare som bor ute i Dun Moroghs kalla vildmark. Han konserverade en hel månads ransoner för att klara den hårda, iskalla årstiden som väntade och förvarade dem omsorgsfullt i ett tungt thoriumskåp, innan det lokala odjuret Old Icebeard ingrep.",al={"vem gjorde macgrann's dried meats","varifrån kommer det torkade köttet","macgranns kött ursprung"}},["6a0307bf"]={q="Varför vill Tundra MacGrann ha tillbaka sitt torkade kött?",a="Utan sitt konserverade förråd riskerar Tundra MacGrann att svälta när de kraftiga snöbyarna sveper över Dun Morogh. Det motsvarar en hel månads saltade förråd. Eftersom ett skadat ben hindrar honom från att våga sig in i Old Icebeards håla för att hämta det, är köttet livsviktigt för att han ska överleva den kommande vintern.",al={"varför vill tundra ha köttet","varför hämta det torkade köttet","varför behövs macgranns kött"}}},fp="22,188,14.351.0,20.394.0,32.110.0,37.176.0,26.124.0,53.88.0"}
P.entries["item:mackreel-s-moonshine"] = {n="MacKreel's Moonshine",s="MacKreel's Moonshine är en stark dvärgdryck som bryggs av Foggy MacKreel, stationerad på den sönderslagna Thandol Span norr om Wetlands. Den är stark nog att slå ut en vaktpost i tjänst och uppskattas så långt norrut som Southshore, där Brewmeister Bilger tar emot den som betalning för skulder.",h="MacKreel's Moonshine är en stark dvärgdryck som bryggs av Foggy MacKreel, stationerad på den sönderslagna...",kw={"brewmeister bilger","dvärgbrygd","foggy mackreel","mackreel's moonshine","hembränd sprit","southshore","wetlands"},ang={["profession:Cooking"]="Även om den destilleras som grov hembränd sprit snarare än fint matlagningsvin är starka regionala drycker som Foggys en stapelvara på gränslandets värdshus.",["race:Dwarf"]="Dvärgar känner igen en god och stark dryck på lukten, och Foggys hembrända sprit har helt klart nog med kraft för att slå en bergsman till marken."},sec={{t="En stark dryck",b="Den här hembrända spriten bryggs av vakten Foggy MacKreel på Thandol Span och har ett ökänt rykte för sin styrka. Till och med härdade dvärgiska vaktposter slås ut efter en natt med drycken och vaknar med huvudvärk som om en brigad belägringsmaskiner rullat fram ovanför dem. Trots den hårda effekten värderas den högt för att värma resenärer mot Lordaerons och Khaz Modans fuktiga kyla."},{t="Betalning till Southshore",b="Foggy MacKreel hade dragit på sig en obetald skuld till Brewmeister Bilger, värdshusvärden och mästerbryggaren i Southshore. För att betala av skulden bytte Foggy bort en sats av sin hembrända sprit i stället för mynt. Bilger tar gärna emot drycken i stället för guld och vill lägga MacKreel's starka brygd i sitt lager inför de kyliga dagarna vid Hillsbrad Foothills kust."}},faq={{q="Vem gör MacKreel's Moonshine?",a="Den destilleras av Foggy MacKreel, en dvärgisk vaktpost stationerad på den sönderslagna delen av Thandol Span mellan Wetlands och Arathi Highlands.",al={"skaparen av mackreels moonshine","vem bryggde den","foggy mackreels sprit"}},{q="Varför skickas den hembrända spriten till Southshore?",a="Foggy MacKreel var skyldig Brewmeister Bilger i Southshore pengar. I stället för mynt gick han med på att betala sin förfallna skuld genom att skicka Bilger en färsk sats av sin hembrända sprit.",al={"varför southshore","leverans av hembränd sprit","brewmeister bilgers skuld"}},{q="Hur stark är MacKreel's Moonshine?",a="Den är exceptionellt stark. Foggy erkände att han däckat på tjänsten efter att ha druckit den och klagade sedan på en huvudvärk som kändes som om en hel brigad belägringsmaskiner mullrade över hans skalle.",al={"hur stark är den","hembränd spritens styrka","effekter av mackreels moonshine"}},{q="Varför måste leveransen skyndas på?",a="Foggy drack mycket och sov igenom sitt vaktpass. Först när han vaknade insåg han att han bara hade några minuter kvar innan tidsfristen för skulden till Brewmeister Bilger löpte ut.",al={"varför tidsbegränsad","är uppdraget tidsbegränsat","varför bråttom"}}},fx={abca7076={q="Vad är MacKreel's Moonshine?",a="MacKreel's Moonshine är en stark, hemgjord sprit som bryggs av Foggy MacKreel i Wetlands. Den är ökänd för sin enorma styrka och kan ge till och med en tålig dvärg en baksmälla som känns som om en belägringsmotorbrigad kört över hans huvud. Förutom sin formidabla styrka fungerar den som värdefull bytesvara och efterfrågas ända uppe i Hillsbrad Foothills för att värma folk under kyliga dagar.",al={"vad är mackreel's moonshine","mackreels moonshine","foggy mackreels dryck"}}},fp="20,161,13.281.0,21.302.0,31.138.0,47.148.0,35.182.0,40.134.0"}
P.entries["item:maggot-eye-s-paw"] = {n="Maggot Eye's Paw",s="Maggot Eye's Paw är den makabra trofén som togs från gnollhövdingen Maggot Eye vid Garren's Haunt. Den förs tillbaka till Brill och fungerar som fysiskt bevis på att odjuret avrättats för gravplundring åt Scourge.",h="Maggot Eye's Paw är den makabra trofén som togs från gnollhövdingen Maggot Eye vid Garren's Haunt.",kw={"belöning","brill","executor zygand","garren's haunt","gnoll","maggot eye","maggot eye's paw","tirisfal glades"},ang={["race:Undead"]="För de Förkastade i Brill är det ett direkt slag mot kroppstjuvarna att föra tillbaka Maggot Eye's tass. De förser den hatade Lich King med råmaterial."},sec={{t="Bevis på avrättning",b="Maggot Eye väckte de Förkastades hårda vrede genom att plundra gravar och härja på landsbygden nära Garren's Haunt. Han försåg Lich King's arméer med lik för att stärka deras led. Som svar utfärdades en formell dödsdom och en belöning utlystes i Brill. För militära administratörer som Executor Zygand räcker rykten om ett dödsfall aldrig. Prisjägare måste därför hugga av skurkens tass och föra den tillbaka till staden för att få sin belöning och avsluta efterlysningen."}},faq={{q="Varför vill Executor Zygand ha Maggot Eye's tass?",a="Executor Zygand kräver obestridliga bevis på att den dömda gnollen verkligen har dödats. En avhuggen tass bekräftar avrättningen fysiskt innan Brill betalar ut belöningen.",al={"varför tassen","bevis på maggot eyes belöning","zygands tass"}},{q="Vilka brott begick Maggot Eye mot de Förkastade?",a="Maggot Eye ledde plundringståg genom de norra delarna av Tirisfal Glades. Han stal särskilt begravda lik från gårdar som Garren's Haunt för att förse Lich King's arméer.",al={"maggot eyes brott","varför är maggot eye efterlyst","vad gjorde maggot eye"}},{q="Var finns Maggot Eye?",a="Maggot Eye håller till vid Garren's Haunt, en förfallen gård norr om Brill i Tirisfal Glades. Han lurar vanligtvis inne i det fallfärdiga boningshuset.",al={"maggot eyes plats","var hittar man maggot eye","gnoll vid garrens haunt"}},{q="Varför samarbetar gnoller med Lich King's styrkor?",a="Gnoller är av naturen opportunistiska asätare, men laglösa grupper i Tirisfal Glades har allierat sig med Scourge eller fallit under dess inflytande. De plundrar människors och Förkastades gravar och levererar kropparna till nekromantiker.",al={"gnoller och scourge","varför stjäl gnoller kroppar","scourge-gnoller"}}},fx={["9017e45e"]={q="Vad är Maggot Eye's Paw?",a="Det är den avhuggna tassen från den ökända gnollen Maggot Eye. Att ta med den är ett obestridligt, fysiskt bevis för myndigheterna i Brill på att odjuret har avrättats.",al={"vad är maggot eye's paw","maggot eye's paw","vad är det här för tass"}},e496e47e={q="Varifrån kommer Maggot Eye's Paw, och vem gjorde den?",a="Det är inget tillverkat föremål, utan en trofé som skurits direkt från liket efter Maggot Eye själv, en förrädisk gnoll som håller till kring Garren's Haunt i Tirisfal Glades.",al={"varifrån kommer maggot eye's paw","maggot eye's paw ursprung","vem gjorde maggot eye's paw"}}},fp="16,148,18.356.0,47.139.0,55.167.0,26.138.0,51.166.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="Maggran's Reserve Letter",s="Maggran's Reserve Letter är en officiell försändelse som Maggran Earthbinder skrev vid Sun Rock Retreat. Den fördes tvärs över Kalimdor till The Great Lift och ger en länge väntad avlösning åt en vaktpostering, så att vakten kan återvända hem och hälsa på sin familj.",h="Maggran's Reserve Letter är en officiell försändelse som Maggran Earthbinder skrev vid Sun Rock Retreat.",kw={"the barrens","earthbinder","grish","brev","hiss","longrunner","maggran","reserv","stonetalon"},ang={["faction:Horde"]="Meddelandet visar hur Horden efter kriget försöker ta hand om sina utspridda styrkor genom att skicka nya reserver till avlägsna utposter runtom Kalimdor."},sec={{t="En vaktpostering avlöst",b="Att hålla vakt vid utposter över Kalimdors karga vidder kräver vaksamhet, men Hordens ledare inser att långvarig vakttjänst tär hårt på moralen. Maggran Earthbinder skrev detta enkla meddelande bland Sun Rock Retreats höga klippor. Det fungerar som officiella order som meddelar Grish Longrunner att en ersättare har skickats för att ta över hans post vid The Great Lift. För en ensam vakt som bevakar de väldiga vinscharna av trä långt i söder utlovar brevet något sällsynt i oroliga tider: en hedervärd ledighet för att återförenas med familjen."}},faq={{q="Vad är syftet med Maggran's Reserve Letter?",a="Brevet innehåller officiella order från Maggran Earthbinder om att avlösa vakten Grish Longrunner från hans post vid The Great Lift i södra The Barrens, så att han kan återvända hem och hälsa på sin familj.",al={"vad gör brevet","syftet med maggrans brev","varför leverera brevet"}},{q="Vem skrev brevet?",a="Brevet skrevs av Maggran Earthbinder, en äldste som bor vid Sun Rock Retreat i Stonetalon Mountains.",al={"vem skrev det","författaren till reservbrevet","maggran earthbinder"}},{q="Vem ska ta emot det?",a="Det är adresserat till Grish Longrunner, en vakt i Horden som är stationerad högst upp vid The Great Lift, som förbinder södra The Barrens med Thousand Needles.",al={"vem får brevet","brevets mottagare","vart ska det"}},{q="Vart levereras brevet?",a="Det måste föras söderut genom The Barrens till kanten av Thousand Needles-ravinen, där The Great Lift står.",al={"leveransplats","var är grish","var ligger the great lift"}}},fx={["419ae143"]={q="Vad är Maggran's Reserve Letter?",a="Det är ett officiellt skriftligt meddelande som Maggran Earthbinder skrev på Sun Rock Retreat i Stonetalon Mountains. Meddelandet talar om för Horde-vakten Grish Longrunner, som är stationerad där, att en reservkrigare skickas för att ta över hans post och ge honom ledigt så att han kan besöka sin familj.",al={"vad är maggran's reserve letter","maggrans brev","reservbrev"}},eb8a36e5={q="Varför vill Grish Longrunner ha Maggran's Reserve Letter?",a="Grish begärde avlösning från sin post för länge sedan och väntar ivrigt på besked. Att bevaka The Great Lift i södra Barrens är en enformig uppgift, och brevet godkänner formellt att en reservkrigare ersätter honom. Därmed får han äntligen den efterlängtade ledigheten att besöka sin familj.",al={"varför vill grish ha brevet","varför efterfrågas reservbrevet","varför behövs maggran's reserve letter"}}},fp="24,172,17.346.0,48.187.0,21.101.0,27.158.0,30.114.0"}
P.entries["item:magma-core-classic"] = {n="Magma Core",s="Magma Core är hjärtat i Magma Lord Bokk, en elementarvarelse i Burning Steppes. Mux Manascrambler behöver dess jämna hetta för att driva en utomdimensionell spökavslöjare.",h="Magma Core är hjärtat i Magma Lord Bokk, en elementarvarelse i Burning Steppes.",kw={"bokk","burning steppes","ektoplasma","gadgetzan","spökavslöjare","magma core","magma lord bokk","mux manascrambler","bärbar kraftkälla"},ang={["profession:Engineering"]="Som ingenjör kanske du förstår varför Mux vill ha en bärbar kraftkälla: han tänker använda Magma Core för att driva en utomdimensionell spökavslöjare."},sec={{t="Ett hjärta av hetta",b="Magma Lord Bokk bor i Burning Steppes, söder om Blackrock Mountain. Hans Magma Core rymmer en outsinlig värmekälla. Mux Manascrambler i Gadgetzan vill ha den för att hålla ektoplasma aktiv och driva en utomdimensionell spökavslöjare."}},faq={{q="Vad är Magma Core?",a="Magma Core är hjärtat i Magma Lord Bokk, en mäktig elementarvarelse i Burning Steppes. Den rymmer en kraftfull värmekälla.",al={"magma core","bokks hjärta"}},{q="Vem vill ha Magma Core?",a="Mux Manascrambler i Gadgetzan vill ha Magma Core för att driva en utomdimensionell spökavslöjare.",al={"vem behöver magma core","mux kraftkälla"}},{q="Var finns Magma Lord Bokk?",a="Magma Lord Bokk finns i Burning Steppes, söder om Blackrock Mountain.",al={"var finns bokk","bokks plats"}},{q="Varför behöver Mux den?",a="Mux behöver en stabil, bärbar energikälla för att hålla ektoplasma aktiv och driva sin utomdimensionella spökavslöjare.",al={"varför magma core","spökavslöjarens kraft"}}},fp="10,170,15.235.0,23.126.0,25.97.0,25.81.0,21.118.0"}
P.entries["item:maiden-s-folly-charts"] = {n="Maiden's Folly Charts",s="Maiden's Folly Charts är navigationshandlingar som bärgats från ett vrak i Arathi Highlands. First Mate Nilzlix vill säkra dem innan skeppen lämnar viken.",h="Maiden's Folly Charts är navigationshandlingar som bärgats från ett vrak i Arathi Highlands.",kw={"arathi highlands","booty bay","sjökort","bärgning på djupt vatten","first mate nilzlix","maiden's folly","maiden's folly charts"},sec={{t="Sjökort från vraket",b="I Arathi Highlands ligger Maiden's Folly som vrak bredvid Spirit of Silverpine. Sjökorten och loggböckerna innehåller uppgifter som besättningen fruktar kan hamna i fiendens händer. First Mate Nilzlix ber dig bärga sjökorten, även dem från Maiden's Folly, och föra dem till Booty Bay."}},faq={{q="Vad är Maiden's Folly Charts?",a="Det är navigationssjökort som tillhörde Maiden's Folly, som nu ligger som vrak i Arathi Highlands.",al={"maiden's folly charts","follys sjökort","vilka sjökort"}},{q="Var hittar jag sjökorten?",a="Maiden's Folly ligger som vrak i en vik i Arathi Highlands.",al={"var finns sjökorten","hitta follys sjökort","sjökortens plats"}},{q="Vem vill att sjökorten bärgas?",a="First Mate Nilzlix ber dig bärga Maiden's Folly Charts och skeppens övriga handlingar.",al={"vem vill ha dem","nilzlix sjökort","förste styrman"}},{q="Varför måste sjökorten säkras?",a="Besättningen fruktar att sjökorten och loggböckerna kan hamna i fiendens händer, och Fleet Master Seahorn skulle hålla dem ansvariga.",al={"varför bärga sjökort","fiendens händer","varför sjökorten är viktiga"}},{q="Vart ska sjökorten?",a="De bärgade sjökorten ska till befälet i Booty Bay.",al={"vart lämna sjökorten","booty bay sjökort","sjökortens destination"}}},fp="21,165,21.292.0,35.102.0,28.66.0,31.94.0,31.117.0,25.60.0"}
P.entries["item:maiden-s-folly-log"] = {n="Maiden's Folly Log",s="Maiden's Folly Log är kaptenens loggbok från ett skepp som förliste vid Arathis rev. Sidorna och sjökorten innehåller information som Fleet Master Seahorn vill hålla borta från nyfikna blickar.",h="Maiden's Folly Log är kaptenens loggbok från ett skepp som förliste vid Arathis rev.",kw={"arathi","booty bay","kaptenens loggbok","bärgning på djuphavet","loggbok","maiden's folly","nilzlix","rev","seahorn","tempel"},sec={{t="Ett vraks loggbok",b="First Mate Nilzlix söker efter loggboken från Maiden's Folly, som förliste tillsammans med Spirit of Silverpine. Skeppen gick på grund vid ett tempel på revet när tidvattnet började sjunka och gick snabbt under. Deras loggböcker är viktiga för befälet i Booty Bay, som fruktar att informationen kan hamna i fiendens händer."}},faq={{q="Vad är Maiden's Folly Log?",a="Det är kaptenens loggbok från Maiden's Folly, ett av skeppen som förliste vid Arathis rev.",al={"maiden's folly loggbok","kaptenens loggbok","skeppets loggbok"}},{q="Var sjönk Maiden's Folly?",a="Maiden's Folly gick på grund vid ett tempel på revet i Arathi och sjönk.",al={"var ligger vraket","maiden folly plats","skeppsvrak arathi"}},{q="Varför vill First Mate Nilzlix ha loggboken?",a="First Mate Nilzlix vill att loggboken och sjökorten från Maiden's Folly bärgas innan informationen hamnar i fiendens händer.",al={"varför bärga loggboken","vad vill nilzlix ha","varför hämta boken"}},{q="Vad hände med Maiden's Folly?",a="Tidvattnet började sjunka när Maiden's Folly närmade sig en vik, och skeppet gick på grund vid ett tempel på revet innan det sjönk.",al={"maiden folly vrak","hur sjönk det","vad hände med skeppet"}},{q="Vem vill hålla dokumenten säkra?",a="Fleet Master Seahorns befäl i Booty Bay vill hålla loggböckerna och sjökorten borta från nyfikna blickar.",al={"vem vill ha sjökorten","fleet master seahorn","booty bay dokument"}}},fp="18,172,16.292.0,31.91.0,34.67.0,41.119.0,36.122.0,32.92.0"}
P.entries["item:malem-pendant"] = {n="Malem Pendant",s="Malem Pendant finns i en vagn i Desolace. Vahlarriel Demonslayer vid Nijel’s Point behöver den och besked om spår som leder söderut.",h="Malem Pendant finns i en vagn i Desolace.",kw={"desolace","fotspår","fort","malem","malem pendant","nijel's point","vahlarriel demonslayer","vagn"},sec={{t="En ledtråd i vagnen",b="Fotspår leder söderut från vagnen där du hittar Malem Pendant. Rök stiger från ett närbeläget fort, och den jämna elden tyder på att människor finns där. Vahlarriel Demonslayer vid Nijel’s Point behöver se hänget och höra vad du hittat."}},faq={{q="Var ska jag lämna in Malem Pendant?",a="Lämna Malem Pendant till Vahlarriel Demonslayer vid Nijel’s Point i Desolace.",al={"var lämna in hänget","lämna in hänget","var finns malem pendant"}},{q="Var hittades hänget?",a="Du hittar Malem Pendant i en vagn i Desolace.",al={"var finns hänget","hängets plats","hitta malem pendant"}},{q="Vilka ledtrådar fanns nära hänget?",a="Fotspår leder söderut från vagnen, och rök stiger från ett närbeläget fort.",al={"spår och rök","vilka ledtrådar","ledtrådar vid vagnen"}},{q="Varför behöver Vahlarriel höra om fortet?",a="Vahlarriel letar efter Malems, och spåren och röken tyder på att de kan ha förts till fortet.",al={"varför berätta för vahlarriel","besked om fortet","vad behöver vahlarriel"}}},fp="13,143,19.241.0,34.80.0,28.50.0,33.73.0,48.114.1"}
P.entries["item:mangy-claw"] = {n="Mangy Claw",s="Mangy Claw är en avhuggen klo från den väldiga isklo-björnen Mangeclaw i Dun Morogh. Den är ett kusligt bevis på att det dödliga odjur som dödade en strandsatt dvärgpilot äntligen har fällts.",h="Mangy Claw är en avhuggen klo från den väldiga isklo-björnen Mangeclaw i Dun Morogh.",kw={"dun morogh","hildelve","isklo-björn","mangeclaw","mangy claw","pilot hammerfoot","belägringsbrigad"},ang={["class:Hunter"]="Att spåra upp ett ökänt rovdjur som Mangeclaw i bergens våldsamma snöstormar sätter jägarens förmåga att fälla farliga, revirhävdande bestar på prov.",["race:Dwarf"]="För dvärgar handlar det om djup personlig och klanmässig heder att uppfylla en fallen kamrats sista önskan och hämnas en medlem av Ironforges belägringsbrigad."},sec={{t="En döende pilots önskan",b="När Pilot Hildelves ångstridsvagn gick sönder i Dun Moroghs frusna kullar fortsatte han till fots sitt sökande efter malm, men blev ensam i vildmarken. I sin återfunna dagbok berättar Hildelve hur han lyckades slå tillbaka ett första angrepp från den monstruösa isklo-björnen Mangeclaw, men blev svårt sargad i striden. Odjuret återvände senare för att döda den försvagade piloten. I sin sista anteckning bad Hildelve om hämnd på rovdjuret. Hans önskan uppfylldes när Mangy Claw togs från den fallna björnen."},{t="Hämnd för belägringsbrigaden",b="När Mangy Claw lämnas till Pilot Hammerfoot får Ironforges belägringsbrigad ett avslut. Hammerfoot hade skickat ut sökare i snödrivorna i hopp om att hitta sin vän vid liv, men fick i stället veta hans dystra öde. Hildelves dagbok och rovdjurets avhuggna klo visar att hans sista önskan uppfylldes. Nu kan han vila, och Ironforges piloter är tacksamma."}},faq={{q="Vad är Mangy Claw?",a="Det är en trofé, avhuggen från Mangeclaw, en vild isklo-björn som stryker omkring i Dun Morogh. Den är ett fysiskt bevis på att odjuret har spårats upp och dödats.",al={"mangy claw syfte","vad är den här klon","mangeclaw föremål"}},{q="Vem vill ha Mangy Claw?",a="Pilot Hammerfoot, som är stationerad nära bergspassen i Dun Morogh, vill ha klon och sin fallne vän Hildelves dagbok för att få bekräftat att björnen som dödade honom är död.",al={"vem tar emot mangy claw","lämna in mangy claw","lämna in till pilot hammerfoot"}},{q="Varför behövde Mangeclaw jagas?",a="Dvärgpiloten Hildelve letade efter malm till fots efter att hans ångstridsvagn gått sönder. Mangeclaw sargade honom svårt och dödade honom till sist. I sin personliga dagbok skrev Hildelve att hans sista önskan var att någon skulle hämnas på odjuret.",al={"varför döda mangeclaw","vem dödades av mangeclaw","hildelves historia"}},{q="Var stryker Mangeclaw omkring?",a="Mangeclaw stryker omkring på Dun Moroghs snötäckta bergsryggar och kullar, inte långt från platsen där Pilot Hildelves kvarlevor hittades.",al={"mangeclaws plats","var finns mangeclaw","mangeclaw dun morogh"}}},fx={["554d85fa"]={q="Varifrån kommer Mangy Claw?",a="Mangy Claw tas direkt från Mangeclaw, en vild isklobjörn som strövar omkring i Dun Moroghs frusna vildmark. Det är inget tillverkat föremål, utan en makaber, fysisk trofé som skärs från odjuret efter att det har dödats.",al={"mangy claw källa","varifrån får man mangy claw","vem har mangy claw"}}},fp="10,173,20.396.0,31.302.1,23.125.0,25.184.0,36.192.0,36.105.0"}
P.entries["item:maraudine-key-fragment"] = {n="Maraudine Key Fragment",s="Maraudine Key Fragment hålls av Khan Hratha i Desolace. Gelkis och Magram söker den i sin kamp mot Maraudine.",h="Maraudine Key Fragment hålls av Khan Hratha i Desolace.",kw={"gelkis","khan hratha","magram","maraudine","maraudine key fragment","uthek the wise","valley of spears","warug"},sec={{t="En nyckelbit",b="Khan Hratha bär Maraudine Key Fragment i Valley of Spears. Gelkis ber om den efter att han har dödats, och Magram ställer samma krav. Varje klan söker fragmentet som en del av sin kamp mot Maraudine."}},faq={{q="Vem har Maraudine Key Fragment?",a="Khan Hratha har Maraudine Key Fragment i Valley of Spears.",al={"vem har fragmentet","hratha nyckelbit","maraudine-fragment"}},{q="Vem vill ha fragmentet?",a="Uthek the Wise ber om fragmentet i Gelkis Village, medan Warug ber om det i Magram Village.",al={"vem vill ha nyckeln","gelkis eller magram","vart ta fragmentet"}},{q="Varför vill Gelkis ha det?",a="Gelkis ber dig att ta med fragmentet till dem efter att Khan Hratha har dödats.",al={"gelkis vill ha fragmentet","uthek nyckelbit","varför behöver gelkis nyckeln"}},{q="Varför vill Magram ha det?",a="Magram ber dig att ta med fragmentet efter att Khan Hratha har dödats.",al={"magram vill ha fragmentet","warug nyckelbit","varför behöver magram nyckeln"}}},fp="22,133,16.225.0,35.69.0,23.98.0,26.73.1,26.68.1"}
P.entries["item:margol-s-gigantic-horn"] = {n="Margol's Gigantic Horn",s="Margol’s Gigantic Horn är en sliten trofé från Searing Gorge. Mountaineer Pebblebitty behöver den innan han överväger att öppna Stonewrought Pass.",h="Margol’s Gigantic Horn är en sliten trofé från Searing Gorge.",kw={"trasigt yxhuvud","lochmodan","margol","margol the rager","margol’s gigantic horn","mountaineer pebblebitty","searing gorge","stonewrought pass"},sec={{t="En grov trofé",b="I Searing Gorge är Margol’s Gigantic Horn ett märkligt fynd för den som söker en väg genom Stonewrought Pass. Repor och sprickor täcker den grova ytan, och en ovanlig metallbit sitter fast i hornet. Mountaineer Pebblebitty är den som vill se det."}},faq={{q="Vem vill ha Margol’s horn?",a="Mountaineer Pebblebitty vill se Margol’s Gigantic Horn. Han finns vid passet mellan Loch Modan och Searing Gorge.",al={"vem vill ha det","pebblebittys horn","var lämna hornet"}},{q="Var hittar jag hornet?",a="Margol’s Gigantic Horn kommer från Margol the Rager i Searing Gorge.",al={"hornets plats","hitta margols horn","var är hornet"}},{q="Varför behöver Pebblebitty hornet?",a="Pebblebitty ber att få se Margol’s Gigantic Horn innan han överväger att öppna Stonewrought Pass mellan Loch Modan och Searing Gorge.",al={"varför pebblebitty vill ha det","vad ska hornet användas till","varför ta hornet"}},{q="Vad sitter fast i hornet?",a="Ett trasigt yxhuvud sitter fast i den grova ytan. På metallen står orden ”Mountaineer Pebblebittys egendom”.",al={"metall i hornet","vad sitter fast i det","yxhuvud"}},{q="Varför kallar Pebblebitty det falskt?",a="Pebblebitty hävdar bestämt att hornet är för litet för att tillhöra Margol och säger att Margols horn är minst åtta gånger större.",al={"falskt horn","pebblebitty säger att det är falskt","är det äkta"}}},fp="22,149,14.266.0,26.118.0,26.70.0,35.136.0,27.118.1,34.116.1"}
P.entries["item:marshal-haggard-s-badge"] = {n="Marshal Haggard's Badge",s="På sin gård i Elwynn har Marshal Haggard blivit av med märket han bar i Stormwinds tjänst. Dead-tooth Jack stal det genom list, och Defias kan använda det för att utge sig för att vara stadens tjänstemän.",h="På sin gård i Elwynn har Marshal Haggard blivit av med märket han bar i Stormwinds tjänst.",kw={"dead-tooth jack","defias","elwynn forest","marshal dughan","marshal haggard","marshal haggard's badge","stormwind","kassaskrin"},ang={["class:Warrior"]="Som krigare bevisar du ditt mod för en veteran från Stormwinds militär när du återfår Haggards märke. Han belönar lovande krigare med välskötta överskottsvapen från sina stridsdagar.",["faction:Alliance"]="Som medlem i Alliansen skyddar du Stormwinds militära ledning när du hämtar märket och hindrar Defias Brotherhood från att undergräva det lokala försvaret inifrån."},sec={{t="Ett stulet märke",b="Marshal Haggard drog sig tillbaka till en liten gård i kullarna i Elwynn Forest, men hans gamla Stormwind-märke som marskalk har fortfarande officiell tyngd. En natt bar Dead-tooth Jack, en Defias-skurk, en Stormwind-tabard och utgav sig för att vara Marshal Dughan, Goldshires garnisonsbefälhavare. Han lurade Haggard att tro att hans tidigare vapenbröder behövde märket i tjänsten. Den åldrande marskalken lämnade över det utan misstankar. Jack flydde in i skogen innan Haggard genomskådade bluffen. I Defias händer kan Stormwinds maktemblem låta laglösa passera vägspärrar eller förvirra lokala patruller."}},faq={{q="Vad är Marshal Haggard's Badge?",a="Det är ett officiellt tjänstemärke som Marshal Haggard bar när han tjänade kungariket Stormwind. Trots att han gått i pension har han fortfarande ett märke med verklig auktoritet.",al={"haggards märke","marskalkens märke"}},{q="Hur fick Dead-tooth Jack tag på märket?",a="Dead-tooth Jack kom hem till Marshal Haggard om natten, iklädd en Stormwind-tabard. Haggard trodde att han var Marshal Dughan från Goldshire och lämnade över märket när Jack bad om det.",al={"hur stals märket","vem stal märket","dead-tooth jacks trick"}},{q="Varför är märket farligt i Defias händer?",a="En Defias-agent med det äkta märket och en förklädnad kan utge sig för att vara en högt uppsatt tjänsteman i Stormwind, ta sig förbi vaktposter, komma in i garnisoner eller ge falska order till stadsvakter.",al={"varför vill jack ha märket","defias användning av märket","märkets fara"}},{q="Var förvaras märket?",a="Dead-tooth Jack låste in märket i sin kassaskrin på lägerplatsen söder om Marshal Haggards gård i Elwynn Forest.",al={"märkets plats","var hittar man märket","dead tooths kassaskrin"}}},fp="23,187,17.593.0,32.166.0,38.185.0,54.188.0,24.115.0"}
P.entries["item:mary-s-looking-glass"] = {n="Mary's Looking Glass",s="Mary's Looking Glass är en övergiven handspegel som Blind Mary en gång höll kär innan en tragedi tog hennes syn och liv. Den lämnades i Duskwoods hemsökta dungar och plockades upp av en kringvandrande ghoul innan den eftersöktes för att fullborda Viktori Prism'Antras teleskop.",h="Mary's Looking Glass är en övergiven handspegel som Blind Mary en gång höll kär innan en tragedi tog hennes...",kw={"blind mary","darkshire","duskwood","insane ghoul","blicka mot stjärnorna","spegel","mary's looking glass","tranquil gardens cemetery","viktori prism'antras"},ang={["faction:Alliance"]="Att återta reliker från fasorna som hemsöker Tranquil Gardens Cemetery ger Darkshires hårt prövade invånare ett visst avslut och hjälper stadens projekt.",["profession:Engineering"]="Ingenjörer kan uppskatta Viktoris uppfinningsrikedom när han gör om en antik hushållsspegel till en fungerande optisk reflektor för ett astronomiskt observationsinstrument."},sec={{t="En övergiven skatt",b="Före sitt hemska öde höll Blind Mary denna polerade spegel kär. Efter sin död och förlusten av sina ögon blev det en plågsam påminnelse om vad hon hade förlorat att se sin spegelbild. Hon kastade bort spegeln bakom sin lada och lämnade den åt Duskwoods framryckande mörker. Där hamnade den i klorna på en Insane Ghoul som strövade omkring i de förstörda utkanterna och bar smycket söderut till kryptorna på Tranquil Gardens Cemetery."},{t="Ögon mot himlen",b="I Darkshire drömde den excentriske stjärnskådaren Viktori Prism'Antras om att blicka genom Duskwoods eviga skymning mot den orörda himlen ovanför. För att bygga sitt teleskop behövde han specialslipade optiska linser och reflekterande glas. När Mary fick höra om hans behov skickade hon äventyrare för att jaga de förvildade odöda som strök omkring i kyrkogårdens förstörda kapell och återta spegeln, så att den kunde fungera som reflektor i hans storslagna stjärnskådningsmaskin."}},faq={{q="Varför kastade Mary bort spegeln?",a="Spegeln var en gång en av Marys finaste skatter, men hon kastade bort den bakom ladan efter en händelse som hon inte beskriver helt. Vid ett annat möte förklarar hon att hon slet ut sina egna ögon eftersom hon inte stod ut med sitt utseende.",al={"varför mary kastade bort den","varför kasta bort spegeln","blind marys spegelhistoria"}},{q="Vem fick spegeln efter att Mary kastat bort den?",a="En Insane Ghoul som strövade i skogen bakom Marys gamla gård plockade upp den bortkastade spegeln. Den vansinniga odöda slog sig så småningom ner i det övergivna kapellet på Tranquil Gardens Cemetery.",al={"vem har spegeln","vem tappade spegeln","var finns spegeln"}},{q="Varför vill Viktori Prism'Antras ha Mary's Looking Glass?",a="Viktori bygger ett sinnrikt teleskop för att tränga igenom Duskwoods dunkel och studera stjärnorna. Han behöver en fin reflekterande yta för att leda ljuset genom apparaten, och Mary's bevarade spegelglas passar perfekt i hans konstruktion.",al={"varför behöver viktori en spegel","viktoris användning av spegeln","teleskopspegel"}},{q="Var finns Insane Ghoul som håller i spegeln?",a="Insane Ghoul lurar i det sydöstra hörnet längst bort i Duskwood, oftast i det förstörda stenkapellet på Tranquil Gardens Cemetery.",al={"insane ghoul plats","var finns insane ghoul","ghoul på tranquil gardens"}}},fx={afb2ba8d={q="Vad är Mary's Looking Glass?",a="Mary's Looking Glass är en handspegel som en gång tillhörde Blind Mary, innan tragedin drabbade henne. Mary betraktade den som en av sina finaste personliga ägodelar, men kastade till slut bort den bakom sin lada efter en fasansfull händelse. Senare hamnade den i klorna på en vandrande odöd gast i Duskwood.",al={"vad är mary's looking glass","mary's looking glass föremål","blind mary's spegel"}}},fp="20,269,19.454.0,19.443.0,42.239.0,53.200.0,56.227.0,55.147.0"}
P.entries["item:mathystra-relic"] = {n="Mathystra Relic",s="Mathystra Relics är urgamla nattalviska artefakter som ligger utspridda bland de igenvuxna Ruins of Mathystra i norra Darkshore. De är rester från en fallen alvisk bastion och bär ännu på vilande magiska fragment som väckt intresse hos kulten Twilight's Hammer.",h="Mathystra Relics är urgamla nattalviska artefakter som ligger utspridda bland de igenvuxna Ruins of Mathystra...",kw={"darkshore","grove of the ancients","the master's glaive","mathystra","mathystra relic","onu","ruins of mathystra","twilight's hammer"},ang={["class:Druid"]="Druider samarbetar nära med uråldringar som Onu för att skydda Darkshores känsliga balans och se till att bortglömda magiska lämningar inte göder mörka åkallelser.",["race:NightElf"]="För kaldoreierna handlar det både om att skydda farlig uråldrig arkana från Twilight's Hammer och att hedra arvet från en stad som gick förlorad i Sundringen."},sec={{t="Rester från en fallen bastion",b="Före den stora Sundringen var Mathystra en stolt stad och bastion för alvisk civilisation längs Kalimdors kust. I dag ligger dess omkullvälta pelare och spruckna stenar halvt begravda i snår och havsdimma, hemsökta av rastlösa andar och lurande vidunder. Uråldriga reliker från stadens storhetstid ligger utspridda bland ruinerna. Trots tiotusen år av förfall bär artefakterna ännu svaga spår av alviskt arkanskt hantverk, vilket gör dem till farliga fynd om de lämnas obevakade."},{t="Ett hot tornar upp sig",b="Kunskapens uråldriga träd Onu söker efter relikerna sedan han upptäckt att den ondskefulla kulten Twilight's Hammer försöker använda bortglömda alviska skrifter som grävts fram vid The Master's Glaive som vapen. Kultisterna vill tygla uråldrig kaldoreisk magi för att påskynda sina mörka herrars återkomst. Genom att studera dessa utspridda lämningar hoppas Onu och Darkshores väktare avslöja kultens avsikter och skydda Mathystra Relics sviktande kraft från att användas i mörka syften."}},faq={{q="Vad är Mathystra Relics?",a="De är fragment och artefakter som lämnats kvar från den uråldriga nattalviska staden Mathystra. Trots att de är tusentals år gamla bär de ännu spår av den för-Sundringska alviska civilisationens magiska hantverk.",al={"vad är mathystra relic","alviska reliker mathystra","vad är det här för reliker"}},{q="Var finns relikerna?",a="De ligger utspridda bland de krossade stenarna, omkullvälta pelarna och höga gräsen i Ruins of Mathystra, i de norra delarna av Darkshore.",al={"mathystra relic plats","var hittar man reliker","relikplatser"}},{q="Vem vill ha Mathystra Relics?",a="Kunskapens uråldring Onu, som bor i Grove of the Ancients i södra Darkshore, ber resande att samla in dem för studier.",al={"vem behöver reliker","vem ska jag lämna relikerna till","onu reliker"}},{q="Varför är Twilight's Hammer intresserade av dem?",a="Kulten har tytt uråldriga alviska texter som grävts fram i närheten vid The Master's Glaive. De vill förvränga och utnyttja de uråldriga alvernas magiska hemligheter för att hjälpa till att kalla sina skuggomslutna herrar till världen.",al={"varför vill twilight hammer ha reliker","twilight's hammer mathystra"}}},fx={bddb4f1c={q="Varifrån kommer Mathystra Relics, och vem gjorde dem?",a="De här föremålen kommer från den uråldriga nattalvstaden Mathystra och tillverkades för länge sedan, när den mäktiga bastionen strålade över norra Darkshore. De lämnades kvar när den gamla bosättningen föll i ruiner och bär fortfarande på kvarvarande fragment av alvmagi.",al={"mathystra relics ursprung","vem gjorde mathystra relics","varifrån kommer mathystra relics"}}},fp="15,130,28.460.0,15.426.1,30.195.0,29.128.0,31.132.0,48.180.0"}
P.entries["item:maury-s-clubbed-foot"] = {n="Maury's Clubbed Foot",s="Maury “Club Foot” Wilkins är skyldig Sea Wolf MacKinley en av skulderna som han tänker driva in i Booty Bay. MacKinley tror att något värdefullt finns i Maurys klumpfot.",h="Maury “Club Foot” Wilkins är skyldig Sea Wolf MacKinley en av skulderna som han tänker driva in i Booty Bay.",kw={"booty bay","club foot","klumpfot","maury","maury wilkins","ruins of aboraz","sea wolf mackinley","voodoo-skulder"},sec={{t="En skuld i djungeln",b="Bland gäldenärerna som MacKinley nämner irrar Maury “Club Foot” Wilkins omkring bland djungelruinerna med Jon-Jon the Crow och Chucky “Ten Thumbs”. Deras skulder har varit obetalda i flera månader, och MacKinley skickar dig för att hitta dem vid Ruins of Aboraz och Ruins of Jubuwal. Maurys klumpfot är en av värdesakerna han vill ha tillbaka till Booty Bay."},{t="MacKinleys pris",b="När du lämnar tillbaka de tre värdesakerna säger MacKinley att han kan få bra betalt för dem. Han talar om vad som finns inuti Maurys fot och varnar sedan för att de tre borde ha varit försiktiga med vem de spelade om pengar med."}},faq={{q="Vem är Maury “Club Foot” Wilkins?",a="Maury “Club Foot” Wilkins är en gäldenär till Sea Wolf MacKinley som irrar omkring bland djungelruinerna.",al={"vem är maury","maury club foot","maury wilkins"}},{q="Varför vill MacKinley ha Maurys fot?",a="MacKinley vill ha Maury's Clubbed Foot bland värdesakerna han samlar in från gäldenärerna.",al={"varför foten","maurys fot","vad mackinley vill ha"}},{q="Vad finns inuti Maurys fot?",a="MacKinley säger att det finns något inuti Maurys fot som han kan sälja för bra betalt.",al={"inuti foten","maurys fothemlighet","vad finns i foten"}},{q="Var kan Maury hittas?",a="Maury irrar omkring bland djungelruinerna nära Ruins of Aboraz och Ruins of Jubuwal.",al={"var är maury","maurys plats","var club foot"}},{q="Vem mer är skyldig MacKinley pengar?",a="Jon-Jon the Crow och Chucky “Ten Thumbs” är också bland MacKinleys gäldenärer.",al={"övriga gäldenärer","jon-jon och chucky","vem är skyldig sea wolf"}}},fp="20,169,20.345.0,19.207.1,37.93.0,39.88.0,30.90.1,25.81.0,24.82.0"}
P.entries["item:maury-s-key"] = {n="Maury's Key",s="Maury's Key söks av Sea Wolf MacKinley i Booty Bay. Han behöver den för att låsa upp låset på Maurys fot och få det han har rätt till.",h="Maury's Key söks av Sea Wolf MacKinley i Booty Bay.",kw={"booty bay","spel om pengar","nyckel","låst fot","maury","maurys nyckel","mosh'ogg","sea wolf mackinley"},sec={{t="En låst fot",b="MacKinley säger att Maury låste sin fot, så bytet därinne är utom räckhåll. Den döde spelaren brukade spela mot Mosh'Ogg-ogrerna vid deras hög nära Booty Bay. Efter att ha vunnit för mycket jagades Maury bort, och MacKinley misstänker att og rer na har hans nyckel."}},faq={{q="Vad är Maury's Key till för?",a="Sea Wolf MacKinley behöver Maury's Key för att låsa upp låset på Maurys fot och få bytet därinne.",al={"maurys nyckel","nyckel till maurys fot","låsa upp fot"}},{q="Vem vill ha Maury's Key?",a="Sea Wolf MacKinley i Booty Bay vill ha Maury's Key så att han kan låsa upp låset på Maurys fot.",al={"vem behöver maurys nyckel","mac kinleys nyckel","sea wolfs nyckel"}},{q="Var tappade Maury nyckeln?",a="MacKinley tror att Mosh'Ogg-ogrerna vid sin hög nordost om Booty Bay kan ha Maury's Key.",al={"var är nyckeln","mosh ogg-nyckel","maury tappade nyckeln"}},{q="Varför kan og rer na ha den?",a="Maury spelade om pengar mot Mosh'Ogg-ogrerna och jagades bort efter att ha vunnit för mycket. MacKinley misstänker att de behöll nyckeln.",al={"varför har og rer na nyckeln","maury och og rer","spelnyckel"}}},fp="11,130,13.264.0,24.94.0,22.90.0,29.95.0,28.119.0"}
P.entries["item:melenas-head"] = {n="Melenas' Head",s="Melenas' Head är den avhuggna belöningen från Lord Melenas, en satyrbefälhavare som slagit läger i Fel Rock. Trofén återlämnades som obestridligt bevis på hans död och markerar att ett kvardröjande demoniskt hot tyst har undanröjts bland Teldrassils grenar.",h="Melenas' Head är den avhuggna belöningen från Lord Melenas, en satyrbefälhavare som slagit läger i Fel Rock.",kw={"fel rock","grell","lord melenas","melenas' head","satyr","teldrassil","twisted hatred"},ang={["class:Warrior"]="Att bära en fiendehövdings avhuggna huvud är ett otvetydigt, ursprungligt bevis på att en farlig motståndare och hans grellstyrka har besegrats.",["race:NightElf"]="Satyrer är en tragisk, demonisk förvrängning av nattalvernas uråldriga släktlinje, vilket gör den tysta avrättningen av Lord Melenas både nödvändig och en kulturell skam."},sec={{t="En outtalad skam",b="För nattalverna som vaktar Shadowglen och Teldrassils omgivande områden är blotta förekomsten av satyrer på deras nya världsträd en bitter skam. Lord Melenas valde att slå sig ned i Fel Rocks förvridna grottor, strax norr om alvernas bosättningar, där han samlade aggressiva grellkrigare under sitt baner. Eftersom kaldorei värdesätter diskretion när de hanterar fördärv så nära sina kärnmarker, är denna blodiga trofé ett privat bevis på att hans planer har kvästs innan hans inflytande kunde spridas."}},faq={{q="Vem var Lord Melenas?",a="Lord Melenas var en satyrbefälhavare som lurade i grottan Fel Rock på Teldrassil. Han samlade en krigarskara av grell under sitt befäl för att smida planer mot kaldoreiernas närliggande utposter.",al={"lord melenas bakgrund","vem är melenas","melenas berättelse"}},{q="Varför måste hans död förbli hemlig?",a="Satyrernas närvaro så nära Teldrassils heliga grenar ses som en djup skam av kaldoreimyndigheterna. Satyrerna är uråldriga, förbannade nattalver som förvridits av demoniskt fördärv. Att ta hand om honom snabbt och i tysthet förebygger panik och minimerar skammen.",al={"varför hemlighetsmakeri","twisted hatred hemlighet","varför i tysthet"}},{q="Varifrån togs Melenas' Head?",a="Huvudet hämtas djupt inne i Fel Rock, en fördärvad grotta strax norr om Dolanaar i centrala Teldrassil.",al={"var hittar man melenas","fel rock plats","melenas plats"}}},fx={["05bed8f4"]={q="Vad är Melenas' Head?",a="Det är det avhuggna huvudet från Lord Melenas, en vidrig satyr som hade sitt näste i Fel Rock, strax norr om Dolanaar. Melenas samlade aggressiva grell kring sig och smidde mörka planer obehagligt nära nattalvernas heliga hem. Hans avhuggna huvud är ett obestridligt bevis på att hans fördärvliga inflytande har utplånats.",al={"vad är melenas' head","melenas' head föremål","vems huvud är det här"}},b9c077d0={q="Varför vill Tallonkai ha Melenas' Head?",a="Tallonkai Swiftroot vill ha huvudet som ett obestridligt bevis på Lord Melenas död. Att en satyr finns så nära Shadowglen ses som en farlig förödmjukelse för nattalverna. Om du levererar hans huvud kan den usle ränksmidaren tystas snabbt och obemärkt, innan hans planer sprider sig vidare över Teldrassil.",al={"varför ta med melenas' head","vem vill ha melenas' head","varför vill tallonkai ha huvudet"}}},fp="13,141,20.426.0,21.159.0,32.242.0,35.110.0"}
P.entries["item:menethil-statuette"] = {n="Menethil Statuette",s="Menethil Statuette är en sällsynt, silverglänsande figur som föreställer den avlidne kung Terenas Menethil II som en ung paladin med en upplyft stridshammare. Den gick förlorad i ett skeppsbrott utanför Wetlands kust och är ett ytterst sällsynt minne av Lordaerons fallne härskare.",h="Menethil Statuette är en sällsynt, silverglänsande figur som föreställer den avlidne kung Terenas Menethil II...",kw={"blind princess","bluegill","bolvar fordragon","cathedral of light","grayson shadowbreaker","menethil statuette","terenas menethil","wetlands"},ang={["class:Paladin"]="Statuetten visar den avlidne kung Terenas som en ung krigare av Ljuset med en upplyft hammare, ett djupt gripande porträtt för heliga riddare som sörjer det fallna kungariket.",["faction:Alliance"]="Terenas var den enande ledaren som grundade Grand Alliance, vilket gör varje bevarat minne av honom till en inspirerande skatt i en splittrad värld."},sec={{t="En sällsynt relik från Lordaeron",b="Statuetten föreställer kung Terenas Menethil II i hans ungdom, med långt hår och som paladin när han lyfter en hammare mot himlen. Terenas var känd för sin ödmjukhet under sin regeringstid och ogillade personliga monument, så få statyer eller avbildningar beställdes någonsin till hans ära. Efter att Scourge krossat kungariket Lordaeron förstördes nästan alla sådana reliker, vilket gör den här bevarade avbildningen oerhört värdefull för Alliance."},{t="Förlorad i träskmarkerna",b="Statuetten var last ombord på handelsfartyget Blind Princess, på väg till Alliances hamn Menethil. När aggressiva Bluegill murlocs anföll skeppet utanför den sumpiga kusten spreds lasten, och statuetten fastnade i en delvis begravd tunna på stranden. Med lokala hot som Dragonmaw-orcherna i närheten skickade försvararna snabbt den återfunna avbildningen söderut till Stormwind City, där Highlord Bolvar Fordragon anförtrodde den åt Cathedral of Light."}},faq={{q="Vem föreställer statuetten?",a="Den föreställer kung Terenas Menethil II, den tidigare härskaren över Lordaeron och grundaren av den ursprungliga Alliance. Han visas inte som en åldrad monark, utan som ung paladin med en stridshammare i handen.",al={"vem finns på statyn","vad föreställer statuetten","vad är menethil statuette"}},{q="Hur gick statuetten förlorad?",a="Den transporterades över Great Sea ombord på handelsfartyget Blind Princess. När Bluegill murlocs angrep skeppet i Wetlands spolades lasten i land och begravdes i leran.",al={"hur gick den förlorad","vem förlorade statuetten","staty skeppsbrott wetlands"}},{q="Varför är avbildningar av kung Terenas så sällsynta?",a="Kung Terenas var en anspråkslös härskare som aktivt ogillade monument som förhärligade honom själv, så mycket få statyer av honom skulpterades. Nästan alla återstående porträtt och figurer i norr förstördes när Scourge härjade Lordaeron.",al={"varför finns det få statyer av terenas","minnesmärken över terenas"}},{q="Vart tar statuetten vägen?",a="Efter att ha återfunnits i Wetlands förs den till Highlord Bolvar Fordragon i Stormwind Keep. Bolvar känner att Ljuset har samlats i reliken och ger Lord Grayson Shadowbreaker i uppdrag att skydda den i Cathedral of Light.",al={"var ska jag lämna statuetten","vem tar hand om statuetten","statuetten cathedral of light"}}},fx={["00c7d589"]={q="Vad är Menethil Statuette?",a="Menethil Statuette är en silverglänsande statyett som föreställer kung Terenas Menethil II i sin ungdom, som en långhårig paladin med hammaren lyft. Förutom att vara en utsökt avbild av Lordaerons fallne monark tycks reliken ha själva Ljusets kraft samlad inom sig, vilket gör den till både ett dyrbart historiskt minnesmärke och ett välsignat heligt föremål.",al={"vad är menethil statuette","menethil-statyett","vad är statyetten"}},["0d8a0354"]={q="Varför är Menethil Statuette så eftertraktad?",a="Kung Terenas avskydde personliga monument och minnesmärken, så det finns ytterst få avbildningar av honom kvar. Nästan alla förstördes när Lordaeron föll för Scourge. Dess sällsynthet, heliga Ljus och starka känslomässiga band till Alliances grundare gör den till ett oersättligt arvegods. Fiender som de lokala Dragonmaw-orcherna skulle gärna skända eller plundra den om den lämnades obevakad.",al={"varför vill folk ha menethil statuette","varför är statyetten värdefull","vem vill ha statyetten"}}},fp="18,131,25.338.0,16.448.0,30.162.0,27.169.0,43.200.0,32.222.1"}
P.entries["item:meridith-s-love-letter"] = {n="Meridith's Love Letter",s="Meridith's Love Letter bär ett meddelande från Meridith till Narain Soothfancy i Tanaris. Det är en stilla vädjan som föddes efter att en flygmaskin störtade.",h="Meridith's Love Letter bär ett meddelande från Meridith till Narain Soothfancy i Tanaris.",kw={"fisk","flygmaskin","gnom","kärleksbrev","meridith","narain soothfancy","tanaris"},ang={["race:Gnome"]="Som gnom förmedlar du Meridiths känslor till Narain Soothfancy, en annan gnom som blir överraskad av hennes budskap."},sec={{t="Ett meddelande till Narain",b="Efter att ha räddat Narain Soothfancy från en störtad flygmaskin ber Meridith dig att överlämna hennes brev till honom. Hon har blivit förälskad i gnomen och hoppas att han ska förstå hennes känslor."},{t="Narains svar",b="Narain ryggar tillbaka när han får veta vem som skickat brevet. Meridith är en fisk, protesterar han, och själv är han en gnom. Han ser ingen möjlighet för deras kärlek att fungera."}},faq={{q="Vem skrev Meridith's Love Letter?",a="Meridith skrev brevet till Narain Soothfancy, gnomen hon räddade från en störtad flygmaskin.",al={"vem skrev brevet","meridiths brev","brevets avsändare"}},{q="Vem är brevet till?",a="Brevet är till Narain Soothfancy, en gnom i Tanaris.",al={"vem får brevet","brev till narain","till vem ska det lämnas"}},{q="Varför skickar Meridith ett brev?",a="Meridith tror att hon har blivit förälskad i Narain och vill att han ska veta hur hon känner.",al={"varför ett brev","vem älskar meridith","meridiths meddelande"}},{q="Hur träffade Meridith Narain?",a="Meridith räddade Narain ur vraket av en störtad flygmaskin.",al={"var träffades de","narains vrak","störtad flygmaskin"}},{q="Vad säger Narain om brevet?",a="Narain säger att Meridith är en fisk och att han är en gnom, så han tror att de aldrig kan vara tillsammans.",al={"narains reaktion","älskar narain meridith","fisk och gnom"}}},fp="22,158,20.184.0,14.140.1,33.101.0,22.56.0,32.89.0,29.70.0,38.94.1"}
P.entries["item:merrin-s-letter"] = {n="Merrin's Letter",s="Merrin's Letter är ett brådskande meddelande från arkeologen Merrin Rockweaver, som sitter fast vid utgrävningen i Wetlands. Hon berättar hur deras expedition gick under i en attack av vilda rovödlor och försäkrar sina nära och kära om att hon fortfarande lever.",h="Merrin's Letter är ett brådskande meddelande från arkeologen Merrin Rockweaver, som sitter fast vid...",kw={"explorers' league","merrin rockweaver","merrin's letter","mottled raptors","tarrel rockweaver","wetlands","whelgar's excavation"},ang={["faction:Alliance"]="När du lämnar över lappen får Alliansens vaktposter längs vägen genom Wetlands avgörande information och en bitterljuv tröst.",["race:Dwarf"]="Brevet visar vilket högt personligt pris Explorers' League betalar för att gräva fram forntidens historia i Khaz Modans farliga vildmarker."},sec={{t="Ett meddelande från ruinerna",b="När dvärgexpeditionen grävde fram enorma förhistoriska fossil och reliker vid Whelgar's Excavation Site i Wetlands störde den ett bo med ursinniga Mottled Raptors. Bestarna vällde in i schakten, dödade flera arbetare och skar av de överlevande forskarna från flyktvägen. Mitt i kaoset skrev Merrin Rockweaver den här lappen till sin make Tarrel vid Menethil Harbor. Utgrävningen ligger i ruiner, men hon, Prospector Whelgar och Ormer Ironbraid överlevde bakom barrikader i ett skydd."}},faq={{q="Vem skrev Merrin's Letter?",a="Brevet skrevs av Merrin Rockweaver, en upptäcktsresande som deltog i den arkeologiska expeditionen vid utgrävningen öster om Menethil Harbor i Wetlands.",al={"författaren till merrins brev","vem är merrin"}},{q="Vem är brevet adresserat till?",a="Det är adresserat till Tarrel Rockweaver, som väntar oroligt på nyheter på bron vid Menethil Harbor.",al={"mottagaren av merrins brev","vem får merrins brev"}},{q="Vad hände med utgrävningsteamet?",a="När det arkeologiska teamet grävde fram massiva förstenade ben överfölls det av en flock Mottled Raptors, som körde bort det. Många dvärgarbetare dödades, och bara en liten handfull överlevande barrikaderade sig i ett provisoriskt läger.",al={"vad hände med utgrävningen","varför misslyckades expeditionen"}},{q="Vem hjälpte Merrin att överleva attacken?",a="Ormer Ironbraid kämpade tappert för att försvara Merrin och huvudprospektören. Tack vare honom kunde de dra sig tillbaka och söka skydd medan rovödlorna tog över resten av utgrävningen.",al={"vem räddade merrin","ormer ironbraid"}}},fx={bce088a8={q="Vad är Merrin's Letter?",a="Merrin's Letter är ett brådskande meddelande från Merrin Rockweaver, som överlevde det katastrofala rovfågelangreppet på utgrävningsplatsen i Wetlands. Brevet är adresserat till hennes älskade Tarrel Rockweaver och berättar om katastrofen som drabbade deras grävlag. Det bekräftar att hon, Prospector Whelgar och Ormer Ironbraid nätt och jämnt kom undan med livet i behåll.",al={"merrin's letter","vad är merrin's letter","merrins meddelande"}},ded8799c={q="Varför vill Tarrel ha Merrin's Letter?",a="Tarrel Rockweaver skickade dig ut i de farliga träskmarkerna för att få veta hur det gått för hans älskade och det försvunna utgrävningsteamet. Merrin's Letter bekräftar att hon fortfarande lever och berättar om den tragiska förlusten av utgrävningsplatsen och deras desperata tillflykt undan rovfåglarna i området.",al={"varför leverera merrin's letter","varför vill tarrel ha brevet","vad är merrin's letter till för"}}},fp="15,152,25.471.0,26.142.0,31.112.0,37.190.0,37.183.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="Middle of Gelkak's Key",s="Middle of Gelkak's Key är en trasig metallbit som tillhörde den skeppsbrutna gnompiraten Gelkak Gyromast. När hans fartyg sjönk utanför Darkshores kust rycktes den här mittdelen bort av asätare bland de lokala Greymist-murlocer.",h="Middle of Gelkak's Key är en trasig metallbit som tillhörde den skeppsbrutna gnompiraten Gelkak Gyromast.",kw={"urverk","darkshore","gelkak gyromast","greymist","middle of gelkak's key","murloc","skeppsvrak"},ang={["profession:Engineering"]="Nyckeln är en specialbyggd mekanisk komponent som är gjord för att dra upp och driva en urverksstyrman. Den visar prov på klassisk gnomisk uppfinningsrikedom, även i pirathänder."},sec={{t="En bit i dyn",b="När vildsinta threshadons drog Gelkak Gyromasts skepp under vågorna spolades gnompiraten i land, medan hans dyrbaraste ägodelar krossades mot de klippiga grunden. Bland vrakdelarna fanns en specialgjord vevnyckel avsedd för hans mekaniska förste styrman. Nyckeln bröts i tre tydliga delar under katastrofen och spreds längs stranden. Topp- och bottendelarna bars bort av kustens bestar, medan mittdelen fångade blicken hos Greymist-murlocer som strök omkring i Darkshores bränningar. De lade snabbt beslag på den blänkande metalldelen i sina läger och bland sina vrakfynd."}},faq={{q="Vad används Middle of Gelkak's Key till?",a="Det är en av tre delar som den skeppsbrutna piraten Gelkak Gyromast behöver vid Darkshores kust. När den sätts ihop med topp- och bottendelarna används den kompletta nyckeln för att återaktivera hans mekaniska förste styrman.",al={"vad gör gelkaks nyckel","vad används middle of gelkaks key till","varför behöver jag den här nyckeln"}},{q="Vart tog den här nyckeldelen vägen?",a="Greymist-stammen tog mittdelen som byte. Den kan bändas loss från Greymist-raiders, oracles, netters, tidehunters och andra stammedlemmar som strövar längs Darkshores stränder och bland skeppsvraken.",al={"vem har mittendelen av nyckeln","var hittar jag middle of gelkak key","vem släpper mittendelen av nyckeln"}},{q="Varför gick nyckeln sönder från början?",a="Aggressiva threshadons sänkte Gelkaks skepp strax utanför kusten. När gnomens kropp spolades i land bland de splittrade vrakdelarna slog nyckeln mot kustklipporna och bröts i tre bitar innan lokala asätare tog dem.",al={"hur gick nyckeln sönder","varför är den i bitar"}}},fx={d3714d13={q="Vad är Middle of Gelkak's Key?",a="Det är mittdelen av en nyckel i tre delar som tillhör den skeppsbrutne gnompiraten Gelkak Gyromast. När hans skepp sjönk utanför Darkshores kust och han spolades i land, splittrades nyckeln mot de vassa klipporna. Den här biten blev kvar bland vrakdelarna.",al={"middle of gelkak's key","gelkak's key mittdel","vad är det här för nyckelbit"}},["55a592b4"]={q="Varifrån kommer Middle of Gelkak's Key, och vem gjorde den?",a="Nyckeln tillhör Gelkak Gyromast och fanns ombord på hans skepp innan threshadoner förstörde det utanför Darkshores kust. Gelkak ägde nyckeln för att kunna styra sin mekaniska styrman, men det är okänt vem som tillverkade den.",al={"vem gjorde gelkak's key","mittdelens ursprung","varifrån kommer nyckeln"}},["7cf04b1b"]={q="Varför vill Gelkak Gyromast ha nyckelns mittdel?",a="Gelkak Gyromast behöver den här mittdelen tillsammans med de två andra bitarna för att sätta ihop hela nyckeln igen. Utan den kompletta nyckeln kan han inte dra upp sin mekaniska styrman och aktivera den igen för att hämnas på odjuren längs kusten.",al={"varför vill gelkak ha den här nyckeln","vem vill ha gelkak's key","varför behövs nyckeln"}}},fp="22,138,22.481.0,44.163.0,32.176.0,42.190.0"}
P.entries["item:milly-s-harvest"] = {n="Milly's Harvest",s="I Northshire Vineyards ligger Millys druvor övergivna efter att Defias Brotherhood dykt upp. Lådor och hinkar med frukt riskerar att stjälas eller krossas under kloster vakternas stövlar.",h="I Northshire Vineyards ligger Millys druvor övergivna efter att Defias Brotherhood dykt upp.",kw={"defias","elwynn forest","druvor","milly osworth","milly's harvest","northshire abbey","northshire vineyards"},ang={["faction:Alliance"]="Hotet mot Northshires bönder visar hur få soldater Stormwinds garnison har kvar. Vanligt folk förlitar sig på förbipasserande äventyrare för att skydda sin försörjning.",["race:Human"]="Som människa som börjar i Northshire kan du möta Defias Brotherhoods laglöshet alldeles inpå knuten när du hämtar Millys druvor."},sec={{t="En bräcklig skörd",b="Milly Osworth plockar druvor i Northshire Vineyards, där skörden är viktig för traktens vinodlare och klostrets gemenskap. När beväpnade rövare i röda masker tränger in på fälten flyr Milly till klosterområdet. Hennes nyplockade druvor ligger kvar utspridda mellan raderna."},{t="Oavsiktliga skador",b="Stormwinds vakter bevakar dalens ingång, men för få soldater gör Northshire sårbart. Garnisonen lovar att driva bort Defias Brotherhood, medan Milly oroar sig för att en långdragen strid mellan vakter och tjuvar ska förstöra hennes skörd. Lådorna kan trampas sönder eller föras bort som proviant, och Northshire går då miste om en av sina få fredliga skördar."}},faq={{q="Vad är Milly's Harvest?",a="Milly's Harvest är druvorna som Milly Osworth plockade och packade i lådor och hinkar innan Defias-rövare tog över Northshire Vineyards.",al={"millys harvest","vad är skörden","milly osworths druvor"}},{q="Varför lämnades lådorna kvar i vingården?",a="Defias-rövare anföll vingårdarna medan Milly skördade, så hon tvingades lämna druvorna och fly till Northshire Abbey.",al={"varför övergivna","varför lämnade milly druvorna","varför lämna skörden"}},{q="Varför kunde inte vakterna i Northshire hämta skörden?",a="Northshires vakter är hårt ansatta av Defias Brotherhoods intrång och lokala hot. Milly oroar sig också för att deras stövlar ska krossa druvorna när de driver bort rövarna.",al={"varför inte vakterna","varför kan inte vakterna hämta den","stormwinds vakter i northshire"}},{q="Vilka är rövarna som hotar skörden?",a="Rövarna som hotar skörden tillhör Defias Brotherhood, ett rövarband som skapar oro i hela Elwynn Forest.",al={"vem tog vingårdarna","vem anfaller vingården","rövare i vingården"}}},fx={["1d7cbab4"]={q="Varför vill Milly få tillbaka sin skörd?",a="Milly Osworth skördade grödan själv och är beroende av den för sin försörjning, men tvingades överge den när Defias-banditerna intog vingården. Hon fruktar att klostrets vakter trampar sönder de ömtåliga druvorna när de driver bort rövarna, om inte tjuvarna hinner föra bort frukten först.",al={"varför vill milly ha tillbaka skörden","varför återta millys skörd","varför är druvorna viktiga"}}},fp="15,174,15.261.0,17.328.0,24.138.0,48.128.0,56.161.0,44.141.0"}
P.entries["item:mind-s-eye"] = {n="Mind's Eye",s="Mind’s Eye är en artefakt som innehas av Mai’Zoth, en ogremagiker i Stranglethorn Vale. Dess magi fruktas för att fördärva och stärka dem som använder den.",h="Mind’s Eye är en artefakt som innehas av Mai’Zoth, en ogremagiker i Stranglethorn Vale.",kw={"brother nimetz","kin'weelay","kurzen","mai’zoth","mind's eye","mosh’ogg","ogremagiker","stranglethorn","yenniku"},ang={["faction:Horde"]="Som medlem av Horde berör Mind’s Eye Darkspears försök att rädda Yenniku, hövdingens son."},sec={{t="Ogremagikern",b="Brother Nimetz tror att Mai’Zoth använde Mind’s Eye för att fördärva Kurzen. Ogremagikern förvarar artefakten inne i Mosh’Oggs ogrehög i östra Stranglethorn Vale. Nimetz fruktar att dess inflytande också kan fördärva andra."},{t="Ett val om ögat",b="Kin’weelay söker Mind’s Eye som det enda hoppet om att rädda Yenniku. När artefakten har återfunnits tänker Kin’weelay styra dess kraft till Darkspears behov. Brother Nimetz tänker studera artefakten och avgöra om den kan användas till gott eller måste förstöras."}},faq={{q="Vad är Mind’s Eye?",a="Mind’s Eye är en artefakt som innehas av ogremagikern Mai’Zoth. Det sägs att dess magi gör hans krafter starkare och fördärvar andra.",al={"mind’s eye","vad är mind’s eye","ögat"}},{q="Vem har Mind’s Eye?",a="Mai’Zoth, en ogremagiker, håller Mind’s Eye djupt inne i Mosh’Oggs ogrehög i Stranglethorn Vale.",al={"vem har ögat","mai’zoths öga","innehavare av mind’s eye"}},{q="Vad gjorde Mind’s Eye med Kurzen?",a="Brother Nimetz tror att Mai’Zoth använde Mind’s Eye för att fördärva Kurzen. Han fruktar att dess inflytande kan fördärva andra.",al={"kurzens fördärv","varför är kurzen ond","mind’s eye och kurzen"}},{q="Varför vill Kin’weelay ha Mind’s Eye?",a="Kin’weelay söker Mind’s Eye som det enda hoppet om att rädda Yenniku, Darkspear-hövdingens son.",al={"kin’weelay och ögat","rädda yenniku","varför ögat"}},{q="Vad ska Brother Nimetz göra med den?",a="Brother Nimetz tänker studera Mind’s Eye och avgöra om den kan användas till gott eller måste förstöras.",al={"nimetz och ögat","förstöra mind’s eye","studera ögat"}},{q="Var är Mai’Zoth?",a="Mai’Zoth håller till inne i Mosh’Oggs ogrehög i östra Stranglethorn Vale.",al={"mai’zoths plats","mosh’oggs hög","var är ogremagikern"}}},fp="10,160,13.229.0,20.267.0,25.133.0,25.109.0,39.120.0,44.100.0,36.111.0,20.81.0"}
P.entries["item:miners-gear"] = {n="Miners' Gear",s="Miners' Gear består av stadiga dvärgiska hackor, spadar och grävredskap som förvaras i Silver Stream Mine. Efter ett skadedjursangrepp gav Miners' League äventyrare i uppdrag att hämta de värdefulla redskapen innan de lokala vakterna inledde ett anfall.",h="Miners' Gear består av stadiga dvärgiska hackor, spadar och grävredskap som förvaras i Silver Stream Mine.",kw={"smutsiga tassar","kobold","loch modan","miners' gear","miners' league","mountaineer stormpike","silver stream mine"},ang={["profession:Mining"]="Varje gruvarbetare vet vad välsmitt dvärgiskt järn är värt. Att låta ljusbärande asätare komma över förstklassiga hackor och spadar betraktas som en mindre tragedi.",["race:Dwarf"]="För dvärgar är det en outhärdlig skymf när kobolder lägger sina smutsiga tassar på dvärgiskt hantverk, en förolämpning som kräver att gruvan genast rensas."},sec={{t="Miners' Leagues förråd",b="När Silver Stream Mine i norra Loch Modan fick slut på malm gjorde Miners' League om de stilla tunnlarna till ett underjordiskt förråd för gruvutrustning. Tyvärr tog kobolderna som bodde i tunnlarna snabbt över området, stal det lagrade godset och byggde bo bland lådorna. I rädsla för att den värdefulla dvärgiska utrustningen antingen skulle förstöras i ett fullskaligt anfall från Mountaineers eller gå förlorad till asätarna, förlitar sig ligan på djärva äventyrare som kan ta sig in och föra lådorna i säkerhet."}},faq={{q="Vad är Miners' Gear?",a="Miners' Gear syftar på lådor med dvärgiska grävredskap, som hackor och spadar, som tillhör Miners' League och förvaras i de torra tunnlarna i Silver Stream Mine.",al={"vad är miners' gear","föremål från miners' gear","miners' gear i loch modan"}},{q="Varför lämnades utrustningen i gruvan?",a="När Silver Stream Mine fick slut på malm gjorde Miners' League om de tomma tunnlarna till ett förråd. Utrustningen blev kvar där tills kobolder oväntat invaderade schakten.",al={"varför finns utrustningen i silver stream mine","varför lämnades utrustningen där"}},{q="Vem vill få tillbaka utrustningen?",a="Mountaineer Stormpike samordnar bärgningsarbetet för Miners' League. Han vill rädda redskapen innan hans krigarkamrater rycker in för att utrota kobolderna.",al={"vem vill ha miners' gear","vem behöver utrustningen","mountaineer stormpike och utrustningen"}},{q="Var hittar man Miners' Gear?",a="Utrustningen ligger i Miners' League Crates som är utspridda i schakten i Silver Stream Mine, i de norra kullarna i Loch Modan, öster om Algaz Station.",al={"miners' gear plats","var hittar man miners' gear","miners' league crates plats"}}},fp="12,184,30.382.0,21.149.0,34.167.0,30.152.0,32.128.0"}
P.entries["item:miners-union-card"] = {n="Miners' Union Card",s="Ett Miners' Union Card är en identitetshandling som en gång bars av arbetare i de rika malmådrorna under Moonbrook. Efter ett katastrofalt ras som förseglade en del av tunnlarna sitter dessa kort nu kvar på de rastlösa skelettliken som vandrar genom de mörka gångarna.",h="Ett Miners' Union Card är en identitetshandling som en gång bars av arbetare i de rika malmådrorna under...",kw={"ras","samla minnen","the deadmines","miners' union card","moonbrook","skelettgruvarbetare","stormwind","fackföreningskort"},ang={["faction:Alliance"]="När de här förlorade korten återfinns får familjer över hela kungariket Stormwind ett avslut. De fick aldrig veta vad som egentligen hände deras arbetande anhöriga.",["profession:Mining"]="För guldletare och dem som svingar hackor är korten en dyster påminnelse om riskerna med ras i underjordiska gångar och osäkrade gruvschakt."},sec={{t="Tragedi i djupet",b="Långt innan Defias Brotherhood tog full kontroll över Moonbrook arbetade gruvarbetare under jord under gruvgillets fana och utvann värdefull malm åt kungariket. Det tog slut i en katastrof när en kraftig tunnelkollaps krossade ett stort schakt och begravde dussintals arbetare under tonvis med sten. I stället för att finna en stilla grav reste sig de döda åter som skelettgruvarbetare, utgrävare och dynamitörer. Fackföreningskorten i deras beniga fickor är det enda beviset som finns kvar på vilka de var. Överlevande kollegor i Stormwind söker efter korten i hopp om att ge sörjande familjer ett avslut."}},faq={{q="Vad är ett Miners' Union Card?",a="Det är ett officiellt identitetskort som tillhör en medlem av gillet som en gång grävde ut gruvorna i Moonbrook. Överlevande arbetare använder korten för att bekräfta vilka som dog i katastrofen under jord.",al={"vad är fackföreningskort","gruvarbetarkort","fackföreningskort"}},{q="Var kommer korten ifrån?",a="De återfinns hos de odöda arbetarna, som skelettgruvarbetare, odöda utgrävare och odöda dynamitörer, som hemsöker de rasade gångarna i tunnlarna i Deadmines under Moonbrook.",al={"var hittar man fackföreningskort","vem släpper gruvarbetarkort","var korten droppar"}},{q="Varför är gruvarbetarna odöda?",a="Ett katastrofalt ras stängde in dem i ett djupt schakt. Det förklaras inte vad som väckte dem till odött liv; deras kvarlevor hemsöker nu de rasade gångarna under Moonbrook.",al={"varför skelettgruvarbetare","hur dog gruvarbetarna","odöda i deadmines"}},{q="Vem vill få korten tillbaka?",a="Överlevande arbetskamrater som undkom raset bor nu i Stormwind City. De samlar in korten så att de kan underrätta de stupades familjer och ge dem ro.",al={"vem tar emot fackföreningskort","uppdragsgivare samla minnen","lämna in fackföreningskort"}}},fp="18,179,19.484.0,29.152.0,31.150.0,26.147.0,31.173.0"}
P.entries["item:miniaturization-residue"] = {n="Miniaturization Residue",s="Miniaturization Residue lämnas kvar på jättar i Feralas som krympts med Zorbin Fandazzles apparat. Han studerar det för att förbättra sin krympstråle och ber om mer vid kajerna i Forgotten Coast.",h="Miniaturization Residue lämnas kvar på jättar i Feralas som krympts med Zorbin Fandazzles apparat.",kw={"ingenjörskonst","feralas","the forgotten coast","jättar","miniaturiseringsrester","steamwheedle cartel","zorbin fandazzle","zorpins ultra-shrinker"},ang={["profession:Engineering"]="Som ingenjör kanske du känner igen Zorbins intresse för rester som ett sätt att förbättra hans krympapparater."},sec={{t="Rester från jättar",b="Längs Forgotten Coast söker Zorbin Fandazzle efter rester från jättar som krympts med hans Ultra-Shrinker. Cliff Giants, Deep Striders, Land Walkers, Shore Striders och Wave Striders lämnar rester efter att apparaten har använts. Zorbin säger att resterna hjälper honom att hindra hans andra zapprar från att explodera på användarna."}},faq={{q="Vad är Miniaturization Residue?",a="Miniaturization Residue finns på jättar i Feralas efter att de har krympts med Zorbins Ultra-Shrinker.",al={"miniaturiseringsrester","vad är de här resterna","jätterester"}},{q="Vem vill ha resterna?",a="Zorbin Fandazzle vid kajerna i Forgotten Coast ber om Miniaturization Residue.",al={"vem vill ha rester","zorbin rester","vem ska jag lämna dem till"}},{q="Varför behöver Zorbin det?",a="Zorbin studerar resterna för att hjälpa till att se till att hans andra krympapparater inte exploderar på användarna.",al={"varför rester","vad används rester till","zapperforskning"}},{q="Vilka jättar har det?",a="Cliff Giants, Deep Striders, Land Walkers, Shore Striders och Wave Striders i Feralas kan lämna rester efter att ha krympts.",al={"jätterester faller från","vilka jättar","feralasjättar"}}},fp="23,179,19.310.0,32.110.0,22.88.0,24.100.0,21.124.0"}
P.entries["item:minshina-s-skull"] = {n="Minshina's Skull",s="På Echo Isles bär Minshina's Skull Minshinas bundna själ. Minshina var en Darkspear-troll och Master Gadrins bror. Zalazane fångade honom där efter att ha drivit stammen från öarna och använder skallen för att ge kraft åt mörka ritualer.",h="På Echo Isles bär Minshina's Skull Minshinas bundna själ.",kw={"kraftcirkel","darkspear","echo isles","gadrin","minshina","sen'jin village","skalle","zalazane"},ang={["faction:Horde"]="Att återta skallen blir ett tidigt slag mot Zalazanes grepp om Echo Isles, strax utanför Durotars kust.",["race:Troll"]="För Darkspear strider Zalazanes skändning av Minshina mot förfädernas traditioner. Att återta hans skalle handlar om stammens heder."},sec={{t="En fångad ande",b="Minshina tillfångatogs och dödades när Zalazane tog Echo Isles och drev bort Darkspear. Den förrädiske häxdoktorn band sitt offers själ till Minshinas avhuggna skalle i stället för att låta honom gå döden till mötes. Skallen ligger i en kraftcirkel på den sydligaste ön och håller Minshina bunden till Zalazanes magi. Plågad av drömmar där hans bror ropar på honom söker Master Gadrin modiga resenärer som kan ta sig in på de ockuperade öarna, återta skallen och bryta Zalazanes grepp om Minshinas ande."}},faq={{q="Vem var Minshina?",a="Minshina var en Darkspear-troll och bror till Master Gadrin från Sen'jin Village. Han mördades under Zalazanes förräderi på Echo Isles.",al={"minshina berättelse","vem är minshina","master gadrins bror"}},{q="Varför är Minshinas själ fångad i hans skalle?",a="Zalazane band Minshinas ande i hans avhuggna huvud med mörk magi. Skallen placerades i en kraftcirkel på huvudön, där den håller Minshinas själ bunden till Zalazanes vilja i stället för att låta den gå vidare till förfäderna.",al={"varför fånga hans själ","zalazanes skallritual","själ fångad i skalle"}},{q="Var finns skallen?",a="Skallen ligger på Echo Isles största och sydligaste ö. Den vilar på en kulle i en kraftcirkel med ljus, rituella markörer och andra dödskallar, vaktad av Zalazanes trälar.",al={"var finns minshinas skalle","kraftcirkelns plats","skallens plats på echo isles"}},{q="Vad händer när skallen lämnas till Master Gadrin?",a="När du återlämnar skallen till Master Gadrin i Sen'jin Village bryts den mörka förtrollningen. Minshinas vålnad visar sig en kort stund, bugar tacksamt och far fridfullt vidare till förfädernas rike.",al={"befria minshina","gadrins skallbelöning","vad händer med minshina"}}},fx={["5c3b75e4"]={q="Vad är Minshina's Skull?",a="Minshina's Skull är de fysiska kvarlevorna efter Minshina, en fallen Darkspear-troll och bror till Master Gadrin. I stället för att vila i frid efter döden fick Minshina sin själ bunden till sin avhuggna skalle genom mörk voodoo. Där sitter han fången och ropar efter befrielse.",al={"vad är minshina's skull","minshina skulls identitet","vad är det här för skalle"}},["1b71ee0f"]={q="Var kommer Minshina's Skull ifrån, och vem skapade den?",a="Skallen tillhörde Minshina, som tillfångatogs och dödades av den förrädiske häxdoktorn Zalazane på Echo Isles. Med hjälp av mörk magi högg Zalazane av hans huvud och band Minshinas ande direkt till benet. Han placerade skallen i en kraftcirkel tillsammans med andra kvarlevor för att ge näring åt sina mörka ritualer.",al={"varifrån kommer minshina's skull","vem skapade minshina skull","minshina skulls ursprung"}},b6c5f4d1={q="Varför vill någon ha Minshina's Skull?",a="Master Gadrin söker efter skallen för att rädda sin brors plågade ande. Minshina ropar ständigt på Gadrin i hans drömmar och kan inte finna ro medan Zalazanes magi håller honom fången. Att hämta skallen från kraftcirkeln på Echo Isles är det enda sättet att bryta bindningen och befria hans själ.",al={"varför vill man ha minshina skull","varför samla in minshina skull","vem vill ha minshina skull"}}},fp="16,242,16.507.0,17.142.0,44.206.0,27.192.0,56.206.1"}
P.entries["item:mirefin-head"] = {n="Mirefin Head"}
P.entries["item:mirror-lake-water-sample"] = {n="Mirror Lake Water Sample",s="Vid Mirror Lake i Elwynn Forest hämtas en flaska vatten åt Jennea Cannon i Stormwind. Magikerna ska undersöka om de lokala vattenströmmarna visar tecken på förändrad magisk energi.",h="Vid Mirror Lake i Elwynn Forest hämtas en flaska vatten åt Jennea Cannon i Stormwind.",kw={"magisk förorening","elwynn forest","flaska","jennea cannon","mirror lake","stormwind","vattenprov","wizard's sanctum"},ang={["class:Mage"]="Som magiker under utbildning vid Wizard's Sanctum hämtar du det här provet som en av dina första uppgifter. Du lär dig att hålla utkik efter ley-linjer i miljön och känna igen okontrollerat magiskt läckage."},sec={{t="Undersökning av vattnet i Elwynn",b="Jennea Cannon skickar lovande lärlingar för att hämta vatten från Mirror Lake. Sjön ligger strax sydväst om Stormwind Gate, och de fyller en särskilt förberedd flaska vid vattenfallets fot. Wizard's Sanctum i Stormwind oroar sig för att världens mystiska strömmar fortfarande är oroliga efter katastrofala konflikter. Magikerna ska undersöka provet för främmande magisk förorening i de vattendrag som människor i närheten använder."}},faq={{q="Vad är Mirror Lake Water Sample?",a="Det är vatten från vattenfallet vid Mirror Lake i Elwynn Forest, förvarat i Jennea's Flask. Nybörjarmagiker hämtar det för undersökning vid Wizard's Sanctum.",al={"mirror lake-prov","vattenprovföremål","jenneas vatten"}},{q="Varför vill Jennea Cannon ha vattenprovet?",a="Nyliga mystiska omvälvningar runt Azeroth har rubbat stabila magiska strömmar. Jennea Cannon oroar sig för att okontrollerad magisk energi kan förändra den naturliga miljön och förgifta det lokala dricksvattnet.",al={"varför testa mirror lake","jennea cannons syfte","magisk förorening i vatten"}},{q="Var samlas provet in?",a="Provet kommer från foten av vattenfallet som mynnar ut i Mirror Lake, sydväst om Stormwind Gate i Elwynn Forest.",al={"var hämtar man provet","mirror lakes läge","vattenfallsprov"}},{q="Vad händer om vattnet visar sig vara magiskt förorenat?",a="Jennea Cannon oroar sig för att långvarig konsumtion av vatten från Mirror Lake kan orsaka skadliga magiska effekter om leyströmmar har förorenat vattenförsörjningen.",al={"effekter av förorenat vatten","är mirror lake förgiftad"}}},fx={["935f4959"]={q="Var kommer Mirror Lake Water Sample ifrån, och vem samlade in det?",a="Provet samlas in vid foten av vattenfallet som störtar ner i Mirror Lake, strax sydväst om Stormwinds portar i Elwynn Forest. Du använder en tom flaska som magitränaren Jennea Cannon tillhandahåller och hämtar själv upp vattnet åt Stormwinds magiker, så att de kan undersöka tillståndet hos de vilda strömmarna i trakten.",al={"varifrån kommer mirror lake water sample","vem tog mirror lake water sample","mirror lake water samples ursprung"}}},fp="24,166,28.411.0,37.151.0,46.177.0,30.123.0,60.154.0"}
P.entries["item:miscellaneous-goblin-supplies"] = {n="Miscellaneous Goblin Supplies",s="Miscellaneous Goblin Supplies är regelbundna leveranser till Lieutenant Dorens läger nära ingången till Stranglethorn. De innehåller landminor som skydd mot Kurzen och hans män.",h="Miscellaneous Goblin Supplies är regelbundna leveranser till Lieutenant Dorens läger nära ingången till...",kw={"duskwood","goblinförnödenheter","kurzen","landminor","lieutenant doren","diverse goblinförnödenheter","private thorsen","stranglethorn vale"},sec={{t="En nödvändig leverans",b="Private Thorsen tar emot förnödenheterna i Lieutenant Dorens läger, nordväst om vägen från Duskwood till Stranglethorn Vale. Trollattacker har försenat den regelbundna leveransen, och Dorens anhängare behöver den. Thorsen kan vara i lägret eller patrullera söder om det. Minorna ska hjälpa till att försvara lägret mot Kurzen och hans män."}},faq={{q="Vad är goblinernas förnödenheter?",a="Det är landminor som gobliner har tillhandahållit för Lieutenant Dorens läger.",al={"goblinförnödenheter","diverse förnödenheter","vad finns i paketet"}},{q="Vem behöver förnödenheterna?",a="Private Thorsen tar emot förnödenheterna åt Lieutenant Dorens anhängare i deras läger.",al={"vem får förnödenheterna","vem vill ha dem","leverera till vem"}},{q="Var ligger Dorens läger?",a="Lägret ligger nordväst om vägen vid ingången till Stranglethorn Vale från Duskwood.",al={"dorens lägerplats","var ligger lägret","läger nära stranglethorn"}},{q="Varför behövs minorna?",a="Minorna ska hjälpa till att försvara Dorens läger mot Kurzen och hans män.",al={"varför minor","vad används minor till","försvar mot kurzen"}}},fp="29,183,17.333.0,29.74.0,25.87.0,24.88.0,25.66.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="Mist Veil's Lockbox",s="Mist Veil's Lockbox är en stadig kista som ligger i det översvämmade vraket efter nattalvfartyget Mist Veil utanför Darkshores kust. Den innehåller kaptenens loggbok och personliga tillhörigheter, som gick förlorade när fartyget överfölls och sänktes av kustmurlocer.",h="Mist Veil's Lockbox är en stadig kista som ligger i det översvämmade vraket efter nattalvfartyget Mist Veil...",kw={"auberdine","darkshore","gorbold steelhand","kista","mist veil","murloc","skeppsvrak","silver dawning"},ang={["faction:Alliance"]="Att återta kistan hedrar den fallna besättningen och hjälper det kämpande sjöfartssamhället i Auberdine.",["race:NightElf"]="Den fallna kaptenen var en aktad nattalvssjöfarare, och om loggboken säkras kan en respekterad själ få ro i vattnen utanför Darkshore."},sec={{t="Förlorad i djupet",b="Nattalvfartyget Mist Veil gick under när det seglade genom de förrädiska kustvattnen mot Auberdine. Fartyget överfölls av fientliga murlocer tillsammans med sitt systerfartyg Silver Dawning, övermannades och sänktes till havsbotten. Kaptenen omkom i angreppet och lämnade sin loggbok och sina dyrbara personliga tillhörigheter förseglade i den här kistan. Kistan ligger i det översvämmade lastrummet, en dyster trofé omgiven av just de varelser som orsakade katastrofen."},{t="Må besättningen få ro",b="För de överlevande sjömän som lyckades nå Auberdine är förlusten av fartyget och dess befälhavare fortfarande ett öppet sår. Gorbold Steelhand söker efter Mist Veil's Lockbox så att kaptenens sista tillhörigheter kan hedras och få vila. Att trotsa de översvämmade ruinerna för att bärga kistan ger de sörjande överlevande, som strandat på fastlandet, en viss tröst."}},faq={{q="Vad finns i Mist Veil's Lockbox?",a="Kistan innehåller kaptenens loggbok och personliga tillhörigheter. Kaptenen omkom när fartyget sjönk, och den överlevande besättningen i Auberdine vill få tillbaka minnessakerna för att hedra sin fallna ledare.",al={"innehållet i mist veil lockbox","vad innehåller kistan","vad finns i kistan"}},{q="Hur sjönk Mist Veil?",a="Mist Veil överfölls av kustmurlocer när fartyget färdades genom vattnen mot Auberdine. Varelserna övermannade fartyget, som tog in vatten och sjönk till havsbotten tillsammans med sitt följeskepp Silver Dawning.",al={"varför förliste fartyget","vem sänkte mist veil","vad hände med mist veil"}},{q="Var finns kistan?",a="Den finns under vatten utanför Darkshores kust, norr om Auberdine. Kistan ligger i det översvämmade skrovet efter det sjunkna Mist Veil, där det kryllar av murlocer.",al={"var finns mist veil's lockbox","mist veils plats","kistans plats"}},{q="Vem vill att kistan ska bärgas?",a="Gorbold Steelhand i Auberdine söker efter kistan på de överlevande besättningsmedlemmarnas vägnar. Han hoppas kunna ge dem ro och sluta fred med minnet av den fallna kaptenen.",al={"vem hämtar kistan","vem ger uppdraget","gorbolds kistuppdrag"}}},fx={fab3edd7={q="Vad är Mist Veil's Lockbox?",a="Det är kaptenens kista från det sjunkna fartyget Mist Veil, som ligger under vågorna utanför Darkshores kust norr om Auberdine. Kistan förvarades säkert ombord tills murlocs sänkte skeppet. Den innehåller den avlidne nattalvskaptenens loggböcker, dagböcker och personliga tillhörigheter från den ödesdigra resan.",al={"vad är mist veil's lockbox","mist veils lockbox","vad är lådan"}}},fp="19,179,18.284.0,17.291.0,35.199.0,27.152.0,27.131.0,32.131.0"}
P.entries["item:mo-grosh-crystal"] = {n="Mo'grosh Crystal",s="Mo'grosh Crystals är sällsynta mineralbildningar som bryts och samlas på hög av Mo'grosh-ogrerna i nordöstra Loch Modan. De uppskattas för sina ovanliga alkemiska egenskaper och är en viktig beståndsdel för att neutralisera Dark Irons sprängämnen.",h="Mo'grosh Crystals är sällsynta mineralbildningar som bryts och samlas på hög av Mo'grosh-ogrerna i nordöstra...",kw={"mörkt hot tornar upp sig","hinderweir","loch modan","mo'grosh crystal","mogrosh","stonewrought dam"},ang={["profession:Mining"]="Dessa obearbetade mineralprover grävs fram djupt inne på ogreterritorium och uppvisar en unik kemisk reaktivitet när de blandas med organiska ämnen.",["race:Dwarf"]="Stonewrought Dams försvar vilar på dvärgarnas uppfinningsrikedom: en ogreklans utgrävda skatt blir ett skydd mot Dark Irons förräderi."},sec={{t="En sällsynt ogrevara",b="Undangömda bland klipporna i nordöstra Loch Modan gräver Mo'grosh-ogrerna fram dessa säregna kristaller från sitt fäste. Ogrerna är råstarka och ägnar sig sällan åt fin metallbearbetning, men Mo'grosh Crystals är värdefulla skatter i klanen. Både vanliga hantlangare, mystiska schamaner och deras resliga ledare bär på dem. Kristallerna är relativt ovanliga och därför hårt bevakade i Mo'grosh Stronghold."},{t="Att hejda hotet från Dark Iron",b="När underrättelser avslöjar att Dark Iron-sabotörer smider planer mot Stonewrought Dam söker Chief Engineer Hinderweir efter en Mo'grosh Crystal, spindelgift från lurkers och krokodiltårar. Genom att blanda mineralet med dessa reaktiva ämnen kan dvärgarnas ingenjörer framställa en specialblandning som desarmerar och oskadliggör de flyktiga Dark Iron-sprängämnena innan dalen kan översvämmas."}},faq={{q="Var kommer Mo'grosh Crystals ifrån?",a="De bryts och förvaras av Mo'grosh-ogrerna i nordöstra Loch Modan. Alla i klanen som befinner sig i Mo'grosh Stronghold, däribland mystiker, bjässar, hantlangare och schamaner, kan bära på en.",al={"mogrosh crystal plats","var hittar man mogrosh crystal","vem släpper mogrosh crystal"}},{q="Vad används kristallen till?",a="Chief Engineer Hinderweir vid Stonewrought Dam behöver kristallen för att bereda en neutraliserande blandning. Tillsammans med lurkergift och krokodiltårar används den för att desarmera Dark Iron-sprängämnen som ska sabotera dammen.",al={"vad gör mogrosh crystal","användning av mogrosh crystal","varför hinderweir vill ha kristallen"}},{q="Varför bryter ogrerna dessa kristaller?",a="Mo'grosh-ogrerna bryter kristallerna i kullarna kring sitt fäste. Även bland ogrerna är de mycket sällsynta. Det finns inga uppgifter om vad ogrerna själva använder dem till.",al={"varför ogrer har kristaller","ogrekristallernas bakgrund"}}},fx={["1713c585"]={q="Vad är en Mo'grosh Crystal?",a="En Mo'grosh Crystal är en ytterst sällsynt mineral som Mo'grosh-ogrerna bryter i sitt fäste nordost om Loch Modan. Chefingenjören Hinderweir värdesätter dess ovanliga egenskaper och säger att den är en nödvändig beståndsdel i en särskild blandning. Blandningen ska oskadliggöra Dark Iron-sprängämnena som hotar Stonewrought Dam.",al={"vad är mo'grosh crystal","mo'grosh crystals bakgrund","mo'grosh crystals identitet"}}},fp="16,170,23.326.0,31.326.1,37.180.0,29.200.0,40.119.0"}
P.entries["item:modr-fragment"] = {n="Modr Fragment",s="Modr Fragment är en av fyra saknade bitar från den uråldriga Goaz Stone, en relik som grävdes fram i Wetlands. Den hittades bland reliker och lös jord vid Whelgar Excavation Site och bär på uråldriga Titan-inskrifter som är avgörande för att återskapa en bortglömd profetia.",h="Modr Fragment är en av fyra saknade bitar från den uråldriga Goaz Stone, en relik som grävdes fram i Wetlands.",kw={"ados","utgrävning","goaz stone","golm","modr fragment","neru","old gods","titan","wetlands","whelgar"},ang={["faction:Alliance"]="Resenärer från Alliance hjälper Prospector Whelgar att trotsa den översvämmade utgrävningen för att bevara ovärderlig historisk forskning åt Ironforge.",["race:Dwarf"]="För dvärgarnas Explorers' League är det viktigt att återfinna förlorade bitar som Modr Fragment för att tyda Titan-arvet och blottlägga deras folks långa historia."},sec={{t="En bit av Goaz Stone",b="Innan skoningslösa rovfåglar drev bort Explorers' League från deras utgrävning i Wetlands upptäckte Prospector Whelgar Goaz Stone, en enorm tavla med uråldriga Titan-inskrifter. Den översatta texten bröts plötsligt av på fyra ställen, vilket dolde varningar om en gudomlig plan och en profetia om undergång. Modr Fragment är en av de fyra förlorade bitarna, som lämnades bland uråldriga reliker och omrörd jord när utgrävarna tvingades fly för sina liv."},{t="Hemligheter under jorden",b="När Modr Fragment sätts samman med fragmenten Ados, Golm och Neru kan Prospector Whelgar äntligen återskapa hela inskriften. Den översatta texten avslöjar häpnadsväckande kunskap från världens gryning och nämner särskilt ”Old Gods... Chained Beneath the Land”. Det som började som en enkel arkeologisk utgrävning i träskmarkerna har i stället blottlagt spåren av en uråldrig kamp som rasat under jorden."}},faq={{q="Vad är Modr Fragment?",a="Det är en bit inskriven sten som brutits loss från Goaz Stone, en uråldrig Titan-relik som upptäcktes vid Whelgar Excavation Site i Wetlands.",al={"modr fragment","vad är modr","modr-relik"}},{q="Vem letar efter fragmentet?",a="Prospector Whelgar, arkeolog hos Explorers' League som är stationerad vid kanten av den rovfågelhärjade utgrävningen, söker efter det för att komplettera tavlans saknade text.",al={"vem vill ha modr fragment","whelgars fragmentuppdrag"}},{q="Vad händer när alla fyra fragmenten har samlats in?",a="När Modr Fragment återförenas med fragmenten Ados, Golm och Neru kan Prospector Whelgar återställa Goaz Stone. När han läser hela Titan-inskriften upptäcker han illavarslande omnämnanden av ”Old Gods... Chained Beneath the Land”.",al={"goaz stone färdigställd","avslutningen på att gräva fram det förflutna","vad står det på goaz stone"}},{q="Var finns fragmentet?",a="Det ligger utspritt vid Whelgar Excavation Site öster om Menethil Harbor i Wetlands, gömt i krukor bland uråldriga reliker eller i fläckar med lös jord som vaktas av aggressiva rovfåglar.",al={"modr fragments plats","var hittar man modr"}}},fx={c1df2f2b={q="Var kommer Modr Fragment ifrån, och vem skapade det?",a="Modr Fragment är en bit av Goaz Stone, en forntida relik som grävdes fram vid utgrävningsplatsen öster om Menethil Harbor i Wetlands. Stenen är täckt av titanernas skrift och är en artefakt från titanerna, som formade världen i urtiden. De lämnade efter sig mystiska nedteckningar om sin gudomliga plan och profetior om undergång.",al={"modr fragments ursprung","vem skapade modr fragment","varifrån kommer modr fragment"}}},fp="13,167,25.455.0,25.315.1,26.164.0,33.181.0,50.181.1,28.194.0"}
P.entries["item:moldy-tome"] = {n="Moldy Tome",s="Moldy Tome är en vattenskadad, bärgad rest som innehåller hälften av den ursprungliga Tome of the Cabal. Den försvann i ett skeppsbrott utanför Hillsbrad Foothills kust och innehåller mörka, esoteriska ritualer som eftertraktas av häxmästare som vill bemästra demoniska åkallelser.",h="Moldy Tome är en vattenskadad, bärgad rest som innehåller hälften av den ursprungliga Tome of the Cabal.",kw={"azurelode","felhunter","hillsbrad","moldy tome","southshore","tattered manuscript","tome of the cabal","häxmästare"},ang={["class:Warlock"]="Att återta denna genomblöta grimoar är ett viktigt övergångsprov för häxmästare som vill sammanfoga ritualerna som krävs för att kuva en felhunter."},sec={{t="Förlorad till vågorna",b="Tome of the Cabal var en enastående och oersättlig avhandling om mörka konster, som en gång förvarades i Lordaerons kungarike. Någon gång under dess dunkla historia vandaliserades och delades grimoaren hänsynslöst i två delar. Den del som nu kallas Moldy Tome transporterades söderut med skepp mot Menethil Harbor och Ironforge. Fartyget nådde aldrig fram, utan dukade under i de förrädiska vattnen väster om Southshore. Den överlevande halvan spolades i land söder om Azurelode Mine, förstörd av fukt och bränningar bland de asätande murlocerna som stryker längs Hillsbrads kust."},{t="Att återta det mörka verket",b="Trots sitt mögelangripna och ruttnande pergament bevarar Moldy Tome mäktig demonisk kunskap. Utövare av de mörka konsterna, vägledda av mentorer som Krom Stoutarm i Ironforge eller Jorah Annison i Undercity, trotsar kustlägren för att återta den. När den åter förenas med sin motsvarighet, Tattered Manuscript, som hittats i Thousand Needles dammiga grottor, innehåller det återställda verket de exakta besvärjelser som krävs för att åkalla och binda en felhunter."}},faq={{q="Vad är Moldy Tome?",a="Den är hälften av den sällsynta Tome of the Cabal, en ockult grimoar med ritualer för demonisk åkallan. Den är vattendränkt och förmultnad och utgör den del av originaltexten som gick förlorad i skeppsbrottet.",al={"möglig bok","vad är det här för föremål","moldy tome-lore"}},{q="Vart hamnade Moldy Tome?",a="Den spolades upp på stranden i Hillsbrad Foothills, väster om Southshore och söder om Azurelode Mine. Den hamnade i händerna på lokala kustmurlocer, som gömmer den i sitt läger.",al={"moldy tome-plats","var finns moldy tome","var hittar man moldy tome"}},{q="Varför fanns boken ombord på ett skepp?",a="Den här delen förvarades ursprungligen i Lordaeron och skickades med ett fartyg till Menethil Harbor för att nå lärda i Ironforge. Skeppet förliste utanför Hillsbrads kust och fullbordade aldrig sin resa.",al={"varför förlorades den till havs","skeppsbruten grimoar","grimoarens transport"}},{q="Vad behövs för att komplettera Tome of the Cabal?",a="Moldy Tome måste återförenas med Tattered Manuscript, bokens andra sönderrivna halva, som hamnade långt borta i Splithoof Hold i Thousand Needles.",al={"grimoarens andra halva","saknade sidor","tome of the cabal-delar"}}},fx={f96f31c9={q="Var kommer Moldy Tome ifrån?",a="Moldy Tome var ursprungligen en del av ett unikt verk kallat Tome of the Cabal, som en gång förvarades i Lordaerons stora salar. För länge sedan vandaliserades den unika handskriften, och en stor del av pergamentet revs bort från bindningen. Den bevarade delen skulle fraktas söderut från Hillsbrad över havet till Menethil Harbor och Ironforge, men fartyget som bar den förliste vid stranden väster om Southshore. De fuktiga sidorna lämnades att ruttna i det grunda vattnet.",al={"moldy tomes ursprung","vem skapade moldy tome","var förvarades moldy tome","moldy tomes historia"}},["53a1a6b9"]={q="Varför vill någon ha Moldy Tome?",a="Lärda och utövare av mörk magi söker efter den eftersom endast ett exemplar av Tome of the Cabal någonsin skrevs. Dess magiska texter innehåller sällsynt och välbevarad kunskap om häxmästare, däribland hemligheter som krävs för att bemästra frammaningen och bindningen av felhunters. Lärda som Krom Stoutarm i Ironforge och Jorah Annison i Undercity åtrår till och med en kort glimt av den förbjudna texten. Därför är det viktigt att återfinna denna vattendränkta rest och återförena hela verket.",al={"varför hitta moldy tome","vem vill ha moldy tome","varför är moldy tome viktig","varför vill häxmästare ha moldy tome"}}},fp="10,171,17.420.0,24.412.1,23.159.0,32.145.0,27.166.0,49.169.0"}
P.entries["item:monstrous-crawler-leg"] = {n="Monstrous Crawler Leg",s="Ett Monstrous Crawler Leg kommer från de enorma Monstrous Crawlers längs kusten i Swamp of Sorrows. Dar söker tio åt kunder i Orgrimmar, som uppskattar köttet.",h="Ett Monstrous Crawler Leg kommer från de enorma Monstrous Crawlers längs kusten i Swamp of Sorrows.",kw={"crawlerkött","dar","monstrous crawler","monstrous crawler leg","orgrimmar","swamp of sorrows"},sec={{t="Kustens läckerheter",b="Dar i Swamp of Sorrows vill ha tio Monstrous Crawler Legs åt kunder i Orgrimmar. Varelserna ilar längs de östra stränderna och under havsytan. Köttet uppskattas för sin saftiga smak, och Dar tänker skicka det norrut."}},faq={{q="Var kommer Monstrous Crawler Legs ifrån?",a="Monstrous Crawler Legs kommer från Monstrous Crawlers längs stränderna och under havsytan vid kusten i Swamp of Sorrows.",al={"källa till crawler legs","var hittar man monstrous legs"}},{q="Vem vill ha de här benen?",a="Dar i Swamp of Sorrows vill ha tio Monstrous Crawler Legs att skicka till kunder i Orgrimmar.",al={"vem vill ha crawler legs","dar legs"}},{q="Varför vill Dar ha dem?",a="Dars kunder uppskattar den saftiga smaken av crawlerkött, särskilt kött från Monstrous Crawlers.",al={"varför crawler legs","vad används benen till"}},{q="Var ligger kusten?",a="Kusten ligger öster om Dar i Swamp of Sorrows. Monstrous Crawlers ilar längs stränderna och under havsytan.",al={"kustens riktning i swamp","crawlerstrand"}}},fp="21,148,12.239.0,42.120.0,21.95.0,23.103.0,19.116.0"}
P.entries["item:moonpetal-lily"] = {n="Moonpetal Lily",s="Moonpetal Lilies är stora, lysande växter som hör hemma på Teldrassil och trivs kring sötvattensdammar. Deras kraftigt läkande egenskaper är välkända, och kronbladen är uppskattade som viktiga ingredienser i naturläkemedel och läkande brygder.",h="Moonpetal Lilies är stora, lysande växter som hör hemma på Teldrassil och trivs kring sötvattensdammar.",kw={"aldrassil","motgift","dirania silvershine","iverron","moonpetal","moonpetal lily","shadowglen","teldrassil"},ang={["profession:Herbalism"]="Moonpetal Lilies plockas för hand när läget är akut och visar tydligt vilken rik läkande potential Teldrassils växter har.",["race:NightElf"]="För unga kaldorei som tränar i Shadowglen är det en viktig tidig lärdom att förstå hur inhemska växter som Moonpetal Lily kan läka och hjälpa dem leva i harmoni med naturen."},sec={{t="Växter vid dammarna",b="Moonpetal Lilies växer bara längs de fuktiga stränderna vid sötvattensdammar och småsjöar, särskilt på den nordvästra sidan av Aldrassil i Shadowglen. Liksom mycket av växtlivet som frodas ovanpå det nyväxta världsträdet tar de upp Teldrassils unika väsen från de skyddade skogsdungarna. Deras breda kronblad är milda och strålande. De syns lätt där de växer tätt intill den stilla vattenkanten, där fukten får dem att trivas."},{t="Naturliga motgifter",b="Nattalvernas läkare och örtutövare värdesätter Moonpetal Lily för dess enastående läkande egenskaper. Tillsammans med andra skogsväxter, som Hyacinth Mushrooms, verkar liljan starkt lindrande och stabiliserande. Därför är den en viktig ingrediens i motgifter mot dödliga gifter, särskilt det potenta giftet från Webwood-spindlarna som lurar i Shadowthread Cave."}},faq={{q="Var växer Moonpetal Lilies?",a="De växer längs stränderna vid de två sötvattensdammarna på nordvästra sidan av Aldrassil i Shadowglen på Teldrassil.",al={"var hittar man moonpetal lilies","moonpetal lily plats","platser med liljor"}},{q="Vad används Moonpetal Lilies till?",a="Liljorna har tydliga läkande och stärkande egenskaper. I Shadowglen använder Dirania Silvershine dem tillsammans med Hyacinth Mushrooms och Webwood Ichor för att brygga ett kraftigt motgift mot spindelgift.",al={"moonpetal lily användning","vad gör moonpetal lily"}},{q="Vem behöver ett motgift gjort av liljorna?",a="En nattalv vid namn Iverron, som föll offer för ett giftigt bett från Webwood-spindlar nära Shadowthread Cave, behöver ett motgift bryggt av Moonpetal Lilies för att överleva.",al={"vem behöver motgiftet","iverron förgiftning"}},{q="Kan Moonpetal Lilies plockas utanför Teldrassil?",a="De hör nära samman med Teldrassils avskilda dammar och är kända i de skyddade trädgrenarna i Shadowglen.",al={"växer liljor någon annanstans","moonpetal lily andra områden"}}},fx={["1aae6896"]={q="Vad är en Moonpetal Lily?",a="Moonpetal Lily är en stor vattenblomma som hör hemma i Teldrassils lugna vatten. Den är känd för sina kraftfulla naturliga läkande egenskaper och trivs i fuktig jord vid kanten av skuggiga skogstjärnar och dammar, som de nära Aldrassil i Shadowglen.",al={"vad är moonpetal lily","information om moonpetal lily","om moonpetal lily"}}},fp="14,156,18.314.0,17.289.0,31.114.0,35.186.0,45.132.0,55.110.0"}
P.entries["item:moonstalker-fang"] = {n="Moonstalker Fang",s="Moonstalker Fangs är vassa hörntänder från de rovdjur som strövar omkring i Darkshores dimmiga skogar. Resenärer samlar in dem när de hjälper Wizbang Cranktoggle att underhålla sina automatiska provtagningsapparater.",h="Moonstalker Fangs är vassa hörntänder från de rovdjur som strövar omkring i Darkshores dimmiga skogar.",kw={"buzzbox 323","darkshore","moonstalker","moonstalker fang","shadowclaw","wizbang cranktoggle"},ang={["class:Hunter"]="När du fäller moonstalkers måste du hålla sinnena skärpta mot bakhåll från rovdjur som naturligt smälter in i strandens mörka trädkronor.",["race:Gnome"]="Wizbang Cranktoggles excentriska fjärrkommunikationsapparater visar prov på klassisk gnomteknik, även om hans sluddriga tal och märkliga val av prover väcker uppmärksamhet."},sec={{t="En malande mekanism",b="Moonstalkers är smygande sabeltandade katter som hemsöker Darkshores skogsbryn och smyger på byten mellan de skuggiga tallarna. Deras långa huggtänder är formidabla jaktvapen som kan skära genom kött och ben. För den excentriske gnomuppfinnaren Wizbang Cranktoggle har tänderna däremot ett helt annat mekaniskt syfte. Norr om Auberdine, nära bron, står hans automatiska apparat Buzzbox 323. Den är särskilt kalibrerad för att mala ner dessa tåliga huggtänder till damm som en del av hans oberäkneliga ekologiska undersökningar."}},faq={{q="Var hittar man Moonstalker Fangs?",a="De tas från de olika moonstalkers som hör hemma i Darkshore, däribland moonstalker runts, vuxna, sires, matriarchs och den svårfångade prowlern Shadowclaw.",al={"var hittar man moonstalker fangs","vilka fiender släpper moonstalker fangs","källa till huggtänder"}},{q="Vem vill ha Moonstalker Fangs?",a="Gnomingenjören Wizbang Cranktoggle behöver sex sådana huggtänder till Buzzbox 323, en automatisk övervakningsapparat norr om Auberdine, nära flodbron.",al={"vem behöver huggtänder","vilket uppdrag använder huggtänder","lämna in till buzzbox 323"}},{q="Vad händer med huggtänderna inuti apparaten?",a="När de läggs i Buzzbox 323 aktiveras de inre kugghjulen och mal genast ner de hårda huggtänderna till fint damm, vilket för Wizbangs egendomliga fältexperiment framåt.",al={"vad gör buzzbox 323","varför mala huggtänder"}}},fx={fbcb9ad4={q="Vad är en Moonstalker Fang?",a="En Moonstalker Fang är en vass rovtand från de rovgiriga moonstalkers som strövar genom Darkshores dimmiga skogar. De här nattaktiva sabelkatterna jagar skogens villebråd med sina kraftiga huggtänder. Därför är tänderna eftertraktade troféer och förvånansvärt tåligt material för märkliga lokala manicker.",al={"moonstalker fang","vad är moonstalker fangs","moonstalker-tänder"}}},fp="16,140,20.312.0,37.125.0,28.138.0,45.88.0"}
P.entries["item:moonwell-water-tube"] = {n="Moonwell Water Tube",s="En flaska fylld med helgat vatten från månbrunnen i Auberdine. Dess kraftfulla, renande naturmagi används för att testa en mystisk röd kristall som sitter inbäddad längs Darkshores östra bergsryggar.",h="En flaska fylld med helgat vatten från månbrunnen i Auberdine.",kw={"när vattnet sköljer över","auberdine","darkshore","empty water tube","felwood","moonwell water tube","röd kristall"},ang={["class:Druid"]="Druider ser månbrunnsvatten som en livsviktig kanal för naturens balans, särskilt lämpad att motverka onaturlig korruption.",["race:NightElf"]="Att använda välsignat vatten från en månbrunn för att undersöka främmande korruption speglar kaldoreiernas tillit till Elunes nåd för att avslöja dolda sanningar."},sec={{t="Ett kärl med renande vatten",b="Moonwell Water Tube innehåller vätska som dragits direkt ur den skimrande månbrunnen i Auberdine och genomsyrats av Elunes välsignade krafter. Månbrunnar fungerar som heliga källor till återställande magi och renhet för nattalvernas bosättningar. Därför är även en liten flaska anmärkningsvärt kraftfull mot korruption och okända mystiska fenomen."},{t="Undersökningen av den röda kristallen",b="Röret förbereddes särskilt för att testa en väldig, främmande röd kristall som dök upp vid Darkshores östra klippsida. Eftersom Felwoods korrumperade höjder reser sig direkt ovanför bergsväggen befarade forskarna att den karmosinröda formationen hade ett mörkt ursprung. När det välsignade vattnet sköljer över kristallens fasetter tvingar magin den ogenomskinliga stenen att bli genomskinlig en kort stund och avslöjar de vibrerande mysterier som är låsta inuti."}},faq={{q="Varifrån hämtas vattnet?",a="Vattnet hämtas direkt ur den heliga månbrunnen i nattalvernas tillflyktsort Auberdine, på Darkshores västkust.",al={"var fyller jag röret","vattenrörets källa","månbrunnsvatten i auberdine"}},{q="Varför används månbrunnsvatten på den röda kristallen?",a="Månbrunnsvatten innehåller koncentrerad naturmagi och månens magi. När det hälls över den besynnerliga röda kristallen prövas dess mystiska sammansättning, vilket utlöser en eterisk reaktion som tillfälligt gör den ogenomskinliga mineralytan genomskinlig.",al={"varför månbrunnsvatten","vattenrörets syfte","vad gör vattnet"}},{q="Varför oroar sig forskarna för kristallen?",a="Kristallen ligger direkt under de östra bergen som gränsar till Felwood. Med tanke på Felwoods djupa demoniska fördärv befarar lärda att den främmande formationen kan vara en fortsättning på den korruption som sipprar ner i Darkshore.",al={"varför testa kristallen","den röda kristallens fara","kopplingen till felwood"}}},fx={f51af5d3={q="Vad är Moonwell Water Tube?",a="Moonwell Water Tube är en enkel glasflaska fylld med välsignat vatten som hämtats direkt ur månkällan i Auberdine. Månkällor rymmer kraftfull, helig magi som vårdas av nattalvernas druider och prästinnor, så vattnet är långt ifrån vanligt källvatten. Med flaskan kan forskare ta med sig en liten, koncentrerad mängd av Elunes renande kraft ut i fält och pröva okända fenomen.",al={"vad är moonwell water tube","föremålet moonwell water tube","vad är det här för vattenflaska"}},["21e1d317"]={q="Varför behövs Moonwell Water Tube?",a="Undersökare i Auberdine behöver Moonwell Water Tube för att analysera en hotfull röd kristall som sitter inbäddad i Darkshores östra berg. Kristallen misstänks ha en mörk koppling till det fördärvade Felwood högt ovanför. Forskarna tror att om de häller månkällans rena, kraftfulla magi över kristallen reagerar den säkert med stenen och avslöjar dess inre sammansättning.",al={"varför behöver jag moonwell water tube","varför vill man ha månkällsvatten","syftet med moonwell water tube"}}},fp="19,146,28.203.0,29.339.1,30.106.0,42.174.0,52.175.0"}
P.entries["item:mossy-tumor"] = {n="Mossy Tumor",s="En mossig tumör är en rutten, giftig utväxt som skurits loss från barken och köttet på fördärvade Timberlings på Teldrassil. De finns främst kring Wellspring Lake och är synliga tecken på en oroande ondska som sprider sig genom det nyväxta världsträdet.",h="En mossig tumör är en rutten, giftig utväxt som skurits loss från barken och köttet på fördärvade Timberlings...",kw={"fördärv","darnassus","mossy tumor","rellian greenspyre","teldrassil","timberling","wellspring lake"},ang={["class:Druid"]="För druider som värnar om naturens balans är det ett plågsamt tecken på att något är allvarligt fel med Teldrassil att se väktare som Timberlings översållade med giftiga tumörer.",["race:NightElf"]="Nattalverna planterade Teldrassil för att återfå sin förlorade kontakt med naturen. Att sjuka utväxter snabbt visar sig i deras nya hem är därför ett oroande omen."},sec={{t="Ett symptom på Teldrassils sjukdom",b="Timberlings på Teldrassil skapades för att vårda och sköta det stora trädets grenar, men många har blivit fientliga och sjuka. De här mossiga tumörerna är synliga uttryck för sjukdomen inom dem. De giftiga utväxterna växer över kropparna på Mire Beasts, Tramplers och Elder Timberlings som stryker omkring vid Wellspring Lake. Rellian Greenspyre och väktarna i Darnassus har gett resande i uppdrag att skära loss tumörerna så att de kan brännas ordentligt och hindra giftet från att slå djupare rot i öns jord."}},faq={{q="Vad är en Mossy Tumor?",a="Det är en sjuk utväxt som skördas från kropparna på besmittade Timberlings. Tumörerna är fyllda av vidrigt gift och visar att Teldrassils naturandar lider av ett onaturligt fördärv.",al={"mossy tumor","vad är den här tumören","timberlingtumör"}},{q="Var hittar du Mossy Tumors?",a="De samlas in från fördärvade Timberlings, som Timberling Tramplers, Mire Beasts och Elder Timberlings, som vandrar omkring vid Wellspring Lake i norra Teldrassil.",al={"var hittar man tumörer","mossy tumor byte","var finns timberlings"}},{q="Varför vill Rellian Greenspyre ha tumörerna?",a="Rellian försöker hejda fördärvet som plågar Teldrassil. Genom att samla in tumörerna och bränna dem till aska ser han till att det koncentrerade giftet i dem inte kan sippra tillbaka ner i jorden och vattnet.",al={"rellian greenspyres tumörer","varför bränna tumörer"}},{q="Varför blir Timberlings sjuka?",a="En mörk ondska har börjat få fäste över hela Teldrassil och förvrider dess vårdare och vilda varelser. Nattalverna undersöker aktivt sjukdomens verkliga källa, men Timberlings med synliga tumörer anses inte kunna räddas.",al={"varför är timberlings sjuka","timberlingfördärv"}}},fp="11,189,33.427.0,22.149.0,31.164.0,46.184.0,42.220.0"}
P.entries["item:mountain-lion-blood"] = {n="Mountain Lion Blood",s="Mountain Lion Blood är en reagens som samlas in från Hillsbrad Foothills och Alteracs snötäckta sluttningar, där rovdjuren strövar omkring. Apothecary Lydon i Tarren Mill behöver det färska blodet för att framställa Royal Apothecary Societys fruktade Elixir of Pain.",h="Mountain Lion Blood är en reagens som samlas in från Hillsbrad Foothills och Alteracs snötäckta sluttningar...",kw={"alterac","apothecary lydon","elixir of pain","hillsbrad","mountain lion blood","royal apothecary society","tarren mill"},ang={["faction:Horde"]="Att samla in reagenser från odjur kring Tarren Mill stärker Horde:s befästa närvaro direkt mot fientliga mänskliga enklaver i Hillsbrad.",["race:Undead"]="Varje insamlad flaska hjälper Royal Apothecary Society att utveckla förödande biologiska vapen för att säkra Lordaeron åt Forsaken."},sec={{t="Reagens från kullarna",b="Höglandet och kullarna kring Hillsbrad och Alterac patrulleras av vilda, utsvultna bergslejon. Vanliga jägare söker dessa rovdjur för deras pälsar och klor, men Forsaken i Royal Apothecary Society ser värde i det som pulserar genom deras ådror. Färskt blod från bergslejon har särskilda biologiska egenskaper som Apothecary Lydon i Tarren Mill tror kan användas som grund för en potent, ny giftbrygd avsedd att vålla de levande elände."},{t="Bränsle till New Plague",b="Apothecary Lydons experiment i Tarren Mill bidrar direkt till Royal Apothecary Societys övergripande uppdrag: att fullända Forsakens New Plague. Genom att skörda blod från livskraftiga vilddjur försöker Lydon förfina en brygd som han kallar Elixir of Pain. Han undersöker hur potenta lokala organiska ämnen kan användas som vapen mot Dark Ladys fiender."}},faq={{q="Vad används Mountain Lion Blood till?",a="Apothecary Lydon i Tarren Mill behöver tio flaskor Mountain Lion Blood för att destillera en dödlig brygd som kallas Elixir of Pain. Den ingår i Royal Apothecary Societys forskning om nya sjukdomar.",al={"vad används mountain lion blood till","vem behöver lejonblod","blod till elixir of pain"}},{q="Var kan man samla in Mountain Lion Blood?",a="Det samlas in från bergslejon som jagar genom Hillsbrad Foothills och vidare upp bland de närliggande snöiga klipporna i Alterac Mountains.",al={"var hittar man mountain lion blood","mountain lion blood plats","vilka lejon lämnar blod"}},{q="Varför vill Apothecary Lydon särskilt ha blod från vildkatter?",a="Lydon tror att kroppsvätskorna från de aggressiva och tåliga bergslejonen är en idealisk biologisk grund för att skapa en särskilt plågsam giftbrygd riktad mot Hillsbrads levande invånare.",al={"varför lejonblod","varför vill lydon ha lejonblod"}},{q="Kan Mountain Lion Blood användas i alkemirecept?",a="Nej. Det är enbart en experimentell reagens som samlas in för Apothecary Lydons personliga arbete och ingår inte i vanliga hantverksrecept för alkemi.",al={"kan alkemister använda mountain lion blood","är lejonblod till alkemi"}}},fx={dcf44a54={q="Vad är Mountain Lion Blood?",a="Det är färskt blod från rovgiriga bergslejon som strövar på de karga sluttningarna i Hillsbrad Foothills och Alterac Mountains. Vanliga alkemister och hantverkare har ingen nytta av det, men dess biologiska egenskaper uppskattas av Royal Apothecary Society för deras dödliga alkemiska experiment.",al={"vad är mountain lion blood","mountain lion bloods bakgrund","vad är det här för blod"}},["7c379830"]={q="Var kommer Mountain Lion Blood ifrån, och vem framställde det?",a="Det tillverkas eller framställs inte, utan tappas direkt från vildkatterna som hör hemma i norra Lordaeron. Bergslejonen som strövar i höglandet mellan Hillsbrad och Alterac jagas och tappas på blod av agenter som arbetar åt de Fördömdas apotekare vid Tarren Mill.",al={"varifrån kommer mountain lion blood","mountain lion bloods källa","vem tappade mountain lion blood"}}},fp="19,159,20.341.0,22.323.0,37.145.0,43.138.0,59.159.0,59.128.0"}
P.entries["item:muddy-journal-pages"] = {n="Muddy Journal Pages",s="De här väderbitna, jordfläckiga sidorna hittades på platsen för ett fasansfullt mord i Duskwood för flera år sedan. Tavernkeep Smitts har bevarat dem länge utan bevis för vem som skrev dem, och de är fortfarande en viktig pusselbit i en olöst lokal utredning.",h="De här väderbitna, jordfläckiga sidorna hittades på platsen för ett fasansfullt mord i Duskwood för flera år...",kw={"darkshire","ebonlocke","haggard","legenden om stalvan","muddy journal pages","smitts","stalvan"},ang={["class:Rogue"]="Att pussla ihop bortglömda handskriftsprov och väderbitna dagboksfragment visar vilket metodiskt kriminaltekniskt arbete som krävs innan en dold mördare kan fällas.",["faction:Alliance"]="När mysteriet bakom massakern på Stormwinds adelsmän löses får ett utdraget olöst fall ett välbehövligt avslut i Duskwoods hårt prövade bosättningar."},sec={{t="Bevisen för massakern",b="Flera år innan Duskwood drabbades av dagens faror mördades ett följe av besökande adelsmän brutalt ute i vildmarken. Tavernkeep Smitts följde med utredaren Haggard till den blodiga platsen och räddade de leriga dagbokssidorna ur dyn. Då saknade staden handskriftsprov och bekräftade uppgifter som krävdes för att knyta texten direkt till någon misstänkt. Smitts behöll i tysthet sidorna på värdshuset i Darkshire och väntade på att en utredare skulle hitta tillräckligt många spridda dokument i de södra kungarikena för att jämföra handstilen med den enstöring som bodde djupt inne i skogen."}},faq={{q="Var hittades de leriga dagbokssidorna?",a="Tavernkeep Smitts och Haggard hittade dem för flera år sedan på platsen där en besökande adelsfamilj mördades i skogarna i Duskwood.",al={"var hittade smitts sidorna","de leriga sidornas ursprung","platsen där dagbokssidorna hittades"}},{q="Varför kunde inte Smitts använda sidorna när han först hittade dem?",a="Sidorna hittades på brottsplatsen, men de lokala utredarna hade inget sätt att kontrollera handstilen. Utan skrivprov att jämföra med kunde stadsvakten inte knyta sidorna till någon misstänkt.",al={"varför hölls sidorna hemliga","varför lämnade smitts inte in dem","smitts problem med bevisen"}},{q="Vem behöver se sidorna?",a="De måste lämnas direkt till Commander Althea Ebonlocke, ledaren för Night Watch i Darkshire, så att utredningens upplösning av massakern på de besökande adelsmännen kan rapporteras officiellt.",al={"vem ska jag ge de leriga sidorna till","lämna in leriga dagbokssidor","ebonlockes leriga sidor"}},{q="Vilket brott kopplas till sidorna?",a="De kopplas till massakern på ett sällskap besökande adelsmän i skogarna i Duskwood för flera år sedan, ett brott som Darkshire aldrig lyckades knyta till någon då.",al={"vilken massaker","vad gjorde stalvan","besökande adelsmän mördades"}}},fx={["7e79311d"]={q="Vad är Muddy Journal Pages?",a="Det är smutsiga, sönderrivna dagbokssidor som för flera år sedan hittades på platsen för en brutal massaker på besökande adelsmän i Duskwood. De skrevs av Stalvan Mistmantle och beskriver hans förfall. De utgör också det skriftliga bevis på hans närvaro och galenskap på mordplatsen som man länge sökt efter.",al={"vad är muddy journal pages","muddy journal pages","vad är det här för föremål"}},bcc5553e={q="Var kommer Muddy Journal Pages ifrån, och vem skrev dem?",a="De skrevs av Stalvan Mistmantle och lämnades i leran när adelsmännen mördades. Tavernkeep Smitts och Haggard hittade dem när de undersökte blodbadet, men Smitts behöll dem i flera år eftersom han saknade handskriftsprov för att kunna bekräfta vem som hade skrivit dem.",al={"vem skrev muddy journal pages","varifrån kommer muddy pages","författaren till muddy journal pages"}},f7c3dc88={q="Varför behöver Commander Ebonlocke Muddy Journal Pages?",a="Commander Althea Ebonlocke ansvarar för Darkshires försvar och behöver obestridliga bevis innan hon agerar mot hotet i skogen. Tillsammans med handskriftsbevisen som du samlat in runtom i kungariket fastslår sidorna Stalvans skuld bortom allt tvivel och manar Night Watch att äntligen ta itu med honom.",al={"varför lämna sidorna till ebonlocke","vem vill ha muddy journal pages","varför är muddy pages viktiga"}}},fp="19,249,28.594.1,41.160.0,59.209.1,29.201.1,37.160.1"}
P.entries["item:muddy-note"] = {n="Muddy Note",s="En lerig, knappt läslig anteckning bland värdesakerna i en kista. Uppgifterna om Private Thorsens patruller kan hjälpa Lieutenant Doren att avslöja en förrädare i Rebel Camp.",h="En lerig, knappt läslig anteckning bland värdesakerna i en kista.",kw={"lieutenant doren","lerig anteckning","private thorsen","rebel camp","stranglethorn vale","kista","förrädare"},sec={{t="Scribbled Note",b="Private Thorsens patrullrutter och vanor finns nedtecknade i en lerig anteckning från en kista i Stranglethorn Vale. Där står också vilka han talar med bland rebellerna. Texten är svår att läsa, men Lieutenant Doren behöver anteckningen för att hitta förrädaren."}},faq={{q="Vad står det i den leriga anteckningen?",a="Anteckningen beskriver Private Thorsens patrullrutter, hans samtal och hur han tillbringar sin tid med rebellerna. Texten är knappt läslig.",al={"vad står det i anteckningen","detaljer om den leriga anteckningen","thorsen-anteckning"}},{q="Vart ska jag ta anteckningen?",a="Ta den leriga anteckningen till Lieutenant Doren i Rebel Camp.",al={"vem vill ha anteckningen","vart ska den lämnas","doren-anteckning"}},{q="Vem skrev anteckningen?",a="Anteckningen är signerad med bokstaven M. Den anger inte skribentens namn.",al={"vem signerade den","anteckningens skribent","vem är m"}},{q="Varför är anteckningen viktig?",a="Anteckningen visar att skribenten kände till Private Thorsens rutiner och förehavanden. Lieutenant Doren behöver den som en ledtråd för att hitta förrädaren bland rebellerna.",al={"varför behöver doren den","ledtråd om förrädaren","vad ska anteckningen användas till"}}},fp="10,172,18.252.0,29.145.0,25.54.0,19.85.0,26.152.0"}
P.entries["item:mudsnout-blossom"] = {n="Mudsnout Blossom",s="Mudsnout Blossoms är starkt illaluktande, giftiga svampar som växer i Nethander Stead i Hillsbrad Foothills. Lokala gnoller vaktar dem, och Royal Apothecary Society skördar dem till Apothecary Lydons forskning om elixir.",h="Mudsnout Blossoms är starkt illaluktande, giftiga svampar som växer i Nethander Stead i Hillsbrad Foothills.",kw={"apothecary lydon","elixir of agony","hillsbrad foothills","mudsnout blossom","mudsnout-gnoller","nethander stead","tarren mill"},ang={["profession:Herbalism"]="Botaniker och örtkunniga kan tro att namnet syftar på en vanlig blomma, men Mudsnout Blossom är egentligen en flyktig, illaluktande svamp som uppskattas av toxikologer och mörka alkemister.",["race:Undead"]="Forsaken använder blomans giftiga egenskaper i stor utsträckning och skördar den för att förädla biokemiska vapen åt Royal Apothecary Society."},sec={{t="En giftig svamp",b="Trots sitt blomsterlika namn är Mudsnout Blossoms stora, illaluktande svampar som främst frodas i den förorenade jorden i Nethander Stead, söder om Tarren Mill. De växer bland lägren där de lokala Mudsnout-gnollerna bor, och gnollerna försvarar området med våldsamhet. För levande organismer fungerar svampens sporer och fruktkött som ett kraftigt gift som orsakar plågor och snabb biologisk nedbrytning."},{t="Bränsle åt Royal Apothecary Society",b="I Tarren Mill söker Apothecary Lydon efter Mudsnout Blossoms som råmaterial till sina kemiska experiment. På Lady Sylvanas Windrunners uppdrag arbetar Royal Apothecary Society outtröttligt med att framställa en ny pest som kan utrota både Scourge och levande människor. Svamparnas frätande och vävnadsnedbrytande egenskaper gör dem till en idealisk grundkomponent i Lydons brygd, det ökända Elixir of Agony."}},faq={{q="Vad är en Mudsnout Blossom?",a="Trots att den kallas en blomma är det en stor, starkt luktande giftig svamp som växer i Hillsbrad Foothills fuktiga jord.",al={"mudsnout blossom bakgrund","är mudsnout blossom en blomma","vilken sorts växt är mudsnout blossom"}},{q="Var växer Mudsnout Blossoms?",a="De växer över hela Nethander Stead, en övergiven gård söder om Tarren Mill och öster om floden som rinner förbi Southshore. Området är fullt av Mudsnout-gnoller.",al={"mudsnout blossom plats","var hittar man mudsnout blossoms","svampar i nethander stead"}},{q="Varför samlar Royal Apothecary Society in dem?",a="Apothecary Lydon i Tarren Mill behöver dem för att brygga Elixir of Agony. Forsaken forskar om gifter för att kunna skapa en ny pest som utplånar både de levande och Scourge.",al={"varför vill lydon ha mudsnout blossoms","ingredienser i elixir of agony","apothecary lydon svamp"}},{q="Vad använder Royal Apothecary Society blommorna till?",a="Apothecary Lydon samlar de illaluktande svamparna till sitt nästa elixir, som en del av Forsakens forskning om sjukdomar och gifter.",al={"mudsnout blossom experiment","mudsnout blossom användning i elixir"}}},fx={f0998bd9={q="Var kommer Mudsnout Blossoms ifrån?",a="Mudsnout Blossoms är stora, illaluktande svampar som växer på fälten vid Nethander Stead i södra Hillsbrad Foothills. De trivs bland traktens Mudsnout-gnoller, som bor där och försvarar svampfältet våldsamt. Det är oklart om gnollerna odlar de starkt doftande svamparna med flit eller bara bygger bo bland dem.",al={"mudsnout blossoms ursprung","varifrån kommer mudsnout blossoms","vem skapade mudsnout blossom"}}},fp="16,166,14.327.0,37.322.1,27.124.0,32.184.0,52.183.0,60.137.0"}
P.entries["item:mudsnout-composite"] = {n="Mudsnout Composite",s="Mudsnout Composite är en alkemisk pasta som Apothecary Lydon bereder i Tarren Mill av skördade Mudsnout Blossoms. Den är en viktig grundingrediens som förs till Undercity för Royal Apothecary Societys forskning om en ny pest.",h="Mudsnout Composite är en alkemisk pasta som Apothecary Lydon bereder i Tarren Mill av skördade Mudsnout...",kw={"apothecarium","apothecary lydon","elixir of agony","master apothecary faranell","mudsnout blossom","mudsnout composite","royal apothecary society"},ang={["profession:Herbalism"]="Mudsnout Blossoms visar att även anspråkslösa inhemska växter kan krossas och göras till vapen av en erfaren apotekare.",["race:Undead"]="Varje leverans som den här blandningen bidrar direkt till Dark Ladys uppdrag: att trygga Forsakens framtid genom att utveckla en pest som utplånar både de levande och Scourge."},sec={{t="En grund för förruttnelse",b="Den här fina blandningen tillverkas i fält av Apothecary Lydon och består direkt av Mudsnout Blossoms som samlats in i Hillsbrad Foothills. Den är giftig i sig, men moset behöver en särskild förruttnelsekolloid, tillredd av Master Apothecary Faranell själv, för att aktivera sina dödligare egenskaper. När den väl bundits bildar blandningen en viktig kemisk beståndsdel i utvecklingen av Dark Lady's Elixir of Agony."},{t="Apotekarens korrespondens",b="Transporten av blandningen från Tarren Mill till Undercitys Apothecarium speglar den decentraliserade och stegvisa naturen hos Forsaken-alkemi. Fältforskare samlar ständigt in regionala reagenser och skickar prover till huvudstadens mästare för förädling. Trots Lady Sylvanas hårda krav på snabba resultat mot både levande människor och Scourge berömmer Faranell blandningen som ett sinnrikt grundarbete för deras övergripande mål."}},faq={{q="Vad används Mudsnout Composite till?",a="Det är en mellanpasta som framställs av Mudsnout Blossoms. Den ska behandlas med en förruttnelsekolloid av Master Apothecary Faranell i Undercity, vilket bidrar till att framställa Elixir of Agony.",al={"syftet med mudsnout composite","vad gör mudsnout composite"}},{q="Vem skapade blandningen?",a="Apothecary Lydon, en Forsaken-forskare stationerad i Tarren Mill i Hillsbrad Foothills, krossade färska blommor och blandade pastan innan han skickade den norrut.",al={"vem skapade mudsnout composite","skaparen av mudsnout composite"}},{q="Varför behöver Master Apothecary Faranell den?",a="Faranell leder Royal Apothecary Societys stora arbete med att skapa en ny pest. Lydons blandning bidrar med den särskilda örtbas som behövs för att föra deras forskning om dödliga gifter framåt.",al={"varför skicka den till faranell","faranell mudsnout"}}},fx={["432a2438"]={q="Vad är Mudsnout Composite?",a="Mudsnout Composite är en förädlad blandning som Apothecary Lydon tillverkar i Tarren Mill. Ämnet framställs genom att sällsynta Mudsnout Blossoms från Hillsbrad Foothills mals ner och är en viktig alkemisk grund i Royal Apothecary Societys forskning för att skapa en förödande ny farsot åt Forsaken.",al={"mudsnout composite","vad är mudsnout composite","mudsnout mixture"}}},fp="18,193,16.326.0,25.385.1,40.176.0,26.148.0,44.174.0"}
P.entries["item:mudsnout-mixture"] = {n="Mudsnout Mixture",s="Mudsnout Mixture är en giftig alkemisk bas som blandats till av Master Apothecary Faranell i Undercity. Den skapas genom att Mudsnout Composite blandas med en alkemisk kolloid av förruttnelse och utgör grunden för Royal Apothecary Societys dödliga Elixir of Agony.",h="Mudsnout Mixture är en giftig alkemisk bas som blandats till av Master Apothecary Faranell i Undercity.",kw={"alkemist","kolloid av förruttnelse","elixir of agony","faranell","hillsbrad","lydon","mudsnout mixture","undercity"},ang={["faction:Horde"]="Hordens äventyrare som arbetar i Tarren Mill agerar kurirer och fältagenter. De för giftiga blandningar genom Lordaeron för att säkra Forsakens fotfäste i Hillsbrad.",["race:Undead"]="Blandningen visar Royal Apothecary Societys hänsynslösa uppfinningsrikedom: de förädlar enkla ingredienser från vildmarken till kemiska vapen som är skapade för att utrota de levande."},sec={{t="En kolloid av förruttnelse",b="När Apothecary Lydon i Tarren Mill vill skapa ett nytt, mycket smittsamt biologiskt vapen skickar han en basblandning av Mudsnout Blossoms, giftiga svampar från det av gnoller hållna Nethander Stead, norrut till Undercity. Master Apothecary Faranell imponeras av blandningens potential och tillsätter sin egen kolloid av förruttnelse, vilket ger den flyktiga Mudsnout Mixture. Lösningen stabiliserar svampföreningen och gör dess smittsamma egenskaper redo för vidare katalytisk förädling i kullarna."},{t="Att katalysera plågan",b="Mudsnout Mixture är potent i sig, men inaktiv utan viktiga katalysatorer som aktiverar dess smittspridande ämnen. Faranell ger kurirer i uppdrag att föra tillbaka flaskan till Tarren Mill tillsammans med en Strong Troll's Blood Elixir, giftiga fjäll från Daggerspine-nagor och ögon från Torn Fin-murlocer. När Lydon har katalyserat blandningen bildar den det dödliga Elixir of Agony, ett signaturgift avsett att sprida förödelse bland de levande fienderna till Forsaken."}},faq={{q="Vad används Mudsnout Mixture till?",a="Den fungerar som en mellanliggande kemisk bas för Elixir of Agony, ett experimentellt gift som Apothecary Lydon finslipar i Tarren Mill för att slakta Forsakens fiender.",al={"mudsnout mixture syfte","vad gör mudsnout mixture","användning av mudsnout mixture"}},{q="Vem skapar Mudsnout Mixture?",a="Master Apothecary Faranell, ledaren för Royal Apothecary Society som bor i Apothecarium i Undercity, skapar den genom att blanda en rå Mudsnout Composite med sin egen kolloid av förruttnelse.",al={"vem tillverkar mudsnout mixture","mudsnout mixture skapare"}},{q="Varför behövs gnollkomponenter?",a="Det gör de inte, trots namnet. Blandningen består av Mudsnout Blossoms, giftiga svampar som växer vid Nethander Stead bland Mudsnout-gnollerna. Apothecary Lydon blandar dem till en sammansättning innan Faranell tillsätter sin kolloid av förruttnelse.",al={"varför mudsnout","gnollers giftkunskap"}},{q="Hur aktiveras blandningen?",a="För att väcka de vilande smittspridande ämnena i blandningen behöver Apothecary Lydon en Strong Troll's Blood Elixir, samt fjäll från Daggerspine-nagor och ögon från Torn Fin-murlocer som samlats längs Hillsbrads kust.",al={"aktivera mudsnout mixture","ingredienser till elixir of agony"}}},fx={f656f7cb={q="Vad är Mudsnout Mixture?",a="Det är en experimentell alkemisk brygd som Royal Apothecary Society har tagit fram. Blandningen bygger på Mudsnout Blossoms och giftiga svampar från Nethander Stead och innehåller Master Apothecary Faranells eget förruttnelsekolloid, som fungerar som en flyktig grund för apotekarnas forskning om farsoter.",al={"vad är mudsnout mixture","mudsnout mixture","mudsnout composite"}},ac01c76e={q="Varför vill Apothecary Lydon ha Mudsnout Mixture?",a="Apothecary Lydon i Tarren Mill behöver den för att framställa Elixir of Agony, en experimentell brygd som ska sprida sjukdom och död bland Forsakens fiender. Genom att aktivera dess smittämnen med trollblod och kustreagenser tänker han föra Royal Apothecary Societys forskning om farsoter framåt.",al={"varför behövs mudsnout mixture","varför vill lydon ha mudsnout mixture","vad används mudsnout mixture till"}}},fp="16,147,18.462.0,20.418.1,38.170.0,33.127.0,37.241.0,29.181.0"}
P.entries["item:murloc-head"] = {n="Murloc Head",s="Murloc Heads är dystra troféer, avhuggna från de groddjur som stryker längs Western Strand i Hillsbrad Foothills. Lieutenant Farren Orinelle i Southshore behöver dem som fysiskt bevis på att hoten har röjts undan, så att hans överordnade, Marshal Redpath, blir nöjd.",h="Murloc Heads är dystra troféer, avhuggna från de groddjur som stryker längs Western Strand i Hillsbrad...",kw={"farren orinelle","farrens bevis","hillsbrad foothills","marshal redpath","murloc","murloc head","southshore","western strand"},ang={["faction:Alliance"]="Att röja undan hoten vid Western Strand skyddar Southshores bräckliga fiskeekonomi och säkrar kusten för en utsatt alliansbastion i Lordaeron."},sec={{t="Ett ännu mer makabert bevis",b="Southshore hotas från alla håll, men de aggressiva murlocerna som samlas längs Western Strand utgör ett omedelbart hot mot traktens fiskare och resenärer längs kusten. Alliansens äventyrare sveper ofta över stränderna för att röja undan varelserna, men Marshal Marcus Redpath kräver obestridliga bevis innan han godkänner försvarsrapporterna. För att blidka byråkratin förlitar sig Lieutenant Farren Orinelle på inhyrda krigare som släpar dit kalla, droppande murloc-huvuden – en otrevlig uppgift som Farren själv finner fullständigt motbjudande, särskilt eftersom åsynen har förstört hans aptit på Southshores lokala fisk och skaldjur."}},faq={{q="Varför vill Farren Orinelle ha murloc-huvuden?",a="Marshal Marcus Redpath nöjde sig inte med enkla rapporter om att murlocer hade röjts undan från stränderna. För att bekräfta att hotet verkligen hade minskat krävde han fysiska bevis, vilket tvingade Lieutenant Farren att samla in avhuggna huvuden som bevis.",al={"farrens bevis","varför murloc-huvuden","vem vill ha murloc-huvuden i southshore"}},{q="Var hittar man dessa murlocer?",a="De kommer från murlocstammarna som hemsöker Western Strand, kuststräckan väster om Southshore i Hillsbrad Foothills.",al={"murloc head plats","var hittar man murloc heads i hillsbrad","murlocer vid western strand"}},{q="Varför äcklas Farren så mycket av dem?",a="Farren tycker att fiskar som går på land är onaturliga och får magen att vända sig. Åsynen av slemmiga, blodiga huvuden som droppar ner på golvet äcklar honom så mycket att han vägrar äta fisk, som är en viktig del av kosten i en hamnstad som Southshore.",al={"farrens reaktion","farren äter fisk"}},{q="Löser insamlingen av huvud Southshores murlocproblem?",a="Huvudena är bevisen som Marshal Redpath begärde. Han tar emot leveransen och uppmanar sedan Farren att rikta uppmärksamheten mot hoten vid Eastern Strand.",al={"slutar murlocer anfalla","farrens uppdragskedja"}}},fx={ab7abae9={q="Vad är ett Murloc Head?",a="Det är den nyligen avhuggna skallen från en murloc som dödats längs kusten i Hillsbrad Foothills. Den är kall, slemmig och dryper av vidriga vätskor och utgör ett obestridligt fysiskt bevis på att ett odjur fällts i försvaret av Southshore.",al={"vad är murloc head","information om murloc head","föremålet murloc head"}},["598cfa24"]={q="Var kommer Murloc Heads ifrån?",a="De huggs loss direkt från kropparna av murlocs som stryker omkring på Western Strand, strax väster om Southshore. De är inga tillverkade varor, utan makabra troféer från plundrarna vid kusten som oroar Alliansens garnison.",al={"var får man murloc heads","vem skapade murloc head","murloc heads ursprung"}}},fp="11,228,24.399.0,43.164.0,30.100.0,35.155.0,60.131.0"}
P.entries["item:musquash-root"] = {n="Musquash Root",s="Under Stonewrought Dam växer Musquash Root i Wetlands. Den sällsynta roten är svår att samla in, och en hemlig sekt under Stormwind behöver den till en brygd.",h="Under Stonewrought Dam växer Musquash Root i Wetlands.",kw={"en brygd åt en adelsman","lord wishock","musquash root","stonewrought dam","tear of tilloa","wetlands","zardeth"},ang={["class:Warlock"]="Som häxmästare under Slaughtered Lamb behöver du den här roten för att tysta nyfikna adelsmän och skydda din bräckliga fristad i staden.",["profession:Herbalism"]="Som örtmästare kan du se hur den fuktiga marken nedanför vattenfallen vid Stonewrought Dam ger näring åt ovanlig och farlig växtlighet."},sec={{t="En sällsynt ingrediens",b="Musquash Root växer i den fuktiga marken nedanför vattenfallen vid Stonewrought Dam. Dimman och det avskilda läget gör den svår att samla in. Få örtmästare söker efter den, men utövare av mörkare konster värdesätter dess kemiska och alkemiska egenskaper."},{t="Häxmästarens plan",b="Zardeth of the Black Claw söker efter Musquash Root och Tear of Tilloa under Stormwind, i Slaughtered Lamb. De sällsynta växterna ska ingå i en diskret brygd som oskadliggör Lord Wishock, en medlem av House of Nobles som har börjat undersöka stadens hemliga sekt av häxmästare."}},faq={{q="Var finns Musquash Root?",a="Musquash Root växer i Wetlands, vid foten av vattenfallen nedanför Stonewrought Dam.",al={"var finns musquash root","musquash root plats","hur hittar man musquash root"}},{q="Vad används Musquash Root till?",a="Zardeth of the Black Claw vill ha Musquash Root och Tear of Tilloa till en brygd som ska hålla Lord Wishock upptagen och stoppa hans försök att få till en utredning av Stormwinds häxmästarsekt.",al={"vad gör musquash root","musquash root syfte","varför behöver jag musquash root"}},{q="Vem vill att roten samlas in?",a="Zardeth of the Black Claw, en häxmästare i katakomberna under Slaughtered Lamb i Stormwinds Mage Quarter, ger sina agenter i uppdrag att hämta Musquash Root.",al={"vem behöver musquash root","uppdragsgivare för musquash root","vem ber om musquash root"}},{q="Vem är Lord Wishock?",a="Lord Wishock är medlem av Stormwinds House of Nobles. När han fick veta att det fanns en häxmästarsekt i staden började han uppmana rådet att inleda en formell utredning.",al={"vem är wishock","lord wishock"}}},fx={["32cf7ee1"]={q="Vad är Musquash Root?",a="Musquash Root är ett sällsynt botaniskt exemplar som växer särskilt i den fuktiga, dimmiga vattenstänken vid foten av vattenfallet under Stonewrought Dam i Wetlands. Mörka apotekare och häxmästare känner till dess starka naturliga egenskaper. Tillsammans med annan sällsynt växtlighet är den en viktig ingrediens i försåtliga brygder och gifter.",al={"vad är musquash root","musquash root i berättelsen","information om musquash root"}},d9341dd1={q="Var kommer Musquash Root ifrån, och vem har skapat den?",a="Musquash Root är en naturligt förekommande växt, inte något konstgjort. Den trivs enbart i Wetlands, där den slår rot i den våta stenen och den vattenmättade jorden vid foten av de forsande vattenfallen direkt nedanför den storslagna Stonewrought Dam.",al={"musquash roots ursprung","var växer musquash root","vem skapade musquash root"}}},fp="13,142,17.226.0,20.283.1,29.90.0,31.201.0,30.158.0,20.160.0"}
P.entries["item:mysterious-artifact-searing-gorge"] = {n="Mysterious Artifact",s="Mysterious Artifact är en relik som vaktas av Twilight's Hammer i Searing Gorge. Den ska till Altar of Suntara i Slag Pit.",h="Mysterious Artifact är en relik som vaktas av Twilight's Hammer i Searing Gorge.",kw={"altar of suntara","idolaters","mysterious artifact","searing gorge","the slag pit","twilight-artefakt","twilight's hammer"},sec={{t="En relik i bergen",b="Ovanför en grotta i de nordvästra kullarna i Searing Gorge vaktar Twilight's Hammer Idolaters Mysterious Artifact. Altar of Suntara väntar tomt i Slag Pit. Den döende arkeologen ber dig bära dit reliken och lägga den på altaret."}},faq={{q="Var finns Mysterious Artifact?",a="Twilight's Hammer Idolaters vaktar Mysterious Artifact i de nordvästra kullarna i Searing Gorge, ovanför en grotta.",al={"artefaktens plats","var finns reliken"}},{q="Vem vaktar artefakten?",a="Twilight's Hammer Idolaters vaktar Mysterious Artifact i kullarna i Searing Gorge.",al={"vem har den","twilight hammer-relik"}},{q="Vart ska den?",a="Mysterious Artifact hör hemma på Altar of Suntara i Slag Pit.",al={"altarets plats","vart ska artefakten"}},{q="Varför letar man efter artefakten?",a="Den döende arkeologen ber dig hämta reliken och placera den på Altar of Suntara.",al={"vad ska den användas till","varför hitta reliken"}}},fp="19,136,20.247.0,33.112.0,24.88.0,25.72.0,27.92.0"}
P.entries["item:mysterious-fossil"] = {n="Mysterious Fossil",s="Mysterious Fossil är ett forntida fynd som Prospector Remtravel grävde fram längs Darkshores kust. Dess märkliga egenskaper har väckt stort intresse hos dvärgarnas Explorers' League, vars forskare skickar det över havet för att avslöja dess hemligheter.",h="Mysterious Fossil är ett forntida fynd som Prospector Remtravel grävde fram längs Darkshores kust.",kw={"darkshore","explorers' league","flagongut","greywhisker","menethil harbor","mysterious fossil","remtravel"},ang={["faction:Alliance"]="Transporten av reliken visar hur viktig logistikkedjan är för att binda samman Alliansens utposter. Den kopplar fältspanare i Darkshore till forskare i Darnassus och Menethil Harbor.",["race:Dwarf"]="För dvärgarna är fossilet ännu en pusselbit i Explorers' Leagues pågående arbete med att förstå titanernas forntida arv och gräva fram bortglömda mysterier."},sec={{t="Ett märkligt fynd",b="Under fältarbete längs Darkshores vilda stränder fann Prospector Remtravel ett fossil som skilde sig från den vanliga förstenade sten som finns utspridd över Kalimdor. Remtravel ansåg att det hade enorm historisk betydelse och ordnade så att fyndet skickades till dvärgiska forskare i stället för att bli kvar i vildmarken. När det visades för Chief Archaeologist Greywhisker i Darnassus framstod reliken genast som ett enastående fynd."},{t="Band över havet",b="Chief Archaeologist Greywhisker noterade att fyndet hade en kuslig likhet med ett annat sällsynt fossil som en gång visades upp vid en sammankomst för Explorers' League i Ironforge. Det tidigare fyndet hade studerats av Archaeologist Flagongut, som misstänkte att stenen bar på en slumrande kraft som kunde väckas. För att bekräfta dess ursprung och avslöja dess möjliga hemligheter gav Greywhisker kurirer i uppdrag att föra fossilet över havet till Flagongut, som väntar på transport på Deepwater Tavern i Menethil Harbor."}},faq={{q="Var hittades Mysterious Fossil?",a="Prospector Remtravel upptäckte fossilet i Darkshore under sitt fältarbete längs Kalimdors forntida nordkust.",al={"fossilets plats","var hittades det","fossilets ursprung"}},{q="Varför vill Explorers' League ha fossilet?",a="Explorers' League ägnar sig åt att studera forntida artefakter och världens ursprung. Chief Archaeologist Greywhisker tror att fyndet har samband med forskning som Archaeologist Flagongut presenterade. Flagongut teoretiserade att sådana fossil kunde rymma en kraft som gick att väcka.",al={"varför vill dvärgarna ha det","explorers' leagues intresse","vad gör fossilet"}},{q="Vem är Archaeologist Flagongut?",a="Archaeologist Flagongut är forskare vid Explorers' League. Han är känd för att studera liknande förstenade reliker och bor för närvarande på Deepwater Tavern i Menethil Harbor i väntan på eskort till Whelgar Excavation Site i Wetlands.",al={"vem är flagongut","flagonguts plats","var finns flagongut"}},{q="Vem är Chief Archaeologist Greywhisker?",a="Chief Archaeologist Greywhisker är Explorers' Leagues högsta representant i Darnassus och övervakar dvärgarnas forskning och arkeologiska arbete i norra Kalimdor.",al={"greywhisker","vem är greywhisker","dvärgarkeolog i darnassus"}}},fx={dc519f37={q="Vad är Mysterious Fossil?",a="Mysterious Fossil är en uråldrig relik som dvärgprospektören Remtravel grävt fram i Darkshores vildmark. Till skillnad från vanliga förstenade lämningar liknar det här exemplaret påfallande mycket en märkvärdig artefakt som tidigare visats upp för Explorers' League i Ironforge. Dess säregna natur tyder på att det rymmer slumrande hemligheter eller krafter som en erfaren arkeolog kan väcka.",al={"mysterious fossil i berättelsen","vad är det här fossilet","information om mysterious fossil"}}},fp="17,134,19.267.0,21.388.1,38.104.0,48.171.0,31.232.0,39.182.0"}
P.entries["item:mysterious-relic"] = {n="Mysterious Relic",s="Mysterious Relic är en främmande apparat som hittades under en naga-utgrävning på Isle of Dread. Feathermoon Stronghold vill undersöka den för att ta reda på vad den är.",h="Mysterious Relic är en främmande apparat som hittades under en naga-utgrävning på Isle of Dread.",kw={"feathermoon stronghold","isle of dread","latronicus moonspear","lord shalzaru","mysterious relic","naga-utgrävning","relik","vestia moonspear"},sec={{t="Ett märkligt fynd",b="Scouter spårade Lord Shalzaru’s utgrävning till en grotta söder om huvudruinerna på Isle of Dread. Nagaherren fann Mysterious Relic där, och Latronicus Moonspear bad att den skulle föras till Feathermoon Stronghold för undersökning.\n\nLatronicus kunde inte utröna mycket om apparaten, så han skickade den till sin hustru Vestia, en prästinna och lärd. Hon fann att den skilde sig från ruinerna vanliga föremål och från naga-arbeten. Dess natur är fortfarande oklar medan hon studerar den."}},faq={{q="Var hittades Mysterious Relic?",a="Lord Shalzaru fann Mysterious Relic i en naga-utgrävningsgrotta söder om huvudruinerna på Isle of Dread.",al={"relikens plats","var reliken","relik på isle of dread"}},{q="Vem vill ha reliken?",a="Latronicus Moonspear bad att Mysterious Relic skulle föras till Feathermoon Stronghold för att undersökas.",al={"vem behöver reliken","latronicus relik","relik åt vem"}},{q="Vem studerar Mysterious Relic?",a="Vestia Moonspear, Latronicus hustru och en prästinna och lärd, studerar Mysterious Relic.",al={"vestia moonspear","vem undersöker reliken","relikens lärda"}},{q="Vad är Mysterious Relic?",a="Vestia säger att Mysterious Relic skiljer sig från föremålen i Ruins of Solarsal och inte är av naga-ursprung. Hon behöver tid för att studera den.",al={"vad är reliken","märklig apparat","relikens betydelse"}},{q="Tillverkade naga reliken?",a="Vestia säger att Mysterious Relic inte är av naga-ursprung, men dess skapare är fortfarande okänd.",al={"naga-relik","är den tillverkad av naga","vem tillverkade reliken"}}},fp="16,158,14.461.0,37.116.0,20.115.0,33.96.0,29.134.0,28.89.0"}
P.entries["item:nak-s-skull"] = {n="Nak's Skull",s="I södra Barrens leder Nak Razormane-krigarskaror mot Horden. Hans skalle bevisar att han besegrats och ger Mangletooth möjlighet att hämnas på sina tidigare fränder som förrådde honom.",h="I södra Barrens leder Nak Razormane-krigarskaror mot Horden.",kw={"barrens","svek inifrån","camp taurajo","kuz","lok orcbane","mangletooth","nak","nak's skull","quilboar","razormane"},ang={["faction:Horde"]="Som medlem av Horden kan du lätta trycket på försörjningslederna mellan Camp Taurajo och The Crossroads genom att ta huvuden från Razormane-krigsherrar som Nak."},sec={{t="En hämndens symbol",b="Nak, Kuz och Lok Orcbane leder räder från Razorfen Kraul genom Barrens. Deras krigarskaror angriper Hordens bosättningar och vägar, medan försvararna vid The Crossroads inte vet att de tre befälhavarna planerar anfall som går längre än vanliga stamstrider. Vid Camp Taurajo har den tillfångatagne Razormane Mangletooth lämnats att dö i en bur av sitt eget folk. Nu söker han hämnd på sina tidigare bröder. Mangletooth kräver bevis för att Nak och hans följeslagare är döda: deras avhuggna skallar, levererade av äventyrare från Horden. Med beviset tänker han slå sönder de södra plundrargrupperna."}},faq={{q="Vem var Nak?",a="Nak är en befälhavare bland Razormane quilboar som leder räder tillsammans med Kuz och Lok Orcbane. De tre kom från Razorfen Kraul och angriper Hordens resenärer och bosättningar i södra Barrens.",al={"vem är nak","nak bakgrund","nak i barrens"}},{q="Vem vill ha Nak's Skull?",a="Mangletooth, en tillfångatagen Razormane quilboar vid Camp Taurajo, vill ha Nak's Skull. Hans eget folk övergav honom, och han söker hämnd på ledarna som förrådde honom.",al={"vem vill ha skallen","vem ska jag ge naks skalle till","mangletooth skalle"}},{q="Varför vill Mangletooth ha skallarna från sitt eget folk?",a="Nak, Kuz och Lok Orcbane övergav Mangletooth att dö i fångenskap. Han slår tillbaka genom att hjälpa Horden att hitta dem och kräva deras avhuggna huvuden som bevis för att de är döda.",al={"varför förrådde han sin stam","mangletooths motiv","varför vill mangletooth ha skallar"}},{q="Bidrar insamlingen av Nak's Skull till att skydda The Crossroads?",a="Ja. Mangletooth säger att Nak och hans kompanjoner leder Razormane-räder mot The Crossroads och de centrala handelsvägarna. Deras nederlag försvagar stammens samordnade anfall.",al={"är crossroads säkert","stoppa quilboar-räder"}}},fx={["96a0c2b0"]={q="Var kommer Nak's Skull ifrån?",a="Skallen tas direkt från kvarlevorna efter Nak, en framstående Razormane quilboar från Razorfen Kraul. Nak och hans fränder färdades långt söderut i The Barrens för att utföra hänsynslösa räder mot Hordens läger. När du jagar upp Nak bland de sydliga snåren och besegrar honom blir hans avhuggna skalle ett obestridligt bevis på att den farliga quilboarplundraren har röjts ur vägen.",al={"nak skulls ursprung","var kommer nak skull ifrån","vem har naks skull"}}},fp="11,169,20.535.0,12.191.0,22.158.0,55.148.0,56.172.0"}
P.entries["item:nek-rosh-s-head"] = {n="Nek'rosh's Head",s="Nek'rosh's Head är det makabra beviset på hövding Nek'roshs fall, ledaren för Dragonmaw-klanen i Wetlands. Alliansäventyrare har skaffat trofén och överlämnar den till Captain Stoutfist för att bekräfta att hotet från orcherna mot Menethil Harbor har krossats.",h="Nek'rosh's Head är det makabra beviset på hövding Nek'roshs fall, ledaren för Dragonmaw-klanen i Wetlands.",kw={"captain stoutfist","hövding","dragonmaw","menethil","nek'rosh","nekrosh","wetlands"},ang={["faction:Alliance"]="Genom att överlämna denna dystra trofé till Captain Stoutfist säkrar du Menethil Harbor mot ett nära förestående angrepp och vinner stor gunst hos kungariket Ironforge.",["race:Dwarf"]="Dragonmaw har plågat Khaz Modan sedan det andra kriget. När hövdingens avhuggna huvud bärs fram får träskmarkernas försvarare äntligen den rättvisa de länge väntat på."},sec={{t="Ett avgörande slag",b="Dragonmaw-klanen utgör en ständig fara i träskmarkerna och samlar styrkor och belägringsvapen mot Alliansens hamn Menethil Harbor. När deras katapulter har bränts hänger hamnens försvar på att hövding Nek'rosh själv dödas. Att skilja huvudet från kroppen ger Captain Stoutfist och myndigheterna i Ironforge obestridliga bevis på att krigsherren har förlorat sitt grepp om Wetlands."}},faq={{q="Vem var Nek'rosh?",a="Nek'rosh var hövdingen som ledde resterna av Dragonmaw-klanen i Wetlands och organiserade attacker och krigsinsatser mot närliggande alliansområden.",al={"vem är nek'rosh","hövding nek'rosh","vem var nekrosh"}},{q="Vem vill ha Nek'rosh's Head?",a="Captain Stoutfist, befälhavaren som leder försvaret av Menethil Harbor, behöver huvudet som fysiskt bevis på att hövdingen har fallit innan han belönar mästaren å Ironforges vägnar.",al={"vem tar emot huvudet","lämna in nekroshs huvud","var ska jag lämna nek'rosh's head"}},{q="Varför skulle Nek'rosh dödas?",a="Nek'rosh ledde Dragonmaw-styrkorna som hotade Menethil Harbor. Genom att förstöra deras belägringsvapen och döda deras hövding ville Alliansen slå ett förödande slag mot klanens närvaro i regionen.",al={"varför döda nekrosh","varför besegra nek'rosh"}}},fx={e464fcda={q="Vad är Nek'rosh's Head?",a="Det är det avhuggna huvudet från hövding Nek'rosh, krigsherren som leder Dragonmaw-klanen i Wetlands. Det är ett vidrigt och obestridligt bevis på att Ironforge Mountaineers främsta fiende i trakten äntligen har dödats.",al={"vad är nekrosh head","föremålet nekrosh head","nekroshs avhuggna huvud"}},["160e4c8d"]={q="Var kommer Nek'rosh's Head ifrån, och vem har skapat det?",a="Det tas direkt från hövding Nek'rosh efter att du besegrat honom vid Dragonmaw-lägret i Wetlands. Det har inte tillverkats, utan huggits av från den fallne orchhövdingen som trofé och bekräftelse på hans död.",al={"var kommer nekrosh head ifrån","hur får man nekrosh head","nekrosh heads ursprung"}},ce210494={q="Varför vill Captain Stoutfist ha Nek'rosh's Head?",a="Captain Stoutfist behöver obestridliga bevis på att Dragonmaw-klanens ledare har fallit. Med Nek'rosh död och deras krigskatapulter förstörda vet Stoutfist att Dragonmaw får svårt att återhämta sig, så Menethil Harbor och Wetlands äntligen kan vara trygga från organiserade angrepp.",al={"varför vill stoutfist ha nekrosh head","varför vill de ha nekrosh head","nekrosh heads syfte"}}},fp="15,176,17.341.0,17.130.0,26.160.0,36.191.0"}
P.entries["item:neru-fragment"] = {n="Neru Fragment",s="Neru Fragment är en av fyra gamla, uthuggna stenbitar som tillhör Goaz Stone, en relik som upptäcktes på Whelgar's Excavation Site i Wetlands. Den grävdes fram ur den omrörda jorden och bär på en del av en gammal Titan-inskrift som beskriver Azeroths uråldriga historia.",h="Neru Fragment är en av fyra gamla, uthuggna stenbitar som tillhör Goaz Stone, en relik som upptäcktes på...",kw={"utgrävning","goaz stone","lös jord","neru fragment","prospector whelgar","uncovering the past","wetlands"},ang={["race:Dwarf"]="För Explorer's League är det viktigt att återfinna tavelfragment som Neru Fragment för att gräva fram Titan-hemligheter och lägga ihop dvärgfolkets ursprung."},sec={{t="Del av Goaz Stone",b="Goaz Stone upptäcktes av dvärgexpeditionen som leddes av Prospector Whelgar och föll sönder i fyra olika delar: Ados, Modr, Golm och Neru. När rovfåglar tog över utgrävningsplatsen avstannade arbetet, och Neru Fragment blev kvar under lös jord bland de aggressiva bestarna. Att återfinna fragmentet är avgörande för att sätta ihop tavlan igen och låta dvärglärda tyda en bortglömd skildring vars bevarade ord nämner en gudomlig plan och en ödesdiger profetia."},{t="Att läsa den återställda tavlan",b="När de fyra fragmenten har återställt Goaz Stone fortsätter Prospector Whelgar att översätta dess Titan-inskrift. De nu läsbara orden talar om Old Gods som kedjats under landet."}},faq={{q="Vad är Neru Fragment?",a="Det är en gammal stenbit som brutits loss från en större relik kallad Goaz Stone. Dvärgexpeditionen grävde fram den i Wetlands innan rovfåglar tog över utgrävningen.",al={"neru fragment historia","vad är neru fragment","neru tavelfragment"}},{q="Var hittar man fragmentet?",a="Det ligger utspritt på den rovfågelinfesterade Whelgar's Excavation Site öster om Menethil Harbor i Wetlands, ofta begravt under lös jord eller gömt bland övergivna föremål.",al={"var hittar man neru fragment","neru fragment plats","hur får man neru fragment"}},{q="Vad händer när alla fyra fragmenten har samlats in?",a="Prospector Whelgar sätter ihop Goaz Stone igen så att han kan fortsätta översätta dess Titan-inskrift och undersöka mysteriet som antyds i den bevarade texten.",al={"goaz stone komplett","vad står det på goaz stone","uncovering the past slut"}}},fx={["1f660d59"]={q="Var kommer Neru Fragment ifrån, och vem har skapat det?",a="Fragmentet kommer från den uråldriga Goaz Stone, som hittades vid Whelgar's Excavation i Wetlands. Inskriften använder titanskrift, men den återfunna uppdragstexten anger inte vem som skapade stenen.",al={"neru fragments ursprung","vem skapade neru fragment","varifrån kom neru fragment"}},b6f45f31={q="Varför vill Prospector Whelgar ha Neru Fragment?",a="Prospector Whelgar grävde upp Goaz Stone precis innan utgrävningsplatsen översvämmades av rovraptorer, men upptäckte att inskriften saknades på fyra tydliga ställen. Han behöver snabbt Neru Fragment och de tre andra delarna för att sätta ihop tavlan och fortsätta tyda hänvisningarna till en gudomlig plan och en ödesdiger profetia.",al={"varför leta efter neru fragment","varför behöver whelgar neru fragment","neru fragments syfte"}}},fp="13,161,23.442.0,27.190.1,26.162.0,28.175.0,50.193.1"}
P.entries["item:nessa-s-collection"] = {n="Nessa's Collection",s="Nessa's Collection är ett paket med fiskben och fjäll som samlats i vattnen kring Rut'theran Village. Det har förberetts för studier av fiskförsäljaren Laird i Auberdine och visar hur ovanligt stora vattenlevande djur trivs kring Teldrassils rötter.",h="Nessa's Collection är ett paket med fiskben och fjäll som samlats i vattnen kring Rut'theran Village.",kw={"auberdine","fiskben","laird","nessa shadowsong","nessa's collection","rut'theran village","teldrassil","vesprystus"},ang={["race:NightElf"]="Samlingen ger Night Elf sin första inblick i det ovanligt livskraftiga vattnet kring Teldrassil när de lämnar sitt öhem för fastlandet."},sec={{t="Världsträdets gåvor",b="Nessa Shadowsong, en fiskare som bor i Rut'theran Village vid foten av Teldrassil, samlade fiskben och fjäll för att jämföra öns marina liv med det på Kalimdors fastland. Vattnen som rinner in mot det stora trädet ger fångster av häpnadsväckande storlek, så Nessa skickar fysiska bevis över havet till Laird, en fiskhandlare vid Auberdines hamn. Paketet transporteras av byns hippogryffmästare Vesprystus och fungerar som konkret bevis på Teldrassils växande livskraft."},{t="En märklig jämförelse",b="När Laird granskar innehållet i Darkshore upptäcker han att exemplaren är mycket större än sina motsvarigheter på fastlandet. Samlingen innehåller käkben som är nästan dubbelt så stora som hos fiskar från Darkshores kust, och enskilda fjäll stora som en knuten näve. För kustens Night Elf ger paketet en tydlig bild av hur mycket vattnen kring Teldrassil skiljer sig från norra Kalimdors ödsliga stränder."}},faq={{q="Vad finns i Nessa's Collection?",a="Samlingen består av fiskben, överdimensionerade käkben och nävestora fjäll från fiskar som fångats i vattnen utanför Rut'theran Village.",al={"innehållet i nessas collection","vad finns i paketet","paket med fiskben"}},{q="Vem skickas samlingen till?",a="Den skickas till Laird, en Night Elf-fiskförsäljare i hamnbyn Auberdine vid Darkshores kust.",al={"vem får nessas collection","vem är laird","leveransmål"}},{q="Varför samlade Nessa in fiskexemplaren?",a="Nessa ville jämföra de anmärkningsvärt stora fiskarna kring Teldrassil med det marina livet längs Kalimdors fastland.",al={"varför skicka fiskben","nessas fiskjämförelse","varför teldrassil ger så stora fångster"}},{q="Hur når samlingen Auberdine?",a="En resenär bär paketet till Rut'therans hippogryffmästare Vesprystus, som ordnar färd över vattnet till Auberdine så att paketet kan levereras till Laird.",al={"hur levereras det","vesprystus leverans","hippogryffpaket"}}},fx={["6bde19ac"]={q="Vad är Nessa's Collection?",a="Nessa's Collection är ett paket med fiskben och fjäll som samlats i vattnen kring Rut'theran Village. Det är ett prov på den ovanliga marina rikedom som frodas vid foten av världsträdet Teldrassil, omsorgsfullt packat för transport över havet till fastlandet i Kalimdor.",al={"vad är nessa's collection","nessas samling","föremålet nessa's collection"}},eb414ab6={q="Var kommer Nessa's Collection ifrån, och vem har satt ihop den?",a="Samlingen sattes ihop av Nessa Shadowsong, en nattalv som bor i Rut'theran Village vid Teldrassils södra fot. Med utgångspunkt i de ovanligt stora fångster som öns lokala fiskare fått ihop valde hon ut fina exemplar att skicka över havet.",al={"vem satte ihop nessa's collection","var kommer nessa collection ifrån","nessa collections ursprung"}},d01c5154={q="Varför vill någon ha Nessa's Collection?",a="En fiskförsäljare vid namn Laird i Auberdine väntar på exemplaren så att han kan studera dem. Nessa hoppas kunna jämföra den häpnadsväckande storleken och kraften hos fångsterna från Rut'theran med fisk från fastlandet, och Laird ser fram emot att undersöka käkben som är dubbelt så stora som normalt och fjäll stora som knytnävar.",al={"varför vill laird ha nessas collection","varför leverera nessas collection","nessa collections syfte"}}},fp="18,132,24.419.0,20.355.0,34.237.0,36.98.0,42.120.0,40.145.0"}
P.entries["item:nether-gem"] = {n="Nether Gem",s="Nether Gem är en förtrollad arkan sten som anförtrotts av en gåtfull gestalt från Brightwater Lake. Den är fylld av magisk kraft och fungerar som en ledare över långa avstånd, så att dess ägare kan framkalla en arkan projektion och tala direkt med Bethor Iceshard i Undercity, även om förbindelsens fulla natur ännu inte har avslöjats.",h="Nether Gem är en förtrollad arkan sten som anförtrotts av en gåtfull gestalt från Brightwater Lake.",kw={"bethor iceshard","brightwater lake","gunther arcanus","nether gem","den förlorade lich","undercity"},ang={["class:Mage"]="För utövare av arkan magi visar Nether Gem hur mästarmagiker överbryggar stora avstånd med magisk skådning och projicerade gestalter i stället för att riskera en resa.",["race:Undead"]="Överlämnandet av stenen är en stor diplomatisk seger för Forsaken och säkrar den mäktige Gunther Arcanus som allierad mot Scourge och Scarlet Crusade."},sec={{t="En ledare för arkan samvaro",b="Nether Gem smiddes eller förtrollades av Gunther Arcanus på hans ensliga ö i Brightwater Lake och fungerar som en mystisk länk genom Tirisfal Glades. Gunther lyckades bryta sig loss från Lich King's kontroll genom ren viljestyrka och höll sig länge borta från den spirande Forsaken-nationen av misstänksamhet. Efter att ha fått tillbaka sin förlorade trollformelsbok överlämnar han stenen till ett sändebud som en fredsgest. När den förs till Bethor Iceshard högst upp i Magic Quarter i Undercity projicerar stenen Gunthers magiska gestalt rakt framför magigillesskråets ledare. Därmed öppnas vägen för den ensamme magikern att ansluta sig till Lady Sylvanas och Forsaken."}},faq={{q="Vad gör Nether Gem?",a="Nether Gem låter Gunther Arcanus kommunicera med Bethor Iceshard över långa avstånd. När Bethor kanaliserar magi in i stenen i Undercity projicerar den en eterisk gestalt av Gunther, så att de två mäktiga magikerna kan tala direkt med varandra.",al={"nether gems syfte","vad är nether gem","vad gör nether gem"}},{q="Vem skapade Nether Gem?",a="Stenen kommer från Gunther Arcanus, en mäktig nekromantiker som bor på en ö i Brightwater Lake. Han ger den till en äventyrare som ska överlämna den till hans gamle kamrat Bethor när hans förlorade trollformelsbok har återlämnats.",al={"vem skapade nether gem","varifrån kommer nether gem","gunthers ädelsten"}},{q="Varför är Nether Gem viktig för Forsaken?",a="Den är redskapet som får Gunther Arcanus att ansluta sig till Forsaken. Gunther misstrodde först andra odöda och fruktade att de fortfarande var Scourges trälar. Stenen gör det möjligt för honom att återknyta kontakten med Bethor Iceshard och svära Lady Sylvanas sin trohet.",al={"varför är nether gem viktig","gunther och forsaken","forsaken och nether gem"}}},fx={aa73e2cb={q="Vad är Nether Gem?",a="Nether Gem är en magisk fokussten som Gunther Arcanus, en mäktig odöd magiker bosatt på en ö i Brightwater Lake, har anförtrott åt dig. Den är laddad med mystisk arkansk energi och fungerar som en magisk ledare som låter Gunther kommunicera över stora avstånd och projicera sin gestalt direkt till sin gamla bundsförvant Bethor Iceshard i Undercity.",al={"vad är nether gem","nether gem i berättelsen","föremålet nether gem"}}},fp="10,160,29.595.1,28.211.0,27.175.1,50.228.1"}
P.entries["item:nether-wing"] = {n="Nether Wing",s="En Nether Wing är en demonvinge som Reclaimers Inc. söker efter i Desolace. Kreldig Ungor behöver tio till en magikers experiment, tillsammans med andra farliga reagenser.",h="En Nether Wing är en demonvinge som Reclaimers Inc.",kw={"desolace","kreldig ungor","nether maiden","nether sister","nether sorceress","nether wing","nether wings","reagenser till reclaimers inc"},sec={{t="En demonvinge",b="Nether Maidens, Nether Sorceresses och Nether Sisters i Desolace bär de vingar som Kreldig Ungor söker. Han ber om tio som en del av en samling reagenser till en magikers experiment. Arbetet kräver också Felhound Brains och flaskor med Doomwarder Blood, vilket gör insamlingen farlig."}},faq={{q="Vem vill ha Nether Wings?",a="Kreldig Ungor i Desolace söker tio Nether Wings till en magikers experiment.",al={"vem behöver nether wing","nether wings till vem"}},{q="Varifrån kommer Nether Wings?",a="Nether Wings kommer från Nether Maidens, Nether Sorceresses och Nether Sisters i Desolace.",al={"varifrån kommer nether wing","nether wing källa"}},{q="Varför behöver Kreldig Ungor dem?",a="Kreldig Ungor samlar Nether Wings som reagenser till en magikers experiment.",al={"varför nether wings","vad används vingarna till"}},{q="Vilka andra reagenser behövs?",a="Samlingen kräver också Felhound Brains och flaskor med Doomwarder Blood.",al={"andra reagenser","vad mer behöver kreldig"}}},fp="11,160,14.287.0,23.76.0,27.90.0,33.74.0,31.75.0"}
P.entries["item:nezzliok-s-head"] = {n="Nezzliok's Head"}
P.entries["item:ng-5"] = {n="NG-5",s="NG-5 är kortnamnet för Nitromirglyceronium, en ökänd instabil kemisk förening. Den har skaffats åt gnommekanikern Gaxim Rustfizzle i Stonetalon Mountains och fungerar som en nödvändig katalysator i hans explosiva ingenjörsplaner.",h="NG-5 är kortnamnet för Nitromirglyceronium, en ökänd instabil kemisk förening.",kw={"dynamit","sprängämnen","gaxim rustfizzle","gnom","ng-5","ng5","nitromirglyceronium","stonetalon"},ang={["profession:Engineering"]="Ingenjörer känner igen NG-5 som Nitromirglyceronium, en nyckfull kemisk katalysator som uppskattas av mekaniker när vanligt svartkrut inte har nog med kraft för att antända tung ammunition.",["race:Gnome"]="Att använda en instabil kemisk lösning för att spränga hela vagnar fulla med dynamit som en enkel avledning är gnomisk problemlösning när den är som mest klassisk och riskfylld."},sec={{t="Ett instabilt reagens",b="NG-5, formellt känt som Nitromirglyceronium, är en ytterst farlig kemisk lösning som bara hanteras med största försiktighet – eller med gnomisk hänförelse utan minsta eftertanke. Gaxim Rustfizzle, en agent stationerad i Stonetalon Mountains, behöver ämnet som en viktig tändningsförening. Enligt Gaxim ger NG-5 exakt den reaktion som krävs för att spränga hela vagnar lastade med dynamit och orsaka en enorm explosion som ska skapa en kaotisk avledning för hans fiender i området."}},faq={{q="Vad är NG-5?",a="NG-5 står för Nitromirglyceronium, en mycket instabil och flyktig kemisk blandning som främst används som explosivt tändningsreagens vid avancerad demolering och gnomisk ingenjörskonst.",al={"vad är ng5","vad är nitromirglyceronium","ng 5 föremål"}},{q="Vem vill ha NG-5 och varför?",a="Gnomingenjören Gaxim Rustfizzle i Stonetalon Mountains behöver kemikalien. Den är den viktiga komponent som krävs för att pålitligt tända flera vagnar fullastade med dynamit, för att skapa en spektakulär avledning.",al={"vem behöver ng-5","gaxim rustfizzle ng-5","varför skaffa ng5"}},{q="Är NG-5 farligt att hantera?",a="Extremt farligt. Leverantören varnar kurirer för att hantera föreningen med största varsamhet och skämtar om att den som inte är Gaxims allierade troligen kommer att spränga sig själv i bitar.",al={"är ng5 säkert","ng-5 sprängämne","exploderar ng5"}}},fx={["43a87313"]={q="Var kommer NG-5 ifrån, och vem har skapat det?",a="NG-5, även känt som Nitromirglyceronium, fås från en bekant till Gaxim Rustfizzle som brygger specialiserade kemiska blandningar. Det är en extremt flyktig alkemisk blandning, särskilt framtagen för explosiva reaktioner, och lämnas bara över tillsammans med stränga varningar om hur lätt den kan spränga en oförsiktig budbärare i bitar.",al={"vem skapade ng-5","var får man tag på ng-5","ng-5:s skapare"}}},fp="4,190,18.319.0,13.115.0,23.170.0,28.183.0"}
P.entries["item:nida-s-necklace"] = {n="Hilary's Necklace",s="Hilary's Necklace är ett kärt minne från barndomen som försvann under ytan på Lake Everstill i Redridge Mountains. Hennes far gav smycket till unga Hilary, men det gled ner i det grumliga vattnet medan barnen från Lakeshire fiskade vid bryggorna.",h="Hilary's Necklace är ett kärt minne från barndomen som försvann under ytan på Lake Everstill i Redridge...",kw={"effsee","skimrande lera","hilary","lake everstill","lakeshire","hilarys halsband","redridge","shawn"},ang={["faction:Alliance"]="Lakeshires försvarare är hårt ansatta av hoten runt omkring, så små vänliga handlingar – som att hjälpa ortens barn att återfå borttappade minnessaker – faller på resande äventyrare från Alliansen."},sec={{t="Förlorat i djupet",b="Unga Hilary fiskade vid Lakeshires strand med sin vän Shawn när hon råkade tappa sitt älskade halsband i Lake Everstill. Arvegodset har stort känslomässigt värde eftersom hon fick det av sin far. Rädslan för de vilda bestarna och de aggressiva murlocer som lever i djupet håller barnen på tryggt avstånd på bryggorna. Halsbandet ligger därför sjunket och begravt i sjöbottnens slam, tills en äventyrare är villig att dyka ner i det grumliga vattnet och hämta upp det."}},faq={{q="Vem tillhör halsbandet?",a="Halsbandet tillhör Hilary, en ung flicka som bor i staden Lakeshire i Redridge Mountains. Det var en särskild gåva från hennes far.",al={"vem äger halsbandet","halsbandets ägare","vems halsband är det här","hilarys halsbandsägare"}},{q="Hur hamnade halsbandet i Lake Everstill?",a="Hilary fiskade vid vattnet tillsammans med sin vän Shawn när halsbandet gled av och sjönk till sjöbottnen, där det lade sig i en hög skimrande lera.",al={"hur hamnade det i sjön","varför ligger halsbandet i vattnet","hur tappades halsbandet bort"}},{q="Varför dök inte barnen ner för att hämta det?",a="Deras föräldrar förbjuder dem strängt att simma i Lake Everstill. I det djupa vattnet finns farliga vattenlevande rovdjur och aggressiva murlocer som utgör ett dödligt hot mot ortens invånare.",al={"varför simmade hilary inte efter det","varför kan shawn inte hämta halsbandet","varför simmade inte hilary efter den"}},{q="Vem är Effsee?",a="Effsee är Hilarys katt. Den håller sig vid hennes sida i Lakeshire och välkomnar glatt halsbandet tillbaka tillsammans med sin unga ägare.",al={"vem är katten","hilarys katt","hilary katt"}}},fx={a22bd4db={q="Var fick Hilary sitt halsband?",a="Halsbandet var en gåva från Hilarys far. Det har ingen större historisk eller magisk betydelse, men är ett kärt arvegods som gavs till en ung flicka i Lakeshire.",al={"vem skapade hilarys halsband","varifrån kommer hilarys halsband","vem gav hilary halsbandet"}},["14f3017c"]={q="Varför är Hilary's Necklace eftertraktad?",a="Hilary tappade halsbandet när hon fiskade vid Lake Everstills bryggor. Eftersom hennes föräldrar förbjuder barnen att dyka i de monsterfyllda vattnen ber hennes vän Shawn förbipasserande äventyrare att våga sig ner i sjön och hämta den kära minnessaken åt henne.",al={"varför leta efter hilary's necklace","vem vill ha hilary's necklace","varför vill hilary ha tillbaka sitt halsband"}}},fp="17,165,18.314.0,33.106.0,46.102.0,47.157.0,14.120.0"}
P.entries["item:nightmare-shard"] = {n="Nightmare Shard",s="Nightmare Shard är en kristallrelik som Falla Sagewind ger till kurirer efter att ha undersökt en förvriden, lysande skärva från Wailing Caverns. Den rymmer The Emerald Dreams rena, oroliga essens och bär på en oroande vision. Den får höga druider i Darnassus och Thunder Bluff att genast varna andra och hålla saken hemlig.",h="Nightmare Shard är en kristallrelik som Falla Sagewind ger till kurirer efter att ha undersökt en förvriden...",kw={"emerald dream","falla sagewind","glowing shard","hamuul runetotem","i mardrömmar","mathrengyl bearwalker","nightmare shard","wailing caverns"},ang={["class:Druid"]="För druiderna är skärvan en isande upptäckt: deras heliga fristad, The Emerald Dream, är inte längre skyddad från fördärv. Den bekräftar oron för Naralex öde i Wailing Caverns.",["faction:Horde"]="Skärvan för med sig allvarliga nyheter direkt till Elder Rise i Thunder Bluff, där Hamuul Runetotem strävar efter att befästa taurenfolkets plats i Cenarion Circles större gemenskap."},sec={{t="En fördärvad vision",b="När Falla Sagewind undersöker den mystiska, lysande skärvan som grävts fram djupt inne i Wailing Caverns inser hon att dess kraft är mycket mörkare än väntat. I stället för att återspegla The Emerald Dreams fridfulla livskraft visar fragmentet en förvriden, onaturlig plåga, en vaken mardröm. Rädd för vad dess närvaro innebär binder hon denna fördärvade essens i Nightmare Shard och befaller kuriren att genast föra den till Cenarion Circles äldste ledare."},{t="Dämpade varsel",b="När de får skärvan reagerar både Archdruid Hamuul Runetotem på Elder Rise och Mathrengyl Bearwalker i Darnassus med bestört förskräckelse när de blickar in i dess djup. Visionen därinne rubbar deras fattning och bekräftar deras tysta misstankar om att något gått fruktansvärt fel i själva drömmen. För att inte sprida panik bland folket beslagtar druiderna snabbt skärvan och uppmanar kuriren att inte säga mer om vad de sett."}},faq={{q="Vad är Nightmare Shard?",a="Det är en skärva som Falla Sagewind anförtrott åt äventyrare. Den innehåller den fångade essensen av The Emerald Dream, hämtad från en artefakt som förts ut ur Wailing Caverns. I stället för fridfulla naturkrafter utstrålar den en mörk, fördärvande drömvision.",al={"vad är nightmare shard","nightmare shard berättelse"}},{q="Vem skapade Nightmare Shard?",a="Falla Sagewind ger skärvan till kuriren efter att ha analyserat ett lysande fragment från Wailing Caverns. När hon inser hur allvarlig dess fördärvade natur är ger hon kuriren i uppdrag att föra den direkt till höga druider för undersökning.",al={"vem skapade nightmare shard","varifrån kommer skärvan"}},{q="Varför är druidernas ledare så oroade?",a="När Hamuul Runetotem och Mathrengyl Bearwalker blickar in i skärvan ser de att The Emerald Dream aktivt förvrids av en mardröm. Eftersom denna upptäckt kan innebära fara och skapa panik tystar båda äldste genast vidare diskussion och håller saken strikt inom Cenarion Circles högre kretsar.",al={"varför är hamuul orolig","varför gömmer mathrengyl skärvan"}},{q="Vart ska skärvan föras?",a="Hordens äventyrare får i uppdrag att föra den till Archdruid Hamuul Runetotem på Elder Rise i Thunder Bluff. Alliansens resenärer bär den till Mathrengyl Bearwalker hos Cenarion Circle i Darnassus.",al={"vem ska jag lämna skärvan till","lämna in nightmare shard"}}},fp="15,214,18.327.0,12.369.1,28.241.0,32.186.0,43.240.1,42.205.0"}
P.entries["item:nightsaber-fang"] = {n="Nightsaber Fang",s="En vass tand från de rovlystna nightsabers som strövar bland Teldrassils vilda grenar. Dessa huggtänder är vanliga jakttroféer, men skogens invånare med tvivelaktiga motiv söker dem också som råa ingredienser.",h="En vass tand från de rovlystna nightsabers som strövar bland Teldrassils vilda grenar.",kw={"dolanaar","huggtand","nightsaber","ingrediens","satyr","teldrassil","zenn foulhoof"},ang={["class:Hunter"]="Att fälla en nightsaber och ta dess huggtand visar att du behärskar vildmarken på grundläggande nivå, men att ge bort djurdelar till korrumperade skogsandar förvränger jaktens anda.",["race:NightElf"]="Nightsabers är uppskattade följeslagare och symboler för gudinnan Elune. Att jaga dessa heliga rovdjur åt en förrädisk satyr är därför djupt skamligt."},sec={{t="Jakttrofé",b="Nightsabers hör till de farligaste naturliga rovdjuren i norra Kalimdor. Nattalverna vördar dem för deras smidighet, våldsamhet och djupa andliga band till Elune. Bland Teldrassils mäktiga grenar jagar dessa kattdjur i skuggorna under trädkronorna. Att fälla en ger vassa huggtänder som otvetydigt bevis på jägarens skicklighet, även om vissa skumma figurer i skogen söker dem för mindre ädla ritualer."},{t="En satyrs ingrediens",b="Utanför Dolanaar lurar Zenn Foulhoof, en svekfull satyr som ger sig på ivriga och oerfarna resenärer. Zenn påstår sig behöva ingredienser från skogen och övertalar spirande äventyrare att samla in nightsaber-huggtänder, strigid-fjädrar och spindelsilke. När de lämnar över sådana rovdjursingredienser hjälper de bedragaren direkt, och han hånar öppet den godtrogna hjälten när de levereras."}},faq={{q="Varifrån kommer Nightsaber Fangs?",a="Nightsaber Fangs tas från de rovlystna nightsabers som strövar omkring i Teldrassils vildmark, särskilt i skogen runt Dolanaar.",al={"var hittar man nightsaber fangs","vem släpper nightsaber fangs","källa till nightsaber fang"}},{q="Vem vill ha Nightsaber Fangs i Teldrassil?",a="Zenn Foulhoof, en satyr som håller till vid landsvägen strax utanför Dolanaar, ber om dem som del av ett uppdrag han ger kringvandrande äventyrare.",al={"vem behöver nightsaber fangs","lämna in nightsaber fang","vem köper nightsaber fangs"}},{q="Varför vill Zenn Foulhoof ha Nightsaber Fangs?",a="Zenn påstår att han behöver djuringredienser för att sköta sina förehavanden i skogen, men håller det exakta syftet hemligt och roas av att lura godtrogna resenärer att hjälpa honom.",al={"varför zenn vill ha huggtänder","zenn foulfoots syfte med ingredienserna","zenns motiv för uppdraget"}},{q="Vilka andra ingredienser ber Zenn om tillsammans med huggtänderna?",a="Förutom två nightsaber-huggtänder kräver Zenn två strigid-ugglors fjädrar och två stycken Webwood Spider Silk.",al={"vad mer behöver zenn","föremål till zenns uppdrag","andra ingredienser till zenn"}}},fx={bc504af2={q="Vad är en Nightsaber Fang?",a="En Nightsaber Fang är en vass hörntand från de nightsabers som stryker omkring i Teldrassils skogar. Sådana huggtänder är en naturlig del av de rovgiriga kattdjuren, men utövare av mörka konster söker efter dem som råmaterial till hemliga ritualer och otillåtna brygder.",al={"vad är nightsaber fang","nightsaber fang i berättelsen","om nightsaber fangs"}}},fp="15,118,18.331.0,17.310.1,36.115.0,41.98.0,45.138.1,58.112.0"}
P.entries["item:nimboya-s-pike"] = {n="Nimboya's Pike",s="Nimboya’s Pike är ett vapen som Nimboya lånar ut för att föra ett mörkt budskap till Witherbark-trollen i Hinterlands. Deras förräderi mot Thrall har väckt Hordes vrede mot deras byar.",h="Nimboya’s Pike är ett vapen som Nimboya lånar ut för att föra ett mörkt budskap till Witherbark-trollen i...",kw={"mörkt budskap","hinterlands","horde","lastad pike","nimboya","nimboya's pike","pike","thrall","witherbark"},ang={["faction:Horde"]="Piken bär Hordes vrede mot Witherbarks för att de förrådde Thrall, som en gång var deras allierade."},sec={{t="Ett mörkt budskap",b="I Stranglethorn ger Nimboya dig sin pik och skickar dig norrut till Hinterlands. Witherbark-trollen stod en gång på Hordes sida, men de förrådde Thrall. Nimboya vill att de ska få svara för sitt förräderi. Han nämner Hiri’watha och Zun’watha som platser där du kan lämna hans budskap."}},faq={{q="Vem är Nimboya’s Pike avsedd för?",a="Nimboya lånar ut piken så att du kan föra hans budskap till Witherbark-trollen i Hinterlands.",al={"nimboyas pike","vem piken är till för"}},{q="Varför vill Nimboya straffa Witherbarks?",a="Witherbark-trollen var en gång Hordes allierade, men de förrådde Thrall.",al={"varför straffa witherbark","witherbarks förräderi"}},{q="Vart ska jag ta piken?",a="Nimboya skickar dig till Hinterlands, nordost om Tarren Mill, för att lämna budskapet vid Hiri’watha eller Zun’watha.",al={"vart piken ska","pike i hinterlands"}},{q="Vad är Nimboya’s Laden Pike?",a="Det är Nimboya’s Pike med Witherbark-kranier, avsedd att placeras i en av deras byar som ett mörkt budskap.",al={"lastad pike","kraniepike"}}},fp="14,182,14.292.0,28.96.0,48.78.0,29.116.0,31.112.1"}
P.entries["item:nissa-s-remains"] = {n="Nissa's Remains",s="Nissa's Remains är de jordiska kvarlevorna efter Nissa Agamand, en adelskvinna ur den en gång välbärgade Agamanddynastin i norra Tirisfal Glades. Under det tredje kriget dödades hon och gjordes till en viljelös tjänare åt Scourge. Nu jagas hon och hennes familj av tidigare arbetare som söker hämnd.",h="Nissa's Remains är de jordiska kvarlevorna efter Nissa Agamand, en adelskvinna ur den en gång välbärgade...",kw={"agamand mills","brill","coleman farthing","dödsfall i familjen","nissa agamand","nissa's remains","tirisfal glades"},ang={["faction:Horde"]="Om du dödar de återuppväckta Agamandarna och rensar deras kvarnar säkrar du norra Tirisfal Glades från kvarvarande Scourge-styrkor som hotar Brill och Undercity.",["race:Undead"]="För Forsaken innebär återtagandet av Tirisfal att både deras forna förtryckare i Scourge och de rika aristokrater som dömde vanliga arbetare till odödhet genom sin dåraktiga stolthet måste förgöras."},sec={{t="Ett arv av stolthet",b="Före det tredje kriget var familjen Agamand den rikaste och mest inflytelserika dynastin i Tirisfal Glades, med välmående kvarnar i de norra kullarna. När pesten som förde de odöda spred sig över Lordaeron vägrade familjens överhuvuden envist att evakuera. I stället befäste de sina gods och övertalade sina tjänare och arbetare att hålla stånd. Den arrogansen kostade alla livet. Agamandfamiljen föll för Scourge. De återuppstod utan sin stolta självständighet, som stapplande, viljelösa trälar bundna till Lich Kings vilja."},{t="Bitter vedergällning",b="I staden Brill har de överlevande som senare bröt sig fria under drottning Sylvanas Windrunner inte glömt familjens ödesdigra stolthet. Coleman Farthing, en tidigare arbetare vid Agamand Mills, hyser ett bittert agg mot sina forna herrar för att de lockade arbetarna rakt in i odödhetens käftar. Han låter äventyrare göra slut på de återuppståndna Agamandarna och hämta deras fysiska kvarlevor, som Nissa's. För Farthing och andra bland Forsaken ger det en bister känsla av slutgiltighet och hämnd att bränna eller förstöra dessa reliker."}},faq={{q="Vem var Nissa Agamand?",a="Nissa tillhörde familjen Agamand, adelsmän från Lordaeron som ägde det vidsträckta Agamand Mills i Tirisfal Glades. När Scourge svepte genom Lordaeron dog hon tillsammans med sin släkt och återuppväcktes som en odöd tjänare under Lich Kings kontroll.",al={"vem är nissa","nissas historia","nissa agamand"}},{q="Varför vill Coleman Farthing ha Nissas kvarlevor?",a="Coleman Farthing arbetade vid Agamand Mills när han levde. Han hyser ett bittert agg mot familjen eftersom deras arroganta vägran att fly övertalade lojala arbetare att stanna kvar och dö. Genom att samla in deras kvarlevor kan han hämnas på sina forna herrar.",al={"varför vill coleman ha kvarlevorna","varför döda agamandarna","coleman farthings motiv"}},{q="Var samlas kvarlevorna in?",a="Nissa Agamand hemsöker de ödelagda Agamand Mills i norra Tirisfal Glades. Hon vandrar bland de förfallna gårdshusen tillsammans med sina återuppväckta släktingar och viljelösa Scourge-trälar.",al={"var hittar jag nissa","nissa agamands plats"}},{q="Behöll Nissa sin fria vilja, som Forsaken?",a="Nej. Till skillnad från Forsaken som bröt sig loss från Lich King förblev Nissa och hennes familj förslavade av Scourge som viljelösa odöda. De saknade den medvetenhet och frihet som Undercitys invånare har.",al={"är nissa forsaken","hade nissa fri vilja","är nissa scourge"}}},fx={a9aa03e3={q="Vad är Nissa's Remains?",a="Det är de fysiska kvarlevorna efter Nissa Agamand, en medlem av den förmögna Agamanddynastin som en gång ägde kvarnarna i norra Tirisfal Glades. När Scourge drog fram genom Lordaeron befäste familjen sitt gods och övertalade sina arbetare att hålla stånd. Liksom resten av sin släkt föll Nissa för Plague och återuppstod som en viljelös träl i Lich Kings tjänst.",al={"vad är nissa's remains","nissas kvarlevor","vem tillhör nissa's remains"}},["4cb46b58"]={q="Var kommer Nissa's Remains ifrån, och vem skapade dem?",a="De hämtas direkt från den förstörda kroppen efter Nissa Agamand vid Agamand Mills. Hon var en gång en stolt aristokrat, men dukade under för Plague of Undeath och blev kvar på sina förfäders marker som odöd. Kvarlevorna är det du får med dig efter att ha lagt hennes viljelösa Scourge-form till vila.",al={"var får man tag på nissa's remains","hur får man tag på nissa's remains","vem tappade nissa's remains"}}},fp="15,240,17.460.0,18.437.0,22.243.0,47.228.0,33.176.0,49.195.0"}
P.entries["item:nitroglycerin"] = {n="Nitroglycerin",s="Vid Bael Modan hjälper Nitroglycerin dvärgarna att driva sin utgrävning genom taurenmark. Deras soldater och officerare bär på den flyktiga kemikalien, som också kan användas mot fästningen.",h="Vid Bael Modan hjälper Nitroglycerin dvärgarna att driva sin utgrävning genom taurenmark.",kw={"bael modan","bael'dun","barrens","sprängämnen","gann stonespire","nitroglycerin","ganns hämnd"},ang={["profession:Engineering"]="Ingenjörer känner nitroglycerin som ett sammansatt sprängämne. Wood Pulp suger upp det, och Sodium Nitrate hjälper till att göra det stabilt och detonationsdugligt.",["race:Tauren"]="Som tauren känner du till de flyktiga kemikalierna runt Bael Modan som ett bittert tecken på förstörelsen som drabbat Stonespire-stammen."},sec={{t="Industriell sprängning",b="Dvärgarna i Bael Modan gräver sig in i Stonespire-taurernas förfädersmarker med tunga borrmaskiner och flyktiga kemikalier. Vid utgrävningsplatsen och i dess befästa fäste håller de nitroglycerin nära till hands för att spränga djupa hål och bryta sönder kullar. Soldater och officerare, däribland Lord Cyrik Blackforge, bär på flaskor med vätskan medan grävandet fortsätter."},{t="Smaka på sin egen medicin",b="Efter att Prospector Khazgorm dör söker Gann Stonespire förstöra den framryckande fästningen. De fördrivna taurenerna vågar studera dvärgarnas ingenjörsplaner och lär sig att nitroglycerin blandat med Wood Pulp och Sodium Nitrate bildar en laddning som är stark nog att slå mot Bael Modans militära garnison."}},faq={{q="Var kommer nitroglycerin från?",a="Dvärgstyrkorna i Bael Modan i södra Barrens bär på nitroglycerin, däribland Bael'dun Soldiers, Riflemen, Officers och Lord Cyrik Blackforge i fästet.",al={"var hittar man nitroglycerin","vem släpper nitroglycerin","nitroglycerins källa"}},{q="Vad används nitroglycerin till?",a="Gann Stonespire blandar nitroglycerin med Wood Pulp och Sodium Nitrate för att skapa en kraftfull laddning mot den militära fästningen i Bael Modan.",al={"vad används nitroglycerin till","nitroglycerins syfte","ingredienser till ganns hämnd"}},{q="Varför bar dvärgarna på det från början?",a="Prospektörerna och garnisonen i Bael Modan använder sprängämnen, ångmaskiner och flyktiga kemikalier för att blotta marken vid sin arkeologiska utgrävningsplats.",al={"varför har dvärgar nitroglycerin","sprängämnen vid bael modan"}},{q="Vem är Gann Stonespire?",a="Gann Stonespire är en landsförvisad taurenkrigare vars stam förlorade sina förfädersmarker när dvärgarna byggde utgrävningsplatsen och fästet i Bael Modan och drev bort dem genom industriell förstörelse.",al={"vem är gann","gann stonespire"}}},fx={["9ba54f78"]={q="Vad är Nitroglycerin?",a="Nitroglycerin är ett flyktigt kemiskt ämne som bärs av de dvärgstyrkor som befäst sig vid Bael Modan i södra Barrens. Bael'dunexpeditionen förlitar sig på tung ingenjörskonst och sprängämnen för att gräva i taurenfolkets förfädersmarker och bryta upp marken. I flyktiga blandningar är det en viktig beståndsdel vid tillverkning av kraftfulla sprängladdningar.",al={"vad är nitroglycerin","nitroglycerin i berättelsen","vad används nitroglycerin till"}}},fp="13,181,21.348.0,29.333.1,35.166.0,35.138.0,52.142.0,23.199.0"}
P.entries["item:nondescript-letter"] = {n="Nondescript Letter",s="Nondescript Letter är ett förseglat, omärkt brev som anförtros nyvaknade Forsaken när de lämnar Deathknell. Calvin Montague överlämnar det under förevändning att det är ett ärende och ber bäraren följa vägen till Innkeeper Renee på Gallows' End Tavern i Brill.",h="Nondescript Letter är ett förseglat, omärkt brev som anförtros nyvaknade Forsaken när de lämnar Deathknell.",kw={"en skurks affär","brill","calvin montague","deathknell","innkeeper renee","nondescript letter","renee"},ang={["class:Rogue"]="Calvin Montagues skumma kroppshållning och Renees plötsliga humörsvängning bär alla tecken på lågmälda skurkkomplotter och kodad kommunikation i undre världen.",["race:Undead"]="För nyuppståndna Forsaken är brevet ett av de första incitamenten att lämna Deathknells gränser och utforska de större bosättningarna i Tirisfal Glades."},sec={{t="Ett ärende åt en kurir",b="Nyuppståndna Forsaken som vill ta sig bortom Deathknell blir kontaktade av Calvin Montague, en skum skurk som dröjer sig kvar nära byns utkant. Han påstår sig vara utmattad efter strider mot tanklösa zombier och spindeldjur och ber resenärer ta med ett enkelt, omärkt kuvert längs vägen österut till Brill. Brevet är lättvindigt adresserat till en värdshusvärd vid namn Renee och fungerar som en förevändning för att få ut resenärer ur dalen och styra dem mot Gallows' End Tavern, trots att Calvins löften om riklig ersättning låter ihåliga från början."},{t="Misstänkt korrespondens",b="När brevet lämnas över i Brill försöker Innkeeper Renee först spela upp en överdrivet munter charad och hävdar att brevet måste innehålla glada nyheter från hennes helgonlika mor i Deathknell. När hon inser att kuriren genomskådar hennes tafatta skådespel försvinner hennes vänliga min och ersätts av skarp irritation. Hon rycker åt sig brevet, vägrar avslöja vem som egentligen skickade det eller vad det innehåller och kör bryskt iväg bäraren, såvida hen inte tänker betala för ett rum."}},faq={{q="Vad är Nondescript Letter?",a="Det är ett enkelt kuvert som ser alldagligt ut. Calvin Montague ger det till nyblivna Forsaken-äventyrare i Deathknell, med uppdraget att lämna det till Innkeeper Renee i Brill.",al={"nondescript letter","vad är det här brevet","calvins brev"}},{q="Vem skickar brevet och vem tar emot det?",a="Calvin Montague, en skurk stationerad i Deathknell, ger brevet till kurirer. Det är adresserat till Innkeeper Renee på Gallows' End Tavern i Brill.",al={"vem skickade brevet","vem får brevet","brevets avsändare"}},{q="Vad står det egentligen i brevet?",a="Brevets exakta innehåll avslöjas inte för spelaren. När du frågar släpper Innkeeper Renee sin glättiga fasad och säger ilsket att brevets ursprung och innehåll inte angår dig.",al={"vad står det i brevet","brevets innehåll","kan man läsa brevet"}},{q="Varför vill Calvin Montague att det ska levereras?",a="Calvin hävdar att han är alltför upptagen med att slåss mot traktens zombier och spindlar för att själv uträtta ärendet. I praktiken leder leveransen resenärer ut ur Deathknell och visar dem vilka bekvämligheter och viloplatser som finns i Brill.",al={"varför skicka brevet","calvins motiv","varför brill"}}},fp="18,205,18.327.0,25.323.1,31.146.0,42.131.0,34.163.0,43.190.0"}
P.entries["item:nori-s-mug"] = {n="Nori's Mug",s="Nori's Mug är Nori Pridedrifts personliga dryckeskärl, som används för att leverera skållhett mornbrew över Dun Moroghs iskalla snövidder. Efter att ha lämnat en varm dryck för att mota bort den bitande kylan i bergen får resenärer i uppgift att lämna tillbaka den tomma muggen till dess sparsamma ägare.",h="Nori's Mug är Nori Pridedrifts personliga dryckeskärl, som används för att leverera skållhett mornbrew över...",kw={"lämna tillbaka muggen","dun morogh","durnan furcutter","mornbrew","nori pridedrift","nori's mug"},ang={["race:Dwarf"]="För dvärgar som trotsar Dun Moroghs stormar är det självklart att dela en varm dryck, men att låta fint värdshusgods försvinna i en snödriva är ett oförlåtligt slöseri."},sec={{t="En kurirs återkomst",b="I Dun Moroghs iskalla bergspass är en rykande het tankard med mornbrew en av få bekvämligheter som kan stå emot den bitande kylan. Nori Pridedrift anförtror sin mugg åt resenärer som ska leverera en nyupphälld, ångande dryck till Durnan Furcutter i Anvilmar. När den är urdrucken måste det tåliga kärlet färdas hela vägen tillbaka. Som Nori påpekar växer muggar inte på träd, och att hålla reda på slitstarkt dvärgkärl är viktigt när gästfrihet möter snöig vildmark."}},faq={{q="Vad används Nori's Mug till?",a="Den används för att leverera rykande hett, skållhett mornbrew till Durnan Furcutter i Anvilmar. När Durnan har druckit sig varm måste den tomma muggen bäras tillbaka till Nori Pridedrift.",al={"vad nori's mug används till","vad som fanns i muggen","noris mugg"}},{q="Vem äger muggen?",a="Muggen tillhör Nori Pridedrift, en dvärg som är stationerad i Dun Morogh och värdesätter sina ägodelar. Han insisterar på att kurirer lämnar tillbaka hans dryckeskärl i stället för att låta dem ligga utspridda i snön.",al={"vem nori är","muggens ägare","vems mugg det är"}},{q="Varför insisterar Nori på att få tillbaka muggen?",a="Bra lergods och tåliga tankards är praktiska förnödenheter i det hårda bergsklimatet. Som Nori krasst påpekar växer muggar inte på träd, så det är både en hederssak och praktiskt att se till att varje lånad mugg återlämnas till honom.",al={"varför muggen ska lämnas tillbaka","varför nori vill ha tillbaka den","muggar växer inte på träd"}},{q="Vad drack man ur muggen?",a="Den innehöll skållhett mornbrew, en mustig varm dryck som dvärgar i Dun Morogh uppskattar för att hålla kylan borta och värma själen.",al={"vad som fanns i koppen","vad mornbrew är","drycken mornbrew"}}},fp="10,154,18.339.0,28.137.0,18.103.0,45.128.0,28.88.0"}
P.entries["item:notched-rib"] = {n="Notched Rib",s="Notched Rib är en bentrofé som samlas in från de horder av viljelösa odöda som strövar omkring i Tirisfal Glades. Deathguard Dillinger i Brill samlar dessa ärrade kvarlevor som bevis på försöken att bryta Scourges grepp om Agamand Mills.",h="Notched Rib är en bentrofé som samlas in från de horder av viljelösa odöda som strövar omkring i Tirisfal...",kw={"agamand mills","brill","cracked skull soldier","deathguard dillinger","notched rib","rattlecage soldier","scourge","tirisfal glades"},ang={["race:Undead"]="För Forsaken är insamlingen av dessa krossade ben en del av ett pågående överlevnadskrig mot Lich Kings viljelösa undersåtar, som vill tvinga dem tillbaka i träldom."},sec={{t="Dyster stridsbevisning",b="Scourges styrkor som samlas på de norra fälten i Tirisfal Glades består av återupplivade skelett klädda i förstörd rustning. Cracked Skull Soldiers och Rattlecage Soldiers kastar sig mot varje levande eller viljestark varelse de möter. När deras sköra kroppar skärs sönder blir benen fulla av gropar och märken. För att se till att Forsakens spejare och frivilliga verkligen rensar bort dessa viljelösa inkräktare i stället för att bara iaktta dem kräver Deathguards konkreta bevis. Ett skårat revben märkt av strid är ett otvetydigt bevis på att ännu en av Lich Kings trälar har krossats."},{t="Säkra kvarnarna",b="Agamand Mills är en avgörande strategisk position nordväst om Brill. Om Scourge får befästa sig bland de förstörda gårdarna och väderkvarnarna får de en direkt bas för att inleda anfall djupt in i Tirisfal. Deathguard Dillinger håller uppsikt över vägarna norrut och skickar ut mästare för att krossa skelettstyrkorna innan de hinner samlas. Högar av skårade revben som återförs till Brill visar att Forsakens försvarslinjer håller och långsamt nöter ned Scourges förtrupp, ben för ben."}},faq={{q="Vad är Notched Rib?",a="Det är ett ärrat skelettben från de animerade Scourge-soldaterna som ockuperar norra Tirisfal Glades. Det lämnas till Deathguard Dillinger som ett fysiskt bevis på att fiender har förgjorts.",al={"notched rib","vad är notched rib","föremålet notched rib"}},{q="Var kommer Notched Ribs ifrån?",a="De tas från Cracked Skull Soldiers och Rattlecage Soldiers som patrullerar området kring Agamand Mills, nordväst om Brill.",al={"var hittar man notched rib","vem släpper notched ribs","källa till notched rib"}},{q="Vem vill ha benen?",a="Deathguard Dillinger, som är stationerad längs vägen strax utanför Brill, samlar in dem tillsammans med Blackened Skulls för att bekräfta att Scourges framryckning har slagits tillbaka.",al={"vem tar emot notched ribs","lämna in notched rib","vem behöver notched rib"}},{q="Varför samlas Scourge vid Agamand Mills?",a="De viljelösa odöda försöker upprätta en bas vid kvarnarna. Därifrån kan Scourges styrkor enkelt inleda anfall över Tirisfal Glades och hota Forsakens bosättningar.",al={"scourge vid agamand mills","varför är skeletten vid kvarnarna","hotet från scourge vid agamand mills"}}},fp="11,75,20.419.0,18.431.0,22.173.0,32.119.0,22.147.0,46.156.0"}
P.entries["item:nugget-slug"] = {n="Nugget Slug",s="Nugget Slugs är specialiserade mekaniska fästelement i 17,5-gauge som används inom industriell teknik. Venture Company lagrar dem i verktygshinkar vid The Sludge Fen, och de är eftertraktade av mekare som försöker reparera instabila maskiner.",h="Nugget Slugs är specialiserade mekaniska fästelement i 17,5-gauge som används inom industriell teknik.",kw={"the barrens","nugget slug","samophlange","the sludge fen","verktygshink","venture company","wenikee boltbucket"},ang={["profession:Engineering"]="Alla ingenjörer vet att en blandning av proprietära fästelement i 17,5 gauge och en instabil, goblinbyggd samophlange snabbt kan leda till en explosiv demontering."},sec={{t="Industriella fästelement från The Sludge Fen",b="Nugget Slugs är kraftiga metallfästelement som tillverkas för krävande industriella konstruktioner. De är särskilt dimensionerade till 17,5 gauge och är en viktig del av den tunga utrustning som används vid Venture Companys utvinningsplatser. Som vanliga handelsvaror är de värdelösa, men oumbärliga för mekare som arbetar med specialanpassad goblinteknik."},{t="Mekande med samophlangen",b="Wenikee Boltbucket behöver en stor mängd nugget slugs för att rusta upp en instabil samophlange som bärgats från The Barrens. Eftersom Venture Company regelbundet lämnar verktygshinkar utspridda vid sina borrplatser i The Sludge Fen, lönar sig bärgningen för skattsökare, även om Wenikees reparationer till slut leder till ett plötsligt, explosivt haveri."}},faq={{q="Vad är nugget slugs?",a="En nugget slug är ett specialiserat metallfästelement eller en metallplugg i 17,5 gauge, avsett för tunga maskiner. De fungerar som konstruktionsdetaljer inuti komplexa industrimaskiner, till exempel oljeborrar och samophlanger.",al={"vad är nugget slugs","nugget slug-lore","fästelementet slug"}},{q="Var hittar man nugget slugs?",a="De förvaras i verktygshinkar som ligger utspridda runt The Sludge Fen, ett borrarläger tillhörande Venture Company i nordöstra The Barrens.",al={"var hittar jag nugget slugs","nugget slug-plats","verktygshinkar i the sludge fen"}},{q="Varför behöver Wenikee Boltbucket dem?",a="Wenikee Boltbucket vill meka med och reparera en bärgad samophlange. Hon har själv fått slut på fästelement i 17,5 gauge och skickar därför äventyrare till det närbelägna Venture Company-lägret för att bärga fler.",al={"vem behöver nugget slugs","varför wenikee vill ha slugs","reparation av samophlange"}},{q="Lagade nugget slugs samophlangen?",a="Inte särskilt bra. När Wenikee monterar de bärgade pluggarna i maskinen och börjar underhålla den exploderar samophlangen plötsligt framför henne.",al={"fungerar maskinen","samophlange-explosion","resultat av wenikees reparation"}}},fx={f3aea894={q="Var kommer Nugget Slug ifrån, och vem tillverkar den?",a="Dessa kulor av kaliber sjutton komma fem är industriell utrustning som Venture Company använder vid Sludge Fen. Arbetarna och ingenjörerna håller dem i lager i verktygshinkar som står utspridda vid deras borrnings- och grävningsplatser i östra Barrens.",al={"var kommer nugget slug ifrån","vem tillverkar nugget slug","nugget slugs ursprung"}}},fp="11,185,38.263.0,30.327.1,22.174.0,29.131.0,38.228.0,48.115.1"}
P.entries["item:oathstone-of-ysera-s-dragonflight"] = {n="Oathstone of Ysera's Dragonflight",s="Oathstone of Ysera's Dragonflight bär Itharius ord om Eranikus. Den ställer dig inför ett val i Swamp of Sorrows.",h="Oathstone of Ysera's Dragonflight bär Itharius ord om Eranikus.",kw={"chained essence","drakflykt","eranikus","itharius","oathstone","återlösning","swamp of sorrows","ysera"},sec={{t="Ett uppdrag",b="I Swamp of Sorrows ger Itharius dig Oathstone efter att ha talat med dig om Eranikus. När du aktiverar stenen når hans röst ditt sinne. Han ber dig att ta på dig ett uppdrag i Ysera's Dragonflight tjänst."},{t="Valet",b="Itharius uppdrag går ut på att hjälpa till att återlösa Eranikus fördärvade själ. För att börja måste du avstå från Chained Essence of Eranikus, som innehåller det som återstår av Eranikus fria vilja. Itharius kallar detta det första av många offer. Det är ditt val om du vill hjälpa Ysera's Dragonflight."}},faq={{q="Vad gör Oathstone?",a="När du aktiverar Oathstone talar Itharius till ditt sinne och ber dig hjälpa Ysera's Dragonflight att återlösa Eranikus.",al={"vad används oathstone till","oathstones syfte"}},{q="Vem ger dig Oathstone?",a="Itharius ger dig Oathstone efter att ha talat med dig om Eranikus i Swamp of Sorrows.",al={"vem ger oathstone","itharius sten"}},{q="Vilket val erbjuder stenen?",a="Oathstone ber dig välja om du vill hjälpa Ysera's Dragonflight att återlösa Eranikus.",al={"oathstones val","hjälpa ysera eller inte"}},{q="Vad måste du ge upp?",a="Itharius ber dig avstå från Chained Essence of Eranikus, som håller fast det som återstår av Eranikus fria vilja.",al={"vilket offer","chained essence"}}},fp="33,128,14.215.0,10.280.1,27.123.1,28.96.0,33.91.1,22.115.1"}
P.entries["item:ogre-s-monocle"] = {n="Ogre's Monocle",s="Ogre's Monocle är en överdimensionerad lornjett som bärs av Zzarc'Vul, en ogre som bor i Vul'Gol Ogre Mound i södra Duskwood. Den enorma glaslinsen har exakt de mått som Viktori Prism'Antras i Darkshire behöver för att bygga ett avancerat stjärnkikarteleskop.",h="Ogre's Monocle är en överdimensionerad lornjett som bärs av Zzarc'Vul, en ogre som bor i Vul'Gol Ogre Mound i...",kw={"cog","darkshire","blicka mot stjärnorna","ogre's monocle","teleskop","viktori prism'antras","vul'gol ogre mound","zzarc'vul"},ang={["faction:Alliance"]="När du hämtar linsen från ogres i Vul'Gol försvinner en farlig best från de södra skogarna, samtidigt som Darkshires hårt prövade invånare får finna tröst i stjärnorna.",["profession:Engineering"]="Ritningen från Cog visar typisk gnomisk ambition: att använda delar utanför standardmåtten, som jättestora glasögon, när precisionsslipade linser inte finns tillgängliga ute i fält."},sec={{t="En märklig lins",b="Ogres är sällan kända för sina förfinade studier, men Zzarc'Vul har på något vis fått tag på en enorm lornjett anpassad till hans väldiga kroppsbyggnad. När Viktori Prism'Antras, som bor i Darkshire, började bygga ett stjärnskådningsinstrument efter ritningar från gnomingenjören Cog, upptäckte han att vanliga linser var alldeles för små. Zzarc'Vuls glasögon visade sig vara den enda biten slipat glas i trakten med den välvning och storlek som krävdes för att fokusera ljuset genom den färdiga apparaten."},{t="Rov från Vul'Gol",b="För att få tag på lornjetten måste du våga dig in i Vul'Gol Ogre Mound, i skuggan av södra Duskwood. Zzarc'Vul håller till bland sina brutala fränder och verkar föga benägen att frivilligt skiljas från sitt utmärkande tillbehör. För att ta linsen måste du besegra besten på hans eget territorium och sedan föra glaset tillbaka till Darkshire, så att Viktori äntligen kan rikta blicken mot natthimlen."}},faq={{q="Vem bär på Ogre's Monocle?",a="Lornjetten innehas av Zzarc'Vul, en anmärkningsvärd ogre som strövar omkring i Vul'Gol Ogre Mound i södra Duskwood.",al={"vem släpper lornjetten","vem har ogrelornjetten","zzarc'vuls föremål"}},{q="Varför behöver Viktori Prism'Antras ett ogreögonstycke?",a="Viktori bygger ett teleskop utifrån ritningar som gnomingenjören Cog har gjort. Apparaten kräver en ovanligt stor optisk lins, och Zzarc'Vuls väldiga lornjett är den enda glasbit i Duskwood som uppfyller måtten.",al={"varför behövs lornjetten","vad används lornjetten till","teleskoplins"}},{q="Hur fick en ogre tag på en jättelornjett?",a="Källan förklarar inte hur Zzarc'Vul fick tag på lornjetten. Den slår bara fast att han har en som är stor nog för Viktoris teleskop.",al={"varför har en ogre en lornjett","lore om ogres läsglasögon"}},{q="Var ligger Vul'Gol Ogre Mound?",a="Vul'Gol Ogre Mound ligger i kullarna i södra Duskwood, söder om huvudvägen mellan Darkshire och den västra gränsen.",al={"var ligger vulgol","ogreborgen i duskwood"}}},fx={["94fbe42d"]={q="Vad är Ogre's Monocle?",a="Ogre's Monocle är en överdimensionerad optisk lins som Zzarc'Vul bär som ett ögonskydd. Han är en framstående ogre som bor i Vul'Gol Ogre Mound i södra Duskwood. Sådan fin optisk utrustning är ytterst sällsynt bland ogres, men den massiva glaslinsen passar särskilt bra i stora optiska maskiner.",al={"vad är ogre's monocle","föremålet ogre's monocle","ogreögonskydd"}}},fp="14,186,14.351.0,22.286.0,31.87.0,54.175.0,36.131.0,40.127.0"}
P.entries["item:okra"] = {n="Okra",s="I Westfall odlas okra i odlingslotterna på Saldean's Farm. Nybyggarna värdesätter grödan, som gör deras grytor matigare.",h="I Westfall odlas okra i odlingslotterna på Saldean's Farm.",kw={"gröda","gård","okra","saldean","salma saldean","grönsak","westfall-gryta"},ang={["faction:Alliance"]="Stormwinds adelsmän äter importerat kött, medan Alliansens nybyggare i gränslandet odlar tåliga grödor som okra bland ruinerna i Westfall.",["profession:Cooking"]="En kringvandrande kock vet att en god gryta behöver mer än rått kött. Okra ger vildmarkens sega föda stärkelse och fyllighet, så att den blir en varm måltid."},sec={{t="En basgröda på Saldean's Farm",b="Saldean's Farm ger fortfarande grönsaker, medan stora delar av Westfall ligger i träda och hotas av Defias-banditer och skenande skördegolemer. Okra växer i de uppodlade lotterna runt gården. Grödan håller ut under de hårda förhållandena och ger näring åt traktens nybyggare när handeln och försörjningen från Stormwind sinar."},{t="Westfall-gryta",b="Salma Saldeans berömda Westfall-gryta kräver okra. Hon blandar skivade frökapslar med det kött nybyggarna kan jaga på de dammiga slätterna, däribland gamkött, goretusktryne och kustmurlocögon. Frökapslarna mjuknar i värmen och gör en tunn buljong mustig och mättande. För nybyggare som klamrar sig fast vid sina gårdar gör färsk okra magert skaffande till en varm kvällsmåltid."}},faq={{q="Var växer okra i Westfall?",a="Okra växer i de uppodlade lotterna vid Saldean's Farm längs Westfalls mittväg. De gröna plantorna trivs i fårorna nära Farmer Saldeans gård.",al={"okra plats","var hittar man okra","var växer okra"}},{q="Vad används okra till?",a="Salma Saldean skördar okra på Saldean's Farm till sin specialitet, Westfall-grytan. Dess naturliga stärkelse gör buljongen tjockare och blandar samman gamkött, vildsvinstryne och murlocögon till en mustig måltid.",al={"användning av okra","vad används okra till","varför behöver jag okra"}},{q="Varför är okra viktig för familjen Saldean?",a="När handeln störs och kungariket ger föga hjälp får nybyggarna förlita sig på det de kan odla och jaga. Okra är en av få odlade grödor som finns kvar på Saldean's Farm och hjälper till att mätta familjen och förbipasserande resenärer.",al={"saldeans okra","varför okra är viktig"}}},fx={["301f0b5e"]={q="Vad är okra?",a="Okra är en ätlig grönsak som växer i den uppodlade jorden i Westfall. Den odlas på gårdar som Saldean Farm, och baljorna klarar regionens hårda klimat och ger de kämpande nybyggarna en pålitlig basgröda.",al={"vad är okra","okra som föremål","okraplanta"}},["5bbd3a8c"]={q="Var kommer okra ifrån?",a="Okra odlas på gårdarna i Westfall, framför allt av Salma och Farmer Saldean på Saldean Farm. Även om stora delar av landsbygden har förfallit och lämnats åt sitt öde fortsätter tåliga grödor som okra att växa på de åkrar som ännu brukas.",al={"var kommer okra ifrån","vem odlar okra","okras ursprung"}},b45f6830={q="Varför vill Salma Saldean ha okra?",a="Salma Saldean behöver färsk okra som en viktig ingrediens i sin berömda Westfall Stew. När grönsaken skivas och får sjuda tillsammans med vilt och lokalt kött hjälper den till att reda den smakrika buljongen och ger en mustig, mättande måltid som håller slättens folk vid liv.",al={"varför vill någon ha okra","varför vill salma ha okra","vem vill ha okra"}}},fp="4,136,26.306.0,13.393.0,33.147.0,22.188.0,38.219.0"}
